/**
 * API Client for SAK ERP System
 * Handles all HTTP requests to the backend API
 */

const DEFAULT_BROWSER_API_BASE_URL = '/api/v1';
const DEFAULT_SERVER_API_BASE_URL =
  process.env.INTERNAL_API_URL || 'http://localhost:4000/api/v1';

function normalizeBaseUrl(value: string): string {
  // Trim whitespace and remove a trailing slash to avoid double slashes when joining.
  const trimmed = value.trim();
  return trimmed.endsWith('/') ? trimmed.slice(0, -1) : trimmed;
}

function getApiBaseUrl(): string {
  const raw = process.env.NEXT_PUBLIC_API_URL;
  if (raw && raw.trim().length > 0) {
    return normalizeBaseUrl(raw);
  }

  if (typeof window !== 'undefined') {
    // Use a relative URL so the Next.js server can proxy via rewrites.
    return DEFAULT_BROWSER_API_BASE_URL;
  }

  return normalizeBaseUrl(DEFAULT_SERVER_API_BASE_URL);
}

interface ApiResponse<T = any> {
  success: boolean;
  data?: T;
  error?: string;
  message?: string;
}

interface RegisterData {
  name: string;
  email: string;
  password: string;
  companyName: string;
}

interface LoginData {
  email: string;
  password: string;
  tenantId?: string;
}

interface LoginResponse {
  accessToken: string;
  refreshToken: string;
  user: {
    id: string;
    email: string;
    firstName?: string;
    lastName?: string;
    tenantId?: string;
    isActive?: boolean;
    role?: {
      id: string;
      name: string;
      permissions?: any[];
    };
    roles?: Array<{
      role: {
        id: string;
        name: string;
        permissions?: any[];
      };
    }>;
  };
}

interface ResetPasswordRequestData {
  email: string;
}

class ApiClient {
  private baseUrl: string;

  constructor(baseUrl?: string) {
    this.baseUrl = normalizeBaseUrl(baseUrl ?? getApiBaseUrl());
  }

  /**
   * Make an HTTP request to the API
   */
  private async request<T>(
    endpoint: string,
    options: RequestInit = {}
  ): Promise<ApiResponse<T>> {
    try {
      const url = `${this.baseUrl}${endpoint}`;

      const isFormData =
        typeof FormData !== 'undefined' && options.body instanceof FormData;

      const headers: Record<string, string> = {};

      if (!isFormData) {
        headers['Content-Type'] = 'application/json';
      }

      // Merge existing headers
      if (options.headers) {
        const existingHeaders = options.headers as Record<string, string>;
        Object.assign(headers, existingHeaders);
      }

      const applyAuthHeader = (token: string | null) => {
        if (token) {
          headers['Authorization'] = `Bearer ${token}`;
        } else {
          delete headers['Authorization'];
        }
      };

      // Add auth token if available
      applyAuthHeader(this.getToken());

      const execute = async () => {
        const response = await fetch(url, {
          ...options,
          headers,
        });

        // Some endpoints return 204/empty body; guard JSON parsing
        const text = await response.text();
        let data: any = null;
        try {
          data = text ? JSON.parse(text) : null;
        } catch {
          data = text || null;
        }

        return { response, data };
      };

      let { response, data } = await execute();

      // If access token expired, attempt a single refresh + retry.
      const isAuthEndpoint = endpoint.startsWith('/auth/');
      if (
        response.status === 401 &&
        !isAuthEndpoint &&
        typeof window !== 'undefined'
      ) {
        const refreshToken = localStorage.getItem('refreshToken');
        if (refreshToken) {
          try {
            const refreshResponse = await fetch(`${this.baseUrl}/auth/refresh`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ refreshToken }),
            });

            const refreshText = await refreshResponse.text();
            const refreshData = refreshText ? JSON.parse(refreshText) : null;

            if (refreshResponse.ok) {
              const authData = (refreshData as any)?.data ?? refreshData;
              const nextAccessToken = authData?.accessToken;
              const nextRefreshToken = authData?.refreshToken;
              if (nextAccessToken && nextRefreshToken) {
                this.saveTokens(nextAccessToken, nextRefreshToken);
                applyAuthHeader(nextAccessToken);
                ({ response, data } = await execute());
              }
            }
          } catch {
            // Ignore refresh errors; fall through to normal error handling.
          }
        }
      }

      if (!response.ok) {
        return {
          success: false,
          error: (data as any)?.message || `HTTP ${response.status}: ${response.statusText}`,
        };
      }

      return {
        success: true,
        data,
      };
    } catch (error: any) {
      console.error('API request failed:', error);
      return {
        success: false,
        error: error.message || 'Network error occurred',
      };
    }
  }

  /**
   * Get JWT token from localStorage
   */
  private getToken(): string | null {
    if (typeof window === 'undefined') return null;
    return localStorage.getItem('accessToken');
  }

  /**
   * Save JWT tokens to localStorage
   */
  private saveTokens(accessToken: string, refreshToken: string): void {
    if (typeof window === 'undefined') return;
    localStorage.setItem('accessToken', accessToken);
    localStorage.setItem('refreshToken', refreshToken);
  }

  /**
   * Remove tokens from localStorage
   */
  private clearTokens(): void {
    if (typeof window === 'undefined') return;
    localStorage.removeItem('accessToken');
    localStorage.removeItem('refreshToken');
    // Clear any cached user data to prevent tenant data leakage
    localStorage.removeItem('user');
    localStorage.removeItem('userId');
    localStorage.removeItem('tenant');
    localStorage.removeItem('tenantId');
  }

  /**
   * Register a new user and create company
   */
  async register(data: RegisterData): Promise<ApiResponse<any>> {
    const response = await this.request('/auth/register', {
      method: 'POST',
      body: JSON.stringify(data),
    });

    if (response.success && response.data) {
      // Auto-login after registration
      const authData = response.data as any;
      if (authData.accessToken && authData.refreshToken) {
        this.saveTokens(authData.accessToken, authData.refreshToken);
      }
    }

    return response;
  }

  /**
   * Login user
   */
  async login(data: LoginData): Promise<ApiResponse<LoginResponse>> {
    // Clear any existing session data before login to prevent tenant mixing
    this.clearTokens();
    
    const response = await this.request<LoginResponse>('/auth/login', {
      method: 'POST',
      body: JSON.stringify(data),
    });

    if (response.success && response.data) {
      this.saveTokens(response.data.accessToken, response.data.refreshToken);

      // Persist user for role-based UI and employee self-service mapping
      if (typeof window !== 'undefined') {
        try {
          localStorage.setItem('user', JSON.stringify(response.data.user));
          localStorage.setItem('userId', response.data.user.id);
        } catch {
          // ignore storage errors
        }
      }
    }

    return response;
  }

  /**
   * Logout user
   */
  async logout(): Promise<ApiResponse> {
    const response = await this.request('/auth/logout', {
      method: 'POST',
    });

    this.clearTokens();
    return response;
  }

  /**
   * Request password reset
   */
  async requestPasswordReset(data: ResetPasswordRequestData): Promise<ApiResponse> {
    return this.request('/auth/reset-password-request', {
      method: 'POST',
      body: JSON.stringify(data),
    });
  }

  /**
   * Change password (authenticated user)
   */
  async changePassword(oldPassword: string, newPassword: string): Promise<ApiResponse> {
    return this.request('/auth/change-password', {
      method: 'POST',
      body: JSON.stringify({ oldPassword, newPassword }),
    });
  }

  /**
   * Refresh access token
   */
  async refreshToken(): Promise<ApiResponse> {
    if (typeof window === 'undefined') {
      return { success: false, error: 'Cannot refresh token on server side' };
    }

    const refreshToken = localStorage.getItem('refreshToken');
    if (!refreshToken) {
      return { success: false, error: 'No refresh token available' };
    }

    const response = await this.request('/auth/refresh', {
      method: 'POST',
      body: JSON.stringify({ refreshToken }),
    });

    if (response.success && response.data) {
      const authData = response.data as any;
      this.saveTokens(authData.accessToken, authData.refreshToken);
    }

    return response;
  }

  /**
   * Check if user is authenticated
   */
  isAuthenticated(): boolean {
    return !!this.getToken();
  }

  /**
   * Generic GET request
   */
  async get<T = any>(endpoint: string, params?: Record<string, any>): Promise<T> {
    let url = endpoint;
    if (params) {
      const queryString = new URLSearchParams(
        Object.entries(params).reduce((acc, [key, value]) => {
          if (value !== undefined && value !== null) {
            acc[key] = String(value);
          }
          return acc;
        }, {} as Record<string, string>)
      ).toString();
      if (queryString) {
        url = `${endpoint}?${queryString}`;
      }
    }
    const response = await this.request<T>(url, { method: 'GET' });
    if (!response.success) {
      throw new Error(response.error || 'Request failed');
    }
    return response.data as T;
  }

  /**
   * Generic POST request
   */
  async post<T = any>(endpoint: string, data?: any): Promise<T> {
    const response = await this.request<T>(endpoint, {
      method: 'POST',
      body: data ? JSON.stringify(data) : undefined,
    });
    if (!response.success) {
      throw new Error(response.error || 'Request failed');
    }
    return response.data as T;
  }

  /**
   * Generic multipart/form-data POST request
   */
  async postForm<T = any>(endpoint: string, formData: FormData): Promise<T> {
    const response = await this.request<T>(endpoint, {
      method: 'POST',
      body: formData,
    });
    if (!response.success) {
      throw new Error(response.error || 'Request failed');
    }
    return response.data as T;
  }

  /**
   * Generic PUT request
   */
  async put<T = any>(endpoint: string, data?: any): Promise<T> {
    const response = await this.request<T>(endpoint, {
      method: 'PUT',
      body: data ? JSON.stringify(data) : undefined,
    });
    if (!response.success) {
      throw new Error(response.error || 'Request failed');
    }
    return response.data as T;
  }

  /**
   * Generic DELETE request
   */
  async delete<T = any>(endpoint: string): Promise<T> {
    const response = await this.request<T>(endpoint, { method: 'DELETE' });
    if (!response.success) {
      throw new Error(response.error || 'Request failed');
    }
    return response.data as T;
  }
}

// Export singleton instance
export const apiClient = new ApiClient();

// Export types
export type { ApiResponse, RegisterData, LoginData, LoginResponse, ResetPasswordRequestData };

'use client';

import { useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { apiClient } from '../../../../../lib/api-client';

export default function ClientUploadPage() {
  const params = useParams();
  const router = useRouter();
  const token = params.token as string;
  
  const [file, setFile] = useState<File | null>(null);
  const [comments, setComments] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!file) {
      setError('Please select a file to upload');
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const formData = new FormData();
      formData.append('file', file);
      if (comments) {
        formData.append('comments', comments);
      }

      await apiClient.postForm(`/client/upload/${token}`, formData);
      setSuccess(true);
    } catch (err: any) {
      setError(err.response?.data?.message || 'Failed to upload file');
    } finally {
      setLoading(false);
    }
  };

  if (success) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center p-4">
        <div className="bg-white rounded-xl shadow-2xl p-8 max-w-md w-full text-center">
          <div className="mb-6">
            <svg
              className="w-16 h-16 text-green-500 mx-auto"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"
              />
            </svg>
          </div>
          <h1 className="text-2xl font-bold text-gray-900 mb-4">
            Upload Successful!
          </h1>
          <p className="text-gray-600 mb-6">
            Your revised document has been uploaded successfully. The document manager will be notified and will review your submission.
          </p>
          <p className="text-sm text-gray-500">
            You can close this window now.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-2xl p-8 max-w-2xl w-full">
        <div className="mb-8 text-center">
          <h1 className="text-3xl font-bold text-gray-900 mb-2">
            Upload Revised Document
          </h1>
          <p className="text-gray-600">
            Please upload your revised document below
          </p>
        </div>

        {error && (
          <div className="mb-6 bg-red-50 border border-red-200 rounded-lg p-4">
            <div className="flex items-center">
              <svg
                className="w-5 h-5 text-red-500 mr-2"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
                />
              </svg>
              <p className="text-red-700 text-sm">{error}</p>
            </div>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Select File
            </label>
            <div className="border-2 border-dashed border-gray-300 rounded-lg p-6 text-center hover:border-indigo-500 transition-colors">
              <input
                type="file"
                id="file-upload"
                className="hidden"
                onChange={(e) => {
                  const selectedFile = e.target.files?.[0];
                  if (selectedFile) {
                    setFile(selectedFile);
                    setError(null);
                  }
                }}
              />
              <label
                htmlFor="file-upload"
                className="cursor-pointer flex flex-col items-center"
              >
                <svg
                  className="w-12 h-12 text-gray-400 mb-3"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"
                  />
                </svg>
                <span className="text-sm text-gray-600">
                  {file ? file.name : 'Click to select file or drag and drop'}
                </span>
                <span className="text-xs text-gray-500 mt-1">
                  PDF, DOC, DOCX, or images (max 100MB)
                </span>
              </label>
            </div>
          </div>

          <div>
            <label
              htmlFor="comments"
              className="block text-sm font-medium text-gray-700 mb-2"
            >
              Comments (optional)
            </label>
            <textarea
              id="comments"
              rows={4}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent"
              placeholder="Add any comments about the changes you made..."
              value={comments}
              onChange={(e) => setComments(e.target.value)}
            />
          </div>

          <button
            type="submit"
            disabled={loading || !file}
            className="w-full bg-indigo-600 text-white py-3 px-4 rounded-lg hover:bg-indigo-700 disabled:bg-gray-400 disabled:cursor-not-allowed transition-colors font-medium"
          >
            {loading ? (
              <span className="flex items-center justify-center">
                <svg
                  className="animate-spin h-5 w-5 mr-2"
                  fill="none"
                  viewBox="0 0 24 24"
                >
                  <circle
                    className="opacity-25"
                    cx="12"
                    cy="12"
                    r="10"
                    stroke="currentColor"
                    strokeWidth="4"
                  />
                  <path
                    className="opacity-75"
                    fill="currentColor"
                    d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                  />
                </svg>
                Uploading...
              </span>
            ) : (
              'Upload Document'
            )}
          </button>
        </form>

        <div className="mt-6 pt-6 border-t border-gray-200">
          <p className="text-xs text-gray-500 text-center">
            This is a secure upload portal. Your file will be reviewed by the document manager.
          </p>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { apiClient } from '../../../../../lib/api-client';

interface VendorPayable {
  vendor_id: string;
  vendor_name: string;
  vendor_code: string;
  total_gross: number;
  total_debit: number;
  total_payable: number;
  grn_count: number;
}

interface GRNPayable {
  id: string;
  grn_number: string;
  grn_date: string;
  receipt_date: string;
  gross_amount: number;
  debit_note_amount: number;
  net_payable_amount: number;
  status: string;
}

export default function AccountsPayablePage() {
  const [vendorPayables, setVendorPayables] = useState<VendorPayable[]>([]);
  const [selectedVendor, setSelectedVendor] = useState<VendorPayable | null>(null);
  const [vendorGRNs, setVendorGRNs] = useState<GRNPayable[]>([]);
  const [loading, setLoading] = useState(true);
  const [showDetailsModal, setShowDetailsModal] = useState(false);
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [selectedGRN, setSelectedGRN] = useState<GRNPayable | null>(null);
  const [sortField, setSortField] = useState<keyof VendorPayable>('vendor_name');
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('asc');
  const [paymentForm, setPaymentForm] = useState({
    amount: '',
    payment_method: 'NEFT',
    payment_reference: '',
    payment_date: new Date().toISOString().split('T')[0],
    payment_notes: '',
  });

  useEffect(() => {
    fetchVendorPayables();
  }, []);

  const fetchVendorPayables = async () => {
    try {
      setLoading(true);
      const data = await apiClient.get<VendorPayable[]>('/purchase/debit-notes/vendor-payables');
      setVendorPayables(data);
    } catch (error) {
      console.error('Failed to fetch payables:', error);
    } finally {
      setLoading(false);
    }
  };

  const viewVendorDetails = async (vendor: VendorPayable) => {
    try {
      // Fetch all GRNs for this vendor
      const allGRNs = await apiClient.get<any[]>('/purchase/grn');
      const vendorGRNs = allGRNs.filter(grn => 
        grn.vendor_id === vendor.vendor_id && 
        grn.status === 'COMPLETED' &&
        (grn.net_payable_amount || 0) > 0
      );
      
      setVendorGRNs(vendorGRNs);
      setSelectedVendor(vendor);
      setShowDetailsModal(true);
    } catch (error) {
      console.error('Failed to fetch vendor GRNs:', error);
    }
  };

  const openPaymentModal = (grn: GRNPayable) => {
    setSelectedGRN(grn);
    setPaymentForm({
      ...paymentForm,
      amount: grn.net_payable_amount.toString(),
    });
    setShowPaymentModal(true);
  };

  const recordPayment = async () => {
    if (!selectedGRN) return;
    
    const amount = parseFloat(paymentForm.amount);
    if (isNaN(amount) || amount <= 0) {
      alert('Please enter a valid payment amount');
      return;
    }

    if (amount > selectedGRN.net_payable_amount) {
      alert('Payment amount cannot exceed net payable amount');
      return;
    }

    try {
      await apiClient.post(`/purchase/debit-notes/grn/${selectedGRN.id}/payment`, {
        amount,
        payment_method: paymentForm.payment_method,
        payment_reference: paymentForm.payment_reference,
        payment_date: paymentForm.payment_date,
        payment_notes: paymentForm.payment_notes,
      });
      
      alert('Payment recorded successfully!');
      setShowPaymentModal(false);
      setShowDetailsModal(false);
      fetchVendorPayables();
      
      // Reset form
      setPaymentForm({
        amount: '',
        payment_method: 'NEFT',
        payment_reference: '',
        payment_date: new Date().toISOString().split('T')[0],
        payment_notes: '',
      });
    } catch (error: any) {
      console.error('Failed to record payment:', error);
      alert(`Failed to record payment: ${error.message || 'Unknown error'}`);
    }
  };

  const handleSort = (field: keyof VendorPayable) => {
    if (sortField === field) {
      setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortDirection('asc');
    }
  };

  const sortedVendorPayables = [...vendorPayables].sort((a, b) => {
    const aValue = a[sortField];
    const bValue = b[sortField];
    
    if (typeof aValue === 'string' && typeof bValue === 'string') {
      return sortDirection === 'asc' 
        ? aValue.localeCompare(bValue)
        : bValue.localeCompare(aValue);
    }
    
    if (typeof aValue === 'number' && typeof bValue === 'number') {
      return sortDirection === 'asc' 
        ? aValue - bValue
        : bValue - aValue;
    }
    
    return 0;
  });

  const SortIcon = ({ field }: { field: keyof VendorPayable }) => {
    if (sortField !== field) {
      return <span className="text-gray-400">⇅</span>;
    }
    return sortDirection === 'asc' ? <span>↑</span> : <span>↓</span>;
  };

  const totalPayables = vendorPayables.reduce((sum, v) => sum + v.total_payable, 0);

  return (
    <div className="min-h-screen bg-gradient-to-br from-green-50 to-blue-50 p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-4xl font-bold text-gray-900 mb-2">💰 Accounts Payable</h1>
          <p className="text-gray-600">Track outstanding payments to vendors</p>
        </div>

        {/* Summary Cards */}
        <div className="grid grid-cols-3 gap-6 mb-8">
          <div className="bg-white rounded-lg shadow-md p-6">
            <div className="text-sm text-gray-600 mb-1">Total Vendors</div>
            <div className="text-3xl font-bold text-gray-900">{vendorPayables.length}</div>
          </div>
          <div className="bg-white rounded-lg shadow-md p-6">
            <div className="text-sm text-gray-600 mb-1">Total Payable</div>
            <div className="text-3xl font-bold text-green-600">
              ₹{totalPayables.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
            </div>
          </div>
          <div className="bg-white rounded-lg shadow-md p-6">
            <div className="text-sm text-gray-600 mb-1">Pending GRNs</div>
            <div className="text-3xl font-bold text-blue-600">
              {vendorPayables.reduce((sum, v) => sum + v.grn_count, 0)}
            </div>
          </div>
        </div>

        {/* Vendor Payables Table */}
        <div className="bg-white rounded-lg shadow-md overflow-hidden">
          {loading ? (
            <div className="p-8 text-center text-gray-500">Loading payables...</div>
          ) : vendorPayables.length === 0 ? (
            <div className="p-12 text-center">
              <div className="text-6xl mb-4">💰</div>
              <h3 className="text-xl font-semibold text-gray-700 mb-2">No Outstanding Payables</h3>
              <p className="text-gray-500">All vendor payments are settled</p>
            </div>
          ) : (
            <table className="w-full">
              <thead className="bg-green-50">
                <tr>
                  <th 
                    className="px-6 py-3 text-left text-xs font-medium text-green-900 uppercase cursor-pointer hover:bg-green-100"
                    onClick={() => handleSort('vendor_name')}
                  >
                    <div className="flex items-center gap-2">
                      Vendor <SortIcon field="vendor_name" />
                    </div>
                  </th>
                  <th 
                    className="px-6 py-3 text-right text-xs font-medium text-green-900 uppercase cursor-pointer hover:bg-green-100"
                    onClick={() => handleSort('total_gross')}
                  >
                    <div className="flex items-center justify-end gap-2">
                      Gross Amount <SortIcon field="total_gross" />
                    </div>
                  </th>
                  <th 
                    className="px-6 py-3 text-right text-xs font-medium text-green-900 uppercase cursor-pointer hover:bg-green-100"
                    onClick={() => handleSort('total_debit')}
                  >
                    <div className="flex items-center justify-end gap-2">
                      Debit Notes <SortIcon field="total_debit" />
                    </div>
                  </th>
                  <th 
                    className="px-6 py-3 text-right text-xs font-medium text-green-900 uppercase cursor-pointer hover:bg-green-100"
                    onClick={() => handleSort('total_payable')}
                  >
                    <div className="flex items-center justify-end gap-2">
                      Net Payable <SortIcon field="total_payable" />
                    </div>
                  </th>
                  <th 
                    className="px-6 py-3 text-center text-xs font-medium text-green-900 uppercase cursor-pointer hover:bg-green-100"
                    onClick={() => handleSort('grn_count')}
                  >
                    <div className="flex items-center justify-center gap-2">
                      GRNs <SortIcon field="grn_count" />
                    </div>
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-green-900 uppercase">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200">
                {sortedVendorPayables.map((vendor) => (
                  <tr key={vendor.vendor_id} className="hover:bg-gray-50">
                    <td className="px-6 py-4">
                      <div className="font-semibold text-gray-900">{vendor.vendor_name}</div>
                      <div className="text-sm text-gray-500">{vendor.vendor_code}</div>
                    </td>
                    <td className="px-6 py-4 text-right text-gray-900">
                      ₹{vendor.total_gross.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                    </td>
                    <td className="px-6 py-4 text-right text-red-600 font-semibold">
                      -₹{vendor.total_debit.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="text-xl font-bold text-green-600">
                        ₹{vendor.total_payable.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                      </div>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <span className="px-3 py-1 bg-blue-100 text-blue-800 rounded-full text-sm font-semibold">
                        {vendor.grn_count}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <button
                        onClick={() => viewVendorDetails(vendor)}
                        className="text-green-600 hover:text-green-800 font-medium"
                      >
                        View Details →
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
              <tfoot className="bg-gray-50">
                <tr>
                  <td className="px-6 py-4 font-bold text-gray-900">Total</td>
                  <td className="px-6 py-4 text-right font-bold text-gray-900">
                    ₹{vendorPayables.reduce((sum, v) => sum + v.total_gross, 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                  </td>
                  <td className="px-6 py-4 text-right font-bold text-red-600">
                    -₹{vendorPayables.reduce((sum, v) => sum + v.total_debit, 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                  </td>
                  <td className="px-6 py-4 text-right font-bold text-green-600 text-xl">
                    ₹{totalPayables.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                  </td>
                  <td colSpan={2}></td>
                </tr>
              </tfoot>
            </table>
          )}
        </div>
      </div>

      {/* Vendor Details Modal */}
      {showDetailsModal && selectedVendor && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg max-w-5xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b border-gray-200 flex justify-between items-center">
              <div>
                <h2 className="text-2xl font-bold text-gray-900">{selectedVendor.vendor_name}</h2>
                <p className="text-sm text-gray-500">{selectedVendor.vendor_code}</p>
              </div>
              <button
                onClick={() => setShowDetailsModal(false)}
                className="text-gray-500 hover:text-gray-700 text-2xl"
              >
                ×
              </button>
            </div>

            <div className="p-6">
              {/* Summary */}
              <div className="grid grid-cols-3 gap-4 mb-6">
                <div className="bg-blue-50 rounded-lg p-4 border border-blue-200">
                  <div className="text-xs text-gray-600 mb-1">Gross Amount</div>
                  <div className="text-xl font-bold text-gray-900">
                    ₹{selectedVendor.total_gross.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                  </div>
                </div>
                <div className="bg-red-50 rounded-lg p-4 border border-red-200">
                  <div className="text-xs text-gray-600 mb-1">Debit Notes</div>
                  <div className="text-xl font-bold text-red-600">
                    -₹{selectedVendor.total_debit.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                  </div>
                </div>
                <div className="bg-green-50 rounded-lg p-4 border border-green-200">
                  <div className="text-xs text-gray-600 mb-1">Net Payable</div>
                  <div className="text-xl font-bold text-green-600">
                    ₹{selectedVendor.total_payable.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                  </div>
                </div>
              </div>

              {/* GRN Breakdown */}
              <h3 className="text-lg font-bold text-gray-900 mb-4">GRN Breakdown</h3>
              <div className="border border-gray-200 rounded-lg overflow-hidden">
                <table className="w-full">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-4 py-3 text-left text-xs font-medium text-gray-700 uppercase">GRN Number</th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-gray-700 uppercase">Date</th>
                      <th className="px-4 py-3 text-right text-xs font-medium text-gray-700 uppercase">Gross</th>
                      <th className="px-4 py-3 text-right text-xs font-medium text-gray-700 uppercase">Debit</th>
                      <th className="px-4 py-3 text-right text-xs font-medium text-gray-700 uppercase">Net Payable</th>
                      <th className="px-4 py-3 text-center text-xs font-medium text-gray-700 uppercase">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-200">
                    {vendorGRNs.map((grn) => (
                      <tr key={grn.id} className="hover:bg-gray-50">
                        <td className="px-4 py-3 text-sm font-semibold text-gray-900">{grn.grn_number}</td>
                        <td className="px-4 py-3 text-sm text-gray-600">
                          {grn.receipt_date ? new Date(grn.receipt_date).toLocaleDateString() : 'N/A'}
                        </td>
                        <td className="px-4 py-3 text-sm text-right text-gray-900">
                          ₹{(grn.gross_amount || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                        </td>
                        <td className="px-4 py-3 text-sm text-right text-red-600">
                          -₹{(grn.debit_note_amount || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                        </td>
                        <td className="px-4 py-3 text-sm text-right font-bold text-green-600">
                          ₹{(grn.net_payable_amount || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                        </td>
                        <td className="px-4 py-3 text-center">
                          <button
                            onClick={() => openPaymentModal(grn)}
                            className="px-4 py-1.5 bg-green-600 text-white text-sm rounded hover:bg-green-700"
                          >
                            💳 Record Payment
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                  <tfoot className="bg-gray-50">
                    <tr>
                      <td colSpan={2} className="px-4 py-3 text-sm font-bold text-gray-900">Total</td>
                      <td className="px-4 py-3 text-sm text-right font-bold text-gray-900">
                        ₹{vendorGRNs.reduce((sum, g) => sum + (g.gross_amount || 0), 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                      </td>
                      <td className="px-4 py-3 text-sm text-right font-bold text-red-600">
                        -₹{vendorGRNs.reduce((sum, g) => sum + (g.debit_note_amount || 0), 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                      </td>
                      <td className="px-4 py-3 text-sm text-right font-bold text-green-600 text-lg">
                        ₹{vendorGRNs.reduce((sum, g) => sum + (g.net_payable_amount || 0), 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                      </td>
                    </tr>
                  </tfoot>
                </table>
              </div>
            </div>

            <div className="p-6 border-t border-gray-200 flex justify-end">
              <button
                onClick={() => setShowDetailsModal(false)}
                className="px-6 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Payment Recording Modal */}
      {showPaymentModal && selectedGRN && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-xl max-w-2xl w-full mx-4">
            <div className="p-6 border-b border-gray-200">
              <h2 className="text-2xl font-bold text-gray-900">Record Payment</h2>
              <p className="text-sm text-gray-600 mt-1">
                GRN: <strong>{selectedGRN.grn_number}</strong> | 
                Net Payable: <strong className="text-green-600">₹{selectedGRN.net_payable_amount.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</strong>
              </p>
            </div>

            <div className="p-6 space-y-4">
              {/* Payment Amount */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Payment Amount <span className="text-red-500">*</span>
                </label>
                <input
                  type="number"
                  step="0.01"
                  value={paymentForm.amount}
                  onChange={(e) => setPaymentForm({ ...paymentForm, amount: e.target.value })}
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500"
                  placeholder="Enter payment amount"
                />
              </div>

              {/* Payment Method */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Payment Method <span className="text-red-500">*</span>
                </label>
                <select
                  value={paymentForm.payment_method}
                  onChange={(e) => setPaymentForm({ ...paymentForm, payment_method: e.target.value })}
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500"
                >
                  <option value="NEFT">NEFT</option>
                  <option value="RTGS">RTGS</option>
                  <option value="UPI">UPI</option>
                  <option value="CHEQUE">Cheque</option>
                  <option value="CASH">Cash</option>
                  <option value="IMPS">IMPS</option>
                  <option value="OTHER">Other</option>
                </select>
              </div>

              {/* Payment Reference */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Payment Reference (Transaction ID / Cheque Number)
                </label>
                <input
                  type="text"
                  value={paymentForm.payment_reference}
                  onChange={(e) => setPaymentForm({ ...paymentForm, payment_reference: e.target.value })}
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500"
                  placeholder="Enter transaction ID or cheque number"
                />
              </div>

              {/* Payment Date */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Payment Date <span className="text-red-500">*</span>
                </label>
                <input
                  type="date"
                  value={paymentForm.payment_date}
                  onChange={(e) => setPaymentForm({ ...paymentForm, payment_date: e.target.value })}
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500"
                />
              </div>

              {/* Payment Notes */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Payment Notes
                </label>
                <textarea
                  value={paymentForm.payment_notes}
                  onChange={(e) => setPaymentForm({ ...paymentForm, payment_notes: e.target.value })}
                  rows={3}
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500"
                  placeholder="Add any additional notes"
                />
              </div>
            </div>

            <div className="p-6 border-t border-gray-200 flex justify-end gap-3">
              <button
                onClick={() => setShowPaymentModal(false)}
                className="px-6 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
              >
                Cancel
              </button>
              <button
                onClick={recordPayment}
                className="px-6 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700"
              >
                💳 Record Payment
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter, useParams } from 'next/navigation';

interface WorkStation {
  id: string;
  station_name: string;
  station_code: string;
  station_type: string;
}

interface RoutingStep {
  id: string;
  sequence_no: number;
  operation_name: string;
  work_station_id: string;
  cycle_time_minutes: number;
  setup_time_minutes: number;
  qc_required: boolean;
  notes: string | null;
  estimated_start_offset_hours: number;
  estimated_duration_hours: number;
  manhours_required: number;
  work_station?: WorkStation;
}

interface BOM {
  id: string;
  item_name: string;
  item_code: string;
}

export default function BOMRoutingPage() {
  const router = useRouter();
  const params = useParams();
  
  // Extract BOM ID from params or URL pathname as fallback
  const getBomId = (): string | null => {
    console.log('Getting BOM ID - params:', params);
    console.log('params.id type:', typeof params?.id);
    console.log('params.id value:', params?.id);
    
    if (!params) {
      console.log('No params object');
      // Fallback: extract from URL pathname
      const pathname = window.location.pathname;
      console.log('Pathname:', pathname);
      const match = pathname.match(/\/bom\/([^\/]+)\/routing/);
      if (match) {
        console.log('Extracted from pathname:', match[1]);
        return match[1];
      }
      return null;
    }
    
    if (typeof params.id === 'string') {
      console.log('Returning string ID:', params.id);
      return params.id;
    }
    
    if (Array.isArray(params.id) && params.id.length > 0) {
      console.log('Returning array ID[0]:', params.id[0]);
      return params.id[0];
    }
    
    console.log('No valid ID found in params');
    return null;
  };
  
  const [bomId, setBomId] = useState<string | null>(null);
  const [bom, setBom] = useState<BOM | null>(null);
  const [routingSteps, setRoutingSteps] = useState<RoutingStep[]>([]);
  const [workStations, setWorkStations] = useState<WorkStation[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    operationName: '',
    workStationId: '',
    estimatedTime: 60,
    description: '',
    startOffsetHours: 0,
    durationHours: 1,
    manhoursRequired: 1,
  });

  // Set bomId when params become available
  useEffect(() => {
    const id = getBomId();
    console.log('useEffect - extracted BOM ID:', id);
    setBomId(id);
  }, [params]);

  useEffect(() => {
    console.log('Data fetch useEffect - bomId:', bomId);
    
    if (!bomId) {
      console.log('No bomId available yet');
      return;
    }
    
    console.log('Fetching data for BOM ID:', bomId);
    fetchBOM();
    fetchRouting();
    fetchWorkStations();
  }, [bomId]);

  const fetchBOM = async () => {
    try {
      const token = localStorage.getItem('accessToken');
      const response = await fetch(`/api/v1/bom/${bomId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (response.ok) {
        const data = await response.json();
        setBom(data);
      }
    } catch (error) {
      console.error('Failed to fetch BOM:', error);
    }
  };

  const fetchRouting = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem('accessToken');
      const response = await fetch(
        `/api/v1/production/routing/bom/${bomId}?withStations=true`,
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );
      if (response.ok) {
        const data = await response.json();
        const stepsArray = Array.isArray(data) ? data : data?.data ? data.data : [];
        setRoutingSteps(stepsArray);
      }
    } catch (error) {
      console.error('Failed to fetch routing:', error);
      setRoutingSteps([]);
    } finally {
      setLoading(false);
    }
  };

  const fetchWorkStations = async () => {
    try {
      const token = localStorage.getItem('accessToken');
      const response = await fetch(
        '/api/v1/production/work-stations?isActive=true',
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );
      if (response.ok) {
        const data = await response.json();
        const stationsArray = Array.isArray(data) ? data : data?.data ? data.data : [];
        setWorkStations(stationsArray);
      }
    } catch (error) {
      console.error('Failed to fetch work stations:', error);
      setWorkStations([]);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!bomId) {
      alert('BOM ID is missing');
      return;
    }
    
    setLoading(true);

    try {
      const token = localStorage.getItem('accessToken');
      
      // Map frontend field names to backend API field names
      const payload = editingId ? {
        work_station_id: formData.workStationId,
        operation_name: formData.operationName,
        cycle_time_minutes: formData.estimatedTime,
        setup_time_minutes: 0,
        qc_required: false,
        notes: null,
        estimated_start_offset_hours: formData.startOffsetHours,
        estimated_duration_hours: formData.durationHours,
        manhours_required: formData.manhoursRequired,
      } : {
        bom_id: bomId,
        work_station_id: formData.workStationId,
        operation_name: formData.operationName,
        cycle_time_minutes: formData.estimatedTime,
        setup_time_minutes: 0,
        qc_required: false,
        notes: null,
        sequence_no: routingSteps.length + 1,
        estimated_start_offset_hours: formData.startOffsetHours,
        estimated_duration_hours: formData.durationHours,
        manhours_required: formData.manhoursRequired,
      };

      console.log('Submitting routing payload:', payload);

      let response;
      if (editingId) {
        response = await fetch(
          `/api/v1/production/routing/${editingId}`,
          {
            method: 'PUT',
            headers: {
              'Content-Type': 'application/json',
              Authorization: `Bearer ${token}`,
            },
            body: JSON.stringify(payload),
          }
        );
      } else {
        response = await fetch('/api/v1/production/routing', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify(payload),
        });
      }

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || `HTTP ${response.status}`);
      }

      alert(editingId ? 'Routing step updated successfully' : 'Routing step added successfully');
      resetForm();
      fetchRouting();
    } catch (error: any) {
      console.error('Save error:', error);
      alert('Failed to save routing step: ' + (error.message || 'Unknown error'));
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (step: RoutingStep) => {
    setFormData({
      operationName: step.operation_name,
      workStationId: step.work_station_id,
      estimatedTime: step.cycle_time_minutes,
      description: '',
      startOffsetHours: step.estimated_start_offset_hours || 0,
      durationHours: step.estimated_duration_hours || 1,
      manhoursRequired: step.manhours_required || 1,
    });
    setEditingId(step.id);
    setShowForm(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this routing step?')) return;

    try {
      const token = localStorage.getItem('accessToken');
      const response = await fetch(`/api/v1/production/routing/${id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!response.ok) throw new Error('Failed to delete');

      alert('Routing step deleted successfully');
      fetchRouting();
    } catch (error) {
      alert('Failed to delete routing step');
    }
  };

  const resetForm = () => {
    setFormData({
      operationName: '',
      workStationId: '',
      estimatedTime: 60,
      description: '',
      startOffsetHours: 0,
      durationHours: 1,
      manhoursRequired: 1,
    });
    setEditingId(null);
    setShowForm(false);
  };

  return (
    <div className="container mx-auto py-6 px-4">
      <div className="mb-6">
        <button
          onClick={() => router.back()}
          className="text-blue-600 hover:text-blue-800 mb-4 flex items-center"
        >
          ← Back to BOM
        </button>
        <h1 className="text-3xl font-bold text-gray-900">
          Routing Configuration: {bom?.item_name || 'Loading...'}
        </h1>
        <p className="text-gray-600 mt-1">
          Define the sequence of operations and work stations for this BOM
        </p>
      </div>

      <div className="flex justify-end mb-6">
        <button
          onClick={() => setShowForm(!showForm)}
          className="bg-blue-600 text-white px-6 py-2 rounded-lg hover:bg-blue-700 font-medium"
        >
          {showForm ? 'Cancel' : '+ Add Routing Step'}
        </button>
      </div>

      {/* Form */}
      {showForm && (
        <div className="bg-white rounded-lg shadow p-6 mb-6">
          <h2 className="text-xl font-semibold mb-4">
            {editingId ? 'Edit Routing Step' : 'Add Routing Step'}
          </h2>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Operation Name <span className="text-red-600">*</span>
              </label>
              <input
                type="text"
                required
                value={formData.operationName}
                onChange={(e) => setFormData({ ...formData, operationName: e.target.value })}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                placeholder="e.g., CNC Machining, Assembly"
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Work Station <span className="text-red-600">*</span>
              </label>
              <select
                required
                value={formData.workStationId}
                onChange={(e) => setFormData({ ...formData, workStationId: e.target.value })}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
              >
                <option value="">Select Work Station</option>
                {workStations.map((station) => (
                  <option key={station.id} value={station.id}>
