                  }
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  placeholder="0"
                />
                <p className="text-xs text-gray-500 mt-1">Hours after previous operation</p>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Duration (hours) <span className="text-red-600">*</span>
                </label>
                <input
                  type="number"
                  required
                  min="0.1"
                  step="0.1"
                  value={formData.durationHours}
                  onChange={(e) =>
                    setFormData({ ...formData, durationHours: parseFloat(e.target.value) })
                  }
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  placeholder="1"
                />
                <p className="text-xs text-gray-500 mt-1">Total operation time</p>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Manhours <span className="text-red-600">*</span>
                </label>
                <input
                  type="number"
                  required
                  min="0.1"
                  step="0.1"
                  value={formData.manhoursRequired}
                  onChange={(e) =>
                    setFormData({ ...formData, manhoursRequired: parseFloat(e.target.value) })
                  }
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  placeholder="1"
                />
                <p className="text-xs text-gray-500 mt-1">Labor hours needed</p>
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Description</label>
              <textarea
                rows={3}
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                placeholder="Operation details and instructions..."
              />
            </div>

            <div className="flex justify-end space-x-4">
              <button
                type="button"
                onClick={resetForm}
                className="px-6 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
              >
                Cancel
              </button>
              <button
                type="submit"
                disabled={loading}
                className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-gray-400"
              >
                {loading ? 'Saving...' : editingId ? 'Update' : 'Add'}
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Routing Steps Table */}
      <div className="bg-white rounded-lg shadow overflow-hidden">
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Seq
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Operation
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Work Station
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Start After
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Duration
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Manhours
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Actions
                </th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {loading ? (
                <tr>
                  <td colSpan={5} className="px-6 py-12 text-center text-gray-500">
                    Loading routing steps...
                  </td>
                </tr>
              ) : routingSteps.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-6 py-12 text-center text-gray-500">
                    No routing steps configured. Click &quot;Add Routing Step&quot; to get started.
                  </td>
                </tr>
              ) : (
                routingSteps.map((step) => (
                  <tr key={step.id} className="hover:bg-gray-50">
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                      {step.sequence_no}
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-900">
                      <div className="font-medium">{step.operation_name}</div>
                      <div className="text-xs text-gray-500">{step.cycle_time_minutes} min cycle time</div>
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-900">
                      {step.work_station?.station_code} - {step.work_station?.station_name}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      {step.estimated_start_offset_hours || 0}h
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      {step.estimated_duration_hours || 1}h
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      {step.manhours_required || 1}h
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium space-x-3">
                      <button
                        onClick={() => handleEdit(step)}
                        className="text-blue-600 hover:text-blue-900"
                      >
                        Edit
                      </button>
                      <button
                        onClick={() => handleDelete(step.id)}
                        className="text-red-600 hover:text-red-900"
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { apiClient } from '../../../../lib/api-client';
import ItemSearch from '../../../components/ItemSearch';
import DrawingManager from '../../../components/DrawingManager';

const fileToDataUrl = (file: File): Promise<string> =>
  new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error('Failed to read file'));
    reader.onload = () => resolve(String(reader.result || ''));
    reader.readAsDataURL(file);
  });

const dataUrlToBlob = (dataUrl: string) => {
  const match = dataUrl.match(/^data:(.+?);base64,(.+)$/);
  if (!match) return null;

  const mimeType = match[1];
  const base64Data = match[2];
  const byteString = atob(base64Data);
  const byteArray = new Uint8Array(byteString.length);
  for (let i = 0; i < byteString.length; i++) {
    byteArray[i] = byteString.charCodeAt(i);
  }

  return new Blob([byteArray], { type: mimeType });
};

const openDrawingUrlInNewTab = (url: string) => {
  try {
    if (!url) return;

    if (url.startsWith('data:')) {
      const blob = dataUrlToBlob(url);
      if (!blob) {
        window.open(url, '_blank', 'noopener,noreferrer');
        return;
      }
      const blobUrl = URL.createObjectURL(blob);
      window.open(blobUrl, '_blank', 'noopener,noreferrer');
      setTimeout(() => URL.revokeObjectURL(blobUrl), 60_000);
      return;
    }

    window.open(url, '_blank', 'noopener,noreferrer');
  } catch (error) {
    console.error('Error opening drawing:', error);
    alert('Failed to open drawing');
  }
};

interface BOM {
  id: string;
  version: number;
  is_active: boolean;
  effective_from?: string;
  effective_to?: string;
  notes?: string;
  item?: {
    id?: string;
    code: string;
    name: string;
    type: string;
  };
  bom_items?: Array<{
    id: string;
    component_type: 'ITEM' | 'BOM';
    quantity: number;
    scrap_percentage: number;
    sequence: number;
    drawing_url?: string;
    notes?: string;
    item?: {
      id?: string;
      code: string;
      name: string;
      uom: string;
    };
    child_bom?: {
      id: string;
      version: number;
      item?: {
        code: string;
        name: string;
        uom?: string;
      };
    };
  }>;
  created_at: string;
}

interface PurchaseTrail {
  uid: string;
  item: {
    code: string;
    name: string;
  };
  supplier: {
    name: string;
    contact_person: string;
  } | null;
  purchase_order: {
    po_number: string;
    order_date: string;
    total_amount: number;
  } | null;
  grn: {
    grn_number: string;
    received_date: string;
    received_quantity: number;
  } | null;
  batch_number: string | null;
  location: string | null;
  lifecycle: Array<{
    stage: string;
    timestamp: string;
    location: string;
    reference: string;
  }>;
}

export default function BOMPage() {
  const router = useRouter();
  const [boms, setBoms] = useState<BOM[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [editingBomId, setEditingBomId] = useState<string | null>(null);
  const [selectedBom, setSelectedBom] = useState<BOM | null>(null);
  const [showPRModal, setShowPRModal] = useState(false);
  const [prBomId, setPrBomId] = useState<string>('');
  const [prQuantity, setPrQuantity] = useState<number>(1);
  const [prStockStatus, setPrStockStatus] = useState<any[]>([]);
  const [showTrailModal, setShowTrailModal] = useState(false);
  const [purchaseTrail, setPurchaseTrail] = useState<PurchaseTrail | null>(null);
  const [loadingTrail, setLoadingTrail] = useState(false);
  const [showDrawingManager, setShowDrawingManager] = useState(false);
  const [selectedItemForDrawing, setSelectedItemForDrawing] = useState<{ id: string; code: string; name: string } | null>(null);
  const [viewMode, setViewMode] = useState<'table' | 'cards'>('table');

  const [formData, setFormData] = useState({
    itemId: '',
    version: 1,
    effectiveFrom: new Date().toISOString().split('T')[0],
    effectiveTo: '',
    notes: '',
    items: [] as Array<{
      componentType: 'ITEM' | 'BOM';
      itemId: string;
      childBomId: string;
      quantity: number;
      scrapPercentage: number;
      sequence: number;
      notes: string;
      drawingUrl: string;
    }>,
  });
  const [availableBOMs, setAvailableBOMs] = useState<BOM[]>([]);

  const isEditMode = Boolean(editingBomId);

  useEffect(() => {
    fetchBOMs();
    if (showModal) {
      fetchAvailableBOMs();
    }
  }, [showModal]);

  useEffect(() => {
    if (!loading) {
      console.log('[BOM] Loaded BOM count:', boms.length);
      boms.forEach((bom) => {
        console.log('[BOM] Summary data', {
          bomId: bom.id,
          itemName: bom.item?.name,
          components: bom.bom_items?.map((item) => ({
            id: item.id,
            type: item.component_type,
            hasItem: Boolean(item.item?.name),
            hasChildBom: Boolean(item.child_bom?.item?.name),
            childBomVersion: item.child_bom?.version,
          })),
        });
      });
    }
  }, [boms, loading]);

  const fetchAvailableBOMs = async () => {
    try {
      const data = await apiClient.get('/bom');
      setAvailableBOMs(Array.isArray(data) ? data : []);
    } catch (error) {
      console.error('Error fetching BOMs:', error);
    }
  };

  const fetchBOMs = async () => {
    try {
      setLoading(true);
      console.log('[BOM] Fetching BOMs...');
      
      const data = await apiClient.get('/bom');
      console.log('[BOM] BOMs loaded:', data?.length || 0, 'First BOM:', data?.[0]);
      
      // Ensure data is an array
      setBoms(Array.isArray(data) ? data : []);
    } catch (error: any) {
      console.error('Error fetching BOMs:', error);
      
      // Handle 401 Unauthorized - redirect to login
      if (error.message?.includes('Unauthorized') || error.message?.includes('401')) {
        console.error('[BOM] Unauthorized - redirecting to login');
        localStorage.removeItem('accessToken');
        localStorage.removeItem('refreshToken');
        localStorage.removeItem('user');
        router.push('/login');
        return;
      }
      
      setBoms([]); // Set empty array on error
    } finally {
      setLoading(false);
    }
  };

  const handleCreateBOM = async () => {
    console.log('[BOM] Create BOM clicked - Form data:', formData);
    
    // Validation
    if (!formData.itemId) {
      alert('Please select an item for the BOM');
      return;
    }
    
    if (formData.items.length === 0) {
      alert('Please add at least one component to the BOM');
      return;
    }
    
    try {
      console.log('[BOM] Sending create request...');
      
      // Clean up empty date fields - send null instead of empty string
      const cleanedData = {
        ...formData,
        effectiveTo: formData.effectiveTo || null,
      };
      
      const result = await apiClient.post('/bom', cleanedData);
      console.log('[BOM] Create successful:', result);
      alert('BOM created successfully!');
      setShowModal(false);
      fetchBOMs();
      resetForm();
    } catch (error) {
      console.error('[BOM] Create error:', error);
      alert(`Error creating BOM: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  };

  const handleUpdateBOM = async () => {
    if (!editingBomId) return;

    // Validation
    if (!formData.itemId) {
      alert('Please select an item for the BOM');
      return;
    }

    if (formData.items.length === 0) {
      alert('Please add at least one component to the BOM');
      return;
    }

    try {
      const cleanedData = {
        ...formData,
        effectiveTo: formData.effectiveTo || null,
      };

      await apiClient.put(`/bom/${editingBomId}`, cleanedData);
      alert('✅ BOM updated successfully!');
      setShowModal(false);
      setEditingBomId(null);
      resetForm();
      await fetchBOMs();
    } catch (error) {
      console.error('[BOM] Update error:', error);
      alert(`Error updating BOM: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  };

  const openEditModal = (bom: BOM) => {
    const toDateOnly = (value?: string) => {
      if (!value) return '';
      const date = new Date(value);
      if (Number.isNaN(date.getTime())) return '';
      return date.toISOString().slice(0, 10);
    };

    // Get the item ID - try item_id first, then item.id
    const itemId = (bom as any).item_id || bom.item?.id || '';
    
    console.log('[BOM Edit] Opening edit modal for BOM:', {
      bomId: bom.id,
      item_id_direct: (bom as any).item_id,
      item_obj_id: bom.item?.id,
      item_code: bom.item?.code,
      finalItemId: itemId
    });

    setSelectedBom(bom);

    setEditingBomId(bom.id);
    setFormData({
      itemId: itemId,
      version: bom.version || 1,
      effectiveFrom: toDateOnly(bom.effective_from) || new Date().toISOString().slice(0, 10),
      effectiveTo: toDateOnly(bom.effective_to),
      notes: bom.notes || '',
      items:
        (bom.bom_items || []).map((bi, index) => {
          // Determine component type from the structure
          const componentType = bi.component_type || (bi.child_bom?.id || (bi as any).child_bom_id ? 'BOM' : 'ITEM');
          
          return {
            componentType: componentType,
            itemId: componentType === 'ITEM' ? (bi.item?.id || (bi as any).item_id || '') : '',
            childBomId: componentType === 'BOM' ? (bi.child_bom?.id || (bi as any).child_bom_id || '') : '',
            quantity: typeof bi.quantity === 'number' ? bi.quantity : Number(bi.quantity) || 0,
            scrapPercentage:
              typeof bi.scrap_percentage === 'number'
                ? bi.scrap_percentage
                : Number(bi.scrap_percentage) || 0,
            sequence: typeof bi.sequence === 'number' ? bi.sequence : Number(bi.sequence) || index + 1,
            notes: bi.notes || '',
            drawingUrl: bi.drawing_url || '',
          };
        }) || [],
    });

    setShowModal(true);
  };

  const handleGeneratePR = async (bomId: string) => {
    console.log('[BOM] Opening PR modal for BOM:', bomId);
    setPrBomId(bomId);
    setPrQuantity(1);
    setShowPRModal(true);
  };

  const handleConfirmGeneratePR = async () => {
    console.log('[BOM] Generating PR - BOM:', prBomId, 'Quantity:', prQuantity);
    
    if (!prQuantity || prQuantity <= 0) {
      alert('Please enter a valid quantity greater than 0');
      return;
    }

    try {
      const data = await apiClient.post(`/bom/${prBomId}/generate-pr`, { 
        quantity: Number(prQuantity) 
      });
      console.log('[BOM] PR response data:', data);
      
      // Store stock status for display
      if (data.stockStatus && data.stockStatus.length > 0) {
        setPrStockStatus(data.stockStatus);
      }
      
      if (data.itemsToOrder && data.itemsToOrder.length > 0) {
        // Show success with stock details - don't close modal yet
        alert(
          `✅ Purchase Requisition ${data.prNumber} generated!\n\n` +
          `Items to order (${data.itemsToOrder.length}):\n${data.itemsToOrder.map((item: any) => 
            `  • ${item.itemCode} - ${item.itemName}: ${item.quantity} units`
          ).join('\n')}\n\n` +
          `Check the detailed stock status below.`
          );
          // Keep modal open to show stock status
        } else {
          alert('✅ All items are in stock! No PR needed.\n\nCheck the detailed stock status below.');
          // Keep modal open to show stock status
        }
    } catch (error) {
      console.error('[BOM] Error generating PR:', error);
      alert('❌ Failed to generate PR. Please try again.');
    }
  };

  const handleDeleteBOM = async (bomId: string) => {
    console.log('[BOM] Delete clicked for BOM:', bomId);
    
    if (!confirm('Are you sure you want to delete this BOM? This action cannot be undone.')) {
      return;
    }

    try {
      await apiClient.delete(`/bom/${bomId}`);
      alert('✅ BOM deleted successfully!');
      setSelectedBom(null);
      fetchBOMs();
    } catch (error) {
      console.error('[BOM] Error deleting:', error);
      alert('❌ Failed to delete BOM.');
    }
  };

  const fetchPurchaseTrail = async (uid: string) => {
    try {
      setLoadingTrail(true);
      const data = await apiClient.get(`/uid/${uid}/purchase-trail`);
      setPurchaseTrail(data);
      setShowTrailModal(true);
    } catch (error) {
      console.error('Error fetching purchase trail:', error);
      alert('Failed to fetch purchase trail');
    } finally {
      setLoadingTrail(false);
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-IN', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const handleAddItem = () => {
    // Validate that all existing rows are complete before adding a new one
    if (formData.items.length > 0) {
      const lastItem = formData.items[formData.items.length - 1];
      
      // Check if the last item is incomplete
      if (lastItem.componentType === 'ITEM' && !lastItem.itemId) {
        alert('Please select an item for the current row before adding a new one');
        return;
      }
      
      if (lastItem.componentType === 'BOM' && !lastItem.childBomId) {
        alert('Please select a BOM/Assembly for the current row before adding a new one');
        return;
      }
      
      if (!lastItem.quantity || lastItem.quantity <= 0) {
        alert('Please enter a valid quantity for the current row before adding a new one');
        return;
      }
    }
    
    setFormData({
      ...formData,
      items: [
        ...formData.items,
        {
          componentType: 'ITEM',
          itemId: '',
          childBomId: '',
          quantity: 1,
          scrapPercentage: 0,
          sequence: formData.items.length + 1,
          notes: '',
          drawingUrl: '',
        },
      ],
    });
  };

  const handleDrawingFileSelect = async (index: number, file?: File | null) => {
    if (!file) return;

    const validTypes = [
      'image/png',
      'image/jpeg',
      'image/jpg',
      'application/pdf',
      'application/msword',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    ];
    if (!validTypes.includes(file.type)) {
      alert('Please upload PNG, JPG, PDF, DOC, or DOCX files only');
      return;
    }

    if (file.size > 10 * 1024 * 1024) {
      alert('File size must be less than 10MB');
      return;
    }

    try {
      const dataUrl = await fileToDataUrl(file);
      handleUpdateItem(index, 'drawingUrl', dataUrl);
    } catch (error) {
      console.error('Error reading drawing file:', error);
      alert('Failed to attach drawing');
    }
  };

  const handleUpdateItem = (index: number, field: string, value: any) => {
    // Check for duplicate items when changing itemId or childBomId
    if (field === 'itemId' && value) {
      const isDuplicate = formData.items.some((item, i) => 
        i !== index && item.componentType === 'ITEM' && item.itemId === value
      );
      if (isDuplicate) {
        alert('This item is already added to the BOM. Please select a different item.');
        return;
      }
    }
    
    if (field === 'childBomId' && value) {
      const isDuplicate = formData.items.some((item, i) => 
        i !== index && item.componentType === 'BOM' && item.childBomId === value
      );
      if (isDuplicate) {
        alert('This BOM/Assembly is already added. Please select a different one.');
        return;
      }
    }
    
    const updatedItems = [...formData.items];
    updatedItems[index] = { ...updatedItems[index], [field]: value };
    setFormData({ ...formData, items: updatedItems });
  };

  const handleRemoveItem = (index: number) => {
    setFormData({
      ...formData,
      items: formData.items.filter((_, i) => i !== index),
    });
  };

  const resetForm = () => {
    setFormData({
      itemId: '',
      version: 1,
      effectiveFrom: new Date().toISOString().split('T')[0],
      effectiveTo: '',
      notes: '',
      items: [],
    });
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-amber-50 to-orange-50 p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="flex justify-between items-center mb-8">
          <div>
            <button
              onClick={() => router.push('/dashboard')}
              className="text-amber-600 hover:text-amber-800 mb-2"
            >
              ← Back to Dashboard
            </button>
            <h1 className="text-4xl font-bold text-amber-900">Bill of Materials (BOM)</h1>
            <p className="text-amber-700">Define product structure and generate purchase requisitions</p>
          </div>
          <div className="flex gap-3">
            <div className="flex rounded-lg overflow-hidden border border-gray-300 bg-white">
              <button
                onClick={() => setViewMode('table')}
                className={`px-4 py-2 text-sm font-medium transition-colors ${
                  viewMode === 'table'
                    ? 'bg-amber-600 text-white'
                    : 'bg-white text-gray-700 hover:bg-gray-50'
                }`}
              >
                📊 Table
              </button>
              <button
                onClick={() => setViewMode('cards')}
                className={`px-4 py-2 text-sm font-medium transition-colors ${
                  viewMode === 'cards'
                    ? 'bg-amber-600 text-white'
                    : 'bg-white text-gray-700 hover:bg-gray-50'
                }`}
              >
                🃏 Cards
              </button>
            </div>
            <button
              onClick={() => {
                setEditingBomId(null);
                resetForm();
                setShowModal(true);
              }}
              className="bg-amber-600 hover:bg-amber-700 text-white px-6 py-3 rounded-lg font-semibold"
            >
              + Create BOM
            </button>
          </div>
        </div>

        {/* Search Bar */}
        <div className="mb-6">
          <div className="relative">
            <input
              type="text"
              placeholder="Search BOMs by item code, item name, or version..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full px-4 py-3 pl-12 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-amber-500"
            />
            <svg
              className="absolute left-4 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
              />
            </svg>
            {searchQuery && (
              <button
                onClick={() => setSearchQuery('')}
                className="absolute right-4 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600"
              >
                ×
              </button>
            )}
          </div>
        </div>

        {/* BOM List - Table or Card View */}
        {viewMode === 'table' ? (
          // TABLE VIEW
          <div className="bg-white rounded-lg shadow overflow-x-auto">
            {loading ? (
              <div className="text-center py-12 text-gray-500">Loading BOMs...</div>
            ) : boms.length === 0 ? (
              <div className="text-center py-12">
                <div className="text-6xl mb-4">📋</div>
                <h3 className="text-xl font-semibold text-gray-700 mb-2">No BOMs Found</h3>
                <p className="text-gray-500">Create your first BOM to define product structure</p>
              </div>
            ) : (() => {
              const filteredBoms = boms.filter((bom) => {
                if (!searchQuery) return true;
                const query = searchQuery.toLowerCase();
                const itemName = bom.item?.name?.toLowerCase() || '';
                const itemCode = bom.item?.code?.toLowerCase() || '';
                const version = String(bom.version);
                return itemName.includes(query) || itemCode.includes(query) || version.includes(query);
              });

              if (filteredBoms.length === 0) {
                return (
                  <div className="text-center py-12">
                    <div className="text-6xl mb-4">🔍</div>
                    <h3 className="text-xl font-semibold text-gray-700 mb-2">No BOMs Match Your Search</h3>
                    <p className="text-gray-500">Try different keywords or clear the search</p>
                  </div>
                );
              }

              return (
                <table className="w-full divide-y divide-gray-200">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Product
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Item Code
                      </th>
                      <th className="px-6 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Version
                      </th>
                      <th className="px-6 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Components
                      </th>
                      <th className="px-6 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Status
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Effective From
                      </th>
                      <th className="px-6 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Actions
                      </th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {filteredBoms.map((bom) => (
                      <tr key={bom.id} className="hover:bg-gray-50">
                        <td className="px-6 py-4 whitespace-nowrap">
                          <div className="text-sm font-medium text-gray-900">{bom.item?.name || 'Unknown Item'}</div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                          <div className="text-sm text-gray-500">{bom.item?.code || 'N/A'}</div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-center">
                          <span className="text-sm font-medium text-gray-900">v{bom.version}</span>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-center">
                          <span className="px-3 py-1 inline-flex text-xs leading-5 font-semibold rounded-full bg-blue-100 text-blue-800">
                            {bom.bom_items?.length || 0} {(bom.bom_items?.length || 0) === 1 ? 'part' : 'parts'}
                          </span>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-center">
                          <span
                            className={`px-2 py-1 inline-flex text-xs leading-5 font-semibold rounded-full ${
                              bom.is_active ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'
                            }`}
                          >
                            {bom.is_active ? 'Active' : 'Inactive'}
                          </span>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                          {bom.effective_from ? formatDate(bom.effective_from) : 'N/A'}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                          <div className="flex items-center justify-center gap-2">
                            <button
                              onClick={() => setSelectedBom(bom)}
                              className="text-amber-600 hover:text-amber-900"
                              title="View Details"
                            >
                              👁️
                            </button>
                            <button
                              onClick={() => openEditModal(bom)}
                              className="text-blue-600 hover:text-blue-900"
                              title="Edit"
                            >
                              ✏️
                            </button>
                            <button
                              onClick={() => router.push(`/dashboard/bom/${bom.id}/routing`)}
                              className="text-indigo-600 hover:text-indigo-900"
                              title="Routing"
                            >
                              🔄
                            </button>
                            <button
                              onClick={() => handleGeneratePR(bom.id)}
                              className="text-green-600 hover:text-green-900"
                              title="Generate PR"
                            >
                              📋
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              );
            })()}
          </div>
        ) : (
          // CARD VIEW
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {loading ? (
            <div className="col-span-full text-center py-12 text-gray-500">Loading BOMs...</div>
          ) : boms.length === 0 ? (
            <div className="col-span-full text-center py-12">
              <div className="text-6xl mb-4">📋</div>
              <h3 className="text-xl font-semibold text-gray-700 mb-2">No BOMs Found</h3>
              <p className="text-gray-500">Create your first BOM to define product structure</p>
            </div>
          ) : (() => {
            const filteredBoms = boms.filter((bom) => {
              if (!searchQuery) return true;
              const query = searchQuery.toLowerCase();
              const itemName = bom.item?.name?.toLowerCase() || '';
              const itemCode = bom.item?.code?.toLowerCase() || '';
              const version = String(bom.version);
              return itemName.includes(query) || itemCode.includes(query) || version.includes(query);
            });

            if (filteredBoms.length === 0) {
              return (
                <div className="col-span-full text-center py-12">
                  <div className="text-6xl mb-4">🔍</div>
                  <h3 className="text-xl font-semibold text-gray-700 mb-2">No BOMs Match Your Search</h3>
                  <p className="text-gray-500">Try different keywords or clear the search</p>
                </div>
              );
            }

            return filteredBoms.map((bom) => (
              <div key={bom.id} className="bg-white rounded-lg shadow-md p-6 hover:shadow-lg transition-shadow">
                <div className="flex justify-between items-start mb-4">
                  <div>
                    <h3 className="text-lg font-bold text-gray-900">{bom.item?.name || 'Unknown Item'}</h3>
                    <p className="text-sm text-gray-500">{bom.item?.code || 'N/A'} - Version {bom.version}</p>
                  </div>
                  <span
                    className={`px-2 py-1 text-xs rounded-full ${
                      bom.is_active ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'
                    }`}
                  >
                    {bom.is_active ? 'Active' : 'Inactive'}
                  </span>
                </div>

                <div className="mb-4">
                  <h4 className="text-sm font-semibold text-gray-700 mb-2">Components ({bom.bom_items?.length || 0})</h4>
                  <div className="space-y-2">
                    {bom.bom_items?.slice(0, 3).map((item) => {
                      const isChildBom = item.component_type === 'BOM';
                      const componentCode = isChildBom
                        ? item.child_bom?.item?.code || 'BOM'
                        : item.item?.code || 'N/A';
                      const componentName = isChildBom
                        ? `${item.child_bom?.item?.name || 'Unknown'} (v${item.child_bom?.version ?? '?'})`
                        : item.item?.name || 'Unknown';
                      const componentUom = isChildBom
                        ? item.child_bom?.item?.uom || 'set'
                        : item.item?.uom || 'units';

                      return (
                        <div key={item.id} className="flex justify-between text-sm">
                          <span className="text-gray-600">
                            {componentCode} - {componentName}
                          </span>
                          <div className="flex items-center gap-2">
                            <span className="font-medium">
                              {item.quantity} {componentUom}
                            </span>
                            {item.drawing_url && (
                              <span className="text-blue-600" title="Drawing attached">📎</span>
                            )}
                          </div>
                        </div>
                      );
                    })}
                    {(bom.bom_items?.length || 0) > 3 && (
                      <p className="text-xs text-gray-500">+ {(bom.bom_items?.length || 0) - 3} more items</p>
                    )}
                  </div>
                </div>

                <div className="flex gap-2 pt-4 border-t">
                  <button
                    onClick={() => {
                      console.log('[BOM] View Details clicked:', bom.id);
                      setSelectedBom(bom);
                    }}
                    className="flex-1 bg-amber-100 text-amber-700 px-4 py-2 rounded hover:bg-amber-200 text-sm"
                  >
                    View Details
                  </button>
                  <button
                    onClick={() => {
                      openEditModal(bom);
                    }}
                    className="flex-1 bg-amber-600 text-white px-4 py-2 rounded hover:bg-amber-700 text-sm"
                  >
                    Edit
                  </button>
                  <button
                    onClick={() => router.push(`/dashboard/bom/${bom.id}/routing`)}
                    className="flex-1 bg-blue-100 text-blue-700 px-4 py-2 rounded hover:bg-blue-200 text-sm"
                  >
                    Routing
                  </button>
                  <button
                    onClick={() => {
                      console.log('[BOM] Generate PR clicked:', bom.id);
                      handleGeneratePR(bom.id);
                    }}
                    className="flex-1 bg-green-100 text-green-700 px-4 py-2 rounded hover:bg-green-200 text-sm"
                  >
                    Generate PR
                  </button>
                </div>
              </div>
            ));
          })()}
        </div>
        )}
      </div>

      {/* Create BOM Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg max-w-4xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b border-gray-200">
              <h2 className="text-2xl font-bold text-gray-900">
                {isEditMode ? 'Edit Bill of Materials' : 'Create Bill of Materials'}
              </h2>
            </div>

            <div className="p-6 space-y-6">
              {/* Info Box */}
              <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                <div className="flex items-start gap-3">
                  <span className="text-2xl">ℹ️</span>
                  <div>
                    <h4 className="font-semibold text-blue-900 mb-1">How to fill this form:</h4>
                    <ul className="text-sm text-blue-800 space-y-1">
                      <li>• <strong>Finished Product:</strong> Search and select the finished product you want to manufacture</li>
                      <li>• <strong>Parts:</strong> Add raw materials or purchased components needed for production</li>
                      <li>• <strong>Assemblies:</strong> Add sub-assemblies (other BOMs) that are part of this product</li>
                      <li>• <strong>Quantity:</strong> How many units of each part/assembly are needed to make 1 finished product</li>
                    </ul>
                    <p className="text-xs text-blue-700 mt-2">
                      ✨ Start typing to search items by name or code
                    </p>
                  </div>
                </div>
              </div>

              {/* BOM Header */}
              <div className="grid grid-cols-2 gap-4">
                <div className="col-span-2">
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Finished Product *
                  </label>
                  <ItemSearch
                    value={formData.itemId}
                    initialItem={
                      selectedBom?.item?.id && selectedBom.item.id === formData.itemId
                        ? { id: selectedBom.item.id, code: selectedBom.item.code, name: selectedBom.item.name }
                        : null
                    }
                    onSelect={(item) => setFormData({ ...formData, itemId: item.id })}
                    placeholder="Search by item name or code..."
                    disabled={isEditMode}
                  />
                  {isEditMode ? (
                    <p className="text-xs text-gray-500 mt-1">
                      Finished product cannot be changed in edit mode.
                    </p>
                  ) : null}
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Version</label>
                  <input
                    type="number"
                    value={formData.version}
                    onChange={(e) => setFormData({ ...formData, version: parseInt(e.target.value) })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                    disabled={isEditMode}
                  />
                  {isEditMode ? (
                    <p className="text-xs text-gray-500 mt-1">Version cannot be changed in edit mode.</p>
                  ) : null}
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Effective From</label>
                  <input
                    type="date"
                    value={formData.effectiveFrom}
                    onChange={(e) => setFormData({ ...formData, effectiveFrom: e.target.value })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  />
                </div>
              </div>

              {/* Components */}
              <div>
                <div className="flex justify-between items-center mb-4">
                  <h3 className="text-lg font-semibold text-gray-900">Components (Parts & Assemblies)</h3>
                  <button
                    onClick={handleAddItem}
                    className="text-amber-600 hover:text-amber-800 font-medium"
                  >
                    + Add Part/Assembly
                  </button>
                </div>

                {formData.items.length === 0 ? (
                  <div className="text-center py-8 border-2 border-dashed border-gray-300 rounded-lg">
                    <p className="text-gray-500">No parts or assemblies added. Click "Add Part/Assembly" to get started.</p>
                  </div>
                ) : (
                  <div className="space-y-4">
                    {formData.items.map((item, index) => (
                      <div key={index} className="border border-gray-300 rounded-lg p-4 bg-white">
                        {/* Component Type Selector */}
                        <div className="mb-3">
                          <label className="text-xs text-gray-600 font-medium block mb-2">Component Type *</label>
                          <div className="flex gap-4">
                            <label className="flex items-center cursor-pointer">
                              <input
                                type="radio"
                                name={`componentType-${index}`}
                                value="ITEM"
                                checked={item.componentType === 'ITEM'}
                                onChange={(e) => handleUpdateItem(index, 'componentType', e.target.value)}
                                className="mr-2"
                              />
                              <span className="text-sm">📦 Part (Raw Material/Component)</span>
                            </label>
                            <label className="flex items-center cursor-pointer">
                              <input
                                type="radio"
                                name={`componentType-${index}`}
                                value="BOM"
                                checked={item.componentType === 'BOM'}
                                onChange={(e) => handleUpdateItem(index, 'componentType', e.target.value)}
                                className="mr-2"
                              />
                              <span className="text-sm">🔧 Assembly (Sub-BOM)</span>
                            </label>
                          </div>
                        </div>

                        <div className="grid grid-cols-12 gap-3">
                          <div className="col-span-4">
                            <label className="text-xs text-gray-600 font-medium">
                              {item.componentType === 'ITEM' ? 'Part *' : 'Assembly *'}
                            </label>
                            {item.componentType === 'ITEM' ? (
                              <ItemSearch
                                value={item.itemId}
                                initialItem={
                                  selectedBom?.bom_items
                                    ?.map((bi) => {
                                      const resolvedId = bi.item?.id || (bi as any).item_id;
                                      if (!resolvedId || resolvedId !== item.itemId) return null;
                                      if (!bi.item?.code || !bi.item?.name) return null;
                                      return { id: resolvedId, code: bi.item.code, name: bi.item.name };
                                    })
                                    .find(Boolean) || null
                                }
                                onSelect={(selectedItem) => handleUpdateItem(index, 'itemId', selectedItem.id)}
                                placeholder="Search part by name or code..."
                                className="w-full border border-gray-300 rounded px-3 py-2 text-sm focus:ring-2 focus:ring-amber-500"
                              />
                            ) : (
                              <select
                                value={item.childBomId}
                                onChange={(e) => handleUpdateItem(index, 'childBomId', e.target.value)}
                                className="w-full border border-gray-300 rounded px-3 py-2 text-sm focus:ring-2 focus:ring-amber-500"
                              >
                                <option value="">Select assembly BOM...</option>
                                {availableBOMs.map((bom) => (
                                  <option key={bom.id} value={bom.id}>
                                    {bom.item?.code} - {bom.item?.name} (v{bom.version})
                                  </option>
                                ))}
                              </select>
                            )}
                          </div>
                          <div className="col-span-2">
                            <label className="text-xs text-gray-600">Quantity *</label>
                            <input
                              type="number"
                              value={item.quantity}
                              onChange={(e) => handleUpdateItem(index, 'quantity', parseFloat(e.target.value))}
                              className="w-full border border-gray-300 rounded px-3 py-2 text-sm"
                            />
                          </div>
                          <div className="col-span-2">
                            <label className="text-xs text-gray-600">Scrap %</label>
                            <input
                              type="number"
                              value={item.scrapPercentage}
                              onChange={(e) => handleUpdateItem(index, 'scrapPercentage', parseFloat(e.target.value))}
                              className="w-full border border-gray-300 rounded px-3 py-2 text-sm"
                            />
                          </div>
                          <div className="col-span-1 flex items-end">
                            <button
                              onClick={() => handleRemoveItem(index)}
                              className="text-red-600 hover:text-red-900 text-xl"
                              title="Remove component"
                            >
                              ×
                            </button>
                          </div>
                        </div>
                        <div className="mt-2">
                          <input
                            type="text"
                            value={item.notes}
                            onChange={(e) => handleUpdateItem(index, 'notes', e.target.value)}
                            className="w-full border border-gray-300 rounded px-3 py-2 text-sm"
                            placeholder="Specifications / Notes..."
                          />
                        </div>

                        <div className="mt-3">
                          <label className="text-xs text-gray-600 font-medium block mb-1">Drawing (optional)</label>
                          <div className="flex flex-col gap-2 sm:flex-row sm:items-center">
                            <input
                              type="text"
                              value={item.drawingUrl || ''}
                              onChange={(e) => handleUpdateItem(index, 'drawingUrl', e.target.value)}
                              className="flex-1 border border-gray-300 rounded px-3 py-2 text-sm"
                              placeholder="Paste drawing URL (or use Upload)"
                            />
                            <div className="flex items-center gap-3">
                              <input
                                type="file"
                                accept="image/png,image/jpeg,image/jpg,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document"
                                onChange={async (e) => {
                                  const file = e.target.files?.[0];
                                  await handleDrawingFileSelect(index, file);
                                  e.target.value = '';
                                }}
                                className="text-sm"
                              />
                              {item.drawingUrl ? (
                                <button
                                  type="button"
                                  onClick={() => openDrawingUrlInNewTab(item.drawingUrl)}
                                  className="text-blue-600 hover:text-blue-800 text-sm font-medium"
                                >
                                  View
                                </button>
                              ) : null}
                            </div>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
                {formData.items.length > 0 && (
                  <div className="mt-4 flex justify-center">
                    <button
                      onClick={handleAddItem}
                      className="px-6 py-2 text-amber-600 hover:text-amber-800 font-medium border-2 border-dashed border-amber-300 hover:border-amber-500 rounded-lg transition-colors"
                    >
                      + Add Another Component
                    </button>
                  </div>
                )}
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">BOM Notes</label>
                <textarea
                  value={formData.notes}
                  onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                  rows={3}
                  className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  placeholder="Additional notes..."
                />
              </div>
            </div>

            <div className="p-6 border-t border-gray-200 flex justify-end gap-4">
              <button
                onClick={() => {
                  setShowModal(false);
                  setEditingBomId(null);
                  resetForm();
                }}
                className="px-6 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
              >
                Cancel
              </button>
              <button
                onClick={isEditMode ? handleUpdateBOM : handleCreateBOM}
                className="px-6 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700"
              >
                {isEditMode ? 'Save Changes' : 'Create BOM'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Purchase Trail Modal */}
      {showTrailModal && purchaseTrail && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg max-w-4xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b border-gray-200">
              <div className="flex justify-between items-start">
                <div>
                  <h2 className="text-2xl font-bold text-gray-900">Purchase Trail</h2>
                  <p className="text-gray-600 mt-1">Complete traceability for UID: {purchaseTrail.uid}</p>
                </div>
                <button
                  onClick={() => {
                    setShowTrailModal(false);
                    setPurchaseTrail(null);
                  }}
                  className="text-gray-500 hover:text-gray-700"
                >
                  <span className="text-2xl">×</span>
                </button>
              </div>
            </div>

            <div className="p-6 space-y-6">
              {/* Item Information */}
              <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                <h3 className="font-semibold text-blue-900 mb-2">📦 Item Information</h3>
                <div className="grid grid-cols-2 gap-4 text-sm">
                  <div>
                    <span className="text-gray-600">Item Code:</span>
                    <span className="ml-2 font-medium">{purchaseTrail.item.code}</span>
                  </div>
                  <div>
                    <span className="text-gray-600">Item Name:</span>
                    <span className="ml-2 font-medium">{purchaseTrail.item.name}</span>
                  </div>
                  {purchaseTrail.batch_number && (
                    <div>
                      <span className="text-gray-600">Batch Number:</span>
                      <span className="ml-2 font-medium">{purchaseTrail.batch_number}</span>
                    </div>
                  )}
                  {purchaseTrail.location && (
                    <div>
                      <span className="text-gray-600">Current Location:</span>
                      <span className="ml-2 font-medium">{purchaseTrail.location}</span>
                    </div>
                  )}
                </div>
              </div>

              {/* Supplier Information */}
              {purchaseTrail.supplier && (
                <div className="bg-green-50 border border-green-200 rounded-lg p-4">
                  <h3 className="font-semibold text-green-900 mb-2">🏭 Supplier Information</h3>
                  <div className="grid grid-cols-2 gap-4 text-sm">
                    <div>
                      <span className="text-gray-600">Supplier Name:</span>
                      <span className="ml-2 font-medium">{purchaseTrail.supplier.name}</span>
                    </div>
                    <div>
                      <span className="text-gray-600">Contact Person:</span>
                      <span className="ml-2 font-medium">{purchaseTrail.supplier.contact_person}</span>
                    </div>
                  </div>
                </div>
              )}

              {/* Purchase Order Information */}
              {purchaseTrail.purchase_order && (
                <div className="bg-purple-50 border border-purple-200 rounded-lg p-4">
                  <h3 className="font-semibold text-purple-900 mb-2">📋 Purchase Order</h3>
                  <div className="grid grid-cols-3 gap-4 text-sm">
                    <div>
                      <span className="text-gray-600">PO Number:</span>
                      <span className="ml-2 font-medium">{purchaseTrail.purchase_order.po_number}</span>
                    </div>
                    <div>
                      <span className="text-gray-600">Order Date:</span>
                      <span className="ml-2 font-medium">{formatDate(purchaseTrail.purchase_order.order_date)}</span>
                    </div>
                    <div>
                      <span className="text-gray-600">Total Amount:</span>
                      <span className="ml-2 font-medium">₹{purchaseTrail.purchase_order.total_amount.toLocaleString('en-IN')}</span>
                    </div>
                  </div>
                </div>
              )}

              {/* GRN Information */}
              {purchaseTrail.grn && (
                <div className="bg-amber-50 border border-amber-200 rounded-lg p-4">
                  <h3 className="font-semibold text-amber-900 mb-2">📥 Goods Receipt Note</h3>
                  <div className="grid grid-cols-3 gap-4 text-sm">
                    <div>
                      <span className="text-gray-600">GRN Number:</span>
                      <span className="ml-2 font-medium">{purchaseTrail.grn.grn_number}</span>
                    </div>
                    <div>
                      <span className="text-gray-600">Received Date:</span>
                      <span className="ml-2 font-medium">{formatDate(purchaseTrail.grn.received_date)}</span>
                    </div>
                    <div>
                      <span className="text-gray-600">Quantity:</span>
                      <span className="ml-2 font-medium">{purchaseTrail.grn.received_quantity}</span>
                    </div>
                  </div>
                </div>
              )}

              {/* Lifecycle Timeline */}
              {purchaseTrail.lifecycle && purchaseTrail.lifecycle.length > 0 && (
                <div className="bg-gray-50 border border-gray-200 rounded-lg p-4">
                  <h3 className="font-semibold text-gray-900 mb-4">🕐 Lifecycle Timeline</h3>
                  <div className="space-y-3">
                    {purchaseTrail.lifecycle.map((event, index) => (
                      <div key={index} className="flex gap-4">
                        <div className="flex flex-col items-center">
                          <div className="w-3 h-3 bg-amber-600 rounded-full"></div>
                          {index < purchaseTrail.lifecycle.length - 1 && (
                            <div className="w-0.5 h-full bg-amber-300 my-1"></div>
                          )}
                        </div>
                        <div className="flex-1 pb-4">
                          <div className="flex justify-between items-start">
                            <div>
                              <p className="font-medium text-gray-900">{event.stage}</p>
                              <p className="text-sm text-gray-600">{event.location}</p>
                              <p className="text-xs text-gray-500">{event.reference}</p>
                            </div>
                            <span className="text-xs text-gray-500">{formatDate(event.timestamp)}</span>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            <div className="p-6 border-t border-gray-200 flex justify-end">
              <button
                onClick={() => {
                  setShowTrailModal(false);
                  setPurchaseTrail(null);
                }}
                className="px-6 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* BOM Details Modal */}
      {selectedBom && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-lg max-w-4xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b border-gray-200">
              <div className="flex justify-between items-start">
                <div>
                  <h2 className="text-2xl font-bold text-gray-900">BOM Details</h2>
                  <p className="text-gray-600 mt-1">
                    {selectedBom.item?.code || 'N/A'} - {selectedBom.item?.name || 'Unknown'}
                  </p>
                </div>
                <button
                  onClick={() => setSelectedBom(null)}
                  className="text-gray-500 hover:text-gray-700 text-2xl"
                >
                  ×
                </button>
              </div>
            </div>

            <div className="p-6 space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-sm font-medium text-gray-600">Version</label>
                  <p className="text-gray-900">{selectedBom.version}</p>
                </div>
                <div>
                  <label className="text-sm font-medium text-gray-600">Status</label>
                  <p className={`inline-block px-2 py-1 text-xs rounded-full ${
                    selectedBom.is_active ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'
                  }`}>
                    {selectedBom.is_active ? 'Active' : 'Inactive'}
                  </p>
                </div>
                <div>
                  <label className="text-sm font-medium text-gray-600">Effective From</label>
                  <p className="text-gray-900">{selectedBom.effective_from ? formatDate(selectedBom.effective_from) : 'N/A'}</p>
                </div>
                <div>
                  <label className="text-sm font-medium text-gray-600">Effective To</label>
                  <p className="text-gray-900">{selectedBom.effective_to ? formatDate(selectedBom.effective_to) : 'N/A'}</p>
                </div>
                {selectedBom.notes && (
                  <div className="col-span-2">
                    <label className="text-sm font-medium text-gray-600">Notes</label>
                    <p className="text-gray-900">{selectedBom.notes}</p>
                  </div>
                )}
              </div>

              <div>
                <h3 className="text-lg font-semibold text-gray-900 mb-4">
                  Components ({selectedBom.bom_items?.length || 0})
                </h3>
                
                {selectedBom.bom_items && selectedBom.bom_items.length > 0 ? (
                  <div className="border border-gray-200 rounded-lg overflow-hidden">
                    <table className="w-full">
                      <thead className="bg-gray-50">
                        <tr>
                          <th className="px-4 py-3 text-left text-xs font-medium text-gray-700 uppercase">Type</th>
                          <th className="px-4 py-3 text-left text-xs font-medium text-gray-700 uppercase">Code</th>
                          <th className="px-4 py-3 text-left text-xs font-medium text-gray-700 uppercase">Name</th>
                          <th className="px-4 py-3 text-right text-xs font-medium text-gray-700 uppercase">Quantity</th>
                          <th className="px-4 py-3 text-right text-xs font-medium text-gray-700 uppercase">Scrap %</th>
                          <th className="px-4 py-3 text-left text-xs font-medium text-gray-700 uppercase">Notes</th>
                          <th className="px-4 py-3 text-center text-xs font-medium text-gray-700 uppercase">Drawing</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-gray-200">
                        {selectedBom.bom_items.map((item) => (
                          <tr key={item.id} className="hover:bg-gray-50">
                            <td className="px-4 py-3">
                              <span className={`px-2 py-1 text-xs rounded ${
                                item.component_type === 'BOM' 
                                  ? 'bg-blue-100 text-blue-800' 
                                  : 'bg-green-100 text-green-800'
                              }`}>
                                {item.component_type === 'BOM' ? '🔧 Assembly' : '📦 Part'}
                              </span>
                            </td>
                            <td className="px-4 py-3 text-sm text-gray-900">
                              {item.component_type === 'BOM' 
                                ? item.child_bom?.item?.code || 'N/A'
                                : item.item?.code || 'N/A'}
                            </td>
                            <td className="px-4 py-3 text-sm text-gray-900">
                              {item.component_type === 'BOM' 
                                ? `${item.child_bom?.item?.name || 'Unknown'} (v${item.child_bom?.version || '?'})`
                                : item.item?.name || 'Unknown'}
                            </td>
                            <td className="px-4 py-3 text-sm text-gray-900 text-right">
                              {item.quantity} {item.component_type === 'ITEM' ? item.item?.uom || 'units' : 'units'}
                            </td>
                            <td className="px-4 py-3 text-sm text-gray-900 text-right">
                              {item.scrap_percentage || 0}%
                            </td>
                            <td className="px-4 py-3 text-sm text-gray-600">{item.notes || '-'}</td>
                            <td className="px-4 py-3 text-center">
                              <div className="flex items-center justify-center gap-3">
                                {item.drawing_url ? (
                                  <a 
                                    href={item.drawing_url} 
                                    target="_blank" 
                                    rel="noopener noreferrer"
                                    className="text-blue-600 hover:text-blue-800"
                                  >
                                    📎 View
                                  </a>
                                ) : (
                                  <span className="text-gray-400">-</span>
                                )}

                                {item.component_type === 'ITEM' && item.item?.id && (
                                  <button
                                    type="button"
                                    onClick={() => {
                                      setSelectedItemForDrawing({
                                        id: item.item!.id!,
                                        code: item.item?.code || '',
                                        name: item.item?.name || '',
                                      });
                                      setShowDrawingManager(true);
                                    }}
                                    className="text-amber-700 hover:text-amber-900 text-sm font-medium"
                                  >
                                    Manage
                                  </button>
                                )}
                              </div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                ) : (
                  <p className="text-gray-500 text-center py-8 bg-gray-50 rounded-lg">No components</p>
                )}
              </div>
            </div>

            <div className="p-6 border-t border-gray-200 flex justify-between">
              <button
                onClick={() => handleDeleteBOM(selectedBom.id)}
                className="px-6 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700"
              >
                Delete BOM
              </button>
              <div className="flex gap-3">
                <button
                  onClick={() => {
                    openEditModal(selectedBom);
                    setSelectedBom(null);
                  }}
                  className="px-6 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700"
                >
                  Edit BOM
                </button>
                <button
                  onClick={() => setSelectedBom(null)}
                  className="px-6 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
                >
                  Close
                </button>
                <button
                  onClick={() => {
                    handleGeneratePR(selectedBom.id);
                    setSelectedBom(null);
                  }}
                  className="px-6 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700"
                >
                  Generate PR
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Generate PR Modal */}
      {showPRModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50 overflow-y-auto">
          <div className="bg-white rounded-lg max-w-4xl w-full max-h-[90vh] overflow-y-auto my-8">
            <div className="p-6 border-b border-gray-200">
              <h2 className="text-xl font-bold text-gray-900">Generate Purchase Requisition</h2>
              <p className="text-gray-600 text-sm mt-1">Enter production quantity to calculate material requirements</p>
            </div>

            <div className="p-6">
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Production Quantity *
              </label>
              <input
                type="number"
                value={prQuantity}
                onChange={(e) => {
                  setPrQuantity(Number(e.target.value));
                  setPrStockStatus([]); // Clear previous status when quantity changes
                }}
                min="1"
                step="1"
                className="w-full border border-gray-300 rounded-lg px-4 py-3 text-lg focus:ring-2 focus:ring-green-500"
                placeholder="Enter quantity"
                autoFocus
              />
              <p className="text-xs text-gray-500 mt-2">
                Number of finished goods you want to produce
              </p>
            </div>

            {/* Stock Status Table */}
            {prStockStatus.length > 0 && (
              <div className="px-6 pb-6">
                <h3 className="text-lg font-semibold text-gray-900 mb-4">Material Stock Status</h3>
                <div className="overflow-x-auto">
                  <table className="min-w-full divide-y divide-gray-200 border">
                    <thead className="bg-gray-50">
                      <tr>
                        <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Item</th>
                        <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">Required</th>
                        <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">Available</th>
                        <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">Reserved</th>
                        <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">Usable</th>
                        <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">Shortfall</th>
                        <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase">PR Status</th>
                      </tr>
                    </thead>
                    <tbody className="bg-white divide-y divide-gray-200">
                      {prStockStatus.map((item: any, index: number) => (
                        <tr key={index} className={item.needsPR ? 'bg-red-50' : 'bg-green-50'}>
                          <td className="px-4 py-3 text-sm">
                            <div className="font-medium text-gray-900">{item.itemCode}</div>
                            <div className="text-gray-500 text-xs">{item.itemName}</div>
                          </td>
                          <td className="px-4 py-3 text-sm text-right font-medium">{item.required}</td>
                          <td className="px-4 py-3 text-sm text-right">{item.availableStock}</td>
                          <td className="px-4 py-3 text-sm text-right text-yellow-600">{item.reservedStock}</td>
                          <td className="px-4 py-3 text-sm text-right font-medium">{item.usableStock}</td>
                          <td className="px-4 py-3 text-sm text-right">
                            {item.shortfall > 0 ? (
                              <span className="text-red-600 font-semibold">{item.shortfall}</span>
                            ) : (
                              <span className="text-green-600">-</span>
                            )}
                          </td>
                          <td className="px-4 py-3 text-center">
                            {item.needsPR ? (
                              <span className="inline-flex px-2 py-1 text-xs font-semibold rounded-full bg-red-100 text-red-800">
                                PR Created
                              </span>
                            ) : (
                              <span className="inline-flex px-2 py-1 text-xs font-semibold rounded-full bg-green-100 text-green-800">
                                In Stock
                              </span>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                <div className="mt-4 p-4 bg-blue-50 rounded-lg">
                  <p className="text-sm text-blue-800">
                    <strong>Note:</strong> Usable Stock = Available Stock - Reorder Level (safety stock). 
                    PR will be generated only for items with shortfall.
                  </p>
                </div>
              </div>
            )}

            <div className="p-6 border-t border-gray-200 flex justify-end gap-3">
              <button
                onClick={() => {
                  setShowPRModal(false);
                  setPrStockStatus([]);
                }}
                className="px-6 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
              >
                Close
              </button>
              {prStockStatus.length === 0 && (
                <button
                  onClick={handleConfirmGeneratePR}
                  className="px-6 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700"
                >
                  Generate PR
                </button>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Drawing Manager Modal (BOM component item drawings) */}
      {showDrawingManager && selectedItemForDrawing && (
        <DrawingManager
          itemId={selectedItemForDrawing.id}
          itemCode={selectedItemForDrawing.code}
          itemName={selectedItemForDrawing.name}
          onClose={() => {
            setShowDrawingManager(false);
            setSelectedItemForDrawing(null);
          }}
        />
      )}
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';

export default function DebugPage() {
  const router = useRouter();
  const [tokenInfo, setTokenInfo] = useState<any>(null);
  const [error, setError] = useState<string>('');

  useEffect(() => {
    try {
      const token = localStorage.getItem('accessToken');
      
      if (!token) {
        setError('No access token found. Please login.');
        return;
      }

      // Decode JWT (split by dots, take payload, base64 decode)
      const parts = token.split('.');
      if (parts.length !== 3) {
        setError('Invalid token format');
        return;
      }

      const payload = JSON.parse(atob(parts[1]));
      setTokenInfo({
        userId: payload.sub,
        email: payload.email,
        tenantId: payload.tenantId,
        iat: new Date(payload.iat * 1000).toLocaleString(),
        exp: new Date(payload.exp * 1000).toLocaleString(),
        fullPayload: payload,
      });
    } catch (err: any) {
      setError(`Error decoding token: ${err.message}`);
    }
  }, []);

  return (
    <div className="min-h-screen bg-gradient-to-br from-amber-50 to-orange-50 p-8">
      <div className="max-w-4xl mx-auto">
        <button
          onClick={() => router.push('/dashboard')}
          className="text-amber-600 hover:text-amber-800 mb-4"
        >
          ← Back to Dashboard
        </button>

        <div className="bg-white rounded-lg shadow-md p-8">
          <h1 className="text-3xl font-bold text-amber-900 mb-6">🔍 JWT Token Debug</h1>

          {error ? (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded mb-4">
              {error}
            </div>
          ) : tokenInfo ? (
            <div className="space-y-6">
              {/* Critical Check */}
              <div className={`p-4 rounded-lg ${tokenInfo.tenantId ? 'bg-green-100 border-2 border-green-500' : 'bg-red-100 border-2 border-red-500'}`}>
                <h2 className="text-xl font-bold mb-2">
                  {tokenInfo.tenantId ? '✅ Tenant ID Present' : '❌ NO TENANT ID - CRITICAL ISSUE'}
                </h2>
                {tokenInfo.tenantId ? (
                  <p className="text-green-800">Your token has tenant isolation enabled</p>
                ) : (
                  <div className="text-red-800">
                    <p className="font-bold">Your token is missing tenantId!</p>
                    <p className="mt-2">This means you&apos;re logged in with an OLD session before the multi-tenant fix.</p>
                    <p className="mt-2 font-bold">ACTION REQUIRED: Logout and login again to get a fresh token with tenantId</p>
                  </div>
                )}
              </div>

              {/* Token Details */}
              <div className="border rounded-lg p-4">
                <h3 className="font-bold text-lg mb-3">Token Information:</h3>
                <div className="space-y-2">
                  <div className="grid grid-cols-3 gap-2">
                    <span className="font-medium">User ID:</span>
                    <span className="col-span-2 font-mono text-sm">{tokenInfo.userId}</span>
                  </div>
                  <div className="grid grid-cols-3 gap-2">
                    <span className="font-medium">Email:</span>
                    <span className="col-span-2">{tokenInfo.email}</span>
                  </div>
                  <div className="grid grid-cols-3 gap-2">
                    <span className="font-medium">Tenant ID:</span>
                    <span className={`col-span-2 font-mono text-sm ${tokenInfo.tenantId ? 'text-green-600' : 'text-red-600'}`}>
                      {tokenInfo.tenantId || 'MISSING ❌'}
                    </span>
                  </div>
                  <div className="grid grid-cols-3 gap-2">
                    <span className="font-medium">Issued At:</span>
                    <span className="col-span-2">{tokenInfo.iat}</span>
                  </div>
                  <div className="grid grid-cols-3 gap-2">
                    <span className="font-medium">Expires At:</span>
                    <span className="col-span-2">{tokenInfo.exp}</span>
                  </div>
                </div>
              </div>

              {/* Full Payload */}
              <div className="border rounded-lg p-4">
                <h3 className="font-bold text-lg mb-3">Full JWT Payload:</h3>
                <pre className="bg-gray-100 p-4 rounded overflow-x-auto text-xs">
                  {JSON.stringify(tokenInfo.fullPayload, null, 2)}
                </pre>
              </div>

              {/* Action Buttons */}
              <div className="flex gap-4">
                <button
                  onClick={() => {
                    localStorage.clear();
                    window.location.href = '/';
                  }}
                  className="bg-red-600 hover:bg-red-700 text-white px-6 py-3 rounded-lg font-semibold"
                >
                  🚪 Force Logout & Clear All Data
                </button>
                <button
                  onClick={() => window.location.reload()}
                  className="bg-amber-600 hover:bg-amber-700 text-white px-6 py-3 rounded-lg font-semibold"
                >
                  🔄 Refresh Debug Info
                </button>
              </div>
            </div>
          ) : (
            <div className="text-center py-8 text-gray-500">Loading token information...</div>
          )}
        </div>

        {/* Instructions */}
        <div className="mt-6 bg-blue-50 border border-blue-200 rounded-lg p-6">
          <h3 className="font-bold text-blue-900 mb-3">🎯 How to Fix &quot;No Vendors/GRN Showing&quot; Issue:</h3>
          <ol className="list-decimal list-inside space-y-2 text-blue-800">
            <li>Check if your JWT token has a <code className="bg-blue-100 px-1 rounded">tenantId</code> field</li>
            <li>If <strong>missing tenantId</strong>: Click &quot;Force Logout&quot; above, then login again</li>
            <li>After fresh login, your token will have tenantId and vendors will be isolated to your company</li>
            <li>Old vendors created before the fix belong to &quot;SAK Solutions&quot; tenant - you&apos;ll need to create new ones</li>
          </ol>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { apiClient } from '../../../../lib/api-client';

interface WorkflowActionsProps {
  document: {
    id: string;
    status: string;
    document_number: string;
    title: string;
  };
  onSuccess: () => void;
}

interface Employee {
  id: string;
  employee_name: string;
  email: string;
  designation: string;
}

export default function WorkflowActions({ document, onSuccess }: WorkflowActionsProps) {
  const [showModal, setShowModal] = useState(false);
  const [action, setAction] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loadingEmployees, setLoadingEmployees] = useState(false);
  const [formData, setFormData] = useState({
    recipientEmail: '',
    recipientName: '',
    comments: '',
    reason: '',
    clientEmail: '',
    clientName: '',
    message: '',
  });

  // Load employees list
  useEffect(() => {
    loadEmployees();
  }, []);

  const loadEmployees = async () => {
    setLoadingEmployees(true);
    try {
      const data = await apiClient.get<Employee[]>('/hr/employees');
      setEmployees(Array.isArray(data) ? data : (data as any)?.data || []);
    } catch (error) {
      console.error('Failed to load employees:', error);
    } finally {
      setLoadingEmployees(false);
    }
  };

  const handleEmployeeSelect = (employeeId: string) => {
    const employee = employees.find(e => e.id === employeeId);
    if (employee) {
      setFormData({
        ...formData,
        recipientName: employee.employee_name,
        recipientEmail: employee.email,
      });
    }
  };

  const handleAction = async () => {
    setLoading(true);
    try {
      let endpoint = '';
      let payload: any = {};

      switch (action) {
        case 'forward-to-staff':
          endpoint = `/documents/${document.id}/forward-to-staff`;
          payload = {
            recipientEmail: formData.recipientEmail,
            recipientName: formData.recipientName,
            comments: formData.comments,
          };
          break;
        case 'return-to-admin':
          endpoint = `/documents/${document.id}/return-to-admin`;
          payload = { comments: formData.comments };
          break;
        case 'forward-to-manager':
          endpoint = `/documents/${document.id}/forward-to-manager`;
          payload = {
            recipientEmail: formData.recipientEmail,
            recipientName: formData.recipientName,
            comments: formData.comments,
          };
          break;
        case 'send-to-client':
          endpoint = `/documents/${document.id}/send-to-client`;
          payload = {
            clientEmail: formData.clientEmail,
            clientName: formData.clientName,
            message: formData.message,
          };
          break;
        case 'reject':
          endpoint = `/documents/${document.id}/workflow-reject`;
          payload = {
            reason: formData.reason,
            rejectedBy: formData.recipientName,
          };
          break;
        case 'final-approve':
          endpoint = `/documents/${document.id}/final-approve`;
          payload = {};
          break;
      }

      await apiClient.post(endpoint, payload);
      setShowModal(false);
      setFormData({
        recipientEmail: '',
        recipientName: '',
        comments: '',
        reason: '',
        clientEmail: '',
        clientName: '',
        message: '',
      });
      onSuccess();
    } catch (error: any) {
      alert(error.response?.data?.message || 'Action failed');
    } finally {
      setLoading(false);
    }
  };

  const openModal = (actionType: string) => {
    setAction(actionType);
    setShowModal(true);
  };

  const getAvailableActions = () => {
    const actions: Array<{ label: string; action: string; color: string; icon: string }> = [];

    switch (document.status) {
      case 'DRAFT':
        actions.push({ label: 'Forward to Staff', action: 'forward-to-staff', color: 'blue', icon: '→' });
        break;
      case 'PENDING_REVIEW':
        actions.push({ label: 'Return to Admin', action: 'return-to-admin', color: 'yellow', icon: '←' });
        actions.push({ label: 'Reject', action: 'reject', color: 'red', icon: '✗' });
        break;
      case 'PENDING_APPROVAL':
        actions.push({ label: 'Forward to Manager', action: 'forward-to-manager', color: 'blue', icon: '→' });
        actions.push({ label: 'Reject', action: 'reject', color: 'red', icon: '✗' });
        break;
      case 'SENT_TO_CLIENT':
        actions.push({ label: 'Final Approve', action: 'final-approve', color: 'green', icon: '✓' });
        actions.push({ label: 'Send to Client Again', action: 'send-to-client', color: 'blue', icon: '📧' });
        break;
      default:
        if (document.status !== 'APPROVED' && document.status !== 'REJECTED') {
          actions.push({ label: 'Send to Client', action: 'send-to-client', color: 'purple', icon: '📧' });
        }
    }

    return actions;
  };

  const renderModalContent = () => {
    switch (action) {
      case 'forward-to-staff':
      case 'forward-to-manager':
        return (
          <>
            <h3 className="text-lg font-semibold mb-4">
              {action === 'forward-to-staff' ? 'Forward to Staff' : 'Forward to Manager'}
            </h3>
            <div className="space-y-3">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Select Employee
                </label>
                <select
                  className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-amber-500"
                  onChange={(e) => handleEmployeeSelect(e.target.value)}
                  disabled={loadingEmployees}
                >
                  <option value="">-- Select Employee --</option>
                  {employees.map((emp) => (
                    <option key={emp.id} value={emp.id}>
                      {emp.employee_name} ({emp.designation})
                    </option>
                  ))}
                </select>
                {loadingEmployees && (
                  <p className="text-xs text-gray-500 mt-1">Loading employees...</p>
                )}
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Recipient Name
                </label>
                <input
                  type="text"
                  className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-amber-500 bg-gray-50"
                  value={formData.recipientName}
                  onChange={(e) => setFormData({ ...formData, recipientName: e.target.value })}
                  required
                  readOnly
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Recipient Email
                </label>
                <input
                  type="email"
                  className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-amber-500 bg-gray-50"
                  value={formData.recipientEmail}
                  onChange={(e) => setFormData({ ...formData, recipientEmail: e.target.value })}
                  required
                  readOnly
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Comments
                </label>
                <textarea
                  className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-amber-500"
                  rows={3}
                  value={formData.comments}
                  onChange={(e) => setFormData({ ...formData, comments: e.target.value })}
                />
              </div>
            </div>
          </>
        );

      case 'return-to-admin':
        return (
          <>
            <h3 className="text-lg font-semibold mb-4">Return to Admin</h3>
            <div className="space-y-3">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Comments
                </label>
                <textarea
                  className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-amber-500"
                  rows={3}
                  value={formData.comments}
                  onChange={(e) => setFormData({ ...formData, comments: e.target.value })}
                  placeholder="Add any comments or feedback..."
                />
              </div>
            </div>
          </>
        );

      case 'send-to-client':
        return (
          <>
            <h3 className="text-lg font-semibold mb-4">Send to Client</h3>
            <div className="space-y-3">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Client Name
                </label>
                <input
                  type="text"
                  className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-amber-500"
                  value={formData.clientName}
                  onChange={(e) => setFormData({ ...formData, clientName: e.target.value })}
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Client Email
                </label>
                <input
                  type="email"
                  className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-amber-500"
                  value={formData.clientEmail}
                  onChange={(e) => setFormData({ ...formData, clientEmail: e.target.value })}
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Message
                </label>
                <textarea
                  className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-amber-500"
                  rows={4}
                  value={formData.message}
                  onChange={(e) => setFormData({ ...formData, message: e.target.value })}
                  placeholder="Add a message for the client..."
                />
              </div>
            </div>
          </>
        );

      case 'reject':
        return (
          <>
            <h3 className="text-lg font-semibold mb-4">Reject Document</h3>
            <div className="space-y-3">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Your Name
                </label>
                <input
                  type="text"
                  className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-amber-500"
                  value={formData.recipientName}
                  onChange={(e) => setFormData({ ...formData, recipientName: e.target.value })}
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Reason for Rejection
                </label>
                <textarea
                  className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-amber-500"
                  rows={4}
                  value={formData.reason}
                  onChange={(e) => setFormData({ ...formData, reason: e.target.value })}
                  placeholder="Explain why this document is being rejected..."
                  required
                />
              </div>
            </div>
          </>
        );

      case 'final-approve':
        return (
          <>
            <h3 className="text-lg font-semibold mb-4">Final Approval</h3>
            <p className="text-gray-600 mb-4">
              Are you sure you want to give final approval to this document? This action will mark the document as APPROVED.
            </p>
            <div className="bg-green-50 border border-green-200 rounded-lg p-3">
              <p className="text-sm text-green-800">
                <strong>Document:</strong> {document.document_number} - {document.title}
              </p>
            </div>
          </>
        );

      default:
        return null;
    }
  };

  const availableActions = getAvailableActions();

  if (availableActions.length === 0) {
    return null;
  }

  return (
    <>
      <div className="flex gap-2 flex-wrap">
        {availableActions.map((item) => (
          <button
            key={item.action}
            onClick={() => openModal(item.action)}
            className={`px-3 py-1.5 rounded text-sm font-medium transition-colors
              ${item.color === 'blue' ? 'bg-blue-50 text-blue-700 hover:bg-blue-100' : ''}
              ${item.color === 'yellow' ? 'bg-yellow-50 text-yellow-700 hover:bg-yellow-100' : ''}
              ${item.color === 'red' ? 'bg-red-50 text-red-700 hover:bg-red-100' : ''}
              ${item.color === 'green' ? 'bg-green-50 text-green-700 hover:bg-green-100' : ''}
              ${item.color === 'purple' ? 'bg-purple-50 text-purple-700 hover:bg-purple-100' : ''}
            `}
          >
            {item.icon} {item.label}
          </button>
        ))}
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-xl p-6 max-w-md w-full mx-4">
            {renderModalContent()}
            <div className="flex gap-3 mt-6">
              <button
                onClick={() => setShowModal(false)}
                disabled={loading}
                className="flex-1 px-4 py-2 border border-gray-300 rounded hover:bg-gray-50 transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={handleAction}
                disabled={loading}
                className="flex-1 px-4 py-2 bg-amber-500 text-white rounded hover:bg-amber-600 transition-colors disabled:bg-gray-400"
              >
                {loading ? 'Processing...' : 'Confirm'}
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { apiClient } from '../../../../lib/api-client';

interface WorkflowHistoryItem {
  id: string;
  action: string;
  from_status: string | null;
  to_status: string | null;
  actor_name: string;
  actor_email: string;
  recipient_name: string | null;
  recipient_email: string | null;
  comments: string | null;
  created_at: string;
}

interface WorkflowHistoryProps {
  documentId: string;
}

export default function WorkflowHistory({ documentId }: WorkflowHistoryProps) {
  const [history, setHistory] = useState<WorkflowHistoryItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [showHistory, setShowHistory] = useState(false);

  useEffect(() => {
    if (showHistory && documentId) {
      loadHistory();
    }
  }, [showHistory, documentId]);

  const loadHistory = async () => {
    setLoading(true);
    setError('');
    try {
      const data = await apiClient.get<WorkflowHistoryItem[]>(`/documents/${documentId}/workflow-history`);
      setHistory(Array.isArray(data) ? data : []);
    } catch (e: any) {
      console.error('Failed to load workflow history:', e);
      setError(e.response?.data?.message || 'Failed to load workflow history');
      setHistory([]);
    } finally {
      setLoading(false);
    }
  };

  const formatAction = (action: string): string => {
    const actionMap: Record<string, string> = {
      'FORWARDED_TO_STAFF': '📤 Forwarded to Staff',
      'RETURNED_TO_ADMIN': '↩️ Returned to Admin',
      'FORWARDED_TO_MANAGER': '📤 Forwarded to Manager',
      'SENT_TO_CLIENT': '📧 Sent to Client',
      'REJECTED': '❌ Rejected',
      'FINAL_APPROVED': '✅ Final Approved',
      'CREATED': '📝 Created',
      'CLIENT_UPLOADED_REVISION': '📎 Client Uploaded Revision',
    };
    return actionMap[action] || action;
  };

  const formatDate = (dateString: string): string => {
    const date = new Date(dateString);
    return date.toLocaleString('en-IN', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  return (
    <div className="mt-4">
      <button
        onClick={() => setShowHistory(!showHistory)}
        className="text-sm text-amber-600 hover:text-amber-700 font-medium flex items-center gap-2"
      >
        {showHistory ? '▼' : '▶'} View Workflow History
      </button>

      {showHistory && (
        <div className="mt-3 border border-gray-200 rounded-lg bg-gray-50 p-4">
          <h4 className="text-sm font-semibold text-gray-700 mb-3">Document Workflow Timeline</h4>

          {loading && (
            <div className="text-sm text-gray-500">Loading history...</div>
          )}

          {error && (
            <div className="text-sm text-red-600 bg-red-50 p-3 rounded">
              {error}
            </div>
          )}

          {!loading && !error && history.length === 0 && (
            <div className="text-sm text-gray-500 italic">
              No workflow history available yet.
            </div>
          )}

          {!loading && !error && history.length > 0 && (
            <div className="space-y-3">
              {history.map((item, index) => (
                <div
                  key={item.id}
                  className="bg-white border border-gray-200 rounded-lg p-3 relative"
                >
                  {/* Timeline connector */}
                  {index < history.length - 1 && (
                    <div className="absolute left-4 top-12 bottom-0 w-0.5 bg-gray-300" style={{ height: 'calc(100% + 12px)' }} />
                  )}

                  <div className="flex items-start gap-3">
                    {/* Timeline dot */}
                    <div className="flex-shrink-0 w-8 h-8 rounded-full bg-amber-100 flex items-center justify-center text-amber-600 font-bold text-xs relative z-10">
                      {index + 1}
                    </div>

                    <div className="flex-1 min-w-0">
                      {/* Action and time */}
                      <div className="flex items-start justify-between gap-2 mb-1">
                        <span className="text-sm font-semibold text-gray-900">
                          {formatAction(item.action)}
                        </span>
                        <span className="text-xs text-gray-500 whitespace-nowrap">
                          {formatDate(item.created_at)}
                        </span>
                      </div>

                      {/* Actor info */}
                      <div className="text-xs text-gray-600 mb-1">
                        <span className="font-medium">By:</span> {item.actor_name}
                        {item.actor_email && (
                          <span className="text-gray-500"> ({item.actor_email})</span>
                        )}
                      </div>

                      {/* Recipient info (if any) */}
                      {item.recipient_name && (
                        <div className="text-xs text-gray-600 mb-1">
                          <span className="font-medium">To:</span> {item.recipient_name}
                          {item.recipient_email && (
                            <span className="text-gray-500"> ({item.recipient_email})</span>
                          )}
                        </div>
                      )}

                      {/* Status change */}
                      {item.from_status && item.to_status && (
                        <div className="text-xs text-gray-500 mb-1">
                          <span className="font-medium">Status:</span>{' '}
                          <span className="bg-gray-100 px-2 py-0.5 rounded">{item.from_status}</span>
                          {' → '}
                          <span className="bg-green-100 text-green-700 px-2 py-0.5 rounded">{item.to_status}</span>
                        </div>
                      )}

                      {/* Comments */}
                      {item.comments && (
                        <div className="text-xs text-gray-700 bg-gray-50 p-2 rounded mt-2 border-l-2 border-amber-400">
                          <span className="font-medium">Comments:</span> {item.comments}
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

