                  {employeeDocuments.map((d) => (
                    <div key={d.id} className="p-3 flex items-center justify-between">
                      <div className="text-sm">
                        <div className="font-medium">{d.doc_type}</div>
                        <div className="text-gray-600">
                          {d.file_name || 'Attachment'}
