                  type="button"
                  onClick={() => {
                    if (selectedEmployee?.id) {
                      setShowKPICalculator(true);
                    }
                  }}
                  className="px-3 py-1 bg-blue-600 text-white rounded text-sm hover:bg-blue-700"
                >
                  🎯 Calculate KPI & Auto-Generate
                </button>
              </div>
              <div className="border rounded">
                <div className="divide-y">
                  {meritsDemerits.length === 0 && (
                    <div className="p-3 text-sm text-gray-500">No records</div>
                  )}
                  {meritsDemerits.map((r) => (
                    <div key={r.id} className="p-3 flex items-center justify-between">
                      <div className="text-sm">
                        <div className="font-medium">
                          <span className={`px-2 py-0.5 rounded text-xs ${r.record_type === 'DEMERIT' ? 'bg-red-100 text-red-800' : 'bg-green-100 text-green-800'}`}>{r.record_type}</span>
                          <span className="ml-2">{r.title}</span>
                        </div>
                        <div className="text-gray-600">
                          {r.event_date ? new Date(r.event_date).toLocaleDateString() : ''}
                          {typeof r.points === 'number' ? ` • Points: ${r.points}` : ''}
                        </div>
                        {r.description && <div className="text-gray-600 mt-1">{r.description}</div>}
                      </div>
                      <div>
                        <button type="button" onClick={() => handleDeleteMeritDemerit(r.id)} className="px-3 py-1 border rounded hover:bg-gray-50 text-sm text-red-600">Delete</button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <div className="mt-3 grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-sm font-medium mb-1">Type</label>
                  <select value={meritDemeritForm.record_type} onChange={(e) => setMeritDemeritForm({ ...meritDemeritForm, record_type: e.target.value })} className="w-full border rounded px-3 py-2">
                    <option value="MERIT">Merit</option>
                    <option value="DEMERIT">Demerit</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">Event Date</label>
                  <input type="date" value={meritDemeritForm.event_date} onChange={(e) => setMeritDemeritForm({ ...meritDemeritForm, event_date: e.target.value })} className="w-full border rounded px-3 py-2" />
                </div>
                <div className="col-span-2">
                  <label className="block text-sm font-medium mb-1">Title</label>
                  <input type="text" value={meritDemeritForm.title} onChange={(e) => setMeritDemeritForm({ ...meritDemeritForm, title: e.target.value })} className="w-full border rounded px-3 py-2" placeholder="Good performance / Late coming / etc." />
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">Points (optional)</label>
                  <input type="number" value={meritDemeritForm.points} onChange={(e) => setMeritDemeritForm({ ...meritDemeritForm, points: e.target.value })} className="w-full border rounded px-3 py-2" />
                </div>
                <div className="col-span-2">
                  <label className="block text-sm font-medium mb-1">Description (optional)</label>
                  <textarea value={meritDemeritForm.description} onChange={(e) => setMeritDemeritForm({ ...meritDemeritForm, description: e.target.value })} className="w-full border rounded px-3 py-2" rows={2} />
                </div>
                <div className="col-span-2 flex justify-end">
                  <button type="button" onClick={handleAddMeritDemerit} disabled={loading} className="px-4 py-2 bg-amber-600 text-white rounded hover:bg-amber-700 disabled:opacity-50">{loading ? 'Saving...' : 'Add Record'}</button>
                </div>
              </div>
            </div>

            <div className="mt-6 flex justify-end"><button onClick={() => setShowEmployeeDetails(false)} className="px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700">Close</button></div>
          </div>
        </div>
      )}

      {/* Edit Employee Modal */}
      {showEditEmployee && selectedEmployee && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 max-w-2xl w-full mx-4 max-h-[90vh] overflow-y-auto">
            <h3 className="text-lg font-semibold mb-4">Edit Employee</h3>
            <form onSubmit={async (e) => { e.preventDefault(); setLoading(true); setError(''); try { await apiClient.put(`/hr/employees/${selectedEmployee.id}`, employeeForm); setShowEditEmployee(false); fetchData(); alert('Employee updated successfully'); } catch (err: any) { setError(err.message); alert('Failed to update employee'); } finally { setLoading(false); } }} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div><label className="block text-sm font-medium mb-1">Employee Code</label><input type="text" value={employeeForm.employee_code} onChange={(e) => setEmployeeForm({ ...employeeForm, employee_code: e.target.value })} className="w-full border rounded px-3 py-2" required /></div>
                <div><label className="block text-sm font-medium mb-1">Employee Name</label><input type="text" value={employeeForm.employee_name} onChange={(e) => setEmployeeForm({ ...employeeForm, employee_name: e.target.value })} className="w-full border rounded px-3 py-2" required /></div>
                <div><label className="block text-sm font-medium mb-1">Designation</label><input type="text" value={employeeForm.designation} onChange={(e) => setEmployeeForm({ ...employeeForm, designation: e.target.value })} className="w-full border rounded px-3 py-2" /></div>
                <div><label className="block text-sm font-medium mb-1">Department</label><input type="text" value={employeeForm.department} onChange={(e) => setEmployeeForm({ ...employeeForm, department: e.target.value })} className="w-full border rounded px-3 py-2" /></div>
                <div><label className="block text-sm font-medium mb-1">Contact</label><input type="text" value={employeeForm.contact_number} onChange={(e) => setEmployeeForm({ ...employeeForm, contact_number: e.target.value })} className="w-full border rounded px-3 py-2" /></div>
                <div><label className="block text-sm font-medium mb-1">Email</label><input type="email" value={employeeForm.email} onChange={(e) => setEmployeeForm({ ...employeeForm, email: e.target.value })} className="w-full border rounded px-3 py-2" /></div>
              </div>
              <div className="flex justify-end space-x-3 pt-4"><button type="button" onClick={() => setShowEditEmployee(false)} className="px-4 py-2 border rounded hover:bg-gray-50">Cancel</button><button type="submit" disabled={loading} className="px-4 py-2 bg-amber-600 text-white rounded hover:bg-amber-700 disabled:opacity-50">{loading ? 'Updating...' : 'Update Employee'}</button></div>
            </form>
          </div>
        </div>
      )}

      {/* Attendance Details Modal */}
      {showAttendanceDetails && selectedAttendance && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 max-w-2xl w-full mx-4">
            <h3 className="text-lg font-semibold mb-4">Attendance Details</h3>
            <div className="space-y-3 text-sm">
              <div className="grid grid-cols-2 gap-4">
                <div><span className="font-medium">Employee:</span> {selectedAttendance.employee_name}</div>
                <div><span className="font-medium">Date:</span> {new Date(selectedAttendance.attendance_date).toLocaleDateString()}</div>
                <div><span className="font-medium">Check In:</span> {selectedAttendance.check_in_time ? new Date(selectedAttendance.check_in_time).toLocaleTimeString() : 'N/A'}</div>
                <div><span className="font-medium">Check Out:</span> {selectedAttendance.check_out_time ? new Date(selectedAttendance.check_out_time).toLocaleTimeString() : 'N/A'}</div>
                <div><span className="font-medium">Status:</span> <span className={`px-2 py-1 text-xs rounded ${getStatusColor(selectedAttendance.status)}`}>{selectedAttendance.status}</span></div>
              </div>
            </div>
            <div className="mt-6 flex justify-end"><button onClick={() => setShowAttendanceDetails(false)} className="px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700">Close</button></div>
          </div>
        </div>
      )}

      {/* Edit Attendance Modal */}
      {showEditAttendance && selectedAttendance && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 max-w-lg w-full mx-4">
            <h3 className="text-lg font-semibold mb-4">Edit Attendance</h3>
            <form onSubmit={async (e) => { e.preventDefault(); setLoading(true); try { await apiClient.put(`/hr/attendance/${selectedAttendance.id}`, attendanceForm); setShowEditAttendance(false); fetchData(); alert('Attendance updated successfully'); } catch (err: any) { alert('Failed to update attendance'); } finally { setLoading(false); } }} className="space-y-4">
              <div><label className="block text-sm font-medium mb-1">Date</label><input type="date" value={attendanceForm.attendance_date} onChange={(e) => setAttendanceForm({ ...attendanceForm, attendance_date: e.target.value })} className="w-full border rounded px-3 py-2" required /></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="block text-sm font-medium mb-1">Check In</label><input type="time" value={attendanceForm.check_in_time} onChange={(e) => setAttendanceForm({ ...attendanceForm, check_in_time: e.target.value })} className="w-full border rounded px-3 py-2" /></div>
                <div><label className="block text-sm font-medium mb-1">Check Out</label><input type="time" value={attendanceForm.check_out_time} onChange={(e) => setAttendanceForm({ ...attendanceForm, check_out_time: e.target.value })} className="w-full border rounded px-3 py-2" /></div>
              </div>
              <div><label className="block text-sm font-medium mb-1">Status</label><select value={attendanceForm.status} onChange={(e) => setAttendanceForm({ ...attendanceForm, status: e.target.value })} className="w-full border rounded px-3 py-2" required><option value="PRESENT">Present</option><option value="ABSENT">Absent</option><option value="LEAVE">Leave</option><option value="LATE">Late</option><option value="HALF_DAY">Half Day</option><option value="WORK_FROM_HOME">Work From Home</option></select></div>
              <div className="flex justify-end space-x-3 pt-4"><button type="button" onClick={() => setShowEditAttendance(false)} className="px-4 py-2 border rounded hover:bg-gray-50">Cancel</button><button type="submit" disabled={loading} className="px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700 disabled:opacity-50">{loading ? 'Updating...' : 'Update Attendance'}</button></div>
            </form>
          </div>
        </div>
      )}

      {/* Leave Details Modal */}
      {showLeaveDetails && selectedLeave && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 max-w-2xl w-full mx-4">
            <h3 className="text-lg font-semibold mb-4">Leave Request Details</h3>
            <div className="space-y-3 text-sm">
              <div className="grid grid-cols-2 gap-4">
                <div><span className="font-medium">Employee:</span> {selectedLeave.employee_name}</div>
                <div><span className="font-medium">Leave Type:</span> <span className="px-2 py-1 text-xs rounded bg-purple-100 text-purple-800">{selectedLeave.leave_type}</span></div>
                <div><span className="font-medium">Start Date:</span> {new Date(selectedLeave.start_date).toLocaleDateString()}</div>
                <div><span className="font-medium">End Date:</span> {new Date(selectedLeave.end_date).toLocaleDateString()}</div>
                <div><span className="font-medium">Total Days:</span> {selectedLeave.total_days}</div>
                <div><span className="font-medium">Status:</span> <span className={`px-2 py-1 text-xs rounded ${getStatusColor(selectedLeave.status)}`}>{selectedLeave.status}</span></div>
                <div className="col-span-2"><span className="font-medium">Reason:</span> <p className="mt-1 bg-gray-50 p-3 rounded">{selectedLeave.reason}</p></div>
              </div>
            </div>
            <div className="mt-6 flex justify-end gap-2">
              {!isEmployeePortal && canManage && isPendingLeaveStatus(selectedLeave.status) && (
                <>
                  <button
                    onClick={async () => {
                      if (!confirm('Approve this leave request?')) return;
                      await handleApproveLeave(selectedLeave.id);
                      setShowLeaveDetails(false);
                    }}
                    className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700"
                  >
                    Approve
                  </button>
                  <button
                    onClick={async () => {
                      if (!confirm('Reject this leave request?')) return;
                      await handleRejectLeave(selectedLeave.id);
                      setShowLeaveDetails(false);
                    }}
                    className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700"
                  >
                    Reject
                  </button>
                </>
              )}
              <button onClick={() => setShowLeaveDetails(false)} className="px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700">Close</button>
            </div>
          </div>
        </div>
      )}

      {/* Edit Leave Modal */}
      {showEditLeave && selectedLeave && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 max-w-lg w-full mx-4">
            <h3 className="text-lg font-semibold mb-4">Edit Leave Request</h3>
            <form onSubmit={async (e) => { e.preventDefault(); setLoading(true); try { await apiClient.put(`/hr/leaves/${selectedLeave.id}`, leaveForm); setShowEditLeave(false); fetchData(); alert('Leave updated successfully'); } catch (err: any) { alert('Failed to update leave'); } finally { setLoading(false); } }} className="space-y-4">
              <div><label className="block text-sm font-medium mb-1">Leave Type</label><select value={leaveForm.leave_type} onChange={(e) => setLeaveForm({ ...leaveForm, leave_type: e.target.value })} className="w-full border rounded px-3 py-2" required><option value="CASUAL">Casual Leave</option><option value="SICK">Sick Leave</option><option value="EARNED">Earned Leave</option><option value="UNPAID">Unpaid Leave</option><option value="MATERNITY">Maternity Leave</option><option value="PATERNITY">Paternity Leave</option><option value="COMP_OFF">Compensatory Off</option></select></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="block text-sm font-medium mb-1">Start Date</label><input type="date" value={leaveForm.start_date} onChange={(e) => { const newStartDate = e.target.value; const updatedForm = { ...leaveForm, start_date: newStartDate }; if (newStartDate && leaveForm.end_date) { const start = new Date(newStartDate); const end = new Date(leaveForm.end_date); const diffTime = Math.abs(end.getTime() - start.getTime()); const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1; updatedForm.total_days = diffDays; } setLeaveForm(updatedForm); }} className="w-full border rounded px-3 py-2" required /></div>
                <div><label className="block text-sm font-medium mb-1">End Date</label><input type="date" value={leaveForm.end_date} onChange={(e) => { const newEndDate = e.target.value; const updatedForm = { ...leaveForm, end_date: newEndDate }; if (leaveForm.start_date && newEndDate) { const start = new Date(leaveForm.start_date); const end = new Date(newEndDate); const diffTime = Math.abs(end.getTime() - start.getTime()); const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1; updatedForm.total_days = diffDays; } setLeaveForm(updatedForm); }} className="w-full border rounded px-3 py-2" required /></div>
              </div>
              <div><label className="block text-sm font-medium mb-1">Total Days</label><input type="number" value={leaveForm.total_days} onChange={(e) => setLeaveForm({ ...leaveForm, total_days: parseInt(e.target.value) })} className="w-full border rounded px-3 py-2" min="1" required /></div>
              <div><label className="block text-sm font-medium mb-1">Reason</label><textarea value={leaveForm.reason} onChange={(e) => setLeaveForm({ ...leaveForm, reason: e.target.value })} className="w-full border rounded px-3 py-2" rows={3} required /></div>
              <div className="flex justify-end space-x-3 pt-4"><button type="button" onClick={() => setShowEditLeave(false)} className="px-4 py-2 border rounded hover:bg-gray-50">Cancel</button><button type="submit" disabled={loading} className="px-4 py-2 bg-purple-600 text-white rounded hover:bg-purple-700 disabled:opacity-50">{loading ? 'Updating...' : 'Update Leave'}</button></div>
            </form>
          </div>
        </div>
      )}



      {/* Monthly Payroll Form Modal */}
      {showMonthlyPayrollForm && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50 overflow-y-auto">
          <div className="bg-white rounded-lg p-6 max-w-5xl w-full mx-4 my-8 max-h-[90vh] overflow-y-auto">
            <h3 className="text-lg font-semibold mb-4">{selectedMonthlyPayroll ? 'Edit' : 'Process'} Monthly Payroll</h3>
            <form onSubmit={handleSaveMonthlyPayroll} className="space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium mb-1">Employee *</label>
                  <select 
                    value={monthlyPayrollForm.employee_id} 
                    onChange={(e) => handleEmployeeSelectForPayroll(e.target.value)} 
                    className="w-full border rounded px-3 py-2" 
                    required 
                    disabled={!!selectedMonthlyPayroll}
                  >
                    <option value="">Select Employee</option>
                    {employees.map(emp => (<option key={emp.id} value={emp.id}>{emp.employee_name} ({emp.employee_code})</option>))}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">Payroll Month *</label>
                  <input type="month" value={monthlyPayrollForm.payroll_month} onChange={(e) => setMonthlyPayrollForm({ ...monthlyPayrollForm, payroll_month: e.target.value })} className="w-full border rounded px-3 py-2" required />
                </div>
              </div>

              <div className="border-t pt-4">
                <h4 className="font-semibold mb-3 text-amber-600">📅 Attendance & Working Days</h4>
                <div className="grid grid-cols-3 gap-4">
                  <div>
                    <label className="block text-sm font-medium mb-1">Days in Month</label>
                    <input type="number" value={monthlyPayrollForm.days_in_month} onChange={(e) => setMonthlyPayrollForm({ ...monthlyPayrollForm, days_in_month: Number(e.target.value) })} className="w-full border rounded px-3 py-2" min="28" max="31" required />
                  </div>
                  <div>
                    <label className="block text-sm font-medium mb-1">No. of days Travelled</label>
                    <input type="number" value={monthlyPayrollForm.days_travelled} onChange={(e) => setMonthlyPayrollForm({ ...monthlyPayrollForm, days_travelled: Number(e.target.value) })} className="w-full border rounded px-3 py-2" min="0" />
                  </div>
                  <div>
                    <label className="block text-sm font-medium mb-1">Comp-Offs</label>
                    <input type="number" value={monthlyPayrollForm.comp_offs} onChange={(e) => setMonthlyPayrollForm({ ...monthlyPayrollForm, comp_offs: Number(e.target.value) })} className="w-full border rounded px-3 py-2" min="0" step="0.5" />
                  </div>
                  <div>
                    <label className="block text-sm font-medium mb-1">Leave(s) / Absent</label>
                    <input type="number" value={monthlyPayrollForm.leaves_absent} onChange={(e) => setMonthlyPayrollForm({ ...monthlyPayrollForm, leaves_absent: Number(e.target.value) })} className="w-full border rounded px-3 py-2" min="0" />
                  </div>
                  <div>
                    <label className="block text-sm font-medium mb-1">Approved Paid Leaves</label>
                    <input type="number" value={monthlyPayrollForm.approved_paid_leaves} onChange={(e) => setMonthlyPayrollForm({ ...monthlyPayrollForm, approved_paid_leaves: Number(e.target.value) })} className="w-full border rounded px-3 py-2" min="0" />
                  </div>
                  <div>
                    <label className="block text-sm font-medium mb-1 text-green-600">Paid for Total Days *</label>
                    <input type="number" value={monthlyPayrollForm.paid_for_total_days} onChange={(e) => setMonthlyPayrollForm({ ...monthlyPayrollForm, paid_for_total_days: Number(e.target.value) })} className="w-full border rounded px-3 py-2 font-semibold" min="0" step="0.5" required />
                  </div>
                </div>
              </div>

              <div className="border-t pt-4">
                <h4 className="font-semibold mb-3 text-green-600">💰 Variable Salary Components</h4>
                <div className="grid grid-cols-2 gap-4">
                  <div className="border-l-4 border-green-400 pl-3">
                    <label className="block text-sm font-medium mb-1">Bonus Monthly</label>
                    <input type="number" value={monthlyPayrollForm.bonus_monthly} onChange={(e) => setMonthlyPayrollForm({ ...monthlyPayrollForm, bonus_monthly: Number(e.target.value) })} className="w-full border rounded px-3 py-2" min="0" step="0.01" />
                    <p className="text-xs text-gray-500 mt-1">Monthly bonus (included in gross)</p>
                  </div>
                  <div className="border-l-4 border-green-400 pl-3">
                    <label className="block text-sm font-medium mb-1">Production Incentive Monthly</label>
                    <input type="number" value={monthlyPayrollForm.production_incentive} onChange={(e) => setMonthlyPayrollForm({ ...monthlyPayrollForm, production_incentive: Number(e.target.value) })} className="w-full border rounded px-3 py-2" min="0" step="0.01" />
                    <p className="text-xs text-gray-500 mt-1">Production bonus (included in gross)</p>
                  </div>
                  <div className="border-l-4 border-amber-400 pl-3">
                    <label className="block text-sm font-medium mb-1 text-amber-700">Bonus Monthly (On Hold)</label>
                    <input type="number" value={monthlyPayrollForm.bonus_hold} onChange={(e) => setMonthlyPayrollForm({ ...monthlyPayrollForm, bonus_hold: Number(e.target.value) })} className="w-full border rounded px-3 py-2" min="0" step="0.01" />
                    <p className="text-xs text-amber-600 mt-1">Calculated but held, not paid now</p>
                  </div>
                  <div className="border-l-4 border-amber-400 pl-3">
                    <label className="block text-sm font-medium mb-1 text-amber-700">Production Incentive (On Hold)</label>
                    <input type="number" value={monthlyPayrollForm.production_incentive_hold} onChange={(e) => setMonthlyPayrollForm({ ...monthlyPayrollForm, production_incentive_hold: Number(e.target.value) })} className="w-full border rounded px-3 py-2" min="0" step="0.01" />
                    <p className="text-xs text-amber-600 mt-1">Calculated but held, not paid now</p>
                  </div>
                  <div>
                    <label className="block text-sm font-medium mb-1">Monthly Special Allowance</label>
                    <input type="number" value={monthlyPayrollForm.special_allowance} onChange={(e) => setMonthlyPayrollForm({ ...monthlyPayrollForm, special_allowance: Number(e.target.value) })} className="w-full border rounded px-3 py-2" min="0" step="0.01" />
                    <p className="text-xs text-gray-500 mt-1">Additional allowance (balancing figure)</p>
                  </div>
                  <div>
                    <label className="block text-sm font-medium mb-1">Professional Tax (Deduction)</label>
                    <input type="number" value={monthlyPayrollForm.professional_tax} onChange={(e) => setMonthlyPayrollForm({ ...monthlyPayrollForm, professional_tax: Number(e.target.value) })} className="w-full border rounded px-3 py-2" min="0" step="0.01" />
                    <p className="text-xs text-gray-500 mt-1">Statutory deduction</p>
                  </div>
                </div>
              </div>

              <div className="bg-blue-50 border border-blue-200 rounded p-4">
                <div className="grid grid-cols-2 gap-3 text-sm">
                  <div><strong>Calculation Formula (as per salary slip):</strong></div>
                  <div></div>
                  <div className="text-gray-700">1. Gross Monthly Salary =</div>
                  <div className="text-gray-700">Fixed Components + Bonus Monthly + Production Incentive + Special Allowance</div>
                  <div className="text-gray-700">2. Net Salary =</div>
                  <div className="text-gray-700">Gross Salary - Professional Tax</div>
                  <div className="text-amber-700 font-medium">3. Monthly Hold =</div>
                  <div className="text-amber-700 font-medium">Bonus Monthly (On Hold) + Production Incentive (On Hold)</div>
                  <div className="font-bold text-green-700">4. Amount Paid =</div>
                  <div className="font-bold text-green-700">Net Salary - Monthly Hold</div>
                </div>
              </div>

              <div className="flex justify-end space-x-3 pt-4">
                <button type="button" onClick={() => { setShowMonthlyPayrollForm(false); setSelectedMonthlyPayroll(null); }} className="px-4 py-2 border rounded hover:bg-gray-50">Cancel</button>
                <button type="submit" disabled={loading} className="px-4 py-2 bg-amber-600 text-white rounded hover:bg-amber-700 disabled:opacity-50">{loading ? 'Saving...' : (selectedMonthlyPayroll ? 'Update' : 'Save as Draft')}</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Create Payroll Run Modal */}
      {showPayrollRunForm && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 max-w-lg w-full mx-4">
            <h3 className="text-lg font-semibold mb-4">Create Payroll Run</h3>
            <form onSubmit={handleCreatePayrollRun} className="space-y-4">
              <div><label className="block text-sm font-medium mb-1">Payroll Month</label><input type="month" value={payrollRunForm.payroll_month} onChange={(e) => setPayrollRunForm({ ...payrollRunForm, payroll_month: e.target.value })} className="w-full border rounded px-3 py-2" required /></div>
              <div><label className="block text-sm font-medium mb-1">Remarks (Optional)</label><textarea value={payrollRunForm.remarks} onChange={(e) => setPayrollRunForm({ ...payrollRunForm, remarks: e.target.value })} className="w-full border rounded px-3 py-2" rows={3} placeholder="Any notes about this payroll run..." /></div>
              <div className="bg-blue-50 border border-blue-200 rounded p-3 text-sm text-blue-800"><strong>Note:</strong> This will create a payroll run for the selected month. You can generate payslips after creating the run.</div>
              <div className="flex justify-end space-x-3 pt-4"><button type="button" onClick={() => setShowPayrollRunForm(false)} className="px-4 py-2 border rounded hover:bg-gray-50">Cancel</button><button type="submit" disabled={loading} className="px-4 py-2 bg-amber-600 text-white rounded hover:bg-amber-700 disabled:opacity-50">{loading ? 'Creating...' : 'Create Run'}</button></div>
            </form>
          </div>
        </div>
      )}

      {/* Comprehensive Salary Setup Modal */}
      {showComprehensiveSalaryForm && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50 overflow-y-auto">
          <div className="bg-white rounded-lg p-6 max-w-4xl w-full mx-4 my-8 max-h-[90vh] overflow-y-auto">
            <h3 className="text-lg font-semibold mb-4">🎯 Comprehensive Salary Setup</h3>
            <p className="text-sm text-gray-600 mb-4">Enter all salary components for an employee in one form. All existing components will be replaced.</p>
            
            <form onSubmit={handleSaveComprehensiveSalary} className="space-y-6">
              {/* Region Selector */}
              <div className="bg-gradient-to-r from-blue-50 to-purple-50 border border-blue-200 rounded-lg p-4">
                <label className="block text-sm font-semibold mb-2">🌍 Compliance Region</label>
                <div className="flex space-x-4">
                  <label className="flex items-center space-x-2 cursor-pointer">
                    <input 
                      type="radio" 
                      value="INDIA" 
                      checked={complianceRegion === 'INDIA'} 
                      onChange={(e) => setComplianceRegion(e.target.value as 'INDIA' | 'UAE')}
                      className="w-4 h-4"
                    />
                    <span className="font-medium">🇮🇳 India (PF, ESI, PT, TDS)</span>
                  </label>
                  <label className="flex items-center space-x-2 cursor-pointer">
                    <input 
                      type="radio" 
                      value="UAE" 
                      checked={complianceRegion === 'UAE'} 
                      onChange={(e) => setComplianceRegion(e.target.value as 'INDIA' | 'UAE')}
                      className="w-4 h-4"
                    />
                    <span className="font-medium">🇦🇪 UAE (WPS, Gratuity, ESB)</span>
                  </label>
                </div>
                {complianceRegion === 'INDIA' && (
                  <div className="mt-3">
                    <label className="block text-xs font-medium mb-1">State (for Professional Tax)</label>
                    <select 
                      value={complianceState} 
                      onChange={(e) => setComplianceState(e.target.value)}
                      className="border rounded px-2 py-1 text-sm"
                    >
                      <option value="MH">Maharashtra</option>
                      <option value="KA">Karnataka</option>
                      <option value="WB">West Bengal</option>
                      <option value="TN">Tamil Nadu</option>
                      <option value="GJ">Gujarat</option>
                      <option value="AP">Andhra Pradesh</option>
                      <option value="TS">Telangana</option>
                      <option value="DL">Delhi (No PT)</option>
                    </select>
                  </div>
                )}
              </div>
              
              <div>
                <label className="block text-sm font-medium mb-1">Select Employee *</label>
                <select 
                  value={comprehensiveSalaryForm.employee_id} 
                  onChange={(e) => setComprehensiveSalaryForm({ ...comprehensiveSalaryForm, employee_id: e.target.value })} 
                  className="w-full border rounded px-3 py-2"
                  required
                >
                  <option value="">Choose Employee</option>
                  {employees.map(emp => (
                    <option key={emp.id} value={emp.id}>{emp.employee_name} ({emp.employee_code})</option>
                  ))}
                </select>
              </div>

              <div className="border-t pt-4">
                <h4 className="font-semibold mb-3 text-green-600">💰 Fixed Components (Monthly)</h4>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium mb-1">Basic Salary *</label>
                    <input 
                      type="number" 
                      value={comprehensiveSalaryForm.basic_salary} 
                      onChange={(e) => handleBasicSalaryChange(Number(e.target.value))} 
                      className="w-full border rounded px-3 py-2" 
                      min="0" 
                      step="0.01"
                      required
                    />
                    <p className="text-xs text-gray-500 mt-1">Auto-calculates HRA, PF, ESI, PT</p>
                  </div>
                  <div>
                    <label className="block text-sm font-medium mb-1">HRA (House Rent Allowance)</label>
                    <input 
                      type="number" 
                      value={comprehensiveSalaryForm.hra} 
                      onChange={(e) => setComprehensiveSalaryForm({ ...comprehensiveSalaryForm, hra: Number(e.target.value) })} 
                      className="w-full border rounded px-3 py-2" 
                      min="0" 
                      step="0.01"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium mb-1">Medical Allowance</label>
                    <input 
                      type="number" 
                      value={comprehensiveSalaryForm.medical_allowance} 
                      onChange={(e) => setComprehensiveSalaryForm({ ...comprehensiveSalaryForm, medical_allowance: Number(e.target.value) })} 
                      className="w-full border rounded px-3 py-2" 
                      min="0" 
                      step="0.01"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium mb-1">Travelling Allowance</label>
                    <input 
                      type="number" 
                      value={comprehensiveSalaryForm.travelling_allowance} 
                      onChange={(e) => setComprehensiveSalaryForm({ ...comprehensiveSalaryForm, travelling_allowance: Number(e.target.value) })} 
                      className="w-full border rounded px-3 py-2" 
                      min="0" 
                      step="0.01"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium mb-1">Special Allowance</label>
                    <input 
                      type="number" 
                      value={comprehensiveSalaryForm.special_allowance} 
                      onChange={(e) => setComprehensiveSalaryForm({ ...comprehensiveSalaryForm, special_allowance: Number(e.target.value) })} 
                      className="w-full border rounded px-3 py-2" 
                      min="0" 
                      step="0.01"
                    />
                  </div>
                </div>
              </div>

              <div className="border-t pt-4">
                <h4 className="font-semibold mb-3 text-red-600">➖ Deductions {complianceRegion === 'INDIA' && '(Auto-calculated)'}</h4>
                {complianceRegion === 'INDIA' && (
                  <div className="bg-green-50 border border-green-200 rounded p-3 mb-4 text-sm">
                    <p className="font-semibold text-green-700 mb-1">✓ Statutory Compliance (India)</p>
                    <ul className="space-y-1 text-green-600">
                      <li>• PF: ₹{comprehensiveSalaryForm.pf_deduction.toFixed(2)} (12% of Basic)</li>
                      <li>• ESI: ₹{comprehensiveSalaryForm.esi_deduction.toFixed(2)} (0.75% if gross ≤ ₹21,000)</li>
                      <li>• PT: ₹{comprehensiveSalaryForm.professional_tax.toFixed(2)} ({complianceState} state slab)</li>
                    </ul>
                  </div>
                )}
                {complianceRegion === 'UAE' && (
                  <div className="bg-blue-50 border border-blue-200 rounded p-3 mb-4 text-sm">
                    <p className="font-semibold text-blue-700">ℹ️ UAE - No PF/ESI/PT required</p>
                    <p className="text-blue-600 text-xs">End of Service Benefits & WPS compliance handled separately</p>
                  </div>
                )}
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium mb-1">PF (Provident Fund)</label>
                    <input 
                      type="number" 
                      value={comprehensiveSalaryForm.pf_deduction} 
                      onChange={(e) => setComprehensiveSalaryForm({ ...comprehensiveSalaryForm, pf_deduction: Number(e.target.value) })} 
                      className="w-full border rounded px-3 py-2 bg-gray-50" 
                      min="0" 
                      step="0.01"
                      readOnly={complianceRegion === 'INDIA'}
                    />
                    <p className="text-xs text-gray-500 mt-1">{complianceRegion === 'INDIA' ? 'Auto: 12% of Basic' : 'Manual entry'}</p>
                  </div>
                  <div>
                    <label className="block text-sm font-medium mb-1">ESI</label>
                    <input 
                      type="number" 
                      value={comprehensiveSalaryForm.esi_deduction} 
                      onChange={(e) => setComprehensiveSalaryForm({ ...comprehensiveSalaryForm, esi_deduction: Number(e.target.value) })} 
                      className="w-full border rounded px-3 py-2 bg-gray-50" 
                      min="0" 
                      step="0.01"
                      readOnly={complianceRegion === 'INDIA'}
                    />
                    <p className="text-xs text-gray-500 mt-1">{complianceRegion === 'INDIA' ? 'Auto: 0.75% if gross ≤ ₹21k' : 'Manual entry'}</p>
                  </div>
                  <div>
                    <label className="block text-sm font-medium mb-1">Professional Tax</label>
                    <input 
                      type="number" 
                      value={comprehensiveSalaryForm.professional_tax} 
                      onChange={(e) => setComprehensiveSalaryForm({ ...comprehensiveSalaryForm, professional_tax: Number(e.target.value) })} 
                      className="w-full border rounded px-3 py-2 bg-gray-50" 
                      min="0" 
                      step="0.01"
                      readOnly={complianceRegion === 'INDIA'}
                    />
                    <p className="text-xs text-gray-500 mt-1">{complianceRegion === 'INDIA' ? `Auto: ${complianceState} state slab` : 'Manual entry'}</p>
                  </div>
                </div>
              </div>

              <div className="border-t pt-4">
                <h4 className="font-semibold mb-3 text-blue-600">➕ Other Allowances (Optional)</h4>
                {comprehensiveSalaryForm.other_allowances.map((allowance, index) => (
                  <div key={index} className="grid grid-cols-12 gap-2 mb-2">
                    <input 
                      type="text" 
                      placeholder="Allowance Name" 
                      value={allowance.name}
                      onChange={(e) => {
                        const updated = [...comprehensiveSalaryForm.other_allowances];
                        updated[index].name = e.target.value;
                        setComprehensiveSalaryForm({ ...comprehensiveSalaryForm, other_allowances: updated });
                      }}
                      className="col-span-5 border rounded px-3 py-2"
                    />
                    <input 
                      type="number" 
                      placeholder="Amount" 
                      value={allowance.amount}
                      onChange={(e) => {
                        const updated = [...comprehensiveSalaryForm.other_allowances];
                        updated[index].amount = Number(e.target.value);
                        setComprehensiveSalaryForm({ ...comprehensiveSalaryForm, other_allowances: updated });
                      }}
                      className="col-span-4 border rounded px-3 py-2"
                      min="0"
                      step="0.01"
                    />
                    <label className="col-span-2 flex items-center text-sm">
                      <input 
                        type="checkbox" 
                        checked={allowance.is_taxable}
                        onChange={(e) => {
                          const updated = [...comprehensiveSalaryForm.other_allowances];
                          updated[index].is_taxable = e.target.checked;
                          setComprehensiveSalaryForm({ ...comprehensiveSalaryForm, other_allowances: updated });
                        }}
                        className="mr-1"
                      />
                      Taxable
                    </label>
                    <button 
                      type="button"
                      onClick={() => {
                        const updated = comprehensiveSalaryForm.other_allowances.filter((_, i) => i !== index);
                        setComprehensiveSalaryForm({ ...comprehensiveSalaryForm, other_allowances: updated });
                      }}
                      className="col-span-1 text-red-600 hover:text-red-800"
                    >
                      ✕
                    </button>
                  </div>
                ))}
                <button 
                  type="button"
                  onClick={() => {
                    setComprehensiveSalaryForm({
                      ...comprehensiveSalaryForm,
                      other_allowances: [...comprehensiveSalaryForm.other_allowances, { name: '', amount: 0, is_taxable: true }]
                    });
                  }}
                  className="text-sm text-blue-600 hover:text-blue-800"
                >
                  + Add Another Allowance
                </button>
              </div>

              <div className="border-t pt-4">
                <h4 className="font-semibold mb-3 text-red-600">➖ Other Deductions (Optional)</h4>
                {comprehensiveSalaryForm.other_deductions.map((deduction, index) => (
                  <div key={index} className="grid grid-cols-12 gap-2 mb-2">
                    <input 
                      type="text" 
                      placeholder="Deduction Name" 
                      value={deduction.name}
                      onChange={(e) => {
                        const updated = [...comprehensiveSalaryForm.other_deductions];
                        updated[index].name = e.target.value;
                        setComprehensiveSalaryForm({ ...comprehensiveSalaryForm, other_deductions: updated });
                      }}
                      className="col-span-7 border rounded px-3 py-2"
                    />
                    <input 
                      type="number" 
                      placeholder="Amount" 
                      value={deduction.amount}
                      onChange={(e) => {
                        const updated = [...comprehensiveSalaryForm.other_deductions];
                        updated[index].amount = Number(e.target.value);
                        setComprehensiveSalaryForm({ ...comprehensiveSalaryForm, other_deductions: updated });
                      }}
                      className="col-span-4 border rounded px-3 py-2"
                      min="0"
                      step="0.01"
                    />
                    <button 
                      type="button"
                      onClick={() => {
                        const updated = comprehensiveSalaryForm.other_deductions.filter((_, i) => i !== index);
                        setComprehensiveSalaryForm({ ...comprehensiveSalaryForm, other_deductions: updated });
                      }}
                      className="col-span-1 text-red-600 hover:text-red-800"
                    >
                      ✕
                    </button>
                  </div>
                ))}
                <button 
                  type="button"
                  onClick={() => {
                    setComprehensiveSalaryForm({
                      ...comprehensiveSalaryForm,
                      other_deductions: [...comprehensiveSalaryForm.other_deductions, { name: '', amount: 0 }]
                    });
                  }}
                  className="text-sm text-red-600 hover:text-red-800"
                >
                  + Add Another Deduction
                </button>
              </div>

              <div className="bg-green-50 border border-green-200 rounded p-4">
                <p className="text-sm text-green-800">
                  <strong>💡 This form will save all components at once.</strong> All existing salary components for this employee will be replaced with the new entries.
                </p>
              </div>

              <div className="flex justify-end space-x-3 pt-4">
                <button 
                  type="button" 
                  onClick={() => {
                    setShowComprehensiveSalaryForm(false);
                    setComprehensiveSalaryForm({
                      employee_id: '',
                      basic_salary: 0,
                      hra: 0,
                      medical_allowance: 0,
                      travelling_allowance: 0,
                      special_allowance: 0,
                      pf_deduction: 0,
                      esi_deduction: 0,
                      professional_tax: 200,
                      other_allowances: [],
                      other_deductions: []
                    });
                  }} 
                  className="px-4 py-2 border rounded hover:bg-gray-50"
                >
                  Cancel
                </button>
                <button 
                  type="submit" 
                  disabled={loading} 
                  className="px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700 disabled:opacity-50 font-medium"
                >
                  {loading ? 'Saving...' : '💾 Save All Components'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* KPI Calculator Modal */}
      {showKPICalculator && selectedEmployee && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 max-w-3xl w-full mx-4 max-h-[90vh] overflow-y-auto">
            <h3 className="text-lg font-semibold mb-4">🎯 KPI Calculator & Merit/Demerit Generator</h3>
            <p className="text-sm text-gray-600 mb-4">
              Employee: <strong>{selectedEmployee.employee_name}</strong> ({selectedEmployee.employee_code})
            </p>

            <div className="mb-4">
              <label className="block text-sm font-medium mb-1">Select Month</label>
              <input 
                type="month" 
                defaultValue={new Date().toISOString().substring(0, 7)}
                onChange={async (e) => {
                  if (selectedEmployee?.id) {
                    await calculateKPIMetrics(selectedEmployee.id, e.target.value);
                  }
                }}
                className="w-full border rounded px-3 py-2"
              />
            </div>

            {kpiMetrics && (
              <div className="space-y-4">
                <div className="bg-blue-50 border border-blue-200 rounded p-4">
                  <h4 className="font-semibold mb-3 text-blue-800">📊 KPI Metrics</h4>
                  <div className="grid grid-cols-2 gap-4 text-sm">
                    <div>
                      <div className="font-medium">Attendance Rate</div>
                      <div className={`text-2xl font-bold ${kpiMetrics.attendance_rate >= 95 ? 'text-green-600' : kpiMetrics.attendance_rate >= 85 ? 'text-amber-600' : 'text-red-600'}`}>
                        {kpiMetrics.attendance_rate.toFixed(1)}%
                      </div>
                    </div>
                    <div>
                      <div className="font-medium">Punctuality Score</div>
                      <div className={`text-2xl font-bold ${kpiMetrics.punctuality_score >= 95 ? 'text-green-600' : kpiMetrics.punctuality_score >= 85 ? 'text-amber-600' : 'text-red-600'}`}>
                        {kpiMetrics.punctuality_score.toFixed(1)}%
                      </div>
                    </div>
                    <div>
                      <div className="font-medium">Late Arrivals</div>
                      <div className={`text-2xl font-bold ${kpiMetrics.late_count <= 2 ? 'text-green-600' : kpiMetrics.late_count <= 5 ? 'text-amber-600' : 'text-red-600'}`}>
                        {kpiMetrics.late_count}
                      </div>
                    </div>
                    <div>
                      <div className="font-medium">Absences</div>
                      <div className={`text-2xl font-bold ${kpiMetrics.absent_count === 0 ? 'text-green-600' : kpiMetrics.absent_count <= 2 ? 'text-amber-600' : 'text-red-600'}`}>
                        {kpiMetrics.absent_count}
                      </div>
                    </div>
                    <div>
                      <div className="font-medium">Leave Days</div>
                      <div className="text-2xl font-bold text-blue-600">
                        {kpiMetrics.leave_utilization}
                      </div>
                    </div>
                    <div>
                      <div className="font-medium">Overtime Hours</div>
                      <div className="text-2xl font-bold text-purple-600">
                        {kpiMetrics.overtime_hours}
                      </div>
                    </div>
                  </div>
                </div>

                <div className="bg-green-50 border border-green-200 rounded p-4">
                  <h4 className="font-semibold mb-2 text-green-800">✅ Merit Criteria (Auto-Applied)</h4>
                  <ul className="text-sm space-y-1">
                    <li>• Attendance Rate ≥ 98% → <strong>Excellent Attendance</strong> (+10 points)</li>
                    <li>• Punctuality ≥ 95% → <strong>Excellent Punctuality</strong> (+8 points)</li>
                    <li>• Leave Days ≤ 2 → <strong>Responsible Leave Management</strong> (+5 points)</li>
                  </ul>
                </div>

                <div className="bg-red-50 border border-red-200 rounded p-4">
                  <h4 className="font-semibold mb-2 text-red-800">❌ Demerit Criteria (Auto-Applied)</h4>
                  <ul className="text-sm space-y-1">
                    <li>• Attendance Rate &lt; 85% → <strong>Poor Attendance</strong> (-5 points)</li>
                    <li>• Late Arrivals ≥ 5 → <strong>Frequent Tardiness</strong> (-3 points)</li>
                    <li>• Absences ≥ 3 → <strong>Excessive Absences</strong> (-5 points)</li>
                  </ul>
                </div>

                <div className="bg-amber-50 border border-amber-200 rounded p-4 text-sm text-amber-800">
                  <strong>ℹ️ Note:</strong> Merit/demerit records have already been auto-generated based on the KPI analysis above. Check the Merits & Demerits section to review.
                </div>

                {/* Manual KPI Entry Section */}
                <div className="bg-purple-50 border border-purple-200 rounded p-4">
                  <h4 className="font-semibold mb-3 text-purple-800">✏️ Manual Performance Metrics (Optional)</h4>
                  <p className="text-sm text-purple-700 mb-3">Enter subjective performance ratings that can&apos;t be auto-calculated (0-100 scale):</p>
                  
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium mb-1">Quality of Work</label>
                      <input 
                        type="number" 
                        value={manualKPIs.quality_of_work} 
                        onChange={(e) => setManualKPIs({ ...manualKPIs, quality_of_work: Number(e.target.value) })}
                        className="w-full border rounded px-3 py-2"
                        min="0"
                        max="100"
                        placeholder="0-100"
                      />
                      <p className="text-xs text-gray-500 mt-1">≥90: Outstanding (+15pts), &lt;60: Poor (-10pts)</p>
                    </div>
                    
                    <div>
                      <label className="block text-sm font-medium mb-1">Productivity Score</label>
                      <input 
                        type="number" 
                        value={manualKPIs.productivity_score} 
                        onChange={(e) => setManualKPIs({ ...manualKPIs, productivity_score: Number(e.target.value) })}
                        className="w-full border rounded px-3 py-2"
                        min="0"
                        max="100"
                        placeholder="0-100"
                      />
                      <p className="text-xs text-gray-500 mt-1">≥90: Excellent (+12pts), &lt;60: Low (-8pts)</p>
                    </div>
                    
                    <div>
                      <label className="block text-sm font-medium mb-1">Teamwork Rating</label>
                      <input 
                        type="number" 
                        value={manualKPIs.teamwork_rating} 
                        onChange={(e) => setManualKPIs({ ...manualKPIs, teamwork_rating: Number(e.target.value) })}
                        className="w-full border rounded px-3 py-2"
                        min="0"
                        max="100"
                        placeholder="0-100"
                      />
                      <p className="text-xs text-gray-500 mt-1">≥85: Great Team Player (+10pts)</p>
                    </div>
                    
                    <div>
                      <label className="block text-sm font-medium mb-1">Customer Satisfaction</label>
                      <input 
                        type="number" 
                        value={manualKPIs.customer_satisfaction} 
                        onChange={(e) => setManualKPIs({ ...manualKPIs, customer_satisfaction: Number(e.target.value) })}
                        className="w-full border rounded px-3 py-2"
                        min="0"
                        max="100"
                        placeholder="0-100"
                      />
                      <p className="text-xs text-gray-500 mt-1">≥90: Excellent (+12pts)</p>
                    </div>
                    
                    <div>
                      <label className="block text-sm font-medium mb-1">Project Completion Rate</label>
                      <input 
                        type="number" 
                        value={manualKPIs.project_completion_rate} 
                        onChange={(e) => setManualKPIs({ ...manualKPIs, project_completion_rate: Number(e.target.value) })}
                        className="w-full border rounded px-3 py-2"
                        min="0"
                        max="100"
                        placeholder="0-100"
                      />
                      <p className="text-xs text-gray-500 mt-1">≥95: Outstanding Delivery (+15pts)</p>
                    </div>
                    
                    <div>
                      <label className="block text-sm font-medium mb-1">Initiative & Innovation</label>
                      <input 
                        type="number" 
                        value={manualKPIs.initiative_innovation} 
                        onChange={(e) => setManualKPIs({ ...manualKPIs, initiative_innovation: Number(e.target.value) })}
                        className="w-full border rounded px-3 py-2"
                        min="0"
                        max="100"
                        placeholder="0-100"
                      />
                      <p className="text-xs text-gray-500 mt-1">≥80: Innovation & Initiative (+10pts)</p>
                    </div>
                  </div>
                  
                  <div className="mt-3">
                    <label className="block text-sm font-medium mb-1">Performance Notes (Optional)</label>
                    <textarea 
                      value={manualKPIs.manual_notes} 
                      onChange={(e) => setManualKPIs({ ...manualKPIs, manual_notes: e.target.value })}
                      className="w-full border rounded px-3 py-2"
                      rows={2}
                      placeholder="Additional comments about performance..."
                    />
                  </div>
                  
                  <div className="mt-4">
                    <button 
                      type="button"
                      onClick={handleSaveManualKPIs}
                      disabled={loading}
                      className="w-full px-4 py-2 bg-purple-600 text-white rounded hover:bg-purple-700 disabled:opacity-50 font-medium"
                    >
                      {loading ? 'Saving...' : '💾 Save Manual KPIs & Generate Merit/Demerit'}
                    </button>
                  </div>
                </div>
              </div>
            )}

            {!kpiMetrics && !loading && (
              <div className="text-center py-8 text-gray-500">
                <p>Select a month above to calculate auto KPIs first</p>
                <p className="text-xs mt-2">Then you can add manual performance metrics</p>
              </div>
            )}

            {loading && (
              <div className="text-center py-8">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
                <p className="mt-4 text-gray-600">Analyzing KPIs...</p>
              </div>
            )}

            <div className="mt-6 flex justify-end">
              <button 
                onClick={() => {
                  setShowKPICalculator(false);
                  setKpiMetrics(null);
                }}
                className="px-4 py-2 bg-gray-600 text-white rounded hover:bg-gray-700"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* KPI Definition Form Modal */}
      {showKpiForm && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 max-w-2xl w-full mx-4 max-h-[90vh] overflow-y-auto">
            <h3 className="text-xl font-semibold mb-4">{editingKpi ? 'Edit' : 'Add'} KPI Definition</h3>
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium mb-1">KPI Name *</label>
                  <input type="text" value={kpiForm.kpi_name} onChange={(e) => setKpiForm({ ...kpiForm, kpi_name: e.target.value })} className="w-full border rounded px-3 py-2" required />
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">Category *</label>
                  <select value={kpiForm.kpi_category} onChange={(e) => setKpiForm({ ...kpiForm, kpi_category: e.target.value })} className="w-full border rounded px-3 py-2">
                    <option value="ATTENDANCE">Attendance</option>
                    <option value="QUALITY">Quality</option>
                    <option value="PRODUCTIVITY">Productivity</option>
                    <option value="BEHAVIOR">Behavior</option>
                    <option value="CUSTOM">Custom</option>
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Description</label>
                <textarea value={kpiForm.description} onChange={(e) => setKpiForm({ ...kpiForm, description: e.target.value })} className="w-full border rounded px-3 py-2" rows={2} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium mb-1">Measurement Type *</label>
                  <select value={kpiForm.measurement_type} onChange={(e) => setKpiForm({ ...kpiForm, measurement_type: e.target.value })} className="w-full border rounded px-3 py-2">
                    <option value="PERCENTAGE">Percentage</option>
                    <option value="NUMBER">Number</option>
                    <option value="SCORE">Score</option>
                    <option value="COUNT">Count</option>
                  </select>
                </div>
                <div className="flex items-center gap-2 pt-6">
                  <input type="checkbox" checked={kpiForm.auto_calculate} onChange={(e) => setKpiForm({ ...kpiForm, auto_calculate: e.target.checked })} />
                  <label className="text-sm">Auto Calculate</label>
                  <input type="checkbox" checked={kpiForm.is_active} onChange={(e) => setKpiForm({ ...kpiForm, is_active: e.target.checked })} />
                  <label className="text-sm">Active</label>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium mb-1">Min Value</label>
                  <input type="number" value={kpiForm.min_value} onChange={(e) => setKpiForm({ ...kpiForm, min_value: Number(e.target.value) })} className="w-full border rounded px-3 py-2" />
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">Max Value</label>
                  <input type="number" value={kpiForm.max_value} onChange={(e) => setKpiForm({ ...kpiForm, max_value: Number(e.target.value) })} className="w-full border rounded px-3 py-2" />
                </div>
              </div>
              <div className="grid grid-cols-3 gap-4">
                <div>
                  <label className="block text-sm font-medium mb-1">Threshold Excellent</label>
                  <input type="number" value={kpiForm.threshold_excellent} onChange={(e) => setKpiForm({ ...kpiForm, threshold_excellent: Number(e.target.value) })} className="w-full border rounded px-3 py-2" />
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">Threshold Good</label>
                  <input type="number" value={kpiForm.threshold_good} onChange={(e) => setKpiForm({ ...kpiForm, threshold_good: Number(e.target.value) })} className="w-full border rounded px-3 py-2" />
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">Threshold Acceptable</label>
                  <input type="number" value={kpiForm.threshold_acceptable} onChange={(e) => setKpiForm({ ...kpiForm, threshold_acceptable: Number(e.target.value) })} className="w-full border rounded px-3 py-2" />
                </div>
              </div>
            </div>
            <div className="flex gap-3 mt-6">
              <button onClick={() => setShowKpiForm(false)} className="flex-1 px-4 py-2 border rounded hover:bg-gray-50">Cancel</button>
              <button onClick={async () => { try { if(editingKpi) { await apiClient.put(`/hr/kpi-definitions/${editingKpi.id}`, kpiForm); } else { await apiClient.post('/hr/kpi-definitions', kpiForm); } await fetchMasterConfig(); setShowKpiForm(false); } catch(e) { alert('Failed to save KPI'); }}} className="flex-1 px-4 py-2 bg-amber-600 text-white rounded hover:bg-amber-700">Save</button>
            </div>
          </div>
        </div>
      )}

      {/* Merit/Demerit Type Form Modal */}
      {showMeritTypeForm && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 max-w-2xl w-full mx-4 max-h-[90vh] overflow-y-auto">
            <h3 className="text-xl font-semibold mb-4">{editingMeritType ? 'Edit' : 'Add'} Merit/Demerit Type</h3>
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium mb-1">Type Name *</label>
                  <input type="text" value={meritTypeForm.type_name} onChange={(e) => setMeritTypeForm({ ...meritTypeForm, type_name: e.target.value })} className="w-full border rounded px-3 py-2" required />
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">Record Type *</label>
                  <select value={meritTypeForm.record_type} onChange={(e) => setMeritTypeForm({ ...meritTypeForm, record_type: e.target.value })} className="w-full border rounded px-3 py-2">
                    <option value="MERIT">Merit</option>
                    <option value="DEMERIT">Demerit</option>
                  </select>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium mb-1">Category *</label>
                  <select value={meritTypeForm.category} onChange={(e) => setMeritTypeForm({ ...meritTypeForm, category: e.target.value })} className="w-full border rounded px-3 py-2">
                    <option value="ATTENDANCE">Attendance</option>
                    <option value="QUALITY">Quality</option>
                    <option value="BEHAVIOR">Behavior</option>
                    <option value="SAFETY">Safety</option>
                    <option value="PRODUCTIVITY">Productivity</option>
                    <option value="CUSTOM">Custom</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">Default Points *</label>
                  <input type="number" value={meritTypeForm.default_points} onChange={(e) => setMeritTypeForm({ ...meritTypeForm, default_points: Number(e.target.value) })} className="w-full border rounded px-3 py-2" required />
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Description</label>
                <textarea value={meritTypeForm.description} onChange={(e) => setMeritTypeForm({ ...meritTypeForm, description: e.target.value })} className="w-full border rounded px-3 py-2" rows={2} />
              </div>
              {meritTypeForm.record_type === 'DEMERIT' && (
                <div>
                  <label className="block text-sm font-medium mb-1">Severity (for demerits)</label>
                  <select value={meritTypeForm.severity} onChange={(e) => setMeritTypeForm({ ...meritTypeForm, severity: e.target.value })} className="w-full border rounded px-3 py-2">
                    <option value="">None</option>
                    <option value="LOW">Low</option>
                    <option value="MEDIUM">Medium</option>
                    <option value="HIGH">High</option>
                    <option value="CRITICAL">Critical</option>
                  </select>
                </div>
              )}
              <div className="flex items-center gap-4">
                <label className="flex items-center gap-2">
                  <input type="checkbox" checked={meritTypeForm.requires_approval} onChange={(e) => setMeritTypeForm({ ...meritTypeForm, requires_approval: e.target.checked })} />
                  <span className="text-sm">Requires Approval</span>
                </label>
                <label className="flex items-center gap-2">
                  <input type="checkbox" checked={meritTypeForm.is_active} onChange={(e) => setMeritTypeForm({ ...meritTypeForm, is_active: e.target.checked })} />
                  <span className="text-sm">Active</span>
                </label>
              </div>
            </div>
            <div className="flex gap-3 mt-6">
              <button onClick={() => setShowMeritTypeForm(false)} className="flex-1 px-4 py-2 border rounded hover:bg-gray-50">Cancel</button>
              <button onClick={async () => { try { if(editingMeritType) { await apiClient.put(`/hr/merit-demerit-types/${editingMeritType.id}`, meritTypeForm); } else { await apiClient.post('/hr/merit-demerit-types', meritTypeForm); } await fetchMasterConfig(); setShowMeritTypeForm(false); } catch(e) { alert('Failed to save type'); }}} className="flex-1 px-4 py-2 bg-amber-600 text-white rounded hover:bg-amber-700">Save</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import * as XLSX from 'xlsx';
import { apiClient } from '../../../../../../lib/api-client';

export default function ImportItemsPage() {
  const router = useRouter();
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState<any[]>([]);
  const [uploading, setUploading] = useState(false);
  const [results, setResults] = useState<any>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (!selectedFile) return;

    setFile(selectedFile);
    setResults(null);
    parseFile(selectedFile);
  };

  const parseFile = (file: File) => {
    const reader = new FileReader();
    
    reader.onload = (e) => {
      try {
        const data = e.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const jsonData = XLSX.utils.sheet_to_json(worksheet);
        
        setPreview(jsonData.slice(0, 10)); // Show first 10 rows
      } catch (err) {
        alert('Failed to parse file. Please check the format.');
        console.error('Parse error:', err);
      }
    };

    reader.readAsBinaryString(file);
  };

  const handleUpload = async () => {
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        setUploading(true);
        const data = e.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const jsonData = XLSX.utils.sheet_to_json(worksheet);
        
        const uploadResults = await apiClient.post('/items/bulk', { items: jsonData });
        setResults(uploadResults);
        
        alert(`Import completed!\nSuccess: ${uploadResults.success}\nFailed: ${uploadResults.failed}`);
      } catch (err: any) {
        alert('Failed to upload items: ' + (err.message || 'Unknown error'));
        console.error('Upload error:', err);
      } finally {
        setUploading(false);
      }
    };

    reader.readAsBinaryString(file);
  };

  const downloadTemplate = () => {
    const template = [{
      code: 'ITEM001',
      name: 'Sample Item',
      description: 'Item description',
      category: 'RAW_MATERIAL',
      uom: 'PCS',
      standard_cost: 100,
      selling_price: 150,
      reorder_level: 10,
      reorder_quantity: 50,
      lead_time_days: 7
    }];

    const worksheet = XLSX.utils.json_to_sheet(template);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Items Template');
    XLSX.writeFile(workbook, 'items_import_template.xlsx');
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-amber-50 to-orange-50 p-8">
      <div className="max-w-6xl mx-auto">
        <button
          onClick={() => router.push('/dashboard/inventory/items')}
          className="text-amber-600 hover:text-amber-800 mb-4 flex items-center gap-2"
        >
          ← Back to Items
        </button>

        <div className="bg-white rounded-lg shadow-md p-8">
          <h1 className="text-3xl font-bold text-amber-900 mb-2">📊 Import Items from Excel</h1>
          <p className="text-gray-600 mb-8">Upload an Excel file with multiple items at once</p>

          {/* Download Template */}
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-6 mb-8">
            <div className="flex items-start gap-3">
              <span className="text-3xl">💡</span>
              <div className="flex-1">
                <h3 className="font-semibold text-blue-900 mb-2">Download Template First</h3>
                <p className="text-sm text-blue-700 mb-4">
                  Get the Excel template with the correct column format to ensure successful import
                </p>
                <button
                  onClick={downloadTemplate}
                  className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg font-medium"
                >
                  📥 Download Template
                </button>
              </div>
            </div>
          </div>

          {/* File Upload */}
          <div className="mb-8">
            <label className="block text-sm font-medium text-gray-700 mb-3">
              Select Excel File (.xlsx, .xls, .csv)
            </label>
            <input
              type="file"
              accept=".xlsx,.xls,.csv"
              onChange={handleFileChange}
              className="block w-full text-sm text-gray-500 
                file:mr-4 file:py-3 file:px-6
                file:rounded-lg file:border-0
                file:text-sm file:font-semibold
                file:bg-amber-50 file:text-amber-700
                hover:file:bg-amber-100
                cursor-pointer"
            />
          </div>

          {/* Expected Format */}
          <div className="bg-gray-50 border border-gray-200 rounded-lg p-6 mb-8">
            <h3 className="font-semibold text-gray-900 mb-3">Expected Columns:</h3>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-3 text-sm">
              {['code', 'name', 'description', 'category', 'uom', 'standard_cost', 'selling_price', 'reorder_level', 'reorder_quantity', 'lead_time_days'].map((col) => (
                <div key={col} className="flex items-center gap-2">
                  <span className="text-green-600">✓</span>
                  <code className="text-gray-700 bg-gray-100 px-2 py-1 rounded">{col}</code>
                </div>
              ))}
            </div>
            <div className="mt-4 text-sm text-gray-600">
              <strong>Category values:</strong> RAW_MATERIAL, COMPONENT, SUBASSEMBLY, FINISHED_GOODS, CONSUMABLE, PACKING_MATERIAL, SPARE_PART
            </div>
          </div>

          {/* Preview */}
          {preview.length > 0 && (
            <div className="mb-8">
              <h3 className="font-semibold text-gray-900 mb-4 text-lg">
                Preview (First {preview.length} rows)
              </h3>
              <div className="overflow-x-auto border rounded-lg">
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-gray-50">
                    <tr>
                      {Object.keys(preview[0]).map((key) => (
                        <th
                          key={key}
                          className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider"
                        >
                          {key}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {preview.map((row, idx) => (
                      <tr key={idx} className="hover:bg-gray-50">
                        {Object.values(row).map((val: any, cellIdx) => (
                          <td key={cellIdx} className="px-4 py-3 text-sm text-gray-900 whitespace-nowrap">
                            {String(val)}
                          </td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* Upload Button */}
          {file && preview.length > 0 && !results && (
            <div className="flex justify-end">
              <button
                onClick={handleUpload}
                disabled={uploading}
                className="bg-amber-600 hover:bg-amber-700 text-white px-8 py-3 rounded-lg font-semibold disabled:bg-gray-300 disabled:cursor-not-allowed"
              >
                {uploading ? 'Uploading...' : `Upload & Import ${preview.length}+ Items`}
              </button>
            </div>
          )}

          {/* Results */}
          {results && (
            <div className="mt-8">
              <div className={`rounded-lg p-6 ${results.failed === 0 ? 'bg-green-50 border-2 border-green-500' : 'bg-yellow-50 border-2 border-yellow-500'}`}>
                <h3 className="text-xl font-bold mb-4">Import Results:</h3>
                <div className="grid grid-cols-2 gap-4 mb-4">
                  <div className="text-center p-4 bg-white rounded-lg">
                    <div className="text-3xl font-bold text-green-600">{results.success}</div>
                    <div className="text-sm text-gray-600">Successfully Imported</div>
                  </div>
                  <div className="text-center p-4 bg-white rounded-lg">
                    <div className="text-3xl font-bold text-red-600">{results.failed}</div>
                    <div className="text-sm text-gray-600">Failed</div>
                  </div>
                </div>

                {results.errors && results.errors.length > 0 && (
                  <div className="mt-4">
                    <h4 className="font-semibold text-red-900 mb-2">Errors:</h4>
                    <div className="bg-white rounded-lg p-4 max-h-60 overflow-y-auto">
                      {results.errors.map((err: any, idx: number) => (
                        <div key={idx} className="text-sm text-red-700 mb-2 pb-2 border-b last:border-0">
                          <strong>Row {err.row}:</strong> {err.item} - {err.error}
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                <div className="mt-6 flex gap-4">
                  <button
                    onClick={() => router.push('/dashboard/inventory/items')}
                    className="flex-1 bg-amber-600 hover:bg-amber-700 text-white px-6 py-3 rounded-lg font-semibold"
                  >
                    Go to Items List
                  </button>
                  <button
                    onClick={() => {
                      setFile(null);
                      setPreview([]);
                      setResults(null);
                    }}
                    className="flex-1 border-2 border-gray-300 hover:bg-gray-50 text-gray-700 px-6 py-3 rounded-lg font-semibold"
                  >
                    Import More Items
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { apiClient } from '../../../../../lib/api-client';
import DrawingManager from '../../../../components/DrawingManager';
import DuplicateWarning, { useDuplicateDetection } from '../../../../components/DuplicateWarning';

interface Item {
  id: string;
  code: string;
  name: string;
  description?: string;
  category: string;
  uom: string;
  hsn_code?: string;
  standard_cost?: number;
  selling_price?: number;
  reorder_level?: number;
  reorder_quantity?: number;
  lead_time_days?: number;
  is_active: boolean;
  created_at: string;
  total_stock?: number;
  uid_tracking?: boolean;
  uid_strategy?: string;
  batch_uom?: string;
  batch_quantity?: number;
  drawing_required?: string;
  parent_item_id?: string;
  is_variant?: boolean;
  is_default_variant?: boolean;
  variant_name?: string;
}

interface Vendor {
  id: string;
  code: string;
  name: string;
}

interface ItemVendor {
  vendor_id: string;
  priority: number;
  unit_price?: number;
  lead_time_days?: number;
  vendor_item_code?: string;
}

type ItemsTableColumnKey =
  | 'code'
  | 'name'
  | 'category'
  | 'uom'
  | 'hsn_code'
  | 'uid_tracking'
  | 'drawing_required'
  | 'total_stock'
  | 'standard_cost'
  | 'selling_price'
  | 'is_active';

const ITEMS_TABLE_COLUMNS: Array<{ key: ItemsTableColumnKey; label: string }> = [
  { key: 'code', label: 'Code' },
  { key: 'name', label: 'Name' },
  { key: 'category', label: 'Category' },
  { key: 'uom', label: 'UOM' },
  { key: 'hsn_code', label: 'HSN' },
  { key: 'uid_tracking', label: 'UID' },
  { key: 'drawing_required', label: 'Drawing' },
  { key: 'total_stock', label: 'Stock' },
  { key: 'standard_cost', label: 'Cost' },
  { key: 'selling_price', label: 'Price' },
  { key: 'is_active', label: 'Status' },
];

const ITEMS_TABLE_COLUMNS_STORAGE_KEY = 'itemsTableColumns:v1';

export default function ItemsPage() {
  const router = useRouter();
  const [items, setItems] = useState<Item[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [editingItem, setEditingItem] = useState<Item | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('');
  const [showDeleted, setShowDeleted] = useState(false);
  const [showDrawingManager, setShowDrawingManager] = useState(false);
  const [selectedItemForDrawing, setSelectedItemForDrawing] = useState<Item | null>(null);
  const [showCategoryManager, setShowCategoryManager] = useState(false);
  const [categories, setCategories] = useState<any[]>([]);
  const [newCategory, setNewCategory] = useState('');
  const [editingCategory, setEditingCategory] = useState<{ id: string; name: string } | null>(null);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [itemVendors, setItemVendors] = useState<ItemVendor[]>([]);
  const [showVendorForm, setShowVendorForm] = useState(false);
  
  // Variant manager state
  const [showVariantManager, setShowVariantManager] = useState(false);
  const [selectedParentItem, setSelectedParentItem] = useState<Item | null>(null);
  const [variants, setVariants] = useState<Item[]>([]);
  const { duplicateState, checkDuplicates, handleProceed, handleCancel } = useDuplicateDetection();
  const [newVariant, setNewVariant] = useState({ code: '', name: '', variant_name: '', is_default: false });
  
  // Drawing upload state
  const [drawingFile, setDrawingFile] = useState<File | null>(null);
  const [uploadingDrawing, setUploadingDrawing] = useState(false);
  
  // Bulk inventory state
  const [showBulkInventory, setShowBulkInventory] = useState(false);
  const [bulkInventoryItems, setBulkInventoryItems] = useState<Array<{itemId: string, itemCode: string, itemName: string, quantity: string, location: string}>>([]);
  
  // Pagination state
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(25);
  
  // Sorting state
  const [sortColumn, setSortColumn] = useState<string>('code');
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('asc');

  // Column visibility
  const [showColumnsMenu, setShowColumnsMenu] = useState(false);
  const [visibleColumns, setVisibleColumns] = useState<Record<ItemsTableColumnKey, boolean>>(() => {
    return ITEMS_TABLE_COLUMNS.reduce(
      (acc, col) => {
        acc[col.key] = true;
        return acc;
      },
      {} as Record<ItemsTableColumnKey, boolean>
    );
  });
  
  // Autocomplete state
  const [showAutocomplete, setShowAutocomplete] = useState(false);
  
  const [vendorForm, setVendorForm] = useState({
    vendor_id: '',
    priority: 1,
    unit_price: '',
    lead_time_days: '',
    vendor_item_code: '',
  });

  const [formData, setFormData] = useState({
    code: '',
    name: '',
    description: '',
    category: 'RAW_MATERIAL',
    uom: 'PCS',
    hsn_code: '',
    standard_cost: '',
    selling_price: '',
    reorder_level: '',
    reorder_quantity: '',
    lead_time_days: '',
    is_active: true,
    uid_tracking: true,
    uid_strategy: 'SERIALIZED',
    batch_uom: '',
    batch_quantity: '',
    drawing_required: 'OPTIONAL',
    parent_item_id: '',
    is_variant: false,
    is_default_variant: false,
    variant_name: '',
    drawing_url: '',
    drawing_file_name: '',
  });

  const addCategory = async () => {
    if (newCategory.trim()) {
      try {
        await apiClient.post('/categories', { name: newCategory });
        setNewCategory('');
        await fetchCategories();
        alert('Category added successfully!');
      } catch (error) {
        console.error('Error adding category:', error);
        alert('Failed to add category');
      }
    }
  };

  const updateCategory = async () => {
    if (editingCategory && editingCategory.name.trim()) {
      try {
        await apiClient.put(`/categories/${editingCategory.id}`, { name: editingCategory.name });
        setEditingCategory(null);
        await fetchCategories();
        alert('Category updated successfully!');
      } catch (error) {
        console.error('Error updating category:', error);
        alert('Failed to update category');
      }
    }
  };

  const deleteCategory = async (id: string, name: string) => {
    if (confirm(`Delete category "${name}"? This won't affect existing items.`)) {
      try {
        await apiClient.delete(`/categories/${id}`);
        await fetchCategories();
        alert('Category deleted successfully!');
      } catch (error) {
        console.error('Error deleting category:', error);
        alert('Failed to delete category');
      }
    }
  };

  const fetchCategories = async () => {
    try {
      const data = await apiClient.get('/categories');
      setCategories(data);
    } catch (error) {
      console.error('Error fetching categories:', error);
    }
  };

  const fetchVendors = async () => {
    try {
      // Vendors live under the purchase module routes
      const data = await apiClient.get('/purchase/vendors');
      setVendors(Array.isArray(data) ? data : []);
    } catch (error) {
      console.error('Error fetching vendors:', error);
      setVendors([]);
    }
  };

  const seedCategories = async () => {
    try {
      await apiClient.post('/categories/seed', {});
      await fetchCategories();
      alert('Default categories restored!');
    } catch (error) {
      console.error('Error seeding categories:', error);
      alert('Failed to restore categories');
    }
  };

  useEffect(() => {
    fetchCategories();
    fetchVendors();
  }, []);

  const uomOptions = [
    'PCS', 'KG', 'GRAM', 'LITER', 'METER', 'CM', 'MM',
    'BOX', 'SET', 'PACK', 'ROLL', 'SHEET', 'FEET', 'INCH'
  ];

  useEffect(() => {
    fetchItems();
    fetchVendors();
  }, [showDeleted]);

  useEffect(() => {
    try {
      const raw = localStorage.getItem(ITEMS_TABLE_COLUMNS_STORAGE_KEY);
      if (!raw) return;
      const parsed = JSON.parse(raw) as Partial<Record<ItemsTableColumnKey, boolean>>;

      setVisibleColumns((prev) => {
        const next = { ...prev };
        for (const { key } of ITEMS_TABLE_COLUMNS) {
          if (typeof parsed[key] === 'boolean') next[key] = parsed[key] as boolean;
        }
        return next;
      });
    } catch {
      // ignore invalid localStorage value
    }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem(ITEMS_TABLE_COLUMNS_STORAGE_KEY, JSON.stringify(visibleColumns));
    } catch {
      // ignore localStorage write errors
    }
  }, [visibleColumns]);

  const fetchItems = async () => {
    try {
      const url = showDeleted 
        ? '/inventory/items?includeInactive=true' 
        : '/inventory/items';
      const data = await apiClient.get(url);
      
      setItems(data);
    } catch (error) {
      console.error('Error fetching items:', error);
      alert('Failed to fetch items');
    } finally {
      setLoading(false);
    }
  };

  const actuallyCreateItem = async (
    payload: any,
    drawingLink?: {
      fileName: string;
      fileUrl: string;
      fileType?: string;
      fileSize?: number;
      revisionNotes?: string;
    },
  ) => {
    try {
      if (editingItem) {
        const shouldPreUploadDrawing =
          !!drawingLink && payload?.drawing_required === 'COMPULSORY';

        // If user is setting drawing as COMPULSORY and uploading in the same save,
        // we must create the drawing record first so the API validation passes.
        if (shouldPreUploadDrawing) {
          try {
            await apiClient.post(`/inventory/items/${editingItem.id}/drawings`, {
              fileName: drawingLink!.fileName,
              fileUrl: drawingLink!.fileUrl,
              fileType: drawingLink!.fileType,
              fileSize: drawingLink!.fileSize,
              revisionNotes: drawingLink!.revisionNotes || 'Uploaded via item form',
            });
          } catch (err) {
            console.error('Error linking drawing before item update:', err);
            // Continue to item update; if drawing is compulsory, API may still reject.
          }
        }

        await apiClient.put(`/inventory/items/${editingItem.id}`, payload);

        // For normal updates, link the new drawing after the item update succeeds.
        if (drawingLink && !shouldPreUploadDrawing) {
          try {
            await apiClient.post(`/inventory/items/${editingItem.id}/drawings`, {
              fileName: drawingLink.fileName,
              fileUrl: drawingLink.fileUrl,
              fileType: drawingLink.fileType,
              fileSize: drawingLink.fileSize,
              revisionNotes: drawingLink.revisionNotes || 'Uploaded via item form',
            });
          } catch (err) {
            console.error('Error linking drawing after item update:', err);
            alert('Item updated, but drawing could not be linked. Please upload it from the Drawings tab.');
          }
        }

        alert('Item updated successfully!');
      } else {
        const result = await apiClient.post('/inventory/items', payload);

        // If a drawing was uploaded during creation, link it to the new item.
        if (drawingLink && result?.id) {
          try {
            await apiClient.post(`/inventory/items/${result.id}/drawings`, {
              fileName: drawingLink.fileName,
              fileUrl: drawingLink.fileUrl,
              fileType: drawingLink.fileType,
              fileSize: drawingLink.fileSize,
              revisionNotes: drawingLink.revisionNotes || 'Initial version',
            });
          } catch (err) {
            console.error('Error linking drawing after item create:', err);
            alert('Item created, but drawing could not be linked. Please upload it from the Drawings tab.');
          }
        }
        
        // If vendors were added during creation, save them now
        if (itemVendors.length > 0 && result.id) {
          for (const vendor of itemVendors) {
            try {
              await apiClient.post(`/inventory/items/${result.id}/vendors`, {
                vendor_id: vendor.vendor_id,
                priority: vendor.priority,
                unit_price: vendor.unit_price,
                lead_time_days: vendor.lead_time_days,
                vendor_item_code: vendor.vendor_item_code,
              });
            } catch (vendorError) {
              console.error('Error adding vendor to new item:', vendorError);
              // Continue with other vendors even if one fails
            }
          }
        }
        
        alert('Item created successfully!');
      }

      setShowForm(false);
      setEditingItem(null);
      resetForm();
      fetchItems();
    } catch (error: any) {
      console.error('Error saving item:', error);
      alert(error.response?.data?.message || 'Failed to save item');
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      // Upload drawing if file is selected
      let drawingData = {
        drawing_url: formData.drawing_url,
        drawing_file_name: formData.drawing_file_name
      };

      let drawingLink:
        | {
            fileName: string;
            fileUrl: string;
            fileType?: string;
            fileSize?: number;
            revisionNotes?: string;
          }
        | undefined;
      
      if (drawingFile) {
        const uploadResult = await handleDrawingUpload(drawingFile);
        if (uploadResult) {
          drawingData = uploadResult;

          // Create a drawing record (item_drawings) after the item save.
          drawingLink = {
            fileName: drawingFile.name,
            fileUrl: uploadResult.drawing_url,
            fileType: drawingFile.type,
            fileSize: drawingFile.size,
            revisionNotes: editingItem ? 'Updated via item form' : 'Initial version',
          };
        }
      }
      
      const payload = {
        ...formData,
        ...drawingData,
        hsn_code: (formData.hsn_code || '').replace(/[^0-9]/g, ''),
        standard_cost: formData.standard_cost ? parseFloat(formData.standard_cost) : null,
        selling_price: formData.selling_price ? parseFloat(formData.selling_price) : null,
        reorder_level: formData.reorder_level ? parseInt(formData.reorder_level) : null,
        reorder_quantity: formData.reorder_quantity ? parseInt(formData.reorder_quantity) : null,
        lead_time_days: formData.lead_time_days ? parseInt(formData.lead_time_days) : null,
        batch_quantity: formData.batch_quantity ? parseFloat(formData.batch_quantity) : null,
        parent_item_id: formData.parent_item_id || null,
        is_variant: formData.is_variant || false,
        is_default_variant: formData.is_default_variant || false,
        variant_name: formData.variant_name || null,
      };

      // For updates, skip duplicate check
      if (editingItem) {
        await actuallyCreateItem(payload, drawingLink);
        return;
      }

      // Check for duplicates before creating
      await checkDuplicates(
        () => apiClient.post('/items/check-duplicates', payload),
        () => actuallyCreateItem(payload, drawingLink),
      );
    } catch (error: any) {
      console.error('Error saving item:', error);
      alert(error.response?.data?.message || 'Failed to save item');
    }
  };

  const loadExistingDrawingForEdit = async (itemId: string) => {
    try {
      const drawings = await apiClient.get(`/inventory/items/${itemId}/drawings`);
      if (!Array.isArray(drawings) || drawings.length === 0) return;

      const active = drawings.find((d: any) => d?.is_active) || drawings[0];
      const fileUrl = String(active?.file_url || '');
      const fileName = String(active?.file_name || '');
      if (!fileUrl && !fileName) return;

      setFormData((prev) => ({
        ...prev,
        drawing_url: fileUrl || prev.drawing_url,
        drawing_file_name: fileName || prev.drawing_file_name,
      }));
    } catch (error) {
      console.error('Error loading existing drawings:', error);
    }
  };

  const handleEdit = (item: Item) => {
    setEditingItem(item);
    setFormData({
      code: item.code,
      name: item.name,
      description: item.description || '',
      category: item.category,
      uom: item.uom,
      // Some older records/imports can have whitespace; trim so HTML pattern validation doesn't block saving
      hsn_code: (item.hsn_code ? String(item.hsn_code) : '').replace(/[^0-9]/g, ''),
      standard_cost: item.standard_cost?.toString() || '',
      selling_price: item.selling_price?.toString() || '',
      reorder_level: item.reorder_level?.toString() || '',
      reorder_quantity: item.reorder_quantity?.toString() || '',
      lead_time_days: item.lead_time_days?.toString() || '',
      is_active: item.is_active,
      uid_tracking: item.uid_tracking !== false,
      uid_strategy: item.uid_strategy || 'SERIALIZED',
      batch_uom: item.batch_uom || '',
      batch_quantity: item.batch_quantity?.toString() || '',
      drawing_required: item.drawing_required || 'OPTIONAL',
      parent_item_id: item.parent_item_id || '',
      is_variant: item.is_variant || false,
      is_default_variant: item.is_default_variant || false,
      variant_name: item.variant_name || '',
      drawing_url: (item as any).drawing_url || '',
      drawing_file_name: (item as any).drawing_file_name || '',
    });
    setDrawingFile(null);
    setShowForm(true);
    fetchItemVendors(item.id);

    // Ensure the edit form shows the current drawing even when drawings are stored in item_drawings.
    loadExistingDrawingForEdit(item.id);
  };

  const fetchItemVendors = async (itemId: string) => {
    try {
      const data = await apiClient.get(`/inventory/items/${itemId}/vendors`);
      setItemVendors(data || []);
    } catch (error) {
      console.error('Error fetching item vendors:', error);
      setItemVendors([]);
    }
  };

  const openVariantManager = async (item: Item) => {
    setSelectedParentItem(item);
    setShowVariantManager(true);
    await fetchVariants(item.id);
  };

  const fetchVariants = async (parentItemId: string) => {
    try {
      console.log('[fetchVariants] Fetching variants for parent:', parentItemId);
      const data = await apiClient.get(`/items/${parentItemId}/variants`);
      console.log('[fetchVariants] Received variants:', data);
      setVariants(data || []);
    } catch (error) {
      console.error('Error fetching variants:', error);
      setVariants([]);
    }
  };

  const addVariantQuick = async () => {
    if (!selectedParentItem || !newVariant.code || !newVariant.name || !newVariant.variant_name) {
      alert('Please fill in all variant fields');
      return;
    }
    
    try {
      const payload = {
        code: newVariant.code,
        name: newVariant.name,
        variant_name: newVariant.variant_name,
        parent_item_id: selectedParentItem.id,
        is_variant: true,
        is_default_variant: newVariant.is_default,
        category: selectedParentItem.category,
        uom: selectedParentItem.uom,
        hsn_code: selectedParentItem.hsn_code || '',
        is_active: true,
        uid_tracking: false,
        uid_strategy: 'NONE',
      };
      
      console.log('[addVariantQuick] Sending payload:', payload);
      const result = await apiClient.post('/inventory/items', payload);
      console.log('[addVariantQuick] Result:', result);
      
      setNewVariant({ code: '', name: '', variant_name: '', is_default: false });
      await fetchVariants(selectedParentItem.id);
      await fetchItems();
      alert('Variant added successfully!');
    } catch (error: any) {
      console.error('[addVariantQuick] Full error:', error);
      console.error('[addVariantQuick] Error response:', error.response);
      const errorMsg = error.response?.data?.message || error.message || 'Failed to add variant';
      alert('Failed to add variant:\n' + errorMsg);
    }
  };

  const deleteVariant = async (variantId: string) => {
    if (!confirm('Delete this variant? This cannot be undone.')) return;
    
    try {
      await apiClient.delete(`/inventory/items/${variantId}`);
      if (selectedParentItem) {
        await fetchVariants(selectedParentItem.id);
      }
      await fetchItems();
      alert('Variant deleted successfully!');
    } catch (error: any) {
      console.error('Error deleting variant:', error);
      alert(error.response?.data?.message || 'Failed to delete variant');
    }
  };

  const toggleDefaultVariant = async (variantId: string, currentDefault: boolean) => {
    if (!selectedParentItem) return;
    
    try {
      await apiClient.put(`/inventory/items/${variantId}`, {
        is_default_variant: !currentDefault
      });
      await fetchVariants(selectedParentItem.id);
      await fetchItems();
    } catch (error: any) {
      console.error('Error updating default variant:', error);
      alert(error.response?.data?.message || 'Failed to update default variant');
    }
  };

  const addItemVendor = async () => {
    if (!vendorForm.vendor_id) {
      alert('Please select a vendor');
      return;
    }

    // Check for duplicate vendor
    const isDuplicate = itemVendors.some(iv => iv.vendor_id === vendorForm.vendor_id);
    if (isDuplicate) {
      alert('This vendor is already added. Please select a different vendor.');
      return;
    }

    // If editing existing item, save to database
    if (editingItem) {
      try {
        await apiClient.post(`/inventory/items/${editingItem.id}/vendors`, {
          vendor_id: vendorForm.vendor_id,
          priority: vendorForm.priority,
          unit_price: vendorForm.unit_price ? parseFloat(vendorForm.unit_price) : null,
          lead_time_days: vendorForm.lead_time_days ? parseInt(vendorForm.lead_time_days) : null,
          vendor_item_code: vendorForm.vendor_item_code || null,
        });
        
        alert('Vendor added successfully!');
        setShowVendorForm(false);
        setVendorForm({
          vendor_id: '',
          priority: 1,
          unit_price: '',
          lead_time_days: '',
          vendor_item_code: '',
        });
        fetchItemVendors(editingItem.id);
      } catch (error: any) {
        console.error('Error adding vendor:', error);
        alert(error.message || 'Failed to add vendor');
      }
    } else {
      // If creating new item, add to temporary list
      const vendor = vendors.find(v => v.id === vendorForm.vendor_id);
      if (!vendor) {
        alert('Vendor not found');
        return;
      }

      const newVendor: any = {
        vendor_id: vendorForm.vendor_id,
        vendor_name: vendor.name,
        priority: vendorForm.priority,
        unit_price: vendorForm.unit_price ? parseFloat(vendorForm.unit_price) : null,
        lead_time_days: vendorForm.lead_time_days ? parseInt(vendorForm.lead_time_days) : null,
        vendor_item_code: vendorForm.vendor_item_code || null,
        is_preferred: vendorForm.priority === 1,
      };

      setItemVendors([...itemVendors, newVendor]);
      setShowVendorForm(false);
      setVendorForm({
        vendor_id: '',
        priority: 1,
        unit_price: '',
        lead_time_days: '',
        vendor_item_code: '',
      });
    }
  };

  const removeItemVendor = async (vendorId: string) => {
    if (editingItem) {
      // If editing, remove from database
      if (!confirm('Remove this vendor?')) return;

      try {
        await apiClient.delete(`/inventory/items/${editingItem.id}/vendors/${vendorId}`);
        alert('Vendor removed successfully!');
        fetchItemVendors(editingItem.id);
      } catch (error) {
        console.error('Error removing vendor:', error);
        alert('Failed to remove vendor');
      }
    } else {
      // If creating new item, remove from temporary list
      setItemVendors(itemVendors.filter(iv => iv.vendor_id !== vendorId));
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this item?')) return;
    
    try {
      await apiClient.delete(`/inventory/items/${id}`);
      alert('Item deleted successfully!');
      fetchItems();
    } catch (error) {
      console.error('Error deleting item:', error);
      alert('Failed to delete item');
    }
  };

  const handleRestore = async (id: string) => {
    if (!confirm('Are you sure you want to restore this item?')) return;
    
    try {
      await apiClient.put(`/inventory/items/${id}`, { is_active: true });
      alert('Item restored successfully!');
      fetchItems();
    } catch (error) {
      console.error('Error restoring item:', error);
      alert('Failed to restore item');
    }
  };

  const handleDrawingUpload = async (file: File) => {
    if (!file) return null;
    
    setUploadingDrawing(true);
    try {
      const formDataUpload = new FormData();
      formDataUpload.append('file', file);
      formDataUpload.append('bucket', 'drawings');
      formDataUpload.append('folder', 'item-drawings');

      const result: any = await apiClient.postForm('/upload', formDataUpload);

      const uploadedUrl = result?.url || '';
      if (!uploadedUrl) throw new Error('Upload failed: no url returned');

      return {
        drawing_url: uploadedUrl,
        drawing_file_name: file.name,
      };
    } catch (error) {
      console.error('Error uploading drawing:', error);
      alert('Failed to upload drawing');
      return null;
    } finally {
      setUploadingDrawing(false);
    }
  };

  const initBulkInventory = () => {
    // Initialize with all active items with zero quantity
    const bulkItems = items
      .filter(item => item.is_active)
      .map(item => ({
        itemId: item.id,
        itemCode: item.code,
        itemName: item.name,
        quantity: '',
        location: 'MAIN_WAREHOUSE'
      }));
    setBulkInventoryItems(bulkItems);
    setShowBulkInventory(true);
  };

  const handleBulkInventorySubmit = async () => {
    // Filter items with quantity entered
    const itemsWithQty = bulkInventoryItems.filter(item => item.quantity && parseFloat(item.quantity) > 0);
    
    if (itemsWithQty.length === 0) {
      alert('Please enter quantities for at least one item');
      return;
    }

    if (!confirm(`Add inventory for ${itemsWithQty.length} items?`)) return;

    try {
      // Fetch warehouses to get warehouse IDs
      const warehousesResponse = await apiClient.get('/inventory/warehouses');
      const warehouses = warehousesResponse || [];

      // Map location names to warehouse IDs
      const locationToWarehouseId: Record<string, string> = {};
      warehouses.forEach((wh: any) => {
        if (wh.name === 'Main Warehouse') locationToWarehouseId['MAIN_WAREHOUSE'] = wh.id;
        else if (wh.name === 'Production Floor') locationToWarehouseId['PRODUCTION_FLOOR'] = wh.id;
        else if (wh.name === 'QC Area') locationToWarehouseId['QC_AREA'] = wh.id;
        else if (wh.name === 'Finished Goods') locationToWarehouseId['FINISHED_GOODS'] = wh.id;
      });

      // If no mapping found, use the first warehouse as default
      const defaultWarehouseId = warehouses[0]?.id;

      if (!defaultWarehouseId) {
        alert('No warehouses found. Please create a warehouse first.');
        return;
      }

      // Create inventory movements for each item
      const promises = itemsWithQty.map(item =>
        apiClient.post('/inventory/movements', {
          movement_type: 'ADJUSTMENT',
          item_id: item.itemId,
          to_warehouse_id: locationToWarehouseId[item.location] || defaultWarehouseId,
          quantity: parseFloat(item.quantity),
          notes: 'Bulk inventory entry'
        })
      );

      await Promise.all(promises);
      alert(`Successfully added inventory for ${itemsWithQty.length} items!`);
      setShowBulkInventory(false);
      setBulkInventoryItems([]);
      fetchItems();
    } catch (error) {
      console.error('Error adding bulk inventory:', error);
      alert('Failed to add bulk inventory');
    }
  };

  const resetForm = () => {
    setFormData({
      code: '',
      name: '',
      description: '',
      category: 'RAW_MATERIAL',
      uom: 'PCS',
      hsn_code: '',
      standard_cost: '',
      selling_price: '',
      reorder_level: '',
      reorder_quantity: '',
      lead_time_days: '',
      is_active: true,
      uid_tracking: true,
      uid_strategy: 'SERIALIZED',
      batch_uom: '',
      batch_quantity: '',
      drawing_required: 'OPTIONAL',
      parent_item_id: '',
      is_variant: false,
      is_default_variant: false,
      variant_name: '',
      drawing_url: '',
      drawing_file_name: '',
    });
    setDrawingFile(null);
    setItemVendors([]);
    setShowVendorForm(false);
  };

  const filteredItems = items.filter(item => {
    const matchesSearch = 
      item.code.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = !categoryFilter || item.category === categoryFilter;
    // When showDeleted is true, show only inactive items. When false, show only active items.
    const matchesActiveStatus = showDeleted ? !item.is_active : item.is_active;
    return matchesSearch && matchesCategory && matchesActiveStatus;
  });

  // Sorting
  const sortedItems = [...filteredItems].sort((a, b) => {
    let aVal: any = a[sortColumn as keyof Item];
    let bVal: any = b[sortColumn as keyof Item];
    
    // Handle null/undefined values
    if (aVal === null || aVal === undefined) aVal = '';
    if (bVal === null || bVal === undefined) bVal = '';
    
    // Convert to string for comparison if needed
    if (typeof aVal === 'string') aVal = aVal.toLowerCase();
    if (typeof bVal === 'string') bVal = bVal.toLowerCase();
    
    if (aVal < bVal) return sortDirection === 'asc' ? -1 : 1;
    if (aVal > bVal) return sortDirection === 'asc' ? 1 : -1;
    return 0;
  });

  // Pagination
  const totalItems = sortedItems.length;
  const totalPages = Math.ceil(totalItems / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const paginatedItems = sortedItems.slice(startIndex, endIndex);

  // Autocomplete suggestions (top 10 matches)
  const autocompleteSuggestions = searchTerm.length >= 2
    ? items
        .filter(item => 
          (item.code.toLowerCase().includes(searchTerm.toLowerCase()) ||
           item.name.toLowerCase().includes(searchTerm.toLowerCase())) &&
          (showDeleted ? !item.is_active : item.is_active)
        )
        .slice(0, 10)
    : [];

  // Handle sort column click
  const handleSort = (column: string) => {
    if (sortColumn === column) {
      setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc');
    } else {
      setSortColumn(column);
      setSortDirection('asc');
    }
  };

  const toggleColumn = (key: ItemsTableColumnKey) => {
    setVisibleColumns((prev) => ({
      ...prev,
      [key]: !prev[key],
    }));
  };

  const resetColumns = () => {
    setVisibleColumns(
      ITEMS_TABLE_COLUMNS.reduce(
        (acc, col) => {
          acc[col.key] = true;
          return acc;
        },
        {} as Record<ItemsTableColumnKey, boolean>
      )
    );
  };

  const visibleColumnsCount = ITEMS_TABLE_COLUMNS.reduce(
    (count, col) => count + (visibleColumns[col.key] ? 1 : 0),
    0
  );

  // Handle pagination
  const goToPage = (page: number) => {
    setCurrentPage(Math.max(1, Math.min(page, totalPages)));
  };

  // Reset to page 1 when filters change
  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, categoryFilter, showDeleted]);

  const normalizedItemUom = String(formData.uom || '')
    .trim()
    .toUpperCase();
  const isVolumeUom = normalizedItemUom === 'LITER' || normalizedItemUom === 'L' || normalizedItemUom === 'LTR' || normalizedItemUom === 'ML';

  useEffect(() => {
    if (formData.uid_strategy !== 'BATCHED') return;
    if (!formData.batch_uom) return;

    const allowedContainerTypes = isVolumeUom
      ? ['Drum', 'Bucket', 'Can', 'IBC', 'Bottle', 'Container']
      : ['Box', 'Carton', 'Pallet', 'Bag', 'Roll', 'Container'];

    if (!allowedContainerTypes.includes(formData.batch_uom)) {
      setFormData((prev) => ({ ...prev, batch_uom: '', batch_quantity: '' }));
    }
  }, [formData.uid_strategy, formData.batch_uom, isVolumeUom]);

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-xl">Loading...</div>
      </div>
    );
  }

  return (
    <div className="p-6">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold text-gray-800">Items Master</h1>
        <div className="flex gap-3">
          <button
            onClick={() => setShowCategoryManager(true)}
            className="bg-[#8B6F47] text-white px-6 py-2 rounded-lg hover:bg-[#6F4E37] font-medium flex items-center gap-2"
          >
            🏷️ Manage Categories
          </button>
          <div className="relative">
            <button
              onClick={() => setShowColumnsMenu((v) => !v)}
              className="bg-gray-200 text-gray-700 px-6 py-2 rounded-lg hover:bg-gray-300 font-medium"
            >
              Columns
            </button>
            {showColumnsMenu && (
              <div className="absolute right-0 mt-2 w-64 bg-white border border-gray-200 rounded-lg shadow-lg z-20 p-3">
                <div className="flex items-center justify-between mb-2">
                  <div className="font-semibold text-gray-800">Show Columns</div>
                  <button
                    onClick={() => setShowColumnsMenu(false)}
                    className="text-gray-500 hover:text-gray-700"
                    aria-label="Close columns"
                  >
                    ×
                  </button>
                </div>
                <div className="max-h-64 overflow-y-auto pr-1">
                  {ITEMS_TABLE_COLUMNS.map((col) => (
                    <label key={col.key} className="flex items-center gap-2 py-1 text-sm text-gray-700">
                      <input
                        type="checkbox"
                        checked={!!visibleColumns[col.key]}
                        onChange={() => toggleColumn(col.key)}
                        className="h-4 w-4"
                      />
                      {col.label}
                    </label>
                  ))}
                </div>
                <div className="flex items-center justify-between pt-2 mt-2 border-t border-gray-100">
                  <button
                    onClick={resetColumns}
                    className="text-sm text-gray-600 hover:text-gray-800"
                  >
                    Reset
                  </button>
                  <button
                    onClick={() => setShowColumnsMenu(false)}
                    className="text-sm bg-amber-600 text-white px-3 py-1 rounded hover:bg-amber-700"
                  >
                    Done
                  </button>
                </div>
              </div>
            )}
          </div>
          <button
            onClick={() => router.push('/dashboard/inventory/items/import')}
            className="bg-green-600 text-white px-6 py-2 rounded-lg hover:bg-green-700 font-medium flex items-center gap-2"
          >
            📊 Import Excel
          </button>
          <button
            onClick={initBulkInventory}
            className="bg-blue-600 text-white px-6 py-2 rounded-lg hover:bg-blue-700 font-medium flex items-center gap-2"
          >
            📦 Bulk Inventory
          </button>
          <button
            onClick={() => {
              setEditingItem(null);
              resetForm();
              setShowForm(true);
            }}
            className="bg-amber-600 text-white px-6 py-2 rounded-lg hover:bg-amber-700 font-medium"
          >
            + Add Item
          </button>
        </div>
      </div>

      {/* Filters */}
      <div className="mb-6 bg-white p-4 rounded-lg shadow flex gap-4">
        <button
          onClick={() => setShowDeleted(!showDeleted)}
          className={`px-4 py-2 rounded-lg font-medium transition-colors ${
            showDeleted 
              ? 'bg-red-600 text-white hover:bg-red-700' 
              : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
          }`}
        >
          {showDeleted ? '🗑️ Showing Deleted' : '📋 Show Deleted'}
        </button>
        <div className="relative flex-1">
          <input
            type="text"
            placeholder="Search by code or name..."
            value={searchTerm}
            onChange={(e) => {
              setSearchTerm(e.target.value);
              setShowAutocomplete(e.target.value.length >= 2);
            }}
            onFocus={() => setShowAutocomplete(searchTerm.length >= 2)}
            onBlur={() => setTimeout(() => setShowAutocomplete(false), 200)}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
          />
          {showAutocomplete && autocompleteSuggestions.length > 0 && (
            <div className="absolute z-10 w-full mt-1 bg-white border border-gray-300 rounded-lg shadow-lg max-h-60 overflow-y-auto">
              {autocompleteSuggestions.map((item) => (
                <div
                  key={item.id}
                  onClick={() => {
                    setSearchTerm(item.code);
                    setShowAutocomplete(false);
                  }}
                  className="px-4 py-2 hover:bg-amber-50 cursor-pointer border-b border-gray-100 last:border-b-0"
                >
                  <div className="font-medium text-gray-900">{item.code}</div>
                  <div className="text-sm text-gray-500">{item.name}</div>
                </div>
              ))}
            </div>
          )}
        </div>
        <select
          value={categoryFilter}
          onChange={(e) => setCategoryFilter(e.target.value)}
          className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
        >
          <option value="">All Categories</option>
          {categories.map(cat => (
            <option key={cat.id} value={cat.name}>{cat.name.replace(/_/g, ' ')}</option>
          ))}
        </select>
      </div>

      {/* Items Table */}
      <div className="bg-white rounded-lg shadow overflow-x-auto">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-50">
            <tr>
              {visibleColumns.code && (
                <th 
                  onClick={() => handleSort('code')}
                  className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100"
                >
                  <div className="flex items-center gap-1">
                    Code
                    {sortColumn === 'code' && (
                      <span>{sortDirection === 'asc' ? '↑' : '↓'}</span>
                    )}
                  </div>
                </th>
              )}
              {visibleColumns.name && (
                <th 
                  onClick={() => handleSort('name')}
                  className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100"
                >
                  <div className="flex items-center gap-1">
                    Name
                    {sortColumn === 'name' && (
                      <span>{sortDirection === 'asc' ? '↑' : '↓'}</span>
                    )}
                  </div>
                </th>
              )}
              {visibleColumns.category && (
                <th 
                  onClick={() => handleSort('category')}
                  className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100"
                >
                  <div className="flex items-center gap-1">
                    Category
                    {sortColumn === 'category' && (
                      <span>{sortDirection === 'asc' ? '↑' : '↓'}</span>
                    )}
                  </div>
                </th>
              )}
              {visibleColumns.uom && (
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">UOM</th>
              )}
              {visibleColumns.hsn_code && (
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">HSN</th>
              )}
              {visibleColumns.uid_tracking && (
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">UID</th>
              )}
              {visibleColumns.drawing_required && (
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Drawing</th>
              )}
              {visibleColumns.total_stock && (
                <th 
                  onClick={() => handleSort('total_stock')}
                  className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100"
                >
                  <div className="flex items-center justify-end gap-1">
                    Stock
                    {sortColumn === 'total_stock' && (
                      <span>{sortDirection === 'asc' ? '↑' : '↓'}</span>
                    )}
                  </div>
                </th>
              )}
              {visibleColumns.standard_cost && (
                <th 
                  onClick={() => handleSort('standard_cost')}
                  className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100"
                >
                  <div className="flex items-center gap-1">
                    Cost
                    {sortColumn === 'standard_cost' && (
                      <span>{sortDirection === 'asc' ? '↑' : '↓'}</span>
                    )}
                  </div>
                </th>
              )}
              {visibleColumns.selling_price && (
                <th 
                  onClick={() => handleSort('selling_price')}
                  className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100"
                >
                  <div className="flex items-center gap-1">
                    Price
                    {sortColumn === 'selling_price' && (
                      <span>{sortDirection === 'asc' ? '↑' : '↓'}</span>
                    )}
                  </div>
                </th>
              )}
              {visibleColumns.is_active && (
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Status</th>
              )}
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Actions</th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {paginatedItems.length === 0 ? (
              <tr>
                <td colSpan={visibleColumnsCount + 1} className="px-6 py-12 text-center text-gray-500">
                  <p className="text-lg">No items found</p>
                  <p className="text-sm mt-2">Create your first item to get started</p>
                </td>
              </tr>
            ) : (
              paginatedItems.map((item) => (
                <tr key={item.id} className="hover:bg-gray-50">
                  {visibleColumns.code && (
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{item.code}</td>
                  )}
                  {visibleColumns.name && (
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">{item.name}</td>
                  )}
                  {visibleColumns.category && (
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {item.category ? item.category.replace(/_/g, ' ') : 'N/A'}
                    </td>
                  )}
                  {visibleColumns.uom && (
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{item.uom}</td>
                  )}
                  {visibleColumns.hsn_code && (
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {item.hsn_code || '-'}
                    </td>
                  )}
                  {visibleColumns.uid_tracking && (
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`px-2 py-1 text-xs rounded-full ${
                        item.uid_tracking !== false
                          ? 'bg-green-100 text-green-800'
                          : 'bg-gray-100 text-gray-800'
                      }`}>
                        {item.uid_tracking !== false ? 'YES' : 'NO'}
                      </span>
                    </td>
                  )}
                  {visibleColumns.drawing_required && (
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`px-2 py-1 text-xs rounded-full ${
                        (item.drawing_required || 'OPTIONAL') === 'COMPULSORY'
                          ? 'bg-red-100 text-red-800'
                          : 'bg-gray-100 text-gray-800'
                      }`}>
                        {item.drawing_required || 'OPTIONAL'}
                      </span>
                    </td>
                  )}
                  {visibleColumns.total_stock && (
                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-semibold">
                      <span className={item.total_stock && item.total_stock > 0 ? 'text-green-700' : 'text-gray-400'}>
                        {item.total_stock ?? 0}
                      </span>
                    </td>
                  )}
                  {visibleColumns.standard_cost && (
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {item.standard_cost ? `₹${item.standard_cost.toFixed(2)}` : '-'}
                    </td>
                  )}
                  {visibleColumns.selling_price && (
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {item.selling_price ? `₹${item.selling_price.toFixed(2)}` : '-'}
                    </td>
                  )}
                  {visibleColumns.is_active && (
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`px-2 py-1 text-xs rounded-full ${
                        item.is_active 
                          ? 'bg-green-100 text-green-800' 
                          : 'bg-gray-100 text-gray-800'
                      }`}>
                        {item.is_active ? 'Active' : 'Inactive'}
                      </span>
                    </td>
                  )}
                  <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                    {item.is_active ? (
                      <>
                        <button
                          onClick={() => handleEdit(item)}
                          className="text-amber-600 hover:text-amber-900 mr-3"
                        >
                          Edit
                        </button>
                        {!item.is_variant && (
                          <button
                            onClick={() => openVariantManager(item)}
                            className="text-[#8B6F47] hover:text-[#6F4E37] mr-3"
                            title="Manage variants/brands"
                          >
                            🏷️ Variants
                          </button>
                        )}
                        <button
                          onClick={() => {
                            setSelectedItemForDrawing(item);
                            setShowDrawingManager(true);
                          }}
                          className="text-blue-600 hover:text-blue-900 mr-3"
                        >
                          Drawings
                        </button>
                        <button
                          onClick={() => handleDelete(item.id)}
                          className="text-red-600 hover:text-red-900"
                        >
                          Delete
                        </button>
                      </>
                    ) : (
                      <button
                        onClick={() => handleRestore(item.id)}
                        className="text-green-600 hover:text-green-900 font-medium"
                      >
                        ↻ Restore
                      </button>
                    )}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
        
        {/* Pagination Controls */}
        {totalItems > 0 && (
          <div className="px-6 py-4 bg-gray-50 border-t border-gray-200 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <span className="text-sm text-gray-700">
                Showing {startIndex + 1} to {Math.min(endIndex, totalItems)} of {totalItems} items
              </span>
              <select
                value={itemsPerPage}
                onChange={(e) => {
                  setItemsPerPage(Number(e.target.value));
                  setCurrentPage(1);
                }}
                className="px-2 py-1 border border-gray-300 rounded text-sm"
              >
                <option value={10}>10 per page</option>
                <option value={25}>25 per page</option>
                <option value={50}>50 per page</option>
                <option value={100}>100 per page</option>
              </select>
            </div>
            
            <div className="flex items-center gap-2">
              <button
                onClick={() => goToPage(1)}
                disabled={currentPage === 1}
                className="px-3 py-1 border border-gray-300 rounded text-sm hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                First
              </button>
              <button
                onClick={() => goToPage(currentPage - 1)}
                disabled={currentPage === 1}
                className="px-3 py-1 border border-gray-300 rounded text-sm hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Previous
              </button>
              
              {/* Page Numbers */}
              <div className="flex gap-1">
                {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                  let pageNum;
                  if (totalPages <= 5) {
                    pageNum = i + 1;
                  } else if (currentPage <= 3) {
                    pageNum = i + 1;
                  } else if (currentPage >= totalPages - 2) {
                    pageNum = totalPages - 4 + i;
                  } else {
                    pageNum = currentPage - 2 + i;
                  }
                  
                  return (
                    <button
                      key={pageNum}
                      onClick={() => goToPage(pageNum)}
                      className={`px-3 py-1 border rounded text-sm ${
                        currentPage === pageNum
                          ? 'bg-amber-600 text-white border-amber-600'
                          : 'border-gray-300 hover:bg-gray-100'
                      }`}
                    >
                      {pageNum}
                    </button>
                  );
                })}
              </div>
              
              <button
                onClick={() => goToPage(currentPage + 1)}
                disabled={currentPage === totalPages}
                className="px-3 py-1 border border-gray-300 rounded text-sm hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Next
              </button>
              <button
                onClick={() => goToPage(totalPages)}
                disabled={currentPage === totalPages}
                className="px-3 py-1 border border-gray-300 rounded text-sm hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Last
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Create/Edit Form Modal */}
      {showForm && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-lg max-w-2xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6">
              <h2 className="text-2xl font-bold mb-6">
                {editingItem ? 'Edit Item' : 'Create New Item'}
              </h2>
              
              <form onSubmit={handleSubmit} className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Item Code *
                    </label>
                    <input
                      type="text"
                      required
                      value={formData.code}
                      onChange={(e) => setFormData({ ...formData, code: e.target.value })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                      placeholder="e.g., RM001"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Item Name *
                    </label>
                    <input
                      type="text"
                      required
                      value={formData.name}
                      onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                      placeholder="e.g., Steel Sheet"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Description
                  </label>
                  <textarea
                    value={formData.description}
                    onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                    rows={2}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                    placeholder="Optional description"
                  />
                </div>

                <div className="grid grid-cols-3 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Category *
                    </label>
                    <select
                      required
                      value={formData.category}
                      onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                    >
                      {categories.map(cat => (
                        <option key={cat.id} value={cat.name}>{cat.name.replace(/_/g, ' ')}</option>
                      ))}
                    </select>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Unit of Measure *
                    </label>
                    <select
                      required
                      value={formData.uom}
                      onChange={(e) => setFormData({ ...formData, uom: e.target.value })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                    >
                      {uomOptions.map(uom => (
                        <option key={uom} value={uom}>{uom}</option>
                      ))}
                    </select>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      HSN Code *
                    </label>
                    <input
                      type="text"
                      required
                      inputMode="numeric"
                      maxLength={8}
                      pattern="^([0-9]{4}|[0-9]{6}|[0-9]{8})$"
                      value={formData.hsn_code}
                      onChange={(e) =>
                        setFormData({ ...formData, hsn_code: e.target.value.replace(/[^0-9]/g, '') })
                      }
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                      placeholder="e.g., 8542"
                      title="HSN must be 4, 6, or 8 digits"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Standard Cost (₹)
                    </label>
                    <input
                      type="number"
                      step="0.01"
                      value={formData.standard_cost}
                      onChange={(e) => setFormData({ ...formData, standard_cost: e.target.value })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                      placeholder="0.00"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Selling Price (₹)
                    </label>
                    <input
                      type="number"
                      step="0.01"
                      value={formData.selling_price}
                      onChange={(e) => setFormData({ ...formData, selling_price: e.target.value })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                      placeholder="0.00"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-3 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Reorder Level
                    </label>
                    <input
                      type="number"
                      value={formData.reorder_level}
                      onChange={(e) => setFormData({ ...formData, reorder_level: e.target.value })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                      placeholder="0"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Reorder Qty
                    </label>
                    <input
                      type="number"
                      value={formData.reorder_quantity}
                      onChange={(e) => setFormData({ ...formData, reorder_quantity: e.target.value })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                      placeholder="0"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Lead Time (days)
                    </label>
                    <input
                      type="number"
                      value={formData.lead_time_days}
                      onChange={(e) => setFormData({ ...formData, lead_time_days: e.target.value })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                      placeholder="0"
                    />
                  </div>
                </div>

                <div className="flex items-center">
                  <input
                    type="checkbox"
                    id="is_active"
                    checked={formData.is_active}
                    onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
                    className="h-4 w-4 text-amber-600 focus:ring-amber-500 border-gray-300 rounded"
                  />
                  <label htmlFor="is_active" className="ml-2 block text-sm text-gray-700">
                    Active
                  </label>
                </div>

                {/* Variant/Brand Configuration Section */}
                <div className="border-t pt-4 mt-4">
                  <h3 className="text-lg font-semibold text-gray-900 mb-3">🏷️ Variant Configuration</h3>
                  <p className="text-sm text-gray-600 mb-4">
                    Create variants for items where you need to track different brands, types, or specifications.
                    Example: Create a parent item &quot;BATTERY&quot; and variants like &quot;Exide Lithium&quot;, &quot;AC Delco Alkaline&quot;, etc.
                  </p>
                  
                  <div className="flex items-start space-x-2 mb-4">
                    <input
                      type="checkbox"
                      id="is_variant"
                      checked={formData.is_variant}
                      onChange={(e) => setFormData({ ...formData, is_variant: e.target.checked })}
                      className="h-4 w-4 text-amber-600 focus:ring-amber-500 border-gray-300 rounded mt-1"
                    />
                    <div>
                      <label htmlFor="is_variant" className="block text-sm font-medium text-gray-700">
                        This is a variant/sub-product
                      </label>
                      <p className="text-xs text-gray-500">Check this if creating a specific brand/type of a generic item</p>
                    </div>
                  </div>

                  {formData.is_variant && (
                    <div className="bg-yellow-50 p-4 rounded-lg space-y-4 border border-yellow-200">
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">
                          Parent Item *
                        </label>
                        <select
                          required={formData.is_variant}
                          value={formData.parent_item_id}
                          onChange={(e) => setFormData({ ...formData, parent_item_id: e.target.value })}
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                        >
                          <option value="">Select parent item...</option>
                          {items.filter(i => !i.is_variant && i.id !== editingItem?.id).map(item => (
                            <option key={item.id} value={item.id}>
                              {item.code} - {item.name}
                            </option>
                          ))}
                        </select>
                        <p className="text-xs text-gray-500 mt-1">
                          Select the generic item this is a variant of (e.g., select &quot;BATTERY&quot; for &quot;Exide Lithium Battery&quot;)
                        </p>
                      </div>

                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">
                          Variant/Brand Name *
                        </label>
                        <input
                          type="text"
                          required={formData.is_variant}
                          value={formData.variant_name}
                          onChange={(e) => setFormData({ ...formData, variant_name: e.target.value })}
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                          placeholder="e.g., Exide Lithium 12V, AC Delco Alkaline"
                        />
                        <p className="text-xs text-gray-500 mt-1">
                          Descriptive name for this specific variant/brand
                        </p>
                      </div>

                      <div className="flex items-start space-x-2">
                        <input
                          type="checkbox"
                          id="is_default_variant"
                          checked={formData.is_default_variant}
                          onChange={(e) => setFormData({ ...formData, is_default_variant: e.target.checked })}
                          className="h-4 w-4 text-amber-600 focus:ring-amber-500 border-gray-300 rounded mt-1"
                        />
                        <div>
                          <label htmlFor="is_default_variant" className="block text-sm font-medium text-gray-700">
                            ⭐ Set as default variant
                          </label>
                          <p className="text-xs text-gray-500">
                            Default variants are automatically selected in job orders (you can change only one variant to default)
                          </p>
                        </div>
                      </div>
                    </div>
                  )}
                </div>

                {/* UID Tracking Strategy Section */}
                <div className="border-t pt-4 mt-4">
                  <h3 className="text-lg font-semibold text-gray-900 mb-3">UID Tracking</h3>
                  
                  <div className="flex items-start space-x-2 mb-4">
                    <input
                      type="checkbox"
                      id="uid_tracking"
                      checked={formData.uid_tracking}
                      onChange={(e) => setFormData({ ...formData, uid_tracking: e.target.checked })}
                      className="h-4 w-4 text-amber-600 focus:ring-amber-500 border-gray-300 rounded mt-1"
                    />
                    <div>
                      <label htmlFor="uid_tracking" className="block text-sm font-medium text-gray-700">
                        Track with UIDs
                      </label>
                      <p className="text-xs text-gray-500">Enable unique identifier tracking for this item</p>
                    </div>
                  </div>

                  {formData.uid_tracking && (
                    <div className="bg-gray-50 p-4 rounded-lg space-y-4">
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">How to track?</label>
                        <div className="space-y-2">
                          <div className="flex items-start">
                            <input
                              type="radio"
                              id="uid_serialized"
                              name="uid_strategy"
                              value="SERIALIZED"
                              checked={formData.uid_strategy === 'SERIALIZED'}
                              onChange={(e) => setFormData({ ...formData, uid_strategy: e.target.value, batch_uom: '', batch_quantity: '' })}
                              className="h-4 w-4 text-amber-600 focus:ring-amber-500 border-gray-300 mt-1"
                            />
                            <div className="ml-2">
                              <label htmlFor="uid_serialized" className="text-sm font-medium text-gray-700">
                                Track Each Piece Individually
                              </label>
                              <p className="text-xs text-gray-500">For: Parts, Components, Assemblies, Finished Goods</p>
                            </div>
                          </div>
                          
                          <div className="flex items-start">
                            <input
                              type="radio"
                              id="uid_batched"
                              name="uid_strategy"
                              value="BATCHED"
                              checked={formData.uid_strategy === 'BATCHED'}
                              onChange={(e) => setFormData({ ...formData, uid_strategy: e.target.value })}
                              className="h-4 w-4 text-amber-600 focus:ring-amber-500 border-gray-300 mt-1"
                            />
                            <div className="ml-2">
                              <label htmlFor="uid_batched" className="text-sm font-medium text-gray-700">
                                Track by Container/Box
                              </label>
                              <p className="text-xs text-gray-500">For: Screws, Washers, Nuts, Bolts, Consumables</p>
                            </div>
                          </div>
                        </div>
                      </div>

                      {formData.uid_strategy === 'BATCHED' && (
                        <div className="border-t pt-4 space-y-3">
                          <p className="text-sm font-medium text-gray-700">Container Details:</p>
                          <div className="grid grid-cols-2 gap-3">
                            <div>
                              <label className="block text-xs font-medium text-gray-600 mb-1">Container Type *</label>
                              <select
                                required
                                value={formData.batch_uom}
                                onChange={(e) => setFormData({ ...formData, batch_uom: e.target.value })}
                                className="w-full px-3 py-2 text-sm border border-gray-300 rounded-lg"
                              >
                                <option value="">Select Type</option>
                                {isVolumeUom ? (
                                  <>
                                    <option value="Drum">Drum</option>
                                    <option value="Bucket">Bucket</option>
                                    <option value="Can">Can</option>
                                    <option value="Bottle">Bottle</option>
                                    <option value="IBC">IBC</option>
                                    <option value="Container">Container</option>
                                  </>
                                ) : (
                                  <>
                                    <option value="Box">Box</option>
                                    <option value="Carton">Carton</option>
                                    <option value="Pallet">Pallet</option>
                                    <option value="Bag">Bag</option>
                                    <option value="Roll">Roll</option>
                                    <option value="Container">Container</option>
                                  </>
                                )}
                              </select>
                            </div>
                            <div>
                              <label className="block text-xs font-medium text-gray-600 mb-1">
                                Qty per {formData.batch_uom || 'Container'} ({formData.uom || 'UOM'}) *
                              </label>
                              <input
                                type="number"
                                required
                                step="any"
                                min="0.000001"
                                value={formData.batch_quantity}
                                onChange={(e) => setFormData({ ...formData, batch_quantity: e.target.value })}
                                className="w-full px-3 py-2 text-sm border border-gray-300 rounded-lg"
                                placeholder={
                                  isVolumeUom
                                    ? 'e.g. 200 (per drum/bucket)'
                                    : 'e.g. 1000'
                                }
                              />
                            </div>
                          </div>
                          <div className="bg-blue-50 p-2 rounded text-xs text-blue-800">
                            💡 You will still purchase/receive in {formData.uom || 'UOM'}. This setting is only for UID generation.
                            <br />
                            Example: If you receive 250 {formData.uom || 'UOM'} and 1 {formData.batch_uom || 'container'} holds 200 {formData.uom || 'UOM'}, system will generate 2 UIDs (one per container).
                          </div>
                        </div>
                      )}
                    </div>
                  )}
                </div>

                {/* Drawing Required Section */}
                <div className="border-t pt-4 mt-4">
                  <h3 className="text-lg font-semibold text-gray-900 mb-3">📐 Drawing & Documentation</h3>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">
                        Drawing Required
                      </label>
                      <select
                        value={formData.drawing_required}
                        onChange={(e) => setFormData({ ...formData, drawing_required: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-amber-500"
                      >
                        <option value="OPTIONAL">Optional</option>
                        <option value="COMPULSORY">Compulsory</option>
                        <option value="NOT_REQUIRED">Not Required</option>
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">
                        Upload Drawing/Spec
                      </label>
                      <input
                        type="file"
                        accept=".pdf,.png,.jpg,.jpeg,.dwg,.dxf"
                        onChange={(e) => setDrawingFile(e.target.files?.[0] || null)}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-amber-500 text-sm"
                      />
                      {(formData.drawing_file_name || drawingFile) && (
                        <p className="text-xs text-green-600 mt-1">
                          📎 {drawingFile?.name || formData.drawing_file_name}
                        </p>
                      )}

                      {!drawingFile && formData.drawing_url && (
                        <button
                          type="button"
                          onClick={() => window.open(formData.drawing_url, '_blank', 'noopener,noreferrer')}
                          className="mt-1 text-xs text-blue-700 hover:text-blue-900 underline"
                        >
                          View current drawing
                        </button>
                      )}
                    </div>
                  </div>
                </div>

                {/* Vendor Management Section */}
                <div className="border-t pt-4 mt-4">
                  <div className="flex justify-between items-center mb-3">
                    <h3 className="text-lg font-semibold text-gray-900">🏭 Preferred Vendors</h3>
                    <button
                      type="button"
                      onClick={() => setShowVendorForm(!showVendorForm)}
                      className="px-3 py-1.5 bg-blue-600 text-white text-sm rounded-lg hover:bg-blue-700"
                    >
                      {showVendorForm ? 'Cancel' : '+ Add Vendor'}
                    </button>
                  </div>

                    {showVendorForm && (
                      <div className="bg-gray-50 p-4 rounded-lg mb-4 space-y-3">
                        <div className="grid grid-cols-2 gap-3">
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Vendor *</label>
                            <select
                              value={vendorForm.vendor_id}
                              onChange={(e) => setVendorForm({ ...vendorForm, vendor_id: e.target.value })}
                              className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                              required
                            >
                              <option value="">Select Vendor</option>
                              {vendors.map(v => (
                                <option key={v.id} value={v.id}>{v.name}</option>
                              ))}
                            </select>
                          </div>
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Priority *</label>
                            <input
                              type="number"
                              min="1"
                              max="10"
                              value={vendorForm.priority}
                              onChange={(e) => setVendorForm({ ...vendorForm, priority: parseInt(e.target.value) })}
                              className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                              placeholder="1 = Preferred"
                            />
                          </div>
                        </div>
                        <div className="grid grid-cols-3 gap-3">
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Unit Price (₹)</label>
                            <input
                              type="number"
                              step="0.01"
                              value={vendorForm.unit_price}
                              onChange={(e) => setVendorForm({ ...vendorForm, unit_price: e.target.value })}
                              className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                            />
                          </div>
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Lead Time (days)</label>
                            <input
                              type="number"
                              value={vendorForm.lead_time_days}
                              onChange={(e) => setVendorForm({ ...vendorForm, lead_time_days: e.target.value })}
                              className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                            />
                          </div>
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Vendor Item Code</label>
                            <input
                              type="text"
                              value={vendorForm.vendor_item_code}
                              onChange={(e) => setVendorForm({ ...vendorForm, vendor_item_code: e.target.value })}
                              className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                            />
                          </div>
                        </div>
                        <button
                          type="button"
                          onClick={addItemVendor}
                          className="w-full px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 text-sm"
                        >
                          Add Vendor
                        </button>
                      </div>
                    )}

                    {itemVendors.length > 0 ? (
                      <div className="space-y-2">
                        {itemVendors.map((iv: any) => {
                          const vendor = vendors.find(v => v.id === iv.vendor_id);
                          return (
                            <div key={iv.vendor_id} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                              <div className="flex-1">
                                <div className="flex items-center gap-2">
                                  <span className="font-medium text-gray-900">{vendor?.name || iv.vendor_name}</span>
                                  {iv.is_preferred && (
                                    <span className="px-2 py-0.5 bg-green-100 text-green-800 text-xs font-medium rounded">
                                      Preferred
                                    </span>
                                  )}
                                  <span className="text-xs text-gray-500">Priority: {iv.priority}</span>
                                </div>
                                <div className="text-sm text-gray-600 mt-1">
                                  {iv.unit_price && <span>₹{iv.unit_price}</span>}
                                  {iv.unit_price && iv.lead_time_days && <span className="mx-2">•</span>}
                                  {iv.lead_time_days && <span>{iv.lead_time_days} days lead time</span>}
                                  {iv.vendor_item_code && (
                                    <>
                                      <span className="mx-2">•</span>
                                      <span>Code: {iv.vendor_item_code}</span>
                                    </>
                                  )}
                                </div>
                              </div>
                              <button
                                type="button"
                                onClick={() => removeItemVendor(iv.vendor_id)}
                                className="text-red-600 hover:text-red-800 text-sm font-medium ml-4"
                              >
                                Remove
                              </button>
                            </div>
                          );
                        })}
                      </div>
                    ) : (
                      <p className="text-sm text-gray-500 text-center py-4">No vendors assigned yet</p>
                    )}
                </div>

                <div className="flex justify-end gap-3 mt-6">
                  <button
                    type="button"
                    onClick={() => {
                      setShowForm(false);
                      setEditingItem(null);
                      resetForm();
                    }}
                    className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700"
                  >
                    {editingItem ? 'Update' : 'Create'} Item
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}

      {/* Drawing Manager Modal */}
      {showDrawingManager && selectedItemForDrawing && (
        <DrawingManager
          itemId={selectedItemForDrawing.id}
          itemCode={selectedItemForDrawing.code}
          itemName={selectedItemForDrawing.name}
          onClose={() => {
            setShowDrawingManager(false);
            setSelectedItemForDrawing(null);
          }}
          mandatory={false}
        />
      )}

      {/* Category Manager Modal */}
      {showCategoryManager && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-xl p-8 max-w-2xl w-full mx-4 max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold text-gray-800">Manage Categories</h2>
              <button
                onClick={() => setShowCategoryManager(false)}
                className="text-gray-500 hover:text-gray-700 text-2xl"
              >
                ×
              </button>
            </div>

            {/* Add New Category */}
            <div className="mb-6 p-4 bg-gray-50 rounded-lg">
              <div className="flex items-center justify-between mb-3">
                <h3 className="font-semibold text-gray-700">Add New Category</h3>
                <button
                  onClick={seedCategories}
                  className="px-4 py-1 bg-amber-600 text-white text-sm rounded hover:bg-amber-700"
                >
                  🔄 Restore Defaults
                </button>
              </div>
              <div className="flex gap-2">
                <input
                  type="text"
                  value={newCategory}
                  onChange={(e) => setNewCategory(e.target.value)}
                  placeholder="Enter category name (e.g., TOOLS)"
                  className="flex-1 px-4 py-2 border rounded-lg"
                  onKeyPress={(e) => e.key === 'Enter' && addCategory()}
                />
                <button
                  onClick={addCategory}
                  className="px-6 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700"
                >
                  Add
                </button>
              </div>
              <p className="text-sm text-gray-500 mt-2">
                Categories will be automatically formatted (spaces become underscores, uppercase)
              </p>
            </div>

            {/* Categories List */}
            <div>
              <h3 className="font-semibold text-gray-700 mb-3">Current Categories</h3>
              <div className="space-y-2">
                {categories.map((category) => (
                  <div
                    key={category.id}
                    className="flex items-center justify-between p-3 bg-white border rounded-lg hover:bg-gray-50"
                  >
                    {editingCategory?.id === category.id ? (
                      <input
                        type="text"
                        value={editingCategory?.name || ''}
                        onChange={(e) =>
                          setEditingCategory({ id: category.id, name: e.target.value })
                        }
                        className="flex-1 px-3 py-1 border rounded mr-2"
                        onKeyPress={(e) => e.key === 'Enter' && updateCategory()}
                      />
                    ) : (
                      <span className="font-medium text-gray-800">
                        {category.name.replace(/_/g, ' ')}
                      </span>
                    )}
                    <div className="flex gap-2">
                      {editingCategory?.id === category.id ? (
                        <>
                          <button
                            onClick={updateCategory}
                            className="px-3 py-1 bg-green-600 text-white rounded hover:bg-green-700 text-sm"
                          >
                            Save
                          </button>
                          <button
                            onClick={() => setEditingCategory(null)}
                            className="px-3 py-1 bg-gray-400 text-white rounded hover:bg-gray-500 text-sm"
                          >
                            Cancel
                          </button>
                        </>
                      ) : (
                        <>
                          <button
                            onClick={() => setEditingCategory({ id: category.id, name: category.name })}
                            className="px-3 py-1 bg-blue-600 text-white rounded hover:bg-blue-700 text-sm"
                          >
                            Edit
                          </button>
                          <button
                            onClick={() => deleteCategory(category.id, category.name)}
                            className="px-3 py-1 bg-red-600 text-white rounded hover:bg-red-700 text-sm"
                          >
                            Delete
                          </button>
                        </>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="mt-6 pt-4 border-t">
              <button
                onClick={() => setShowCategoryManager(false)}
                className="w-full px-6 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Variant Manager Modal */}
      {showVariantManager && selectedParentItem && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-5xl max-h-[90vh] overflow-hidden flex flex-col">
            <div className="bg-gradient-to-r from-[#8B6F47] to-[#6F4E37] text-white px-6 py-4">
              <div className="flex justify-between items-center">
                <div>
                  <h2 className="text-2xl font-bold">🏷️ Manage Variants</h2>
                  <p className="text-[#FAF9F6] text-sm mt-1">
                    Parent: {selectedParentItem.code} - {selectedParentItem.name}
                  </p>
                </div>
                <button
                  onClick={() => {
                    setShowVariantManager(false);
                    setSelectedParentItem(null);
                    setVariants([]);
                    setNewVariant({ code: '', name: '', variant_name: '', is_default: false });
                  }}
                  className="text-white hover:text-gray-200 text-3xl font-bold"
                >
                  ×
                </button>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-6">
              {/* Add New Variant Form */}
              <div className="bg-yellow-50 border-2 border-yellow-200 rounded-lg p-4 mb-6">
                <h3 className="font-semibold text-lg mb-3">➕ Add New Variant</h3>
                <div className="grid grid-cols-4 gap-3 mb-3">
                  <div>
                    <label className="block text-xs font-medium text-gray-700 mb-1">Item Code *</label>
                    <input
                      type="text"
                      value={newVariant.code}
                      onChange={(e) => setNewVariant({ ...newVariant, code: e.target.value })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                      placeholder="e.g., BAT-EXIDE"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-gray-700 mb-1">Item Name *</label>
                    <input
                      type="text"
                      value={newVariant.name}
                      onChange={(e) => setNewVariant({ ...newVariant, name: e.target.value })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                      placeholder="e.g., Exide Battery"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-gray-700 mb-1">Variant/Brand Name *</label>
                    <input
                      type="text"
                      value={newVariant.variant_name}
                      onChange={(e) => setNewVariant({ ...newVariant, variant_name: e.target.value })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                      placeholder="e.g., Exide Lithium 12V"
                    />
                  </div>
                  <div className="flex items-end">
                    <label className="flex items-center space-x-2 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={newVariant.is_default}
                        onChange={(e) => setNewVariant({ ...newVariant, is_default: e.target.checked })}
                        className="h-4 w-4 text-[#8B6F47] focus:ring-[#8B6F47] border-gray-300 rounded"
                      />
                      <span className="text-sm font-medium text-gray-700">⭐ Default</span>
                    </label>
                  </div>
                </div>
                <button
                  onClick={addVariantQuick}
                  className="w-full px-4 py-2 bg-[#8B6F47] text-white rounded-lg hover:bg-[#6F4E37] font-medium"
                >
                  ➕ Add Variant
                </button>
                <p className="text-xs text-gray-500 mt-2">
                  💡 Inherits category ({selectedParentItem.category}), UOM ({selectedParentItem.uom}), and HSN ({selectedParentItem.hsn_code}) from parent
                </p>
              </div>

              {/* Existing Variants List */}
              <div>
                <h3 className="font-semibold text-lg mb-3">
                  Existing Variants ({variants.length})
                </h3>
                
                {variants.length === 0 ? (
                  <div className="text-center py-8 text-gray-500">
                    <p className="text-lg">No variants created yet</p>
                    <p className="text-sm">Add your first variant above to get started</p>
                  </div>
                ) : (
                  <div className="space-y-2">
                    {variants.map((variant) => (
                      <div
                        key={variant.id}
                        className={`flex items-center justify-between p-4 rounded-lg border-2 ${
                          variant.is_default_variant
                            ? 'bg-green-50 border-green-300'
                            : 'bg-white border-gray-200'
                        }`}
                      >
                        <div className="flex-1">
                          <div className="flex items-center space-x-2">
                            {variant.is_default_variant && (
                              <span className="text-xl" title="Default variant">⭐</span>
                            )}
                            <div>
                              <div className="font-semibold text-gray-900">
                                {variant.code} - {variant.name}
                              </div>
                              <div className="text-sm text-gray-600">
                                Brand: <span className="font-medium">{variant.variant_name}</span>
                              </div>
                            </div>
                          </div>
                        </div>
                        <div className="flex items-center space-x-2">
                          <button
                            onClick={() => toggleDefaultVariant(variant.id, variant.is_default_variant || false)}
                            className={`px-3 py-1 text-sm rounded-lg font-medium ${
                              variant.is_default_variant
                                ? 'bg-gray-200 text-gray-600 hover:bg-gray-300'
                                : 'bg-green-100 text-green-700 hover:bg-green-200'
                            }`}
                            title={variant.is_default_variant ? 'Remove default' : 'Set as default'}
                          >
                            {variant.is_default_variant ? '✓ Default' : 'Set Default'}
                          </button>
                          <button
                            onClick={() => handleEdit(variant)}
                            className="px-3 py-1 text-sm bg-blue-100 text-blue-700 rounded-lg hover:bg-blue-200 font-medium"
                          >
                            Edit
                          </button>
                          <button
                            onClick={() => deleteVariant(variant.id)}
                            className="px-3 py-1 text-sm bg-red-100 text-red-700 rounded-lg hover:bg-red-200 font-medium"
                          >
                            Delete
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>

            <div className="border-t px-6 py-4 bg-gray-50">
              <button
                onClick={() => {
                  setShowVariantManager(false);
                  setSelectedParentItem(null);
                  setVariants([]);
                  setNewVariant({ code: '', name: '', variant_name: '', is_default: false });
                }}
                className="w-full px-6 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 font-medium"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Bulk Inventory Modal */}
      {showBulkInventory && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-lg max-w-6xl w-full max-h-[90vh] overflow-hidden flex flex-col">
            <div className="p-6 border-b border-gray-200">
              <h2 className="text-2xl font-bold text-gray-900">📦 Bulk Inventory Entry</h2>
              <p className="text-sm text-gray-600 mt-1">
                Enter quantities for items you want to add to inventory. Leave blank to skip.
              </p>
            </div>

            <div className="flex-1 overflow-y-auto p-6">
              <div className="space-y-1">
                <div className="grid grid-cols-5 gap-4 text-sm font-semibold text-gray-700 pb-2 border-b">
                  <div>Item Code</div>
                  <div className="col-span-2">Item Name</div>
                  <div>Quantity</div>
                  <div>Location</div>
                </div>
                
                {bulkInventoryItems.map((item, index) => (
                  <div key={item.itemId} className="grid grid-cols-5 gap-4 py-2 border-b border-gray-100 hover:bg-gray-50">
                    <div className="text-sm font-medium text-gray-700">{item.itemCode}</div>
                    <div className="col-span-2 text-sm text-gray-600">{item.itemName}</div>
                    <div>
                      <input
                        type="number"
                        step="0.01"
                        value={item.quantity}
                        onChange={(e) => {
                          const newItems = [...bulkInventoryItems];
                          newItems[index].quantity = e.target.value;
                          setBulkInventoryItems(newItems);
                        }}
                        className="w-full px-2 py-1 text-sm border border-gray-300 rounded focus:ring-2 focus:ring-blue-500"
                        placeholder="0"
                      />
                    </div>
                    <div>
                      <select
                        value={item.location}
                        onChange={(e) => {
                          const newItems = [...bulkInventoryItems];
                          newItems[index].location = e.target.value;
                          setBulkInventoryItems(newItems);
                        }}
                        className="w-full px-2 py-1 text-sm border border-gray-300 rounded focus:ring-2 focus:ring-blue-500"
                      >
                        <option value="MAIN_WAREHOUSE">Main Warehouse</option>
                        <option value="PRODUCTION_FLOOR">Production Floor</option>
                        <option value="QC_AREA">QC Area</option>
                        <option value="FINISHED_GOODS">Finished Goods</option>
                      </select>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="p-6 border-t border-gray-200 flex gap-4">
              <button
                onClick={() => {
                  setShowBulkInventory(false);
                  setBulkInventoryItems([]);
                }}
                className="flex-1 px-6 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 font-medium"
              >
                Cancel
              </button>
              <button
                onClick={handleBulkInventorySubmit}
                className="flex-1 px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-medium"
              >
                Add Inventory
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Duplicate Warning Modal */}
      <DuplicateWarning
        isOpen={duplicateState.isOpen}
        exactMatches={duplicateState.exactMatches}
        fuzzyMatches={duplicateState.fuzzyMatches}
        entityType="Item"
        onProceed={handleProceed}
        onCancel={handleCancel}
        formatRecord={(data) => (
          <div className="text-sm">
            <p className="font-semibold">{data.name || data.item_name}</p>
            <p className="text-xs text-gray-600">Code: {data.code || data.item_code}</p>
            <p className="text-xs text-gray-600">Drawing: {data.drawing_number || 'N/A'}</p>
            <p className="text-xs text-gray-600 line-clamp-2">{data.description}</p>
          </div>
        )}
      />
    </div>
  );
}

'use client';
export const dynamic = 'force-dynamic';
export const fetchCache = 'force-no-store';

import { Suspense, useEffect, useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { apiClient } from '../../../../lib/api-client';
import { useSelection } from '../../../hooks/useSelection';

interface StockLevel {
  id: string;
  item_id: string;
  warehouse_id: string;
  quantity: number;
  available_quantity: number;
  allocated_quantity: number;
  unit_price?: number;
  batch_number?: string;
  items: {
    code: string;
    name: string;
    uom: string;
    category: string;
    standard_cost?: number;
    selling_price?: number;
  };
  warehouses: {
    code: string;
    name: string;
  };
}

interface StockMovement {
  id: string;
  movement_number: string;
  movement_type: string;
  quantity: number;
  uid?: string;
  movement_date: string;
  reference_number?: string;
  notes?: string;
  items: {
    code: string;
    name: string;
  };
  from_warehouse?: {
    code: string;
    name: string;
  };
  to_warehouse?: {
    code: string;
    name: string;
  };
}

interface Alert {
  id: string;
  alert_type: string;
  severity: string;
  message: string;
  acknowledged: boolean;
  created_at: string;
  items?: {
    item_code?: string | null;
    item_name?: string | null;
  } | null;
  warehouses?: {
    warehouse_code: string;
    warehouse_name: string;
  };
}

interface DemoItem {
  id: string;
  demo_id: string;
  uid: string;
  customer_name: string;
  customer_contact: string;
  issue_date: string;
  expected_return_date?: string;
  status: string;
  demo_expenses: number;
  items?: {
    item_code?: string | null;
    item_name?: string | null;
  } | null;
}

export default function InventoryPage() {
  return (
    <Suspense
      fallback={
        <div className="p-6">
          <div className="text-xl">Loading...</div>
        </div>
      }
    >
      <InventoryPageContent />
    </Suspense>
  );
}

function InventoryPageContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const tabParam = searchParams.get('tab');
  
  const [activeTab, setActiveTab] = useState<'movements' | 'alerts' | 'demo'>(
    (tabParam as 'movements' | 'alerts' | 'demo') || 'movements'
  );
  const [movements, setMovements] = useState<StockMovement[]>([]);
  const [alerts, setAlerts] = useState<Alert[]>([]);
  const [demoItems, setDemoItems] = useState<DemoItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [emailModal, setEmailModal] = useState(false);
  const [recipientEmail, setRecipientEmail] = useState('');
  const [sendingEmail, setSendingEmail] = useState(false);

  const movementSelection = useSelection(movements);
  const alertSelection = useSelection(alerts);
  const demoSelection = useSelection(demoItems);

  // Update tab when URL parameter changes
  useEffect(() => {
    if (tabParam && ['movements', 'alerts', 'demo'].includes(tabParam)) {
      setActiveTab(tabParam as 'movements' | 'alerts' | 'demo');
    }
  }, [tabParam]);

  useEffect(() => {
    fetchData();
  }, [activeTab]);

  const fetchData = async () => {
    setLoading(true);
    try {
      if (activeTab === 'movements') {
        const data = await apiClient.get('/inventory/movements', { limit: 50 });
        setMovements(Array.isArray(data) ? data : []);
      } else if (activeTab === 'alerts') {
        const data = await apiClient.get('/inventory/alerts', { acknowledged: false });
        setAlerts(Array.isArray(data) ? data : []);
      } else if (activeTab === 'demo') {
        const data = await apiClient.get('/inventory/demo');
        setDemoItems(Array.isArray(data) ? data : []);
      }
    } catch (error) {
      console.error('Error fetching data:', error);
    } finally {
      setLoading(false);
    }
  };

  const acknowledgeAlert = async (alertId: string) => {
    try {
      await apiClient.put(`/inventory/alerts/${alertId}/acknowledge`);
      fetchData();
    } catch (error) {
      console.error('Error acknowledging alert:', error);
    }
  };

  const sendLowStockEmail = async () => {
    if (!recipientEmail) {
      alert('Please enter a recipient email address');
      return;
    }

    setSendingEmail(true);
    try {
      const result = await apiClient.post('/inventory/alerts/send-email', { recipientEmail });
      alert(`Email sent successfully to ${recipientEmail}. ${result.itemCount} low stock items included.`);
      setEmailModal(false);
      setRecipientEmail('');
    } catch (error: any) {
      console.error('Error sending email:', error);
      alert(error.response?.data?.message || 'Failed to send email');
    } finally {
      setSendingEmail(false);
    }
  };

  const checkAllLowStock = async () => {
    try {
      const result = await apiClient.post('/inventory/alerts/check-low-stock');
      alert(result.message);
      fetchData();
    } catch (error: any) {
      console.error('Error checking low stock:', error);
      alert('Failed to check low stock');
    }
  };

  const checkJobOrderAlerts = async () => {
    try {
      console.log('[Frontend] Calling check-job-orders endpoint...');
      const result = await apiClient.post('/inventory/alerts/check-job-orders');
      console.log('[Frontend] Check job orders result:', result);
      alert(result.message);
      fetchData();
    } catch (error: any) {
      console.error('[Frontend] Error checking job orders:', error);
      console.error('[Frontend] Error response:', error.response);
      console.error('[Frontend] Error data:', error.response?.data);
      const errorMessage = error.response?.data?.message || error.message || 'Failed to check job orders';
      alert(`Error: ${errorMessage}`);
    }
  };

  const deleteMovements = async (ids: string[]) => {
    if (!confirm(`Are you sure you want to delete ${ids.length} movements? This action cannot be undone.`)) return;
    try {
      await Promise.all(ids.map(id => apiClient.delete(`/inventory/movements/${id}`)));
      movementSelection.deselectAll();
      fetchData();
    } catch (error) {
      console.error('Error deleting movements:', error);
    }
  };

  const deleteAlerts = async (ids: string[]) => {
    if (!confirm(`Are you sure you want to delete ${ids.length} alerts? This action cannot be undone.`)) return;
    try {
      await Promise.all(ids.map(id => apiClient.delete(`/inventory/alerts/${id}`)));
      alertSelection.deselectAll();
      fetchData();
    } catch (error) {
      console.error('Error deleting alerts:', error);
    }
  };

  const deleteDemoItems = async (ids: string[]) => {
    if (!confirm(`Are you sure you want to delete ${ids.length} demo items? This action cannot be undone.`)) return;
    try {
      await Promise.all(ids.map(id => apiClient.delete(`/inventory/demo/${id}`)));
      demoSelection.deselectAll();
      fetchData();
    } catch (error) {
      console.error('Error deleting demo items:', error);
    }
  };

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'CRITICAL': return 'text-red-600 bg-red-50';
      case 'HIGH': return 'text-orange-600 bg-orange-50';
      case 'MEDIUM': return 'text-yellow-600 bg-yellow-50';
      default: return 'text-amber-600 bg-amber-50';
    }
  };

  const getCategoryColor = (category: string) => {
    switch (category) {
      case 'RAW_MATERIAL': return 'bg-blue-100 text-blue-800';
      case 'WIP': return 'bg-yellow-100 text-yellow-800';
      case 'FINISHED_GOODS': return 'bg-green-100 text-green-800';
      case 'DEMO': return 'bg-purple-100 text-purple-800';
      case 'SERVICE_SPARES': return 'bg-orange-100 text-orange-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'ISSUED': return 'bg-blue-100 text-blue-800';
      case 'RETURNED': return 'bg-green-100 text-green-800';
      case 'SOLD': return 'bg-purple-100 text-purple-800';
      case 'DAMAGED': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <div className="p-6">
      <div className="mb-6">
        <button
          onClick={() => router.push('/dashboard')}
          className="text-amber-600 hover:text-amber-800 text-sm mb-2"
        >
          ← Back to Dashboard
        </button>
        <h1 className="text-2xl font-bold text-gray-900">Inventory Management</h1>
        <p className="text-gray-600">Stock levels, movements, alerts, and demo inventory</p>
      </div>

      {/* Tabs */}
      <div className="border-b border-gray-200 mb-6">
        <nav className="-mb-px flex space-x-8">
          <button
            onClick={() => router.push('/dashboard/inventory/items')}
            className="py-4 px-1 border-b-2 font-medium text-sm border-transparent text-gray-500 hover:text-amber-600 hover:border-amber-300"
          >
            Items Master
          </button>
          <button
            onClick={() => setActiveTab('movements')}
            className={`py-4 px-1 border-b-2 font-medium text-sm ${
              activeTab === 'movements'
                ? 'border-amber-500 text-amber-600'
                : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
            }`}
          >
            Movements
          </button>
          <button
            onClick={() => setActiveTab('alerts')}
            className={`py-4 px-1 border-b-2 font-medium text-sm relative ${
              activeTab === 'alerts'
                ? 'border-amber-500 text-amber-600'
                : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
            }`}
          >
            Alerts
            {alerts.length > 0 && (
              <span className="ml-2 px-2 py-0.5 text-xs bg-red-100 text-red-800 rounded-full">
                {alerts.length}
              </span>
            )}
          </button>
          <button
            onClick={() => setActiveTab('demo')}
            className={`py-4 px-1 border-b-2 font-medium text-sm ${
              activeTab === 'demo'
                ? 'border-amber-500 text-amber-600'
                : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
            }`}
          >
            Demo Inventory
          </button>
        </nav>
      </div>

      {/* Movements Tab */}
      {activeTab === 'movements' && (
        <div className="bg-white rounded-lg shadow overflow-hidden">
          {movements.length > 0 && (
            <div className="px-6 py-4 border-b border-gray-200 bg-gray-50">
              <div className="flex items-center justify-between">
                <label className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={movementSelection.isAllSelected}
                    onChange={movementSelection.toggleSelectAll}
                    className="w-4 h-4"
                  />
                  <span className="text-sm font-medium text-gray-700">
                    Select All ({movements.length} movements)
                  </span>
                </label>
                {movementSelection.hasSelections && (
                  <div className="flex gap-2">
                    <button
                      onClick={() => deleteMovements(Array.from(movementSelection.selectedIds))}
                      className="px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700 text-sm"
                    >
                      Delete Selected ({movementSelection.selectedItems.length})
                    </button>
                    <button
                      onClick={movementSelection.deselectAll}
                      className="px-4 py-2 bg-gray-600 text-white rounded hover:bg-gray-700 text-sm"
                    >
                      Deselect All
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase w-12"></th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Movement #</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Type</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Item</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">From</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">To</th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">Quantity</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">UID</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Date</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {loading ? (
                <tr>
                  <td colSpan={9} className="px-6 py-4 text-center text-gray-500">
                    Loading...
                  </td>
                </tr>
              ) : movements.length === 0 ? (
                <tr>
                  <td colSpan={9} className="px-6 py-4 text-center text-gray-500">
                    No movements found
                  </td>
                </tr>
              ) : (
                movements.map((movement) => (
                  <tr key={movement.id} className={`hover:bg-gray-50 ${movementSelection.isSelected(movement.id) ? 'bg-amber-50' : ''}`}>
                    <td className="px-6 py-4">
                      <input
                        type="checkbox"
                        checked={movementSelection.isSelected(movement.id)}
                        onChange={() => movementSelection.toggleSelection(movement.id)}
                        className="w-4 h-4"
                      />
                    </td>
                    <td className="px-6 py-4">
                      <div className="text-sm font-medium text-gray-900">{movement.movement_number}</div>
                      {movement.reference_number && (
                        <div className="text-sm text-gray-500">Ref: {movement.reference_number}</div>
                      )}
                    </td>
                    <td className="px-6 py-4">
                      <span className="text-sm text-gray-900">
                        {movement.movement_type.replace(/_/g, ' ')}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <div className="text-sm text-gray-900">{movement.items.name}</div>
                      <div className="text-sm text-gray-500">{movement.items.code}</div>
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-500">
                      {movement.from_warehouse?.name || '-'}
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-500">
                      {movement.to_warehouse?.name || '-'}
                    </td>
                    <td className="px-6 py-4 text-right text-sm text-gray-900">
                      {movement.quantity}
                    </td>
                    <td className="px-6 py-4">
                      {movement.uid ? (
                        <span className="text-sm font-mono text-amber-600">{movement.uid}</span>
                      ) : (
                        <span className="text-sm text-gray-400">-</span>
                      )}
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-500">
                      {new Date(movement.movement_date).toLocaleString()}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      )}

      {/* Alerts Tab */}
      {activeTab === 'alerts' && (
        <div>
          <div className="mb-4 p-4 bg-white rounded-lg shadow">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                {alerts.length > 0 && (
                  <label className="flex items-center gap-2">
                    <input
                      type="checkbox"
                      checked={alertSelection.isAllSelected}
                      onChange={alertSelection.toggleSelectAll}
                      className="w-4 h-4"
                    />
                    <span className="text-sm font-medium text-gray-700">
                      Select All ({alerts.length} alerts)
                    </span>
                  </label>
                )}
              </div>
              <div className="flex gap-2">
                <button
                  onClick={checkAllLowStock}
                  className="px-4 py-2 bg-amber-600 text-white rounded hover:bg-amber-700 text-sm flex items-center gap-2"
                >
                  🔍 Check Stock
                </button>
                <button
                  onClick={checkJobOrderAlerts}
                  className="px-4 py-2 bg-purple-600 text-white rounded hover:bg-purple-700 text-sm flex items-center gap-2"
                >
                  📋 Check Jobs
                </button>
                {alerts.length > 0 && (
                  <>
                    <button
                      onClick={() => setEmailModal(true)}
                      className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 text-sm flex items-center gap-2"
                    >
                      📧 Email Alert
                    </button>
                    {alertSelection.hasSelections && (
                      <>
                        <button
                          onClick={() => deleteAlerts(Array.from(alertSelection.selectedIds))}
                          className="px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700 text-sm"
                        >
                          Delete Selected ({alertSelection.selectedItems.length})
                        </button>
                        <button
                          onClick={alertSelection.deselectAll}
                          className="px-4 py-2 bg-gray-600 text-white rounded hover:bg-gray-700 text-sm"
                        >
                          Deselect All
                        </button>
                      </>
                    )}
                  </>
                )}
              </div>
            </div>
          </div>
          <div className="space-y-4">
            {loading ? (
              <div className="text-center py-8 text-gray-500">Loading...</div>
            ) : alerts.length === 0 ? (
              <div className="bg-white rounded-lg shadow p-8 text-center text-gray-500">
                No active alerts
              </div>
            ) : (
              alerts.map((alert) => (
                <div
                  key={alert.id}
                  className={`bg-white rounded-lg shadow p-6 border-l-4 ${
                    alert.severity === 'CRITICAL' ? 'border-red-500' :
                    alert.severity === 'HIGH' ? 'border-orange-500' :
                    alert.severity === 'MEDIUM' ? 'border-yellow-500' : 'border-amber-500'
                  } ${alertSelection.isSelected(alert.id) ? 'ring-2 ring-amber-500' : ''}`}
                >
                  <div className="flex items-start justify-between">
                    <div className="flex items-start gap-3 flex-1">
                      <input
                        type="checkbox"
                        checked={alertSelection.isSelected(alert.id)}
                        onChange={() => alertSelection.toggleSelection(alert.id)}
                        className="w-4 h-4 mt-1"
                      />
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-2">
                          <span className={`px-2 py-1 text-xs rounded-full ${getSeverityColor(alert.severity)}`}>
                            {alert.severity}
                          </span>
                          <span className="text-sm text-gray-500">{alert.alert_type.replace(/_/g, ' ')}</span>
                        </div>
                        <p className="text-gray-900 mb-2">{alert.message}</p>
                        <div className="text-sm text-gray-500">
                          {alert.items?.item_name || 'Unknown Item'}
                          {alert.items?.item_code ? ` (${alert.items.item_code})` : ''}
                          {alert.warehouses && ` - ${alert.warehouses.warehouse_name}`}
                        </div>
                        <div className="text-xs text-gray-400 mt-2">
                          {new Date(alert.created_at).toLocaleString()}
                        </div>
                      </div>
                    </div>
                    <button
                      onClick={() => acknowledgeAlert(alert.id)}
                      className="ml-4 px-4 py-2 bg-amber-600 text-white rounded hover:bg-amber-700"
                    >
                      Acknowledge
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      )}

      {/* Demo Inventory Tab */}
      {activeTab === 'demo' && (
        <div className="bg-white rounded-lg shadow overflow-hidden">
          {demoItems.length > 0 && (
            <div className="px-6 py-4 border-b border-gray-200 bg-gray-50">
              <div className="flex items-center justify-between">
                <label className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={demoSelection.isAllSelected}
                    onChange={demoSelection.toggleSelectAll}
                    className="w-4 h-4"
                  />
                  <span className="text-sm font-medium text-gray-700">
                    Select All ({demoItems.length} demo items)
                  </span>
                </label>
                {demoSelection.hasSelections && (
                  <div className="flex gap-2">
                    <button
                      onClick={() => deleteDemoItems(Array.from(demoSelection.selectedIds))}
                      className="px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700 text-sm"
                    >
                      Delete Selected ({demoSelection.selectedItems.length})
                    </button>
                    <button
                      onClick={demoSelection.deselectAll}
                      className="px-4 py-2 bg-gray-600 text-white rounded hover:bg-gray-700 text-sm"
                    >
                      Deselect All
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase w-12"></th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Demo ID</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Item</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">UID</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Customer</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Issue Date</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Expected Return</th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">Expenses</th>
                <th className="px-6 py-3 text-center text-xs font-medium text-gray-500 uppercase">Status</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {loading ? (
                <tr>
                  <td colSpan={9} className="px-6 py-4 text-center text-gray-500">
                    Loading...
                  </td>
                </tr>
              ) : demoItems.length === 0 ? (
                <tr>
                  <td colSpan={9} className="px-6 py-4 text-center text-gray-500">
                    No demo items found
                  </td>
                </tr>
              ) : (
                demoItems.map((demo) => (
                  <tr key={demo.id} className={`hover:bg-gray-50 ${demoSelection.isSelected(demo.id) ? 'bg-amber-50' : ''}`}>
                    <td className="px-6 py-4">
                      <input
                        type="checkbox"
                        checked={demoSelection.isSelected(demo.id)}
                        onChange={() => demoSelection.toggleSelection(demo.id)}
                        className="w-4 h-4"
                      />
                    </td>
                    <td className="px-6 py-4 text-sm font-medium text-gray-900">
                      {demo.demo_id}
                    </td>
                    <td className="px-6 py-4">
                      <div className="text-sm text-gray-900">{demo.items?.item_name || 'Unknown Item'}</div>
                      <div className="text-sm text-gray-500">{demo.items?.item_code || '-'}</div>
                    </td>
                    <td className="px-6 py-4">
                      <span className="text-sm font-mono text-amber-600">{demo.uid}</span>
                    </td>
                    <td className="px-6 py-4">
                      <div className="text-sm text-gray-900">{demo.customer_name}</div>
                      <div className="text-sm text-gray-500">{demo.customer_contact}</div>
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-500">
                      {new Date(demo.issue_date).toLocaleDateString()}
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-500">
                      {demo.expected_return_date
                        ? new Date(demo.expected_return_date).toLocaleDateString()
                        : '-'}
                    </td>
                    <td className="px-6 py-4 text-right text-sm text-gray-900">
                      ₹{demo.demo_expenses.toLocaleString()}
                    </td>
                    <td className="px-6 py-4 text-center">
                      <span className={`px-2 py-1 text-xs rounded-full ${getStatusColor(demo.status)}`}>
                        {demo.status}
                      </span>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      )}

      {/* Email Modal */}
      {emailModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 max-w-md w-full mx-4">
            <h3 className="text-xl font-bold text-gray-900 mb-4">Send Low Stock Alert Email</h3>
            <p className="text-sm text-gray-600 mb-4">
              Send an email notification with all {alerts.length} low stock alerts to the specified recipient.
            </p>
            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Recipient Email Address
              </label>
              <input
                type="email"
                value={recipientEmail}
                onChange={(e) => setRecipientEmail(e.target.value)}
                placeholder="purchasing@company.com"
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                disabled={sendingEmail}
              />
            </div>
            <div className="flex gap-3 justify-end">
              <button
                onClick={() => {
                  setEmailModal(false);
                  setRecipientEmail('');
                }}
                className="px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
                disabled={sendingEmail}
              >
                Cancel
              </button>
              <button
                onClick={sendLowStockEmail}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50"
                disabled={sendingEmail || !recipientEmail}
              >
                {sendingEmail ? 'Sending...' : 'Send Email'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { apiClient } from '../../../lib/api-client';

export const dynamic = 'force-dynamic';

interface DashboardStats {
  activeOrders: number;
  pendingPOs: number;
  inProduction: number;
  readyToShip: number;
  lowStockCount: number;
}

export default function DashboardPage() {
  const router = useRouter();
  const [stats, setStats] = useState<DashboardStats>({
    activeOrders: 0,
    pendingPOs: 0,
    inProduction: 0,
    readyToShip: 0,
    lowStockCount: 0,
  });
  const [loading, setLoading] = useState(true);

  const shouldHideDashboardForCurrentUser = (): boolean => {
    if (typeof window === 'undefined') return false;
    try {
      const raw = localStorage.getItem('user');
      if (!raw) return false;
      const user = JSON.parse(raw) as any;

      const roleNames: string[] = [];
      if (Array.isArray(user?.roles)) {
        user.roles.forEach((entry: any) => {
          if (typeof entry === 'string') roleNames.push(entry);
          else if (entry?.role?.name) roleNames.push(String(entry.role.name));
        });
      }
      if (user?.role?.name) roleNames.push(String(user.role.name));

      const normalized = roleNames
        .map((n) => String(n).toUpperCase().replace(/[_\-]+/g, ' '))
        .map((n) => n.trim())
        .filter(Boolean);

      const isHr = normalized.some((n) => n.includes('HR'));
      const isAdminLike = normalized.some(
        (n) => n.includes('ADMIN') || n.includes('SUPER') || n.includes('OWNER'),
      );

      return isHr && !isAdminLike;
    } catch {
      return false;
    }
  };

  useEffect(() => {
    // Check if user is authenticated
    if (!apiClient.isAuthenticated()) {
      router.push('/login');
      return;
    }

    // HR-only users should not see the global dashboard.
    if (shouldHideDashboardForCurrentUser()) {
      router.replace('/dashboard/hr');
      return;
    }

    fetchStats();
  }, [router]);

  const fetchStats = async () => {
    try {
      const data = await apiClient.get('/dashboard/stats');
      setStats(data);
    } catch (error) {
      console.error('Error fetching dashboard stats:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      {/* Header with Logout */}
      <div className="bg-white shadow-sm border-b-2 mb-6" style={{ borderColor: '#E8DCC4' }}>
        <div className="flex items-center justify-between px-6 py-4">
          <div>
            <h1 className="text-3xl font-bold" style={{ color: '#36454F' }}>
              SAK ERP Dashboard
            </h1>
            <p className="text-sm mt-1" style={{ color: '#6F4E37' }}>
              Your complete lifecycle management solution
            </p>
          </div>
          
          <button
            onClick={async () => {
              await apiClient.logout();
              router.push('/login');
            }}
            className="px-6 py-2 rounded-lg text-white transition-colors hover:opacity-90 font-medium"
            style={{ backgroundColor: '#6F4E37' }}
          >
            Logout
          </button>
        </div>
      </div>

      {/* Main Content */}
      <div>
        {/* KPI Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-6 mb-8">
          {[
            { title: 'Active Orders', value: loading ? '...' : String(stats?.activeOrders ?? 0), color: '#8B6F47', link: null },
            { title: 'Pending POs', value: loading ? '...' : String(stats?.pendingPOs ?? 0), color: '#6F4E37', link: null },
            { title: 'In Production', value: loading ? '...' : String(stats?.inProduction ?? 0), color: '#6B8E23', link: null },
            { title: 'Ready to Ship', value: loading ? '...' : String(stats?.readyToShip ?? 0), color: '#4682B4', link: null },
            { title: 'Low Stock Alerts', value: loading ? '...' : String(stats?.lowStockCount ?? 0), color: (stats?.lowStockCount ?? 0) > 0 ? '#DC2626' : '#10B981', link: '/dashboard/inventory?tab=alerts', alert: (stats?.lowStockCount ?? 0) > 0 },
          ].map((kpi, index) => (
            <div
              key={index}
              className={`bg-white p-6 rounded-xl shadow-md hover:shadow-lg transition-all border-2 ${
                kpi.link ? 'cursor-pointer' : ''
              } ${
                kpi.alert ? 'animate-pulse' : ''
              }`}
              style={{ borderColor: kpi.alert ? '#DC2626' : '#E8DCC4' }}
              onClick={() => kpi.link && router.push(kpi.link)}
            >
              <h3 className="text-sm font-medium mb-2 flex items-center gap-2" style={{ color: '#6F4E37' }}>
                {kpi.title}
                {kpi.alert && <span className="text-xs px-2 py-0.5 bg-red-100 text-red-800 rounded-full">⚠️</span>}
              </h3>
              <p className="text-3xl font-bold" style={{ color: kpi.color }}>
                {kpi.value}
              </p>
            </div>
          ))}
        </div>

        {/* Modules Grid */}
        <div className="bg-white p-6 rounded-xl shadow-md border-2" style={{ borderColor: '#E8DCC4' }}>
          <h3 className="text-xl font-bold mb-6" style={{ color: '#36454F' }}>
            ERP Modules
          </h3>
          
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {[
              { name: 'Purchase Management', icon: '📦', path: '/dashboard/purchase' },
              { name: 'BOM Management', icon: '📋', path: '/dashboard/bom' },
              { name: 'Inventory & Stores', icon: '🏪', path: '/dashboard/inventory' },
              { name: 'Production Planning', icon: '⚙️', path: '/dashboard/production' },
              { name: 'Quality Control', icon: '✅', path: '/dashboard/quality' },
              { name: 'Sales & Dispatch', icon: '🚚', path: '/dashboard/sales' },
              { name: 'UID Tracking', icon: '🔍', path: '/dashboard/uid' },
              { name: 'After-Sales Service', icon: '🛠️', path: '/dashboard/service' },
              { name: 'Document Control', icon: '📄', path: '/dashboard/documents' },
              { name: 'Settings & Users', icon: '⚙️', path: '/dashboard/settings' },
            ].map((module, index) => (
              <button
                key={index}
                className="flex items-center space-x-4 p-4 rounded-lg border-2 transition-all hover:shadow-md"
                style={{ 
                  borderColor: '#E8DCC4',
                  backgroundColor: 'white',
                }}
                onClick={() => router.push(module.path)}
              >
                <span className="text-3xl">{module.icon}</span>
                <span className="font-medium" style={{ color: '#6F4E37' }}>
                  {module.name}
                </span>
              </button>
            ))}
          </div>
        </div>

        {/* Module Status Notice */}
        <div className="mt-8 p-6 rounded-xl border-2" style={{ backgroundColor: '#E8DCC4', borderColor: '#8B6F47' }}>
          <p className="text-center font-medium" style={{ color: '#6F4E37' }}>
            ✅ All modules are active and ready to use! Click any module above to get started.
          </p>
        </div>
      </div>
    </div>
  );
}

'use client';

import { Suspense, useEffect, useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { apiClient } from '../../../../../lib/api-client';
import SearchableSelect from '../../../../components/SearchableSelect';

interface Item {
  id: string;
  code: string;
  name: string;
  type?: string;
  category?: string;
  uom?: string;
  total_stock?: number;
  current_stock?: number;
  stock_in_hand?: number;
  stock_available?: number;
}

type ItemStockSummary = {
  total_quantity: number;
  available_quantity: number;
  allocated_quantity: number;
};

interface Workstation {
  id: string;
  code: string;
  name: string;
}

interface User {
  id: string;
  employee_name: string;
  employee_code: string;
  designation?: string;
}

interface Operation {
  id?: string;
  sequenceNumber: number;
  operationName: string;
  workstationId: string;
  workstationName?: string;
  assignedUserId?: string;
  assignedUserName?: string;
  startDatetime?: string;
  endDatetime?: string;
  expectedDurationHours?: number;
  setupTimeHours?: number;
  acceptedVariationPercent?: number;
  status?: string;
  notes?: string;
}

interface Material {
  id?: string;
  itemId: string;
  itemCode?: string;
  itemName?: string;
  requiredQuantity: number;
  issuedQuantity?: number;
  warehouseId?: string;
  status?: string;
  variants?: any[];
  selectedVariantId?: string;
  selectedVariantName?: string;
  variantNotes?: string;
}

interface JobOrder {
  id: string;
  jobOrderNumber: string;
  itemId: string;
  itemCode: string;
  itemName: string;
  bomId?: string;
  quantity: number;
  completedQuantity?: number;
  rejectedQuantity?: number;
  startDate: string;
  endDate?: string;
  priority: string;
  status: string;
  notes?: string;
  operations?: Operation[];
  materials?: Material[];
  createdAt: string;
}

interface JobOrderUID {
  uid: string;
  quality_status?: string;
  client_part_number?: string;
  created_at?: string;
  items?: {
    id: string;
    code: string;
    name: string;
  };
}

type JobOrderQcSummary = {
  jobOrderId: string;
  jobOrderNumber: string;
  status: string;
  qcStockEntriesCount: number;
  stockAdded: number;
  approvedUidsCount: number;
  isQcApplied: boolean;
  qcAppliedAt: string | null;
};

export default function JobOrdersPage() {
  return (
    <Suspense
      fallback={
        <div className="p-6 min-h-screen bg-gradient-to-br from-[#FAF9F6] to-[#E8DCC4]">
          <div className="max-w-6xl mx-auto">
            <div className="bg-white rounded-lg shadow p-6">
              <div className="text-lg font-semibold text-[#36454F]">Loading Job Orders…</div>
            </div>
          </div>
        </div>
      }
    >
      <JobOrdersPageContent />
    </Suspense>
  );
}

function JobOrdersPageContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const legacy = searchParams.get('legacy') === '1';

  const [jobOrders, setJobOrders] = useState<JobOrder[]>([]);
  const [items, setItems] = useState<Item[]>([]);
  const [workstations, setWorkstations] = useState<Workstation[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [boms, setBoms] = useState<any[]>([]);
  const [allBoms, setAllBoms] = useState<any[]>([]);
  const [bomSearchTerm, setBomSearchTerm] = useState('');
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [selectedJobOrder, setSelectedJobOrder] = useState<JobOrder | null>(null);
  const [selectedJobOrderLoading, setSelectedJobOrderLoading] = useState(false);
  const [loading, setLoading] = useState(false);
  const [completionPreview, setCompletionPreview] = useState<any>(null);
  const [completionJobOrderId, setCompletionJobOrderId] = useState<string | null>(null);
  const [showCompletionModal, setShowCompletionModal] = useState(false);
  const [stockErrorModal, setStockErrorModal] = useState<{show: boolean, shortages: any[]}>({show: false, shortages: []});
  const [itemStockSummaryById, setItemStockSummaryById] = useState<Record<string, ItemStockSummary>>({});

  // QC modal state
  const [showQcModal, setShowQcModal] = useState(false);
  const [qcLoading, setQcLoading] = useState(false);
  const [qcSubmitting, setQcSubmitting] = useState(false);
  const [qcUids, setQcUids] = useState<JobOrderUID[]>([]);
  const [qcIndex, setQcIndex] = useState(0);
  const [qcAlreadyApplied, setQcAlreadyApplied] = useState(false);
  const [qcSummary, setQcSummary] = useState<JobOrderQcSummary | null>(null);

  // Form state
  const [formData, setFormData] = useState({
    itemId: '',
    bomId: '',
    quantity: 1,
    startDate: new Date().toISOString().split('T')[0],
    endDate: '',
    priority: 'NORMAL',
    notes: '',
  });

  const [operations, setOperations] = useState<Operation[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [baseMaterialQuantities, setBaseMaterialQuantities] = useState<{ [key: string]: number }>({});

  useEffect(() => {
    fetchJobOrders();
    fetchItems();
    fetchWorkstations();
    fetchUsers();
    fetchAllBoms();
    console.log('Initial data fetch triggered');
  }, []);

  const mapJobOrderFromApi = (jo: any): JobOrder => {
    const operationsRaw = Array.isArray(jo?.operations) ? jo.operations : [];
    const materialsRaw = Array.isArray(jo?.materials) ? jo.materials : [];

    return {
      id: jo.id,
      jobOrderNumber: jo.job_order_number || jo.jobOrderNumber,
      itemId: jo.item_id || jo.itemId,
      itemCode: jo.item_code || jo.itemCode,
      itemName: jo.item_name || jo.itemName,
      bomId: jo.bom_id || jo.bomId,
      quantity: Number(jo.quantity) || 0,
      completedQuantity: jo.completed_quantity ?? jo.completedQuantity,
      rejectedQuantity: jo.rejected_quantity ?? jo.rejectedQuantity,
      startDate: jo.start_date || jo.startDate,
      endDate: jo.end_date || jo.endDate,
      priority: jo.priority,
      status: jo.status,
      notes: jo.notes,
      createdAt: jo.created_at || jo.createdAt,
      operations: operationsRaw.map((op: any) => ({
        id: op.id,
        sequenceNumber: op.sequence_number ?? op.sequenceNumber,
        operationName: op.operation_name ?? op.operationName,
        workstationId: op.workstation_id ?? op.workstationId,
        workstationName: op.workstation_name ?? op.workstationName,
        assignedUserId: op.assigned_user_id ?? op.assignedUserId,
        assignedUserName: op.assigned_user_name ?? op.assignedUserName,
        startDatetime: op.start_datetime ?? op.startDatetime,
        endDatetime: op.end_datetime ?? op.endDatetime,
        expectedDurationHours: op.expected_duration_hours ?? op.expectedDurationHours,
        setupTimeHours: op.setup_time_hours ?? op.setupTimeHours,
        acceptedVariationPercent: op.accepted_variation_percent ?? op.acceptedVariationPercent,
        status: op.status,
        notes: op.notes,
      })),
      materials: materialsRaw.map((m: any) => ({
        id: m.id,
        itemId: m.item_id ?? m.itemId,
        itemCode: m.item_code ?? m.itemCode,
        itemName: m.item_name ?? m.itemName,
        requiredQuantity: m.required_quantity ?? m.requiredQuantity,
        issuedQuantity: m.issued_quantity ?? m.issuedQuantity,
        warehouseId: m.warehouse_id ?? m.warehouseId,
        status: m.status,
        selectedVariantId: m.selected_variant_id ?? m.selectedVariantId,
        variantNotes: m.variant_notes ?? m.variantNotes,
      })),
    };
  };

  const openJobOrderDetails = async (jo: JobOrder) => {
    setSelectedJobOrder(jo);
    setSelectedJobOrderLoading(true);
    try {
      const data = await apiClient.get(`/job-orders/${jo.id}`);
      const mapped = mapJobOrderFromApi(data);
      setSelectedJobOrder(mapped);
    } catch (error) {
      console.error('Error fetching job order details:', error);
      // Keep basic details visible even if details fetch fails.
    } finally {
      setSelectedJobOrderLoading(false);
    }
  };

  const openQcModal = async () => {
    if (!selectedJobOrder?.id) return;

    setShowQcModal(true);
    setQcLoading(true);
    setQcSubmitting(false);
    setQcUids([]);
    setQcIndex(0);
    setQcAlreadyApplied(false);
    setQcSummary(null);

    try {
      try {
        const summary = await apiClient.get<JobOrderQcSummary>(`/job-orders/${selectedJobOrder.id}/qc-summary`);
        setQcSummary(summary ?? null);
        setQcAlreadyApplied(Boolean(summary?.isQcApplied));
      } catch {
        // Non-blocking: if summary fails, QC can still proceed (API is idempotent).
        setQcAlreadyApplied(false);
        setQcSummary(null);
      }

      const response = await apiClient.get<any>(
        `/uid?job_order_id=${selectedJobOrder.id}&limit=5000&sortBy=created_at&sortOrder=asc`,
      );
      const data = Array.isArray(response) ? response : response?.data || [];
      const list = (data || []) as JobOrderUID[];

      setQcUids(list);

      // Jump to first non-PASSED UID
      const firstPendingIdx = list.findIndex(u => String(u?.quality_status || '').toUpperCase() !== 'PASSED');
      setQcIndex(firstPendingIdx >= 0 ? firstPendingIdx : 0);
    } catch (error) {
      console.error('Error fetching job order UIDs for QC:', error);
      alert('Failed to load UIDs for QC');
      setShowQcModal(false);
    } finally {
      setQcLoading(false);
    }
  };

  const ensureJobOrderUidsAndReloadQc = async () => {
    if (!selectedJobOrder?.id) return;

    setQcLoading(true);
    setQcSubmitting(false);
    try {
      await apiClient.post(`/job-orders/${selectedJobOrder.id}/ensure-uids`, {});

      const response = await apiClient.get<any>(
        `/uid?job_order_id=${selectedJobOrder.id}&limit=5000&sortBy=created_at&sortOrder=asc`,
      );
      const data = Array.isArray(response) ? response : response?.data || [];
      const list = (data || []) as JobOrderUID[];

      setQcUids(list);
      const firstPendingIdx = list.findIndex(
        (u) => String(u?.quality_status || '').toUpperCase() !== 'PASSED',
      );
      setQcIndex(firstPendingIdx >= 0 ? firstPendingIdx : 0);

      try {
        const summary = await apiClient.get<JobOrderQcSummary>(`/job-orders/${selectedJobOrder.id}/qc-summary`);
        setQcSummary(summary ?? null);
        setQcAlreadyApplied(Boolean(summary?.isQcApplied));
      } catch {
        setQcAlreadyApplied(false);
        setQcSummary(null);
      }
    } catch (error: any) {
      console.error('Error ensuring job order UIDs:', error);
      const errorMsg = error.response?.data?.message || error.message || 'Failed to generate UIDs';
      alert(errorMsg);
    } finally {
      setQcLoading(false);
    }
  };

  const setCurrentUidQc = async (qualityStatus: 'PASSED' | 'ON_HOLD', targetUid?: string) => {
    const uidToUpdate = targetUid || qcUids[qcIndex]?.uid;
    if (!uidToUpdate) return;

    try {
      await apiClient.put(`/uid/${encodeURIComponent(uidToUpdate)}/quality-status`, {
        quality_status: qualityStatus,
      });

      const updated = qcUids.map((u) => 
        u.uid === uidToUpdate ? { ...u, quality_status: qualityStatus } : u
      );
      setQcUids(updated);

      // If no targetUid specified (old sequential behavior), advance to next pending
      if (!targetUid) {
        const nextPendingIdx = updated.findIndex(
          (u, idx) => idx > qcIndex && String(u?.quality_status || '').toUpperCase() !== 'PASSED',
        );

        if (nextPendingIdx >= 0) {
          setQcIndex(nextPendingIdx);
          return;
        }

        // If none after current, try from start
        const firstPendingIdx = updated.findIndex(u => String(u?.quality_status || '').toUpperCase() !== 'PASSED');
        if (firstPendingIdx >= 0) {
          setQcIndex(firstPendingIdx);
          return;
        }

        alert('✅ All UIDs are QC PASSED');
        setShowQcModal(false);
      }
    } catch (error: any) {
      console.error('Error updating QC status:', error);
      const msg = error?.response?.data?.message || error?.message || 'Failed to update QC status';
      alert(msg);
    }
  };

  const fetchItemStockSummary = async (itemId: string) => {
    const id = String(itemId || '').trim();
    if (!id) return;

    // Avoid refetch if we already have it.
    if (itemStockSummaryById[id]) return;

    try {
      // Source of truth for stock in this ERP is `stock_entries` via the RPC-backed endpoint.
      const summary = await apiClient.get(`/items/${id}/stock`);

      const normalized: ItemStockSummary = {
        total_quantity: Number(summary?.total_quantity) || 0,
        available_quantity: Number(summary?.available_quantity) || 0,
        allocated_quantity: Number(summary?.allocated_quantity) || 0,
      };

      setItemStockSummaryById(prev => ({ ...prev, [id]: normalized }));
    } catch (error) {
      console.error('Error fetching item stock summary:', { itemId: id, error });
      // Store a safe default so we don't spam retries.
      setItemStockSummaryById(prev => ({
        ...prev,
        [id]: { total_quantity: 0, available_quantity: 0, allocated_quantity: 0 },
      }));
    }
  };

  // When BOM loads materials (or user edits materials), ensure we have stock summaries
  // for all referenced item IDs.
  useEffect(() => {
    const ids = Array.from(
      new Set(materials.map(m => String(m.itemId || '').trim()).filter(Boolean))
    );
    ids.forEach(id => {
      if (!itemStockSummaryById[id]) {
        fetchItemStockSummary(id);
      }
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [materials]);

  const fetchJobOrders = async () => {
    try {
      const data = await apiClient.get('/job-orders');
      // Map snake_case to camelCase (list endpoint typically does not include materials/operations)
      const mapped = (data || []).map((jo: any) => mapJobOrderFromApi(jo));
      setJobOrders(mapped);
    } catch (error) {
      console.error('Error fetching job orders:', error);
    }
  };

  const fetchItems = async () => {
    try {
      const data = await apiClient.get('/items');

      // Keep the list lightweight; stock is fetched on-demand per material via /items/:id/stock.
      // Some API responses include `total_stock` (available) already; keep it for fallback.
      const itemsWithOptionalStock = (data || []).map((item: any) => ({
        ...item,
        total_stock: Number(item?.total_stock) || 0,
      }));

      setItems(itemsWithOptionalStock || []);
    } catch (error) {
      console.error('Error fetching items:', error);
      setItems([]);
    }
  };

  const fetchWorkstations = async () => {
    try {
      const data = await apiClient.get('/production/work-stations');
      // Map station_code and station_name to code and name for dropdown compatibility
      const mapped = data.map((ws: any) => ({
        id: ws.id,
        code: ws.station_code,
        name: ws.station_name,
      }));
      setWorkstations(mapped);
    } catch (error) {
      console.error('Error fetching workstations:', error);
    }
  };

  const fetchUsers = async () => {
    try {
      const data = await apiClient.get('/hr/employees');
      setUsers(data);
    } catch (error) {
      console.error('Error fetching users:', error);
    }
  };

  // Fetch all BOMs on page load
  const fetchAllBoms = async () => {
    try {
      console.log('Fetching all BOMs...');
      const bomsData = await apiClient.get('/bom');
      console.log('All BOMs loaded:', bomsData?.length || 0, 'First BOM:', bomsData?.[0]);
      const bomsArray = Array.isArray(bomsData) ? bomsData : [];
      setAllBoms(bomsArray);
      setBoms(bomsArray);
    } catch (error) {
      console.error('Error fetching BOMs:', error);
      alert('Failed to load BOMs. Please check console for details.');
      setAllBoms([]);
      setBoms([]);
    }
  };

  // Filter BOMs based on search term
  useEffect(() => {
    if (!bomSearchTerm.trim()) {
      setBoms(allBoms);
      return;
    }
    
    const searchLower = bomSearchTerm.toLowerCase();
    const filtered = allBoms.filter(bom => {
      const itemCode = (bom.item?.code || '').toLowerCase();
      const itemName = (bom.item?.name || '').toLowerCase();
      const version = String(bom.version || '').toLowerCase();
      return itemCode.includes(searchLower) || 
             itemName.includes(searchLower) ||
             version.includes(searchLower);
    });
    setBoms(filtered);
  }, [bomSearchTerm, allBoms]);

  const fetchBOMData = async (bomId: string) => {
    if (!bomId) return;
    
    console.log('fetchBOMData called with bomId:', bomId);
    try {
      // Get BOM details to auto-populate item
      const selectedBom = allBoms.find(b => b.id === bomId);
      if (selectedBom && selectedBom.item_id) {
        setFormData(prev => ({ ...prev, itemId: selectedBom.item_id }));
        console.log('Auto-populated item from BOM:', selectedBom.item_id);
      }

      console.log('Loading BOM details for bomId:', bomId);

      // Fetch BOM items (materials)
      console.log('Fetching BOM items for bomId:', bomId);
      const bomItems = await apiClient.get(`/bom/${bomId}/items`);
      console.log('BOM items response:', bomItems);
      console.log('First BOM item structure:', bomItems[0]);
      
      // Store base quantities from BOM (per 1 unit)
      const baseQuantities: { [key: string]: number } = {};
      const materialsWithVariantsRaw = await Promise.all(bomItems.map(async (item: any) => {
        console.log('Processing BOM item:', {
          component_id: item.component_id,
          item_id: item.item_id,
          component_code: item.component_code,
          component_name: item.component_name,
          quantity: item.quantity
        });
        const itemId = String(item.component_id || item.item_id || '').trim();
        if (!itemId) {
          console.warn('Skipping BOM item with no resolvable item id:', item);
          return null;
        }

        baseQuantities[itemId] = item.quantity;
        
        // Fetch variants for this item
        let variants = [];
        let selectedVariantId = itemId;
        let selectedVariantName = item.component_name;
        
        try {
          variants = await apiClient.get(`/items/${itemId}/variants`);
          if (variants && variants.length > 0) {
            const defaultVariant = variants.find((v: any) => v.is_default_variant) || variants[0];
            selectedVariantId = defaultVariant.id;
            selectedVariantName = defaultVariant.variant_name || defaultVariant.name;
          }
        } catch (error) {
          console.log('No variants found for item:', itemId);
        }
        
        return {
          itemId: itemId,
          itemCode: item.component_code,
          itemName: item.component_name,
          requiredQuantity: item.quantity * formData.quantity,
          variants: variants,
          selectedVariantId: selectedVariantId,
          selectedVariantName: selectedVariantName,
        };
      }));

      const materialsWithVariants = materialsWithVariantsRaw.filter(Boolean);
      
      setBaseMaterialQuantities(baseQuantities);
      setMaterials(materialsWithVariants);
      console.log('Materials with variants set:', materialsWithVariants);
      console.log('Base quantities:', baseQuantities);

      // Fetch routing (operations)
      console.log('Fetching routing for bomId:', bomId);
      const routing = await apiClient.get(`/production/routing/bom/${bomId}?withStations=true`);
      console.log('Routing response:', routing);
      
      if (routing && routing.length > 0) {
        const operations = routing.map((route: any) => ({
          sequenceNumber: route.sequence_no,
          operationName: route.operation_name,
          workstationId: route.work_station_id,
          acceptedVariationPercent: 5,
        }));
        setOperations(operations);
        console.log('Operations set:', operations);
      }
      
      alert('BOM data loaded! Materials and operations have been added.');
      
      // Scroll to materials section after a short delay to show what was loaded
      setTimeout(() => {
        const materialsSection = document.getElementById('materials-section');
        if (materialsSection) {
          materialsSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      }, 500);
    } catch (error) {
      console.error('Error fetching BOM data:', error);
      alert('Error loading BOM data. Check console for details.');
    }
  };

  const addOperation = () => {
    const newSequence = operations.length > 0 
      ? Math.max(...operations.map(op => op.sequenceNumber)) + 10 
      : 10;
    
    setOperations([...operations, {
      sequenceNumber: newSequence,
      operationName: '',
      workstationId: '',
      acceptedVariationPercent: 5,
    }]);
  };

  const updateOperation = (index: number, field: keyof Operation, value: any) => {
    const updated = [...operations];
    updated[index] = { ...updated[index], [field]: value };
    setOperations(updated);
  };

  const removeOperation = (index: number) => {
    setOperations(operations.filter((_, i) => i !== index));
  };

  const updateMaterialVariant = (index: number, variantId: string) => {
    const updated = [...materials];
    const variant = updated[index].variants?.find((v: any) => v.id === variantId);
    updated[index] = {
      ...updated[index],
      selectedVariantId: variantId,
      selectedVariantName: variant?.variant_name || variant?.name || '',
    };
    setMaterials(updated);
  };

  const fetchItemVariants = async (itemId: string) => {
    const id = String(itemId || '').trim();
    if (!id) return [] as any[];

    try {
      const variants = await apiClient.get(`/items/${id}/variants`);
      return Array.isArray(variants) ? variants : [];
    } catch {
      return [] as any[];
    }
  };

  const changeMaterialItem = async (index: number, nextItemId: string) => {
    const id = String(nextItemId || '').trim();
    if (!id) {
      updateMaterial(index, 'itemId', '');
      return;
    }

    // Keep quantities stable even when swapping the item.
    const currentQty = Number(formData.quantity) || 1;
    const currentRequiredQty = Number(materials[index]?.requiredQuantity) || 0;
    const basePerUnit = currentRequiredQty / currentQty;
    setBaseMaterialQuantities((prev) => ({ ...prev, [id]: basePerUnit }));

    // Update basic item fields immediately for responsive UI.
    const selectedItem = items.find((i) => String(i.id) === id);
    setMaterials((prev) => {
      const next = [...prev];
      const current = next[index] || ({ itemId: '', requiredQuantity: 0 } as Material);

      next[index] = {
        ...current,
        itemId: id,
        itemCode: selectedItem?.code,
        itemName: selectedItem?.name,
        variants: [],
        selectedVariantId: id,
        selectedVariantName: selectedItem?.name,
      };

      return next;
    });

    fetchItemStockSummary(id);

    const variants = await fetchItemVariants(id);
    if (!Array.isArray(variants) || variants.length === 0) return;

    const defaultVariant = variants.find((v: any) => v.is_default_variant) || variants[0];

    setMaterials((prev) => {
      const next = [...prev];
      if (!next[index]) return prev;

      next[index] = {
        ...next[index],
        variants,
        selectedVariantId: defaultVariant?.id || id,
        selectedVariantName:
          defaultVariant?.variant_name ||
          defaultVariant?.name ||
          next[index]?.selectedVariantName,
      };

      return next;
    });
  };

  const addMaterial = () => {
    setMaterials([...materials, {
      itemId: '',
      requiredQuantity: 1,
    }]);
  };

  const updateMaterial = (index: number, field: keyof Material, value: any) => {
    const updated = [...materials];
    updated[index] = { ...updated[index], [field]: value };
    setMaterials(updated);
  };

  const removeMaterial = (index: number) => {
    setMaterials(materials.filter((_, i) => i !== index));
  };

  const handleCreateJobOrder = async () => {
    console.log('Create button clicked', { formData, operations, materials });
    
    if (!formData.itemId || !formData.quantity || !formData.startDate) {
      console.log('Validation failed', { 
        itemId: formData.itemId, 
        quantity: formData.quantity, 
        startDate: formData.startDate 
      });
      alert('Please fill in all required fields');
      return;
    }

    setLoading(true);
    try {
      console.log('Sending request to /job-orders');
      
      // Clean up the payload - remove empty endDate and extra fields from materials
      const payload: any = {
        itemId: formData.itemId,
        bomId: formData.bomId || undefined,
        quantity: formData.quantity,
        startDate: formData.startDate,
        priority: formData.priority,
        notes: formData.notes,
      };
      
      // Only include endDate if it's not empty
      if (formData.endDate) {
        payload.endDate = formData.endDate;
      }
      
      // Clean materials - include selectedVariantId if present
      if (materials.length > 0) {
        payload.materials = materials.map(m => ({
          itemId: m.itemId,
          requiredQuantity: m.requiredQuantity,
          warehouseId: m.warehouseId || undefined,
          selectedVariantId: m.selectedVariantId || undefined,
          variantNotes: m.variantNotes || undefined,
        }));
      }
      
      // Clean operations - only send required fields
      if (operations.length > 0) {
        payload.operations = operations.map(op => ({
          sequenceNumber: op.sequenceNumber,
          operationName: op.operationName,
          workstationId: op.workstationId,
          assignedUserId: op.assignedUserId || undefined,
          acceptedVariationPercent: op.acceptedVariationPercent || 0,
          notes: op.notes || undefined,
        }));
      }
      
      console.log('Cleaned payload:', payload);
      const response = await apiClient.post('/job-orders', payload);
      console.log('Job order created successfully', response);

      setShowCreateModal(false);
      resetForm();
      fetchJobOrders();
      alert('Job Order created successfully!');
    } catch (error: any) {
      console.error('Error creating job order:', error);
      
      // Check if it's an inventory shortage error
      const errorMessage = error?.message || '';
      if (errorMessage.includes('Insufficient materials')) {
        // Parse the error message to extract shortage details
        const lines = errorMessage.split('\n');
        const shortageLines = lines.slice(1).filter((line: string) => line.trim()); // Skip the first line and empty lines

        const shortages = shortageLines.map((line: string) => {
          // Parse lines like "SG1 - L80 GPS: Need 1, Available 0, Short 1"
          const match = line.match(/^(.+?):\s*Need\s+(\d+(?:\.\d+)?),\s*Available\s+(\d+(?:\.\d+)?),\s*Short\s+(\d+(?:\.\d+)?)$/);
          if (match) {
            return {
              material: match[1].trim(),
              needed: parseFloat(match[2]),
              available: parseFloat(match[3]),
              short: parseFloat(match[4])
            };
          }
          return null;
        }).filter(Boolean);
        
        setStockErrorModal({show: true, shortages});
      } else {
        alert('Failed to create job order: ' + errorMessage);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleUpdateStatus = async (id: string, status: string) => {
    try {
      await apiClient.put(`/job-orders/${id}/status`, { status });
      fetchJobOrders();
      alert(`Job Order status updated to ${status}`);
    } catch (error) {
      console.error('Error updating status:', error);
      alert('Failed to update status');
    }
  };

  const handleCompleteJobOrder = async (id: string) => {
    // First, fetch completion preview
    setLoading(true);
    try {
      setCompletionJobOrderId(id);
      const preview = await apiClient.get(`/job-orders/${id}/completion-preview`);
      setCompletionPreview(preview);
      setShowCompletionModal(true);
    } catch (error: any) {
      console.error('Error fetching completion preview:', error);
      const errorMsg = error.response?.data?.message || error.message || 'Failed to load completion preview';
      alert(errorMsg);
      setCompletionJobOrderId(null);
    } finally {
      setLoading(false);
    }
  };

  const confirmCompletion = async () => {
    if (!completionPreview) return;
    if (!completionJobOrderId) {
      alert('Missing Job Order ID. Please close the popup and try again.');
      return;
    }
    
    setLoading(true);
    try {
      await apiClient.post(`/job-orders/${completionJobOrderId}/complete`, {});
      setShowCompletionModal(false);
      setCompletionPreview(null);
      setCompletionJobOrderId(null);
      fetchJobOrders();
      alert('✅ Job Order completed successfully!\n\nUIDs generated and awaiting QC approval.\nStock will be added after QC inspection.');
    } catch (error: any) {
      console.error('Error completing job order:', error);
      const errorMsg = error.response?.data?.message || error.message || 'Failed to complete job order';
      alert(errorMsg);
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setFormData({
      itemId: '',
      bomId: '',
      quantity: 1,
      startDate: new Date().toISOString().split('T')[0],
      endDate: '',
      priority: 'NORMAL',
      notes: '',
    });
    setOperations([]);
    setMaterials([]);
    setBomSearchTerm('');
    setBoms(allBoms);
  };

  const getStatusColor = (status: string) => {
    const colors: Record<string, string> = {
      DRAFT: 'bg-gray-100 text-gray-800',
      SCHEDULED: 'bg-blue-100 text-blue-800',
      IN_PROGRESS: 'bg-yellow-100 text-yellow-800',
      COMPLETED: 'bg-green-100 text-green-800',
      CANCELLED: 'bg-red-100 text-red-800',
      ON_HOLD: 'bg-orange-100 text-orange-800',
    };
    return colors[status] || 'bg-gray-100 text-gray-800';
  };

  return (
    <div className="p-6 min-h-screen bg-gradient-to-br from-[#FAF9F6] to-[#E8DCC4]">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-[#36454F]">Job Orders</h1>
        <div className="flex items-center gap-3">
          <button
            onClick={() => {
              if (legacy) {
                setShowCreateModal(true);
                return;
              }

              router.push('/dashboard/production/job-orders/smart-items');
            }}
            className="px-4 py-2 bg-[#8B6F47] text-white rounded hover:bg-[#6F4E37]"
            title={
              legacy
                ? 'Legacy Create Job Order (backup)'
                : 'Smart Job Order: select FG + preview BOM explosion + create'
            }
          >
            + Create Job Order
          </button>
        </div>
      </div>

      {/* Job Orders List */}
      <div className="bg-[#FAF9F6] rounded-lg shadow-lg border border-[#E8DCC4] overflow-x-auto">
        <table className="min-w-[980px] w-full divide-y divide-[#E8DCC4]">
          <thead className="bg-[#E8DCC4]">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium text-[#6F4E37] uppercase">Job Order #</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-[#6F4E37] uppercase w-[420px]">Item</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-[#6F4E37] uppercase">Quantity</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-[#6F4E37] uppercase">Start Date</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-[#6F4E37] uppercase">Priority</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-[#6F4E37] uppercase">Status</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-[#6F4E37] uppercase">Actions</th>
            </tr>
          </thead>
          <tbody className="bg-[#FAF9F6] divide-y divide-[#E8DCC4]">
            {jobOrders.map((jo) => (
              <tr key={jo.id} className="hover:bg-[#E8DCC4]">
                <td className="px-6 py-4 whitespace-nowrap font-medium">{jo.jobOrderNumber}</td>
                <td className="px-6 py-4 min-w-[280px] max-w-[520px]">
                  <div className="font-medium text-[#36454F] whitespace-nowrap">{jo.itemCode}</div>
                  <div className="text-sm text-gray-500 whitespace-normal break-words" title={jo.itemName}>
                    {jo.itemName}
                  </div>
                </td>
                <td className="px-6 py-4 whitespace-nowrap">{jo.quantity}</td>
                <td className="px-6 py-4 whitespace-nowrap">{new Date(jo.startDate).toLocaleDateString()}</td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <span className={`px-2 py-1 text-xs rounded ${
                    jo.priority === 'HIGH' ? 'bg-red-100 text-red-800' :
                    jo.priority === 'URGENT' ? 'bg-red-200 text-red-900' :
                    'bg-gray-100 text-gray-800'
                  }`}>
                    {jo.priority}
                  </span>
                </td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <span className={`px-2 py-1 text-xs rounded ${getStatusColor(jo.status)}`}>
                    {jo.status}
                  </span>
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm">
                  <button
                    onClick={() => openJobOrderDetails(jo)}
                    className="text-blue-600 hover:text-blue-800 mr-3"
                  >
                    View
                  </button>
                  {jo.status === 'DRAFT' && (
                    <button
                      onClick={() => handleUpdateStatus(jo.id, 'SCHEDULED')}
                      className="text-green-600 hover:text-green-800 mr-3"
                    >
                      Schedule
                    </button>
                  )}
                  {jo.status === 'SCHEDULED' && (
                    <button
                      onClick={() => handleUpdateStatus(jo.id, 'IN_PROGRESS')}
                      className="text-yellow-600 hover:text-yellow-800 mr-3"
                    >
                      Start
                    </button>
                  )}
                  {jo.status === 'IN_PROGRESS' && (
                    <button
                      onClick={() => handleCompleteJobOrder(jo.id)}
                      className="text-green-600 hover:text-green-800"
                      disabled={loading}
                    >
                      Complete
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Create Job Order Modal */}
      {showCreateModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 overflow-y-auto">
          <div className="bg-white rounded-lg p-6 max-w-6xl w-full mx-4 my-8 max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold">Create Job Order</h2>
              <button onClick={() => { setShowCreateModal(false); resetForm(); }} className="text-gray-500 hover:text-gray-700">
                ✕
              </button>
            </div>

            {/* Basic Information */}
            <div className="grid grid-cols-2 gap-4 mb-6">
              <div>
                <label className="block text-sm font-medium mb-1">🔍 BOM (Bill of Materials) *</label>
                <div className="space-y-2">
                  <input
                    type="text"
                    placeholder="Search BOM by number, item code, or item name..."
                    value={bomSearchTerm}
                    onChange={(e) => setBomSearchTerm(e.target.value)}
                    className="w-full border rounded px-3 py-2 text-sm"
                  />
                  <select
                    value={formData.bomId}
                    onChange={(e) => {
                      const bomId = e.target.value;
                      setFormData({...formData, bomId});
                      if (bomId) {
                        fetchBOMData(bomId);
                      } else {
                        setFormData({...formData, itemId: ''});
                        setMaterials([]);
                        setOperations([]);
                      }
                    }}
                    className="w-full border rounded px-3 py-2 text-sm"
                    size={Math.min(boms.length + 1, 8)}
                    required
                  >
                    <option value="">-- Select a BOM to manufacture --</option>
                    {boms.map(bom => {
                      const itemCode = bom.item?.code || 'N/A';
                      const itemName = bom.item?.name || 'Unknown Item';
                      const version = bom.version || '1';
                      const status = bom.is_active ? '✓ Active' : 'Inactive';
                      return (
                        <option key={bom.id} value={bom.id}>
                          BOM for: {itemCode} - {itemName} (v{version}) | {status}
                        </option>
                      );
                    })}
                  </select>
                  {bomSearchTerm && boms.length === 0 && (
                    <p className="text-xs text-amber-600">⚠ No BOMs match your search</p>
                  )}
                  {!bomSearchTerm && allBoms.length === 0 && (
                    <p className="text-xs text-red-600">⚠ No BOMs found in system. Create a BOM first.</p>
                  )}
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">
                  📦 Final Product (What you&apos;ll manufacture)
                </label>
                <select
                  value={formData.itemId}
                  onChange={(e) => setFormData({...formData, itemId: e.target.value})}
                  className="w-full border rounded px-3 py-2 text-sm bg-gray-100 cursor-not-allowed"
                  disabled
                  title="This is automatically set based on the BOM you select"
                >
                  <option value="">-- Select BOM first --</option>
                  {items.map(item => (
                    <option key={item.id} value={item.id}>
                      {item.code} - {item.name}
                    </option>
                  ))}
                </select>
                <p className="text-xs text-gray-500 mt-1">ℹ️ Item is automatically set when you select a BOM</p>
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">Quantity *</label>
                <input
                  type="number"
                  value={formData.quantity}
                  onChange={(e) => {
                    const newQuantity = Number(e.target.value);
                    setFormData({...formData, quantity: newQuantity});
                    
                    // Update material quantities based on new job order quantity
                    if (Object.keys(baseMaterialQuantities).length > 0) {
                      const updatedMaterials = materials.map(mat => ({
                        ...mat,
                        requiredQuantity: baseMaterialQuantities[mat.itemId] * newQuantity
                      }));
                      setMaterials(updatedMaterials);
                      console.log('Materials updated for quantity:', newQuantity, updatedMaterials);
                    }
                  }}
                  className="w-full border rounded px-3 py-2"
                  min="1"
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">Start Date *</label>
                <input
                  type="date"
                  value={formData.startDate}
                  onChange={(e) => setFormData({...formData, startDate: e.target.value})}
                  className="w-full border rounded px-3 py-2"
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">End Date</label>
                <input
                  type="date"
                  value={formData.endDate}
                  onChange={(e) => setFormData({...formData, endDate: e.target.value})}
                  className="w-full border rounded px-3 py-2"
                />
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">Priority</label>
                <select
                  value={formData.priority}
                  onChange={(e) => setFormData({...formData, priority: e.target.value})}
                  className="w-full border rounded px-3 py-2"
                >
                  <option value="NORMAL">Normal</option>
                  <option value="HIGH">High</option>
                  <option value="URGENT">Urgent</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">Notes</label>
                <input
                  type="text"
                  value={formData.notes}
                  onChange={(e) => setFormData({...formData, notes: e.target.value})}
                  className="w-full border rounded px-3 py-2"
                  placeholder="Additional notes..."
                />
              </div>
            </div>

            {/* Work Operations */}
            <div className="mb-6">
              <div className="flex justify-between items-center mb-3">
                <h3 className="text-lg font-semibold">Work Operations</h3>
                <button
                  onClick={addOperation}
                  className="px-3 py-1 text-sm bg-blue-600 text-white rounded hover:bg-blue-700"
                >
                  + Add Operation
                </button>
              </div>

              <div className="space-y-3">
                {operations.map((op, idx) => (
                  <div key={idx} className="border border-[#E8DCC4] rounded p-4 bg-white">
                    <div className="grid grid-cols-4 gap-3 mb-2">
                      <div>
                        <label className="block text-xs font-medium mb-1">Sequence #</label>
                        <input
                          type="number"
                          value={op.sequenceNumber}
                          onChange={(e) => updateOperation(idx, 'sequenceNumber', Number(e.target.value))}
                          className="w-full border rounded px-2 py-1 text-sm"
                        />
                      </div>

                      <div className="col-span-3">
                        <label className="block text-xs font-medium mb-1">Operation Name</label>
                        <input
                          type="text"
                          value={op.operationName}
                          onChange={(e) => updateOperation(idx, 'operationName', e.target.value)}
                          className="w-full border rounded px-2 py-1 text-sm"
                          placeholder="e.g., Assembly, Testing, QC"
                        />
                      </div>
                    </div>

                    <div className="grid grid-cols-3 gap-3 mb-2">
                      <div>
                        <label className="block text-xs font-medium mb-1">Workstation</label>
                        <select
                          value={op.workstationId}
                          onChange={(e) => updateOperation(idx, 'workstationId', e.target.value)}
                          className="w-full border rounded px-2 py-1 text-sm"
                        >
                          <option value="">Select...</option>
                          {workstations.map(ws => (
                            <option key={ws.id} value={ws.id}>{ws.code} - {ws.name}</option>
                          ))}
                        </select>
                      </div>

                      <div>
                        <label className="block text-xs font-medium mb-1">Assigned Person</label>
                        <select
                          value={op.assignedUserId || ''}
                          onChange={(e) => updateOperation(idx, 'assignedUserId', e.target.value)}
                          className="w-full border rounded px-2 py-1 text-sm"
                        >
                          <option value="">Unassigned</option>
                          {users.map(user => (
                            <option key={user.id} value={user.id}>
                              {user.employee_name} {user.designation && `(${user.designation})`}
                            </option>
                          ))}
                        </select>
                      </div>

                      <div>
                        <label className="block text-xs font-medium mb-1">Duration (hrs)</label>
                        <input
                          type="number"
                          value={op.expectedDurationHours || ''}
                          onChange={(e) => updateOperation(idx, 'expectedDurationHours', Number(e.target.value))}
                          className="w-full border rounded px-2 py-1 text-sm"
                          step="0.5"
                          placeholder="Hours"
                        />
                      </div>
                    </div>

                    <div className="grid grid-cols-3 gap-3">
                      <div>
                        <label className="block text-xs font-medium mb-1">Variation %</label>
                        <input
                          type="number"
                          value={op.acceptedVariationPercent || 0}
                          onChange={(e) => updateOperation(idx, 'acceptedVariationPercent', Number(e.target.value))}
                          className="w-full border rounded px-2 py-1 text-sm"
                          step="0.1"
                        />
                      </div>

                      <div className="col-span-2">
                        <label className="block text-xs font-medium mb-1">Notes</label>
                        <input
                          type="text"
                          value={op.notes || ''}
                          onChange={(e) => updateOperation(idx, 'notes', e.target.value)}
                          className="w-full border rounded px-2 py-1 text-sm"
                          placeholder="Operation notes..."
                        />
                      </div>
                    </div>

                    <button
                      onClick={() => removeOperation(idx)}
                      className="mt-2 text-xs text-red-600 hover:text-red-800"
                    >
                      Remove Operation
                    </button>
                  </div>
                ))}
              </div>
            </div>

            {/* Materials */}
            <div className="mb-6" id="materials-section">
              <div className="flex justify-between items-center mb-3">
                <h3 className="text-lg font-semibold">Materials Required</h3>
                <button
                  onClick={addMaterial}
                  className="px-3 py-1 text-sm bg-blue-600 text-white rounded hover:bg-blue-700"
                >
                  + Add Material
                </button>
              </div>

              <div className="space-y-2">
                {materials.length === 0 && (
                  <p className="text-sm text-gray-500 italic">No materials added. Click &quot;+ Add Material&quot; or select an item with BOM to auto-load materials.</p>
                )}
                {materials.map((mat, idx) => {
                  // Find item details including current stock
                  const selectedItem = items.find(i => String(i.id) === String(mat.itemId));
                  const summary = itemStockSummaryById[String(mat.itemId || '').trim()];
                  const stockInHand = summary?.total_quantity ?? 0;
                  const stockAvailable = summary?.available_quantity ?? selectedItem?.total_stock ?? 0;
                  const isShort = stockAvailable < mat.requiredQuantity;
                  
                  return (
                  <div key={idx} className="flex gap-3 items-center border border-[#E8DCC4] rounded p-3 bg-white">
                    <div className="flex-1">
                      <label className="block text-xs font-medium mb-1">Item</label>
                      <SearchableSelect
                        options={items.map(item => ({
                          value: item.id,
                          label: `${item.code} - ${item.name}`,
                          subtitle: item.type || undefined
                        }))}
                        value={mat.itemId}
                        onChange={(value) => {
                          console.log('Material changed to:', value);
                          void changeMaterialItem(idx, value);
                        }}
                        placeholder="Search item by code or name..."
                        className="text-sm"
                      />
                    </div>

                    {mat.variants && mat.variants.length > 0 && (
                      <div className="flex-1">
                        <label className="block text-xs font-medium mb-1">
                          Variant/Brand {mat.variants.find((v: any) => v.is_default_variant) && <span className="text-green-600">(Default)</span>}
                        </label>
                        <SearchableSelect
                          options={mat.variants.map((variant: any) => ({
                            value: String(variant.id),
                            label: String(variant.variant_name || variant.name || 'Variant'),
                            subtitle: variant.is_default_variant ? 'Default' : undefined,
                          }))}
                          value={mat.selectedVariantId || mat.itemId}
                          onChange={(value) => updateMaterialVariant(idx, value)}
                          placeholder="Search brand/variant..."
                          className="text-sm"
                        />
                      </div>
                    )}

                    <div className="w-32">
                      <label className="block text-xs font-medium mb-1">Quantity</label>
                      <input
                        type="number"
                        value={mat.requiredQuantity}
                        onChange={(e) => updateMaterial(idx, 'requiredQuantity', Number(e.target.value))}
                        className="w-full border rounded px-2 py-1 text-sm"
                        placeholder="Qty"
                        min="0.01"
                        step="0.01"
                      />
                    </div>
                    
                    <div className="w-32 text-sm">
                      <div className="text-gray-600">Stock in Hand:</div>
                      <div className={`font-semibold ${isShort ? 'text-red-600' : 'text-green-600'}`}>
                        {stockInHand} {selectedItem?.uom || ''}
                        <span className="text-xs block text-gray-600">Available: {stockAvailable}</span>
                        {isShort && <span className="text-xs block text-red-500">Short: {mat.requiredQuantity - stockAvailable}</span>}
                      </div>
                    </div>

                    <button
                      onClick={() => removeMaterial(idx)}
                      className="text-red-600 hover:text-red-800 text-sm"
                    >
                      Remove
                    </button>
                  </div>
                  );
                })}
              </div>
            </div>

            {/* Actions */}
            <div className="flex justify-end gap-3">
              <button
                onClick={() => { setShowCreateModal(false); resetForm(); }}
                className="px-4 py-2 border rounded hover:bg-gray-100"
              >
                Cancel
              </button>
              <button
                onClick={handleCreateJobOrder}
                disabled={loading}
                className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50"
              >
                {loading ? 'Creating...' : 'Create Job Order'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* View Job Order Modal */}
      {selectedJobOrder && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 overflow-y-auto">
          <div className="bg-white rounded-lg p-6 max-w-6xl w-full mx-4 my-8 max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold">Job Order: {selectedJobOrder.jobOrderNumber}</h2>
              <button onClick={() => setSelectedJobOrder(null)} className="text-gray-500 hover:text-gray-700">
                ✕
              </button>
            </div>

            {/* Job Order Details */}
            <div className="grid grid-cols-2 gap-4 mb-6 p-4 bg-gray-50 rounded">
              {selectedJobOrderLoading ? (
                <div className="col-span-2 text-sm text-gray-600">Loading materials & operations…</div>
              ) : null}
              <div>
                <strong>Item:</strong> {selectedJobOrder.itemCode} - {selectedJobOrder.itemName}
              </div>
              <div>
                <strong>Quantity:</strong> {selectedJobOrder.quantity}
              </div>
              <div>
                <strong>Start Date:</strong> {new Date(selectedJobOrder.startDate).toLocaleDateString()}
              </div>
              <div>
                <strong>Priority:</strong> {selectedJobOrder.priority}
              </div>
              <div>
                <strong>Status:</strong> <span className={`px-2 py-1 text-xs rounded ${getStatusColor(selectedJobOrder.status)}`}>
                  {selectedJobOrder.status}
                </span>
              </div>

              <div className="col-span-2 flex justify-end">
                <button
                  onClick={openQcModal}
                  disabled={selectedJobOrder.status !== 'COMPLETED'}
                  className="px-4 py-2 bg-amber-600 text-white rounded hover:bg-amber-700 disabled:opacity-50"
                >
                  Complete QC
                </button>
              </div>

              <div className="col-span-2 text-xs text-gray-600">
                Smart Job Orders issue materials at <strong>creation</strong> (stock reduces immediately). Completion consumes any remaining and adds finished goods.
              </div>
            </div>

            {/* Operations */}
            {selectedJobOrder.operations && selectedJobOrder.operations.length > 0 && (
              <div className="mb-6">
                <h3 className="text-lg font-semibold mb-3">Operations</h3>
                <table className="min-w-full border">
                  <thead className="bg-gray-100">
                    <tr>
                      <th className="border px-3 py-2 text-left text-sm">#</th>
                      <th className="border px-3 py-2 text-left text-sm">Operation</th>
                      <th className="border px-3 py-2 text-left text-sm">Workstation</th>
                      <th className="border px-3 py-2 text-left text-sm">Assigned To</th>
                      <th className="border px-3 py-2 text-left text-sm">Duration</th>
                      <th className="border px-3 py-2 text-left text-sm">Status</th>
                      <th className="border px-3 py-2 text-left text-sm">Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {selectedJobOrder.operations.map((op) => (
                      <tr key={op.id}>
                        <td className="border px-3 py-2 text-sm">{op.sequenceNumber}</td>
                        <td className="border px-3 py-2 text-sm">{op.operationName}</td>
                        <td className="border px-3 py-2 text-sm">{op.workstationName}</td>
                        <td className="border px-3 py-2 text-sm">{op.assignedUserName || 'Unassigned'}</td>
                        <td className="border px-3 py-2 text-sm">{op.expectedDurationHours}h</td>
                        <td className="border px-3 py-2 text-sm">
                          <span className={`px-2 py-1 text-xs rounded ${getStatusColor(op.status || 'NOT_STARTED')}`}>
                            {op.status || 'NOT_STARTED'}
                          </span>
                        </td>
                        <td className="border px-3 py-2 text-sm">
                          {selectedJobOrder.status === 'IN_PROGRESS' && (
                            <>
                              {(!op.status || op.status === 'NOT_STARTED') && (
                                <button
                                  onClick={async () => {
                                    try {
                                      await apiClient.put(`/job-orders/${selectedJobOrder.id}/operations/${op.id}`, {
                                        status: 'IN_PROGRESS',
                                        actualStartDatetime: new Date().toISOString()
                                      });
                                      alert('Operation started');
                                      setSelectedJobOrder(null);
                                      fetchJobOrders();
                                    } catch (error) {
                                      console.error('Error starting operation:', error);
                                      alert('Failed to start operation');
                                    }
                                  }}
                                  className="text-blue-600 hover:text-blue-800 text-xs mr-2"
                                >
                                  Start
                                </button>
                              )}
                              {op.status === 'IN_PROGRESS' && (
                                <button
                                  onClick={async () => {
                                    try {
                                      await apiClient.put(`/job-orders/${selectedJobOrder.id}/operations/${op.id}`, {
                                        status: 'COMPLETED',
                                        actualEndDatetime: new Date().toISOString(),
                                        completedQuantity: selectedJobOrder.quantity
                                      });
                                      alert('Operation completed');
                                      setSelectedJobOrder(null);
                                      fetchJobOrders();
                                    } catch (error) {
                                      console.error('Error completing operation:', error);
                                      alert('Failed to complete operation');
                                    }
                                  }}
                                  className="text-green-600 hover:text-green-800 text-xs"
                                >
                                  Complete
                                </button>
                              )}
                            </>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}

            {/* Materials */}
            {selectedJobOrder.materials && selectedJobOrder.materials.length > 0 && (
              <div className="mb-6">
                <h3 className="text-lg font-semibold mb-3">Materials</h3>
                <table className="min-w-full border">
                  <thead className="bg-gray-100">
                    <tr>
                      <th className="border px-3 py-2 text-left text-sm">Item</th>
                      <th className="border px-3 py-2 text-right text-sm">Required</th>
                      <th className="border px-3 py-2 text-right text-sm">Issued</th>
                      <th className="border px-3 py-2 text-left text-sm">Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {selectedJobOrder.materials.map((mat) => (
                      <tr key={mat.id}>
                        <td className="border px-3 py-2 text-sm">{mat.itemCode} - {mat.itemName}</td>
                        <td className="border px-3 py-2 text-sm text-right">{mat.requiredQuantity}</td>
                        <td className="border px-3 py-2 text-sm text-right">{mat.issuedQuantity || 0}</td>
                        <td className="border px-3 py-2 text-sm">{mat.status}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}

            <div className="flex justify-end">
              <button
                onClick={() => setSelectedJobOrder(null)}
                className="px-4 py-2 border rounded hover:bg-gray-100"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* QC Modal */}
      {showQcModal && selectedJobOrder && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 overflow-y-auto">
          <div className="bg-white rounded-lg p-6 max-w-3xl w-full mx-4 my-8 max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-xl font-bold">Complete QC</h2>
              <button
                onClick={() => {
                  setShowQcModal(false);
                  setQcSubmitting(false);
                  setQcAlreadyApplied(false);
                  setQcSummary(null);
                }}
                className="text-gray-500 hover:text-gray-700"
              >
                ✕
              </button>
            </div>

            <div className="mb-4 p-3 bg-white rounded border border-[#E8DCC4]">
              <div className="text-sm text-gray-600">Job Order</div>
              <div className="font-semibold">{selectedJobOrder.jobOrderNumber}</div>
              <div className="text-sm text-gray-600 mt-2">Item</div>
              <div className="font-semibold">{selectedJobOrder.itemCode} - {selectedJobOrder.itemName}</div>
            </div>

            {qcAlreadyApplied && (
              <div className="mb-4 p-4 rounded border border-green-300 bg-green-50 text-green-900">
                <div className="font-semibold">QC already submitted</div>
                <div className="text-sm mt-1">
                  {qcSummary?.qcAppliedAt
                    ? `Submitted on ${new Date(qcSummary.qcAppliedAt).toLocaleString()}`
                    : 'Submitted previously (timestamp unavailable)'}
                </div>
                {qcSummary && (
                  <div className="text-sm mt-2">
                    Stock added: <span className="font-semibold">{qcSummary.stockAdded}</span> | Approved UIDs: <span className="font-semibold">{qcSummary.approvedUidsCount}</span>
                  </div>
                )}
                <div className="text-sm mt-2">The submit button is disabled to prevent duplicate stock.</div>
              </div>
            )}

            {qcLoading ? (
              <div className="p-6 text-center text-gray-600">Loading UIDs...</div>
            ) : qcUids.length === 0 ? (
              <div className="p-6 text-center text-gray-600">
                <div>No UIDs found for this job order.</div>
                <div className="mt-3">
                  <button
                    onClick={ensureJobOrderUidsAndReloadQc}
                    disabled={qcLoading}
                    className="px-4 py-2 bg-[#8B6F47] text-white rounded hover:bg-[#6F4E37] disabled:opacity-50"
                  >
                    Generate UIDs
                  </button>
                </div>
              </div>
            ) : (
              <>
                <div className="mb-4 flex justify-between items-center">
                  <div className="text-sm text-gray-600">
                    Total UIDs: <span className="font-semibold">{qcUids.length}</span> | 
                    Pending: <span className="font-semibold text-orange-600">
                      {qcUids.filter(u => String(u?.quality_status || '').toUpperCase() !== 'PASSED').length}
                    </span> | 
                    Passed: <span className="font-semibold text-green-600">
                      {qcUids.filter(u => String(u?.quality_status || '').toUpperCase() === 'PASSED').length}
                    </span>
                  </div>
                  <div className="flex gap-2">
                    <button
                      onClick={async () => {
                        const pendingUids = qcUids.filter(u => String(u?.quality_status || '').toUpperCase() !== 'PASSED');
                        if (pendingUids.length === 0) return;
                        
                        if (!confirm(`Mark ${pendingUids.length} UIDs as PASSED?`)) return;
                        
                        setQcLoading(true);
                        try {
                          // Process all UIDs in parallel
                          await Promise.all(
                            pendingUids.map(uid =>
                              apiClient.put(`/uid/${encodeURIComponent(uid.uid)}/quality-status`, {
                                quality_status: 'PASSED',
                              })
                            )
                          );
                          
                          // Update local state after all are complete
                          const updated = qcUids.map(u => 
                            pendingUids.some(p => p.uid === u.uid) 
                              ? { ...u, quality_status: 'PASSED' } 
                              : u
                          );
                          setQcUids(updated);
                          alert(`✅ ${pendingUids.length} UIDs marked as PASSED`);
                        } catch (error: any) {
                          console.error('Error marking all as passed:', error);
                          alert('Failed to mark all UIDs. Please try again.');
                        } finally {
                          setQcLoading(false);
                        }
                      }}
                      className="text-xs px-3 py-1 bg-green-600 text-white rounded hover:bg-green-700"
                      disabled={qcLoading}
                    >
                      Mark All PASS
                    </button>
                  </div>
                </div>

                <div className="border rounded overflow-hidden">
                  <table className="min-w-full divide-y divide-gray-200">
                    <thead className="bg-gray-50">
                      <tr>
                        <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">UID</th>
                        <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Part Number</th>
                        <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">QC Status</th>
                        <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase">Actions</th>
                      </tr>
                    </thead>
                    <tbody className="bg-white divide-y divide-gray-200">
                      {qcUids.map((uid) => {
                        const currentStatus = String(uid?.quality_status || '').toUpperCase() || 'PENDING';
                        return (
                          <tr key={uid.uid} className={currentStatus === 'PASSED' ? 'bg-green-50' : ''}>
                            <td className="px-4 py-3 text-sm font-mono break-all">{uid.uid}</td>
                            <td className="px-4 py-3 text-sm">{uid.client_part_number || '—'}</td>
                            <td className="px-4 py-3 text-sm">
                              <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded ${
                                currentStatus === 'PASSED' 
                                  ? 'bg-green-100 text-green-800' 
                                  : currentStatus === 'ON_HOLD' 
                                  ? 'bg-orange-100 text-orange-800'
                                  : 'bg-gray-100 text-gray-800'
                              }`}>
                                {currentStatus}
                              </span>
                            </td>
                            <td className="px-4 py-3 text-sm text-center">
                              {currentStatus !== 'PASSED' && (
                                <div className="flex justify-center gap-2">
                                  <button
                                    onClick={() => setCurrentUidQc('ON_HOLD', uid.uid)}
                                    className="px-3 py-1 bg-orange-600 text-white text-xs rounded hover:bg-orange-700"
                                    title="Mark as Failed / On Hold"
                                  >
                                    FAIL
                                  </button>
                                  <button
                                    onClick={() => setCurrentUidQc('PASSED', uid.uid)}
                                    className="px-3 py-1 bg-green-600 text-white text-xs rounded hover:bg-green-700"
                                    title="Mark as Passed"
                                  >
                                    PASS
                                  </button>
                                </div>
                              )}
                              {currentStatus === 'PASSED' && (
                                <span className="text-green-600 font-semibold">✓ Passed</span>
                              )}
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>

                <div className="mt-6 p-4 bg-blue-50 border border-blue-200 rounded">
                  <p className="text-sm text-gray-700 mb-4">
                    <strong>Important:</strong> After completing QC inspection for all UIDs, click &quot;Submit QC Results&quot; below. 
                    Only <strong>PASSED</strong> UIDs will be added to stock. Failed UIDs will be marked for rework/scrap.
                  </p>
                  <button
                    onClick={async () => {
                      if (qcAlreadyApplied) {
                        alert('QC is already submitted for this job order. Stock has already been updated.');
                        return;
                      }
                      const approvedUids = qcUids.filter(u => String(u?.quality_status || '').toUpperCase() === 'PASSED').map(u => u.uid);
                      const rejectedUids = qcUids.filter(u => String(u?.quality_status || '').toUpperCase() !== 'PASSED').map(u => u.uid);

                      if (approvedUids.length === 0 && rejectedUids.length === 0) {
                        alert('Please mark UIDs as PASS or FAIL before submitting QC results');
                        return;
                      }

                      if (!confirm(`Submit QC Results?\n\nApproved (will add to stock): ${approvedUids.length}\nRejected (rework/scrap): ${rejectedUids.length}`)) {
                        return;
                      }

                      setQcSubmitting(true);
                      try {
                        const response = await apiClient.post(`/job-orders/${selectedJobOrder.id}/qc-approve`, {
                          approvedUids,
                          rejectedUids,
                        });

                        alert(`✅ QC Complete!\n\n${response.message || `${approvedUids.length} units added to stock, ${rejectedUids.length} rejected`}`);
                        setQcAlreadyApplied(true);
                        setShowQcModal(false);
                        setQcUids([]);
                        fetchJobOrders();
                      } catch (error: any) {
                        console.error('Error submitting QC results:', error);
                        const errorMsg = error.response?.data?.message || error.message || 'Failed to submit QC results';
                        alert(errorMsg);
                      } finally {
                        setQcSubmitting(false);
                      }
                    }}
                    disabled={qcLoading || qcSubmitting || qcAlreadyApplied}
                    className="w-full px-6 py-3 bg-blue-600 text-white font-semibold rounded hover:bg-blue-700 disabled:opacity-50"
                  >
                    {qcAlreadyApplied ? 'QC Already Submitted' : qcSubmitting ? 'Submitting QC…' : 'Submit QC Results & Add Stock'}
                  </button>
                </div>
              </>
            )}
          </div>
        </div>
      )}

      {/* Completion Preview Modal */}
      {showCompletionModal && completionPreview && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50 overflow-y-auto">
          <div className="bg-white rounded-lg max-w-4xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b">
              <h2 className="text-2xl font-bold text-gray-900">Complete Job Order - Stock Impact Preview</h2>
              <p className="text-gray-600 mt-1">Job Order: {completionPreview.jobOrderNumber}</p>
            </div>

            <div className="p-6 space-y-6">
              {/* Finished Product Section */}
              <div className="bg-green-50 border border-green-200 rounded-lg p-4">
                <h3 className="text-lg font-semibold text-green-900 mb-3">✅ Finished Product to Add</h3>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <p className="text-sm text-gray-600">Product</p>
                    <p className="text-base font-semibold text-gray-900">
                      {completionPreview.finishedProduct.itemCode} - {completionPreview.finishedProduct.itemName}
                    </p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-600">Quantity to Add</p>
                    <p className="text-2xl font-bold text-green-600">+{completionPreview.finishedProduct.quantityToAdd}</p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-600">Current Stock</p>
                    <p className="text-lg font-medium text-gray-700">{completionPreview.finishedProduct.currentStock}</p>
                  </div>
                  <div>
                    <p className="text-sm text-gray-600">New Stock</p>
                    <p className="text-lg font-bold text-green-700">{completionPreview.finishedProduct.newStock}</p>
                  </div>
                </div>
              </div>

              {/* Materials to Consume Section */}
              <div>
                <h3 className="text-lg font-semibold text-gray-900 mb-3">📦 Materials to Consume</h3>
                <div className="overflow-x-auto">
                  <table className="min-w-full divide-y divide-gray-200 border">
                    <thead className="bg-gray-50">
                      <tr>
                        <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Item</th>
                        <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">To Consume</th>
                        <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">Current Stock</th>
                        <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">Reserved</th>
                        <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">New Stock</th>
                        <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase">Status</th>
                      </tr>
                    </thead>
                    <tbody className="bg-white divide-y divide-gray-200">
                      {completionPreview.materialsToConsume.map((material: any, index: number) => (
                        <tr key={index} className={material.sufficient ? '' : 'bg-red-50'}>
                          <td className="px-4 py-3 text-sm">
                            <div className="font-medium text-gray-900">{material.itemCode}</div>
                            <div className="text-gray-500 text-xs">{material.itemName}</div>
                          </td>
                          <td className="px-4 py-3 text-sm text-right font-semibold text-red-600">-{material.toConsume}</td>
                          <td className="px-4 py-3 text-sm text-right">{material.currentStock}</td>
                          <td className="px-4 py-3 text-sm text-right text-yellow-600">{material.reservedStock}</td>
                          <td className="px-4 py-3 text-sm text-right font-medium">
                            {material.newStock >= 0 ? (
                              <span className="text-gray-900">{material.newStock}</span>
                            ) : (
                              <span className="text-red-600 font-bold">{material.newStock}</span>
                            )}
                          </td>
                          <td className="px-4 py-3 text-center">
                            {material.sufficient ? (
                              <span className="inline-flex px-2 py-1 text-xs font-semibold rounded-full bg-green-100 text-green-800">
                                ✓ OK
                              </span>
                            ) : (
                              <span className="inline-flex px-2 py-1 text-xs font-semibold rounded-full bg-red-100 text-red-800">
                                ⚠ Insufficient
                              </span>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>

              {/* Warning for insufficient materials */}
              {!completionPreview.canComplete && (
                <div className="bg-red-50 border border-red-200 rounded-lg p-4">
                  <h3 className="text-lg font-semibold text-red-900 mb-2">⚠️ Cannot Complete Job Order</h3>
                  <p className="text-sm text-red-700 mb-3">
                    The following materials have insufficient stock:
                  </p>
                  <ul className="list-disc list-inside text-sm text-red-700 space-y-1">
                    {completionPreview.insufficientMaterials.map((mat: any, idx: number) => (
                      <li key={idx}>
                        {mat.itemCode} - {mat.itemName}: Need {mat.toConsume}, Have {mat.currentStock}
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {/* Summary */}
              <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                <p className="text-sm text-blue-800">
                  <strong>Note:</strong> Completing this job order will automatically update inventory. 
                  Materials will be consumed and finished goods will be added. This action cannot be undone.
                </p>
              </div>
            </div>

            <div className="p-6 border-t flex justify-end gap-3">
              <button
                onClick={() => {
                  setShowCompletionModal(false);
                  setCompletionPreview(null);
                  setCompletionJobOrderId(null);
                }}
                className="px-6 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
              >
                Cancel
              </button>
              <button
                onClick={confirmCompletion}
                disabled={!completionPreview.canComplete || loading}
                className={`px-6 py-2 rounded-lg font-semibold ${
                  completionPreview.canComplete && !loading
                    ? 'bg-green-600 hover:bg-green-700 text-white'
                    : 'bg-gray-300 text-gray-500 cursor-not-allowed'
                }`}
              >
                {loading ? 'Completing...' : 'Confirm & Complete'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Stock Shortage Error Modal */}
      {stockErrorModal.show && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-xl shadow-2xl max-w-2xl w-full max-h-[90vh] overflow-auto">
            <div className="p-6 border-b border-gray-200">
              <div className="flex items-center gap-3">
                <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center">
                  <svg className="w-6 h-6 text-red-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                  </svg>
                </div>
                <div>
                  <h3 className="text-xl font-bold text-gray-900">Insufficient Stock</h3>
                  <p className="text-sm text-gray-600 mt-1">Cannot create job order due to material shortages</p>
                </div>
              </div>
            </div>

            <div className="p-6">
              <div className="mb-4">
                <p className="text-sm text-gray-700 mb-4">
                  The following materials are not available in sufficient quantities:
                </p>
                
                <div className="overflow-x-auto">
                  <table className="min-w-full divide-y divide-gray-200">
                    <thead className="bg-gray-50">
                      <tr>
                        <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                          Material
                        </th>
                        <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">
                          Required
                        </th>
                        <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">
                          Available
                        </th>
                        <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">
                          Shortage
                        </th>
                      </tr>
                    </thead>
                    <tbody className="bg-white divide-y divide-gray-200">
                      {stockErrorModal.shortages.map((shortage: any, idx: number) => (
                        <tr key={idx} className="hover:bg-gray-50">
                          <td className="px-4 py-3 text-sm text-gray-900">
                            {shortage.material}
                          </td>
                          <td className="px-4 py-3 text-sm text-center text-gray-700 font-medium">
                            {shortage.needed}
                          </td>
                          <td className="px-4 py-3 text-sm text-center">
                            <span className="text-orange-600 font-semibold">
                              {shortage.available}
                            </span>
                          </td>
                          <td className="px-4 py-3 text-sm text-center">
                            <span className="inline-flex items-center px-3 py-1 rounded-full text-xs font-medium bg-red-100 text-red-800">
                              {shortage.short} short
                            </span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>

              <div className="mt-6 p-4 bg-blue-50 border border-blue-200 rounded-lg">
                <div className="flex gap-3">
                  <svg className="w-5 h-5 text-blue-600 flex-shrink-0 mt-0.5" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
                  </svg>
                  <div>
                    <h4 className="text-sm font-semibold text-blue-900">Next Steps</h4>
                    <p className="text-sm text-blue-800 mt-1">
                      Please add inventory for these materials before creating the job order. You can do this from the Inventory module.
                    </p>
                  </div>
                </div>
              </div>
            </div>

            <div className="p-6 border-t border-gray-200 flex justify-end gap-3">
              <button
                onClick={() => setStockErrorModal({show: false, shortages: []})}
                className="px-6 py-2.5 bg-gray-600 hover:bg-gray-700 text-white rounded-lg font-medium transition-colors"
              >
                Close
              </button>
              <button
                onClick={() => {
                  setStockErrorModal({show: false, shortages: []});
                  window.location.href = '/dashboard/inventory/items';
                }}
                className="px-6 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-medium transition-colors"
              >
                Go to Inventory
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { Suspense, useEffect, useMemo, useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { apiClient } from '../../../../../../lib/api-client';
import SearchableSelect from '../../../../../components/SearchableSelect';
import { ChevronDown, ChevronRight, Package, Layers } from 'lucide-react';

type FinishedItem = {
  id: string;
  code: string;
  name: string;
  category?: string | null;
};

type RawItem = {
  id?: string | number;
  item_id?: string | number;
  code?: string;
  item_code?: string;
  name?: string;
  item_name?: string;
  category?: string | null;
};

type SmartExplosionNode = {
  level: number;
  componentType: 'ITEM' | 'BOM';
  bomId: string;
  parentBomId?: string;
  itemId: string;
  itemCode: string;
  itemName: string;
  requiredQuantity: number;
  availableQuantity: number;
  toMakeQuantity: number;
  shortageQuantity: number;
};

type SmartSubAssemblyPlan = {
  bomId: string;
  itemId: string;
  itemCode: string;
  itemName: string;
  requiredQuantity: number;
  availableQuantity: number;
  toMakeQuantity: number;
};

type ItemStockSummary = {
  total_quantity?: number;
  available_quantity?: number;
  allocated_quantity?: number;
};

type SmartPreview = {
  finishedItem: FinishedItem;
  quantity: number;
  topBom: {
    id: string;
    version: number;
    is_active?: boolean;
  };
  nodes: SmartExplosionNode[];
  subAssembliesToMake: SmartSubAssemblyPlan[];
  source: {
    salesOrderId: string | null;
    salesOrderItemId: string | null;
  };
};

type JobOrderListRow = {
  id: string;
  job_order_number?: string;
  jobOrderNumber?: string;
  item_code?: string;
  item_name?: string;
  quantity?: number;
  status?: string;
  start_date?: string;
  created_at?: string;
};

type JobOrderDetail = {
  id: string;
  job_order_number?: string;
  item_code?: string;
  item_name?: string;
  quantity?: number;
  status?: string;
  start_date?: string;
  created_at?: string;
  materials?: Array<{
    id: string;
    item_code?: string;
    item_name?: string;
    required_quantity?: number;
    issued_quantity?: number;
    status?: string;
  }>;
};
type SmartCreateResponse = {
  jobOrder?: any;
  autoCompletedSubJobOrders?: any[];
  preview?: SmartPreview;
};

export default function SmartJobOrdersItemsPage() {
  return (
    <Suspense
      fallback={
        <div className="p-6">
          <div className="text-xl">Loading...</div>
        </div>
      }
    >
      <SmartJobOrdersItemsPageContent />
    </Suspense>
  );
}

function SmartJobOrdersItemsPageContent() {
  const router = useRouter();
  const searchParams = useSearchParams();

  const prefillItemId = searchParams.get('itemId') || '';
  const prefillQuantity = Number(searchParams.get('quantity') || '') || 1;
  const salesOrderId = searchParams.get('salesOrderId');
  const salesOrderItemId = searchParams.get('salesOrderItemId');

  const [itemId, setItemId] = useState<string>(prefillItemId);
  const [quantity, setQuantity] = useState<number>(prefillQuantity);

  const [itemsLoading, setItemsLoading] = useState(false);
  const [itemsError, setItemsError] = useState<string>('');
  const [finishedGoodsItems, setFinishedGoodsItems] = useState<FinishedItem[]>([]);
  const [allItems, setAllItems] = useState<FinishedItem[]>([]);

  const [loadingPreview, setLoadingPreview] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [loadingMessage, setLoadingMessage] = useState('');
  const [preview, setPreview] = useState<SmartPreview | null>(null);
  const [previewError, setPreviewError] = useState<string>('');

  const [selectedItemByNodeKey, setSelectedItemByNodeKey] = useState<Record<string, string>>({});
  const [stockByItemId, setStockByItemId] = useState<
    Record<string, { available: number; loading: boolean; error?: string }>
  >({});
  const [expandedBoms, setExpandedBoms] = useState<Set<string>>(new Set());
  const [showShortageDetails, setShowShortageDetails] = useState(false);

  const [creating, setCreating] = useState(false);
  const [creatingPR, setCreatingPR] = useState(false);
  const [createSummary, setCreateSummary] = useState<SmartCreateResponse | null>(null);
  const [showCreateSummary, setShowCreateSummary] = useState(false);

  useEffect(() => {
    const previousOverflow = document.body.style.overflow;
    if (showCreateSummary) document.body.style.overflow = 'hidden';
    return () => {
      document.body.style.overflow = previousOverflow;
    };
  }, [showCreateSummary]);

  const canPreview = Boolean(itemId) && Number(quantity) > 0;

  const headerSubtitle = useMemo(() => {
    if (salesOrderId) return `From Sales Order: ${salesOrderId}`;
    return 'Swap BOM items (brand) using dropdowns, then create JO';
  }, [salesOrderId]);

  const finishedGoodsOptions = useMemo(
    () =>
      finishedGoodsItems.map((i) => ({
        value: i.id,
        label: i.code,
        subtitle: i.name,
      })),
    [finishedGoodsItems],
  );

  const allItemOptions = useMemo(
    () =>
      allItems.map((i) => ({
        value: i.id,
        label: i.code,
        subtitle: i.name,
      })),
    [allItems],
  );

  const fetchItems = async () => {
    setItemsError('');
    setItemsLoading(true);
    try {
      // Fetch all BOMs to get items that have BOMs (for finished goods dropdown)
      const bomsResponse = await apiClient.get('/bom');
      const bomsList = Array.isArray(bomsResponse) ? bomsResponse : [];
      
      // Extract unique item IDs from BOMs
      const itemsWithBoms = new Set<string>();
      const itemDataMap = new Map<string, { code: string; name: string; category?: string | null }>();
      
      bomsList.forEach((bom: any) => {
        // Try multiple field patterns for item ID
        const itemId = bom.item?.id || bom.item_id || bom.itemId;
        if (itemId) {
          const id = String(itemId);
          itemsWithBoms.add(id);
          itemDataMap.set(id, {
            code: bom.item?.code || bom.item?.item_code || '',
            name: bom.item?.name || bom.item?.item_name || '',
            category: bom.item?.category ?? null,
          });
        }
      });

      // Create normalized list of finished goods items (items that have BOMs)
      const finishedGoods: FinishedItem[] = Array.from(itemsWithBoms)
        .map((id) => {
          const data = itemDataMap.get(id);
          if (!data?.code || !data?.name) return null;
          return {
            id,
            code: data.code,
            name: data.name,
            category: data.category,
          } as FinishedItem;
        })
        .filter((i) => i !== null) as FinishedItem[];

      console.log('[Job Orders] Loaded finished goods with BOMs:', finishedGoods.length, finishedGoods);
      setFinishedGoodsItems(finishedGoods);

      // Fetch ALL items for component selection dropdowns
      const allItemsResponse = await apiClient.get('/inventory/items');
      const allItemsList = Array.isArray(allItemsResponse) ? allItemsResponse : [];
      
      const allItemsNormalized: FinishedItem[] = allItemsList
        .map((raw: RawItem) => {
          const id = raw.id || raw.item_id;
          const code = raw.code || raw.item_code;
          const name = raw.name || raw.item_name;
          if (!id || !code || !name) return null;
          return {
            id: String(id),
            code: String(code),
            name: String(name),
            category: raw.category,
          } as FinishedItem;
        })
        .filter((i) => i !== null) as FinishedItem[];

      console.log('[Job Orders] Loaded all items for component dropdowns:', allItemsNormalized.length);
      setAllItems(allItemsNormalized);
    } catch (err: any) {
      console.error('[Job Orders] Error loading items:', err);
      setFinishedGoodsItems([]);
      setAllItems([]);
      setItemsError(err?.message || 'Failed to load items');
    } finally {
      setItemsLoading(false);
    }
  };

  const nodeKey = (node: SmartExplosionNode) => `${node.bomId}:${node.itemId}`;

  const isUuid = (value: unknown) => {
    if (typeof value !== 'string') return false;
    const v = value.trim();
    if (!v) return false;
    return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(v);
  };

  const fetchItemStockAvailable = async (itemIdToCheck: string) => {
    const id = String(itemIdToCheck || '').trim();
    if (!id) return;

    setStockByItemId((prev) => {
      const existing = prev[id];
      if (existing?.loading) return prev;
      return {
        ...prev,
        [id]: { available: existing?.available ?? 0, loading: true },
      };
    });

    try {
      const summary = (await apiClient.get(`/items/${id}/stock`)) as ItemStockSummary;
      const available = Number((summary as any)?.available_quantity ?? 0) || 0;
      setStockByItemId((prev) => ({
        ...prev,
        [id]: { available, loading: false },
      }));
    } catch (err: any) {
      setStockByItemId((prev) => ({
        ...prev,
        [id]: {
          available: prev[id]?.available ?? 0,
          loading: false,
          error: err?.message || 'Failed to load stock',
        },
      }));
    }
  };

  const fetchPreview = async () => {
    if (!canPreview) return;
    setPreviewError('');
    setLoadingPreview(true);
    setLoadingProgress(0);
    setLoadingMessage('🔍 Loading BOM...');

    try {
      const progressInterval = setInterval(() => {
        setLoadingProgress((prev) => {
          if (prev < 25) {
            setLoadingMessage('🔍 Loading BOM...');
            return prev + 2;
          } else if (prev < 60) {
            setLoadingMessage('💥 Exploding BOM structure...');
            return prev + 2;
          } else if (prev < 90) {
            setLoadingMessage('📦 Extracting items...');
            return prev + 1;
          }
          return prev;
        });
      }, 200);

      const data = (await apiClient.get('/job-orders/smart/preview', {
        itemId,
        quantity,
        salesOrderId: salesOrderId || undefined,
        salesOrderItemId: salesOrderItemId || undefined,
        includeAllComponents: true,
      })) as SmartPreview;

      clearInterval(progressInterval);
      setLoadingProgress(100);
      setLoadingMessage('✅ Preview ready!');

      setTimeout(() => {
        setPreview(data);
        setLoadingPreview(false);
      }, 300);
    } catch (err: any) {
      setPreview(null);
      setPreviewError(err?.message || 'Failed to load BOM preview');
      setLoadingPreview(false);
      setLoadingProgress(0);
      setLoadingMessage('');
    }
  };

  useEffect(() => {
    fetchItems();

    if (prefillItemId) {
      fetchPreview();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (!preview?.nodes?.length) {
      setSelectedItemByNodeKey({});
      setStockByItemId({});
      setExpandedBoms(new Set());
      return;
    }

    const itemNodes = preview.nodes.filter((n) => n.componentType === 'ITEM' && n.itemId);
    const bomNodes = preview.nodes.filter((n) => n.componentType === 'BOM');
    
    // Expand all BOMs by default
    setExpandedBoms(new Set([preview.topBom.id, ...bomNodes.map((b) => b.bomId)]));

    let cancelled = false;

    (async () => {
      const nextSelected: Record<string, string> = {};
      const toFetchStock = new Set<string>();

      for (const node of itemNodes) {
        const key = nodeKey(node);
        const selected = String(node.itemId);
        nextSelected[key] = selected;
        toFetchStock.add(selected);
      }

      if (cancelled) return;

      setSelectedItemByNodeKey(nextSelected);
      await Promise.all(Array.from(toFetchStock).map((id) => fetchItemStockAvailable(id)));
    })();

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [preview?.topBom?.id, preview?.quantity, preview?.finishedItem?.id]);

  useEffect(() => {
    if (!canPreview) return;

    const handle = setTimeout(() => {
      fetchPreview();
    }, 350);

    return () => clearTimeout(handle);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [itemId, quantity, salesOrderId, salesOrderItemId]);

  const handlePurchaseShortageItems = async () => {
    if (!preview) return;

    const itemsWithShortage = preview.nodes.filter(n => {
      if (n.componentType !== 'ITEM') return false;
      const key = nodeKey(n);
      const selectedItemId = selectedItemByNodeKey[key] || n.itemId;
      const stockState = selectedItemId ? stockByItemId[selectedItemId] : undefined;
      const available = stockState?.available ?? n.availableQuantity;
      return Number(n.requiredQuantity || 0) > Number(available || 0);
    });

    const autoMakeItemIds = new Set((preview.subAssembliesToMake || []).map(sa => sa.itemId));
    const rawMaterialShortages = itemsWithShortage.filter(item => {
      const selectedItemId = selectedItemByNodeKey[nodeKey(item)] || item.itemId;
      return !autoMakeItemIds.has(selectedItemId);
    });

    if (rawMaterialShortages.length === 0) return;

    setCreatingPR(true);
    try {
      // Create PR with shortage items
      const prItems = rawMaterialShortages.map(item => {
        const key = nodeKey(item);
        const selectedItemId = selectedItemByNodeKey[key] || item.itemId;
        const stockState = selectedItemId ? stockByItemId[selectedItemId] : undefined;
        const available = stockState?.available ?? item.availableQuantity;
        const shortage = Math.max(0, Number(item.requiredQuantity || 0) - Number(available || 0));
        
        return {
          itemCode: item.itemCode,
          itemName: item.itemName,
          requestedQty: Math.ceil(shortage), // Round up to ensure we have enough
          description: `For Job Order: ${preview.finishedItem.code} (Shortage)`,
          uom: 'PCS', // Default unit, can be enhanced later
        };
      });

      const prData = {
        requestDate: new Date().toISOString().split('T')[0],
        purpose: `Auto-generated PR for Job Order shortage: ${preview.finishedItem.code}`,
        items: prItems,
      };

      const result = await apiClient.post('/purchase/requisitions', prData);
      const prId = result?.id || result?.pr_id;
      
      if (prId) {
        // Navigate to PR page
        router.push(`/dashboard/purchase/requisitions?prId=${prId}`);
      } else {
        alert('✅ Purchase Requisition created successfully!');
        router.push('/dashboard/purchase/requisitions');
      }
    } catch (err: any) {
      alert(`❌ Failed to create Purchase Requisition: ${err?.message || 'Unknown error'}`);
    } finally {
      setCreatingPR(false);
    }
  };

  const handleCreate = async () => {
    if (!canPreview) {
      alert('Please select a Finished Good item and quantity');
      return;
    }

    // Check if any RAW MATERIALS (items without BOMs) are out of stock
    const itemsWithShortage = preview?.nodes?.filter(n => {
      if (n.componentType !== 'ITEM') return false;
      const key = nodeKey(n);
      const selectedItemId = selectedItemByNodeKey[key] || n.itemId;
      const stockState = selectedItemId ? stockByItemId[selectedItemId] : undefined;
      const available = stockState?.available ?? n.availableQuantity;
      return Number(n.requiredQuantity || 0) > Number(available || 0);
    }) || [];

    // Filter out items that can be auto-made (those with BOMs in subAssembliesToMake)
    const autoMakeItemIds = new Set((preview?.subAssembliesToMake || []).map(sa => sa.itemId));
    const rawMaterialShortages = itemsWithShortage.filter(item => {
      const selectedItemId = selectedItemByNodeKey[nodeKey(item)] || item.itemId;
      return !autoMakeItemIds.has(selectedItemId);
    });

    if (rawMaterialShortages.length > 0) {
      const shortageList = rawMaterialShortages.map(item => {
        const key = nodeKey(item);
        const selectedItemId = selectedItemByNodeKey[key] || item.itemId;
        const stockState = selectedItemId ? stockByItemId[selectedItemId] : undefined;
        const available = stockState?.available ?? item.availableQuantity;
        const shortage = Number(item.requiredQuantity || 0) - Number(available || 0);
        return `${item.itemCode} - ${item.itemName}: Need ${formatQuantity(item.requiredQuantity)}, Have ${formatQuantity(available)}, Short ${formatQuantity(shortage)}`;
      }).join('\n');
      
      alert(`❌ Cannot create Job Order - Raw materials out of stock:\n\n${shortageList}\n\nPlease purchase or adjust stock before creating this job order.`);
      return;
    }

    setCreating(true);
    try {
      const itemSelections: Record<string, string> = {};
      if (preview?.nodes?.length) {
        for (const node of preview.nodes) {
          if (node.componentType !== 'ITEM' || !node.itemId) continue;
          const key = nodeKey(node);
          const selected = selectedItemByNodeKey[key];
          if (selected && isUuid(selected)) itemSelections[key] = selected;
        }
      }

      const result = (await apiClient.post('/job-orders/smart/create', {
        itemId,
        quantity: Number(quantity),
        startDate: new Date().toISOString().slice(0, 10),
        salesOrderId: salesOrderId || undefined,
        salesOrderItemId: salesOrderItemId || undefined,
        itemSelections,
      })) as SmartCreateResponse;

      setCreateSummary(result);
      setShowCreateSummary(true);

      await fetchPreview();
    } catch (err: any) {
      alert(`❌ Failed to create Smart Job Order: ${err?.message || 'Unknown error'}`);
    } finally {
      setCreating(false);
    }
  };

  const formatQuantity = (value: number | string | undefined): string => {
    const num = Number(value || 0);
    if (num === 0) return '0';
    // Round to 4 decimal places and remove trailing zeros
    const rounded = Math.round(num * 10000) / 10000;
    return rounded.toString();
  };

  const renderExplosionTree = () => {
    if (!preview) return null;

    const rootBomId = preview.topBom.id;
    const virtualRoot: SmartExplosionNode = {
      level: 0,
      componentType: 'BOM',
      bomId: rootBomId,
      parentBomId: undefined,
      itemId: preview.finishedItem.id,
      itemCode: preview.finishedItem.code,
      itemName: preview.finishedItem.name,
      requiredQuantity: preview.quantity,
      availableQuantity: 0,
      toMakeQuantity: 0,
      shortageQuantity: 0,
    };

    const bomNodes = [virtualRoot, ...preview.nodes.filter((n) => n.componentType === 'BOM')];
    const itemNodes = preview.nodes.filter((n) => n.componentType === 'ITEM');

    const bomById = new Map<string, SmartExplosionNode>();
    for (const b of bomNodes) {
      if (!bomById.has(b.bomId)) bomById.set(b.bomId, b);
    }

    const childBomIdsByParent = new Map<string, string[]>();
    for (const b of bomNodes) {
      if (b.bomId === rootBomId) continue;
      const parentId = b.parentBomId || rootBomId;
      const list = childBomIdsByParent.get(parentId) || [];
      list.push(b.bomId);
      childBomIdsByParent.set(parentId, list);
    }

    const itemNodesByBomId = new Map<string, SmartExplosionNode[]>();
    for (const n of itemNodes) {
      const list = itemNodesByBomId.get(n.bomId) || [];
      list.push(n);
      itemNodesByBomId.set(n.bomId, list);
    }

    // Deduplicate items within each BOM level - sum up quantities for same item
    for (const [bid, items] of itemNodesByBomId.entries()) {
      const dedupMap = new Map<string, SmartExplosionNode>();
      for (const item of items) {
        const key = item.itemId;
        if (dedupMap.has(key)) {
          // Merge quantities for duplicate items
          const existing = dedupMap.get(key)!;
          existing.requiredQuantity += item.requiredQuantity;
          existing.shortageQuantity = Math.max(0, existing.requiredQuantity - existing.availableQuantity);
        } else {
          dedupMap.set(key, { ...item });
        }
      }
      itemNodesByBomId.set(bid, Array.from(dedupMap.values()));
    }

    // Stable ordering: by level then item code
    for (const [parentId, list] of childBomIdsByParent.entries()) {
      const sorted = [...list].sort((a, b) => {
        const aa = bomById.get(a);
        const bb = bomById.get(b);
        const lvlA = Number(aa?.level ?? 0);
        const lvlB = Number(bb?.level ?? 0);
        if (lvlA !== lvlB) return lvlA - lvlB;
        return String(aa?.itemCode || '').localeCompare(String(bb?.itemCode || ''));
      });
      childBomIdsByParent.set(parentId, sorted);
    }

    for (const [bid, list] of itemNodesByBomId.entries()) {
      itemNodesByBomId.set(
        bid,
        [...list].sort((a, b) => String(a.itemCode || '').localeCompare(String(b.itemCode || ''))),
      );
    }

    const toggleBom = (id: string) => {
      setExpandedBoms((prev) => {
        const next = new Set(prev);
        if (next.has(id)) next.delete(id);
        else next.add(id);
        return next;
      });
    };

    const shortageMemo = new Map<string, boolean>();
    const hasShortageInBom = (id: string): boolean => {
      const cached = shortageMemo.get(id);
      if (cached !== undefined) return cached;

      const directItems = itemNodesByBomId.get(id) || [];
      for (const item of directItems) {
        const key = nodeKey(item);
        const selectedItemId = selectedItemByNodeKey[key] || item.itemId;
        const stockState = selectedItemId ? stockByItemId[selectedItemId] : undefined;
        const available = stockState?.available ?? item.availableQuantity;
        if (Number(item.requiredQuantity || 0) > Number(available || 0)) {
          shortageMemo.set(id, true);
          return true;
        }
      }

      const childBoms = childBomIdsByParent.get(id) || [];
      for (const childId of childBoms) {
        if (hasShortageInBom(childId)) {
          shortageMemo.set(id, true);
          return true;
        }
      }

      shortageMemo.set(id, false);
      return false;
    };

    const getBgColor = (lvl: number) => {
      if (lvl === 0) return 'bg-amber-100 hover:bg-amber-200';
      if (lvl === 1) return 'bg-amber-50 hover:bg-amber-100';
      if (lvl === 2) return 'bg-orange-50 hover:bg-orange-100';
      return 'bg-yellow-50 hover:bg-yellow-100';
    };

    const renderBom = (id: string, isFirstInSection: boolean) => {
      const bom = bomById.get(id);
      if (!bom) return null;

      const isExpanded = expandedBoms.has(id);
      const directItems = itemNodesByBomId.get(id) || [];
      const childBoms = childBomIdsByParent.get(id) || [];
      const hasShortage = hasShortageInBom(id);
      const lvl = Number(bom.level ?? 0);

      return (
        <div key={id} className={!isFirstInSection ? 'border-t border-gray-200' : ''}>
          <div
            onClick={() => toggleBom(id)}
            className={`flex items-center gap-3 px-4 py-3 cursor-pointer transition-colors ${getBgColor(lvl)}`}
            style={{ paddingLeft: `${16 + lvl * 24}px` }}
          >
            <span className="text-amber-700">
              {isExpanded ? <ChevronDown size={18} /> : <ChevronRight size={18} />}
            </span>
            <Layers size={16} className="text-amber-600" />
            <span className="font-semibold text-amber-900 flex items-center gap-2">
              {bom.itemCode} - {bom.itemName}
              {lvl > 0 && (
                <span className="px-2 py-0.5 rounded-full bg-blue-100 text-blue-700 text-xs font-medium">
                  Level {lvl} Sub-BOM
                </span>
              )}
            </span>
            <span className="ml-auto flex items-center gap-4 text-sm">
              <span className="text-amber-700">
                {directItems.length} item{directItems.length !== 1 ? 's' : ''}
                {childBoms.length ? ` • ${childBoms.length} sub` : ''}
              </span>
              {hasShortage && (
                <span className="px-2 py-0.5 rounded-full bg-red-100 text-red-700 text-xs font-medium">
                  Shortage
                </span>
              )}
            </span>
          </div>

          {isExpanded && (
            <div className="bg-white">
              {directItems.length > 0 ? (
                <table className="min-w-full">
                  <thead className="bg-gray-50 border-b border-gray-200">
                    <tr>
                      <th
                        className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase"
                        style={{ paddingLeft: `${40 + lvl * 24}px` }}
                      >
                        Item
                      </th>
                      <th className="px-4 py-2 text-right text-xs font-medium text-gray-500 uppercase w-24">
                        Required
                      </th>
                      <th className="px-4 py-2 text-right text-xs font-medium text-gray-500 uppercase w-24">
                        In Stock
                      </th>
                      <th className="px-4 py-2 text-right text-xs font-medium text-gray-500 uppercase w-24">
                        Short
                      </th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100">
                    {directItems.map((node, idx) => {
                      const key = nodeKey(node);
                      const selectedItemId = selectedItemByNodeKey[key] || node.itemId;
                      const stockState = selectedItemId ? stockByItemId[selectedItemId] : undefined;
                      const available = stockState?.available ?? node.availableQuantity;
                      const inStockLabel = stockState?.loading ? '…' : formatQuantity(available);
                      const requiredQty = Number(node.requiredQuantity || 0);
                      const short = Math.max(0, requiredQty - Number(available || 0));

                      return (
                        <tr key={`${node.bomId}:${node.itemId}:${idx}`} className="hover:bg-gray-50">
                          <td className="px-4 py-2" style={{ paddingLeft: `${40 + lvl * 24}px` }}>
                            <div className="flex items-center gap-2">
                              <Package size={14} className="text-gray-400 flex-shrink-0" />
                              <div className="min-w-[280px]">
                                <SearchableSelect
                                  options={allItemOptions}
                                  value={selectedItemId}
                                  onChange={async (value) => {
                                    const next = String(value || '');
                                    setSelectedItemByNodeKey((prev) => ({ ...prev, [key]: next }));
                                    await fetchItemStockAvailable(next);
                                  }}
                                  placeholder={itemsLoading ? 'Loading items…' : 'Select item…'}
                                  disabled={itemsLoading || allItemOptions.length === 0}
                                />
                              </div>
                            </div>
                          </td>
                          <td className="px-4 py-2 text-sm text-right text-gray-900">{formatQuantity(node.requiredQuantity)}</td>
                          <td
                            className="px-4 py-2 text-sm text-right text-gray-900"
                            title={stockState?.error || ''}
                          >
                            {inStockLabel}
                          </td>
                          <td
                            className={`px-4 py-2 text-sm text-right font-semibold ${
                              short > 0 ? 'text-red-600' : 'text-green-600'
                            }`}
                          >
                            {short > 0 ? formatQuantity(short) : '✓'}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              ) : null}

              {childBoms.length > 0 ? (
                <div className={directItems.length > 0 ? 'border-t border-gray-100' : ''}>
                  {childBoms.map((childId, idx) => renderBom(childId, idx === 0))}
                </div>
              ) : null}
            </div>
          )}
        </div>
      );
    };

    const topChildren = childBomIdsByParent.get(rootBomId) || [];
    if (!topChildren.length && itemNodes.length) {
      // Fallback: show root with items if there are no BOM nodes.
      return renderBom(rootBomId, true);
    }

    return topChildren.map((id, idx) => renderBom(id, idx === 0));
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#FAF9F6] to-[#E8DCC4] p-6">
      <div className="max-w-6xl mx-auto">
        <div className="flex justify-between items-start gap-6 mb-8">
          <div>
            <h1 className="text-4xl font-bold text-[#36454F]">Smart Job Order (Item Swap)</h1>
            <p className="text-[#6F4E37]">{headerSubtitle}</p>
            <p className="text-xs text-[#6F4E37] mt-2">
              Variant version: /dashboard/production/job-orders/smart
            </p>
          </div>

          <div className="flex gap-3">
            <button
              onClick={fetchPreview}
              disabled={!canPreview || loadingPreview}
              className="px-4 py-2 rounded-lg border border-[#E8DCC4] text-[#6F4E37] hover:bg-[#E8DCC4] disabled:opacity-50"
            >
              {loadingPreview ? 'Loading…' : 'Load BOM'}
            </button>
            <button
              onClick={handleCreate}
              disabled={!canPreview || creating}
              className="px-4 py-2 rounded-lg bg-[#8B6F47] text-white hover:bg-[#6F4E37] disabled:opacity-50"
            >
              {creating ? 'Creating…' : 'Create Job Order'}
            </button>
          </div>
        </div>

        <div className="bg-white rounded-lg shadow p-6 border border-[#E8DCC4]">
          <div className="grid grid-cols-12 gap-4 items-end">
            <div className="col-span-8">
              <label className="block text-sm font-medium text-gray-700 mb-2">Finished Goods Item *</label>
              <SearchableSelect
                options={finishedGoodsOptions}
                value={itemId}
                onChange={(value) => {
                  setItemId(value);
                  setPreview(null);
                }}
                placeholder={itemsLoading ? 'Loading items…' : 'Select finished good item…'}
                required
                disabled={itemsLoading}
              />
              {itemsError ? <div className="mt-2 text-xs text-red-700">{itemsError}</div> : null}
            </div>
            <div className="col-span-4">
              <label className="block text-sm font-medium text-gray-700 mb-2">Quantity *</label>
              <input
                type="number"
                value={quantity}
                min={1}
                onChange={(e) => {
                  setQuantity(Number(e.target.value || 0));
                  setPreview(null);
                }}
                className="w-full border border-gray-300 rounded-lg px-4 py-2"
              />
            </div>
          </div>
        </div>

          {previewError ? (
            <div className="mt-4 p-3 rounded-lg bg-red-50 border border-red-200 text-red-800 text-sm">{previewError}</div>
          ) : null}

          {loadingPreview && (
            <div className="mt-6 p-6 rounded-lg border border-[#E8DCC4] bg-[#FAF9F6]">
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <span className="text-lg font-semibold text-[#36454F]">{loadingMessage}</span>
                  <span className="text-sm font-medium text-[#6F4E37]">{loadingProgress}%</span>
                </div>
                <div className="w-full bg-[#E8DCC4] rounded-full h-3 overflow-hidden">
                  <div
                    className="bg-gradient-to-r from-[#8B6F47] to-[#6F4E37] h-3 rounded-full transition-all duration-500 ease-linear"
                    style={{ width: `${loadingProgress}%` }}
                  />
                </div>
                <div className="flex items-center justify-center text-[#6F4E37] text-sm">
                  <svg
                    className="animate-spin h-5 w-5 mr-2"
                    xmlns="http://www.w3.org/2000/svg"
                    fill="none"
                    viewBox="0 0 24 24"
                  >
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path
                      className="opacity-75"
                      fill="currentColor"
                      d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                    ></path>
                  </svg>
                  Processing BOM explosion...
                </div>
              </div>
            </div>
          )}

          {preview ? (
            <>
              <div className="mt-6 p-4 rounded-lg border border-amber-200 bg-amber-50">
                <div className="flex flex-wrap gap-6 items-center">
                  <div>
                    <div className="text-xs text-amber-800">Finished Goods</div>
                    <div className="font-semibold text-amber-900">
                      {preview.finishedItem.code} - {preview.finishedItem.name}
                    </div>
                  </div>
                  <div>
                    <div className="text-xs text-amber-800">Quantity</div>
                    <div className="font-semibold text-amber-900">{preview.quantity}</div>
                  </div>
                  <div>
                    <div className="text-xs text-amber-800">BOM</div>
                    <div className="font-semibold text-amber-900">
                      v{preview.topBom.version} {preview.topBom.is_active ? '(Active)' : ''}
                    </div>
                  </div>
                </div>
              </div>

              {preview.subAssembliesToMake?.length ? (
                <div className="mt-6">
                  <h3 className="text-lg font-semibold text-gray-900 mb-2">Sub-assemblies to Auto-Make</h3>
                  <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
                    <table className="min-w-full divide-y divide-gray-200">
                      <thead className="bg-gray-50">
                        <tr>
                          <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Item</th>
                          <th className="px-4 py-2 text-right text-xs font-medium text-gray-500 uppercase">Required</th>
                          <th className="px-4 py-2 text-right text-xs font-medium text-gray-500 uppercase">In Stock</th>
                          <th className="px-4 py-2 text-right text-xs font-medium text-gray-500 uppercase">To Make</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-gray-200">
                        {preview.subAssembliesToMake.map((sa) => (
                          <tr key={`${sa.bomId}:${sa.itemId}`}>
                            <td className="px-4 py-2 text-sm text-gray-900">
                              {sa.itemCode} - {sa.itemName}
                            </td>
                            <td className="px-4 py-2 text-sm text-right text-gray-900">{sa.requiredQuantity}</td>
                            <td className="px-4 py-2 text-sm text-right text-gray-900">{sa.availableQuantity}</td>
                            <td className="px-4 py-2 text-sm text-right font-semibold text-amber-700">{sa.toMakeQuantity}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              ) : null}

              <div className="mt-6">
                <div className="flex items-center justify-between mb-3">
                  <h3 className="text-lg font-semibold text-gray-900">BOM Explosion</h3>
                  <div className="flex gap-2">
                    <button
                      onClick={() => {
                        const allBomIds = [
                          preview.topBom.id,
                          ...preview.nodes.filter((n) => n.componentType === 'BOM').map((n) => n.bomId),
                        ];
                        setExpandedBoms(new Set(allBomIds));
                      }}
                      className="px-3 py-1 text-xs rounded border border-amber-300 text-amber-700 hover:bg-amber-50"
                    >
                      Expand All
                    </button>
                    <button
                      onClick={() => setExpandedBoms(new Set())}
                      className="px-3 py-1 text-xs rounded border border-gray-300 text-gray-600 hover:bg-gray-50"
                    >
                      Collapse All
                    </button>
                  </div>
                </div>
                <div 
                  className="bg-white border border-gray-200 rounded-lg overflow-hidden max-h-[500px] overflow-y-scroll"
                  style={{
                    scrollbarWidth: 'thin',
                    scrollbarColor: '#d97706 #f3f4f6'
                  }}
                >
                  {renderExplosionTree()}
                </div>
              </div>

              <div className="mt-6 sticky bottom-0 bg-white border-t-2 border-amber-200 shadow-lg rounded-lg">
                {(() => {
                  const itemsWithShortage = preview.nodes.filter(n => {
                    if (n.componentType !== 'ITEM') return false;
                    const key = nodeKey(n);
                    const selectedItemId = selectedItemByNodeKey[key] || n.itemId;
                    const stockState = selectedItemId ? stockByItemId[selectedItemId] : undefined;
                    const available = stockState?.available ?? n.availableQuantity;
                    return Number(n.requiredQuantity || 0) > Number(available || 0);
                  });
                  
                  const autoMakeItemIds = new Set((preview.subAssembliesToMake || []).map(sa => sa.itemId));
                  const rawMaterialShortages = itemsWithShortage.filter(item => {
                    const selectedItemId = selectedItemByNodeKey[nodeKey(item)] || item.itemId;
                    return !autoMakeItemIds.has(selectedItemId);
                  });
                  const subAssemblyShortages = itemsWithShortage.filter(item => {
                    const selectedItemId = selectedItemByNodeKey[nodeKey(item)] || item.itemId;
                    return autoMakeItemIds.has(selectedItemId);
                  });

                  if (rawMaterialShortages.length > 0) {
                    return (
                      <div className="p-4">
                        <div 
                          className="flex items-center justify-between cursor-pointer hover:bg-red-50 p-2 rounded transition-colors"
                          onClick={() => setShowShortageDetails(!showShortageDetails)}
                        >
                          <div className="flex items-center gap-2 text-red-700 font-semibold">
                            <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                              <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                            </svg>
                            <span>❌ Blocked: {rawMaterialShortages.length} raw material{rawMaterialShortages.length > 1 ? 's' : ''} out of stock!</span>
                          </div>
                          <svg 
                            className={`w-5 h-5 text-red-700 transition-transform ${showShortageDetails ? 'rotate-180' : ''}`}
                            fill="currentColor" 
                            viewBox="0 0 20 20"
                          >
                            <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
                          </svg>
                        </div>
                        
                        {showShortageDetails && (
                          <div className="mt-4 border-t border-red-200 pt-4">
                            <div className="max-h-60 overflow-y-auto mb-4">
                              <table className="min-w-full text-sm">
                                <thead className="bg-red-50">
                                  <tr>
                                    <th className="px-3 py-2 text-left text-xs font-medium text-red-900">Item</th>
                                    <th className="px-3 py-2 text-right text-xs font-medium text-red-900">Required</th>
                                    <th className="px-3 py-2 text-right text-xs font-medium text-red-900">In Stock</th>
                                    <th className="px-3 py-2 text-right text-xs font-medium text-red-900">Shortage</th>
                                  </tr>
                                </thead>
                                <tbody className="divide-y divide-red-100">
                                  {rawMaterialShortages.map((item, idx) => {
                                    const key = nodeKey(item);
                                    const selectedItemId = selectedItemByNodeKey[key] || item.itemId;
                                    const stockState = selectedItemId ? stockByItemId[selectedItemId] : undefined;
                                    const available = stockState?.available ?? item.availableQuantity;
                                    const shortage = Math.max(0, Number(item.requiredQuantity || 0) - Number(available || 0));
                                    
                                    return (
                                      <tr key={idx} className="hover:bg-red-50">
                                        <td className="px-3 py-2 text-gray-900">
                                          <div className="font-medium">{item.itemCode}</div>
                                          <div className="text-xs text-gray-600">{item.itemName}</div>
                                        </td>
                                        <td className="px-3 py-2 text-right text-gray-900">{formatQuantity(item.requiredQuantity)}</td>
                                        <td className="px-3 py-2 text-right text-gray-900">{formatQuantity(available)}</td>
                                        <td className="px-3 py-2 text-right font-semibold text-red-700">{formatQuantity(shortage)}</td>
                                      </tr>
                                    );
                                  })}
                                </tbody>
                              </table>
                            </div>
                            <button
                              onClick={(e) => {
                                e.stopPropagation();
                                handlePurchaseShortageItems();
                              }}
                              disabled={creatingPR}
                              className="w-full px-4 py-2 bg-red-600 hover:bg-red-700 text-white font-semibold rounded-lg transition-colors disabled:bg-gray-400 disabled:cursor-not-allowed"
                            >
                              {creatingPR ? 'Creating PR...' : '🛒 Purchase All Shortage Items'}
                            </button>
                          </div>
                        )}
                      </div>
                    );
                  } else {
                    return (
                      <div className="p-4 flex items-center justify-between">
                        <div className="text-sm text-gray-700">
                          {subAssemblyShortages.length > 0 ? (
                            <span className="flex items-center gap-2 text-amber-700 font-semibold">
                              <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                                <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                              </svg>
                              ⚠️ {subAssemblyShortages.length} sub-assembl{subAssemblyShortages.length > 1 ? 'ies' : 'y'} will be auto-created
                            </span>
                          ) : (
                            <span className="flex items-center gap-2 text-green-700 font-semibold">
                              <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                                <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
                              </svg>
                              ✓ All materials available in stock
                            </span>
                          )}
                        </div>
                        <button
                          onClick={handleCreate}
                          disabled={creating || !canPreview}
                          className={`px-6 py-3 rounded-lg font-semibold text-white transition-colors ${
                            creating || !canPreview
                              ? 'bg-gray-400 cursor-not-allowed'
                              : 'bg-[#8B6F47] hover:bg-[#6F4E37] shadow-md hover:shadow-lg'
                          }`}
                        >
                          {creating ? 'Creating...' : 'Create Job Order'}
                        </button>
                      </div>
                    );
                  }
                })()}
              </div>
            </>
          ) : null}
      </div>
      {showCreateSummary ? (
        <div className="fixed inset-0 z-50 bg-black/40 flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-4xl max-h-[90vh] rounded-xl shadow-xl border border-amber-200 overflow-hidden flex flex-col">
            <div className="px-6 py-4 bg-amber-50 border-b border-amber-200 flex items-center justify-between">
              <div>
                <div className="text-lg font-semibold text-amber-900">Smart Job Order Created</div>
                <div className="text-sm text-amber-800">
                  Materials below are <span className="font-semibold">issued</span> (stock reduced) at creation.
                </div>
              </div>
              <button
                onClick={() => setShowCreateSummary(false)}
                className="px-3 py-1.5 rounded-md border border-amber-300 text-amber-800 hover:bg-amber-100"
              >
                Close
              </button>
            </div>

            {(() => {
              const jo = (createSummary as any)?.jobOrder || (createSummary as any)?.job_order;
              const joNumber = jo?.job_order_number || jo?.jobOrderNumber || '';
              const joStatus = jo?.status || '-';
              const joItemCode = jo?.item_code || jo?.itemCode || '';
              const joItemName = jo?.item_name || jo?.itemName || '';
              const joQty = Number(jo?.quantity ?? 0) || 0;

              const materials = Array.isArray(jo?.materials) ? jo.materials : [];
              const totalRequired = materials.reduce(
                (sum: number, m: any) => sum + (Number(m?.required_quantity ?? m?.requiredQuantity ?? 0) || 0),
                0,
              );
              const totalIssued = materials.reduce(
                (sum: number, m: any) => sum + (Number(m?.issued_quantity ?? m?.issuedQuantity ?? 0) || 0),
                0,
              );

              const subJobs = Array.isArray((createSummary as any)?.autoCompletedSubJobOrders)
                ? (createSummary as any).autoCompletedSubJobOrders
                : [];

              return (
                <div className="flex-1 overflow-y-auto overscroll-contain p-6">
                  <div className="grid grid-cols-2 gap-4 bg-gray-50 rounded-lg p-4">
                    <div className="text-sm">
                      <div className="text-gray-600">Job Order</div>
                      <div className="font-semibold text-gray-900">{joNumber || '—'}</div>
                    </div>
                    <div className="text-sm">
                      <div className="text-gray-600">Status</div>
                      <div className="font-semibold text-gray-900">{joStatus}</div>
                    </div>
                    <div className="text-sm col-span-2">
                      <div className="text-gray-600">Item</div>
                      <div className="font-semibold text-gray-900">
                        {joItemCode ? `${joItemCode} — ${joItemName}` : joItemName || '—'}
                      </div>
                    </div>
                    <div className="text-sm">
                      <div className="text-gray-600">Quantity</div>
                      <div className="font-semibold text-gray-900">{joQty}</div>
                    </div>
                    <div className="text-sm">
                      <div className="text-gray-600">Stock Reduced (Issued)</div>
                      <div className="font-semibold text-gray-900">{totalIssued}</div>
                    </div>
                  </div>

                  {subJobs.length ? (
                    <div className="mt-5">
                      <div className="font-medium text-gray-800 mb-2">Auto-completed Sub-Assemblies</div>
                      <div className="text-sm text-gray-700">
                        {subJobs.map((s: any, idx: number) => {
                          const n = s?.job_order_number || s?.jobOrderNumber || s?.jobOrder?.job_order_number;
                          const code = s?.item_code || s?.itemCode;
                          const name = s?.item_name || s?.itemName;
                          const q = Number(s?.quantity ?? 0) || 0;
                          return (
                            <div key={idx} className="py-1">
                              <span className="font-semibold text-gray-900">{n || 'JO'}</span>
                              {code || name ? <span className="text-gray-700"> — {code} {name ? `(${name})` : ''}</span> : null}
                              {q ? <span className="text-gray-600"> • Qty {q}</span> : null}
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  ) : null}

                  <div className="mt-5">
                    <div className="flex items-center justify-between mb-2">
                      <div className="font-medium text-gray-800">Materials Issued</div>
                      <div className="text-xs text-gray-600">Issued reduces stock immediately.</div>
                    </div>
                    <div className="overflow-x-auto border rounded-lg">
                      <table className="min-w-full text-sm">
                        <thead className="bg-gray-50 border-b">
                          <tr className="text-left text-gray-600">
                            <th className="py-2 px-3">Item</th>
                            <th className="py-2 px-3 text-right">Required</th>
                            <th className="py-2 px-3 text-right">Issued (Reduced)</th>
                            <th className="py-2 px-3">Status</th>
                          </tr>
                        </thead>
                        <tbody>
                          {materials.map((m: any) => {
                            const code = m?.item_code || m?.itemCode || '';
                            const name = m?.item_name || m?.itemName || '';
                            const reqQty = Number(m?.required_quantity ?? m?.requiredQuantity ?? 0) || 0;
                            const issuedQty = Number(m?.issued_quantity ?? m?.issuedQuantity ?? 0) || 0;
                            const st = m?.status || '-';
                            return (
                              <tr key={m?.id || `${code}-${name}`} className="border-b last:border-b-0">
                                <td className="py-2 px-3">
                                  <div className="text-gray-900">{code || '-'}</div>
                                  <div className="text-xs text-gray-600">{name}</div>
                                </td>
                                <td className="py-2 px-3 text-right text-gray-900">{reqQty}</td>
                                <td className="py-2 px-3 text-right font-semibold text-gray-900">{issuedQty}</td>
                                <td className="py-2 px-3 text-gray-700">{st}</td>
                              </tr>
                            );
                          })}
                          {materials.length === 0 ? (
                            <tr>
                              <td colSpan={4} className="py-4 px-3 text-center text-gray-600">
                                No materials returned for this job order.
                              </td>
                            </tr>
                          ) : null}
                        </tbody>
                        {materials.length ? (
                          <tfoot className="bg-gray-50 border-t">
                            <tr>
                              <td className="py-2 px-3 font-medium text-gray-700">Totals</td>
                              <td className="py-2 px-3 text-right font-medium text-gray-900">{totalRequired}</td>
                              <td className="py-2 px-3 text-right font-semibold text-gray-900">{totalIssued}</td>
                              <td className="py-2 px-3" />
                            </tr>
                          </tfoot>
                        ) : null}
                      </table>
                    </div>

                    <div className="mt-3 text-xs text-gray-600">
                      Finished goods (UIDs/stock add) happens when the job order is <span className="font-semibold">COMPLETED</span>.
                    </div>
                  </div>
                </div>
              );
            })()}
          </div>
        </div>
      ) : null}
    </div>
  );
}

'use client';

import { Suspense, useEffect, useMemo, useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { apiClient } from '../../../../../../lib/api-client';
import SearchableSelect from '../../../../../components/SearchableSelect';

type FinishedItem = {
  id: string;
  code: string;
  name: string;
  category?: string | null;
};

type RawItem = {
  id?: string | number;
  item_id?: string | number;
  code?: string;
  item_code?: string;
  name?: string;
  item_name?: string;
  category?: string | null;
};

type SmartExplosionNode = {
  level: number;
  componentType: 'ITEM' | 'BOM';
  bomId: string;
  parentBomId?: string;
  itemId: string;
  itemCode: string;
  itemName: string;
  requiredQuantity: number;
  availableQuantity: number;
  toMakeQuantity: number;
  shortageQuantity: number;
};

type SmartSubAssemblyPlan = {
  bomId: string;
  itemId: string;
  itemCode: string;
  itemName: string;
  requiredQuantity: number;
  availableQuantity: number;
  toMakeQuantity: number;
};

type ItemVariant = {
  id: string;
  code: string;
  name: string;
  variant_name?: string | null;
  is_default_variant?: boolean;
};

type ItemStockSummary = {
  total_quantity?: number;
  available_quantity?: number;
  allocated_quantity?: number;
};

type SmartPreview = {
  finishedItem: FinishedItem;
  quantity: number;
  topBom: {
    id: string;
    version: number;
    is_active?: boolean;
  };
  nodes: SmartExplosionNode[];
  subAssembliesToMake: SmartSubAssemblyPlan[];
  source: {
    salesOrderId: string | null;
    salesOrderItemId: string | null;
  };
};

type SmartCreateResponse = {
  jobOrder?: any;
  autoCompletedSubJobOrders?: any[];
  preview?: SmartPreview;
};

export default function SmartJobOrdersPage() {
  return (
    <Suspense
      fallback={
        <div className="p-6">
          <div className="text-xl">Loading...</div>
        </div>
      }
    >
      <SmartJobOrdersPageContent />
    </Suspense>
  );
}

function SmartJobOrdersPageContent() {
  const router = useRouter();
  const searchParams = useSearchParams();

  const prefillItemId = searchParams.get('itemId') || '';
  const prefillQuantity = Number(searchParams.get('quantity') || '') || 1;
  const salesOrderId = searchParams.get('salesOrderId');
  const salesOrderItemId = searchParams.get('salesOrderItemId');

  const [itemId, setItemId] = useState<string>(prefillItemId);
  const [quantity, setQuantity] = useState<number>(prefillQuantity);

  const [itemsLoading, setItemsLoading] = useState(false);
  const [itemsError, setItemsError] = useState<string>('');
  const [items, setItems] = useState<FinishedItem[]>([]);

  const [loadingPreview, setLoadingPreview] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [loadingMessage, setLoadingMessage] = useState('');
  const [preview, setPreview] = useState<SmartPreview | null>(null);
  const [previewError, setPreviewError] = useState<string>('');

  const [variantsByItemId, setVariantsByItemId] = useState<Record<string, ItemVariant[]>>({});
  const [selectedVariantByNodeKey, setSelectedVariantByNodeKey] = useState<Record<string, string>>({});
  const [stockByItemId, setStockByItemId] = useState<
    Record<string, { available: number; loading: boolean; error?: string }>
  >({});

  const [createSummary, setCreateSummary] = useState<SmartCreateResponse | null>(null);
  const [showCreateSummary, setShowCreateSummary] = useState(false);

  const [creating, setCreating] = useState(false);

  const canPreview = Boolean(itemId) && Number(quantity) > 0;

  const headerSubtitle = useMemo(() => {
    if (salesOrderId) return `From Sales Order: ${salesOrderId}`;
    return 'Create a Job Order in one click from BOM + stock';
  }, [salesOrderId]);

  const itemOptions = useMemo(
    () =>
      items.map((i) => ({
        value: i.id,
        label: i.code,
        subtitle: i.name,
      })),
    [items],
  );

  const fetchItems = async () => {
    setItemsError('');
    setItemsLoading(true);
    try {
      const response = await apiClient.get('/inventory/items');
      const list = Array.isArray(response) ? (response as RawItem[]) : [];
      const normalized: FinishedItem[] = list
        .map((raw) => ({
          id: String(raw.id ?? raw.item_id ?? ''),
          code: String(raw.code ?? raw.item_code ?? ''),
          name: String(raw.name ?? raw.item_name ?? ''),
          category: raw.category ?? null,
        }))
        .filter((i) => i.id && i.code && i.name);

      setItems(normalized);
    } catch (err: any) {
      setItems([]);
      setItemsError(err?.message || 'Failed to load items');
    } finally {
      setItemsLoading(false);
    }
  };

  const nodeKey = (node: SmartExplosionNode) => `${node.bomId}:${node.itemId}`;

  const fetchItemVariants = async (baseItemId: string): Promise<ItemVariant[]> => {
    const id = String(baseItemId || '').trim();
    if (!id) return [];
    try {
      const variants = await apiClient.get<ItemVariant[]>(`/items/${id}/variants`);
      return Array.isArray(variants) ? variants : [];
    } catch {
      return [];
    }
  };

  const fetchItemStockAvailable = async (itemIdToCheck: string) => {
    const id = String(itemIdToCheck || '').trim();
    if (!id) return;

    setStockByItemId((prev) => {
      const existing = prev[id];
      if (existing?.loading) return prev;
      return {
        ...prev,
        [id]: { available: existing?.available ?? 0, loading: true },
      };
    });

    try {
      const summary = await apiClient.get<ItemStockSummary>(`/items/${id}/stock`);
      const available = Number((summary as any)?.available_quantity ?? 0) || 0;
      setStockByItemId((prev) => ({
        ...prev,
        [id]: { available, loading: false },
      }));
    } catch (err: any) {
      setStockByItemId((prev) => ({
        ...prev,
        [id]: {
          available: prev[id]?.available ?? 0,
          loading: false,
          error: err?.message || 'Failed to load stock',
        },
      }));
    }
  };

  const fetchPreview = async () => {
    if (!canPreview) return;
    setPreviewError('');
    setLoadingPreview(true);
    setLoadingProgress(0);
    setLoadingMessage('🔍 Loading BOM...');
    
    try {
      // Simulate progress stages with gradual increments
      const progressInterval = setInterval(() => {
        setLoadingProgress((prev) => {
          if (prev < 25) {
            setLoadingMessage('🔍 Loading BOM...');
            return prev + 2;
          } else if (prev < 60) {
            setLoadingMessage('💥 Exploding BOM structure...');
            return prev + 2;
          } else if (prev < 90) {
            setLoadingMessage('📦 Extracting items...');
            return prev + 1;
          }
          return prev;
        });
      }, 200);

      const data = await apiClient.get<SmartPreview>('/job-orders/smart/preview', {
        itemId,
        quantity,
        salesOrderId: salesOrderId || undefined,
        salesOrderItemId: salesOrderItemId || undefined,
      });
      
      clearInterval(progressInterval);
      setLoadingProgress(100);
      setLoadingMessage('✅ Preview ready!');
      
      // Small delay to show completion
      setTimeout(() => {
        setPreview(data);
        setLoadingPreview(false);
      }, 300);
    } catch (err: any) {
      setPreview(null);
      setPreviewError(err?.message || 'Failed to load BOM preview');
      setLoadingPreview(false);
      setLoadingProgress(0);
      setLoadingMessage('');
    }
  };

  useEffect(() => {
    fetchItems();

    // auto-preview on first load if prefilled
    if (prefillItemId) {
      fetchPreview();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (!preview?.nodes?.length) {
      setVariantsByItemId({});
      setSelectedVariantByNodeKey({});
      setStockByItemId({});
      return;
    }

    const itemNodes = preview.nodes.filter((n) => n.componentType === 'ITEM' && n.itemId);
    const uniqueBaseItemIds = Array.from(new Set(itemNodes.map((n) => String(n.itemId))));

    let cancelled = false;

    (async () => {
      const variantPairs = await Promise.all(
        uniqueBaseItemIds.map(async (id) => {
          const variants = await fetchItemVariants(id);
          return [id, variants] as const;
        }),
      );

      if (cancelled) return;

      const nextVariantsByItemId: Record<string, ItemVariant[]> = {};
      for (const [id, variants] of variantPairs) {
        nextVariantsByItemId[id] = variants;
      }
      setVariantsByItemId(nextVariantsByItemId);

      const nextSelected: Record<string, string> = {};
      const toFetchStock = new Set<string>();

      for (const node of itemNodes) {
        const key = nodeKey(node);
        const baseId = String(node.itemId);
        const variants = nextVariantsByItemId[baseId] || [];
        const defaultVariantId =
          variants.find((v) => v.is_default_variant)?.id ||
          variants[0]?.id ||
          baseId;

        nextSelected[key] = defaultVariantId;
        toFetchStock.add(defaultVariantId);
      }

      setSelectedVariantByNodeKey(nextSelected);
      await Promise.all(Array.from(toFetchStock).map((id) => fetchItemStockAvailable(id)));
    })();

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [preview?.topBom?.id, preview?.quantity, preview?.finishedItem?.id]);

  useEffect(() => {
    if (!canPreview) return;

    // Auto-preview after selecting item / changing quantity.
    const handle = setTimeout(() => {
      fetchPreview();
    }, 350);

    return () => clearTimeout(handle);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [itemId, quantity, salesOrderId, salesOrderItemId]);

  const handleCreate = async () => {
    if (!canPreview) {
      alert('Please select a Finished Good item and quantity');
      return;
    }

    setCreating(true);
    try {
      const variantSelections: Record<string, string> = {};
      if (preview?.nodes?.length) {
        for (const node of preview.nodes) {
          if (node.componentType !== 'ITEM') continue;
          const key = nodeKey(node);
          const selected = selectedVariantByNodeKey[key];
          if (selected) variantSelections[key] = selected;
        }
      }

      const result = (await apiClient.post('/job-orders/smart/create', {
        itemId,
        quantity: Number(quantity),
        startDate: new Date().toISOString().slice(0, 10),
        salesOrderId: salesOrderId || undefined,
        salesOrderItemId: salesOrderItemId || undefined,
        variantSelections,
      })) as SmartCreateResponse;

      setCreateSummary(result);
      setShowCreateSummary(true);

      // refresh preview (stock changed due to auto-completion)
      await fetchPreview();
    } catch (err: any) {
      alert(`❌ Failed to create Smart Job Order: ${err?.message || 'Unknown error'}`);
    } finally {
      setCreating(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#FAF9F6] to-[#E8DCC4] p-6">
      <div className="max-w-6xl mx-auto">
        <div className="flex justify-between items-start gap-6 mb-8">
          <div>
            <h1 className="text-4xl font-bold text-[#36454F]">Smart Job Order</h1>
            <p className="text-[#6F4E37]">{headerSubtitle}</p>
            <p className="text-xs text-[#6F4E37] mt-2">
              Legacy form: /dashboard/production/job-orders?legacy=1
            </p>
          </div>

          <div className="flex gap-3">
            <button
              onClick={fetchPreview}
              disabled={!canPreview || loadingPreview}
              className="px-4 py-2 rounded-lg border border-[#E8DCC4] text-[#6F4E37] hover:bg-[#E8DCC4] disabled:opacity-50"
            >
              {loadingPreview ? 'Loading…' : 'Load BOM'}
            </button>
            <button
              onClick={handleCreate}
              disabled={!canPreview || creating}
              className="px-4 py-2 rounded-lg bg-[#8B6F47] text-white hover:bg-[#6F4E37] disabled:opacity-50"
            >
              {creating ? 'Creating…' : 'Create Job Order'}
            </button>
          </div>
        </div>

        <div className="bg-white rounded-lg shadow p-6">
          <div className="grid grid-cols-12 gap-4 items-end">
            <div className="col-span-8">
              <label className="block text-sm font-medium text-gray-700 mb-2">Finished Goods Item *</label>
              <SearchableSelect
                options={itemOptions}
                value={itemId}
                onChange={(value) => {
                  setItemId(value);
                  setPreview(null);
                }}
                placeholder={itemsLoading ? 'Loading items…' : 'Select finished good item…'}
                required
                disabled={itemsLoading}
              />
              {itemsError ? (
                <div className="mt-2 text-xs text-red-700">{itemsError}</div>
              ) : null}
            </div>
            <div className="col-span-4">
              <label className="block text-sm font-medium text-gray-700 mb-2">Quantity *</label>
              <input
                type="number"
                value={quantity}
                min={1}
                onChange={(e) => {
                  setQuantity(Number(e.target.value || 0));
                  setPreview(null);
                }}
                className="w-full border border-gray-300 rounded-lg px-4 py-2"
              />
            </div>
          </div>

          {previewError ? (
            <div className="mt-4 p-3 rounded-lg bg-red-50 border border-red-200 text-red-800 text-sm">
              {previewError}
            </div>
          ) : null}

          {loadingPreview && (
            <div className="mt-6 p-6 rounded-lg border border-amber-200 bg-amber-50">
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <span className="text-lg font-semibold text-amber-900">{loadingMessage}</span>
                  <span className="text-sm font-medium text-amber-800">{loadingProgress}%</span>
                </div>
                <div className="w-full bg-amber-100 rounded-full h-3 overflow-hidden">
                  <div
                    className="bg-gradient-to-r from-amber-700 to-amber-800 h-3 rounded-full transition-all duration-500 ease-linear"
                    style={{ width: `${loadingProgress}%` }}
                  />
                </div>
                <div className="flex items-center justify-center text-amber-700 text-sm">
                  <svg className="animate-spin h-5 w-5 mr-2" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  Processing BOM explosion...
                </div>
              </div>
            </div>
          )}

          {preview ? (
            <>
              <div className="mt-6 p-4 rounded-lg border border-amber-200 bg-amber-50">
                <div className="flex flex-wrap gap-6 items-center">
                  <div>
                    <div className="text-xs text-amber-800">Finished Goods</div>
                    <div className="font-semibold text-amber-900">
                      {preview.finishedItem.code} - {preview.finishedItem.name}
                    </div>
                  </div>
                  <div>
                    <div className="text-xs text-amber-800">Quantity</div>
                    <div className="font-semibold text-amber-900">{preview.quantity}</div>
                  </div>
                  <div>
                    <div className="text-xs text-amber-800">BOM</div>
                    <div className="font-semibold text-amber-900">
                      v{preview.topBom.version} {preview.topBom.is_active ? '(Active)' : ''}
                    </div>
                  </div>
                </div>
              </div>

              {preview.subAssembliesToMake?.length ? (
                <div className="mt-6">
                  <h3 className="text-lg font-semibold text-gray-900 mb-2">Sub-assemblies to Auto-Make</h3>
                  <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
                    <table className="min-w-full divide-y divide-gray-200">
                      <thead className="bg-gray-50">
                        <tr>
                          <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Item</th>
                          <th className="px-4 py-2 text-right text-xs font-medium text-gray-500 uppercase">Required</th>
                          <th className="px-4 py-2 text-right text-xs font-medium text-gray-500 uppercase">In Stock</th>
                          <th className="px-4 py-2 text-right text-xs font-medium text-gray-500 uppercase">To Make</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-gray-200">
                        {preview.subAssembliesToMake.map((sa) => (
                          <tr key={`${sa.bomId}:${sa.itemId}`}>
                            <td className="px-4 py-2 text-sm text-gray-900">
                              {sa.itemCode} - {sa.itemName}
                            </td>
                            <td className="px-4 py-2 text-sm text-gray-900 text-right">{sa.requiredQuantity}</td>
                            <td className="px-4 py-2 text-sm text-gray-900 text-right">{sa.availableQuantity}</td>
                            <td className="px-4 py-2 text-sm font-semibold text-right text-amber-700">{sa.toMakeQuantity}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              ) : (
                <div className="mt-6 p-3 rounded-lg bg-green-50 border border-green-200 text-green-800 text-sm">
                  ✅ All required sub-assemblies are available in stock.
                </div>
              )}

              <div className="mt-6">
                <h3 className="text-lg font-semibold text-gray-900 mb-2">BOM Explosion (Only what needs to be made)</h3>
                <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
                  <table className="min-w-full divide-y divide-gray-200">
                    <thead className="bg-gray-50">
                      <tr>
                        <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Component</th>
                        <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Variant</th>
                        <th className="px-4 py-2 text-center text-xs font-medium text-gray-500 uppercase">Type</th>
                        <th className="px-4 py-2 text-right text-xs font-medium text-gray-500 uppercase">Required</th>
                        <th className="px-4 py-2 text-right text-xs font-medium text-gray-500 uppercase">In Stock</th>
                        <th className="px-4 py-2 text-right text-xs font-medium text-gray-500 uppercase">To Make</th>
                        <th className="px-4 py-2 text-right text-xs font-medium text-gray-500 uppercase">Short</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-200">
                      {preview.nodes.map((node, idx) => {
                        const isBOM = node.componentType === 'BOM';
                        const highlight = isBOM ? 'text-gray-900 font-medium' : 'text-gray-800';
                        const key = nodeKey(node);
                        const selectedVariantId = !isBOM ? (selectedVariantByNodeKey[key] || node.itemId) : '';
                        const stockState = selectedVariantId ? stockByItemId[selectedVariantId] : undefined;
                        const resolvedAvailable = !isBOM
                          ? (stockState ? stockState.available : (node.availableQuantity || 0))
                          : (node.availableQuantity || 0);

                        const short = Math.max(0, (node.requiredQuantity || 0) - (resolvedAvailable || 0));
                        const toMake = node.toMakeQuantity || 0;

                        const baseVariants = !isBOM ? (variantsByItemId[String(node.itemId)] || []) : [];
                        const variantOptions = !isBOM
                          ? [
                              {
                                value: String(node.itemId),
                                label: `${node.itemCode} - ${node.itemName}`,
                              },
                              ...baseVariants.map((v) => ({
                                value: String(v.id),
                                label: `${v.code} - ${v.variant_name || v.name}`,
                              })),
                            ]
                          : [];

                        return (
                          <tr key={`${node.bomId}:${node.itemId}:${idx}`}>
                            <td className={`px-4 py-2 text-sm ${highlight}`}>
                              <div style={{ paddingLeft: `${node.level * 16}px` }}>
                                {node.itemCode} - {node.itemName}
                              </div>
                            </td>

                            <td className="px-4 py-2 text-sm text-gray-900">
                              {isBOM ? (
                                <span className="text-gray-400">-</span>
                              ) : (
                                <select
                                  className="w-full border border-gray-300 rounded-lg px-2 py-1 text-sm"
                                  value={selectedVariantId}
                                  onChange={(e) => {
                                    const nextId = e.target.value;
                                    setSelectedVariantByNodeKey((prev) => ({ ...prev, [key]: nextId }));
                                    fetchItemStockAvailable(nextId);
                                  }}
                                >
                                  {variantOptions.map((opt) => (
                                    <option key={opt.value} value={opt.value}>
                                      {opt.label}
                                    </option>
                                  ))}
                                </select>
                              )}
                            </td>

                            <td className="px-4 py-2 text-xs text-center">
                              <span
                                className={`px-2 py-1 rounded-full ${
                                  isBOM ? 'bg-purple-100 text-purple-800' : 'bg-blue-100 text-blue-800'
                                }`}
                              >
                                {node.componentType}
                              </span>
                            </td>
                            <td className="px-4 py-2 text-sm text-right text-gray-900">{node.requiredQuantity}</td>
                            <td className="px-4 py-2 text-sm text-right text-gray-900">
                              {!isBOM && stockState?.loading ? '…' : resolvedAvailable}
                            </td>
                            <td className="px-4 py-2 text-sm text-right text-amber-700 font-semibold">{toMake || '-'}</td>
                            <td className={`px-4 py-2 text-sm text-right ${short > 0 ? 'text-red-700 font-semibold' : 'text-gray-500'}`}>
                              {short > 0 ? short : '-'}
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>

                <div className="mt-3 text-xs text-gray-600">
                  Note: Sub-assembly explosion is calculated only for the missing quantity (Required - In Stock).
                </div>
              </div>
            </>
          ) : (
            <div className="mt-6 text-sm text-gray-600">
              Select an item and quantity to see the BOM preview.
            </div>
          )}
        </div>
      </div>

      {showCreateSummary ? (
        <div className="fixed inset-0 z-50 bg-black/40 flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-3xl rounded-xl shadow-xl border border-amber-200 overflow-hidden">
            <div className="px-6 py-4 bg-amber-50 border-b border-amber-200 flex items-center justify-between">
              <div>
                <div className="text-lg font-semibold text-amber-900">Smart Job Order Created</div>
                <div className="text-sm text-amber-800">
                  Materials below are <span className="font-semibold">issued</span> (stock reduced) at creation.
                </div>
              </div>
              <button
                onClick={() => setShowCreateSummary(false)}
                className="px-3 py-1.5 rounded-md border border-amber-300 text-amber-800 hover:bg-amber-100"
              >
                Close
              </button>
            </div>

            {(() => {
              const jo = (createSummary as any)?.jobOrder || (createSummary as any)?.job_order;
              const joNumber = jo?.job_order_number || jo?.jobOrderNumber || '';
              const joStatus = jo?.status || '-';
              const joItemCode = jo?.item_code || jo?.itemCode || '';
              const joItemName = jo?.item_name || jo?.itemName || '';
              const joQty = Number(jo?.quantity ?? 0) || 0;

              const materials = Array.isArray(jo?.materials) ? jo.materials : [];
              const totalIssued = materials.reduce(
                (sum: number, m: any) => sum + (Number(m?.issued_quantity ?? m?.issuedQuantity ?? 0) || 0),
                0,
              );

              const subJobs = Array.isArray((createSummary as any)?.autoCompletedSubJobOrders)
                ? (createSummary as any).autoCompletedSubJobOrders
                : [];

              return (
                <div className="p-6">
                  <div className="grid grid-cols-2 gap-4 bg-gray-50 rounded-lg p-4">
                    <div className="text-sm">
                      <div className="text-gray-600">Job Order</div>
                      <div className="font-semibold text-gray-900">{joNumber || '—'}</div>
                    </div>
                    <div className="text-sm">
                      <div className="text-gray-600">Status</div>
                      <div className="font-semibold text-gray-900">{joStatus}</div>
                    </div>
                    <div className="text-sm col-span-2">
                      <div className="text-gray-600">Item</div>
                      <div className="font-semibold text-gray-900">
                        {joItemCode ? `${joItemCode} — ${joItemName}` : joItemName || '—'}
                      </div>
                    </div>
                    <div className="text-sm">
                      <div className="text-gray-600">Quantity</div>
                      <div className="font-semibold text-gray-900">{joQty}</div>
                    </div>
                    <div className="text-sm">
                      <div className="text-gray-600">Stock Reduced (Issued)</div>
                      <div className="font-semibold text-gray-900">{totalIssued}</div>
                    </div>
                  </div>

                  {subJobs.length ? (
                    <div className="mt-5">
                      <div className="font-medium text-gray-800 mb-2">Auto-completed Sub-Assemblies</div>
                      <div className="text-sm text-gray-700">
                        {subJobs.map((s: any, idx: number) => {
                          const n = s?.job_order_number || s?.jobOrderNumber || s?.jobOrder?.job_order_number;
                          const code = s?.item_code || s?.itemCode;
                          const name = s?.item_name || s?.itemName;
                          const q = Number(s?.quantity ?? 0) || 0;
                          return (
                            <div key={idx} className="py-1">
                              <span className="font-semibold text-gray-900">{n || 'JO'}</span>
                              {code || name ? <span className="text-gray-700"> — {code} {name ? `(${name})` : ''}</span> : null}
                              {q ? <span className="text-gray-600"> • Qty {q}</span> : null}
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  ) : null}

                  <div className="mt-5">
                    <div className="flex items-center justify-between mb-2">
                      <div className="font-medium text-gray-800">Materials Issued</div>
                      <div className="text-xs text-gray-600">Issued reduces stock immediately.</div>
                    </div>
                    <div className="overflow-x-auto border rounded-lg">
                      <table className="min-w-full text-sm">
                        <thead className="bg-gray-50 border-b">
                          <tr className="text-left text-gray-600">
                            <th className="py-2 px-3">Item</th>
                            <th className="py-2 px-3 text-right">Required</th>
                            <th className="py-2 px-3 text-right">Issued (Reduced)</th>
                            <th className="py-2 px-3">Status</th>
                          </tr>
                        </thead>
                        <tbody>
                          {materials.map((m: any) => {
                            const code = m?.item_code || m?.itemCode || '';
                            const name = m?.item_name || m?.itemName || '';
                            const reqQty = Number(m?.required_quantity ?? m?.requiredQuantity ?? 0) || 0;
                            const issuedQty = Number(m?.issued_quantity ?? m?.issuedQuantity ?? 0) || 0;
                            const st = m?.status || '-';
                            return (
                              <tr key={m?.id || `${code}-${name}`} className="border-b last:border-b-0">
                                <td className="py-2 px-3">
                                  <div className="text-gray-900">{code || '-'}</div>
                                  <div className="text-xs text-gray-600">{name}</div>
                                </td>
                                <td className="py-2 px-3 text-right text-gray-900">{reqQty}</td>
                                <td className="py-2 px-3 text-right font-semibold text-gray-900">{issuedQty}</td>
                                <td className="py-2 px-3 text-gray-700">{st}</td>
                              </tr>
                            );
                          })}
                          {materials.length === 0 ? (
                            <tr>
                              <td colSpan={4} className="py-4 px-3 text-center text-gray-600">
                                No materials returned for this job order.
                              </td>
                            </tr>
                          ) : null}
                        </tbody>
                      </table>
                    </div>

                    <div className="mt-3 text-xs text-gray-600">
                      Finished goods (UIDs/stock add) happens when the job order is <span className="font-semibold">COMPLETED</span>.
                    </div>
                  </div>
                </div>
              );
            })()}
          </div>
        </div>
      ) : null}
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import ItemSearch from '@/components/ItemSearch';

interface BOMComponent {
  id: string;
  componentType: string;
  quantity: number;
  uom: string;
  item: { id: string; code: string; name: string; };
}

interface BOM {
  id: string;
  version: string;
  description?: string;
  status?: string;
  items: BOMComponent[];
}

interface AvailableUID {
  uid: string;
  item_id: string;
  item_code: string;
  item_name: string;
  batch_number: string;
  received_date: string;
  expiry_date: string;
  location: string;
  status: string;
}

interface ProductionOrder {
  id: string;
  order_number: string;
  item: { code: string; name: string; uom: string };
  quantity: number;
  produced_quantity: number;
  status: string;
  start_date: string;
  end_date: string;
  priority: string;
  production_assemblies: Array<{
    id: string;
    finished_product_uid: string;
    qc_status: string;
  }>;
}

interface StationCompletion {
  id: string;
  routing_id: string;
  quantity_completed: number;
  quantity_rejected: number;
  start_time: string;
  end_time: string | null;
  status: string;
  routing: {
    sequence: number;
    operation_description: string;
    standard_time_minutes: number;
  };
  work_station: {
    name: string;
    code: string;
  };
}

export default function ProductionPage() {
  const router = useRouter();
  const [orders, setOrders] = useState<ProductionOrder[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [showAssemblyModal, setShowAssemblyModal] = useState(false);
  const [selectedOrder, setSelectedOrder] = useState<string | null>(null);
  const [filterStatus, setFilterStatus] = useState('ALL');
  const [expandedOrders, setExpandedOrders] = useState<Set<string>>(new Set());
  const [orderCompletions, setOrderCompletions] = useState<Record<string, StationCompletion[]>>({});
  
  // New state for BOM and UID selection
  const [availableBOMs, setAvailableBOMs] = useState<BOM[]>([]);
  const [selectedBOM, setSelectedBOM] = useState<BOM | null>(null);
  const [availableUIDs, setAvailableUIDs] = useState<Record<string, AvailableUID[]>>({});
  const [selectedUIDs, setSelectedUIDs] = useState<Record<string, string>>({});

  const [formData, setFormData] = useState({
    itemId: '',
    itemCode: '',
    itemName: '',
    bomId: '',
    quantity: 1,
    plantCode: 'KOL',
    startDate: new Date().toISOString().split('T')[0],
    endDate: '',
    priority: 'NORMAL',
    notes: '',
  });

  const [assemblyData, setAssemblyData] = useState({
    productionOrderId: '',
    componentUids: [''],
  });

  const normalizeBomFromApi = (bom: any): BOM => {
    const components = Array.isArray(bom?.bom_items) ? bom.bom_items : [];
    const normalizedItems: BOMComponent[] = components
      .map((component: any) => {
        const resolvedItem = component?.item || component?.child_bom?.item;
        if (!resolvedItem) {
          return null;
        }
        return {
          id: component.id,
          componentType: component.component_type || 'ITEM',
          quantity: Number(component.quantity) || 0,
          uom: resolvedItem.uom || '',
          item: {
            id: resolvedItem.id,
            code: resolvedItem.code || 'UNKNOWN',
            name: resolvedItem.name || 'Unnamed Component',
          },
        };
      })
      .filter(Boolean) as BOMComponent[];

    return {
      id: bom.id,
      version: String(bom.version ?? ''),
      description: bom.notes || bom.description || '',
      status: bom.is_active ? 'ACTIVE' : 'INACTIVE',
      items: normalizedItems,
    };
  };

  // Fetch BOMs when item is selected
  const fetchBOMsForItem = async (itemId: string) => {
    try {
      const token = localStorage.getItem('accessToken');
      const response = await fetch(`/api/v1/bom?productId=${itemId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      
      if (response.ok) {
        const data = await response.json();
        const normalized = Array.isArray(data)
          ? data.map((bom: any) => normalizeBomFromApi(bom))
          : [];
        setAvailableBOMs(normalized);
      }
    } catch (error) {
      console.error('Error fetching BOMs:', error);
      setAvailableBOMs([]);
    }
  };

  // Fetch available UIDs for BOM components (FIFO sorted)
  const fetchAvailableUIDsForBOM = async (bomId: string) => {
    try {
      const token = localStorage.getItem('accessToken');
      const response = await fetch(`/api/v1/production/available-uids/${bomId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      
      if (response.ok) {
        const data = await response.json();
        // Data format: { itemId: UID[] } sorted by received_date (FIFO)
        setAvailableUIDs(data);
      }
    } catch (error) {
      console.error('Error fetching available UIDs:', error);
    }
  };

  const handleItemSelect = (item: any) => {
    setFormData({ 
      ...formData, 
      itemId: item.id,
      itemCode: item.code,
      itemName: item.name
    });
    fetchBOMsForItem(item.id);
  };

  const handleBOMSelect = (bomId: string) => {
    const bom = availableBOMs.find(b => b.id === bomId);
    setSelectedBOM(bom || null);
    setFormData({ ...formData, bomId });
    if (bomId) {
      fetchAvailableUIDsForBOM(bomId);
    }
  };

  useEffect(() => {
    fetchOrders();
  }, [filterStatus]);

  const fetchOrders = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('accessToken');

      if (!token) {
        router.push('/login');
        return;
      }
      const params = new URLSearchParams();
      if (filterStatus !== 'ALL') params.append('status', filterStatus);

      const response = await fetch(`/api/v1/production?${params}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (response.status === 401) {
        localStorage.removeItem('accessToken');
        router.push('/login');
        return;
      }

      const data = await response.json();
      const ordersData = Array.isArray(data)
        ? data
        : Array.isArray(data?.data)
          ? data.data
          : [];
      setOrders(ordersData);
    } catch (error) {
      console.error('Error fetching production orders:', error);
      setOrders([]);
    } finally {
      setLoading(false);
    }
  };

  const fetchOrderCompletions = async (orderId: string) => {
    try {
      const token = localStorage.getItem('accessToken');
      const response = await fetch(`/api/v1/production/completions/order/${orderId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (response.ok) {
        const data = await response.json();
        setOrderCompletions(prev => ({ ...prev, [orderId]: data }));
      }
    } catch (error) {
      console.error('Error fetching order completions:', error);
    }
  };

  const toggleOrderExpansion = async (orderId: string) => {
    const newExpanded = new Set(expandedOrders);
    if (newExpanded.has(orderId)) {
      newExpanded.delete(orderId);
    } else {
      newExpanded.add(orderId);
      // Fetch completions if not already loaded
      if (!orderCompletions[orderId]) {
        await fetchOrderCompletions(orderId);
      }
    }
    setExpandedOrders(newExpanded);
  };

  const handleCreate = async () => {
    try {
      const token = localStorage.getItem('accessToken');
      const response = await fetch('/api/v1/production', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(formData),
      });

      if (response.ok) {
        setShowModal(false);
        fetchOrders();
        setFormData({
          itemId: '',
          itemCode: '',
          itemName: '',
          bomId: '',
          quantity: 1,
          plantCode: 'KOL',
          startDate: new Date().toISOString().split('T')[0],
          endDate: '',
          priority: 'NORMAL',
          notes: '',
        });
      } else {
        const errorBody = await response
          .json()
          .catch(() => ({ message: 'Unexpected server error' }));
        const message = errorBody?.message || errorBody?.error || 'Failed to create production order';
        console.error('Error creating production order:', errorBody);
        alert(`❌ Unable to create production order.\n${message}`);
      }
    } catch (error) {
      console.error('Error creating production order:', error);
      alert('Unable to create production order. Please try again.');
    }
  };

  const handleStartProduction = async (orderId: string) => {
    try {
      const token = localStorage.getItem('accessToken');
      await fetch(`/api/v1/production/${orderId}/start`, {
        method: 'PUT',
        headers: { Authorization: `Bearer ${token}` },
      });
      fetchOrders();
    } catch (error) {
      console.error('Error starting production:', error);
    }
  };

  const handleCompleteAssembly = async () => {
    try {
      // Auto-select FIFO UIDs for each component
      const selectedComponentUids: string[] = [];
      
      if (!selectedBOM || !selectedBOM.items) {
        alert('No BOM selected');
        return;
      }

      // For each BOM component, select required quantity of UIDs (FIFO)
      for (const component of selectedBOM.items) {
        const requiredQty = component.quantity * formData.quantity;
        const availableForItem = availableUIDs[component.item.id] || [];
        
        if (availableForItem.length < requiredQty) {
          alert(`Insufficient UIDs for ${component.item.name}. Need ${requiredQty}, have ${availableForItem.length}`);
          return;
        }

        // Take first N UIDs (already FIFO sorted from API)
        const selectedForItem = availableForItem.slice(0, Math.ceil(requiredQty)).map(u => u.uid);
        selectedComponentUids.push(...selectedForItem);
      }

      if (selectedComponentUids.length === 0) {
        alert('No component UIDs selected');
        return;
      }

      const token = localStorage.getItem('accessToken');
      const response = await fetch('/api/v1/production/assembly/complete', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          productionOrderId: assemblyData.productionOrderId,
          componentUids: selectedComponentUids,
        }),
      });

      if (response.ok) {
        const result = await response.json();
        alert(`✅ Assembly completed successfully!\n\nFinished Product UID: ${result.finishedUid}\n\nComponents consumed: ${selectedComponentUids.length}\nInventory updated automatically.`);
        setShowAssemblyModal(false);
        fetchOrders();
        setAssemblyData({ productionOrderId: '', componentUids: [''] });
        setSelectedBOM(null);
        setAvailableUIDs({});
      } else {
        const error = await response.json();
        alert(`Error: ${error.message || 'Failed to complete assembly'}`);
      }
    } catch (error) {
      console.error('Error completing assembly:', error);
      alert('Error completing assembly. Please try again.');
    }
  };

  const addComponentUid = () => {
    setAssemblyData({
      ...assemblyData,
      componentUids: [...assemblyData.componentUids, ''],
    });
  };

  const updateComponentUid = (index: number, value: string) => {
    const newUids = [...assemblyData.componentUids];
    newUids[index] = value;
    setAssemblyData({ ...assemblyData, componentUids: newUids });
  };

  const removeComponentUid = (index: number) => {
    const newUids = assemblyData.componentUids.filter((_, i) => i !== index);
    setAssemblyData({ ...assemblyData, componentUids: newUids });
  };

  const getStatusColor = (status: string) => {
    const colors = {
      DRAFT: 'bg-gray-100 text-gray-800',
      RELEASED: 'bg-orange-100 text-orange-800',
      IN_PROGRESS: 'bg-yellow-100 text-yellow-800',
      QC: 'bg-purple-100 text-purple-800',
      COMPLETED: 'bg-green-100 text-green-800',
      CANCELLED: 'bg-red-100 text-red-800',
    };
    return colors[status as keyof typeof colors] || 'bg-gray-100 text-gray-800';
  };

  const getPriorityColor = (priority: string) => {
    const colors = {
      HIGH: 'text-red-600',
      NORMAL: 'text-gray-600',
      LOW: 'text-orange-600',
    };
    return colors[priority as keyof typeof colors] || 'text-gray-600';
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-orange-50 via-amber-50 to-yellow-50 p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <button
            onClick={() => router.push('/dashboard')}
            className="text-orange-800 hover:text-orange-900 mb-4 flex items-center gap-2"
          >
            ← Back to Dashboard
          </button>
          <div className="flex justify-between items-center">
            <div>
              <h1 className="text-4xl font-bold text-orange-900 mb-2">Production Management</h1>
              <p className="text-orange-700">Manufacturing orders with UID assembly tracking</p>
            </div>
            <button
              onClick={() => setShowModal(true)}
              className="bg-orange-600 hover:bg-orange-700 text-white px-6 py-3 rounded-lg font-medium shadow-lg"
            >
              + Create Production Order
            </button>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-lg shadow-md p-6 mb-6">
          <div className="flex gap-4 items-center">
            <label className="font-medium text-gray-700">Status:</label>
            <select
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value)}
              className="border border-gray-300 rounded-lg px-4 py-2"
            >
              <option value="ALL">All Status</option>
              <option value="DRAFT">Draft</option>
              <option value="RELEASED">Released</option>
              <option value="IN_PROGRESS">In Progress</option>
              <option value="QC">QC</option>
              <option value="COMPLETED">Completed</option>
              <option value="CANCELLED">Cancelled</option>
            </select>
          </div>
        </div>

        {/* Production Orders List */}
        <div className="bg-white rounded-lg shadow-md overflow-hidden">
          {loading ? (
            <div className="p-8 text-center text-gray-500">Loading production orders...</div>
          ) : orders.length === 0 ? (
            <div className="p-12 text-center">
              <div className="text-6xl mb-4">🏭</div>
              <h3 className="text-xl font-semibold text-gray-700 mb-2">No Production Orders</h3>
              <p className="text-gray-500">Create your first production order to start manufacturing</p>
            </div>
          ) : (
            <table className="w-full">
              <thead className="bg-orange-50">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-medium text-orange-900 uppercase">Order #</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-orange-900 uppercase">Item</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-orange-900 uppercase">Quantity</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-orange-900 uppercase">Progress</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-orange-900 uppercase">UIDs</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-orange-900 uppercase">Priority</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-orange-900 uppercase">Status</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-orange-900 uppercase">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200">
                {orders.map((order) => (
                  <React.Fragment key={order.id}>
                    <tr className="hover:bg-gray-50">
                      <td className="px-6 py-4 whitespace-nowrap font-medium text-gray-900">
                        <div className="flex items-center">
                          <button
                            onClick={() => toggleOrderExpansion(order.id)}
                            className="mr-2 text-gray-500 hover:text-gray-700"
                          >
                            {expandedOrders.has(order.id) ? '▼' : '▶'}
                          </button>
                          {order.order_number}
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <div className="text-sm font-medium text-gray-900">{order.item.name}</div>
                        <div className="text-sm text-gray-500">{order.item.code}</div>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                        {order.quantity} {order.item.uom}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <div className="text-sm font-medium text-gray-900">
                          {order.produced_quantity} / {order.quantity}
                        </div>
                        <div className="w-full bg-gray-200 rounded-full h-2 mt-1">
                          <div
                            className="bg-orange-600 h-2 rounded-full"
                            style={{
                              width: `${(order.produced_quantity / order.quantity) * 100}%`,
                            }}
                          />
                        </div>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm">
                        {order.production_assemblies.length > 0 ? (
                          <div className="font-mono text-green-600">
                            ✓ {order.production_assemblies.length} assemblies
                          </div>
                        ) : (
                          <div className="text-gray-400">No assemblies</div>
                        )}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className={`font-semibold ${getPriorityColor(order.priority)}`}>
                          {order.priority}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className={`px-2 py-1 text-xs font-semibold rounded-full ${getStatusColor(order.status)}`}>
                          {order.status}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm space-x-2">
                        {order.status === 'DRAFT' && (
                          <button
                            onClick={() => handleStartProduction(order.id)}
                            className="text-orange-600 hover:text-orange-900 font-medium"
                          >
                            Start
                          </button>
                        )}
                        {(order.status === 'RELEASED' || order.status === 'IN_PROGRESS') && (
                          <button
                            onClick={async () => {
                              setSelectedOrder(order.id);
                              setAssemblyData({ ...assemblyData, productionOrderId: order.id });
                              
                              // Fetch the production order's BOM details
                              const token = localStorage.getItem('accessToken');
                              const response = await fetch(`/api/v1/production/${order.id}`, {
                                headers: { Authorization: `Bearer ${token}` },
                              });
                              if (response.ok) {
                                const orderDetails = await response.json();
                                if (orderDetails.bomId) {
                                  // Fetch BOM details
                                  const bomResponse = await fetch(`/api/v1/bom/${orderDetails.bomId}`, {
                                    headers: { Authorization: `Bearer ${token}` },
                                  });
                                  if (bomResponse.ok) {
                                    const bomData = await bomResponse.json();
                                    setSelectedBOM(bomData);
                                    setFormData({ ...formData, bomId: orderDetails.bomId, quantity: orderDetails.quantity });
                                    // Fetch available UIDs
                                    await fetchAvailableUIDsForBOM(orderDetails.bomId);
                                  }
                                }
                              }
                              
                              setShowAssemblyModal(true);
                            }}
                            className="text-green-600 hover:text-green-900 font-medium"
                          >
                            Complete Assembly
                          </button>
                        )}
                        <button 
                          onClick={() => toggleOrderExpansion(order.id)}
                          className="text-orange-600 hover:text-orange-900 font-medium"
                        >
                          {expandedOrders.has(order.id) ? 'Hide Details' : 'View Details'}
                        </button>
                      </td>
                    </tr>
                    
                    {/* Expanded Routing Progress */}
                    {expandedOrders.has(order.id) && (
                      <tr className="bg-blue-50">
                        <td colSpan={8} className="px-6 py-4">
                          <div className="pl-8">
                            <h4 className="font-semibold text-gray-900 mb-3">Operation Progress</h4>
                            {orderCompletions[order.id] && orderCompletions[order.id].length > 0 ? (
                              <div className="space-y-2">
                                {orderCompletions[order.id]
                                  .sort((a, b) => a.routing.sequence - b.routing.sequence)
                                  .map((completion) => (
                                    <div key={completion.id} className="bg-white rounded-lg p-3 shadow-sm">
                                      <div className="flex items-center justify-between">
                                        <div className="flex-1">
                                          <div className="flex items-center space-x-3">
                                            <span className="bg-blue-100 text-blue-800 text-xs font-medium px-2 py-1 rounded">
                                              Op {completion.routing.sequence}
                                            </span>
                                            <span className="font-medium text-gray-900">
                                              {completion.routing.operation_description}
                                            </span>
                                            <span className="text-sm text-gray-600">
                                              @ {completion.work_station.name}
                                            </span>
                                          </div>
                                          <div className="mt-2 flex items-center space-x-4 text-sm">
                                            <span className="text-gray-600">
                                              Completed: <span className="font-medium text-green-600">{completion.quantity_completed}</span>
                                            </span>
                                            {completion.quantity_rejected > 0 && (
                                              <span className="text-gray-600">
                                                Rejected: <span className="font-medium text-red-600">{completion.quantity_rejected}</span>
                                              </span>
                                            )}
                                            <span className="text-gray-600">
                                              Duration: <span className="font-medium">{completion.routing.standard_time_minutes} min std</span>
                                            </span>
                                          </div>
                                        </div>
                                        <div className="ml-4">
                                          <span className={`px-3 py-1 rounded-full text-xs font-medium ${
                                            completion.status === 'COMPLETED' 
                                              ? 'bg-green-100 text-green-800'
                                              : completion.status === 'IN_PROGRESS'
                                              ? 'bg-blue-100 text-blue-800'
                                              : 'bg-yellow-100 text-yellow-800'
                                          }`}>
                                            {completion.status}
                                          </span>
                                        </div>
                                      </div>
                                      {completion.start_time && (
                                        <div className="mt-2 text-xs text-gray-500">
                                          Started: {new Date(completion.start_time).toLocaleString()}
                                          {completion.end_time && ` • Ended: ${new Date(completion.end_time).toLocaleString()}`}
                                        </div>
                                      )}
                                    </div>
                                  ))}
                              </div>
                            ) : (
                              <div className="text-center py-4 text-gray-500">
                                No operations completed yet
                              </div>
                            )}
                          </div>
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>

      {/* Create Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg max-w-2xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b border-gray-200">
              <h2 className="text-2xl font-bold text-gray-900">Create Production Order</h2>
            </div>

            <div className="p-6 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="col-span-2">
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Item to Manufacture *
                  </label>
                  <ItemSearch
                    value={formData.itemCode}
                    onSelect={handleItemSelect}
                    placeholder="Search for finished goods to manufacture..."
                  />
                  {formData.itemName && (
                    <div className="mt-2 text-sm text-green-600">
                      ✓ Selected: {formData.itemCode} - {formData.itemName}
                    </div>
                  )}
                </div>
                
                <div className="col-span-2">
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Bill of Materials (BOM) *
                  </label>
                  <select
                    value={formData.bomId}
                    onChange={(e) => handleBOMSelect(e.target.value)}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2 focus:ring-2 focus:ring-orange-500"
                    disabled={!formData.itemId}
                  >
                    <option value="">
                      {!formData.itemId ? 'Select an item first...' : 'Select BOM...'}
                    </option>
                    {availableBOMs.map(bom => (
                      <option key={bom.id} value={bom.id}>
                        v{bom.version} - {bom.description} ({bom.items?.length || 0} components)
                      </option>
                    ))}
                  </select>
                  {selectedBOM && (
                    <div className="mt-2 p-3 bg-orange-50 rounded border border-orange-200">
                      <div className="text-xs font-semibold text-orange-900 mb-2">BOM Components:</div>
                      {selectedBOM.items && selectedBOM.items.length > 0 ? (
                        selectedBOM.items.map((item, idx) => (
                          <div key={idx} className="text-xs text-orange-800">
                            • {item.item.code} - {item.item.name} × {item.quantity} {item.uom}
                          </div>
                        ))
                      ) : (
                        <div className="text-xs text-orange-600">No components defined</div>
                      )}
                    </div>
                  )}
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Quantity *</label>
                  <input
                    type="number"
                    value={formData.quantity}
                    onChange={(e) => setFormData({ ...formData, quantity: parseFloat(e.target.value) })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                    min="1"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Plant Code</label>
                  <input
                    type="text"
                    value={formData.plantCode}
                    onChange={(e) => setFormData({ ...formData, plantCode: e.target.value })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Start Date</label>
                  <input
                    type="date"
                    value={formData.startDate}
                    onChange={(e) => setFormData({ ...formData, startDate: e.target.value })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">End Date</label>
                  <input
                    type="date"
                    value={formData.endDate}
                    onChange={(e) => setFormData({ ...formData, endDate: e.target.value })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Priority</label>
                  <select
                    value={formData.priority}
                    onChange={(e) => setFormData({ ...formData, priority: e.target.value })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  >
                    <option value="LOW">Low</option>
                    <option value="NORMAL">Normal</option>
                    <option value="HIGH">High</option>
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Notes</label>
                <textarea
                  value={formData.notes}
                  onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                  className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  rows={3}
                />
              </div>
            </div>

            <div className="p-6 border-t border-gray-200 flex justify-end gap-3">
              <button
                onClick={() => setShowModal(false)}
                className="px-6 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
              >
                Cancel
              </button>
              <button
                onClick={handleCreate}
                className="px-6 py-2 bg-orange-600 text-white rounded-lg hover:bg-orange-700"
              >
                Create Order
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Complete Assembly Modal */}
      {showAssemblyModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg max-w-4xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b border-gray-200">
              <h2 className="text-2xl font-bold text-gray-900">Complete Assembly</h2>
              <p className="text-sm text-gray-600 mt-2">
                Select component UIDs to create finished product with full traceability (FIFO recommended)
              </p>
            </div>

            <div className="p-6 space-y-6">
              {/* BOM Components with FIFO UID Selection */}
              {selectedBOM && selectedBOM.items && selectedBOM.items.length > 0 ? (
                selectedBOM.items.map((component, idx) => {
                const uids = availableUIDs[component.item.id] || [];
                const requiredQty = component.quantity * formData.quantity;
                
                return (
                  <div key={idx} className="border border-gray-300 rounded-lg p-4 bg-gray-50">
                    <div className="flex justify-between items-start mb-3">
                      <div>
                        <div className="font-semibold text-gray-900">
                          {component.item.code} - {component.item.name}
                        </div>
                        <div className="text-sm text-gray-600">
                          Required: {requiredQty} {component.uom}
                        </div>
                      </div>
                      <span className={`px-2 py-1 text-xs rounded ${
                        uids.length >= requiredQty 
                          ? 'bg-green-100 text-green-800' 
                          : 'bg-red-100 text-red-800'
                      }`}>
                        {uids.length} available
                      </span>
                    </div>

                    {/* UID Selection - FIFO Sorted */}
                    <div className="space-y-2 max-h-48 overflow-y-auto">
                      {uids.length === 0 ? (
                        <div className="text-center py-4 text-red-600">
                          ⚠️ No UIDs available in inventory. Cannot proceed with assembly.
                        </div>
                      ) : (
                        uids.slice(0, Math.ceil(requiredQty)).map((uid, uidIdx) => (
                          <div
                            key={uidIdx}
                            className={`p-3 border rounded ${
                              uidIdx < requiredQty
                                ? 'border-green-500 bg-green-50'
                                : 'border-gray-300 bg-white'
                            }`}
                          >
                            <div className="flex justify-between items-center">
                              <div className="flex-1">
                                <div className="font-mono text-sm font-semibold text-orange-600">
                                  {uid.uid}
                                </div>
                                <div className="text-xs text-gray-600 mt-1">
                                  Batch: {uid.batch_number} | 
                                  Received: {new Date(uid.received_date).toLocaleDateString()} |
                                  Location: {uid.location}
                                  {uid.expiry_date && (
                                    <span className="ml-2 text-red-600">
                                      Expiry: {new Date(uid.expiry_date).toLocaleDateString()}
                                    </span>
                                  )}
                                </div>
                              </div>
                              {uidIdx < requiredQty && (
                                <span className="ml-3 px-2 py-1 bg-green-600 text-white text-xs rounded">
                                  ✓ Will be used
                                </span>
                              )}
                            </div>
                          </div>
                        ))
                      )}
                    </div>
                  </div>
                );
              })
              ) : (
                <div className="text-center py-8 text-gray-500">
                  <p>No BOM components available. Please ensure a valid BOM is selected.</p>
                </div>
              )}

              <div className="bg-amber-50 border border-amber-200 rounded-lg p-4">
                <p className="text-sm text-amber-800">
                  <strong>🔄 FIFO Logic:</strong> System automatically selects oldest stock first (by received date).
                  Inventory will be reduced automatically upon completion.
                </p>
              </div>

              <div className="bg-orange-50 border border-orange-200 rounded-lg p-4">
                <p className="text-sm text-orange-800">
                  <strong>📦 Assembly Process:</strong><br/>
                  1. System validates all component UIDs are available<br/>
                  2. Generates new Finished Goods UID<br/>
                  3. Links all component UIDs to FG UID<br/>
                  4. Reduces inventory quantities automatically<br/>
                  5. Marks component UIDs as CONSUMED<br/>
                  6. Creates complete traceability record
                </p>
              </div>
            </div>

            <div className="p-6 border-t border-gray-200 flex justify-end gap-3">
              <button
                onClick={() => setShowAssemblyModal(false)}
                className="px-6 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
              >
                Cancel
              </button>
              <button
                onClick={handleCompleteAssembly}
                disabled={!selectedBOM || Object.keys(availableUIDs).length === 0}
                className="px-6 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 disabled:bg-gray-400"
              >
                Complete Assembly & Generate FG UID
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { apiClient } from '../../../../../lib/api-client';

interface DebitNote {
  id: string;
  debit_note_number: string;
  debit_note_date: string;
  total_amount: number;
  status: string;
  reason: string;
  notes?: string;
  grn: { id: string; grn_number: string };
  vendor: { id: string; name: string; code: string };
  creator: { name: string };
  approver?: { name: string };
  approval_date?: string;
  debit_note_items?: DebitNoteItem[];
}

interface DebitNoteItem {
  id: string;
  rejected_qty: number;
  unit_price: number;
  amount: number;
  rejection_reason: string;
  return_status: string;
  return_date?: string;
  disposal_notes?: string;
  item: { id: string; code: string; name: string; unit: string };
}

export default function DebitNotesPage() {
  const [debitNotes, setDebitNotes] = useState<DebitNote[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedDebitNote, setSelectedDebitNote] = useState<DebitNote | null>(null);
  const [showViewModal, setShowViewModal] = useState(false);
  const [filterStatus, setFilterStatus] = useState('');
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    fetchDebitNotes();
  }, [filterStatus]);

  const fetchDebitNotes = async () => {
    try {
      setLoading(true);
      const params = filterStatus ? `?status=${filterStatus}` : '';
      const data = await apiClient.get<DebitNote[]>(`/purchase/debit-notes${params}`);
      setDebitNotes(data);
    } catch (error) {
      console.error('Failed to fetch debit notes:', error);
    } finally {
      setLoading(false);
    }
  };

  const viewDebitNote = async (id: string) => {
    try {
      const data = await apiClient.get<DebitNote>(`/purchase/debit-notes/${id}`);
      setSelectedDebitNote(data);
      setShowViewModal(true);
    } catch (error) {
      console.error('Failed to fetch debit note details:', error);
    }
  };

  const approveDebitNote = async (id: string) => {
    if (!confirm('Are you sure you want to approve this debit note? This will update the GRN payable amount.')) return;
    
    try {
      await apiClient.post(`/purchase/debit-notes/${id}/approve`, {});
      alert('Debit note approved successfully!');
      setShowViewModal(false);
      fetchDebitNotes();
    } catch (error: any) {
      console.error('Failed to approve debit note:', error);
      alert(`Failed to approve: ${error.message || 'Unknown error'}`);
    }
  };

  const sendEmailToSupplier = async (id: string) => {
    if (!confirm('Send this debit note to the supplier via email?')) return;
    
    try {
      await apiClient.post(`/purchase/debit-notes/${id}/send-email`, {});
      alert('Debit note sent to supplier successfully!');
      setShowViewModal(false);
      fetchDebitNotes();
    } catch (error: any) {
      console.error('Failed to send email:', error);
      alert(`Failed to send email: ${error.message || 'Unknown error'}`);
    }
  };

  const updateStatus = async (id: string, status: string) => {
    try {
      await apiClient.put(`/purchase/debit-notes/${id}/status`, { status });
      alert(`Debit note status updated to ${status}`);
      setShowViewModal(false);
      fetchDebitNotes();
    } catch (error: any) {
      console.error('Failed to update status:', error);
      alert(`Failed to update: ${error.message || 'Unknown error'}`);
    }
  };

  const updateReturnStatus = async (debitNoteId: string, itemId: string, returnStatus: string) => {
    const disposalNotes = prompt('Enter disposal notes (optional):');
    
    try {
      await apiClient.put(`/purchase/debit-notes/${debitNoteId}/items/${itemId}/return-status`, {
        returnStatus,
        disposalNotes,
      });
      alert('Return status updated successfully!');
      viewDebitNote(debitNoteId); // Refresh
    } catch (error: any) {
      console.error('Failed to update return status:', error);
      alert(`Failed to update: ${error.message || 'Unknown error'}`);
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'DRAFT': return 'bg-gray-100 text-gray-800';
      case 'APPROVED': return 'bg-green-100 text-green-800';
      case 'SENT': return 'bg-blue-100 text-blue-800';
      case 'ACKNOWLEDGED': return 'bg-purple-100 text-purple-800';
      case 'CLOSED': return 'bg-gray-400 text-white';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const getReturnStatusColor = (status: string) => {
    switch (status) {
      case 'PENDING': return 'bg-yellow-100 text-yellow-800';
      case 'RETURNED': return 'bg-green-100 text-green-800';
      case 'DESTROYED': return 'bg-red-100 text-red-800';
      case 'REWORKED': return 'bg-blue-100 text-blue-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const filteredDebitNotes = debitNotes.filter(dn =>
    dn.debit_note_number.toLowerCase().includes(searchTerm.toLowerCase()) ||
    dn.vendor?.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    dn.grn?.grn_number.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-gradient-to-br from-amber-50 to-orange-50 p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-4xl font-bold text-gray-900 mb-2">📄 Debit Notes</h1>
          <p className="text-gray-600">Manage supplier debit notes for rejected materials</p>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-lg shadow-md p-4 mb-6 flex gap-4">
          <input
            type="text"
            placeholder="Search by DN number, vendor, or GRN..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500"
          />
          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value)}
            className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500"
          >
            <option value="">All Status</option>
            <option value="DRAFT">Draft</option>
            <option value="APPROVED">Approved</option>
            <option value="SENT">Sent</option>
            <option value="ACKNOWLEDGED">Acknowledged</option>
            <option value="CLOSED">Closed</option>
          </select>
        </div>

        {/* Debit Notes Table */}
        <div className="bg-white rounded-lg shadow-md overflow-hidden">
          {loading ? (
            <div className="p-8 text-center text-gray-500">Loading debit notes...</div>
          ) : filteredDebitNotes.length === 0 ? (
            <div className="p-12 text-center">
              <div className="text-6xl mb-4">📄</div>
              <h3 className="text-xl font-semibold text-gray-700 mb-2">No Debit Notes Found</h3>
              <p className="text-gray-500">Debit notes will be auto-created when materials are rejected during QC</p>
            </div>
          ) : (
            <table className="w-full">
              <thead className="bg-amber-50">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-medium text-amber-900 uppercase">DN Number</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-amber-900 uppercase">Date</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-amber-900 uppercase">GRN</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-amber-900 uppercase">Vendor</th>
                  <th className="px-6 py-3 text-right text-xs font-medium text-amber-900 uppercase">Amount</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-amber-900 uppercase">Status</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-amber-900 uppercase">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200">
                {filteredDebitNotes.map((dn) => (
                  <tr key={dn.id} className="hover:bg-gray-50">
                    <td className="px-6 py-4">
                      <div className="font-semibold text-gray-900">{dn.debit_note_number}</div>
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-600">
                      {new Date(dn.debit_note_date).toLocaleDateString()}
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-900">{dn.grn?.grn_number || '-'}</td>
                    <td className="px-6 py-4">
                      <div className="text-sm text-gray-900">{dn.vendor?.name}</div>
                      <div className="text-xs text-gray-500">{dn.vendor?.code}</div>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="text-lg font-bold text-red-600">
                        ₹{dn.total_amount.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`px-3 py-1 rounded-full text-xs font-semibold ${getStatusColor(dn.status)}`}>
                        {dn.status}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <button
                        onClick={() => viewDebitNote(dn.id)}
                        className="text-amber-600 hover:text-amber-800 font-medium"
                      >
                        View Details →
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>

      {/* View Debit Note Modal */}
      {showViewModal && selectedDebitNote && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg max-w-4xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b border-gray-200 flex justify-between items-center">
              <div>
                <h2 className="text-2xl font-bold text-gray-900">{selectedDebitNote.debit_note_number}</h2>
                <p className="text-sm text-gray-500 mt-1">
                  Created by {selectedDebitNote.creator?.name} on {new Date(selectedDebitNote.debit_note_date).toLocaleDateString()}
                </p>
              </div>
              <button
                onClick={() => setShowViewModal(false)}
                className="text-gray-500 hover:text-gray-700 text-2xl"
              >
                ×
              </button>
            </div>

            <div className="p-6 space-y-6">
              {/* Header Information */}
              <div className="grid grid-cols-2 gap-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">GRN Number</label>
                  <p className="text-gray-900 font-semibold">{selectedDebitNote.grn?.grn_number}</p>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Status</label>
                  <span className={`px-3 py-1 rounded-full text-xs font-semibold ${getStatusColor(selectedDebitNote.status)}`}>
                    {selectedDebitNote.status}
                  </span>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Vendor</label>
                  <p className="text-gray-900">{selectedDebitNote.vendor?.name}</p>
                  <p className="text-sm text-gray-500">{selectedDebitNote.vendor?.code}</p>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Total Amount</label>
                  <p className="text-2xl font-bold text-red-600">
                    ₹{selectedDebitNote.total_amount.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                  </p>
                </div>
              </div>

              {/* Reason */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Reason</label>
                <p className="text-gray-900 bg-gray-50 p-3 rounded-lg">{selectedDebitNote.reason}</p>
              </div>

              {selectedDebitNote.notes && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Notes</label>
                  <p className="text-gray-900 bg-gray-50 p-3 rounded-lg">{selectedDebitNote.notes}</p>
                </div>
              )}

              {/* Approval Info */}
              {selectedDebitNote.approver && (
                <div className="bg-green-50 border border-green-200 rounded-lg p-4">
                  <p className="text-sm text-green-800">
                    ✓ Approved by <strong>{selectedDebitNote.approver.name}</strong> on{' '}
                    {new Date(selectedDebitNote.approval_date!).toLocaleDateString()}
                  </p>
                </div>
              )}

              {/* Line Items */}
              <div>
                <h3 className="text-lg font-bold text-gray-900 mb-4">Rejected Items</h3>
                <div className="space-y-3">
                  {selectedDebitNote.debit_note_items?.map((item) => (
                    <div key={item.id} className="border border-red-200 rounded-lg p-4 bg-red-50">
                      <div className="flex justify-between items-start mb-3">
                        <div>
                          <div className="font-semibold text-gray-900">
                            {item.item.name} ({item.item.code})
                          </div>
                          <div className="text-sm text-gray-600 mt-1">
                            Quantity: <span className="font-bold">{item.rejected_qty} {item.item.unit}</span>
                            <span className="mx-2">×</span>
                            ₹{item.unit_price.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                            <span className="mx-2">=</span>
                            <span className="font-bold text-red-600">
                              ₹{item.amount.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                            </span>
                          </div>
                        </div>
                        <span className={`px-2 py-1 rounded text-xs font-bold ${getReturnStatusColor(item.return_status)}`}>
                          {item.return_status}
                        </span>
                      </div>
                      
                      <div className="text-sm text-gray-700 bg-white border-l-4 border-red-400 p-2 rounded mb-2">
                        <span className="font-medium">Rejection Reason:</span> {item.rejection_reason}
                      </div>

                      {item.disposal_notes && (
                        <div className="text-sm text-gray-600 bg-white p-2 rounded">
                          <span className="font-medium">Disposal Notes:</span> {item.disposal_notes}
                        </div>
                      )}

                      {/* Return Status Actions */}
                      {item.return_status === 'PENDING' && selectedDebitNote.status !== 'CLOSED' && (
                        <div className="mt-3 flex gap-2">
                          <button
                            onClick={() => updateReturnStatus(selectedDebitNote.id, item.id, 'RETURNED')}
                            className="px-3 py-1 text-xs bg-green-600 text-white rounded hover:bg-green-700"
                          >
                            Mark Returned
                          </button>
                          <button
                            onClick={() => updateReturnStatus(selectedDebitNote.id, item.id, 'DESTROYED')}
                            className="px-3 py-1 text-xs bg-red-600 text-white rounded hover:bg-red-700"
                          >
                            Mark Destroyed
                          </button>
                          <button
                            onClick={() => updateReturnStatus(selectedDebitNote.id, item.id, 'REWORKED')}
                            className="px-3 py-1 text-xs bg-blue-600 text-white rounded hover:bg-blue-700"
                          >
                            Mark Reworked
                          </button>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Footer Actions */}
            <div className="p-6 border-t border-gray-200 flex justify-between items-center">
              <button
                onClick={() => setShowViewModal(false)}
                className="px-6 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
              >
                Close
              </button>
              <div className="flex gap-3">
                {selectedDebitNote.status === 'DRAFT' && (
                  <button
                    onClick={() => approveDebitNote(selectedDebitNote.id)}
                    className="px-6 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700"
                  >
                    ✓ Approve Debit Note
                  </button>
                )}
                {selectedDebitNote.status === 'APPROVED' && (
                  <button
                    onClick={() => sendEmailToSupplier(selectedDebitNote.id)}
                    className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
                  >
                    📧 Send Email to Supplier
                  </button>
                )}
                {selectedDebitNote.status === 'SENT' && (
                  <button
                    onClick={() => updateStatus(selectedDebitNote.id, 'ACKNOWLEDGED')}
                    className="px-6 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700"
                  >
                    ✓ Mark as Acknowledged
                  </button>
                )}
                {selectedDebitNote.status === 'ACKNOWLEDGED' && (
                  <button
                    onClick={() => updateStatus(selectedDebitNote.id, 'CLOSED')}
                    className="px-6 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700"
                  >
                    🔒 Close Debit Note
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { apiClient } from '../../../../../lib/api-client';

function getApiV1BaseUrl(): string | null {
  const raw = (process.env.NEXT_PUBLIC_API_URL || '').trim();
  if (!raw) return null;
  const normalized = raw.endsWith('/') ? raw.slice(0, -1) : raw;
  return normalized.endsWith('/api/v1') ? normalized : `${normalized}/api/v1`;
}

interface GRN {
  id: string;
  grn_number: string;
  grn_date: string;
  invoice_number: string;
  invoice_date: string;
  invoice_file_url?: string;
  invoice_file_name?: string;
  invoice_file_type?: string;
  invoice_file_size?: number;
  status: string;
  remarks?: string;
  qc_completed?: boolean;
  gross_amount?: number;
  debit_note_amount?: number;
  net_payable_amount?: number;
  vendor: {
    name: string;
    code: string;
  };
  purchase_order: {
    po_number: string;
  };
  warehouse: {
    id?: string;
    name: string;
  };
  grn_items: Array<{
    id?: string;
    item_code?: string;
    item_name?: string;
    item?: { name: string; code: string; hsn_code?: string };
    received_qty?: number;
    accepted_qty?: number;
    rejected_qty?: number;
    received_quantity?: number;
    accepted_quantity?: number;
    rejected_quantity?: number;
    uid?: string;
    batch_number?: string;
    supplier_hsn_code?: string;
    unit_price?: number;
    rejection_amount?: number;
    rejection_reason?: string;
    qc_notes?: string;
    qc_file_url?: string;
    qc_file_name?: string;
    qc_file_type?: string;
    qc_file_size?: number;
    return_status?: string;
    debit_note_id?: string;
  }>;
}

interface UIDRecord {
  uid: string;
  entity_type: string;
  status: string;
  location: string;
  batch_number: string;
  created_at: string;
  item?: {
    code: string;
    name: string;
  };
}

interface PurchaseTrail {
  uid: string;
  item: { code: string; name: string };
  supplier: { name: string; contact_person: string } | null;
  purchase_order: { po_number: string; order_date: string; total_amount: number } | null;
  grn: { grn_number: string; received_date: string; received_quantity: number } | null;
  batch_number: string | null;
  location: string | null;
  lifecycle: Array<{
    stage: string;
    timestamp: string;
    location: string;
    reference: string;
  }>;
}

interface PurchaseOrder {
  id: string;
  po_number: string;
  vendor_id: string;
  vendor: {
    id: string;
    name: string;
    code: string;
  };
  po_date: string;
  status: string;
  purchase_order_items: Array<{
    id: string;
    item_id: string;
    item_code: string;
    item_name: string;
    uom?: string;
    ordered_qty: number;
    rate: number;
    item?: {
      hsn_code?: string;
    };
  }>;
}

interface Warehouse {
  id: string;
  code: string;
  name: string;
  location: string;
}

type ItemUidConfig = {
  id: string;
  uid_tracking?: boolean;
  uid_strategy?: string;
  batch_uom?: string;
  batch_quantity?: number;
};

function GRNContent() {
  // const { duplicateState, checkDuplicates, handleProceed, handleCancel } = useDuplicateDetection();
  const router = useRouter();
  const [grns, setGrns] = useState<GRN[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [filterStatus, setFilterStatus] = useState('ALL');
  const [searchTerm, setSearchTerm] = useState('');
  const [showUIDsModal, setShowUIDsModal] = useState(false);
  const [selectedGRNUIDs, setSelectedGRNUIDs] = useState<UIDRecord[]>([]);
  const [loadingUIDs, setLoadingUIDs] = useState(false);
  const [showTrailModal, setShowTrailModal] = useState(false);
  const [purchaseTrail, setPurchaseTrail] = useState<PurchaseTrail | null>(null);
  const [loadingTrail, setLoadingTrail] = useState(false);
  const [purchaseOrders, setPurchaseOrders] = useState<PurchaseOrder[]>([]);
  const [warehouses, setWarehouses] = useState<Warehouse[]>([]);
  const [itemUidConfigById, setItemUidConfigById] = useState<Record<string, ItemUidConfig>>({});
  const [selectedPO, setSelectedPO] = useState<PurchaseOrder | null>(null);
  const [alertMessage, setAlertMessage] = useState<{ type: 'success' | 'error' | 'info'; message: string } | null>(null);
  const [showViewModal, setShowViewModal] = useState(false);
  const [showQCModal, setShowQCModal] = useState(false);
  const [selectedGRN, setSelectedGRN] = useState<GRN | null>(null);
  const [qcFormData, setQcFormData] = useState<Array<{
    itemId: string;
    itemCode: string;
    itemName: string;
    receivedQty: number;
    acceptedQty: number;
    rejectedQty: number;
    qcNotes: string;
    rejectionReason: string;
    qcFileUrl?: string;
    qcFileName?: string;
    qcFileType?: string;
    qcFileSize?: number;
  }>>([]);
  const [editMode, setEditMode] = useState(false);
  const [editFormData, setEditFormData] = useState<{
    invoiceNumber: string;
    invoiceDate: string;
    invoiceFileUrl: string;
    invoiceFileName: string;
    invoiceFileType: string;
    invoiceFileSize: number;
    warehouseId: string;
    notes: string;
    items: Array<{
      id?: string;
      itemId?: string;
      poItemId?: string;
      itemCode: string;
      itemName: string;
      uom?: string;
      orderedQuantity?: number;
      receivedQty: number;
      acceptedQty: number;
      rejectedQty: number;
      unitPrice?: number;
      batchNumber: string;
      expiryDate?: string;
      notes?: string;
    }>;
  }>({
    invoiceNumber: '',
    invoiceDate: '',
    invoiceFileUrl: '',
    invoiceFileName: '',
    invoiceFileType: '',
    invoiceFileSize: 0,
    warehouseId: '',
    notes: '',
    items: [],
  });

  const [formData, setFormData] = useState({
    poId: '',
    vendorId: '',
    receiptDate: new Date().toISOString().split('T')[0],
    invoiceNumber: '',
    invoiceDate: '',
    invoiceFileUrl: '',
    invoiceFileName: '',
    invoiceFileType: '',
    invoiceFileSize: 0,
    warehouseId: '',
    notes: '',
    items: [] as Array<{
      itemId: string;
      itemCode?: string;
      itemName?: string;
      poItemId: string;
      uom?: string;
      orderedQuantity: number;
      receivedQuantity: number;
      acceptedQuantity: number;
      rejectedQuantity: number;
      unitPrice: number;
      batchNumber: string;
      expiryDate: string;
      notes: string;
      rejectionReason?: string;
      supplierHsnCode?: string;
      masterHsnCode?: string;
    }>,
  });

  const handleViewInvoice = (invoiceFileUrl: string, invoiceFileName?: string) => {
    // Convert base64 data URL to blob and open in new window
    if (invoiceFileUrl.startsWith('data:')) {
      const base64Data = invoiceFileUrl.split(',')[1];
      const mimeType = invoiceFileUrl.split(':')[1].split(';')[0];
      const byteCharacters = atob(base64Data);
      const byteNumbers = new Array(byteCharacters.length);
      for (let i = 0; i < byteCharacters.length; i++) {
        byteNumbers[i] = byteCharacters.charCodeAt(i);
      }
      const byteArray = new Uint8Array(byteNumbers);
      const blob = new Blob([byteArray], { type: mimeType });
      const url = URL.createObjectURL(blob);
      const newWindow = window.open(url, '_blank');
      // Clean up the URL after window opens
      if (newWindow) {
        newWindow.onload = () => {
          URL.revokeObjectURL(url);
        };
      }
    } else {
      // Regular URL, open directly
      window.open(invoiceFileUrl, '_blank');
    }
  };

  const handleInvoiceFileSelect = (file: File, target: 'create' | 'edit') => {
    const validTypes = ['image/png', 'image/jpeg', 'image/jpg', 'application/pdf'];
    if (!validTypes.includes(file.type)) {
      alert('Please upload PNG, JPG, or PDF files only');
      return;
    }
    if (file.size > 10 * 1024 * 1024) {
      alert('File size must be less than 10MB');
      return;
    }

    // Prefer server-side upload (avoids large base64 JSON payloads that can break GRN save)
    const upload = async () => {
      try {
        const token = localStorage.getItem('accessToken');
        const fd = new FormData();
        fd.append('file', file);

        const apiBase = getApiV1BaseUrl();
        const uploadUrl = apiBase
          ? `${apiBase}/purchase/grn/invoice/upload`
          : '/api/v1/purchase/grn/invoice/upload';

        const response = await fetch(uploadUrl, {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${token}`,
          },
          body: fd,
        });

        if (response.ok) {
          const data = await response.json();
          const url = String(data?.url || '').trim();
          if (!url) throw new Error('Upload did not return a URL');

          if (target === 'create') {
            setFormData(prev => ({
              ...prev,
              invoiceFileUrl: url,
              invoiceFileName: String(data?.name || file.name),
              invoiceFileType: String(data?.type || file.type),
              invoiceFileSize: Number(data?.size || file.size) || 0,
            }));
          } else {
            setEditFormData(prev => ({
              ...prev,
              invoiceFileUrl: url,
              invoiceFileName: String(data?.name || file.name),
              invoiceFileType: String(data?.type || file.type),
              invoiceFileSize: Number(data?.size || file.size) || 0,
            }));
          }

          return;
        }
      } catch (e) {
        console.warn('Invoice upload failed; falling back to base64', e);
      }

      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = reader.result as string;
        if (target === 'create') {
          setFormData(prev => ({
            ...prev,
            invoiceFileUrl: base64,
            invoiceFileName: file.name,
            invoiceFileType: file.type,
            invoiceFileSize: file.size,
          }));
        } else {
          setEditFormData(prev => ({
            ...prev,
            invoiceFileUrl: base64,
            invoiceFileName: file.name,
            invoiceFileType: file.type,
            invoiceFileSize: file.size,
          }));
        }
      };
      reader.readAsDataURL(file);
    };

    upload();
  };

  const handleQCFileSelect = async (file: File, index: number) => {
    const validTypes = ['image/png', 'image/jpeg', 'image/jpg', 'application/pdf'];
    if (!validTypes.includes(file.type)) {
      alert('Please upload PNG, JPG, or PDF files only');
      return;
    }
    if (file.size > 10 * 1024 * 1024) {
      alert('File size must be less than 10MB');
      return;
    }

    try {
      const token = localStorage.getItem('accessToken');
      const fd = new FormData();
      fd.append('file', file);

      const apiBase = getApiV1BaseUrl();
      const uploadUrl = apiBase
        ? `${apiBase}/purchase/grn/qc/upload`
        : '/api/v1/purchase/grn/qc/upload';

      const response = await fetch(uploadUrl, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${token}`,
        },
        body: fd,
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        alert(`QC upload failed: ${errorData.message || response.statusText}`);
        return;
      }

      const data = await response.json();
      const url = String(data?.url || '').trim();
      if (!url) {
        alert('QC upload failed: no URL returned');
        return;
      }

      const newData = [...qcFormData];
      newData[index] = {
        ...newData[index],
        qcFileUrl: url,
        qcFileName: String(data?.name || file.name),
        qcFileType: String(data?.type || file.type),
        qcFileSize: Number(data?.size || file.size) || 0,
      };
      setQcFormData(newData);
    } catch (e) {
      console.error('QC upload error:', e);
      alert('QC upload failed. Please try again.');
    }
  };

  useEffect(() => {
    fetchGRNs();
    fetchPurchaseOrders();
    fetchWarehouses();
  }, [filterStatus]);

  useEffect(() => {
    // Used to show container/drum breakdown while entering GRN qty in base UOM.
    const fetchItemUidConfig = async () => {
      try {
        const token = localStorage.getItem('accessToken');
        const response = await fetch('/api/v1/inventory/items?includeInactive=true', {
          headers: {
            Authorization: `Bearer ${token}`,
            'Content-Type': 'application/json',
          },
        });

        if (!response.ok) {
          return;
        }

        const data = await response.json();
        const items = Array.isArray(data) ? data : [];
        const next: Record<string, ItemUidConfig> = {};
        for (const it of items) {
          if (!it?.id) continue;
          next[String(it.id)] = {
            id: String(it.id),
            uid_tracking: it.uid_tracking,
            uid_strategy: it.uid_strategy,
            batch_uom: it.batch_uom,
            batch_quantity: typeof it.batch_quantity === 'number' ? it.batch_quantity : Number(it.batch_quantity) || undefined,
          };
        }
        setItemUidConfigById(next);
      } catch {
        // Best-effort UI enhancement only.
      }
    };

    fetchItemUidConfig();
  }, []);

  const fetchPurchaseOrders = async () => {
    try {
      const token = localStorage.getItem('accessToken');
      
      // Fetch all approved POs
      const poResponse = await fetch('/api/v1/purchase/orders?status=APPROVED', {
        headers: { 
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      });
      
      if (!poResponse.ok) {
        const errorData = await poResponse.json();
        console.error('Failed to fetch purchase orders:', poResponse.status, errorData);
        setPurchaseOrders([]);
        return;
      }
      
      const allPOs = await poResponse.json();
      
      // Fetch all GRNs to check which POs already have GRNs
      const grnResponse = await fetch('/api/v1/purchase/grn', {
        headers: { 
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      });
      
      let poIdsWithGRNs = new Set();
      if (grnResponse.ok) {
        const allGRNs = await grnResponse.json();
        poIdsWithGRNs = new Set(allGRNs.map((grn: any) => grn.po_id));
      }
      
      // Filter out POs that already have GRNs
      const availablePOs = Array.isArray(allPOs) ? allPOs.filter((po: any) => !poIdsWithGRNs.has(po.id)) : [];
      
      console.log('Available POs (without GRNs):', availablePOs);
      setPurchaseOrders(availablePOs);
    } catch (error) {
      console.error('Error fetching purchase orders:', error);
      setPurchaseOrders([]);
    }
  };

  const fetchWarehouses = async () => {
    try {
      const token = localStorage.getItem('accessToken');
      const response = await fetch('/api/v1/inventory/warehouses', {
        headers: { 
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      });
      
      if (!response.ok) {
        const errorData = await response.json();
        console.error('Failed to fetch warehouses:', response.status, errorData);
        if (response.status === 401) {
          console.error('Authentication failed - token may be expired');
        }
        setWarehouses([]);
        return;
      }
      
      const data = await response.json();
      console.log('Warehouses fetched:', data);
      setWarehouses(Array.isArray(data) ? data : []);
    } catch (error) {
      console.error('Error fetching warehouses:', error);
      setWarehouses([]);
    }
  };

  const handlePOChange = (poId: string) => {
    const po = purchaseOrders.find(p => p.id === poId);
    if (po) {
      setSelectedPO(po);
      setFormData({
        ...formData,
        poId: po.id,
        vendorId: po.vendor_id,
        items: po.purchase_order_items.map(item => ({
          itemId: item.item_id ?? (item as any).itemId ?? (item as any).item?.id,
          itemCode: item.item_code,
          itemName: item.item_name,
          poItemId: item.id,
          uom: item.uom || '',
          orderedQuantity: item.ordered_qty,
          receivedQuantity: item.ordered_qty,
          acceptedQuantity: item.ordered_qty,
          rejectedQuantity: 0,
          unitPrice: item.rate,
          batchNumber: '',
          expiryDate: '',
          notes: '',
          rejectionReason: '',
          masterHsnCode: item.item?.hsn_code || '',
          supplierHsnCode: item.item?.hsn_code || '',
        })),
      });
    }
  };

  const fetchGRNs = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      if (filterStatus !== 'ALL') params.append('status', filterStatus);
      if (searchTerm) params.append('search', searchTerm);

      const data = await apiClient.get(`/purchase/grn?${params}`);
      setGrns(data);
    } catch (error) {
      console.error('Error fetching GRNs:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleUpdateGRN = async () => {
    if (!selectedGRN) return;
    
    try {
      const missingIds = editFormData.items.some((it) => !it.itemId || !it.poItemId);
      if (missingIds) {
        alert('Some GRN items are missing Item/PO Item IDs. Please close and re-open Edit.');
        return;
      }

      await apiClient.put(`/purchase/grn/${selectedGRN.id}`, {
        invoiceNumber: editFormData.invoiceNumber,
        invoiceDate: editFormData.invoiceDate,
        invoiceFileUrl: editFormData.invoiceFileUrl || null,
        invoiceFileName: editFormData.invoiceFileName || null,
        invoiceFileType: editFormData.invoiceFileType || null,
        invoiceFileSize: editFormData.invoiceFileSize || null,
        warehouseId: editFormData.warehouseId,
        remarks: editFormData.notes,
        items: editFormData.items.map(item => ({
          itemId: item.itemId,
          poItemId: item.poItemId,
          itemCode: item.itemCode,
          itemName: item.itemName,
          orderedQuantity: item.orderedQuantity ?? item.receivedQty,
          receivedQuantity: item.receivedQty,
          acceptedQuantity: item.acceptedQty,
          rejectedQuantity: item.rejectedQty,
          unitPrice: item.unitPrice ?? 0,
          batchNumber: item.batchNumber,
          expiryDate: item.expiryDate || null,
          notes: item.notes || null,
        })),
      });

      setAlertMessage({ type: 'success', message: 'GRN updated successfully!' });
      setShowViewModal(false);
      setEditMode(false);
      fetchGRNs();
    } catch (error) {
      console.error('Error updating GRN:', error);
      setAlertMessage({ type: 'error', message: 'Failed to update GRN. Please try again.' });
    }
  };

  const actuallyCreateGRN = async () => {
    try {
      // Validate required fields
      if (!formData.poId) {
        alert('Please select a Purchase Order');
        return;
      }
      
      if (!formData.warehouseId) {
        alert('Please select a Warehouse');
        return;
      }
      
      if (formData.items.length === 0) {
        alert('No items to receive. Please select a PO with items.');
        return;
      }
      
      // Transform data to match API expectations
      const payload = {
        poId: formData.poId,
        vendorId: formData.vendorId,
        grnDate: formData.receiptDate,
        invoiceNumber: formData.invoiceNumber || null,
        invoiceDate: formData.invoiceDate || null,
        invoiceFileUrl: formData.invoiceFileUrl || null,
        invoiceFileName: formData.invoiceFileName || null,
        invoiceFileType: formData.invoiceFileType || null,
        invoiceFileSize: formData.invoiceFileSize || null,
        warehouseId: formData.warehouseId,
        remarks: formData.notes || null,
        status: 'DRAFT',
        items: formData.items.map(item => ({
          itemId: item.itemId,
          poItemId: item.poItemId,
          itemCode: item.itemCode,
          itemName: item.itemName,
          orderedQty: item.orderedQuantity,
          receivedQty: item.receivedQuantity,
          acceptedQty: item.acceptedQuantity,
          rejectedQty: item.rejectedQuantity,
          rejectionReason: item.rejectionReason || null,
          rate: item.unitPrice,
          batchNumber: item.batchNumber || null,
          expiryDate: item.expiryDate || null,
          remarks: item.notes || null,
          supplierHsnCode: item.supplierHsnCode || null,
        })),
      };
      
      console.log('Creating GRN with payload:', payload);
      console.log('Items with acceptedQty:', payload.items.map(i => `${i.itemCode}: ${i.acceptedQty}`));
      
      // Update item HSN codes if different from master
      const token = localStorage.getItem('accessToken');
      for (const item of formData.items) {
        if (item.supplierHsnCode && item.supplierHsnCode !== item.masterHsnCode) {
          console.log(`Updating HSN for ${item.itemCode}: ${item.masterHsnCode} → ${item.supplierHsnCode}`);
          try {
            await fetch(`/api/v1/inventory/items/${item.itemId}`, {
              method: 'PUT',
              headers: {
                'Content-Type': 'application/json',
                Authorization: `Bearer ${token}`,
              },
              body: JSON.stringify({ hsn_code: item.supplierHsnCode }),
            });
          } catch (err) {
            console.error(`Failed to update HSN for ${item.itemCode}:`, err);
          }
        }
      }
      
      const response = await fetch('/api/v1/purchase/grn', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(payload),
      });

      if (response.ok) {
        const data = await response.json();
        console.log('GRN created successfully:', data);
        setAlertMessage({ type: 'success', message: 'GRN created successfully!' });
        setShowModal(false);
        fetchGRNs();
        fetchPurchaseOrders(); // Refresh PO list to remove the used PO
        resetForm();
      } else {
        const errorData = await response.json();
        console.error('GRN creation failed:', errorData);
        setAlertMessage({ type: 'error', message: `Failed to create GRN: ${errorData.message || 'Unknown error'}` });
      }
    } catch (error) {
      console.error('Error creating GRN:', error);
      setAlertMessage({ type: 'error', message: 'Failed to create GRN. Please try again.' });
    }
  };

  const handleCreateGRN = async () => {
    // Validate required fields first
    if (!formData.poId) {
      alert('Please select a Purchase Order');
      return;
    }
    
    if (!formData.warehouseId) {
      alert('Please select a Warehouse');
      return;
    }
    
    if (formData.items.length === 0) {
      alert('No items to receive. Please select a PO with items.');
      return;
    }

    // Prepare payload for duplicate check
    const checkPayload = {
      purchaseOrderId: formData.poId,
      items: formData.items.map(item => ({
        itemId: item.itemId,
        quantity: item.receivedQuantity,
      })),
    };

    // Directly create GRN (duplicate detection temporarily disabled)
    await actuallyCreateGRN();
  };

  const fetchGRNUIDs = async (grnId: string) => {
    try {
      console.log('Fetching UIDs for GRN:', grnId);
      setLoadingUIDs(true);
      setSelectedGRNUIDs([]);
      const token = localStorage.getItem('accessToken');
      const response = await fetch(`/api/v1/purchase/grn/${grnId}/uids`, {
        headers: { 
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      });

      console.log('UIDs response status:', response.status);
      if (response.ok) {
        const data = await response.json();
        console.log('UIDs data received:', data);
        const uidsArray = Array.isArray(data) ? data : [];
        console.log('Setting UIDs array:', uidsArray);
        
        if (uidsArray.length === 0) {
          setAlertMessage({ 
            type: 'info', 
            message: 'No UIDs found. UIDs are generated when GRN status is COMPLETED. Please ensure the GRN is completed first.' 
          });
        } else {
          setSelectedGRNUIDs(uidsArray);
          setShowUIDsModal(true);
        }
      } else {
        const errorData = await response.json();
        console.error('Failed to fetch UIDs:', errorData);
        setAlertMessage({
          type: 'error',
          message: `Failed to fetch UIDs: ${errorData.message || 'Unknown error'}. UIDs are auto-generated when GRN status is COMPLETED.` 
        });
      }
    } catch (error) {
      console.error('Error fetching UIDs:', error);
      setAlertMessage({ type: 'error', message: 'Failed to fetch UIDs. Please check your connection.' });
    } finally {
      setLoadingUIDs(false);
    }
  };

  const fetchPurchaseTrail = async (uid: string) => {
    try {
      setLoadingTrail(true);
      const token = localStorage.getItem('accessToken');
      
      const response = await fetch(`/api/v1/uid/${uid}/purchase-trail`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (response.ok) {
        const data = await response.json();
        setPurchaseTrail(data);
        setShowTrailModal(true);
      } else {
        alert('Purchase trail not found for this UID');
      }
    } catch (error) {
      console.error('Error fetching purchase trail:', error);
      alert('Failed to fetch purchase trail');
    } finally {
      setLoadingTrail(false);
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-IN', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const handleAddItem = () => {
    setFormData({
      ...formData,
      items: [
        ...formData.items,
        {
          itemId: '',
          poItemId: '',
          orderedQuantity: 0,
          receivedQuantity: 0,
          acceptedQuantity: 0,
          rejectedQuantity: 0,
          unitPrice: 0,
          batchNumber: '',
          expiryDate: '',
          notes: '',
          rejectionReason: '',
        },
      ],
    });
  };

  const handleUpdateItem = (index: number, field: string, value: any) => {
    const updatedItems = [...formData.items];
    updatedItems[index] = { ...updatedItems[index], [field]: value };

    const toNum = (v: any) => {
      const n = typeof v === 'number' ? v : Number(v);
      return Number.isFinite(n) ? n : 0;
    };

    // Auto-calculate accepted/rejected based on received
    if (field === 'receivedQuantity') {
      const ordered = Math.max(0, toNum(updatedItems[index].orderedQuantity));
      let receivedInput = Math.max(0, toNum(value));
      
      // Validate: Received cannot exceed Ordered
      if (receivedInput > ordered) {
        alert(`Received quantity (${receivedInput}) cannot exceed ordered quantity (${ordered})`);
        receivedInput = ordered; // Cap at ordered quantity
      }
      
      const received = receivedInput;
      updatedItems[index].receivedQuantity = received;
      updatedItems[index].acceptedQuantity = received;
      updatedItems[index].rejectedQuantity = 0;
    }

    if (field === 'acceptedQuantity' || field === 'rejectedQuantity') {
      const item = updatedItems[index];
      if (field === 'acceptedQuantity') {
        let received = Math.max(0, toNum(item.receivedQuantity));
        const ordered = Math.max(0, toNum(item.orderedQuantity));
        const acceptedRaw = Math.max(0, toNum(value));

        // UX: if user edits Accepted and hasn't explicitly adjusted Received,
        // assume full receipt (Received = Ordered) so Rejected auto-fills.
        if (ordered > 0 && (received === 0 || (received === acceptedRaw && ordered > received))) {
          received = ordered;
          item.receivedQuantity = received;
        }

        const accepted = Math.min(received, acceptedRaw);
        item.acceptedQuantity = accepted;
        item.rejectedQuantity = received - accepted;
      } else {
        const received = Math.max(0, toNum(item.receivedQuantity));
        const rejected = Math.min(received, Math.max(0, toNum(value)));
        item.rejectedQuantity = rejected;
        item.acceptedQuantity = received - rejected;
      }
    }

    setFormData({ ...formData, items: updatedItems });
  };

  const handleRemoveItem = (index: number) => {
    setFormData({
      ...formData,
      items: formData.items.filter((_, i) => i !== index),
    });
  };

  const resetForm = () => {
    setSelectedPO(null);
    setFormData({
      poId: '',
      vendorId: '',
      receiptDate: new Date().toISOString().split('T')[0],
      invoiceNumber: '',
      invoiceDate: '',
      invoiceFileUrl: '',
      invoiceFileName: '',
      invoiceFileType: '',
      invoiceFileSize: 0,
      warehouseId: '',
      notes: '',
      items: [],
    });
  };

  const getStatusColor = (status: string) => {
    return status === 'COMPLETED'
      ? 'bg-green-100 text-green-800'
      : status === 'CANCELLED'
      ? 'bg-red-100 text-red-800'
      : 'bg-gray-100 text-gray-800';
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-amber-50 to-orange-50 p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="flex justify-between items-center mb-8">
          <div>
            <button
              onClick={() => router.push('/dashboard/purchase')}
              className="text-amber-600 hover:text-amber-800 mb-2"
            >
              ← Back to Purchase Management
            </button>
            <h1 className="text-4xl font-bold text-amber-900">Goods Receipt Note (GRN)</h1>
            <p className="text-amber-700">Record and manage goods received from vendors</p>
          </div>
          <button
            onClick={() => setShowModal(true)}
            className="bg-amber-600 hover:bg-amber-700 text-white px-6 py-3 rounded-lg font-semibold"
          >
            + Create GRN
          </button>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-lg shadow-md p-6 mb-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Status</label>
              <select
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value)}
                className="w-full border border-gray-300 rounded-lg px-4 py-2"
              >
                <option value="ALL">All Status</option>
                <option value="DRAFT">Draft</option>
                <option value="COMPLETED">Completed</option>
                <option value="CANCELLED">Cancelled</option>
              </select>
            </div>
            <div className="md:col-span-2">
              <label className="block text-sm font-medium text-gray-700 mb-2">Search</label>
              <input
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && fetchGRNs()}
                placeholder="Search by GRN number, invoice number..."
                className="w-full border border-gray-300 rounded-lg px-4 py-2"
              />
            </div>
          </div>
        </div>

        {/* GRN List */}
        <div className="bg-white rounded-lg shadow-sm border border-gray-200">
          <div className="overflow-x-auto">
          {loading ? (
            <div className="p-8 text-center text-gray-500">Loading GRNs...</div>
          ) : grns.length === 0 ? (
            <div className="p-12 text-center">
              <div className="text-6xl mb-4">📦</div>
              <h3 className="text-xl font-semibold text-gray-700 mb-2">No GRNs Yet</h3>
              <p className="text-gray-500">Create your first goods receipt note to track incoming inventory</p>
            </div>
          ) : (
            <table className="w-full min-w-[1100px]">
              <thead className="bg-gray-50 border-b border-gray-200">
                <tr>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">GRN Number</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">PO Number</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">Vendor</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">Receipt Date</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">Invoice</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">Warehouse</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">Items / UIDs</th>
                  <th className="px-4 py-3 text-center text-xs font-semibold text-gray-600 uppercase tracking-wider">Status</th>
                  <th className="px-4 py-3 text-right text-xs font-semibold text-gray-600 uppercase tracking-wider">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {grns.map((grn) => (
                  <tr key={grn.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-4 py-3 whitespace-nowrap font-medium text-gray-900">{grn.grn_number}</td>
                    <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-600">
                      {grn.purchase_order?.po_number || '-'}
                    </td>
                    <td className="px-4 py-3">
                      <div className="text-sm font-medium text-gray-900">{grn.vendor.name}</div>
                      <div className="text-xs text-gray-500">{grn.vendor.code}</div>
                    </td>
                    <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-600">
                      {grn.grn_date ? new Date(grn.grn_date).toLocaleDateString() : '-'}
                    </td>
                    <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-600">
                      <div>{grn.invoice_number || '-'}</div>
                      {grn.invoice_date && (
                        <div className="text-xs text-gray-400">{new Date(grn.invoice_date).toLocaleDateString()}</div>
                      )}
                      {grn.invoice_file_url && (
                        <button
                          onClick={() => handleViewInvoice(grn.invoice_file_url!, grn.invoice_file_name)}
                          className="text-xs text-blue-600 hover:text-blue-800 underline cursor-pointer"
                        >
                          View Invoice
                        </button>
                      )}
                    </td>
                    <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-600">
                      {grn.warehouse?.name || '-'}
                    </td>
                    <td className="px-4 py-3 text-sm text-gray-600">
                      <div className="font-medium">{grn.grn_items.length} items</div>
                      <div className="text-xs text-gray-400">
                        Accepted: {grn.grn_items.reduce((sum, item) => sum + (Number(item.accepted_qty || item.accepted_quantity) || 0), 0)}
                        {grn.grn_items.some((i) => (Number(i.rejected_qty || i.rejected_quantity) || 0) > 0) && (
                          <span className="text-red-600 ml-2">
                            Rejected: {grn.grn_items.reduce((sum, item) => sum + (Number(item.rejected_qty || item.rejected_quantity) || 0), 0)}
                          </span>
                        )}
                      </div>
                      {/* Display UID count instead of individual UIDs */}
                      {grn.grn_items.some((item: any) => item.uid_count > 0) ? (
                        <div className="mt-1">
                          <span className="text-xs text-green-600 font-medium">
                            ✓ {grn.grn_items.reduce((sum: number, item: any) => sum + (item.uid_count || 0), 0)} UIDs
                          </span>
                        </div>
                      ) : (
                        <div className="text-xs text-amber-500 mt-1">
                          ⚠️ UIDs pending
                        </div>
                      )}
                    </td>
                    <td className="px-4 py-3 text-center whitespace-nowrap">
                      <span className={`inline-flex px-2 py-1 text-xs font-medium rounded-full ${getStatusColor(grn.status)}`}>
                        {grn.status}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-right whitespace-nowrap text-sm">
                      <button 
                        type="button"
                        onClick={async (e: React.MouseEvent<HTMLButtonElement>) => {
                          e.preventDefault();
                          e.stopPropagation();
                          console.log('View clicked for GRN:', grn);
                          
                          // Fetch full GRN details with items
                          try {
                            const token = localStorage.getItem('accessToken');
                            const response = await fetch(`/api/v1/purchase/grn/${grn.id}`, {
                              headers: { Authorization: `Bearer ${token}` },
                            });
                            const detailedGRN = await response.json();
                            console.log('Detailed GRN data:', detailedGRN);
                            setSelectedGRN(detailedGRN);
                          } catch (error) {
                            console.error('Error fetching GRN details:', error);
                            setSelectedGRN(grn); // Fallback to list data
                          }
                          
                          setShowViewModal(true);
                          setEditMode(false);
                        }}
                        className="text-amber-600 hover:text-amber-900 mr-3 font-medium"
                      >
                        View
                      </button>
                      {grn.status === 'COMPLETED' && (
                        <button 
                          type="button"
                          onClick={(e: React.MouseEvent<HTMLButtonElement>) => {
                            e.preventDefault();
                            e.stopPropagation();
                            console.log('UIDs clicked for GRN:', grn.id);
                            fetchGRNUIDs(grn.id);
                          }}
                          className="text-green-600 hover:text-green-900 mr-3 font-medium"
                        >
                          🔍 UIDs
                        </button>
                      )}
                      <button
                        type="button"
                        onClick={async (e: React.MouseEvent<HTMLButtonElement>) => {
                          e.preventDefault();
                          e.stopPropagation();

                          try {
                            const token = localStorage.getItem('accessToken');
                            const response = await fetch(`/api/v1/purchase/grn/${grn.id}`, {
                              headers: { Authorization: `Bearer ${token}` },
                            });
                            const detailedGRN = await response.json();
                            setSelectedGRN(detailedGRN);

                            setEditFormData({
                              invoiceNumber: detailedGRN.invoice_number || '',
                              invoiceDate: detailedGRN.invoice_date || '',
                              invoiceFileUrl: detailedGRN.invoice_file_url || '',
                              invoiceFileName: detailedGRN.invoice_file_name || '',
                              invoiceFileType: detailedGRN.invoice_file_type || '',
                              invoiceFileSize: detailedGRN.invoice_file_size || 0,
                              warehouseId: detailedGRN.warehouse?.id || '',
                              notes: detailedGRN.remarks || detailedGRN.notes || '',
                              items: (Array.isArray(detailedGRN.grn_items) ? detailedGRN.grn_items : []).map((item: any) => ({
                                id: item.id,
                                itemId: item.item_id || item.itemId || item.item?.id || '',
                                poItemId: item.po_item_id || item.poItemId || '',
                                itemCode: item.item_code || item.item?.code || '',
                                itemName: item.item_name || item.item?.name || '',
                                uom: item.uom || item.item?.uom || '',
                                orderedQuantity:
                                  Number(item.ordered_qty || item.ordered_quantity) ||
                                  Number(item.received_qty || item.received_quantity) ||
                                  0,
                                receivedQty: Number(item.received_qty || item.received_quantity) || 0,
                                acceptedQty: Number(item.accepted_qty || item.accepted_quantity) || 0,
                                rejectedQty: Number(item.rejected_qty || item.rejected_quantity) || 0,
                                unitPrice: Number(item.unit_price || item.unitPrice) || 0,
                                batchNumber: item.batch_number || '',
                                expiryDate: item.expiry_date || '',
                                notes: item.notes || '',
                              })),
                            });
                          } catch (error) {
                            console.error('Error fetching GRN details for edit:', error);
                            setSelectedGRN(grn);
                            setEditFormData({
                              invoiceNumber: grn.invoice_number || '',
                              invoiceDate: grn.invoice_date || '',
                              invoiceFileUrl: grn.invoice_file_url || '',
                              invoiceFileName: grn.invoice_file_name || '',
                              invoiceFileType: grn.invoice_file_type || '',
                              invoiceFileSize: grn.invoice_file_size || 0,
                              warehouseId: grn.warehouse?.id || '',
                              notes: grn.remarks || '',
                              items: (Array.isArray(grn.grn_items) ? grn.grn_items : []).map((item: any) => ({
                                id: item.id,
                                itemId: item.item_id || item.itemId || item.item?.id || '',
                                poItemId: item.po_item_id || item.poItemId || '',
                                itemCode: item.item_code || item.item?.code || '',
                                itemName: item.item_name || item.item?.name || '',
                                uom: item.uom || item.item?.uom || '',
                                orderedQuantity:
                                  Number(item.ordered_qty || item.ordered_quantity) ||
                                  Number(item.received_qty || item.received_quantity) ||
                                  0,
                                receivedQty: Number(item.received_qty || item.received_quantity) || 0,
                                acceptedQty: Number(item.accepted_qty || item.accepted_quantity) || 0,
                                rejectedQty: Number(item.rejected_qty || item.rejected_quantity) || 0,
                                unitPrice: Number(item.unit_price || item.unitPrice) || 0,
                                batchNumber: item.batch_number || '',
                                expiryDate: item.expiry_date || '',
                                notes: item.notes || '',
                              })),
                            });
                          }

                          setShowViewModal(true);
                          setEditMode(true);
                        }}
                        className="text-blue-600 hover:text-blue-900"
                      >
                        Edit
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
          </div>
        </div>
      </div>

      {/* Create Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg w-[95vw] max-w-7xl max-h-[92vh] overflow-y-auto">
            <div className="p-6 border-b border-gray-200">
              <h2 className="text-2xl font-bold text-gray-900">Create Goods Receipt Note</h2>
            </div>

            <div className="p-6 space-y-6">
              {/* GRN Header */}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Purchase Order *</label>
                  <select
                    value={formData.poId}
                    onChange={(e) => handlePOChange(e.target.value)}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2 focus:ring-2 focus:ring-amber-500"
                    required
                  >
                    <option value="">Select Purchase Order...</option>
                    {purchaseOrders.map(po => (
                      <option key={po.id} value={po.id}>
                        {po.po_number} - {po.vendor.name} ({new Date(po.po_date).toLocaleDateString()})
                      </option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Vendor *</label>
                  <input
                    type="text"
                    value={selectedPO ? `${selectedPO.vendor.name} (${selectedPO.vendor.code})` : ''}
                    readOnly
                    className="w-full border border-gray-300 rounded-lg px-4 py-2 bg-gray-50"
                    placeholder="Auto-filled from PO"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Receipt Date</label>
                  <input
                    type="date"
                    value={formData.receiptDate}
                    onChange={(e) => setFormData({ ...formData, receiptDate: e.target.value })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Warehouse *</label>
                  <select
                    value={formData.warehouseId}
                    onChange={(e) => setFormData({ ...formData, warehouseId: e.target.value })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2 focus:ring-2 focus:ring-amber-500"
                    required
                  >
                    <option value="">Select Warehouse...</option>
                    {warehouses.map(warehouse => (
                      <option key={warehouse.id} value={warehouse.id}>
                        {warehouse.name} ({warehouse.code}) - {warehouse.location}
                      </option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Invoice Number</label>
                  <input
                    type="text"
                    value={formData.invoiceNumber}
                    onChange={(e) => setFormData({ ...formData, invoiceNumber: e.target.value })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Invoice Date</label>
                  <input
                    type="date"
                    value={formData.invoiceDate}
                    onChange={(e) => setFormData({ ...formData, invoiceDate: e.target.value })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  />
                </div>

                <div className="col-span-2">
                  <label className="block text-sm font-medium text-gray-700 mb-2">Purchase Invoice (File)</label>
                  <input
                    type="file"
                    accept="image/png,image/jpeg,image/jpg,application/pdf"
                    onChange={(e) => {
                      const file = e.target.files?.[0];
                      if (file) handleInvoiceFileSelect(file, 'create');
                    }}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  />
                  {formData.invoiceFileName && (
                    <div className="text-xs text-gray-600 mt-1">Selected: {formData.invoiceFileName}</div>
                  )}
                </div>
              </div>

              {/* Items */}
              <div>
                <div className="flex justify-between items-center mb-4">
                  <h3 className="text-lg font-semibold text-gray-900">Items {formData.items.length > 0 && `(${formData.items.length})`}</h3>
                </div>

                {formData.items.length === 0 ? (
                  <div className="text-center py-8 border-2 border-dashed border-gray-300 rounded-lg">
                    <p className="text-gray-500">Select a Purchase Order to auto-fill items</p>
                  </div>
                ) : (
                  <div className="space-y-4">
                    {formData.items.map((item, index) => (
                      <div key={index} className="border border-gray-300 rounded-lg p-4 bg-gray-50">
                        <div className="overflow-x-auto">
                          <div className="min-w-[980px] grid grid-cols-1 md:grid-cols-[56px_2.2fr_80px_160px_90px_90px_90px_90px_120px_44px] gap-3 items-end">
                          <div>
                            <label className="text-xs text-gray-600 font-semibold whitespace-nowrap">S.No</label>
                            <div className="text-sm font-medium text-gray-900 mt-2">{index + 1}</div>
                          </div>

                          <div>
                            <label className="text-xs text-gray-600 font-semibold whitespace-nowrap">Item</label>
                            <div className="text-sm font-medium text-gray-900 mt-1 break-words">
                              <span className="whitespace-nowrap">{item.itemCode}</span>
                              <span className="text-gray-500"> - </span>
                              <span>{item.itemName}</span>
                            </div>
                            <div className="text-xs text-gray-500 mt-1">
                              Master HSN: {item.masterHsnCode || 'N/A'}
                            </div>
                            {(() => {
                              const cfg = itemUidConfigById[item.itemId];
                              const isBatched = cfg?.uid_tracking !== false && cfg?.uid_strategy === 'BATCHED';
                              const perContainer = Number(cfg?.batch_quantity ?? 0) || 0;
                              if (!isBatched || perContainer <= 0) return null;

                              const qty = Number(item.acceptedQuantity ?? 0) || 0;
                              const containers = qty > 0 ? Math.ceil(qty / perContainer) : 0;
                              const containerLabel = String(cfg?.batch_uom || 'Container');
                              const uomLabel = String(item.uom || 'UOM');

                              return (
                                <div className="text-xs text-indigo-700 mt-1">
                                  Pack: {perContainer} {uomLabel} / {containerLabel}  UIDs: {containers} {containerLabel}{containers === 1 ? '' : 's'}
                                </div>
                              );
                            })()}
                          </div>

                          <div>
                            <label className="text-xs text-gray-600 font-semibold whitespace-nowrap">UOM</label>
                            <input
                              type="text"
                              value={item.uom || ''}
                              readOnly
                              className="w-full border border-gray-300 rounded px-3 py-2 text-sm bg-white"
                              placeholder="-"
                            />
                          </div>
                          <div>
                            <label className="text-xs text-gray-600 font-semibold whitespace-nowrap">Supplier HSN</label>
                            <input
                              type="text"
                              value={item.supplierHsnCode || ''}
                              onChange={(e) => handleUpdateItem(index, 'supplierHsnCode', e.target.value)}
                              className={`w-full border rounded px-3 py-2 text-sm ${
                                item.supplierHsnCode && item.supplierHsnCode !== item.masterHsnCode
                                  ? 'border-amber-500 bg-amber-50'
                                  : 'border-gray-300'
                              }`}
                              placeholder="HSN from invoice"
                            />
                            {item.supplierHsnCode && item.supplierHsnCode !== item.masterHsnCode && (
                              <div className="text-xs text-amber-600 mt-1">⚠ HSN differs</div>
                            )}
                          </div>
                          <div>
                            <label className="text-xs text-gray-600 font-semibold whitespace-nowrap">Ordered</label>
                            <input
                              type="number"
                              value={item.orderedQuantity}
                              readOnly
                              className="w-full border border-gray-300 rounded px-3 py-2 text-sm bg-white"
                            />
                          </div>
                          <div>
                            <label className="text-xs text-gray-600 font-semibold whitespace-nowrap">Received *</label>
                            <input
                              type="number"
                              value={item.receivedQuantity}
                              onChange={(e) => handleUpdateItem(index, 'receivedQuantity', parseFloat(e.target.value))}
                              className="w-full border border-gray-300 rounded px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500"
                            />
                          </div>
                          <div>
                            <label className="text-xs text-gray-600 font-semibold whitespace-nowrap">Accepted *</label>
                            <input
                              type="number"
                              value={item.acceptedQuantity}
                              onChange={(e) => handleUpdateItem(index, 'acceptedQuantity', parseFloat(e.target.value) || 0)}
                              className="w-full border border-gray-300 rounded px-3 py-2 text-sm bg-green-50 focus:ring-2 focus:ring-green-500"
                            />
                          </div>
                          <div>
                            <label className="text-xs text-gray-600 font-semibold whitespace-nowrap">Rejected</label>
                            <input
                              type="number"
                              value={item.rejectedQuantity}
                              onChange={(e) => handleUpdateItem(index, 'rejectedQuantity', parseFloat(e.target.value))}
                              className="w-full border border-gray-300 rounded px-3 py-2 text-sm bg-red-50 focus:ring-2 focus:ring-red-500"
                            />
                          </div>
                          <div>
                            <label className="text-xs text-gray-600 font-semibold whitespace-nowrap">Batch</label>
                            <input
                              type="text"
                              value={item.batchNumber}
                              onChange={(e) => handleUpdateItem(index, 'batchNumber', e.target.value)}
                              className="w-full border border-gray-300 rounded px-3 py-2 text-sm"
                            />
                          </div>
                          <div className="flex items-end justify-end">
                            <button
                              onClick={() => handleRemoveItem(index)}
                              className="h-10 w-10 inline-flex items-center justify-center rounded border border-red-200 bg-red-50 text-red-700 hover:bg-red-100 hover:text-red-900"
                              aria-label="Remove item"
                            >
                              <span className="text-xl leading-none">×</span>
                            </button>
                          </div>
                          </div>
                        </div>
                        <div className="mt-2">
                          <input
                            type="text"
                            value={item.notes}
                            onChange={(e) => handleUpdateItem(index, 'notes', e.target.value)}
                            className="w-full border border-gray-300 rounded px-3 py-2 text-sm"
                            placeholder="Item notes..."
                          />
                        </div>

                        {(Number(item.rejectedQuantity) || 0) > 0 && (
                          <div className="mt-2">
                            <input
                              type="text"
                              value={item.rejectionReason || ''}
                              onChange={(e) => handleUpdateItem(index, 'rejectionReason', e.target.value)}
                              className="w-full border border-gray-300 rounded px-3 py-2 text-sm"
                              placeholder="Rejection remark..."
                            />
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                )}
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Notes</label>
                <textarea
                  value={formData.notes}
                  onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                  rows={3}
                  className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  placeholder="Additional notes..."
                />
              </div>
            </div>

            <div className="p-6 border-t border-gray-200 flex justify-end gap-4">
              <button
                onClick={() => {
                  setShowModal(false);
                  resetForm();
                }}
                className="px-6 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
              >
                Cancel
              </button>
              <button
                onClick={handleCreateGRN}
                className="px-6 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700"
              >
                Create GRN
              </button>
            </div>
          </div>
        </div>
      )}

      {/* View/Edit Modal */}
      {showViewModal && selectedGRN && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg w-[95vw] max-w-7xl max-h-[92vh] overflow-y-auto">
            <div className="p-6 border-b border-gray-200 flex justify-between items-center">
              <h2 className="text-2xl font-bold text-gray-900">
                {editMode ? 'Edit GRN' : 'View GRN Details'}
              </h2>
              <button
                onClick={() => {
                  setShowViewModal(false);
                  setSelectedGRN(null);
                  setEditMode(false);
                }}
                className="text-gray-500 hover:text-gray-700 text-2xl"
              >
                ×
              </button>
            </div>

            <div className="p-6 space-y-6">
              {/* GRN Header Information */}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700">GRN Number</label>
                  <p className="mt-1 text-gray-900 font-semibold">{selectedGRN.grn_number}</p>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700">Status</label>
                  <span className={`inline-block mt-1 px-3 py-1 text-xs font-semibold rounded-full ${getStatusColor(selectedGRN.status)}`}>
                    {selectedGRN.status}
                  </span>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700">PO Number</label>
                  <p className="mt-1 text-gray-900">{selectedGRN.purchase_order?.po_number || '-'}</p>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700">Vendor</label>
                  <p className="mt-1 text-gray-900">{selectedGRN.vendor?.name} ({selectedGRN.vendor?.code})</p>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700">Receipt Date</label>
                  <p className="mt-1 text-gray-900">{new Date(selectedGRN.grn_date).toLocaleDateString()}</p>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700">Warehouse</label>
                  {editMode ? (
                    <select
                      value={editFormData.warehouseId}
                      onChange={(e) => setEditFormData({ ...editFormData, warehouseId: e.target.value })}
                      className="mt-1 w-full border border-gray-300 rounded-lg px-3 py-2"
                    >
                      <option value="">Select Warehouse</option>
                      {warehouses.map(wh => (
                        <option key={wh.id} value={wh.id}>{wh.name}</option>
                      ))}
                    </select>
                  ) : (
                    <p className="mt-1 text-gray-900">{selectedGRN.warehouse?.name || '-'}</p>
                  )}
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700">Invoice Number</label>
                  {editMode ? (
                    <input
                      type="text"
                      value={editFormData.invoiceNumber}
                      onChange={(e) => setEditFormData({ ...editFormData, invoiceNumber: e.target.value })}
                      className="mt-1 w-full border border-gray-300 rounded-lg px-3 py-2"
                      placeholder="Enter invoice number"
                    />
                  ) : (
                    <p className="mt-1 text-gray-900">{selectedGRN.invoice_number || '-'}</p>
                  )}
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700">Invoice Date</label>
                  {editMode ? (
                    <input
                      type="date"
                      value={editFormData.invoiceDate}
                      onChange={(e) => setEditFormData({ ...editFormData, invoiceDate: e.target.value })}
                      className="mt-1 w-full border border-gray-300 rounded-lg px-3 py-2"
                    />
                  ) : (
                    <p className="mt-1 text-gray-900">{selectedGRN.invoice_date ? new Date(selectedGRN.invoice_date).toLocaleDateString() : '-'}</p>
                  )}
                </div>

                <div className="col-span-2">
                  <label className="block text-sm font-medium text-gray-700">Purchase Invoice (File)</label>
                  {editMode ? (
                    <>
                      <input
                        type="file"
                        accept="image/png,image/jpeg,image/jpg,application/pdf"
                        onChange={(e) => {
                          const file = e.target.files?.[0];
                          if (file) handleInvoiceFileSelect(file, 'edit');
                        }}
                        className="mt-1 w-full border border-gray-300 rounded-lg px-3 py-2"
                      />
                      {editFormData.invoiceFileName && (
                        <div className="text-xs text-gray-600 mt-1">Selected: {editFormData.invoiceFileName}</div>
                      )}
                    </>
                  ) : selectedGRN.invoice_file_url ? (
                    <button
                      onClick={() => handleViewInvoice(selectedGRN.invoice_file_url!, selectedGRN.invoice_file_name)}
                      className="mt-1 inline-block text-blue-600 hover:text-blue-800 underline cursor-pointer"
                    >
                      View Invoice
                    </button>
                  ) : (
                    <p className="mt-1 text-gray-900">-</p>
                  )}
                </div>
              </div>

              {/* Financial Summary - Only show if financial data exists */}
              {(selectedGRN.gross_amount || selectedGRN.debit_note_amount || selectedGRN.net_payable_amount) && (
                <div className="bg-blue-50 border-2 border-blue-200 rounded-lg p-4">
                  <h3 className="text-lg font-bold text-blue-900 mb-3">💰 Financial Summary</h3>
                  <div className="grid grid-cols-3 gap-4">
                    <div className="bg-white rounded-lg p-3 border border-blue-200">
                      <div className="text-xs text-gray-600 mb-1">Gross Amount</div>
                      <div className="text-xl font-bold text-gray-900">
                        ₹{(selectedGRN.gross_amount || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                      </div>
                    </div>
                    <div className="bg-white rounded-lg p-3 border border-red-200">
                      <div className="text-xs text-gray-600 mb-1">Debit Notes</div>
                      <div className="text-xl font-bold text-red-600">
                        -₹{(selectedGRN.debit_note_amount || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                      </div>
                    </div>
                    <div className="bg-white rounded-lg p-3 border border-green-200">
                      <div className="text-xs text-gray-600 mb-1">Net Payable</div>
                      <div className="text-xl font-bold text-green-600">
                        ₹{(selectedGRN.net_payable_amount || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                      </div>
                    </div>
                  </div>
                </div>
              )}

              {/* Items Table */}
              <div>
                <h3 className="text-lg font-semibold text-gray-900 mb-4">Items</h3>
                <table className="min-w-full border border-gray-200">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-4 py-2 text-center text-xs font-medium text-gray-700">S.No</th>
                      <th className="px-4 py-2 text-left text-xs font-medium text-gray-700">Item Code</th>
                      <th className="px-4 py-2 text-left text-xs font-medium text-gray-700">Item Name</th>
                      <th className="px-4 py-2 text-center text-xs font-medium text-gray-700">UOM</th>
                      <th className="px-4 py-2 text-right text-xs font-medium text-gray-700">Received</th>
                      <th className="px-4 py-2 text-right text-xs font-medium text-gray-700">Accepted</th>
                      <th className="px-4 py-2 text-right text-xs font-medium text-gray-700">Rejected</th>
                      <th className="px-4 py-2 text-left text-xs font-medium text-gray-700">Batch Number</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-200">
                    {editMode ? (
                      editFormData.items.map((item, idx) => (
                        <tr key={idx}>
                          <td className="px-4 py-2 text-sm text-gray-700 text-center">{idx + 1}</td>
                          <td className="px-4 py-2 text-sm text-gray-900">{item.itemCode}</td>
                          <td className="px-4 py-2 text-sm text-gray-900">{item.itemName}</td>
                          <td className="px-4 py-2 text-sm text-gray-900 text-center">{item.uom || '-'}</td>
                          <td className="px-4 py-2 text-sm text-gray-900 text-right">
                            <input
                              type="number"
                              value={item.receivedQty}
                              onChange={(e) => {
                                const newItems = [...editFormData.items];
                                newItems[idx].receivedQty = Number(e.target.value);
                                setEditFormData({ ...editFormData, items: newItems });
                              }}
                              className="w-20 border border-gray-300 rounded px-2 py-1 text-right"
                            />
                          </td>
                          <td className="px-4 py-2 text-sm text-green-600 text-right font-semibold">
                            <input
                              type="number"
                              value={item.acceptedQty}
                              onChange={(e) => {
                                const newItems = [...editFormData.items];
                                newItems[idx].acceptedQty = Number(e.target.value);
                                setEditFormData({ ...editFormData, items: newItems });
                              }}
                              className="w-20 border border-gray-300 rounded px-2 py-1 text-right"
                            />
                          </td>
                          <td className="px-4 py-2 text-sm text-red-600 text-right font-semibold">
                            <input
                              type="number"
                              value={item.rejectedQty}
                              onChange={(e) => {
                                const newItems = [...editFormData.items];
                                newItems[idx].rejectedQty = Number(e.target.value);
                                setEditFormData({ ...editFormData, items: newItems });
                              }}
                              className="w-20 border border-gray-300 rounded px-2 py-1 text-right"
                            />
                          </td>
                          <td className="px-4 py-2 text-sm">
                            <input
                              type="text"
                              value={item.batchNumber}
                              onChange={(e) => {
                                const newItems = [...editFormData.items];
                                newItems[idx].batchNumber = e.target.value;
                                setEditFormData({ ...editFormData, items: newItems });
                              }}
                              className="w-32 border border-gray-300 rounded px-2 py-1"
                              placeholder="Batch number"
                            />
                          </td>
                        </tr>
                      ))
                    ) : (
                      selectedGRN.grn_items.map((item, idx) => (
                        <tr key={idx}>
                          <td className="px-4 py-2 text-sm text-gray-700 text-center">{idx + 1}</td>
                          <td className="px-4 py-2 text-sm text-gray-900">{item.item_code || item.item?.code || '-'}</td>
                          <td className="px-4 py-2 text-sm text-gray-900">{item.item_name || item.item?.name || '-'}</td>
                          <td className="px-4 py-2 text-sm text-gray-900 text-center">{(item as any).uom || (item.item as any)?.uom || '-'}</td>
                          <td className="px-4 py-2 text-sm text-gray-900 text-right">{Number(item.received_qty || item.received_quantity) || 0}</td>
                          <td className="px-4 py-2 text-sm text-green-600 text-right font-semibold">{Number(item.accepted_qty || item.accepted_quantity) || 0}</td>
                          <td className="px-4 py-2 text-sm text-red-600 text-right font-semibold">{Number(item.rejected_qty || item.rejected_quantity) || 0}</td>
                          <td className="px-4 py-2 text-sm">
                            {item.batch_number && <div className="text-gray-600">Batch: {item.batch_number}</div>}
                            {item.uid && <div className="font-mono text-blue-600 text-xs">{item.uid}</div>}
                            {!item.batch_number && !item.uid && <span className="text-gray-400">-</span>}
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>

              {/* Rejections Section - Only show if there are rejections */}
              {selectedGRN.grn_items?.some((item: any) => (item.rejected_qty || 0) > 0) && (
                <div className="bg-red-50 border-2 border-red-200 rounded-lg p-4">
                  <h3 className="text-lg font-bold text-red-900 mb-3">❌ Rejected Items</h3>
                  <div className="space-y-3">
                    {selectedGRN.grn_items
                      .filter((item: any) => (item.rejected_qty || 0) > 0)
                      .map((item: any, idx: number) => {
                        const itemName = item.item_name || item.item?.name || 'Unknown Item';
                        const itemCode = item.item_code || item.item?.code || 'N/A';
                        return (
                          <div key={idx} className="bg-white border border-red-200 rounded-lg p-3">
                            <div className="flex justify-between items-start mb-2">
                              <div>
                                <div className="font-semibold text-gray-900">
                                  {itemName} ({itemCode})
                                </div>
                                <div className="text-sm text-gray-600 mt-1">
                                  Rejected Qty: <span className="font-bold text-red-600">{item.rejected_qty}</span>
                                  {item.unit_price && (
                                    <span className="ml-3">
                                      Amount:{' '}
                                      <span className="font-bold text-red-600">
                                        ₹{(item.rejection_amount || (item.rejected_qty * item.unit_price)).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                                      </span>
                                    </span>
                                  )}
                                </div>
                              </div>

                              {item.return_status && item.return_status !== 'NONE' && (
                                <span
                                  className={`px-2 py-1 rounded text-xs font-bold ${
                                    item.return_status === 'PENDING_RETURN'
                                      ? 'bg-yellow-100 text-yellow-800'
                                      : item.return_status === 'RETURNED'
                                      ? 'bg-green-100 text-green-800'
                                      : item.return_status === 'DESTROYED'
                                      ? 'bg-gray-100 text-gray-800'
                                      : 'bg-blue-100 text-blue-800'
                                  }`}
                                >
                                  {item.return_status.replace('_', ' ')}
                                </span>
                              )}
                            </div>

                            {item.rejection_reason && (
                              <div className="text-sm text-gray-700 bg-red-50 border-l-4 border-red-400 p-2 rounded">
                                <span className="font-medium">Reason:</span> {item.rejection_reason}
                              </div>
                            )}
                            {item.qc_notes && (
                              <div className="text-sm text-gray-600 mt-1">
                                <span className="font-medium">QC Notes:</span> {item.qc_notes}
                              </div>
                            )}
                            {item.debit_note_id && (
                              <div className="text-sm text-blue-600 mt-2 font-medium">📄 Debit Note Created</div>
                            )}
                          </div>
                        );
                      })}
                  </div>
                </div>
              )}
            </div>

            {/* Footer with Action Buttons */}
            <div className="p-6 border-t border-gray-200 flex justify-between items-center">
              <div className="flex gap-3">
                {editMode ? (
                  <button
                    onClick={handleUpdateGRN}
                    className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
                  >
                    💾 Save Changes
                  </button>
                ) : (
                  <>
                    <button
                      onClick={() => {
                        // Initialize QC form data with GRN items
                        const qcData = selectedGRN.grn_items.map((item: any) => {
                          const receivedQty = item.received_qty || item.received_quantity || 0;
                          const acceptedQty = item.accepted_qty || item.accepted_quantity || receivedQty;
                          const rejectedQty = item.rejected_qty || item.rejected_quantity || 0;
                          return {
                            itemId: item.id,
                            itemCode: item.item_code || item.item?.code,
                            itemName: item.item_name || item.item?.name,
                            receivedQty: receivedQty,
                            acceptedQty: acceptedQty,
                            rejectedQty: rejectedQty,
                            qcNotes: item.qc_notes || '',
                            rejectionReason: item.rejection_reason || '',
                            qcFileUrl: item.qc_file_url || '',
                            qcFileName: item.qc_file_name || '',
                            qcFileType: item.qc_file_type || '',
                            qcFileSize: item.qc_file_size || 0,
                          };
                        });
                        setQcFormData(qcData);
                        setShowQCModal(true);
                      }}
                      disabled={selectedGRN.status !== 'DRAFT'}
                      className={`px-6 py-2 text-white rounded-lg ${
                        selectedGRN.status === 'DRAFT'
                          ? 'bg-blue-600 hover:bg-blue-700 cursor-pointer' 
                          : 'bg-gray-400 cursor-not-allowed'
                      }`}
                      title={
                        selectedGRN.status !== 'DRAFT'
                          ? 'QC can be performed only in DRAFT'
                          : selectedGRN.qc_completed
                            ? 'QC already marked completed (you can still review/update)'
                            : 'Perform QC inspection'
                      }
                    >
                      🔍 QC Accept
                    </button>
                    <button
                      onClick={async () => {
                        console.log('Approve button clicked!');
                        console.log('GRN ID:', selectedGRN.id);
                        console.log('GRN Status:', selectedGRN.status);
                        try {
                          const token = localStorage.getItem('accessToken');
                          console.log('Token exists:', !!token);
                          const response = await fetch(`/api/v1/purchase/grn/${selectedGRN.id}/status`, {
                            method: 'POST',
                            headers: {
                              'Content-Type': 'application/json',
                              Authorization: `Bearer ${token}`,
                            },
                            body: JSON.stringify({ status: 'APPROVED' }),
                          });

                          console.log('Response status:', response.status);
                          const responseData = await response.json();
                          console.log('Response data:', responseData);
                          
                          if (response.ok) {
                            setAlertMessage({ type: 'success', message: 'GRN approved successfully! UIDs generated.' });
                            setShowViewModal(false);
                            fetchGRNs();
                          } else {
                            console.error('Error response:', responseData);
                            setAlertMessage({ type: 'error', message: `Failed to approve GRN: ${responseData.message}` });
                          }
                        } catch (error) {
                          console.error('Catch error:', error);
                          setAlertMessage({ type: 'error', message: 'Failed to approve GRN. Please try again.' });
                        }
                      }}
                      disabled={selectedGRN.status !== 'DRAFT'}
                      className={`px-6 py-2 text-white rounded-lg ${
                        selectedGRN.status === 'DRAFT' 
                          ? 'bg-green-600 hover:bg-green-700 cursor-pointer' 
                          : 'bg-gray-400 cursor-not-allowed'
                      }`}
                    >
                      ✓ Approve
                    </button>
                    <button
                      onClick={async () => {
                        console.log('Reject button clicked!');
                        try {
                          const token = localStorage.getItem('accessToken');
                          const response = await fetch(`/api/v1/purchase/grn/${selectedGRN.id}/status`, {
                            method: 'POST',
                            headers: {
                              'Content-Type': 'application/json',
                              Authorization: `Bearer ${token}`,
                            },
                            body: JSON.stringify({ status: 'REJECTED' }),
                          });

                          if (response.ok) {
                            setAlertMessage({ type: 'success', message: 'GRN rejected successfully!' });
                            setShowViewModal(false);
                            fetchGRNs();
                          } else {
                            const errorData = await response.json();
                            setAlertMessage({ type: 'error', message: `Failed to reject GRN: ${errorData.message}` });
                          }
                        } catch (error) {
                          setAlertMessage({ type: 'error', message: 'Failed to reject GRN. Please try again.' });
                        }
                      }}
                      disabled={selectedGRN.status !== 'DRAFT'}
                      className={`px-6 py-2 text-white rounded-lg ${
                        selectedGRN.status === 'DRAFT' 
                          ? 'bg-red-600 hover:bg-red-700 cursor-pointer' 
                          : 'bg-gray-400 cursor-not-allowed'
                      }`}
                    >
                      ✗ Reject
                    </button>
                  </>
                )}
              </div>
              <button
                onClick={() => {
                  setShowViewModal(false);
                  setSelectedGRN(null);
                  setEditMode(false);
                }}
                className="px-6 py-2 bg-gray-200 text-gray-800 rounded-lg hover:bg-gray-300"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* UIDs Modal */}
      {showUIDsModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg max-w-4xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b border-gray-200 flex justify-between items-center">
              <h2 className="text-2xl font-bold text-gray-900">Generated UIDs</h2>
              <button
                onClick={() => setShowUIDsModal(false)}
                className="text-gray-500 hover:text-gray-700 text-2xl"
              >
                ×
              </button>
            </div>
            <div className="p-6">
              {selectedGRNUIDs.length === 0 ? (
                <p className="text-center text-gray-500 py-8">No UIDs found</p>
              ) : (
                <div className="grid gap-3">
                  {selectedGRNUIDs.map((uidRecord) => (
                    <div
                      key={uidRecord.uid}
                      className="border border-gray-200 rounded-lg p-4 hover:bg-blue-50 cursor-pointer transition-colors"
                      onClick={() => fetchPurchaseTrail(uidRecord.uid)}
                    >
                      <div className="flex justify-between items-start">
                        <div className="flex-1">
                          <div className="font-mono text-sm font-semibold text-blue-600">
                            {uidRecord.uid}
                          </div>
                          {uidRecord.item && (
                            <div className="text-sm font-medium text-gray-900 mt-1">
                              {uidRecord.item.name} ({uidRecord.item.code})
                            </div>
                          )}
                          <div className="text-sm text-gray-600 mt-1">
                            Type: {uidRecord.entity_type} | Status: {uidRecord.status}
                          </div>
                          {uidRecord.batch_number && (
                            <div className="text-xs text-gray-500 mt-1">
                              Batch: {uidRecord.batch_number}
                            </div>
                          )}
                          <div className="text-xs text-gray-500 mt-1">
                            Location: {uidRecord.location || 'N/A'}
                          </div>
                        </div>
                        <div className="text-xs text-gray-400">
                          {formatDate(uidRecord.created_at)}
                        </div>
                      </div>
                      <div className="mt-2 text-xs text-blue-600">
                        Click to view purchase trail →
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Purchase Trail Modal - Same as BOM page */}
      {showTrailModal && purchaseTrail && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg max-w-4xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b border-gray-200">
              <div className="flex justify-between items-start">
                <div>
                  <h2 className="text-2xl font-bold text-gray-900">Purchase Trail</h2>
                  <p className="text-gray-600 mt-1">UID: {purchaseTrail.uid}</p>
                </div>
                <button onClick={() => setShowTrailModal(false)} className="text-2xl text-gray-500">×</button>
              </div>
            </div>
            <div className="p-6 space-y-6">
              <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                <h3 className="font-semibold text-blue-900 mb-2">📦 Item</h3>
                <div className="text-sm"><span className="text-gray-600">Code:</span> {purchaseTrail.item.code} | <span className="text-gray-600">Name:</span> {purchaseTrail.item.name}</div>
              </div>
              {purchaseTrail.supplier && (
                <div className="bg-green-50 border border-green-200 rounded-lg p-4">
                  <h3 className="font-semibold text-green-900 mb-2">🏭 Supplier</h3>
                  <div className="text-sm">{purchaseTrail.supplier.name} - {purchaseTrail.supplier.contact_person}</div>
                </div>
              )}
              {purchaseTrail.purchase_order && (
                <div className="bg-purple-50 border border-purple-200 rounded-lg p-4">
                  <h3 className="font-semibold text-purple-900 mb-2">📋 PO</h3>
                  <div className="text-sm">{purchaseTrail.purchase_order.po_number} | {formatDate(purchaseTrail.purchase_order.order_date)} | ₹{purchaseTrail.purchase_order.total_amount.toLocaleString()}</div>
                </div>
              )}
              {purchaseTrail.grn && (
                <div className="bg-amber-50 border border-amber-200 rounded-lg p-4">
                  <h3 className="font-semibold text-amber-900 mb-2">📥 GRN</h3>
                  <div className="text-sm">{purchaseTrail.grn.grn_number} | {formatDate(purchaseTrail.grn.received_date)} | Qty: {purchaseTrail.grn.received_quantity}</div>
                </div>
              )}
              {purchaseTrail.lifecycle?.length > 0 && (
                <div className="bg-gray-50 border border-gray-200 rounded-lg p-4">
                  <h3 className="font-semibold text-gray-900 mb-4">🕐 Timeline</h3>
                  <div className="space-y-3">
                    {purchaseTrail.lifecycle.map((event, i) => (
                      <div key={i} className="flex gap-3">
                        <div className="w-2 h-2 bg-amber-600 rounded-full mt-1"></div>
                        <div className="flex-1">
                          <p className="font-medium text-sm">{event.stage}</p>
                          <p className="text-xs text-gray-600">{event.location} - {event.reference}</p>
                          <p className="text-xs text-gray-400">{formatDate(event.timestamp)}</p>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Alert Popup */}
      {alertMessage && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-xl max-w-md w-full mx-4 p-6">
            <div className="flex items-start">
              <div className={`flex-shrink-0 ${
                alertMessage.type === 'success' ? 'text-green-500' :
                alertMessage.type === 'error' ? 'text-red-500' :
                'text-blue-500'
              }`}>
                {alertMessage.type === 'success' && (
                  <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                )}
                {alertMessage.type === 'error' && (
                  <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2m7-2a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                )}
                {alertMessage.type === 'info' && (
                  <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                )}
              </div>
              <div className="ml-3 flex-1">
                <h3 className={`text-sm font-medium ${
                  alertMessage.type === 'success' ? 'text-green-800' :
                  alertMessage.type === 'error' ? 'text-red-800' :
                  'text-blue-800'
                }`}>
                  {alertMessage.type === 'success' ? 'Success' :
                   alertMessage.type === 'error' ? 'Error' :
                   'Information'}
                </h3>
                <div className="mt-2 text-sm text-gray-700">
                  {alertMessage.message}
                </div>
              </div>
            </div>
            <div className="mt-4">
              <button
                onClick={() => setAlertMessage(null)}
                className={`w-full px-4 py-2 text-sm font-medium text-white rounded-md ${
                  alertMessage.type === 'success' ? 'bg-green-600 hover:bg-green-700' :
                  alertMessage.type === 'error' ? 'bg-red-600 hover:bg-red-700' :
                  'bg-blue-600 hover:bg-blue-700'
                }`}
              >
                OK
              </button>
            </div>
          </div>
        </div>
      )}

      {/* QC Accept Modal */}
      {showQCModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-hidden">
            <div className="p-6 border-b border-gray-200 flex justify-between items-center bg-blue-50">
              <h2 className="text-2xl font-bold text-gray-900">🔍 QC Inspection</h2>
              <button
                onClick={() => setShowQCModal(false)}
                className="text-gray-500 hover:text-gray-700"
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>

            <div className="p-6 overflow-y-auto max-h-[calc(90vh-200px)]">
              <div className="space-y-4">
                {qcFormData.map((item, index) => (
                  <div key={index} className="border border-gray-200 rounded-lg p-4 bg-gray-50">
                    <div className="flex justify-between items-start mb-3">
                      <div>
                        <div className="font-semibold text-gray-900">{item.itemName}</div>
                        <div className="text-sm text-gray-600">Code: {item.itemCode}</div>
                      </div>
                      <div className="text-sm text-gray-600">
                        Received: <span className="font-semibold">{item.receivedQty}</span>
                      </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">
                          Accepted Quantity *
                        </label>
                        <input
                          type="number"
                          min="0"
                          max={item.receivedQty}
                          value={item.acceptedQty}
                          onChange={(e) => {
                            const accepted = parseFloat(e.target.value) || 0;
                            const rejected = item.receivedQty - accepted;
                            const newData = [...qcFormData];
                            newData[index] = {
                              ...item,
                              acceptedQty: accepted,
                              rejectedQty: Math.max(0, rejected)
                            };
                            setQcFormData(newData);
                          }}
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                        />
                      </div>

                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">
                          Rejected Quantity
                        </label>
                        <input
                          type="number"
                          value={item.rejectedQty}
                          readOnly
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg bg-gray-100"
                        />
                      </div>
                    </div>

                    {item.rejectedQty > 0 && (
                      <div className="mt-3">
                        <label className="block text-sm font-medium text-gray-700 mb-1">
                          Rejection Reason *
                        </label>
                        <input
                          type="text"
                          value={item.rejectionReason}
                          onChange={(e) => {
                            const newData = [...qcFormData];
                            newData[index] = { ...item, rejectionReason: e.target.value };
                            setQcFormData(newData);
                          }}
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                          placeholder="Enter reason for rejection"
                        />
                      </div>
                    )}

                    <div className="mt-3">
                      <label className="block text-sm font-medium text-gray-700 mb-1">
                        QC Notes
                      </label>
                      <textarea
                        value={item.qcNotes}
                        onChange={(e) => {
                          const newData = [...qcFormData];
                          newData[index] = { ...item, qcNotes: e.target.value };
                          setQcFormData(newData);
                        }}
                        rows={2}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                        placeholder="Optional inspection notes"
                      />
                    </div>

                    <div className="mt-3">
                      <label className="block text-sm font-medium text-gray-700 mb-1">
                        Upload QC Photo / Report (PNG, JPG, PDF)
                      </label>
                      <input
                        type="file"
                        accept="image/png,image/jpeg,image/jpg,application/pdf"
                        onChange={(e) => {
                          const file = e.target.files?.[0];
                          if (file) handleQCFileSelect(file, index);
                        }}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                      {(item.qcFileName || item.qcFileUrl) && (
                        <div className="text-xs text-gray-600 mt-1">
                          Selected: {item.qcFileName || 'QC Attachment'}
                          {item.qcFileUrl && (
                            <button
                              type="button"
                              onClick={() => handleViewInvoice(item.qcFileUrl!, item.qcFileName)}
                              className="ml-2 text-blue-600 hover:text-blue-800 underline"
                            >
                              View
                            </button>
                          )}
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="p-6 border-t border-gray-200 flex justify-end gap-3">
              <button
                onClick={() => setShowQCModal(false)}
                className="px-6 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50"
              >
                Cancel
              </button>
              <button
                onClick={async () => {
                  try {
                    // Validate
                    const hasRejectedWithoutReason = qcFormData.some(
                      item => item.rejectedQty > 0 && !item.rejectionReason?.trim()
                    );
                    
                    if (hasRejectedWithoutReason) {
                      setAlertMessage({ 
                        type: 'error', 
                        message: 'Please provide rejection reason for all rejected items' 
                      });
                      return;
                    }

                    if (!selectedGRN) return;

                    const token = localStorage.getItem('accessToken');
                    const response = await fetch(
                      `/api/v1/purchase/grn/${selectedGRN.id}/qc-accept`,
                      {
                        method: 'POST',
                        headers: {
                          'Content-Type': 'application/json',
                          Authorization: `Bearer ${token}`,
                        },
                        body: JSON.stringify({ items: qcFormData }),
                      }
                    );

                    if (response.ok) {
                      setAlertMessage({ type: 'success', message: 'QC inspection completed successfully!' });
                      setShowQCModal(false);
                      fetchGRNs();
                      setShowViewModal(false);
                    } else {
                      const errorData = await response.json();
                      setAlertMessage({ 
                        type: 'error', 
                        message: `QC inspection failed: ${errorData.message || 'Unknown error'}` 
                      });
                    }
                  } catch (error) {
                    console.error('QC accept error:', error);
                    setAlertMessage({ type: 'error', message: 'Failed to complete QC inspection' });
                  }
                }}
                className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
              >
                ✓ Complete QC Inspection
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default function GRNPage() {
  return <GRNContent />;
}

'use client';

import { useState, useEffect, Suspense } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { apiClient } from '../../../../../lib/api-client';
import DrawingManager from '../../../../components/DrawingManager';
import SearchableSelect from '../../../../components/SearchableSelect';
import { useSelection } from '../../../../hooks/useSelection';
import DuplicateWarning, { useDuplicateDetection } from '../../../../components/DuplicateWarning';

interface PurchaseOrder {
  id: string;
  po_number: string;
  pr_id?: string;
  pr?: {
    id: string;
    pr_number: string;
  } | null;
  vendor: {
    name: string;
    contact_person: string;
  };
  po_date: string;
  delivery_date: string;
  status: string;
  total_amount: number;
  remarks?: string;
  payment_status?: string;
  payment_notes?: string;
  customs_duty?: number;
  other_charges?: number;
  updated_by?: string;
  edit_count?: number;
  last_edited_at?: string;
  is_partial_po?: boolean;
  purchase_order_items: Array<{
    item: { name: string; code?: string; uom?: string };
    quantity: number;
    uom?: string;
    serial_no?: number;
    pr_item_id?: string;
  }>;
}

function PurchaseOrdersContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const prId = searchParams?.get('prId');

  const [purchaseRequisitions, setPurchaseRequisitions] = useState<
    Array<{ id: string; pr_number: string; department?: string; status?: string }>
  >([]);
  const [loadingPrList, setLoadingPrList] = useState(false);
  
  const [orders, setOrders] = useState<PurchaseOrder[]>([]);
  const [vendors, setVendors] = useState<Array<{ id: string; name: string; contact_person: string }>>([]);
  const [items, setItems] = useState<Array<{ 
    id: string; 
    code: string; 
    name: string; 
    uom: string; 
    standard_cost?: number; 
    selling_price?: number;
    drawing_required?: string;
  }>>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [showViewModal, setShowViewModal] = useState(false);
  const [selectedPO, setSelectedPO] = useState<PurchaseOrder | null>(null);
  const [showPOEmailPreview, setShowPOEmailPreview] = useState(false);
  const [poEmailPreviewLoading, setPoEmailPreviewLoading] = useState(false);
  const [poEmailSending, setPoEmailSending] = useState(false);
  const [poEmailPreview, setPoEmailPreview] = useState<any>(null);
  const [poEmailTo, setPoEmailTo] = useState('');
  const [poEmailSubject, setPoEmailSubject] = useState('');
  const [poEmailMessage, setPoEmailMessage] = useState('');
  const [editingPOId, setEditingPOId] = useState<string | null>(null);
  const [editingMode, setEditingMode] = useState<'create' | 'edit' | 'tracking'>('create');
  const [filterStatus, setFilterStatus] = useState('ALL');
  const [searchTerm, setSearchTerm] = useState('');
  const [loadingPR, setLoadingPR] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [showDrawingManager, setShowDrawingManager] = useState(false);
  const [selectedItemForDrawing, setSelectedItemForDrawing] = useState<{ id: string; code: string; name: string; mandatory: boolean } | null>(null);
  const [pendingItemIndex, setPendingItemIndex] = useState<number | null>(null);
  const [alertMessage, setAlertMessage] = useState<{ type: 'success' | 'error' | 'info'; message: string } | null>(null);
  const [currentPrId, setCurrentPrId] = useState<string | null>(null);
  const { duplicateState, checkDuplicates, handleProceed, handleCancel } = useDuplicateDetection();
  type PriceHistoryRecord = { po_number: string; po_date: string; unit_price: number; quantity: number; po_status: string };
  const [priceHistory, setPriceHistory] = useState<Record<string, PriceHistoryRecord[]>>({});
  const [stockInfo, setStockInfo] = useState<Record<string, { total_quantity: number; available_quantity: number; allocated_quantity: number }>>({});
  const [hoveredItem, setHoveredItem] = useState<number | null>(null);

  const orderSelection = useSelection(orders);

  // Form state
  const [formData, setFormData] = useState({
    vendorId: '',
    orderDate: new Date().toISOString().split('T')[0],
    expectedDelivery: '',
    paymentTerms: 'NET_30',
    paymentStatus: 'UNPAID',
    paymentNotes: '',
    deliveryAddress: '',
    notes: '',
    customsDuty: 0,
    otherCharges: 0,
    trackingNumber: '',
    shippedDate: '',
    estimatedDeliveryDate: '',
    carrierName: '',
    trackingUrl: '',
    deliveryStatus: 'PENDING',
    items: [] as Array<{
      prItemId?: string;
      itemId: string;
      itemCode: string;
      itemName: string;
      uom?: string;
      vendorId: string;
      quantity: number;
      unitPrice: number;
      taxRate: number;
      totalPrice: number;
      specifications: string;
      paymentTerms?: string;
      deliveryTerms?: string;
    }>,
  });

  useEffect(() => {
    fetchOrders();
    fetchVendors();
    // Items are lazy-loaded when modal opens
    // Check if PR ID is provided in URL
    if (prId) {
      loadPRData(prId);
    }
  }, [filterStatus, prId]);

  useEffect(() => {
    if (!showModal) return;
    if (editingMode !== 'create') return;
    fetchPurchaseRequisitions();
  }, [showModal, editingMode]);

  const fetchPurchaseRequisitions = async () => {
    try {
      setLoadingPrList(true);
      const data = await apiClient.get(`/purchase/requisitions?status=APPROVED`);
      const list = Array.isArray(data) ? data : [];
      setPurchaseRequisitions(
        list
          .map((raw: any) => ({
            id: String(raw?.id || ''),
            pr_number: String(raw?.pr_number || raw?.prNumber || ''),
            department: raw?.department ? String(raw.department) : undefined,
            status: raw?.status ? String(raw.status) : undefined,
          }))
          .filter((x: any) => x.id && x.pr_number),
      );
    } catch (error) {
      console.error('Error fetching purchase requisitions:', error);
      setPurchaseRequisitions([]);
    } finally {
      setLoadingPrList(false);
    }
  };

  // Ensure item master data is loaded whenever the create/edit modal is open.
  // This prevents the Product dropdown from appearing empty in some edit flows.
  useEffect(() => {
    if (!showModal) return;
    if (items.length > 0) return;
    fetchItems();
  }, [showModal, items.length]);

  // Backfill missing itemId (and itemName) from itemCode once items master data loads.
  // Some PO payloads provide only item_code/item_name; SearchableSelect needs itemId.
  useEffect(() => {
    if (items.length === 0) return;

    setFormData((prev) => {
      const currentItems = Array.isArray(prev.items) ? prev.items : [];
      if (currentItems.length === 0) return prev;

      let changed = false;
      const patched = currentItems.map((row) => {
        if (String(row?.itemId || '').trim()) return row;
        const code = String(row?.itemCode || '').trim();
        if (!code) return row;
        const match = items.find((i) => String(i.code || '').trim() === code);
        if (!match?.id) return row;
        changed = true;
        return {
          ...row,
          itemId: String(match.id),
          itemCode: row.itemCode || String(match.code || ''),
          itemName: row.itemName || String(match.name || ''),
        };
      });

      return changed ? { ...prev, items: patched } : prev;
    });
  }, [items]);

  // Prefetch last purchase price for any item+vendor pairs shown in the create/edit modal
  useEffect(() => {
    const pairs = new Set(
      (formData.items || [])
        .map((it) => {
          const rawItemId = String((it as any)?.itemId || '').trim();
          const code = String((it as any)?.itemCode || '').trim();
          const resolvedItemId =
            rawItemId ||
            String(items.find((i) => String(i.code).trim() === code)?.id || '').trim();
          const vendorId = String((it as any)?.vendorId || formData.vendorId || '').trim();
          return resolvedItemId && vendorId ? `${resolvedItemId}-${vendorId}` : '';
        })
        .filter(Boolean),
    );

    pairs.forEach((key) => {
      if (priceHistory[key] !== undefined) return;
      const [itemId, vendorId] = key.split('-');
      if (itemId && vendorId) {
        fetchPriceHistory(itemId, vendorId);
      }
    });
  }, [formData.items, formData.vendorId, items, priceHistory]);

  // Prefetch last purchase prices for the approval/details (view) modal.
  // This handles the case where vendorId/itemId can only be resolved after
  // vendors/items master data finishes loading.
  useEffect(() => {
    if (!showViewModal || !selectedPO) return;

    const vendorId = resolveVendorIdFromPO(selectedPO);
    if (!vendorId) return;

    const poItems = Array.isArray((selectedPO as any)?.purchase_order_items)
      ? (selectedPO as any).purchase_order_items
      : [];

    const itemIds = poItems.map((it: any) => resolveItemIdFromPOLine(it)).filter(Boolean);
    itemIds.forEach((itemId: string) => {
      const key = `${itemId}-${vendorId}`;
      if (priceHistory[key] !== undefined) return;
      fetchPriceHistory(itemId, vendorId);
    });
  }, [showViewModal, selectedPO, vendors, items, priceHistory]);

  const fetchVendors = async () => {
    try {
      const token = localStorage.getItem('accessToken');
      const response = await fetch('/api/v1/purchase/vendors', {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json();
      setVendors(data || []);
    } catch (error) {
      console.error('Error fetching vendors:', error);
    }
  };

  const fetchItems = async () => {
    try {
      const token = localStorage.getItem('accessToken');
      const response = await fetch('/api/v1/inventory/items', {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json();
      setItems(data || []);
    } catch (error) {
      console.error('Error fetching items:', error);
    }
  };

  const fetchPriceHistory = async (itemId: string, vendorId: string): Promise<PriceHistoryRecord[]> => {
    const key = `${itemId}-${vendorId}`;
    if (priceHistory[key] !== undefined) return priceHistory[key];

    try {
      const token = localStorage.getItem('accessToken');
      const response = await fetch(
        `/api/v1/items/${itemId}/vendors/${vendorId}/price-history`,
        { headers: { Authorization: `Bearer ${token}` } }
      );

      if (!response.ok) {
        setPriceHistory((prev) => ({ ...prev, [key]: [] }));
        return [];
      }

      const data = await response.json().catch(() => []);
      const normalized = Array.isArray(data) ? (data as PriceHistoryRecord[]) : [];
      setPriceHistory((prev) => ({ ...prev, [key]: normalized }));
      return normalized;
    } catch (error) {
      console.error('Error fetching price history:', error);
      setPriceHistory((prev) => ({ ...prev, [key]: [] }));
    }

    return [];
  };

  const resolveVendorIdFromPO = (po: any): string => {
    const direct = String(po?.vendor_id || po?.vendorId || po?.vendor?.id || po?.vendor?.vendor_id || '').trim();
    if (direct) return direct;

    const vendorName = String(po?.vendor?.name || po?.vendor_name || '').trim().toLowerCase();
    if (!vendorName) return '';
    const match = vendors.find((v) => String(v?.name || '').trim().toLowerCase() === vendorName);
    return String(match?.id || '').trim();
  };

  const resolveItemIdFromPOLine = (poLine: any): string => {
    const direct = String(poLine?.item_id || poLine?.itemId || poLine?.item?.id || '').trim();
    if (direct) return direct;
    const code = String(poLine?.item?.code || poLine?.item_code || '').trim();
    if (!code) return '';
    const match = items.find((i) => i.code === code);
    return String(match?.id || '').trim();
  };

  const fetchStockInfo = async (itemId: string) => {
    if (stockInfo[itemId]) return; // Already fetched

    try {
      const token = localStorage.getItem('accessToken');
      const response = await fetch(
        `/api/v1/items/${itemId}/stock`,
        { headers: { Authorization: `Bearer ${token}` } }
      );
      
      if (response.ok) {
        const data = await response.json();
        setStockInfo(prev => ({ ...prev, [itemId]: data }));
      }
    } catch (error) {
      console.error('Error fetching stock info:', error);
    }
  };

  const loadPRData = async (prId: string) => {
    try {
      setLoadingPR(true);
      console.log('Loading PR data for ID:', prId);
      
      // Fetch fresh items data to ensure we have prices
      const token = localStorage.getItem('accessToken');
      const itemsResponse = await fetch('/api/v1/inventory/items', {
        headers: { Authorization: `Bearer ${token}` },
      });
      const itemsData = await itemsResponse.json();
      const freshItems = itemsData || [];
      console.log('Fetched items for price lookup:', freshItems.length);
      
      const prData = await apiClient.get(`/purchase/requisitions/${prId}/available-for-po`);
      console.log('PR Data received:', prData);
      console.log('PR Items:', prData.purchase_requisition_items);
      
      // Store PR ID for later use
      setCurrentPrId(prId);
      
      // Map PR items to PO items and fetch preferred vendors
      const prItemsRaw = Array.isArray(prData.purchase_requisition_items) ? prData.purchase_requisition_items : [];
      const poItemsPromises = prItemsRaw.map(async (item: any) => {
        console.log('Mapping PR item:', item);
        console.log(`Item ID: ${item.item_id}, Item Code: ${item.item_code}, Items count: ${freshItems.length}`);
        
        // Try to find item in items master to get actual price
        let unitPrice = item.estimated_rate || 0;
        let preferredVendorId = '';
        let itemId = item.item_id;
        
        // If no item_id, try to find by item_code
        if (!itemId && item.item_code && freshItems.length > 0) {
          const masterItem = freshItems.find((i: any) => i.code === item.item_code);
          if (masterItem) {
            itemId = masterItem.id;
            console.log(`✓ Found item by code ${item.item_code}: ID = ${itemId}`);
          } else {
            console.log(`⚠ Could not find item with code: ${item.item_code}`);
          }
        }
        
        if (itemId && freshItems.length > 0) {
          const masterItem = freshItems.find((i: any) => i.id === item.item_id);
          if (masterItem) {
            unitPrice = masterItem.standard_cost || masterItem.selling_price || unitPrice;
            console.log(`Found price for ${item.item_code}: ${unitPrice}`);
          }
        }
        
        if (itemId && freshItems.length > 0) {
          const masterItem = freshItems.find((i: any) => i.id === itemId);
          if (masterItem) {
            unitPrice = masterItem.standard_cost || masterItem.selling_price || unitPrice;
            console.log(`Found price for ${item.item_code}: ${unitPrice}`);
          }
        }
        
        // Fetch preferred vendor for this item (unconditional - try even if item not in master)
        if (itemId) {
          try {
            console.log(`[PR→PO] Fetching preferred vendor for ${item.item_code} (ID: ${itemId})...`);
            const vendorResponse = await fetch(`/api/v1/items/${itemId}/vendors/preferred`, {
              headers: { Authorization: `Bearer ${token}` },
            });
            
            console.log(`[PR→PO] Vendor API response status for ${item.item_code}: ${vendorResponse.status}`);
            
            if (vendorResponse.ok) {
              const preferredVendor = await vendorResponse.json();
              console.log(`[PR→PO] Vendor data for ${item.item_code}:`, preferredVendor);
              
              if (preferredVendor && preferredVendor.vendor_id) {
                preferredVendorId = preferredVendor.vendor_id;
                // Use vendor price if available
                if (preferredVendor.unit_price) {
                  unitPrice = preferredVendor.unit_price;
                }
                console.log(`✓ [PR→PO] Auto-selected preferred vendor for ${item.item_code}: ${preferredVendor.vendor_name} (ID: ${preferredVendorId})`);
              } else {
                console.log(`⚠ [PR→PO] No vendor_id in response for ${item.item_code}:`, preferredVendor);
              }
            } else {
              const errorText = await vendorResponse.text();
              console.log(`⚠ [PR→PO] Vendor API error for ${item.item_code} (${vendorResponse.status}): ${errorText}`);
            }
          } catch (error) {
            console.error(`❌ [PR→PO] Exception fetching vendor for ${item.item_code}:`, error);
          }
        } else {
          console.log(`⚠ [PR→PO] No item_id found for ${item.item_code}, skipping vendor fetch`);
        }
        
        const quantity = item.requested_qty || 0;
        const subtotal = quantity * unitPrice;
        const totalWithTax = subtotal + (subtotal * 18 / 100);
        
        // Get UOM from PR item or master item
        let uom = item.uom || '';
        if (!uom && itemId && freshItems.length > 0) {
          const masterItem = freshItems.find((i: any) => i.id === itemId);
          if (masterItem) {
            uom = masterItem.uom || '';
          }
        }
        
        return {
          prItemId: item.id ? String(item.id) : undefined,
          itemId: itemId || '',
          itemCode: item.item_code || '',
          itemName: item.item_name || '',
          uom: uom,
          vendorId: preferredVendorId, // Auto-selected preferred vendor
          quantity: quantity,
          unitPrice: unitPrice,
          taxRate: 18, // Default GST rate
          totalPrice: totalWithTax,
          specifications: item.remarks || '',
          paymentTerms: item.payment_terms || '',
          deliveryTerms: item.delivery_terms || '',
        };
      });

      const poItems = await Promise.all(poItemsPromises);
      console.log('Mapped PO Items with preferred vendors:', poItems);

      setFormData((prev) => ({
        ...prev,
        notes: `Generated from PR: ${prData.pr_number}\nDepartment: ${prData.department}\nPriority: ${prData.priority || 'MEDIUM'}`,
        items: poItems,
      }));

      // Open modal automatically
      setShowModal(true);
      const autoSelectedCount = poItems.filter(item => item.vendorId).length;
      setAlertMessage({ 
        type: 'info', 
        message: poItems.length === 0
          ? `PR ${prData.pr_number} has no remaining items available for PO.`
          : `Loaded ${poItems.length} items from PR ${prData.pr_number}. ${autoSelectedCount} items have preferred vendors auto-selected. You can override vendor selection if needed. System will automatically create separate POs for different vendors.` 
      });
    } catch (error) {
      console.error('Error loading PR data:', error);
      setAlertMessage({ type: 'error', message: 'Failed to load PR data. Please try again.' });
    } finally {
      setLoadingPR(false);
    }
  };

  const fetchOrders = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      if (filterStatus !== 'ALL') params.append('status', filterStatus);
      if (searchTerm) params.append('search', searchTerm);

      const data = await apiClient.get(`/purchase/orders?${params}`);
      console.log('PO API Response:', data);
      if (data && data.length > 0) {
        console.log('First PO:', data[0]);
        console.log('PO Date:', data[0].po_date);
        console.log('Delivery Date:', data[0].delivery_date);
      }
      setOrders(Array.isArray(data) ? data : []);
    } catch (error) {
      console.error('Error fetching orders:', error);
      setOrders([]);
    } finally {
      setLoading(false);
    }
  };

  const actuallyCreatePO = async () => {
    if (submitting) return; // Prevent duplicate submissions
    
    try {
      setSubmitting(true);
      const token = localStorage.getItem('accessToken');
      
      if (!formData.orderDate) {
        setAlertMessage({ type: 'error', message: 'Please select an order date' });
        setSubmitting(false);
        return;
      }
      
      if (formData.items.length === 0) {
        setAlertMessage({ type: 'error', message: 'Please add at least one item' });
        setSubmitting(false);
        return;
      }
      
      // Check if all items have vendor selected
      const itemsWithoutVendor = formData.items.filter(item => !item.vendorId);
      if (itemsWithoutVendor.length > 0) {
        setAlertMessage({ type: 'error', message: 'Please select vendor for all items' });
        setSubmitting(false);
        return;
      }
      
      // Check if all items have itemId (or at least itemCode for pre-filled items)
      const invalidItems = formData.items.filter(item => !item.itemId && !item.itemCode);
      if (invalidItems.length > 0) {
        setAlertMessage({ type: 'error', message: 'Please select items for all rows' });
        setSubmitting(false);
        return;
      }

      // Unit price cannot be 0/empty for any PO line
      const itemsWithInvalidPrice = formData.items
        .map((row, index) => {
          const masterItem = items.find((i) => i.id === row.itemId || i.code === row.itemCode);
          const displayCode = row.itemCode || masterItem?.code || '';
          const displayName = row.itemName || masterItem?.name || '';
          const price = typeof row.unitPrice === 'number' ? row.unitPrice : Number(row.unitPrice);
          return {
            index,
            label: displayCode && displayName ? `${displayCode} - ${displayName}` : (displayName || displayCode || `Row ${index + 1}`),
            price,
          };
        })
        .filter((x) => !Number.isFinite(x.price) || x.price <= 0);

      if (itemsWithInvalidPrice.length > 0) {
        setAlertMessage({
          type: 'error',
          message: `Unit Price cannot be 0. Please enter a valid price for: ${itemsWithInvalidPrice.map((x) => x.label).join(', ')}`,
        });
        setPendingItemIndex(itemsWithInvalidPrice[0].index);
        setSubmitting(false);
        return;
      }

      // Check for compulsory drawings
      const compulsoryItems = formData.items
        .map((row, index) => {
          const masterItem = items.find(i => i.id === row.itemId || i.code === row.itemCode);
          return {
            row,
            index,
            resolvedItemId: masterItem?.id || row.itemId,
            resolvedCode: masterItem?.code || row.itemCode,
            resolvedName: masterItem?.name || row.itemName,
            drawingRequired: masterItem?.drawing_required,
          };
        })
        .filter(x => x.drawingRequired === 'COMPULSORY');

      if (compulsoryItems.length > 0) {
        const itemsWithoutDrawings: Array<{ name: string; firstMissing?: { id: string; code: string; name: string; index: number } }> = [];
        let firstMissing: { id: string; code: string; name: string; index: number } | null = null;

        for (const item of compulsoryItems) {
          const id = item.resolvedItemId;
          const name = item.resolvedName || item.resolvedCode || 'Unknown item';

          if (!id) {
            itemsWithoutDrawings.push({ name });
            continue;
          }

          try {
            const drawings: any[] = await apiClient.get(`/inventory/items/${id}/drawings`);
            if (!Array.isArray(drawings) || drawings.length === 0) {
              itemsWithoutDrawings.push({ name });
              if (!firstMissing) {
                firstMissing = {
                  id,
                  code: item.resolvedCode || '',
                  name: item.resolvedName || '',
                  index: item.index,
                };
              }
            }
          } catch (error) {
            console.error(`Error checking drawings for item ${id}:`, error);
            itemsWithoutDrawings.push({ name });
            if (!firstMissing) {
              firstMissing = {
                id,
                code: item.resolvedCode || '',
                name: item.resolvedName || '',
                index: item.index,
              };
            }
          }
        }

        if (itemsWithoutDrawings.length > 0) {
          setAlertMessage({
            type: 'error',
            message: `Drawing upload is compulsory for: ${itemsWithoutDrawings.map(i => i.name).join(', ')}. Please upload drawings before creating PO.`,
          });

          if (firstMissing) {
            setPendingItemIndex(firstMissing.index);
            setSelectedItemForDrawing({
              id: firstMissing.id,
              code: firstMissing.code,
              name: firstMissing.name,
              mandatory: true,
            });
            setShowDrawingManager(true);
          }

          setSubmitting(false);
          return;
        }
      }

      console.log('FormData before transformation:', formData);
      
      // Group items by vendor
      const itemsByVendor = formData.items.reduce((acc, item) => {
        if (!acc[item.vendorId]) {
          acc[item.vendorId] = [];
        }
        acc[item.vendorId].push(item);
        return acc;
      }, {} as Record<string, typeof formData.items>);

      const vendorIds = Object.keys(itemsByVendor);
      console.log(`Creating ${vendorIds.length} PO(s) for ${vendorIds.length} vendor(s)`);

      const createdPOs = [];
      
      // Create a PO for each vendor
      for (const vendorId of vendorIds) {
        const vendorItems = itemsByVendor[vendorId];
        
        // Transform items for API
        const transformedItems = vendorItems.map(item => {
          let finalItemId = item.itemId;
          
          if (!finalItemId && item.itemCode) {
            const foundItem = items.find(i => i.code === item.itemCode);
            if (foundItem) {
              finalItemId = foundItem.id;
            }
          }
          
          return {
            prItemId: (item as any).prItemId,
            itemCode: item.itemCode || '',
            itemName: item.itemName || '',
            orderedQty: item.quantity,
            rate: item.unitPrice,
            taxPercent: item.taxRate,
            amount: item.totalPrice,
            remarks: item.specifications || '',
            paymentTerms: (item as any).paymentTerms || null,
            deliveryTerms: (item as any).deliveryTerms || null,
          };
        });

        const itemsSubtotal = vendorItems.reduce((sum, item) => sum + item.totalPrice, 0);
        const customsDuty = parseFloat(formData.customsDuty?.toString() || '0');
        const otherCharges = parseFloat(formData.otherCharges?.toString() || '0');
        const grandTotal = itemsSubtotal + customsDuty + otherCharges;

        const payload = {
          prId: currentPrId,
          vendorId: vendorId,
          poDate: formData.orderDate,
          deliveryDate: formData.expectedDelivery || null,
          paymentTerms: formData.paymentTerms,
          paymentStatus: formData.paymentStatus,
          paymentNotes: formData.paymentNotes || null,
          deliveryAddress: formData.deliveryAddress,
          remarks: formData.notes,
          customsDuty: customsDuty,
          otherCharges: otherCharges,
          status: 'DRAFT',
          totalAmount: grandTotal,
          items: transformedItems,
        };

        console.log(`Creating PO for vendor ${vendorId}:`, payload);
        
        const response = await fetch('/api/v1/purchase/orders', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify(payload),
        });

        if (response.ok) {
          const data = await response.json();
          createdPOs.push(data.po_number || data.id);
          console.log('PO created successfully:', data);
        } else {
          const errorData = await response.json();
          console.error('PO creation failed:', errorData);
          throw new Error(`Failed to create PO for vendor: ${errorData.message || 'Unknown error'}`);
        }
      }

      setShowModal(false);
      fetchOrders();
      resetForm();
      setAlertMessage({ 
        type: 'success', 
        message: `Successfully created ${createdPOs.length} Purchase Order(s): ${createdPOs.join(', ')}` 
      });
    } catch (error: any) {
      console.error('Error creating order:', error);
      setAlertMessage({ type: 'error', message: error.message || 'Failed to create PO. Please try again.' });
    } finally {
      setSubmitting(false);
    }
  };

  const handleCreateOrder = async () => {
    // First validate required fields
    if (!formData.orderDate) {
      setAlertMessage({ type: 'error', message: 'Please select an order date' });
      return;
    }
    
    if (formData.items.length === 0) {
      setAlertMessage({ type: 'error', message: 'Please add at least one item' });
      return;
    }

    // Check if all items have vendor selected
    const itemsWithoutVendor = formData.items.filter(item => !item.vendorId);
    if (itemsWithoutVendor.length > 0) {
      setAlertMessage({ type: 'error', message: 'Please select vendor for all items' });
      return;
    }

    // Get first vendor ID for duplicate check
    const firstVendorId = formData.items[0]?.vendorId;
    if (!firstVendorId) {
      setAlertMessage({ type: 'error', message: 'Please select vendor for items' });
      return;
    }

    // Prepare simplified payload for duplicate check
    const checkPayload = {
      vendorId: firstVendorId,
      items: formData.items.map(item => ({
        itemId: item.itemId || items.find(i => i.code === item.itemCode)?.id,
        quantity: item.quantity,
      })),
    };

    // Check for duplicates before creating
    await checkDuplicates(
      () => apiClient.post('/purchase/orders/check-duplicates', checkPayload),
      () => actuallyCreatePO(),
    );
  };

  const handleUpdateOrder = async (poId: string) => {
    if (submitting) return; // Prevent duplicate submissions

    try {
      setSubmitting(true);
      const token = localStorage.getItem('accessToken');

      if (!formData.orderDate) {
        setAlertMessage({ type: 'error', message: 'Please select an order date' });
        setSubmitting(false);
        return;
      }

      if (formData.items.length === 0) {
        setAlertMessage({ type: 'error', message: 'Please add at least one item' });
        setSubmitting(false);
        return;
      }

      const vendorId = formData.vendorId || formData.items[0]?.vendorId;
      if (!vendorId) {
        setAlertMessage({ type: 'error', message: 'Please select a vendor' });
        setSubmitting(false);
        return;
      }

      const invalidItems = formData.items.filter((item) => !item.itemId && !item.itemCode);
      if (invalidItems.length > 0) {
        setAlertMessage({ type: 'error', message: 'Please select items for all rows' });
        setSubmitting(false);
        return;
      }

      const itemsWithInvalidPrice = formData.items
        .map((row, index) => {
          const masterItem = items.find((i) => i.id === row.itemId || i.code === row.itemCode);
          const displayCode = row.itemCode || masterItem?.code || '';
          const displayName = row.itemName || masterItem?.name || '';
          const price = typeof row.unitPrice === 'number' ? row.unitPrice : Number(row.unitPrice);
          return {
            index,
            label:
              displayCode && displayName
                ? `${displayCode} - ${displayName}`
                : displayName || displayCode || `Row ${index + 1}`,
            price,
          };
        })
        .filter((x) => !Number.isFinite(x.price) || x.price <= 0);

      if (itemsWithInvalidPrice.length > 0) {
        setAlertMessage({
          type: 'error',
          message: `Unit Price cannot be 0. Please enter a valid price for: ${itemsWithInvalidPrice
            .map((x) => x.label)
            .join(', ')}`,
        });
        setPendingItemIndex(itemsWithInvalidPrice[0].index);
        setSubmitting(false);
        return;
      }

      const itemsSubtotal = formData.items.reduce((sum, item) => sum + item.totalPrice, 0);
      const customsDuty = parseFloat(formData.customsDuty?.toString() || '0');
      const otherCharges = parseFloat(formData.otherCharges?.toString() || '0');
      const grandTotal = itemsSubtotal + customsDuty + otherCharges;

      const payload = {
        vendorId,
        poDate: formData.orderDate,
        deliveryDate: formData.expectedDelivery || null,
        paymentTerms: formData.paymentTerms,
        paymentStatus: formData.paymentStatus,
        paymentNotes: formData.paymentNotes || null,
        deliveryAddress: formData.deliveryAddress,
        remarks: formData.notes,
        customsDuty,
        otherCharges,
        totalAmount: grandTotal,
        items: formData.items.map((item) => ({
          prItemId: (item as any).prItemId,
          itemCode: item.itemCode || '',
          itemName: item.itemName || '',
          orderedQty: item.quantity,
          rate: item.unitPrice,
          taxPercent: item.taxRate,
          amount: item.totalPrice,
          remarks: item.specifications || '',
          paymentTerms: (item as any).paymentTerms || null,
          deliveryTerms: (item as any).deliveryTerms || null,
        })),
      };

      const response = await fetch(`/api/v1/purchase/orders/${poId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(payload),
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => null);
        throw new Error(errorData?.message || 'Failed to update PO');
      }

      setAlertMessage({ type: 'success', message: 'Purchase Order updated successfully' });
      setShowModal(false);
      fetchOrders();
      resetForm();
    } catch (error: any) {
      console.error('Error updating PO:', error);
      setAlertMessage({ type: 'error', message: error.message || 'Failed to update PO' });
    } finally {
      setSubmitting(false);
    }
  };

  const handleAddItem = () => {
    // Validate last row before adding new one
    if (formData.items.length > 0) {
      const lastItem = formData.items[formData.items.length - 1];
      if (!lastItem.itemId || lastItem.quantity <= 0) {
        alert('Please complete the current row before adding a new one');
        return;
      }
    }

    setFormData((prev) => ({
      ...prev,
      items: [
        ...prev.items,
        {
          prItemId: undefined,
          itemId: '',
          itemCode: '',
          itemName: '',
          uom: '',
          vendorId: '',
          quantity: 1,
          unitPrice: 0,
          taxRate: 18,
          totalPrice: 0,
          specifications: '',
          paymentTerms: '',
          deliveryTerms: '',
        },
      ],
    }));
  };

  const handleUpdateItem = async (index: number, field: string, value: any) => {
    const updatedItems = [...formData.items];
    
    // Check for duplicate items when changing itemId
    if (field === 'itemId' && value) {
      const isDuplicate = formData.items.some((item, i) => 
        i !== index && item.itemId === value
      );
      if (isDuplicate) {
        alert('This item is already added to the purchase order. Please select a different item.');
        return;
      }
    }
    
    // If selecting an item from dropdown, populate itemCode, itemName, unitPrice, and preferred vendor
    if (field === 'itemId' && value) {
      const selectedItem = items.find(item => item.id === value);
      if (selectedItem) {
        updatedItems[index] = {
          ...updatedItems[index],
          itemId: value,
          itemCode: selectedItem.code,
          itemName: selectedItem.name,
          uom: selectedItem.uom || '',
          unitPrice: selectedItem.standard_cost || selectedItem.selling_price || 0,
        };
        
        // Fetch stock info for this item
        fetchStockInfo(value);
        
        // Fetch preferred vendor for this item
        try {
          const token = localStorage.getItem('accessToken');
          console.log(`Fetching preferred vendor for item ${value}...`);
          const response = await fetch(`/api/v1/items/${value}/vendors/preferred`, {
            headers: { Authorization: `Bearer ${token}` },
          });
          
          console.log(`Preferred vendor API response status: ${response.status}`);
          
          if (response.ok) {
            const preferredVendor = await response.json();
            console.log('Preferred vendor data:', preferredVendor);

            const preferredVendorId =
              preferredVendor?.vendor_id ??
              preferredVendor?.vendorId ??
              preferredVendor?.id ??
              preferredVendor?.vendor?.id ??
              '';

            if (preferredVendor && preferredVendorId) {
              updatedItems[index].vendorId = String(preferredVendorId);
              // Update unit price from preferred vendor if available
              if (preferredVendor.unit_price) {
                updatedItems[index].unitPrice = preferredVendor.unit_price;
              }
              console.log(`✓ Auto-selected preferred vendor: ${preferredVendor.vendor_name || preferredVendor.vendorName || preferredVendor.name || ''} (ID: ${String(preferredVendorId)}) for item ${selectedItem.code}`);
            } else {
              console.log('⚠ No preferred vendor ID in response:', preferredVendor);
            }
          } else {
            const errorText = await response.text();
            console.log(`⚠ Preferred vendor API returned ${response.status}: ${errorText}`);
          }
        } catch (error) {
          console.error('❌ Error fetching preferred vendor:', error);
        }
      }
    } else {
      updatedItems[index] = { ...updatedItems[index], [field]: value };
    }

    // If we have item + vendor, try to autofill the unit price from last purchase price.
    // (This overrides standard cost / preferred vendor unit_price when history exists.)
    const row = updatedItems[index];
    const shouldTryAutofill =
      (field === 'itemId' || field === 'vendorId') &&
      Boolean(row?.itemId) &&
      Boolean(row?.vendorId);

    if (shouldTryAutofill) {
      const history = await fetchPriceHistory(row.itemId, row.vendorId);
      const last = history?.[0];
      if (last && typeof last.unit_price === 'number' && !Number.isNaN(last.unit_price)) {
        row.unitPrice = Number(last.unit_price);
      }
    }

    // Recalculate total price
    if (field === 'quantity' || field === 'unitPrice' || field === 'taxRate' || field === 'itemId' || field === 'vendorId') {
      const item = updatedItems[index];
      const subtotal = item.quantity * item.unitPrice;
      item.totalPrice = subtotal + (subtotal * item.taxRate) / 100;
    }

    // Use functional update to avoid clobbering other form fields
    setFormData((prev) => ({ ...prev, items: updatedItems }));
  };

  const handleRemoveItem = (index: number) => {
    setFormData({
      ...formData,
      items: formData.items.filter((_, i) => i !== index),
    });
  };

  // Helper function to set vendor for all items
  const handleSetAllVendors = (vendorId: string) => {
    setFormData({
      ...formData,
      vendorId: vendorId,
      items: formData.items.map(item => ({ ...item, vendorId }))
    });
  };

  const resetForm = () => {
    setFormData({
      vendorId: '',
      orderDate: new Date().toISOString().split('T')[0],
      expectedDelivery: '',
      paymentTerms: 'NET_30',
      paymentStatus: 'UNPAID',
      paymentNotes: '',
      deliveryAddress: '',
      notes: '',
      customsDuty: 0,
      otherCharges: 0,
      trackingNumber: '',
      shippedDate: '',
      estimatedDeliveryDate: '',
      carrierName: '',
      trackingUrl: '',
      deliveryStatus: 'PENDING',
      items: [],
    });
    setCurrentPrId(null); // Clear PR ID on form reset
    setEditingPOId(null); // Clear editing state
    setEditingMode('create');
  };

  const handleViewDetails = async (poId: string) => {
    try {
      const token = localStorage.getItem('accessToken');
      const response = await fetch(`/api/v1/purchase/orders/${poId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json();
      console.log('PO Details:', data);
      setSelectedPO(data);
      setShowViewModal(true);

      // Prefetch last purchase prices for inline display on the approval/details screen
      try {
        const vendorId = resolveVendorIdFromPO(data);
        const poItems = Array.isArray(data?.purchase_order_items) ? data.purchase_order_items : [];
        if (vendorId) {
          await Promise.all(
            poItems
              .map((it: any) => resolveItemIdFromPOLine(it))
              .filter(Boolean)
              .map((itemId: string) => fetchPriceHistory(itemId, vendorId)),
          );
        }
      } catch (e) {
        console.error('Error prefetching PO price history:', e);
      }

      // Ensure we have item master data so we can resolve drawing_required + item ids
      if (items.length === 0) {
        fetchItems();
      }
    } catch (error) {
      console.error('Error fetching PO details:', error);
      setAlertMessage({ type: 'error', message: 'Failed to load PO details' });
    }
  };

  const handleSaveTracking = async (poId: string) => {
    try {
      const token = localStorage.getItem('accessToken');
      
      const trackingData = {
        tracking_number: formData.trackingNumber || null,
        shipped_date: formData.shippedDate || null,
        estimated_delivery_date: formData.estimatedDeliveryDate || null,
        carrier_name: formData.carrierName || null,
        tracking_url: formData.trackingUrl || null,
        delivery_status: formData.deliveryStatus || 'PENDING',
      };

      const response = await fetch(`/api/v1/purchase/orders/${poId}/tracking`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(trackingData),
      });

      if (response.ok) {
        setAlertMessage({ type: 'success', message: 'Tracking information saved successfully' });
        fetchOrders();
        setShowModal(false);
        resetForm();
      } else {
        const error = await response.json();
        throw new Error(error.message || 'Failed to save tracking information');
      }
    } catch (error: any) {
      console.error('Error saving tracking:', error);
      setAlertMessage({ type: 'error', message: error.message || 'Failed to save tracking information' });
    }
  };

  const handleEditDetails = async (poId: string, mode: 'edit' | 'tracking' = 'edit') => {
    try {
      setCurrentPrId(null);
      setPendingItemIndex(null);

      // Ensure item options are loaded so SearchableSelect can render the selected label
      if (items.length === 0) {
        await fetchItems();
      }

      const token = localStorage.getItem('accessToken');
      const response = await fetch(`/api/v1/purchase/orders/${poId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json();
      console.log('PO Details for Edit:', data);

      const resolvedVendorId = String(data?.vendor_id || data?.vendorId || data?.vendor?.id || data?.vendor?.vendor_id || '');
      
      // Populate form with PO data for editing
      const editItems = data.purchase_order_items?.map((item: any) => ({
        itemCode: item.item_code || item.item?.code || '',
        itemId: (() => {
          const direct = item.item_id || item.itemId || item.item?.id;
          if (direct) return direct;
          const code = String(item.item_code || item.item?.code || '').trim();
          if (!code) return '';
          const match = items.find((i) => String(i.code).trim() === code);
          return match?.id || '';
        })(),
        itemName: item.item_name || item.item?.name || '',
        vendorId: resolvedVendorId, // Use PO's vendor for all items
        quantity: item.ordered_qty || 0,
        unitPrice: item.rate || 0,
        taxRate: item.tax_percent || 18,
        totalPrice: item.amount || 0,
        specifications: item.remarks || '',
      })) || [];
      
      setFormData({
        vendorId: resolvedVendorId,
        orderDate: data.po_date || new Date().toISOString().split('T')[0],
        expectedDelivery: data.delivery_date || '',
        paymentTerms: data.payment_terms || 'NET_30',
        paymentStatus: data.payment_status || 'UNPAID',
        paymentNotes: data.payment_notes || '',
        deliveryAddress: data.delivery_address || '',
        notes: data.remarks || '',
        customsDuty: data.customs_duty || 0,
        otherCharges: data.other_charges || 0,
        trackingNumber: data.tracking_number || '',
        shippedDate: data.shipped_date || '',
        estimatedDeliveryDate: data.estimated_delivery_date || '',
        carrierName: data.carrier_name || '',
        trackingUrl: data.tracking_url || '',
        deliveryStatus: data.delivery_status || 'PENDING',
        items: editItems,
      });
      
      setEditingPOId(poId);
      setEditingMode(mode);
      setShowModal(true);
      setAlertMessage({
        type: 'info',
        message: mode === 'tracking' ? 'Update tracking details below' : 'Edit mode: Update the PO details below',
      });
    } catch (error) {
      console.error('Error fetching PO details:', error);
      setAlertMessage({ type: 'error', message: 'Failed to load PO details' });
    }
  };

  const fetchPOEmailPreview = async (poId: string, payload: any, seedEditableFields: boolean) => {
    try {
      setPoEmailPreviewLoading(true);
      const res = await apiClient.post(`/purchase/orders/${poId}/preview-email`, payload);

      setPoEmailPreview(res);
      setShowPOEmailPreview(true);

      if (seedEditableFields) {
        const preview = res?.preview || res;
        setPoEmailTo(String(preview?.to || res?.recipient || ''));
        setPoEmailSubject(String(preview?.subject || ''));
        setPoEmailMessage('');
      }
    } catch (error: any) {
      console.error('Error previewing PO email:', error);
      setAlertMessage({
        type: 'error',
        message: error?.message || 'Failed to generate PO email preview',
      });
    } finally {
      setPoEmailPreviewLoading(false);
    }
  };

  const handlePreviewPOEmail = async (poId: string) => {
    return fetchPOEmailPreview(poId, {}, true);
  };

  const handleUpdatePOEmailPreview = async () => {
    const poId = String(poEmailPreview?.po_id || selectedPO?.id || '').trim();
    if (!poId) return;
    return fetchPOEmailPreview(
      poId,
      {
        to: poEmailTo,
        subject: poEmailSubject,
        customMessage: poEmailMessage,
      },
      false,
    );
  };

  const handleSendPOEmail = async (poId: string) => {
    try {
      setPoEmailSending(true);
      const res = await apiClient.post(`/purchase/orders/${poId}/send-email`, {
        to: poEmailTo,
        subject: poEmailSubject,
        customMessage: poEmailMessage,
      });

      setAlertMessage({
        type: 'success',
        message: res?.message || 'PO email sent successfully',
      });
      setShowPOEmailPreview(false);
      setPoEmailPreview(null);
      setPoEmailTo('');
      setPoEmailSubject('');
      setPoEmailMessage('');
      setShowViewModal(false);
      await fetchOrders();
    } catch (error: any) {
      console.error('Error sending PO email:', error);
      setAlertMessage({
        type: 'error',
        message: error?.message || 'Failed to send PO email',
      });
    } finally {
      setPoEmailSending(false);
    }
  };

  const handleDeleteAll = async () => {
    if (!confirm(`Are you sure you want to delete ${orderSelection.selectedItems.length} purchase orders? This action cannot be undone.`)) return;

    try {
      const selectedOrders = [...orderSelection.selectedItems];
      const results = await Promise.allSettled(
        selectedOrders.map((order) => apiClient.delete(`/purchase/orders/${order.id}`)),
      );

      const failed: Array<{ poNumber: string; reason: string }> = [];
      let successCount = 0;

      results.forEach((result, index) => {
        const order = selectedOrders[index];
        if (result.status === 'fulfilled') {
          successCount += 1;
          return;
        }

        const reason =
          (result.reason as any)?.message ||
          (typeof result.reason === 'string' ? result.reason : 'Delete failed');

        failed.push({ poNumber: order?.po_number || 'Unknown PO', reason });
      });

      orderSelection.deselectAll();
      fetchOrders();

      if (failed.length === 0) {
        setAlertMessage({
          type: 'success',
          message: `${successCount} purchase orders deleted successfully`,
        });
        return;
      }

      const shown = failed.slice(0, 3);
      const remainder = failed.length - shown.length;
      const details = shown
        .map((f) => `${f.poNumber}: ${f.reason}`)
        .join(' | ');
      const suffix = remainder > 0 ? ` (+${remainder} more)` : '';

      setAlertMessage({
        type: failed.length === selectedOrders.length ? 'error' : 'info',
        message: `Deleted ${successCount} of ${selectedOrders.length} purchase orders. Failed: ${details}${suffix}`,
      });
    } catch (error) {
      console.error('Error deleting purchase orders:', error);
      setAlertMessage({
        type: 'error',
        message: (error as any)?.message || 'Failed to delete purchase orders',
      });
    }
  };

  const getStatusColor = (status: string) => {
    const colors: Record<string, string> = {
      DRAFT: 'bg-gray-100 text-gray-800',
      SENT: 'bg-blue-100 text-blue-800',
      ACKNOWLEDGED: 'bg-purple-100 text-purple-800',
      PARTIAL: 'bg-yellow-100 text-yellow-800',
      COMPLETED: 'bg-green-100 text-green-800',
      CANCELLED: 'bg-red-100 text-red-800',
    };
    return colors[status] || 'bg-gray-100 text-gray-800';
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-amber-50 to-orange-50 p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="flex justify-between items-center mb-8">
          <div>
            <button
              onClick={() => router.push('/dashboard/purchase')}
              className="text-amber-600 hover:text-amber-800 mb-2"
            >
              ← Back to Purchase Management
            </button>
            <h1 className="text-4xl font-bold text-amber-900">Purchase Orders</h1>
            <p className="text-amber-700">Create and manage purchase orders to vendors</p>
          </div>
          <div className="flex gap-4">
            {orderSelection.hasSelections && (
              <button
                onClick={handleDeleteAll}
                className="bg-red-600 hover:bg-red-700 text-white px-6 py-3 rounded-lg font-semibold"
              >
                Delete Selected ({orderSelection.selectedItems.length})
              </button>
            )}
            <button
              onClick={() => {
                setShowModal(true);
                setEditingMode('create');
                setEditingPOId(null);
                // Lazy load items when modal opens
                if (items.length === 0) {
                  fetchItems();
                }
              }}
              className="bg-amber-600 hover:bg-amber-700 text-white px-6 py-3 rounded-lg font-semibold"
            >
              + Create Purchase Order
            </button>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-lg shadow-md p-6 mb-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Status</label>
              <select
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value)}
                className="w-full border border-gray-300 rounded-lg px-4 py-2"
              >
                <option value="ALL">All Status</option>
                <option value="DRAFT">Draft</option>
                <option value="SENT">Sent</option>
                <option value="ACKNOWLEDGED">Acknowledged</option>
                <option value="APPROVED">Approved</option>
                <option value="PARTIAL">Partial</option>
                <option value="COMPLETED">Completed</option>
              </select>
            </div>
            <div className="md:col-span-2">
              <label className="block text-sm font-medium text-gray-700 mb-2">Search</label>
              <input
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && fetchOrders()}
                placeholder="Search by PO number, notes..."
                className="w-full border border-gray-300 rounded-lg px-4 py-2"
              />
            </div>
          </div>
          {orders.length > 0 && (
            <div className="mt-4 flex items-center gap-4">
              <label className="flex items-center gap-2">
                <input
                  type="checkbox"
                  checked={orderSelection.isAllSelected}
                  onChange={orderSelection.toggleSelectAll}
                  className="w-4 h-4"
                />
                <span className="text-sm font-medium text-gray-700">
                  Select All ({orders.length} orders)
                </span>
              </label>
              {orderSelection.hasSelections && (
                <button
                  onClick={orderSelection.deselectAll}
                  className="text-sm text-amber-600 hover:text-amber-800"
                >
                  Deselect All
                </button>
              )}
            </div>
          )}
        </div>

        {/* Orders List */}
        <div className="bg-white rounded-lg shadow-md border border-gray-200">
          <div className="overflow-x-auto">
          {loading ? (
            <div className="p-8 text-center text-gray-500">Loading orders...</div>
          ) : orders.length === 0 ? (
            <div className="p-12 text-center">
              <div className="text-6xl mb-4">📋</div>
              <h3 className="text-xl font-semibold text-gray-700 mb-2">No Purchase Orders Yet</h3>
              <p className="text-gray-500">Create your first purchase order to get started</p>
            </div>
          ) : (
            <table className="w-full min-w-[1000px]">
              <thead className="bg-gray-50 border-b border-gray-200">
                <tr>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider w-12"></th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">PO Number</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">PR Ref</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">Vendor</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">Order Date</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">Expected</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">Items</th>
                  <th className="px-4 py-3 text-right text-xs font-semibold text-gray-600 uppercase tracking-wider">Amount</th>
                  <th className="px-4 py-3 text-center text-xs font-semibold text-gray-600 uppercase tracking-wider">Payment</th>
                  <th className="px-4 py-3 text-center text-xs font-semibold text-gray-600 uppercase tracking-wider">Status</th>
                  <th className="px-4 py-3 text-right text-xs font-semibold text-gray-600 uppercase tracking-wider">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {orders.map((order) => (
                  <tr key={order.id} className={`hover:bg-gray-50 transition-colors ${orderSelection.isSelected(order.id) ? 'bg-amber-50' : ''}`}>
                    <td className="px-4 py-3">
                      <input
                        type="checkbox"
                        checked={orderSelection.isSelected(order.id)}
                        onChange={() => orderSelection.toggleSelection(order.id)}
                        className="w-4 h-4 rounded border-gray-300 text-amber-600 focus:ring-amber-500"
                      />
                    </td>
                    <td className="px-4 py-3 whitespace-nowrap font-medium text-gray-900">{order.po_number}</td>
                    <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-500">
                      {order.pr?.pr_number || '-'}
                    </td>
                    <td className="px-4 py-3">
                      <div className="text-sm font-medium text-gray-900">{order.vendor.name}</div>
                      <div className="text-xs text-gray-500">{order.vendor.contact_person}</div>
                    </td>
                    <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-600">
                      {order.po_date ? (() => {
                        try {
                          return new Date(order.po_date).toLocaleDateString();
                        } catch {
                          return order.po_date;
                        }
                      })() : '-'}
                    </td>
                    <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-600">
                      {order.delivery_date ? (() => {
                        try {
                          return new Date(order.delivery_date).toLocaleDateString();
                        } catch {
                          return order.delivery_date;
                        }
                      })() : '-'}
                    </td>
                    <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-600">
                      {order.purchase_order_items.length} items
                    </td>
                    <td className="px-4 py-3 text-right whitespace-nowrap text-sm font-semibold text-gray-900">
                      ₹{order.total_amount?.toLocaleString() || 0}
                    </td>
                    <td className="px-4 py-3 text-center whitespace-nowrap">
                      <span className={`inline-flex px-2 py-1 text-xs font-medium rounded-full ${
                        order.payment_status === 'PAID' ? 'bg-green-100 text-green-700' :
                        order.payment_status === 'CHEQUE_ISSUED' ? 'bg-blue-100 text-blue-700' :
                        order.payment_status === 'OTHER' ? 'bg-purple-100 text-purple-700' :
                        'bg-yellow-100 text-yellow-700'
                      }`}>
                        {order.payment_status === 'CHEQUE_ISSUED' ? 'CHEQUE' : order.payment_status || 'UNPAID'}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-center whitespace-nowrap">
                      <span className={`inline-flex px-2 py-1 text-xs font-medium rounded-full ${getStatusColor(order.status)}`}>
                        {order.status}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-right whitespace-nowrap text-sm">
                      <button 
                        onClick={() => handleViewDetails(order.id)}
                        className="text-amber-600 hover:text-amber-800 font-medium mr-3"
                      >
                        View
                      </button>
                      <button 
                        onClick={() => handleEditDetails(order.id, 'edit')}
                        className="text-blue-600 hover:text-blue-800 font-medium"
                      >
                        Edit
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
          </div>
        </div>
      </div>

      {/* Create Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg w-full max-w-[95vw] h-[95vh] flex flex-col overflow-hidden">
            <div className="p-6 border-b border-gray-200 flex-shrink-0">
              <h2 className="text-2xl font-bold text-gray-900">
                {editingMode === 'create'
                  ? 'Create Purchase Order'
                  : editingMode === 'tracking'
                    ? 'Update Tracking Information'
                    : 'Edit Purchase Order'}
              </h2>
            </div>
            <div className="flex-1 overflow-y-auto p-6 space-y-6">
              {/* Order Details */}
              <div className="grid grid-cols-2 gap-4">
                {editingMode === 'create' && (
                  <div className="col-span-2">
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Purchase Requisition (optional)
                    </label>
                    <SearchableSelect
                      value={currentPrId || ''}
                      onChange={(value) => {
                        const next = String(value || '').trim();
                        if (!next) {
                          setCurrentPrId(null);
                          setFormData((prev) => ({ ...prev, items: [] }));
                          return;
                        }
                        loadPRData(next);
                      }}
                      options={purchaseRequisitions.map((pr) => ({
                        value: pr.id,
                        label: pr.pr_number,
                        subtitle: pr.department || pr.status || '',
                      }))}
                      placeholder={loadingPrList ? 'Loading PRs...' : 'Select PR...'}
                    />
                    <p className="text-xs text-gray-500 mt-1">
                      Shows only PR items not already used in any PO.
                    </p>
                  </div>
                )}
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Master Vendor (sets all items)
                  </label>
                  <SearchableSelect
                    value={formData.vendorId}
                    onChange={(value) => handleSetAllVendors(String(value || ''))}
                    options={vendors.map((v) => ({
                      value: v.id,
                      label: v.name,
                      subtitle: v.contact_person,
                    }))}
                    placeholder="Search vendor to apply to all items..."
                  />
                  <p className="text-xs text-gray-500 mt-1">
                    You can override individual item vendors in the items grid below
                  </p>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Payment Terms</label>
                  <select
                    value={formData.paymentTerms}
                    onChange={(e) => setFormData({ ...formData, paymentTerms: e.target.value })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  >
                    <option value="NET_30">Net 30</option>
                    <option value="NET_60">Net 60</option>
                    <option value="NET_90">Net 90</option>
                    <option value="ADVANCE">Advance</option>
                    <option value="COD">Cash on Delivery</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Payment Status</label>
                  <select
                    value={formData.paymentStatus}
                    onChange={(e) => setFormData({ ...formData, paymentStatus: e.target.value })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  >
                    <option value="UNPAID">Unpaid</option>
                    <option value="PAID">Paid</option>
                    <option value="CHEQUE_ISSUED">Cheque Issued</option>
                    <option value="OTHER">Other</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Order Date</label>
                  <input
                    type="date"
                    value={formData.orderDate}
                    onChange={(e) => setFormData({ ...formData, orderDate: e.target.value })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Expected Delivery</label>
                  <input
                    type="date"
                    value={formData.expectedDelivery}
                    onChange={(e) => setFormData({ ...formData, expectedDelivery: e.target.value })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Delivery Address</label>
                <textarea
                  value={formData.deliveryAddress}
                  onChange={(e) => setFormData({ ...formData, deliveryAddress: e.target.value })}
                  rows={2}
                  className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  placeholder="Enter delivery address..."
                />
              </div>

              {/* Tracking Information */}
              {editingMode !== 'create' && (
                <div className="border-t pt-4">
                  <h3 className="text-lg font-semibold text-gray-900 mb-4">Tracking Information</h3>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">Tracking Number</label>
                      <input
                        type="text"
                        value={formData.trackingNumber}
                        onChange={(e) => setFormData({ ...formData, trackingNumber: e.target.value })}
                        className="w-full border border-gray-300 rounded-lg px-4 py-2"
                        placeholder="Enter tracking number..."
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">Delivery Status</label>
                      <select
                        value={formData.deliveryStatus}
                        onChange={(e) => setFormData({ ...formData, deliveryStatus: e.target.value })}
                        className="w-full border border-gray-300 rounded-lg px-4 py-2"
                      >
                        <option value="PENDING">Pending</option>
                        <option value="SHIPPED">Shipped</option>
                        <option value="IN_TRANSIT">In Transit</option>
                        <option value="DELIVERED">Delivered</option>
                        <option value="DELAYED">Delayed</option>
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">Carrier Name</label>
                      <input
                        type="text"
                        value={formData.carrierName}
                        onChange={(e) => setFormData({ ...formData, carrierName: e.target.value })}
                        className="w-full border border-gray-300 rounded-lg px-4 py-2"
                        placeholder="e.g., Blue Dart, DTDC..."
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">Shipped Date</label>
                      <input
                        type="date"
                        value={formData.shippedDate}
                        onChange={(e) => setFormData({ ...formData, shippedDate: e.target.value })}
                        className="w-full border border-gray-300 rounded-lg px-4 py-2"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">Estimated Delivery Date</label>
                      <input
                        type="date"
                        value={formData.estimatedDeliveryDate}
                        onChange={(e) => setFormData({ ...formData, estimatedDeliveryDate: e.target.value })}
                        className="w-full border border-gray-300 rounded-lg px-4 py-2"
                      />
                    </div>
                    <div className="col-span-2">
                      <label className="block text-sm font-medium text-gray-700 mb-2">Tracking URL</label>
                      <input
                        type="url"
                        value={formData.trackingUrl}
                        onChange={(e) => setFormData({ ...formData, trackingUrl: e.target.value })}
                        className="w-full border border-gray-300 rounded-lg px-4 py-2"
                        placeholder="https://..."
                      />
                    </div>
                  </div>
                </div>
              )}

              {formData.paymentStatus === 'OTHER' && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Payment Notes</label>
                  <textarea
                    value={formData.paymentNotes}
                    onChange={(e) => setFormData({ ...formData, paymentNotes: e.target.value })}
                    rows={2}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                    placeholder="Enter payment details or notes..."
                  />
                </div>
              )}

              {/* Items */}
              {editingMode !== 'tracking' && (
                <div>
                  <div className="flex justify-between items-center mb-2">
                    <h3 className="text-lg font-semibold text-gray-900">Items</h3>
                    <button
                      onClick={handleAddItem}
                      className="text-amber-600 hover:text-amber-800 font-medium"
                    >
                      + Add Item
                    </button>
                  </div>
                  {editingMode === 'create' && currentPrId && (
                    <div className="mb-4 p-3 bg-blue-50 border border-blue-200 rounded-lg">
                      <p className="text-sm text-blue-800">
                        <strong>Multiple Vendors?</strong> Remove items not from the selected vendor (click × button), then create PO. You can create another PO from the same PR for different vendors.
                      </p>
                    </div>
                  )}

                {formData.items.length === 0 ? (
                  <div className="text-center py-8 border-2 border-dashed border-gray-300 rounded-lg">
                    <p className="text-gray-500">No items added. Click &ldquo;Add Item&rdquo; to get started.</p>
                  </div>
                ) : (
                  <div className="space-y-4">
                    {/* Column Headers */}
                    <div className="grid grid-cols-[48px_minmax(280px,3fr)_minmax(220px,2fr)_minmax(90px,1fr)_minmax(90px,1fr)_minmax(110px,1fr)_minmax(90px,1fr)_minmax(170px,1.2fr)] gap-4 px-4 pb-2 border-b border-gray-300">
                      <div className="text-sm font-semibold text-gray-700">S. No</div>
                      <div className="text-sm font-semibold text-gray-700">Item</div>
                      <div className="text-sm font-semibold text-gray-700">Vendor</div>
                      <div className="text-sm font-semibold text-gray-700">Quantity</div>
                      <div className="text-sm font-semibold text-gray-700">UOM</div>
                      <div className="text-sm font-semibold text-gray-700">Unit Price</div>
                      <div className="text-sm font-semibold text-gray-700">Tax %</div>
                      <div className="text-sm font-semibold text-gray-700">Total Price</div>
                    </div>
                    
                    {formData.items.map((item, index) => (
                      <div key={index} className={`border border-gray-300 rounded-lg p-4 ${pendingItemIndex === index ? 'ring-2 ring-red-300' : ''}`}>
                        <div className="grid grid-cols-[48px_minmax(280px,3fr)_minmax(220px,2fr)_minmax(90px,1fr)_minmax(90px,1fr)_minmax(110px,1fr)_minmax(90px,1fr)_minmax(170px,1.2fr)] gap-4 items-start">
                          <div className="pt-2 text-sm font-medium text-gray-700">{index + 1}</div>
                          <div className="min-w-0">
                            {item.itemId ? (
                              <div className="space-y-1">
                                <div className="w-full border border-gray-300 rounded px-3 py-2 bg-gray-50 overflow-hidden">
                                  {(() => {
                                    const masterItem = items.find((i) => i.id === item.itemId || i.code === item.itemCode);
                                    const displayCode = item.itemCode || masterItem?.code || '';
                                    const displayName = item.itemName || masterItem?.name || '';
                                    const drawingRequired = masterItem?.drawing_required || 'OPTIONAL';
                                    const resolvedItemId = masterItem?.id || item.itemId;

                                    return (
                                      <>
                                        <div className="font-medium text-sm leading-snug whitespace-normal break-words">
                                          {displayCode && displayName ? `${displayCode} - ${displayName}` : (displayName || displayCode || 'Selected Item')}
                                        </div>
                                        {resolvedItemId ? (
                                          <div className="mt-1 flex items-center justify-between gap-2 min-w-0">
                                            <span className={`text-xs px-2 py-0.5 rounded ${
                                              drawingRequired === 'COMPULSORY'
                                                ? 'bg-red-100 text-red-800'
                                                : 'bg-gray-100 text-gray-700'
                                            }`}>
                                              Drawing: {drawingRequired}
                                            </span>
                                            <button
                                              type="button"
                                              onClick={() => {
                                                setPendingItemIndex(index);
                                                setSelectedItemForDrawing({
                                                  id: resolvedItemId,
                                                  code: displayCode,
                                                  name: displayName,
                                                  mandatory: drawingRequired === 'COMPULSORY',
                                                });
                                                setShowDrawingManager(true);
                                              }}
                                              className="text-xs text-amber-700 hover:text-amber-900 font-medium shrink-0"
                                            >
                                              Manage Drawings
                                            </button>
                                          </div>
                                        ) : null}
                                      </>
                                    );
                                  })()}
                                  {item.itemId && stockInfo[item.itemId] && (
                                    <div className="text-xs text-gray-600 mt-1 space-y-0.5">
                                      <div className="flex justify-between">
                                        <span>Stock in Hand:</span>
                                        <span className="font-semibold text-blue-600">{stockInfo[item.itemId].total_quantity || 0}</span>
                                      </div>
                                      <div className="flex justify-between">
                                        <span>Available:</span>
                                        <span className="font-semibold text-green-600">{stockInfo[item.itemId].available_quantity || 0}</span>
                                      </div>
                                      <div className="flex justify-between">
                                        <span>Allocated:</span>
                                        <span className="font-semibold text-amber-600">{stockInfo[item.itemId].allocated_quantity || 0}</span>
                                      </div>
                                    </div>
                                  )}
                                </div>
                                <SearchableSelect
                                  value={item.itemId}
                                  onChange={(value) => handleUpdateItem(index, 'itemId', value)}
                                  options={items.map(i => ({
                                    value: i.id,
                                    label: i.code,
                                    subtitle: i.name
                                  }))}
                                  placeholder="Change item..."
                                  className="text-xs"
                                />
                              </div>
                            ) : (
                              <SearchableSelect
                                value={item.itemId}
                                onChange={(value) => handleUpdateItem(index, 'itemId', value)}
                                options={items.map(i => ({
                                  value: i.id,
                                  label: i.code,
                                  subtitle: i.name
                                }))}
                                placeholder="Select Item"
                                required
                              />
                            )}
                          </div>
                          <div className="min-w-0">
                            <SearchableSelect
                              value={item.vendorId}
                              onChange={(value) => handleUpdateItem(index, 'vendorId', String(value || ''))}
                              options={vendors.map((v) => ({
                                value: v.id,
                                label: v.name,
                                subtitle: v.contact_person,
                              }))}
                              placeholder="Search vendor..."
                              required
                            />
                          </div>
                          <div className="min-w-0">
                            <div className="flex items-center gap-2">
                              <input
                                type="number"
                                value={item.quantity}
                                onChange={(e) => handleUpdateItem(index, 'quantity', parseFloat(e.target.value))}
                                placeholder="Quantity"
                                className="w-full border border-gray-300 rounded px-3 py-2"
                                required
                              />
                            </div>
                          </div>
                          <div className="min-w-0">
                            <input
                              type="text"
                              value={item.uom || ''}
                              readOnly
                              placeholder="UOM"
                              className="w-full border border-gray-300 rounded px-3 py-2 bg-gray-50 cursor-not-allowed"
                              title="UOM is auto-filled from master item"
                            />
                          </div>
                          <div className="relative min-w-0">
                            <div className="flex items-center gap-1">
                              <input
                                type="number"
                                value={item.unitPrice}
                                onChange={(e) => handleUpdateItem(index, 'unitPrice', parseFloat(e.target.value))}
                                placeholder="Unit Price"
                                className="w-full border border-gray-300 rounded px-3 py-2"
                              />
                              {(() => {
                                const effectiveVendorId = String(item.vendorId || formData.vendorId || '').trim();
                                const effectiveItemId =
                                  String(item.itemId || '').trim() ||
                                  String(items.find((i) => i.code === item.itemCode)?.id || '').trim();
                                if (!effectiveItemId || !effectiveVendorId) return null;

                                return (
                                <div
                                  className="relative"
                                  onMouseEnter={() => {
                                    setHoveredItem(index);
                                    fetchPriceHistory(effectiveItemId, effectiveVendorId);
                                  }}
                                  onMouseLeave={() => setHoveredItem(null)}
                                >
                                  <button
                                    type="button"
                                    className="p-1 text-blue-500 hover:text-blue-700 cursor-help"
                                  >
                                    <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                                      <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
                                    </svg>
                                  </button>
                                  
                                  {hoveredItem === index && (
                                    <div className="absolute z-50 right-0 mr-2 top-0 w-80 bg-white border border-gray-300 rounded-lg shadow-xl p-4">
                                      <div className="text-sm font-semibold text-gray-700 mb-2">Last 3 Purchase Prices</div>
                                      {(() => {
                                        const key = `${effectiveItemId}-${effectiveVendorId}`;
                                        const history = priceHistory[key];
                                        
                                        if (!history) {
                                          return <div className="text-xs text-gray-500">Loading...</div>;
                                        }
                                        
                                        if (history.length === 0) {
                                          return <div className="text-xs text-gray-500">No purchase history available</div>;
                                        }
                                        
                                        return (
                                          <div className="space-y-2">
                                            {history.map((record, idx) => (
                                              <div key={idx} className="border-b border-gray-200 pb-2 last:border-0">
                                                <div className="flex justify-between items-start">
                                                  <div>
                                                    <div className="text-xs font-medium text-gray-900">
                                                      PO: {record.po_number}
                                                    </div>
                                                    <div className="text-xs text-gray-500">
                                                      {new Date(record.po_date).toLocaleDateString()}
                                                    </div>
                                                    <div className="text-xs text-gray-500">
                                                      Qty: {record.quantity}
                                                    </div>
                                                  </div>
                                                  <div className="text-right">
                                                    <div className="text-sm font-semibold text-blue-600">
                                                      ₹{record.unit_price?.toFixed(2) || '0.00'}
                                                    </div>
                                                    <div className="text-xs text-gray-500 capitalize">
                                                      {record.po_status.replace('_', ' ')}
                                                    </div>
                                                  </div>
                                                </div>
                                              </div>
                                            ))}
                                          </div>
                                        );
                                      })()}

                                    </div>
                                  )}
                                </div>
                                );
                              })()}
                            </div>

                            {(() => {
                              const effectiveVendorId = String(item.vendorId || formData.vendorId || '').trim();
                              const effectiveItemId =
                                String(item.itemId || '').trim() ||
                                String(items.find((i) => i.code === item.itemCode)?.id || '').trim();
                              if (!effectiveItemId || !effectiveVendorId) return null;

                              const key = `${effectiveItemId}-${effectiveVendorId}`;
                              const history = priceHistory[key];
                              if (!history) {
                                return <div className="mt-1 max-w-full break-words text-[11px] leading-tight text-gray-500">Last: Loading...</div>;
                              }
                              const last = history?.[0];
                              if (!last) {
                                return <div className="mt-1 max-w-full break-words text-[11px] leading-tight text-gray-500">Last purchase price not available</div>;
                              }
                              return (
                                <div className="mt-1 max-w-full break-words text-[11px] leading-tight text-gray-600">
                                  Last: <span className="font-medium text-gray-800">₹{Number(last.unit_price || 0).toFixed(2)}</span>
                                </div>
                              );
                            })()}
                          </div>
                          <div>
                            <input
                              type="number"
                              value={item.taxRate}
                              onChange={(e) => handleUpdateItem(index, 'taxRate', parseFloat(e.target.value))}
                              placeholder="Tax %"
                              className="w-full border border-gray-300 rounded px-3 py-2"
                            />
                          </div>
                          <div className="flex items-center justify-between gap-2 min-w-0 pt-2">
                            <span className="font-medium">₹{item.totalPrice.toFixed(2)}</span>
                            <button
                              onClick={() => handleRemoveItem(index)}
                              className="shrink-0 px-2 py-1 bg-red-100 text-red-600 hover:bg-red-200 hover:text-red-800 rounded font-bold text-lg"
                              title="Remove this item"
                            >
                              ×
                            </button>
                          </div>
                        </div>

                        <div className="mt-3 grid grid-cols-2 gap-4">
                          <div>
                            <label className="block text-xs font-medium text-gray-700 mb-1">Line Payment Terms</label>
                            <input
                              type="text"
                              value={(item as any).paymentTerms || ''}
                              onChange={(e) => handleUpdateItem(index, 'paymentTerms', e.target.value)}
                              className="w-full border border-gray-300 rounded px-3 py-2 text-sm"
                            />
                          </div>
                          <div>
                            <label className="block text-xs font-medium text-gray-700 mb-1">Line Delivery Terms</label>
                            <input
                              type="text"
                              value={(item as any).deliveryTerms || ''}
                              onChange={(e) => handleUpdateItem(index, 'deliveryTerms', e.target.value)}
                              className="w-full border border-gray-300 rounded px-3 py-2 text-sm"
                            />
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
                {(editingMode === 'create' || editingMode === 'edit') && formData.items.length > 0 && (
                  <div className="mt-4 flex justify-center">
                    <button
                      onClick={handleAddItem}
                      className="px-6 py-2 text-amber-600 hover:text-amber-800 font-medium border-2 border-dashed border-amber-300 hover:border-amber-500 rounded-lg transition-colors"
                    >
                      + Add Another Item
                    </button>
                  </div>
                )}
              </div>
              )}

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Notes</label>
                <textarea
                  value={formData.notes}
                  onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                  rows={3}
                  className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  placeholder="Additional notes..."
                />
              </div>

              {/* Additional Charges */}
              {editingMode !== 'tracking' && (
                <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Customs Duty (₹)</label>
                  <input
                    type="number"
                    step="0.01"
                    min="0"
                    value={formData.customsDuty}
                    onChange={(e) => setFormData({ ...formData, customsDuty: parseFloat(e.target.value) || 0 })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                    placeholder="0.00"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Other Charges (₹)</label>
                  <input
                    type="number"
                    step="0.01"
                    min="0"
                    value={formData.otherCharges}
                    onChange={(e) => setFormData({ ...formData, otherCharges: parseFloat(e.target.value) || 0 })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                    placeholder="0.00"
                  />
                </div>
              </div>
              )}

              {/* Total */}
              <div className="border-t pt-4">
                <div className="space-y-2 text-right">
                  <div className="flex justify-between text-sm text-gray-600">
                    <span>Items Subtotal:</span>
                    <span>₹{formData.items.reduce((sum, item) => sum + item.totalPrice, 0).toFixed(2)}</span>
                  </div>
                  {(formData.customsDuty > 0 || formData.otherCharges > 0) && (
                    <>
                      {formData.customsDuty > 0 && (
                        <div className="flex justify-between text-sm text-gray-600">
                          <span>Customs Duty:</span>
                          <span>₹{formData.customsDuty.toFixed(2)}</span>
                        </div>
                      )}
                      {formData.otherCharges > 0 && (
                        <div className="flex justify-between text-sm text-gray-600">
                          <span>Other Charges:</span>
                          <span>₹{formData.otherCharges.toFixed(2)}</span>
                        </div>
                      )}
                    </>
                  )}
                  <div className="flex justify-between text-xl font-bold text-gray-900 border-t pt-2">
                    <span>Grand Total:</span>
                    <span>₹{(
                      formData.items.reduce((sum, item) => sum + item.totalPrice, 0) +
                      (formData.customsDuty || 0) +
                      (formData.otherCharges || 0)
                    ).toFixed(2)}</span>
                  </div>
                </div>
              </div>
            </div>

            <div className="p-6 border-t border-gray-200 flex justify-end gap-4 flex-shrink-0 bg-white">
              <button
                onClick={() => {
                  setShowModal(false);
                  resetForm();
                }}
                className="px-6 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
              >
                Cancel
              </button>
              {editingMode === 'tracking' && editingPOId ? (
                <button
                  onClick={() => handleSaveTracking(editingPOId)}
                  disabled={submitting}
                  className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {submitting ? 'Saving...' : 'Save Tracking Info'}
                </button>
              ) : editingMode === 'edit' && editingPOId ? (
                <button
                  onClick={() => handleUpdateOrder(editingPOId)}
                  disabled={submitting}
                  className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {submitting ? 'Saving...' : 'Save Changes'}
                </button>
              ) : (
                <button
                  onClick={handleCreateOrder}
                  disabled={submitting}
                  className="px-6 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {submitting ? 'Creating...' : 'Create Purchase Order'}
                </button>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Drawing Manager Modal - Mandatory for PO items */}
      {showDrawingManager && selectedItemForDrawing && (
        <DrawingManager
          itemId={selectedItemForDrawing.id}
          itemCode={selectedItemForDrawing.code}
          itemName={selectedItemForDrawing.name}
          onClose={() => {
            setShowDrawingManager(false);
            setSelectedItemForDrawing(null);
            setPendingItemIndex(null);

            // Context-aware message
            if (showModal && editingMode === 'create') {
              setAlertMessage({ type: 'info', message: 'Drawing uploaded! Please try creating the PO again.' });
            } else {
              setAlertMessage({ type: 'success', message: 'Drawing updated successfully.' });
            }
          }}
          mandatory={selectedItemForDrawing.mandatory}
        />
      )}

      {/* View Details Modal */}
      {showViewModal && selectedPO && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg max-w-4xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b border-gray-200 flex justify-between items-center">
              <h2 className="text-2xl font-bold text-gray-900">Purchase Order Details</h2>
              <button onClick={() => setShowViewModal(false)} className="text-gray-500 hover:text-gray-700">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>

            <div className="p-6 space-y-6">
              {/* Header Info */}
              <div className="grid grid-cols-2 gap-6">
                <div>
                  <p className="text-sm text-gray-600">PO Number</p>
                  <p className="font-semibold text-lg">{selectedPO.po_number}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-600">PR Reference</p>
                  <p className="font-semibold">{selectedPO.pr?.pr_number || '-'}</p>
                  {selectedPO.is_partial_po && (
                    <span className="inline-block mt-1 px-2 py-0.5 text-xs font-semibold rounded bg-yellow-100 text-yellow-800">
                      Partial PO
                    </span>
                  )}
                </div>
                <div>
                  <p className="text-sm text-gray-600">Status</p>
                  <span className={`inline-block px-3 py-1 text-xs font-semibold rounded-full ${getStatusColor(selectedPO.status)}`}>
                    {selectedPO.status}
                  </span>
                </div>
                {selectedPO.edit_count != null && selectedPO.edit_count > 0 && (
                  <div>
                    <p className="text-sm text-gray-600">Edits</p>
                    <p className="font-semibold">{selectedPO.edit_count} time{selectedPO.edit_count !== 1 ? 's' : ''}</p>
                  </div>
                )}
                {selectedPO.last_edited_at && (
                  <div>
                    <p className="text-sm text-gray-600">Last Edited</p>
                    <p className="font-semibold">{new Date(selectedPO.last_edited_at).toLocaleDateString()} {new Date(selectedPO.last_edited_at).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                  </div>
                )}
              </div>
              <div className="grid grid-cols-2 gap-6">
                <div>
                  <p className="text-sm text-gray-600">Vendor</p>
                  <p className="font-semibold">{(selectedPO as any)?.vendor?.name || (selectedPO as any)?.vendor_name || '-'}</p>
                  <p className="text-sm text-gray-500">{(selectedPO as any)?.vendor?.contact_person || (selectedPO as any)?.vendor_contact_person || ''}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-600">Order Date</p>
                  <p className="font-semibold">{selectedPO.po_date ? new Date(selectedPO.po_date).toLocaleDateString() : '-'}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-600">Expected Delivery</p>
                  <p className="font-semibold">{selectedPO.delivery_date ? new Date(selectedPO.delivery_date).toLocaleDateString() : '-'}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-600">Total Amount</p>
                  <p className="font-semibold text-lg">₹{selectedPO.total_amount?.toLocaleString() || 0}</p>
                </div>
              </div>

              {/* Items Table */}
              <div>
                <h3 className="text-lg font-semibold mb-3">Items</h3>
                <div className="border rounded-lg overflow-hidden">
                  <table className="w-full">
                    <thead className="bg-gray-50">
                      <tr>
                        <th className="px-4 py-2 text-center text-xs font-medium text-gray-700">S.No</th>
                        <th className="px-4 py-2 text-left text-xs font-medium text-gray-700">Item</th>
                        <th className="px-4 py-2 text-left text-xs font-medium text-gray-700">Drawing</th>
                        <th className="px-4 py-2 text-right text-xs font-medium text-gray-700">Quantity</th>
                        <th className="px-4 py-2 text-center text-xs font-medium text-gray-700">UOM</th>
                        <th className="px-4 py-2 text-right text-xs font-medium text-gray-700">Rate</th>
                        <th className="px-4 py-2 text-right text-xs font-medium text-gray-700">Amount</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y">
                      {selectedPO.purchase_order_items && selectedPO.purchase_order_items.length > 0 ? (
                        selectedPO.purchase_order_items.map((item: any, idx: number) => (
                          <tr key={idx}>
                            <td className="px-4 py-2 text-center text-sm">{item.serial_no || idx + 1}</td>
                            <td className="px-4 py-2">
                              <div className="font-medium">{item.item?.name || item.item_name || '-'}</div>
                              <div className="text-xs text-gray-500">{item.item?.code || item.item_code || ''}</div>
                            </td>
                            <td className="px-4 py-2">
                              {(() => {
                                const itemCode = item.item?.code || item.item_code;
                                const itemId = item.item_id || item.itemId || item.item?.id;
                                const masterItem = items.find((i) => i.id === itemId || i.code === itemCode);
                                const drawingRequired = masterItem?.drawing_required || 'OPTIONAL';
                                const resolvedItemId = masterItem?.id || itemId;

                                if (!resolvedItemId) {
                                  return <span className="text-xs text-gray-500">-</span>;
                                }

                                return (
                                  <div className="flex items-center justify-between gap-2">
                                    <span className={`text-xs px-2 py-0.5 rounded ${
                                      drawingRequired === 'COMPULSORY'
                                        ? 'bg-red-100 text-red-800'
                                        : 'bg-gray-100 text-gray-700'
                                    }`}>
                                      {drawingRequired}
                                    </span>
                                    <button
                                      type="button"
                                      onClick={() => {
                                        setSelectedItemForDrawing({
                                          id: resolvedItemId,
                                          code: masterItem?.code || itemCode || '',
                                          name: masterItem?.name || item.item?.name || item.item_name || '',
                                          mandatory: drawingRequired === 'COMPULSORY',
                                        });
                                        setShowDrawingManager(true);
                                      }}
                                      className="text-xs text-amber-700 hover:text-amber-900 font-medium"
                                    >
                                      Manage Drawings
                                    </button>
                                  </div>
                                );
                              })()}
                            </td>
                            <td className="px-4 py-2 text-right">{item.quantity || item.ordered_qty || 0}</td>
                            <td className="px-4 py-2 text-center text-sm">{item.uom || item.item?.uom || '-'}</td>
                            <td className="px-4 py-2 text-right">
                              <div>₹{(item.rate || 0).toLocaleString()}</div>
                              {(() => {
                                const vendorId = resolveVendorIdFromPO(selectedPO);
                                const itemId = resolveItemIdFromPOLine(item);

                                // Always show some message under Rate
                                if (!vendorId || !itemId) {
                                  return <div className="mt-0.5 ml-auto max-w-[160px] break-words text-[11px] leading-tight text-gray-500">Last purchase price not available</div>;
                                }

                                const key = `${itemId}-${vendorId}`;
                                const history = priceHistory[key];
                                if (!history) return <div className="mt-0.5 ml-auto max-w-[160px] break-words text-[11px] leading-tight text-gray-500">Last: Loading...</div>;
                                const last = history?.[0];
                                if (!last) return <div className="mt-0.5 ml-auto max-w-[160px] break-words text-[11px] leading-tight text-gray-500">Last purchase price not available</div>;
                                return (
                                  <div className="mt-0.5 ml-auto max-w-[160px] break-words text-[11px] leading-tight text-gray-600">
                                    Last: <span className="font-medium text-gray-800">₹{Number(last.unit_price || 0).toFixed(2)}</span>
                                  </div>
                                );
                              })()}
                            </td>
                            <td className="px-4 py-2 text-right font-medium">₹{(item.amount || 0).toLocaleString()}</td>
                          </tr>
                        ))
                      ) : (
                        <tr>
                          <td colSpan={5} className="px-4 py-8 text-center text-gray-500">No items found</td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </div>

              {/* Tracking Information */}
              {(selectedPO as any).status && (selectedPO as any).status !== 'DRAFT' && (
                <div className="border-t pt-4">
                  <h3 className="text-lg font-semibold mb-3">Tracking Information</h3>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <p className="text-sm text-gray-600">Tracking Number</p>
                      <p className="font-semibold">{(selectedPO as any).tracking_number || '-'}</p>
                      {!(selectedPO as any).tracking_number && (
                        <p className="text-xs text-gray-500 mt-1">No tracking added yet</p>
                      )}
                    </div>
                    <div>
                      <p className="text-sm text-gray-600">Delivery Status</p>
                      <span className={`inline-block px-2 py-1 text-xs font-semibold rounded ${
                        (selectedPO as any).delivery_status === 'DELIVERED' ? 'bg-green-100 text-green-800' :
                        (selectedPO as any).delivery_status === 'SHIPPED' ? 'bg-blue-100 text-blue-800' :
                        (selectedPO as any).delivery_status === 'DELAYED' ? 'bg-red-100 text-red-800' :
                        'bg-gray-100 text-gray-800'
                      }`}>
                        {(selectedPO as any).delivery_status || 'PENDING'}
                      </span>
                    </div>
                    {(selectedPO as any).carrier_name && (
                      <div>
                        <p className="text-sm text-gray-600">Carrier</p>
                        <p className="font-semibold">{(selectedPO as any).carrier_name}</p>
                      </div>
                    )}
                    {(selectedPO as any).shipped_date && (
                      <div>
                        <p className="text-sm text-gray-600">Shipped Date</p>
                        <p className="font-semibold">{new Date((selectedPO as any).shipped_date).toLocaleDateString()}</p>
                      </div>
                    )}
                    {(selectedPO as any).estimated_delivery_date && (
                      <div>
                        <p className="text-sm text-gray-600">Estimated Delivery</p>
                        <p className="font-semibold">{new Date((selectedPO as any).estimated_delivery_date).toLocaleDateString()}</p>
                      </div>
                    )}
                    {(selectedPO as any).tracking_url && (
                      <div className="col-span-2">
                        <p className="text-sm text-gray-600 mb-1">Track Shipment</p>
                        <a 
                          href={(selectedPO as any).tracking_url} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          className="text-blue-600 hover:text-blue-800 underline text-sm"
                        >
                          {(selectedPO as any).tracking_url}
                        </a>
                      </div>
                    )}
                  </div>
                </div>
              )}

              {/* Notes */}
              {selectedPO.remarks && (
                <div>
                  <p className="text-sm text-gray-600 mb-2">Remarks</p>
                  <p className="text-gray-800">{selectedPO.remarks}</p>
                </div>
              )}
            </div>

            <div className="p-6 border-t border-gray-200 flex justify-between">
              <div className="flex gap-3">
                {selectedPO.status === 'DRAFT' && (
                  <>
                    <button
                      onClick={() => {
                        setShowViewModal(false);
                        handleEditDetails(selectedPO.id, 'edit');
                      }}
                      className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
                    >
                      Edit
                    </button>
                    <button
                      onClick={async () => {
                        try {
                          const token = localStorage.getItem('accessToken');
                          const response = await fetch(`/api/v1/purchase/orders/${selectedPO.id}/status`, {
                            method: 'POST',
                            headers: {
                              'Content-Type': 'application/json',
                              Authorization: `Bearer ${token}`,
                            },
                            body: JSON.stringify({ status: 'APPROVED' }),
                          });
                          if (response.ok) {
                            setAlertMessage({ type: 'success', message: 'Purchase Order approved successfully!' });
                            setShowViewModal(false);
                            fetchOrders();
                          } else {
                            const errorData = await response.json();
                            console.error('Approve failed:', errorData);
                            setAlertMessage({ type: 'error', message: `Failed to approve PO: ${errorData.message || 'Unknown error'}` });
                          }
                        } catch (error) {
                          console.error('Error approving PO:', error);
                          setAlertMessage({ type: 'error', message: 'Error approving PO' });
                        }
                      }}
                      className="px-6 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700"
                    >
                      Approve
                    </button>
                    <button
                      onClick={async () => {
                        try {
                          const token = localStorage.getItem('accessToken');
                          const response = await fetch(`/api/v1/purchase/orders/${selectedPO.id}/status`, {
                            method: 'POST',
                            headers: {
                              'Content-Type': 'application/json',
                              Authorization: `Bearer ${token}`,
                            },
                            body: JSON.stringify({ status: 'REJECTED' }),
                          });
                          if (response.ok) {
                            setAlertMessage({ type: 'success', message: 'Purchase Order rejected successfully!' });
                            setShowViewModal(false);
                            fetchOrders();
                          } else {
                            const errorData = await response.json();
                            console.error('Reject failed:', errorData);
                            setAlertMessage({ type: 'error', message: `Failed to reject PO: ${errorData.message || 'Unknown error'}` });
                          }
                        } catch (error) {
                          console.error('Error rejecting PO:', error);
                          setAlertMessage({ type: 'error', message: 'Error rejecting PO' });
                        }
                      }}
                      className="px-6 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700"
                    >
                      Reject
                    </button>
                  </>
                )}

                {selectedPO.status !== 'DRAFT' && (
                  <>
                    <button
                      onClick={() => handlePreviewPOEmail(selectedPO.id)}
                      disabled={poEmailPreviewLoading}
                      className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      {poEmailPreviewLoading ? 'Generating...' : 'Preview Email'}
                    </button>
                    <button
                      onClick={() => {
                        setShowViewModal(false);
                        handleEditDetails(selectedPO.id, 'tracking');
                      }}
                      className="px-6 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700"
                    >
                      Update Tracking
                    </button>
                  </>
                )}
              </div>
              <button
                onClick={() => setShowViewModal(false)}
                className="px-6 py-2 bg-gray-200 text-gray-800 rounded-lg hover:bg-gray-300"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* PO Email Preview Modal */}
      {showPOEmailPreview && poEmailPreview && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[60] p-4">
          <div className="bg-white rounded-lg shadow-xl max-w-5xl w-full max-h-[90vh] overflow-y-auto">
            <div className="sticky top-0 bg-white border-b px-6 py-4 flex justify-between items-center">
              <h2 className="text-2xl font-bold text-amber-900">PO Email Preview</h2>
              <button
                type="button"
                onClick={() => {
                  setShowPOEmailPreview(false);
                  setPoEmailPreview(null);
                  setPoEmailTo('');
                  setPoEmailSubject('');
                  setPoEmailMessage('');
                }}
                className="text-gray-500 hover:text-gray-700 text-2xl"
              >
                ×
              </button>
            </div>

            {(() => {
              const preview = poEmailPreview?.preview || poEmailPreview;
              const poId = String(poEmailPreview?.po_id || selectedPO?.id || '');
              const html = String(preview?.html || '');

              return (
                <div className="p-6 space-y-4">
                  <div className="bg-gray-50 p-4 rounded-lg text-sm space-y-1">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                      <label className="block">
                        <span className="font-semibold">To</span>
                        <input
                          className="mt-1 w-full border rounded px-3 py-2"
                          value={poEmailTo}
                          onChange={(e) => setPoEmailTo(e.target.value)}
                          placeholder="vendor@email.com"
                        />
                      </label>

                      <label className="block">
                        <span className="font-semibold">Subject</span>
                        <input
                          className="mt-1 w-full border rounded px-3 py-2"
                          value={poEmailSubject}
                          onChange={(e) => setPoEmailSubject(e.target.value)}
                          placeholder="Subject"
                        />
                      </label>
                    </div>

                    <label className="block mt-2">
                      <span className="font-semibold">Message (optional)</span>
                      <textarea
                        className="mt-1 w-full border rounded px-3 py-2"
                        rows={3}
                        value={poEmailMessage}
                        onChange={(e) => setPoEmailMessage(e.target.value)}
                        placeholder="Add a short note to the vendor..."
                      />
                    </label>

                    <div className="flex justify-end mt-2">
                      <button
                        type="button"
                        onClick={handleUpdatePOEmailPreview}
                        disabled={poEmailPreviewLoading}
                        className={`px-4 py-2 rounded-lg transition-colors text-sm ${
                          poEmailPreviewLoading
                            ? 'bg-gray-300 text-gray-600'
                            : 'bg-blue-600 text-white hover:bg-blue-700'
                        }`}
                      >
                        {poEmailPreviewLoading ? 'Updating...' : 'Update Preview'}
                      </button>
                    </div>

                    <div>
                      <span className="font-semibold">From:</span> {String(preview?.from || '')}
                    </div>
                    {preview?.replyTo && (
                      <div>
                        <span className="font-semibold">Reply-To:</span> {String(preview.replyTo)}
                      </div>
                    )}
                    {Array.isArray(preview?.attachments) && preview.attachments.length > 0 && (
                      <div>
                        <span className="font-semibold">Attachments:</span> {preview.attachments.join(', ')}
                      </div>
                    )}
                  </div>

                  <div className="border rounded-lg overflow-hidden bg-white">
                    <iframe
                      title="PO Email Preview"
                      className="w-full h-[60vh]"
                      srcDoc={html}
                      sandbox=""
                      referrerPolicy="no-referrer"
                    />
                  </div>

                  <div className="sticky bottom-0 bg-white border-t -mx-6 px-6 py-4 flex justify-end gap-3">
                    <button
                      onClick={() => {
                        setShowPOEmailPreview(false);
                        setPoEmailPreview(null);
                        setPoEmailTo('');
                        setPoEmailSubject('');
                        setPoEmailMessage('');
                      }}
                      className="px-6 py-2 bg-gray-300 text-gray-700 rounded-lg hover:bg-gray-400 transition-colors"
                    >
                      Cancel
                    </button>
                    <button
                      onClick={() => handleSendPOEmail(poId)}
                      disabled={poEmailSending || !poId || !poEmailTo.trim()}
                      className={`px-6 py-2 rounded-lg transition-colors ${
                        poEmailSending || !poId || !poEmailTo.trim()
                          ? 'bg-gray-300 text-gray-600'
                          : 'bg-green-600 text-white hover:bg-green-700'
                      }`}
                    >
                      {poEmailSending ? 'Sending...' : 'Confirm & Send PO Email'}
                    </button>
                  </div>
                </div>
              );
            })()}
          </div>
        </div>
      )}

      {/* Alert Popup */}
      {alertMessage && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-xl max-w-md w-full mx-4 p-6">
            <div className="flex items-start">
              <div className={`flex-shrink-0 ${
                alertMessage.type === 'success' ? 'text-green-500' :
                alertMessage.type === 'error' ? 'text-red-500' :
                'text-blue-500'
              }`}>
                {alertMessage.type === 'success' && (
                  <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                )}
                {alertMessage.type === 'error' && (
                  <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2m7-2a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                )}
                {alertMessage.type === 'info' && (
                  <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                )}
              </div>
              <div className="ml-3 flex-1">
                <h3 className={`text-sm font-medium ${
                  alertMessage.type === 'success' ? 'text-green-800' :
                  alertMessage.type === 'error' ? 'text-red-800' :
                  'text-blue-800'
                }`}>
                  {alertMessage.type === 'success' ? 'Success' :
                   alertMessage.type === 'error' ? 'Error' :
                   'Information'}
                </h3>
                <div className="mt-2 text-sm text-gray-700">
                  {alertMessage.message}
                </div>
              </div>
            </div>
            <div className="mt-4">
              <button
                onClick={() => setAlertMessage(null)}
                className={`w-full px-4 py-2 text-sm font-medium text-white rounded-md ${
                  alertMessage.type === 'success' ? 'bg-green-600 hover:bg-green-700' :
                  alertMessage.type === 'error' ? 'bg-red-600 hover:bg-red-700' :
                  'bg-blue-600 hover:bg-blue-700'
                }`}
              >
                OK
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Duplicate Warning Modal */}
      <DuplicateWarning
        isOpen={duplicateState.isOpen}
        exactMatches={duplicateState.exactMatches}
        fuzzyMatches={duplicateState.fuzzyMatches}
        entityType="Purchase Order"
        onProceed={handleProceed}
        onCancel={handleCancel}
        formatRecord={(data) => (
          <div className="text-sm">
            <p className="font-semibold">PO #{data.po_number}</p>
            <p className="text-xs text-gray-600">Vendor: {data.vendor?.name}</p>
            <p className="text-xs text-gray-600">Items: {data.purchase_order_items?.length || 0}</p>
            <p className="text-xs text-gray-600">Total: ₹{data.total_amount?.toLocaleString()}</p>
            <p className="text-xs text-gray-600">Date: {new Date(data.po_date).toLocaleDateString()}</p>
          </div>
        )}
      />
    </div>
  );
}

export default function PurchaseOrdersPage() {
