}

'use client';

import { useRouter } from 'next/navigation';
import { useState, useEffect } from 'react';
import { apiClient } from '../../../../lib/api-client';

export default function PurchasePage() {
  const router = useRouter();
  const [stats, setStats] = useState({
    pendingPRs: 0,
    activePOs: 0,
    activeVendors: 0,
    pendingGRNs: 0,
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchStats();
  }, []);

  const fetchStats = async () => {
    try {
      setLoading(true);
      
      // Fetch all statistics in parallel
      const [prs, pos, vendors, grns] = await Promise.all([
        apiClient.get('/purchase/requisitions').catch(() => []),
        apiClient.get('/purchase/orders').catch(() => []),
        apiClient.get('/purchase/vendors').catch(() => []),
        apiClient.get('/purchase/grn').catch(() => []),
      ]);

      setStats({
        pendingPRs: Array.isArray(prs)
          ? prs.filter((pr: any) => {
              const status = String(pr?.status ?? '').toUpperCase();
              return status === 'DRAFT' || status === 'SUBMITTED' || status === 'PENDING';
            }).length
          : 0,
        activePOs: Array.isArray(pos) ? pos.filter((po: any) => po.status === 'APPROVED' || po.status === 'PARTIAL').length : 0,
        activeVendors: Array.isArray(vendors) ? vendors.filter((v: any) => v.is_active).length : 0,
        pendingGRNs: Array.isArray(grns) ? grns.filter((grn: any) => grn.status === 'DRAFT' || grn.status === 'PENDING').length : 0,
      });
    } catch (error) {
      console.error('Error fetching purchase stats:', error);
    } finally {
      setLoading(false);
    }
  };

  const modules = [
    {
      title: 'Purchase Requisitions',
      description: 'Create and manage purchase requisition requests',
      icon: '📝',
      path: '/dashboard/purchase/requisitions',
      color: 'bg-blue-50 hover:bg-blue-100 border-blue-200',
    },
    {
      title: 'Purchase Orders',
      description: 'Manage purchase orders to vendors',
      icon: '📋',
      path: '/dashboard/purchase/orders',
      color: 'bg-green-50 hover:bg-green-100 border-green-200',
    },
    {
      title: 'Vendors',
      description: 'Manage vendor information and relationships',
      icon: '🏢',
      path: '/dashboard/purchase/vendors',
      color: 'bg-purple-50 hover:bg-purple-100 border-purple-200',
    },
    {
      title: 'GRN (Goods Receipt)',
      description: 'Record goods received from vendors',
      icon: '📦',
      path: '/dashboard/purchase/grn',
      color: 'bg-orange-50 hover:bg-orange-100 border-orange-200',
    },
  ];

  return (
    <div className="min-h-screen bg-gradient-to-br from-amber-50 via-orange-50 to-yellow-50 p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <button
            onClick={() => router.push('/dashboard')}
            className="text-amber-800 hover:text-amber-900 mb-4 flex items-center gap-2"
          >
            ← Back to Dashboard
          </button>
          <h1 className="text-4xl font-bold text-amber-900 mb-2">Purchase Management</h1>
          <p className="text-amber-700">Manage procurement, vendors, and purchase workflows</p>
        </div>

        {/* Module Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {modules.map((module) => (
            <div
              key={module.path}
              onClick={() => router.push(module.path)}
              className={`${module.color} border-2 rounded-lg p-6 cursor-pointer transition-all hover:shadow-lg`}
            >
              <div className="text-4xl mb-4">{module.icon}</div>
              <h3 className="text-xl font-bold text-amber-900 mb-2">{module.title}</h3>
              <p className="text-sm text-amber-700">{module.description}</p>
            </div>
          ))}
        </div>

        {/* Quick Stats */}
        <div className="mt-8 grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="bg-white rounded-lg shadow p-4 border-l-4 border-blue-500">
            <div className="text-sm text-gray-600">Pending PRs</div>
            <div className="text-2xl font-bold text-gray-900">
              {loading ? '...' : stats.pendingPRs}
            </div>
          </div>
          <div className="bg-white rounded-lg shadow p-4 border-l-4 border-green-500">
            <div className="text-sm text-gray-600">Active POs</div>
            <div className="text-2xl font-bold text-gray-900">
              {loading ? '...' : stats.activePOs}
            </div>
          </div>
          <div className="bg-white rounded-lg shadow p-4 border-l-4 border-purple-500">
            <div className="text-sm text-gray-600">Active Vendors</div>
            <div className="text-2xl font-bold text-gray-900">
              {loading ? '...' : stats.activeVendors}
            </div>
          </div>
          <div className="bg-white rounded-lg shadow p-4 border-l-4 border-orange-500">
            <div className="text-sm text-gray-600">Pending GRNs</div>
            <div className="text-2xl font-bold text-gray-900">
              {loading ? '...' : stats.pendingGRNs}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useRef } from 'react';
import { useRouter } from 'next/navigation';
import { apiClient } from '../../../../../lib/api-client';
import DuplicateWarning, { useDuplicateDetection } from '../../../../components/DuplicateWarning';

interface PRItem {
  id: string;
  itemCode?: string;
  itemName: string;
  uom?: string;
  vendorId?: string;
  vendorName?: string;
  quantity: number;
  estimatedPrice?: number;
  specifications?: string;
  paymentTerms?: string;
  deliveryTerms?: string;
}

interface Item {
  id: string;
  code: string;
  name: string;
  uom: string;
  standard_cost?: number;
}

type RawItem = Record<string, any>;

interface Requisition {
  id: string;
  pr_number: string;
  department: string;
  request_date: string;
  required_date: string;
  status: string;
  priority?: string;
  purpose?: string;
  requested_by: string;
  created_at: string;
}

interface PRDetailItem {
  id: string;
  item_id?: string;
  item_code: string;
  item_name: string;
  uom?: string;
  serial_no?: number;
  vendor_id?: string | null;
  requested_qty: number;
  estimated_rate: number;
  total_amount: number;
  total_ordered_qty?: number;
  remaining_qty?: number;
  po_conversion_status?: string;
  remarks?: string;
  payment_terms?: string;
  delivery_terms?: string;
  updated_at?: string;
  updated_by?: string;
}

interface PRDetail {
  id: string;
  pr_number: string;
  department: string;
  request_date: string;
  required_date: string;
  status: string;
  priority?: string;
  purpose?: string;
  requested_by: string;
  approved_by?: string;
  approved_at?: string;
  updated_by?: string;
  edit_count?: number;
  last_edited_at?: string;
  purchase_requisition_items: PRDetailItem[];
}

interface Vendor {
  id: string;
  code: string;
  name: string;
  email: string;
  is_active: boolean;
}

function PRContent() {
  const { duplicateState, checkDuplicates, handleProceed, handleCancel } = useDuplicateDetection();
  const router = useRouter();
  const dropdownRef = useRef<HTMLDivElement>(null);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [items, setItems] = useState<PRItem[]>([]);
  const [requisitions, setRequisitions] = useState<Requisition[]>([]);
  const [loadingRequisitions, setLoadingRequisitions] = useState(true);
  const [filterStatus, setFilterStatus] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedPR, setSelectedPR] = useState<PRDetail | null>(null);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [loadingDetail, setLoadingDetail] = useState(false);
  const [editingItemId, setEditingItemId] = useState<string | null>(null);
  const [editingPRId, setEditingPRId] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    department: '',
    requiredDate: '',
    priority: 'MEDIUM',
    notes: '',
  });

  const [itemForm, setItemForm] = useState({
    itemName: '',
    vendorId: '',
    vendorName: '',
    quantity: '',
    uom: '',
    estimatedPrice: '',
    specifications: '',
    paymentTerms: '',
    deliveryTerms: '',
  });

  const [masterItems, setMasterItems] = useState<Item[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [showDropdown, setShowDropdown] = useState(false);
  const [useManualEntry, setUseManualEntry] = useState(false);
  const [selectedItemId, setSelectedItemId] = useState<string | null>(null);
  const [itemsLoadError, setItemsLoadError] = useState<string | null>(null);
  const [lastPurchasePrice, setLastPurchasePrice] = useState<{
    unit_price: number;
    po_number?: string;
    po_date?: string;
  } | null>(null);

  const [rfqPanelOpen, setRfqPanelOpen] = useState(false);
  const [rfqVendors, setRfqVendors] = useState<Vendor[]>([]);
  const [rfqItemVendors, setRfqItemVendors] = useState<Record<string, string[]>>({});
  const [rfqLoadingVendors, setRfqLoadingVendors] = useState(false);
  const [rfqSending, setRfqSending] = useState(false);
  const [rfqResponseDate, setRfqResponseDate] = useState('');
  const [rfqRemarks, setRfqRemarks] = useState('');
  const [rfqRecipientOverrides, setRfqRecipientOverrides] = useState<Record<string, string>>({});
  const [rfqSubjectOverride, setRfqSubjectOverride] = useState('');
  const [rfqCustomMessage, setRfqCustomMessage] = useState('');
  const [showRfqPreview, setShowRfqPreview] = useState(false);
  const [rfqPreviewData, setRfqPreviewData] = useState<any>(null);
  const [rfqPreviewIndex, setRfqPreviewIndex] = useState(0);
  const [rfqPreviewLoading, setRfqPreviewLoading] = useState(false);

  // Helper to get selected vendor IDs
  const getSelectedVendorIds = () => {
    const allVendorIds = Object.values(rfqItemVendors).flat().filter(Boolean);
    return Array.from(new Set(allVendorIds));
  };

  useEffect(() => {
    fetchRequisitions();
  }, []);

  useEffect(() => {
    if (showCreateForm) {
      fetchMasterItems();
      if (rfqVendors.length === 0) {
        fetchRFQVendors();
      }
    }
  }, [showCreateForm]);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setShowDropdown(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const fetchRequisitions = async () => {
    try {
      setLoadingRequisitions(true);
      const response = await apiClient.get('/purchase/requisitions');
      setRequisitions(Array.isArray(response) ? response : []);
    } catch (error: any) {
      console.error('Error fetching requisitions:', error);
    } finally {
      setLoadingRequisitions(false);
    }
  };

  const fetchMasterItems = async () => {
    try {
      setItemsLoadError(null);
      const response = await apiClient.get('/inventory/items');
      // apiClient.get already unwraps the data, so response is the array directly.
      // Normalize field names because some APIs return item_id/item_code/etc.
      const list = Array.isArray(response) ? (response as RawItem[]) : [];
      const normalized: Item[] = list
        .map((raw) => ({
          id: String(raw.id ?? raw.item_id ?? ''),
          code: String(raw.code ?? raw.item_code ?? ''),
          name: String(raw.name ?? raw.item_name ?? ''),
          uom: String(raw.uom ?? raw.unit ?? raw.unit_of_measure ?? ''),
          standard_cost:
            typeof raw.standard_cost === 'number'
              ? raw.standard_cost
              : typeof raw.standardCost === 'number'
                ? raw.standardCost
                : undefined,
        }))
        .filter((i) => i.id && i.code && i.name);

      setMasterItems(normalized);
    } catch (error: any) {
      console.error('Error fetching items:', error);
      if (error.message && (error.message.includes('401') || error.message.includes('Unauthorized'))) {
        setItemsLoadError('Session expired. Please refresh the page and login again.');
      } else {
        setItemsLoadError('Failed to load items. Please try again.');
      }
    }
  };

  const filteredItems = masterItems.filter(item => {
    if (!searchTerm) return true; // Show all items when no search term
    const search = searchTerm.toLowerCase();
    return (
      item.name.toLowerCase().includes(search) ||
      item.code.toLowerCase().includes(search) ||
      (item.uom && item.uom.toLowerCase().includes(search))
    );
  });

  const selectItem = async (item: Item) => {
    setSelectedItemId(item.id);
    setSearchTerm(`${item.code} - ${item.name}`);
    setShowDropdown(false);
    setLastPurchasePrice(null);

    // Fetch preferred vendor
    try {
      const preferredVendor = await apiClient.get(`/items/${item.id}/vendors/preferred`);
      
      if (preferredVendor) {
        const preferredVendorId =
          preferredVendor.vendor_id ??
          preferredVendor.vendorId ??
          preferredVendor.id ??
          '';

        const preferredVendorName =
          preferredVendor.vendor_name ??
          preferredVendor.vendorName ??
          preferredVendor.name ??
          '';

        // Try last purchase price (item + preferred vendor). If available, prefer it.
        let lastUnitPrice: number | null = null;
        if (preferredVendorId) {
          try {
            const history = await apiClient.get<
              Array<{ po_number?: string; po_date?: string; unit_price: number; quantity?: number; po_status?: string }>
            >(`/items/${item.id}/vendors/${String(preferredVendorId)}/price-history`);

            const last = Array.isArray(history) ? history[0] : null;
            if (last && typeof last.unit_price === 'number' && !Number.isNaN(last.unit_price)) {
              lastUnitPrice = Number(last.unit_price);
              setLastPurchasePrice({
                unit_price: lastUnitPrice,
                po_number: last.po_number,
                po_date: last.po_date,
              });
            }
          } catch (error) {
            console.error('Error fetching last purchase price:', error);
          }
        }

        setItemForm((prev) => ({
          ...prev,
          itemName: `${item.code} - ${item.name}`,
          uom: item.uom || '',
          vendorId: preferredVendorId ? String(preferredVendorId) : '',
          vendorName: preferredVendorName || '',
          estimatedPrice:
            (lastUnitPrice !== null
              ? String(lastUnitPrice)
              : preferredVendor.unit_price?.toString() || item.standard_cost?.toString()) ||
            '',
        }));
      } else {
        setLastPurchasePrice(null);
        setItemForm((prev) => ({
          ...prev,
          itemName: `${item.code} - ${item.name}`,
          uom: item.uom || '',
          vendorId: '',
          vendorName: '',
          estimatedPrice: item.standard_cost?.toString() || '',
        }));
      }
    } catch (error) {
      console.error('Error fetching preferred vendor:', error);
      // Fallback to item without vendor
      setLastPurchasePrice(null);
      setItemForm((prev) => ({
        ...prev,
        itemName: `${item.code} - ${item.name}`,
        uom: item.uom || '',
        vendorId: '',
        vendorName: '',
        estimatedPrice: item.standard_cost?.toString() || '',
      }));
    }
  };

  const addItem = () => {
    if (!itemForm.quantity) {
      alert('Please enter quantity');
      return;
    }
    
    if (!itemForm.itemName && !searchTerm) {
      alert('Please search and select an item, or enter item name');
      return;
    }

    const selectedItem = masterItems.find(item => item.id === selectedItemId);

    // Check for duplicate items (only when selecting from master items, not manual entry)
    if (selectedItemId && !useManualEntry) {
      const duplicate = items.find(item => {
        const existingItemId = masterItems.find(mi => mi.code === item.itemCode)?.id;
        return existingItemId === selectedItemId;
      });
      
      if (duplicate) {
        alert('This item is already added to the requisition');
        return;
      }
    }

    const nextItem = {
      id: Date.now().toString(),
      itemCode: selectedItem?.code || '',
      itemName: useManualEntry ? itemForm.itemName : searchTerm,
      uom: useManualEntry ? (itemForm.uom || undefined) : (selectedItem?.uom || undefined),
      vendorId: itemForm.vendorId || undefined,
      vendorName: itemForm.vendorName || undefined,
      quantity: parseFloat(itemForm.quantity),
      estimatedPrice: itemForm.estimatedPrice ? parseFloat(itemForm.estimatedPrice) : undefined,
      specifications: itemForm.specifications,
      paymentTerms: itemForm.paymentTerms || undefined,
      deliveryTerms: itemForm.deliveryTerms || undefined,
    };

    setItems((prev) => [...prev, nextItem]);

    setItemForm({
      itemName: '',
      vendorId: '',
      vendorName: '',
      quantity: '',
      uom: '',
      estimatedPrice: '',
      specifications: '',
      paymentTerms: '',
      deliveryTerms: '',
    });
    setSearchTerm('');
    setSelectedItemId(null);
    setUseManualEntry(false);
    setLastPurchasePrice(null);
  };

  const resetItemEntry = () => {
    setItemForm({
      itemName: '',
      vendorId: '',
      vendorName: '',
      quantity: '',
      uom: '',
      estimatedPrice: '',
      specifications: '',
      paymentTerms: '',
      deliveryTerms: '',
    });
    setSearchTerm('');
    setSelectedItemId(null);
    setShowDropdown(false);
    setUseManualEntry(false);
    setLastPurchasePrice(null);
  };

  const removeItem = (id: string) => {
    setItems((prev) => prev.filter((item) => item.id !== id));
  };

  const editItem = (id: string) => {
    const item = items.find(it => it.id === id);
    if (!item) return;

    setEditingItemId(id);
    setItemForm({
      itemName: item.itemName,
      vendorId: item.vendorId || '',
      vendorName: item.vendorName || '',
      quantity: item.quantity.toString(),
      uom: item.uom || '',
      estimatedPrice: item.estimatedPrice?.toString() || '',
      specifications: item.specifications || '',
      paymentTerms: item.paymentTerms || '',
      deliveryTerms: item.deliveryTerms || '',
    });
    setSearchTerm(item.itemName);
    const matchedItem = masterItems.find(mi => mi.code === item.itemCode);
    if (matchedItem) {
      setSelectedItemId(matchedItem.id);
    }
  };

  const updateItem = () => {
    if (!editingItemId) return;
    
    if (!itemForm.quantity) {
      alert('Please enter quantity');
      return;
    }
    
    if (!itemForm.itemName && !searchTerm) {
      alert('Please search and select an item, or enter item name');
      return;
    }

    const selectedItem = masterItems.find(item => item.id === selectedItemId);

    // Check for duplicate items when changing selection (only when selecting from master items, not manual entry)
    if (selectedItemId && !useManualEntry) {
      const duplicate = items.find(item => {
        if (item.id === editingItemId) return false; // Skip the item being edited
        const existingItemId = masterItems.find(mi => mi.code === item.itemCode)?.id;
        return existingItemId === selectedItemId;
      });
      
      if (duplicate) {
        alert('This item is already added to the requisition');
        return;
      }
    }

    setItems(prev => prev.map(item => 
      item.id === editingItemId ? {
        ...item,
        itemCode: selectedItem?.code || item.itemCode,
        itemName: useManualEntry ? itemForm.itemName : searchTerm,
        uom: useManualEntry ? (itemForm.uom || item.uom) : (selectedItem?.uom || item.uom),
        vendorId: itemForm.vendorId || undefined,
        vendorName: itemForm.vendorName || undefined,
        quantity: parseFloat(itemForm.quantity),
        estimatedPrice: itemForm.estimatedPrice ? parseFloat(itemForm.estimatedPrice) : undefined,
        specifications: itemForm.specifications,
      } : item
    ));

    setEditingItemId(null);
    resetItemEntry();
  };

  const cancelEdit = () => {
    setEditingItemId(null);
    resetItemEntry();
  };

  const handleViewDetails = async (prId: string) => {
    setSelectedPR(null);
    setLoadingDetail(true);
    setShowDetailModal(true);
    setRfqPanelOpen(false);
    setRfqItemVendors({});
    setRfqResponseDate('');
    setRfqRemarks('');
    try {
      const data = await apiClient.get(`/purchase/requisitions/${prId}`);
      setSelectedPR(data);
    } catch (error) {
      console.error('Error fetching PR details:', error);
      alert('Failed to load PR details');
      setShowDetailModal(false);
    } finally {
      setLoadingDetail(false);
    }
  };

  const handleEditPR = async (prId: string) => {
    try {
      const data = await apiClient.get(`/purchase/requisitions/${prId}`);
      
      // Populate form with existing PR data
      setFormData({
        department: data.department,
        requiredDate: data.required_date.split('T')[0],
        priority: data.priority,
        notes: data.notes || '',
      });

      // Populate items (API may return purchase_requisition_items)
      const rawItems: any[] = Array.isArray(data?.purchase_requisition_items)
        ? data.purchase_requisition_items
        : Array.isArray(data?.items)
          ? data.items
          : [];

      const prItems: PRItem[] = rawItems.map((item: any) => ({
        id: String(item?.id || ''),
        itemCode: item?.item_code || item?.itemCode || '',
        itemName: item?.item_name || item?.itemName || '',
        uom: item?.uom || undefined,
        vendorId: item?.vendor_id || item?.vendorId || undefined,
        vendorName: item?.vendor_name || item?.vendorName || undefined,
        quantity: item?.requested_qty ?? item?.quantity ?? 0,
        estimatedPrice: item?.estimated_rate ?? item?.estimated_price ?? item?.estimatedPrice ?? undefined,
        specifications: item?.remarks || item?.specifications || '',
        paymentTerms: item?.payment_terms || item?.paymentTerms || undefined,
        deliveryTerms: item?.delivery_terms || item?.deliveryTerms || undefined,
      }));
      setItems(prItems);

      setEditingPRId(prId);
      setShowCreateForm(true);
    } catch (error) {
      console.error('Error loading PR for edit:', error);
      alert('Failed to load PR for editing');
    }
  };

  const resolveItemIdForPRItem = async (prItem: PRDetailItem): Promise<string | null> => {
    if (prItem.item_id) return prItem.item_id;

    const query = (prItem.item_code || prItem.item_name || '').trim();
    if (!query) return null;

    try {
      const results = await apiClient.get<Array<{ id: string; code: string; name: string }>>(
        `/items/search?q=${encodeURIComponent(query)}`,
      );
      const list = Array.isArray(results) ? results : [];

      const exactCode = prItem.item_code
        ? list.find((i) => i.code?.toLowerCase() === prItem.item_code.toLowerCase())
        : undefined;
      if (exactCode?.id) return exactCode.id;

      const exactName = prItem.item_name
        ? list.find((i) => i.name?.toLowerCase() === prItem.item_name.toLowerCase())
        : undefined;
      if (exactName?.id) return exactName.id;

      return list[0]?.id || null;
    } catch (error) {
      console.error('Error resolving item for RFQ preferred vendor:', error);
      return null;
    }
  };

  const fetchPreferredVendorsForPR = async (pr: PRDetail) => {
    const items = Array.isArray(pr.purchase_requisition_items) ? pr.purchase_requisition_items : [];
    if (items.length === 0) return;

    const itemIdCache = new Map<string, string | null>();
    const itemVendorMap: Record<string, string[]> = {};

    for (const prItem of items) {
      // If a vendor was already selected and saved with the PR item, prefer it.
      if (prItem.vendor_id) {
        itemVendorMap[prItem.id] = [prItem.vendor_id];
        continue;
      }

      const cacheKey = prItem.item_id || prItem.item_code || prItem.item_name || prItem.id;
      let itemId: string | null | undefined = itemIdCache.get(cacheKey);
      if (itemId === undefined) {
        itemId = await resolveItemIdForPRItem(prItem);
        itemIdCache.set(cacheKey, itemId);
      }

      if (!itemId) continue;

      try {
        const pref = await apiClient.get(`/items/${itemId}/vendors/preferred`);
        const vendorId = pref?.vendor_id;
        if (vendorId) {
          itemVendorMap[prItem.id] = [vendorId];
        }
      } catch (error) {
        console.error('Error fetching preferred vendor for item:', error);
        continue;
      }
    }

    // Set the per-item vendor selections
    setRfqItemVendors(itemVendorMap);
  };

  const fetchRFQVendors = async () => {
    try {
      setRfqLoadingVendors(true);
      const data = await apiClient.get<Vendor[]>('/purchase/vendors');
      const list = Array.isArray(data) ? data : [];
      setRfqVendors(list.filter((v) => v?.is_active !== false));
    } catch (error) {
      console.error('Error fetching vendors for RFQ:', error);
      alert('Failed to load vendors');
    } finally {
      setRfqLoadingVendors(false);
    }
  };

  const toggleItemVendor = (itemId: string, vendorId: string) => {
    setRfqItemVendors((prev) => {
      const currentVendors = prev[itemId] || [];
      const isSelected = currentVendors.includes(vendorId);
      
      return {
        ...prev,
        [itemId]: isSelected 
          ? currentVendors.filter(v => v !== vendorId)
          : [...currentVendors, vendorId]
      };
    });
  };

  const handlePreviewRFQ = async (options?: { keepIndex?: number }) => {
    if (!selectedPR) return;
    const selectedVendors = getSelectedVendorIds();
    if (selectedVendors.length === 0) {
      alert('Please select at least one vendor for the items');
      return;
    }

    // Create item-vendor assignments
    const itemVendorAssignments = selectedPR.purchase_requisition_items?.map((item) => ({
      item: item,
      vendorIds: rfqItemVendors[item.id] || []
    })) || [];

    // Create item-vendor assignments for API
    const itemVendorAssignmentsForApi = selectedPR.purchase_requisition_items?.map((item) => ({
      itemId: item.id,
      vendorIds: rfqItemVendors[item.id] || [],
    })) || [];

    try {
      setRfqPreviewLoading(true);
      const preview = await apiClient.post(`/purchase/requisitions/${selectedPR.id}/rfq/preview`, {
        vendorIds: selectedVendors,
        itemVendors: itemVendorAssignmentsForApi,
        responseDate: rfqResponseDate || undefined,
        remarks: rfqRemarks || undefined,
        recipientOverrides: rfqRecipientOverrides,
        subject: rfqSubjectOverride.trim() ? rfqSubjectOverride.trim() : undefined,
        customMessage: rfqCustomMessage || undefined,
      });

      const emailPreviews = Array.isArray(preview?.previews) ? preview.previews : [];
      const keepIndex = typeof options?.keepIndex === 'number' ? options.keepIndex : undefined;
      const nextIndex =
        typeof keepIndex === 'number'
          ? Math.min(Math.max(keepIndex, 0), Math.max(emailPreviews.length - 1, 0))
          : 0;

      setRfqPreviewIndex(nextIndex);
      setRfqPreviewData({
        pr: selectedPR,
        vendors: rfqVendors.filter((v) => selectedVendors.includes(v.id)),
        itemVendors: itemVendorAssignments,
        responseDate: rfqResponseDate,
        remarks: rfqRemarks,
        emailPreviews,
      });
      setShowRfqPreview(true);
    } catch (error) {
      console.error('Error previewing RFQ:', error);
      alert('Failed to generate RFQ preview');
    } finally {
      setRfqPreviewLoading(false);
    }
  };

  const handleSendRFQ = async () => {
    if (!selectedPR) return;
    const selectedVendors = getSelectedVendorIds();
    if (selectedVendors.length === 0) {
      alert('Please select at least one vendor for the items');
      return;
    }

    // Create item-vendor assignments for API
    const itemVendorAssignments = selectedPR.purchase_requisition_items?.map((item) => ({
      itemId: item.id,
      vendorIds: rfqItemVendors[item.id] || []
    })) || [];

    try {
      setRfqSending(true);
      const result = await apiClient.post(`/purchase/requisitions/${selectedPR.id}/rfq/send`, {
        vendorIds: selectedVendors,
        itemVendors: itemVendorAssignments,
        responseDate: rfqResponseDate || undefined,
        remarks: rfqRemarks || undefined,
        recipientOverrides: rfqRecipientOverrides,
        subject: rfqSubjectOverride.trim() ? rfqSubjectOverride.trim() : undefined,
        customMessage: rfqCustomMessage || undefined,
      });

      alert(`RFQ sent: ${result?.sent_count ?? 0}, failed: ${result?.failed_count ?? 0}`);
      setShowRfqPreview(false);
      setRfqPanelOpen(false);
      setRfqItemVendors({});
      setRfqResponseDate('');
      setRfqRemarks('');
      setRfqRecipientOverrides({});
      setRfqSubjectOverride('');
      setRfqCustomMessage('');
    } catch (error) {
      console.error('Error sending RFQ:', error);
      alert('Failed to send RFQ');
    } finally {
      setRfqSending(false);
    }
  };

  const handleApprove = async (prId: string) => {
    if (!confirm('Are you sure you want to approve this PR?')) return;
    try {
      await apiClient.post(`/purchase/requisitions/${prId}/approve`, {});
      alert('PR approved successfully!');
      setShowDetailModal(false);
      fetchRequisitions();
    } catch (error) {
      console.error('Error approving PR:', error);
      alert('Failed to approve PR');
    }
  };

  const handleReject = async (prId: string) => {
    const reason = prompt('Please enter rejection reason:');
    if (!reason) return;
    try {
      await apiClient.post(`/purchase/requisitions/${prId}/reject`, { reason });
      alert('PR rejected successfully!');
      setShowDetailModal(false);
      fetchRequisitions();
    } catch (error) {
      console.error('Error rejecting PR:', error);
      alert('Failed to reject PR');
    }
  };

  const handleDelete = async (prId: string) => {
    if (!confirm('Are you sure you want to delete this PR? This action cannot be undone.')) return;
    try {
      await apiClient.delete(`/purchase/requisitions/${prId}`);
      alert('PR deleted successfully!');
      setShowDetailModal(false);
      fetchRequisitions();
    } catch (error) {
      console.error('Error deleting PR:', error);
      alert('Failed to delete PR');
    }
  };

  const actuallySubmitPR = async (status: 'DRAFT' | 'SUBMITTED') => {
    try {
      const prData = {
        department: formData.department,
        requiredDate: formData.requiredDate,
        priority: formData.priority,
        purpose: formData.notes || null,
        status: status,
        items: items.map(item => ({
          itemCode: item.itemCode,
          itemName: item.itemName,
          vendorId: item.vendorId || null,
          uom: item.uom || null,
          requestedQty: item.quantity,
          estimatedRate: item.estimatedPrice || 0,
          description: item.specifications || null,
          remarks: item.specifications || null,
          paymentTerms: item.paymentTerms || null,
          deliveryTerms: item.deliveryTerms || null,
        })),
      };
      
      if (editingPRId) {
        await apiClient.put(`/purchase/requisitions/${editingPRId}`, prData);
        alert(`Purchase Requisition ${status === 'DRAFT' ? 'saved as draft' : 'updated'} successfully!`);
      } else {
        await apiClient.post('/purchase/requisitions', prData);
        alert(`Purchase Requisition ${status === 'DRAFT' ? 'saved as draft' : 'submitted'} successfully!`);
      }
      
      setShowCreateForm(false);
      setItems([]);
      setFormData({ department: '', requiredDate: '', priority: 'MEDIUM', notes: '' });
      setEditingPRId(null);
      fetchRequisitions(); // Refresh the list
    } catch (error: any) {
      console.error('Error saving PR:', error);
      alert('Failed to save purchase requisition. Please try again.');
    }
  };

  const handleSubmit = async (status: 'DRAFT' | 'SUBMITTED') => {
    // Skip duplicate check for updates or drafts
    if (editingPRId || status === 'DRAFT') {
      return actuallySubmitPR(status);
    }

    // Validate items before duplicate check
    if (items.length === 0) {
      alert('Please add at least one item');
      return;
    }

    // Prepare payload for duplicate check
    const checkPayload = {
      items: items.map(item => ({
        itemId: item.id,
        quantity: item.quantity,
      })),
    };

    // Check for duplicates before creating new PR
    await checkDuplicates(
      () => apiClient.post('/purchase/requisitions/check-duplicates', checkPayload),
      () => actuallySubmitPR(status),
    );
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-amber-50 via-orange-50 to-yellow-50 p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8 flex justify-between items-center">
          <div>
            <button
              type="button"
              onClick={() => router.push('/dashboard/purchase')}
              className="text-amber-800 hover:text-amber-900 mb-4 flex items-center gap-2"
            >
              ← Back to Purchase
            </button>
            <h1 className="text-4xl font-bold text-amber-900 mb-2">Purchase Requisitions</h1>
            <p className="text-amber-700">Create and manage purchase requisition requests</p>
          </div>
          <button
            type="button"
            onClick={() => setShowCreateForm(true)}
            className="bg-amber-800 text-white px-6 py-3 rounded-lg hover:bg-amber-900 transition-colors font-semibold"
          >
            + New Requisition
          </button>
        </div>

        {/* Create Form Modal */}
        {showCreateForm && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-lg shadow-xl max-w-4xl w-full max-h-[90vh] overflow-y-auto">
              <div className="sticky top-0 bg-white border-b px-6 py-4 flex justify-between items-center">
                <h2 className="text-2xl font-bold text-amber-900">
                  {editingPRId ? 'Edit Purchase Requisition' : 'New Purchase Requisition'}
                </h2>
                <button
                  type="button"
                  onClick={() => {
                    setShowCreateForm(false);
                    setEditingPRId(null);
                    setItems([]);
                    setFormData({ department: '', requiredDate: '', priority: 'MEDIUM', notes: '' });
                  }}
                  className="text-gray-500 hover:text-gray-700 text-2xl"
                >
                  ×
                </button>
              </div>

              <div className="p-6">
                {/* Basic Information */}
                <div className="grid grid-cols-2 gap-4 mb-6">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Department *
                    </label>
                    <select
                      value={formData.department}
                      onChange={(e) => setFormData({ ...formData, department: e.target.value })}
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                    >
                      <option value="">Select Department</option>
                      <option value="Production">Production</option>
                      <option value="Maintenance">Maintenance</option>
                      <option value="Quality Assurance">Quality Assurance</option>
                      <option value="QA Testing">QA Testing</option>
                      <option value="Engineering">Engineering</option>
                      <option value="R&D">R&D</option>
                      <option value="Warehouse">Warehouse</option>
                      <option value="Logistics">Logistics</option>
                      <option value="Procurement">Procurement</option>
                      <option value="IT">IT</option>
                      <option value="Admin">Admin</option>
                      <option value="HR">HR</option>
                      <option value="Finance">Finance</option>
                      <option value="Sales">Sales</option>
                      <option value="Marketing">Marketing</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Required Date *
                    </label>
                    <input
                      type="date"
                      value={formData.requiredDate}
                      onChange={(e) => setFormData({ ...formData, requiredDate: e.target.value })}
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Priority
                    </label>
                    <select
                      value={formData.priority}
                      onChange={(e) => setFormData({ ...formData, priority: e.target.value })}
                      className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                    >
                      <option value="LOW">Low</option>
                      <option value="MEDIUM">Medium</option>
                      <option value="HIGH">High</option>
                      <option value="URGENT">Urgent</option>
                    </select>
                  </div>
                </div>

                {/* Items Section */}
                <div className="mb-6">
                  <h3 className="text-lg font-bold text-gray-900 mb-4">Items</h3>
                  
                  {/* Toggle between search and manual entry */}
                  <div className="flex gap-2 mb-4">
                    <button
                      type="button"
                      onClick={() => setUseManualEntry(false)}
                      className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                        !useManualEntry
                          ? 'bg-amber-800 text-white'
                          : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                      }`}
                    >
                      Search Existing Items
                    </button>
                    <button
                      type="button"
                      onClick={() => setUseManualEntry(true)}
                      className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                        useManualEntry
                          ? 'bg-amber-800 text-white'
                          : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                      }`}
                    >
                      Add New Item
                    </button>
                  </div>
                  
                  {/* Add Item Form */}
                  <div className="bg-gray-50 rounded-lg p-4 mb-4">
                    <div className="grid grid-cols-5 gap-3 mb-3">
                      {/* Item Name/Search */}
                      <div className="relative" ref={dropdownRef}>
                        {!useManualEntry ? (
                          <>
                            <div className="relative">
                              <input
                                type="text"
                                value={searchTerm}
                                onChange={(e) => {
                                  setSearchTerm(e.target.value);
                                  setShowDropdown(true);
                                  setSelectedItemId(null);
                                  setItemForm((prev) => ({ ...prev, vendorId: '', vendorName: '' }));
                                  setLastPurchasePrice(null);
                                }}
                                onFocus={() => setShowDropdown(true)}
                                placeholder="🔍 Search items by name, code..."
                                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-amber-500"
                                autoComplete="off"
                              />
                              {searchTerm && (
                                <button
                                  type="button"
                                  onClick={() => {
                                    setSearchTerm('');
                                    setSelectedItemId(null);
                                    setItemForm({ ...itemForm, estimatedPrice: '', vendorId: '', vendorName: '' });
                                    setLastPurchasePrice(null);
                                  }}
                                  className="absolute right-2 top-2.5 text-gray-400 hover:text-gray-600"
                                >
                                  ✕
                                </button>
                              )}
                            </div>
                            {itemForm.vendorName ? (
                              <div className="mt-1 text-xs text-gray-600">
                                Preferred Vendor: <span className="font-medium text-gray-800">{itemForm.vendorName}</span>
                              </div>
                            ) : null}
                            {showDropdown && (
                              <div className="absolute z-50 w-full mt-1 bg-white border border-gray-300 rounded-lg shadow-xl max-h-72 overflow-y-auto">
                                {itemsLoadError ? (
                                  <div className="px-4 py-6 text-center">
                                    <div className="text-red-600 font-semibold mb-2">⚠️ {itemsLoadError}</div>
                                    <button
                                      type="button"
                                      onClick={() => window.location.href = '/login'}
                                      className="mt-2 px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 text-sm"
                                    >
                                      Go to Login
                                    </button>
                                  </div>
                                ) : filteredItems.length > 0 ? (
                                  <>
                                    <div className="sticky top-0 bg-amber-50 px-3 py-2 text-xs font-semibold text-amber-900 border-b">
                                      {filteredItems.length} item{filteredItems.length !== 1 ? 's' : ''} found
                                    </div>
                                    {filteredItems.map((item) => (
                                      <button
                                        type="button"
                                        key={item.id}
                                        onClick={() => selectItem(item)}
                                        className={`w-full text-left px-4 py-3 hover:bg-amber-50 border-b last:border-b-0 transition-colors ${
                                          selectedItemId === item.id ? 'bg-amber-100' : ''
                                        }`}
                                      >
                                        <div className="flex justify-between items-start">
                                          <div className="flex-1">
                                            <div className="font-semibold text-gray-900">{item.name}</div>
                                            <div className="text-sm text-gray-600 mt-1">
                                              <span className="inline-flex items-center px-2 py-0.5 rounded bg-blue-100 text-blue-800 text-xs font-medium mr-2">
                                                {item.code}
                                              </span>
                                              <span className="text-gray-500">UOM: {item.uom}</span>
                                            </div>
                                          </div>
                                          {item.standard_cost && (
                                            <div className="text-right ml-2">
                                              <div className="text-xs text-gray-500">Std Cost</div>
                                              <div className="font-semibold text-green-700">₹{item.standard_cost.toFixed(2)}</div>
                                            </div>
                                          )}
                                        </div>
                                      </button>
                                    ))}
                                  </>
                                ) : (
                                  <div className="px-4 py-8 text-center text-gray-500">
                                    <div className="text-4xl mb-2">🔍</div>
                                    <div className="font-medium">No items found</div>
                                    <div className="text-sm mt-1">Try a different search term</div>
                                  </div>
                                )}
                              </div>
                            )}
                          </>
                        ) : (
                          <input
                            type="text"
                            value={itemForm.itemName}
                            onChange={(e) => setItemForm({ ...itemForm, itemName: e.target.value })}
                            placeholder="Item Name *"
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                          />
                        )}
                      </div>
                      <input
                        type="number"
                        value={itemForm.quantity}
                        onChange={(e) => setItemForm({ ...itemForm, quantity: e.target.value })}
                        placeholder="Quantity *"
                        className="px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                      />
                      <input
                        type="text"
                        value={itemForm.uom || ''}
                        onChange={(e) => setItemForm({ ...itemForm, uom: e.target.value })}
                        placeholder="UOM"
                        readOnly={!useManualEntry}
                        className={`px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500 ${!useManualEntry ? 'bg-gray-100 cursor-not-allowed' : ''}`}
                        title={!useManualEntry ? 'UOM is auto-filled from master item' : 'Enter unit of measurement (e.g., PCS, KG, MTR)'}
                      />
                      <div>
                        <input
                          type="number"
                          value={itemForm.estimatedPrice}
                          onChange={(e) => setItemForm({ ...itemForm, estimatedPrice: e.target.value })}
                          placeholder="Est. Unit Price"
                          title="Estimated unit price. Extended price = Qty × unit price."
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                        />
                        {lastPurchasePrice && (
                          <div className="mt-1 text-[11px] text-gray-600">
                            Last: <span className="font-medium text-gray-800">₹{Number(lastPurchasePrice.unit_price || 0).toFixed(2)}</span>
                          </div>
                        )}
                      </div>
                      {editingItemId ? (
                        <div className="flex gap-2">
                          <button
                            type="button"
                            onClick={updateItem}
                            className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 transition-colors"
                          >
                            Update
                          </button>
                          <button
                            type="button"
                            onClick={cancelEdit}
                            className="bg-gray-500 text-white px-4 py-2 rounded-lg hover:bg-gray-600 transition-colors"
                          >
                            Cancel
                          </button>
                        </div>
                      ) : (
                        <button
                          type="button"
                          onClick={addItem}
                          className="bg-amber-800 text-white px-4 py-2 rounded-lg hover:bg-amber-900 transition-colors"
                        >
                          + Add
                        </button>
                      )}
                    </div>
                    <input
                      type="text"
                      value={itemForm.specifications}
                      onChange={(e) => setItemForm({ ...itemForm, specifications: e.target.value })}
                      placeholder="Specifications / Notes"
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                    />

                    <div className="grid grid-cols-2 gap-3 mt-3">
                      <input
                        type="text"
                        value={itemForm.paymentTerms}
                        onChange={(e) => setItemForm({ ...itemForm, paymentTerms: e.target.value })}
                        placeholder="Payment Terms (line)"
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                      />
                      <input
                        type="text"
                        value={itemForm.deliveryTerms}
                        onChange={(e) => setItemForm({ ...itemForm, deliveryTerms: e.target.value })}
                        placeholder="Delivery Terms (line)"
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                      />
                    </div>
                  </div>

                  {/* Items List */}
                  {items.length > 0 && (
                    <div className="border rounded-lg overflow-hidden">
                      <table className="w-full">
                        <thead className="bg-gray-100">
                          <tr>
                            <th className="px-4 py-2 text-left text-sm font-semibold">Item</th>
                            <th className="px-4 py-2 text-left text-sm font-semibold">Vendor</th>
                            <th className="px-4 py-2 text-left text-sm font-semibold">Qty</th>
                            <th
                              className="px-4 py-2 text-left text-sm font-semibold"
                              title="Estimated unit price. Extended price = Qty × unit price."
                            >
                              Est. Unit Price
                            </th>
                            <th className="px-4 py-2 text-left text-sm font-semibold">Payment Terms</th>
                            <th className="px-4 py-2 text-left text-sm font-semibold">Delivery Terms</th>
                            <th className="px-4 py-2 text-left text-sm font-semibold">Specifications</th>
                            <th className="px-4 py-2"></th>
                          </tr>
                        </thead>
                        <tbody>
                          {items.map((item) => (
                            <tr key={item.id} className="border-t">
                              <td className="px-4 py-2">
                                <div className="font-medium text-gray-900">{item.itemName}</div>
                              </td>
                              <td className="px-4 py-2">
                                <select
                                  value={item.vendorId || ''}
                                  onChange={(e) => {
                                    const vendorId = e.target.value;
                                    const vendor = rfqVendors.find((v) => v.id === vendorId);
                                    setItems((prev) =>
                                      prev.map((it) =>
                                        it.id === item.id
                                          ? {
                                              ...it,
                                              vendorId: vendorId || undefined,
                                              vendorName: vendor ? vendor.name : undefined,
                                            }
                                          : it,
                                      ),
                                    );
                                  }}
                                  className="w-full px-2 py-1 border border-gray-300 rounded text-sm"
                                >
                                  <option value="">Select Vendor</option>
                                  {rfqVendors.map((vendor) => (
                                    <option key={vendor.id} value={vendor.id}>
                                      {vendor.name}
                                    </option>
                                  ))}
                                </select>
                              </td>
                              <td className="px-4 py-2">
                                {item.quantity}
                                {item.uom ? <span className="ml-1 text-xs text-gray-600">{item.uom}</span> : null}
                              </td>
                              <td className="px-4 py-2">
                                {item.estimatedPrice ? `₹${item.estimatedPrice.toFixed(2)}` : '-'}
                              </td>
                              <td className="px-4 py-2 text-sm text-gray-600">
                                {item.specifications || '-'}
                              </td>
                              <td className="px-4 py-2">
                                <div className="flex gap-2">
                                  <button
                                    type="button"
                                    onClick={() => editItem(item.id)}
                                    className="text-blue-600 hover:text-blue-800 font-medium"
                                  >
                                    Edit
                                  </button>
                                  <button
                                    type="button"
                                    onClick={() => removeItem(item.id)}
                                    className="text-red-600 hover:text-red-800 font-medium"
                                  >
                                    Remove
                                  </button>
                                </div>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                      {items.length > 0 && (
                        <div className="mt-4 flex justify-center">
                          <button
                            type="button"
                            onClick={resetItemEntry}
                            className="px-6 py-2 text-amber-600 hover:text-amber-800 font-medium border-2 border-dashed border-amber-300 hover:border-amber-500 rounded-lg transition-colors"
                          >
                            + Add Another Item
                          </button>
                        </div>
                      )}
                    </div>
                  )}
                </div>

                {/* Notes */}
                <div className="mb-6">
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Additional Notes
                  </label>
                  <textarea
                    value={formData.notes}
                    onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                    rows={3}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                    placeholder="Any additional information..."
                  />
                </div>

                {/* Actions */}
                <div className="flex justify-end gap-3">
                  <button
                    type="button"
                    onClick={() => setShowCreateForm(false)}
                    className="px-6 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors"
                  >
                    Cancel
                  </button>
                  <button
                    type="button"
                    onClick={() => handleSubmit('DRAFT')}
                    disabled={items.length === 0}
                    className="px-6 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    Save as Draft
                  </button>
                  <button
                    type="button"
                    onClick={() => handleSubmit('SUBMITTED')}
                    disabled={items.length === 0 || !formData.department || !formData.requiredDate}
                    className="px-6 py-2 bg-amber-800 text-white rounded-lg hover:bg-amber-900 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {editingPRId ? 'Update Requisition' : 'Submit for Approval'}
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* List View */}
        <div className="bg-white rounded-lg shadow-lg overflow-hidden">
          <div className="p-6 border-b bg-gray-50">
            <div className="flex justify-between items-center">
              <h3 className="text-lg font-bold text-gray-900">All Requisitions</h3>
              <div className="flex gap-2">
                <select 
                  value={filterStatus}
                  onChange={(e) => setFilterStatus(e.target.value)}
                  className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                >
                  <option value="">All Status</option>
                  <option value="DRAFT">Draft</option>
                  <option value="SUBMITTED">Submitted</option>
                  <option value="APPROVED">Approved</option>
                  <option value="REJECTED">Rejected</option>
                </select>
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Search..."
                  className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                />
              </div>
            </div>
          </div>

          {loadingRequisitions ? (
            <div className="p-6 text-center text-gray-500">
              <p>Loading requisitions...</p>
            </div>
          ) : requisitions.length === 0 ? (
            <div className="p-6 text-center text-gray-500">
              <p className="text-lg mb-2">No purchase requisitions yet</p>
              <p className="text-sm">Click &ldquo;New Requisition&rdquo; to create your first purchase request</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-gray-50 border-b">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">PR Number</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Department</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Required Date</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Created</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200">
                  {requisitions
                    .filter(req => !filterStatus || req.status === filterStatus)
                    .filter(req => !searchQuery || 
                      req.pr_number.toLowerCase().includes(searchQuery.toLowerCase()) ||
                      req.department.toLowerCase().includes(searchQuery.toLowerCase())
                    )
                    .map((req) => (
                      <tr key={req.id} className="hover:bg-gray-50">
                        <td className="px-6 py-4 text-sm font-medium text-gray-900">{req.pr_number}</td>
                        <td className="px-6 py-4 text-sm text-gray-700">{req.department}</td>
                        <td className="px-6 py-4 text-sm text-gray-700">
                          {new Date(req.required_date).toLocaleDateString()}
                        </td>
                        <td className="px-6 py-4">
                          <span className={`px-2 py-1 text-xs font-semibold rounded-full ${
                            req.status === 'APPROVED' ? 'bg-green-100 text-green-800' :
                            req.status === 'SUBMITTED' ? 'bg-blue-100 text-blue-800' :
                            req.status === 'DRAFT' ? 'bg-yellow-100 text-yellow-800' :
                            req.status === 'REJECTED' ? 'bg-red-100 text-red-800' :
                            'bg-gray-100 text-gray-800'
                          }`}>
                            {req.status}
                          </span>
                        </td>
                        <td className="px-6 py-4 text-sm text-gray-700">
                          {new Date(req.created_at).toLocaleDateString()}
                        </td>
                        <td className="px-6 py-4 text-sm">
                          <div className="flex gap-2">
                            <button 
                              type="button"
                              onClick={() => handleViewDetails(req.id)}
                              className="text-amber-600 hover:text-amber-900 font-medium"
                            >
                              View Details
                            </button>
                            {(req.status === 'DRAFT' || req.status === 'SUBMITTED') && (
                              <button
                                type="button"
                                onClick={() => handleEditPR(req.id)}
                                className="text-blue-600 hover:text-blue-900 font-medium"
                              >
                                Edit
                              </button>
                            )}
                            {(req.status === 'DRAFT' || req.status === 'SUBMITTED') && (
                              <>
                                <button
                                  type="button"
                                  onClick={() => handleApprove(req.id)}
                                  className="text-green-600 hover:text-green-900 font-medium"
                                >
                                  Approve
                                </button>
                                <button
                                  type="button"
                                  onClick={() => handleReject(req.id)}
                                  className="text-red-600 hover:text-red-900 font-medium"
                                >
                                  Reject
                                </button>
                              </>
                            )}
                            <button
                              type="button"
                              onClick={() => handleDelete(req.id)}
                              className="text-gray-600 hover:text-gray-900 font-medium"
                            >
                              Delete
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* PR Detail Modal */}
        {showDetailModal && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
            <div className="bg-white rounded-lg max-w-4xl w-full max-h-[90vh] overflow-auto">
              {loadingDetail ? (
                <div className="p-8 text-center">
                  <div className="animate-pulse">
                    <div className="h-4 bg-gray-200 rounded w-3/4 mx-auto mb-4"></div>
                    <div className="h-4 bg-gray-200 rounded w-1/2 mx-auto"></div>
                  </div>
                  <p className="text-gray-600 mt-4">Loading PR details...</p>
                </div>
              ) : selectedPR ? (
                <div className="p-6">
                  {/* Header */}
                  <div className="flex justify-between items-start mb-6">
                    <div>
                      <h2 className="text-2xl font-bold text-gray-900">Purchase Requisition Details</h2>
                      <p className="text-gray-600 mt-1">PR Number: {selectedPR.pr_number}</p>
                    </div>
                    <button
                      type="button"
                      onClick={() => setShowDetailModal(false)}
                      className="text-gray-400 hover:text-gray-600 text-2xl font-bold"
                    >
                      ×
                    </button>
                  </div>

                  {/* PR Info */}
                  <div className="grid grid-cols-2 gap-4 mb-6 p-4 bg-gray-50 rounded-lg">
                    <div>
                      <p className="text-sm text-gray-600">Department</p>
                      <p className="font-semibold">{selectedPR.department}</p>
                    </div>
                    <div>
                      <p className="text-sm text-gray-600">Status</p>
                      <span className={`inline-block px-3 py-1 text-sm font-semibold rounded-full ${
                        selectedPR.status === 'APPROVED' ? 'bg-green-100 text-green-800' :
                        selectedPR.status === 'SUBMITTED' ? 'bg-blue-100 text-blue-800' :
                        selectedPR.status === 'DRAFT' ? 'bg-yellow-100 text-yellow-800' :
                        selectedPR.status === 'REJECTED' ? 'bg-red-100 text-red-800' :
                        'bg-gray-100 text-gray-800'
                      }`}>
                        {selectedPR.status}
                      </span>
                    </div>
                    <div>
                      <p className="text-sm text-gray-600">Required Date</p>
                      <p className="font-semibold">{new Date(selectedPR.required_date).toLocaleDateString()}</p>
                    </div>
                    <div>
                      <p className="text-sm text-gray-600">Priority</p>
                      <p className="font-semibold">{selectedPR.priority || 'MEDIUM'}</p>
                    </div>
                    <div>
                      <p className="text-sm text-gray-600">Purpose</p>
                      <p className="font-semibold">{selectedPR.purpose || 'N/A'}</p>
                    </div>
                    <div>
                      <p className="text-sm text-gray-600">Request Date</p>
                      <p className="font-semibold">{new Date(selectedPR.request_date).toLocaleDateString()}</p>
                    </div>
                    {/* Hide UUID for requested_by until we implement user lookup */}
                    {selectedPR.approved_by && (
                      <div>
                        <p className="text-sm text-gray-600">Approved By</p>
                        <p className="font-semibold text-xs">{selectedPR.approved_by}</p>
                      </div>
                    )}
                    {selectedPR.approved_at && (
                      <div>
                        <p className="text-sm text-gray-600">Approved At</p>
                        <p className="font-semibold">{new Date(selectedPR.approved_at).toLocaleDateString()}</p>
                      </div>
                    )}
                    {selectedPR.edit_count && selectedPR.edit_count > 0 && (
                      <div>
                        <p className="text-sm text-gray-600">Edits</p>
                        <p className="font-semibold">{selectedPR.edit_count} time{selectedPR.edit_count !== 1 ? 's' : ''}</p>
                      </div>
                    )}
                    {selectedPR.last_edited_at && (
                      <div>
                        <p className="text-sm text-gray-600">Last Edited</p>
                        <p className="font-semibold">{new Date(selectedPR.last_edited_at).toLocaleDateString()} {new Date(selectedPR.last_edited_at).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                      </div>
                    )}
                  </div>

                  {/* Items Table */}
                  <div className="mb-6">
                    <h3 className="text-lg font-bold mb-3">Items</h3>
                    <div className="border rounded-lg overflow-hidden">
                      <table className="w-full">
                        <thead className="bg-gray-100">
                          <tr>
                            <th className="px-4 py-2 text-center text-sm font-semibold">S.No</th>
                            <th className="px-4 py-2 text-left text-sm font-semibold">Item Code</th>
                            <th className="px-4 py-2 text-left text-sm font-semibold">Item Name</th>
                            {rfqPanelOpen && <th className="px-4 py-2 text-left text-sm font-semibold">Vendors (Select Multiple)</th>}
                            <th className="px-4 py-2 text-right text-sm font-semibold">Requested</th>
                            <th className="px-4 py-2 text-center text-sm font-semibold">UOM</th>
                            <th className="px-4 py-2 text-right text-sm font-semibold">Ordered</th>
                            <th className="px-4 py-2 text-right text-sm font-semibold">Remaining</th>
                            <th className="px-4 py-2 text-center text-sm font-semibold">Status</th>
                            <th className="px-4 py-2 text-right text-sm font-semibold">Est. Rate</th>
                            <th className="px-4 py-2 text-right text-sm font-semibold">Total</th>
                            <th className="px-4 py-2 text-left text-sm font-semibold">Remarks</th>
                          </tr>
                        </thead>
                        <tbody>
                          {selectedPR.purchase_requisition_items && selectedPR.purchase_requisition_items.length > 0 ? (
                            selectedPR.purchase_requisition_items.map((item, index) => (
                              <tr key={item.id} className="border-t">
                                <td className="px-4 py-2 text-sm text-center">{item.serial_no || index + 1}</td>
                                <td className="px-4 py-2 text-sm">{item.item_code || '-'}</td>
                                <td className="px-4 py-2 text-sm">{item.item_name}</td>
                                {rfqPanelOpen && (
                                  <td className="px-4 py-2">
                                    <div className="space-y-1 max-h-32 overflow-y-auto">
                                      {rfqVendors.map((vendor) => {
                                        const isSelected = (rfqItemVendors[item.id] || []).includes(vendor.id);
                                        const isPreferred = item.vendor_id === vendor.id;
                                        return (
                                          <label key={vendor.id} className="flex items-center gap-2 text-sm cursor-pointer hover:bg-gray-50 px-2 py-1 rounded">
                                            <input
                                              type="checkbox"
                                              checked={isSelected}
                                              onChange={() => toggleItemVendor(item.id, vendor.id)}
                                              className="rounded border-gray-300 text-amber-600 focus:ring-amber-500"
                                            />
                                            <span className={isPreferred ? 'font-semibold text-amber-700' : ''}>
                                              {vendor.name}
                                              {isPreferred && <span className="ml-1 text-xs">(Preferred)</span>}
                                            </span>
                                          </label>
                                        );
                                      })}
                                    </div>
                                  </td>
                                )}
                                <td className="px-4 py-2 text-sm text-right">{item.requested_qty}</td>
                                <td className="px-4 py-2 text-sm text-center">{item.uom || '-'}</td>
                                <td className="px-4 py-2 text-sm text-right">{item.total_ordered_qty || 0}</td>
                                <td className="px-4 py-2 text-sm text-right font-medium text-blue-700">{item.remaining_qty ?? item.requested_qty}</td>
                                <td className="px-4 py-2 text-center">
                                  {item.po_conversion_status === 'COMPLETED' && (
                                    <span className="inline-block px-2 py-1 text-xs font-semibold rounded-full bg-green-100 text-green-800">DONE</span>
                                  )}
                                  {item.po_conversion_status === 'PARTIAL' && (
                                    <span className="inline-block px-2 py-1 text-xs font-semibold rounded-full bg-yellow-100 text-yellow-800">PARTIAL</span>
                                  )}
                                  {(!item.po_conversion_status || item.po_conversion_status === 'PENDING') && (
                                    <span className="inline-block px-2 py-1 text-xs font-semibold rounded-full bg-gray-100 text-gray-600">PENDING</span>
                                  )}
                                </td>
                                <td className="px-4 py-2 text-sm text-right">₹{(item.estimated_rate || 0).toFixed(2)}</td>
                                <td className="px-4 py-2 text-sm text-right font-semibold">₹{((item.requested_qty || 0) * (item.estimated_rate || 0)).toFixed(2)}</td>
                                <td className="px-4 py-2 text-sm text-gray-600">{item.remarks || '-'}</td>
                              </tr>
                            ))
                          ) : (
                            <tr>
                              <td colSpan={rfqPanelOpen ? 12 : 11} className="px-4 py-8 text-center text-gray-500">
                                No items found in this requisition
                              </td>
                            </tr>
                          )}
                        </tbody>
                        {selectedPR.purchase_requisition_items && selectedPR.purchase_requisition_items.length > 0 && (
                          <tfoot className="bg-gray-50 border-t-2">
                            <tr>
                              <td colSpan={rfqPanelOpen ? 10 : 9} className="px-4 py-3 text-right font-bold">Total Amount:</td>
                              <td className="px-4 py-3 text-right font-bold text-lg">
                                ₹{selectedPR.purchase_requisition_items.reduce((sum, item) => sum + ((item.requested_qty || 0) * (item.estimated_rate || 0)), 0).toFixed(2)}
                              </td>
                              <td></td>
                            </tr>
                          </tfoot>
                        )}
                      </table>
                    </div>
                  </div>

                  {/* Action Buttons */}
                  <div className="flex justify-end gap-3">
                    {selectedPR.status === 'SUBMITTED' && (
                      <>
                        <button
                          onClick={() => {
                            handleEditPR(selectedPR.id);
                            setShowDetailModal(false);
                          }}
                          className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
                        >
                          Edit
                        </button>
                        <button
                          onClick={() => handleReject(selectedPR.id)}
                          className="px-6 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors"
                        >
                          Reject
                        </button>
                        <button
                          onClick={() => handleApprove(selectedPR.id)}
                          className="px-6 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors"
                        >
                          Approve
                        </button>
                      </>
                    )}
                    {selectedPR.status === 'APPROVED' && (
                      <>
                        <button
                          onClick={async () => {
                            const nextOpen = !rfqPanelOpen;
                            setRfqPanelOpen(nextOpen);
                            if (nextOpen && rfqVendors.length === 0) {
                              await fetchRFQVendors();
                            }
                            if (nextOpen && selectedPR) {
                              await fetchPreferredVendorsForPR(selectedPR);
                            }
                          }}
                          className="px-6 py-2 bg-amber-800 text-white rounded-lg hover:bg-amber-900 transition-colors"
                        >
                          Send RFQ
                        </button>
                        <button
                          onClick={() => {
                            setShowDetailModal(false);
                            router.push(`/dashboard/purchase/orders?prId=${selectedPR.id}`);
                          }}
                          className="px-6 py-2 bg-amber-800 text-white rounded-lg hover:bg-amber-900 transition-colors"
                        >
                          Create PO from this PR
                        </button>
                      </>
                    )}
                    <button
                      onClick={() => setShowDetailModal(false)}
                      className="px-6 py-2 bg-gray-300 text-gray-700 rounded-lg hover:bg-gray-400 transition-colors"
                    >
                      Close
                    </button>
                  </div>

                  {selectedPR.status === 'APPROVED' && rfqPanelOpen && (
                    <div className="mt-4 p-4 bg-gray-50 rounded-lg border">
                      <div className="flex items-center justify-between mb-3">
                        <h3 className="text-sm font-bold text-gray-900">Send RFQ to Vendors</h3>
                        <button
                          onClick={() => setRfqPanelOpen(false)}
                          className="text-gray-600 hover:text-gray-900 font-medium"
                        >
                          Hide
                        </button>
                      </div>

                      <div className="mb-3 text-sm text-gray-600">
                        💡 Select multiple vendors for each item using checkboxes. Preferred vendors are auto-selected and marked.
                      </div>

                      {rfqLoadingVendors && (
                        <p className="text-sm text-gray-600">Loading vendors...</p>
                      )}

                      <div className="grid grid-cols-2 gap-3 mt-3">
                        <div>
                          <label className="block text-xs font-semibold text-gray-700 mb-1">Expected Response Date (optional)</label>
                          <input
                            type="date"
                            value={rfqResponseDate}
                            onChange={(e) => setRfqResponseDate(e.target.value)}
                            className="w-full px-3 py-2 border rounded-lg text-sm"
                          />
                        </div>
                        <div>
                          <label className="block text-xs font-semibold text-gray-700 mb-1">Remarks (optional)</label>
                          <input
                            type="text"
                            value={rfqRemarks}
                            onChange={(e) => setRfqRemarks(e.target.value)}
                            placeholder="Any notes to vendor"
                            className="w-full px-3 py-2 border rounded-lg text-sm"
                          />
                        </div>
                      </div>

                      <div className="flex justify-end gap-3 mt-3">
                        <button
                          onClick={() => handlePreviewRFQ()}
                          disabled={rfqLoadingVendors || rfqPreviewLoading}
                          className={`px-6 py-2 rounded-lg transition-colors ${
                            rfqLoadingVendors || rfqPreviewLoading
                              ? 'bg-gray-300 text-gray-600'
                              : 'bg-blue-600 text-white hover:bg-blue-700'
                          }`}
                        >
                          {rfqPreviewLoading ? 'Generating...' : 'Preview Email'}
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              ) : (
                <div className="p-8 text-center">
                  <p className="text-gray-600">No data available</p>
                  <button
                    onClick={() => setShowDetailModal(false)}
                    className="mt-4 px-6 py-2 bg-gray-300 text-gray-700 rounded-lg hover:bg-gray-400 transition-colors"
                  >
                    Close
                  </button>
                </div>
              )}
            </div>
          </div>
        )}

        {/* RFQ Email Preview Modal */}
        {showRfqPreview && rfqPreviewData && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-lg shadow-xl max-w-4xl w-full max-h-[90vh] overflow-y-auto">
              <div className="sticky top-0 bg-white border-b px-6 py-4 flex justify-between items-center">
                <h2 className="text-2xl font-bold text-amber-900">RFQ Email Preview</h2>
                <button
                  type="button"
                  onClick={() => {
                    setShowRfqPreview(false);
                    setRfqPreviewIndex(0);
                  }}
                  className="text-gray-500 hover:text-gray-700 text-2xl"
                >
                  ×
                </button>
              </div>

              <div className="p-6 space-y-6">
                {(() => {
                  const previews = Array.isArray(rfqPreviewData?.emailPreviews)
                    ? rfqPreviewData.emailPreviews
                    : [];
                  const current = previews[rfqPreviewIndex] || previews[0];
                  const recipientKey = String(current?.vendor_id || current?.to || '').trim();
                  const effectiveTo =
                    (recipientKey && typeof rfqRecipientOverrides[recipientKey] === 'string'
                      ? rfqRecipientOverrides[recipientKey]
                      : '') || String(current?.to || '');
                  const effectiveSubject =
                    (rfqSubjectOverride ? rfqSubjectOverride : String(current?.subject || '')) || '';

                  return (
                    <>
                      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        {/* Recipient list */}
                        <div className="md:col-span-1">
                          <h3 className="text-lg font-bold mb-2">Recipients</h3>
                          <div className="border rounded-lg overflow-hidden">
                            <div className="bg-gray-50 px-3 py-2 text-xs font-semibold text-gray-700">
                              Select vendor
                            </div>
                            <div className="max-h-72 overflow-y-auto divide-y">
                              {previews.length === 0 ? (
                                <div className="p-3 text-sm text-gray-600">No preview data available.</div>
                              ) : (
                                previews.map((p: any, idx: number) => {
                                  const active = idx === rfqPreviewIndex;
                                  return (
                                    <button
                                      key={`${String(p?.to || '')}-${idx}`}
                                      type="button"
                                      onClick={() => setRfqPreviewIndex(idx)}
                                      className={`w-full text-left px-3 py-2 hover:bg-gray-50 ${
                                        active ? 'bg-amber-50' : ''
                                      }`}
                                    >
                                      <div className="text-sm font-semibold text-gray-900">
                                        {p?.vendor_name || 'Vendor'}
                                      </div>
                                      <div className="text-xs text-gray-600">{String(p?.to || '')}</div>
                                    </button>
                                  );
                                })
                              )}
                            </div>
                          </div>
                        </div>

                        {/* Email preview */}
                        <div className="md:col-span-2 space-y-3">
                          <h3 className="text-lg font-bold">Email</h3>
                          {!current ? (
                            <div className="bg-gray-50 p-4 rounded-lg text-sm text-gray-700">
                              Select a recipient to preview the email.
                            </div>
                          ) : (
                            <>
                              <div className="bg-gray-50 p-4 rounded-lg text-sm space-y-3">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                                  <label className="block">
                                    <span className="font-semibold">To</span>
                                    <input
                                      className="mt-1 w-full border rounded px-3 py-2"
                                      value={effectiveTo}
                                      onChange={(e) => {
                                        const value = e.target.value;
                                        if (!recipientKey) return;
                                        setRfqRecipientOverrides((prev) => {
                                          const next = { ...prev };
                                          if (!value.trim()) {
                                            delete next[recipientKey];
                                            return next;
                                          }
                                          next[recipientKey] = value;
                                          return next;
                                        });
                                      }}
                                      placeholder="vendor@email.com"
                                    />
                                  </label>

                                  <label className="block">
                                    <span className="font-semibold">Subject</span>
                                    <input
                                      className="mt-1 w-full border rounded px-3 py-2"
                                      value={effectiveSubject}
                                      onChange={(e) => setRfqSubjectOverride(e.target.value)}
                                      placeholder="Subject"
                                    />
                                  </label>
                                </div>

                                <label className="block">
                                  <span className="font-semibold">Message (optional)</span>
                                  <textarea
                                    className="mt-1 w-full border rounded px-3 py-2"
                                    rows={3}
                                    value={rfqCustomMessage}
                                    onChange={(e) => setRfqCustomMessage(e.target.value)}
                                    placeholder="Add a short note to the vendor..."
                                  />
                                </label>

                                <div className="flex justify-end">
                                  <button
                                    type="button"
                                    onClick={() => handlePreviewRFQ({ keepIndex: rfqPreviewIndex })}
                                    disabled={rfqPreviewLoading}
                                    className={`px-4 py-2 rounded-lg transition-colors text-sm ${
                                      rfqPreviewLoading
                                        ? 'bg-gray-300 text-gray-600'
                                        : 'bg-blue-600 text-white hover:bg-blue-700'
                                    }`}
                                  >
                                    {rfqPreviewLoading ? 'Updating...' : 'Update Preview'}
                                  </button>
                                </div>

                                <div>
                                  <span className="font-semibold">From:</span> {String(current?.from || '')}
                                </div>
                                {current?.replyTo && (
                                  <div>
                                    <span className="font-semibold">Reply-To:</span>{' '}
                                    {String(current.replyTo)}
                                  </div>
                                )}
                                {Array.isArray(current?.attachments) && current.attachments.length > 0 && (
                                  <div>
                                    <span className="font-semibold">Attachments:</span>{' '}
                                    {current.attachments.join(', ')}
                                  </div>
                                )}
                              </div>

                              <div className="border rounded-lg overflow-hidden bg-white">
                                <iframe
                                  title="RFQ Email Preview"
                                  className="w-full h-[55vh]"
                                  srcDoc={String(current?.html || '')}
                                />
                              </div>
                            </>
                          )}
                        </div>
                      </div>

                      {/* Vendor-Item Assignment Summary (selection aid) */}
                      <div>
                        <h3 className="text-lg font-bold mb-2">Vendor Assignment Summary</h3>
                        <div className="bg-blue-50 p-4 rounded-lg border border-blue-200">
                          {rfqPreviewData.vendors.map((vendor: Vendor) => {
                            const vendorItems = rfqPreviewData.itemVendors.filter((iv: any) =>
                              iv.vendorIds.includes(vendor.id),
                            );
                            return (
                              <div key={vendor.id} className="mb-3 last:mb-0">
                                <p className="font-semibold text-sm">{vendor.name}:</p>
                                <ul className="ml-4 text-sm text-gray-700">
                                  {vendorItems.map((iv: any) => (
                                    <li key={iv.item.id}>
                                      • {iv.item.item_name} (Qty: {iv.item.requested_qty})
                                    </li>
                                  ))}
                                </ul>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    </>
                  );
                })()}
              </div>

              <div className="sticky bottom-0 bg-white border-t px-6 py-4 flex justify-end gap-3">
                <button
                  onClick={() => {
                    setShowRfqPreview(false);
                    setRfqPreviewIndex(0);
                  }}
                  className="px-6 py-2 bg-gray-300 text-gray-700 rounded-lg hover:bg-gray-400 transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={handleSendRFQ}
                  disabled={rfqSending}
                  className={`px-6 py-2 rounded-lg transition-colors ${
                    rfqSending
                      ? 'bg-gray-300 text-gray-600'
                      : 'bg-green-600 text-white hover:bg-green-700'
                  }`}
                >
                  {rfqSending ? 'Sending...' : 'Confirm & Send RFQ Email'}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Duplicate Warning Modal */}
      <DuplicateWarning
        isOpen={duplicateState.isOpen}
        exactMatches={duplicateState.exactMatches}
        fuzzyMatches={duplicateState.fuzzyMatches}
        entityType="Purchase Requisition"
        onProceed={handleProceed}
        onCancel={handleCancel}
        formatRecord={(data) => (
          <div className="text-sm">
            <p className="font-semibold">PR #{data.pr_number}</p>
            <p className="text-xs text-gray-600">Department: {data.department}</p>
            <p className="text-xs text-gray-600">Items: {data.purchase_requisition_items?.length || 0}</p>
            <p className="text-xs text-gray-600">Status: {data.status}</p>
          </div>
        )}
      />
    </div>
  );
}

export default function PurchaseRequisitionsPage() {
  return <PRContent />;
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { apiClient } from '../../../../../lib/api-client';
import { useSelection } from '../../../../hooks/useSelection';
import DuplicateWarning, { useDuplicateDetection } from '../../../../components/DuplicateWarning';

interface Vendor {
  id: string;
  code: string;
  name: string;
  legal_name: string;
  tax_id?: string;
  category: string;
  contact_person: string;
  email: string;
  phone: string;
  address: string;
  street?: string;
  city?: string;
  state?: string;
  country?: string;
  pincode?: string;
  shipping_street?: string;
  shipping_city?: string;
  shipping_state?: string;
  shipping_country?: string;
  shipping_pincode?: string;
  payment_terms: string;
  credit_limit: number;
  rating: number;
  is_active: boolean;
}

export default function VendorsPage() {
  const router = useRouter();
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editingVendor, setEditingVendor] = useState<Vendor | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('ALL');

  const selection = useSelection(vendors);
  const { duplicateState, checkDuplicates, handleProceed, handleCancel } = useDuplicateDetection();

  const [formData, setFormData] = useState({
    name: '',
    legalName: '',
    taxId: '',
    category: 'RAW_MATERIAL',
    contactPerson: '',
    email: '',
    phone: '',
    address: '',
    street: '',
    city: '',
    state: '',
    country: 'India',
    pincode: '',
    shippingStreet: '',
    shippingCity: '',
    shippingState: '',
    shippingCountry: 'India',
    shippingPincode: '',
    paymentTerms: 'NET_30',
    creditLimit: 0,
    rating: 0,
    isActive: true,
    sameAsbilling: true,
  });

  useEffect(() => {
    fetchVendors();
  }, [filterCategory]);

  const fetchVendors = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      if (filterCategory !== 'ALL') params.append('category', filterCategory);
      if (searchTerm) params.append('search', searchTerm);

      const data = await apiClient.get<Vendor[]>(`/purchase/vendors?${params}`);
      setVendors(Array.isArray(data) ? data : []);
    } catch (error) {
      console.error('Error fetching vendors:', error);
    } finally {
      setLoading(false);
    }
  };

  const actuallyCreateVendor = async () => {
    try {
      if (editingVendor) {
        await apiClient.put(`/purchase/vendors/${editingVendor.id}`, formData);
      } else {
        await apiClient.post('/purchase/vendors', formData);
      }
      setShowModal(false);
      fetchVendors();
      resetForm();
    } catch (error) {
      console.error('Error saving vendor:', error);
    }
  };

  const handleSubmit = async () => {
    // For updates, skip duplicate check or include ID
    if (editingVendor) {
      await actuallyCreateVendor();
      return;
    }

    // Check for duplicates before creating
    await checkDuplicates(
      () => apiClient.post('/purchase/vendors/check-duplicates', formData),
      () => actuallyCreateVendor(),
    );
  };

  const handleEdit = (vendor: Vendor) => {
    setEditingVendor(vendor);
    setFormData({
      name: vendor.name,
      legalName: vendor.legal_name,
      taxId: vendor.tax_id || '',
      category: vendor.category,
      contactPerson: vendor.contact_person || '',
      email: vendor.email || '',
      phone: vendor.phone || '',
      address: vendor.address || '',
      street: vendor.street || '',
      city: vendor.city || '',
      state: vendor.state || '',
      country: vendor.country || 'India',
      pincode: vendor.pincode || '',
      shippingStreet: vendor.shipping_street || '',
      shippingCity: vendor.shipping_city || '',
      shippingState: vendor.shipping_state || '',
      shippingCountry: vendor.shipping_country || 'India',
      shippingPincode: vendor.shipping_pincode || '',
      paymentTerms: vendor.payment_terms,
      creditLimit: vendor.credit_limit || 0,
      rating: vendor.rating || 0,
      isActive: vendor.is_active,
      sameAsbilling: !vendor.shipping_street && !vendor.shipping_city,
    });
    setShowModal(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this vendor?')) return;

    try {
      await apiClient.delete(`/purchase/vendors/${id}`);
      fetchVendors();
    } catch (error) {
      console.error('Error deleting vendor:', error);
    }
  };

  const handleDeleteAll = async () => {
    if (!confirm(`Are you sure you want to delete ${selection.selectedItems.length} vendors? This action cannot be undone.`)) return;

    try {
      await Promise.all(
        selection.selectedItems.map(vendor => apiClient.delete(`/purchase/vendors/${vendor.id}`))
      );
      selection.deselectAll();
      fetchVendors();
    } catch (error) {
      console.error('Error deleting vendors:', error);
    }
  };

  const resetForm = () => {
    setEditingVendor(null);
    setFormData({
      name: '',
      legalName: '',
      taxId: '',
      category: 'RAW_MATERIAL',
      contactPerson: '',
      email: '',
      phone: '',
      address: '',
      street: '',
      city: '',
      state: '',
      country: 'India',
      pincode: '',
      shippingStreet: '',
      shippingCity: '',
      shippingState: '',
      shippingCountry: 'India',
      shippingPincode: '',
      paymentTerms: 'NET_30',
      creditLimit: 0,
      rating: 0,
      isActive: true,
      sameAsbilling: true,
    });
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-amber-50 to-orange-50 p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="flex justify-between items-center mb-8">
          <div>
            <button
              onClick={() => router.push('/dashboard/purchase')}
              className="text-amber-600 hover:text-amber-800 mb-2"
            >
              ← Back to Purchase Management
            </button>
            <h1 className="text-4xl font-bold text-amber-900">Vendor Management</h1>
            <p className="text-amber-700">Manage supplier and vendor information</p>
          </div>
          <div className="flex gap-4">
            {selection.hasSelections && (
              <button
                onClick={handleDeleteAll}
                className="bg-red-600 hover:bg-red-700 text-white px-6 py-3 rounded-lg font-semibold"
              >
                Delete Selected ({selection.selectedItems.length})
              </button>
            )}
            <button
              onClick={() => {
                resetForm();
                setShowModal(true);
              }}
              className="bg-amber-600 hover:bg-amber-700 text-white px-6 py-3 rounded-lg font-semibold"
            >
              + Add Vendor
            </button>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-lg shadow-md p-6 mb-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Category</label>
              <select
                value={filterCategory}
                onChange={(e) => setFilterCategory(e.target.value)}
                className="w-full border border-gray-300 rounded-lg px-4 py-2"
              >
                <option value="ALL">All Categories</option>
                <option value="RAW_MATERIAL">Raw Material</option>
                <option value="COMPONENT">Component</option>
                <option value="SERVICE">Service</option>
                <option value="CONSUMABLE">Consumable</option>
              </select>
            </div>
            <div className="md:col-span-2">
              <label className="block text-sm font-medium text-gray-700 mb-2">Search</label>
              <input
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && fetchVendors()}
                placeholder="Search by name, code, email..."
                className="w-full border border-gray-300 rounded-lg px-4 py-2"
              />
            </div>
          </div>
          {vendors.length > 0 && (
            <div className="mt-4 flex items-center gap-4">
              <label className="flex items-center gap-2">
                <input
                  type="checkbox"
                  checked={selection.isAllSelected}
                  onChange={selection.toggleSelectAll}
                  className="w-4 h-4"
                />
                <span className="text-sm font-medium text-gray-700">
                  Select All ({vendors.length} vendors)
                </span>
              </label>
              {selection.hasSelections && (
                <button
                  onClick={selection.deselectAll}
                  className="text-sm text-amber-600 hover:text-amber-800"
                >
                  Deselect All
                </button>
              )}
            </div>
          )}
        </div>

        {/* Vendors Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {loading ? (
            <div className="col-span-full text-center py-12 text-gray-500">Loading vendors...</div>
          ) : vendors.length === 0 ? (
            <div className="col-span-full text-center py-12">
              <div className="text-6xl mb-4">🏢</div>
              <h3 className="text-xl font-semibold text-gray-700 mb-2">No Vendors Found</h3>
              <p className="text-gray-500">Add your first vendor to get started</p>
            </div>
          ) : (
            vendors.map((vendor) => (
              <div key={vendor.id} className={`bg-white rounded-lg shadow-md p-6 hover:shadow-lg transition-shadow ${selection.isSelected(vendor.id) ? 'ring-2 ring-amber-500' : ''}`}>
                <div className="flex justify-between items-start mb-4">
                  <div className="flex items-center gap-3">
                    <input
                      type="checkbox"
                      checked={selection.isSelected(vendor.id)}
                      onChange={() => selection.toggleSelection(vendor.id)}
                      className="w-4 h-4"
                    />
                    <div>
                      <h3 className="text-lg font-bold text-gray-900">{vendor.name}</h3>
                      <p className="text-sm text-gray-500">{vendor.code}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    {vendor.rating > 0 && (
                      <span className="text-yellow-500">★ {vendor.rating.toFixed(1)}</span>
                    )}
                    <span
                      className={`px-2 py-1 text-xs rounded-full ${
                        vendor.is_active ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
                      }`}
                    >
                      {vendor.is_active ? 'Active' : 'Inactive'}
                    </span>
                  </div>
                </div>

                <div className="space-y-2 mb-4">
                  <div className="flex items-center text-sm text-gray-600">
                    <span className="font-medium w-24">Category:</span>
                    <span>{vendor.category}</span>
                  </div>
                  {vendor.contact_person && (
                    <div className="flex items-center text-sm text-gray-600">
                      <span className="font-medium w-24">Contact:</span>
                      <span>{vendor.contact_person}</span>
                    </div>
                  )}
                  {vendor.email && (
                    <div className="flex items-center text-sm text-gray-600">
                      <span className="font-medium w-24">Email:</span>
                      <span className="truncate">{vendor.email}</span>
                    </div>
                  )}
                  {vendor.phone && (
                    <div className="flex items-center text-sm text-gray-600">
                      <span className="font-medium w-24">Phone:</span>
                      <span>{vendor.phone}</span>
                    </div>
                  )}
                  {(vendor.city || vendor.state) && (
                    <div className="flex items-start text-sm text-gray-600">
                      <span className="font-medium w-24">Location:</span>
                      <span>
                        {[vendor.city, vendor.state, vendor.pincode].filter(Boolean).join(', ')}
                      </span>
                    </div>
                  )}
                  <div className="flex items-center text-sm text-gray-600">
                    <span className="font-medium w-24">Terms:</span>
                    <span>{vendor.payment_terms}</span>
                  </div>
                  {vendor.credit_limit > 0 && (
                    <div className="flex items-center text-sm text-gray-600">
                      <span className="font-medium w-24">Credit:</span>
                      <span>₹{vendor.credit_limit.toLocaleString()}</span>
                    </div>
                  )}
                </div>

                <div className="flex gap-2 pt-4 border-t">
                  <button
                    onClick={() => handleEdit(vendor)}
                    className="flex-1 bg-amber-100 text-amber-700 px-4 py-2 rounded hover:bg-amber-200"
                  >
                    Edit
                  </button>
                  <button
                    onClick={() => handleDelete(vendor.id)}
                    className="flex-1 bg-red-100 text-red-700 px-4 py-2 rounded hover:bg-red-200"
                  >
                    Delete
                  </button>
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {/* Create/Edit Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg max-w-2xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b border-gray-200">
              <h2 className="text-2xl font-bold text-gray-900">
                {editingVendor ? 'Edit Vendor' : 'Add New Vendor'}
              </h2>
            </div>

            <div className="p-6 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Vendor Name *</label>
                  <input
                    type="text"
                    value={formData.name}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Legal Name</label>
                  <input
                    type="text"
                    value={formData.legalName}
                    onChange={(e) => setFormData({ ...formData, legalName: e.target.value })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Tax ID / GSTIN</label>
                  <input
                    type="text"
                    value={formData.taxId}
                    onChange={(e) => setFormData({ ...formData, taxId: e.target.value })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Category</label>
                  <select
                    value={formData.category}
                    onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  >
                    <option value="RAW_MATERIAL">Raw Material</option>
                    <option value="COMPONENT">Component</option>
                    <option value="SERVICE">Service</option>
                    <option value="CONSUMABLE">Consumable</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Contact Person</label>
                  <input
                    type="text"
                    value={formData.contactPerson}
                    onChange={(e) => setFormData({ ...formData, contactPerson: e.target.value })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Email</label>
                  <input
                    type="email"
                    value={formData.email}
                    onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Phone</label>
                  <input
                    type="tel"
                    value={formData.phone}
                    onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Payment Terms</label>
                  <select
                    value={formData.paymentTerms}
                    onChange={(e) => setFormData({ ...formData, paymentTerms: e.target.value })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  >
                    <option value="NET_30">Net 30</option>
                    <option value="NET_60">Net 60</option>
                    <option value="NET_90">Net 90</option>
                    <option value="ADVANCE">Advance</option>
                    <option value="COD">Cash on Delivery</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Credit Limit</label>
                  <input
                    type="number"
                    value={formData.creditLimit}
                    onChange={(e) => setFormData({ ...formData, creditLimit: parseFloat(e.target.value) })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Rating (0-5)</label>
                  <input
                    type="number"
                    min="0"
                    max="5"
                    step="0.1"
                    value={formData.rating}
                    onChange={(e) => setFormData({ ...formData, rating: parseFloat(e.target.value) })}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                  />
                </div>
              </div>

              {/* Billing Address Section */}
              <div className="border-t pt-4">
                <h3 className="text-lg font-semibold text-gray-900 mb-4">Billing Address</h3>
                <div className="grid grid-cols-2 gap-4">
                  <div className="col-span-2">
                    <label className="block text-sm font-medium text-gray-700 mb-2">Street</label>
                    <input
                      type="text"
                      value={formData.street}
                      onChange={(e) => setFormData({ ...formData, street: e.target.value })}
                      className="w-full border border-gray-300 rounded-lg px-4 py-2"
                      placeholder="Street address, building name, floor, etc."
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">City</label>
                    <input
                      type="text"
                      value={formData.city}
                      onChange={(e) => setFormData({ ...formData, city: e.target.value })}
                      className="w-full border border-gray-300 rounded-lg px-4 py-2"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">State</label>
                    <input
                      type="text"
                      value={formData.state}
                      onChange={(e) => setFormData({ ...formData, state: e.target.value })}
                      className="w-full border border-gray-300 rounded-lg px-4 py-2"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">PIN Code</label>
                    <input
                      type="text"
                      value={formData.pincode}
                      onChange={(e) => setFormData({ ...formData, pincode: e.target.value })}
                      className="w-full border border-gray-300 rounded-lg px-4 py-2"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">Country</label>
                    <input
                      type="text"
                      value={formData.country}
                      onChange={(e) => setFormData({ ...formData, country: e.target.value })}
                      className="w-full border border-gray-300 rounded-lg px-4 py-2"
                    />
                  </div>
                </div>
              </div>

              {/* Shipping Address Section */}
              <div className="border-t pt-4">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-lg font-semibold text-gray-900">Shipping Address</h3>
                  <label className="flex items-center gap-2">
                    <input
                      type="checkbox"
                      checked={formData.sameAsbilling}
                      onChange={(e) => {
                        const checked = e.target.checked;
                        setFormData({ 
                          ...formData, 
                          sameAsbilling: checked,
                          shippingStreet: checked ? formData.street : formData.shippingStreet,
                          shippingCity: checked ? formData.city : formData.shippingCity,
                          shippingState: checked ? formData.state : formData.shippingState,
                          shippingCountry: checked ? formData.country : formData.shippingCountry,
                          shippingPincode: checked ? formData.pincode : formData.shippingPincode,
                        });
                      }}
                      className="w-4 h-4"
                    />
                    <span className="text-sm text-gray-700">Same as Billing</span>
                  </label>
                </div>
                
                {!formData.sameAsbilling && (
                  <div className="grid grid-cols-2 gap-4">
                    <div className="col-span-2">
                      <label className="block text-sm font-medium text-gray-700 mb-2">Street</label>
                      <input
                        type="text"
                        value={formData.shippingStreet}
                        onChange={(e) => setFormData({ ...formData, shippingStreet: e.target.value })}
                        className="w-full border border-gray-300 rounded-lg px-4 py-2"
                        placeholder="Street address, building name, floor, etc."
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">City</label>
                      <input
                        type="text"
                        value={formData.shippingCity}
                        onChange={(e) => setFormData({ ...formData, shippingCity: e.target.value })}
                        className="w-full border border-gray-300 rounded-lg px-4 py-2"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">State</label>
                      <input
                        type="text"
                        value={formData.shippingState}
                        onChange={(e) => setFormData({ ...formData, shippingState: e.target.value })}
                        className="w-full border border-gray-300 rounded-lg px-4 py-2"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">PIN Code</label>
                      <input
                        type="text"
                        value={formData.shippingPincode}
                        onChange={(e) => setFormData({ ...formData, shippingPincode: e.target.value })}
                        className="w-full border border-gray-300 rounded-lg px-4 py-2"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-2">Country</label>
                      <input
                        type="text"
                        value={formData.shippingCountry}
                        onChange={(e) => setFormData({ ...formData, shippingCountry: e.target.value })}
                        className="w-full border border-gray-300 rounded-lg px-4 py-2"
                      />
                    </div>
                  </div>
                )}
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Address (Legacy - will be migrated)</label>
                <textarea
                  value={formData.address}
                  onChange={(e) => setFormData({ ...formData, address: e.target.value })}
                  rows={2}
                  className="w-full border border-gray-300 rounded-lg px-4 py-2 bg-gray-50"
                  disabled
                />
              </div>

              <div className="flex items-center">
                <input
                  type="checkbox"
                  id="isActive"
                  checked={formData.isActive}
                  onChange={(e) => setFormData({ ...formData, isActive: e.target.checked })}
                  className="mr-2"
                />
                <label htmlFor="isActive" className="text-sm font-medium text-gray-700">
                  Active Vendor
                </label>
              </div>
            </div>

            <div className="p-6 border-t border-gray-200 flex justify-end gap-4">
              <button
                onClick={() => {
                  setShowModal(false);
                  resetForm();
                }}
                className="px-6 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
              >
                Cancel
              </button>
              <button
                onClick={handleSubmit}
                className="px-6 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700"
              >
                {editingVendor ? 'Update Vendor' : 'Create Vendor'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Duplicate Warning Modal */}
      <DuplicateWarning
        isOpen={duplicateState.isOpen}
        exactMatches={duplicateState.exactMatches}
        fuzzyMatches={duplicateState.fuzzyMatches}
        entityType="Vendor"
        onProceed={handleProceed}
        onCancel={handleCancel}
        formatRecord={(data) => (
          <div className="text-sm">
            <p className="font-semibold">{data.name || data.legal_name}</p>
            <p className="text-xs text-gray-600">GST: {data.tax_id || data.gst_number || 'N/A'}</p>
            <p className="text-xs text-gray-600">Email: {data.email || 'N/A'}</p>
            <p className="text-xs text-gray-600">Phone: {data.phone || 'N/A'}</p>
          </div>
        )}
      />
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { apiClient } from '../../../../lib/api-client';

interface Inspection {
  id: string;
  inspection_number: string;
  inspection_type: 'INCOMING' | 'IN_PROCESS' | 'FINAL';
  status: 'PENDING' | 'IN_PROGRESS' | 'PASSED' | 'FAILED' | 'ON_HOLD';
  inspection_date: string;
  item_name: string;
  inspected_quantity: number;
  accepted_quantity: number;
  rejected_quantity: number;
  on_hold_quantity: number;
  defect_rate: number;
  inspector_name: string;
  grn_id?: string;
  uid?: string;
  completion_date?: string;
  inspector_remarks?: string;
}

interface NCR {
  id: string;
  ncr_number: string;
  status: 'OPEN' | 'UNDER_REVIEW' | 'ACTION_PLANNED' | 'IN_PROGRESS' | 'RESOLVED' | 'CLOSED';
  ncr_date: string;
  description: string;
  root_cause: string;
  corrective_action: string;
  containment_action: string;
  preventive_action: string;
  raised_by: string;
  nonconformance_type: string;
  item_name?: string;
  quantity_affected?: number;
}

interface VendorRating {
  vendor_name: string;
  total_inspections: number;
  passed_inspections: number;
  pass_rate: number;
  total_defects: number;
  defect_rate_ppm: number;
  ncr_count: number;
  quality_score: number;
  quality_grade: string;
}

interface QualityDashboard {
  total_inspections: number;
  passed_inspections: number;
  failed_inspections: number;
  pass_rate: number;
  open_ncrs: number;
  closed_ncrs: number;
  top_defects: Array<{ defect_type: string; count: number }>;
}

export default function QualityPage() {
  const router = useRouter();
  const [activeTab, setActiveTab] = useState<'inspections' | 'ncr' | 'vendors' | 'dashboard'>('inspections');
  const [inspections, setInspections] = useState<Inspection[]>([]);
  const [ncrs, setNcrs] = useState<NCR[]>([]);
  const [vendorRatings, setVendorRatings] = useState<VendorRating[]>([]);
  const [dashboard, setDashboard] = useState<QualityDashboard | null>(null);
  
  // Dropdown data
  const [grns, setGrns] = useState<any[]>([]);
  const [uids, setUids] = useState<any[]>([]);
  const [users, setUsers] = useState<any[]>([]);
  const [selectedGRN, setSelectedGRN] = useState<any>(null);
  
  // Inspection form state
  const [showInspectionForm, setShowInspectionForm] = useState(false);
  const [inspectionForm, setInspectionForm] = useState({
    inspection_type: 'INCOMING',
    reference_type: 'GRN',
    reference_id: '',
    item_id: '',
    uid: '',
    quantity_inspected: 0,
    inspector_id: '',
    inspection_date: new Date().toISOString().split('T')[0],
    remarks: ''
  });

  // NCR form state
  const [showNcrForm, setShowNcrForm] = useState(false);
  const [ncrForm, setNcrForm] = useState({
    related_to: 'INSPECTION',
    reference_id: '',
    issue_description: '',
    severity: 'MEDIUM',
    root_cause: '',
    containment_action: '',
    corrective_action: '',
    preventive_action: ''
  });

  // Complete inspection form state
  const [showCompleteForm, setShowCompleteForm] = useState(false);
  const [completeInspectionId, setCompleteInspectionId] = useState('');
  const [completeForm, setCompleteForm] = useState({
    inspection_status: 'PASSED',
    quantity_accepted: 0,
    quantity_rejected: 0,
    quantity_on_hold: 0,
    inspector_remarks: '',
    generate_ncr: false,
    ncr_description: ''
  });

  // Edit/Delete state
  const [editingInspection, setEditingInspection] = useState<any>(null);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState<string | null>(null);
  const [viewingInspection, setViewingInspection] = useState<any>(null);
  const [viewingNCR, setViewingNCR] = useState<any>(null);
  const [editingNCR, setEditingNCR] = useState<any>(null);

  useEffect(() => {
    fetchData();
  }, [activeTab]);

  useEffect(() => {
    if (showInspectionForm) {
      fetchFormData();
    }
  }, [showInspectionForm]);

  const fetchFormData = async () => {
    try {
      // Fetch all UIDs for inspection (with forInspection flag)
      const uidsData = await apiClient.get('/uid?forInspection=true');
      setUids(uidsData || []);
      
      // Fetch users (for inspectors)
      const usersData = await apiClient.get('/users');
      setUsers(usersData);
    } catch (error) {
      console.error('Error fetching form data:', error);
    }
  };

  const handleUIDChange = async (uid: string) => {
    if (!uid) {
      setSelectedGRN(null);
      return;
    }
    
    try {
      // Fetch UID details which contains vendor, item, GRN info
      const uidDetails = await apiClient.get(`/uid/details/${uid}`);
      console.log('UID Details:', uidDetails);
      
      // Create a mock GRN object with vendor and item info from UID for display
      const mockGRN = {
        id: uidDetails.grnId,
        grn_number: `GRN-${uidDetails.grnId?.substring(0, 8) || 'UNKNOWN'}`,
        vendor_id: uidDetails.vendorId,
        vendor_name: uidDetails.vendorName,
        batch_number: uidDetails.batchNumber,
        lot_number: uidDetails.lotNumber,
        grn_items: [{
          item_id: uidDetails.itemId,
          item_name: uidDetails.itemName,
          item_code: uidDetails.itemCode,
        }]
      };
      
      console.log('Mock GRN for display:', mockGRN);
      setSelectedGRN(mockGRN);
      
      // Auto-fill form with UID data
      setInspectionForm({
        ...inspectionForm,
        uid: uid,
        reference_id: uidDetails.grnId || '',
        item_id: uidDetails.itemId || '',
        quantity_inspected: 1, // UID represents 1 unit
      });
    } catch (error) {
      console.error('Error fetching UID details:', error);
      alert('Failed to fetch UID information. Please check if the UID exists.');
    }
  };

  const fetchData = async () => {
    try {
      if (activeTab === 'inspections') {
        const data = await apiClient.get('/quality/inspections');
        setInspections(data);
      } else if (activeTab === 'ncr') {
        const data = await apiClient.get('/quality/ncr');
        setNcrs(data);
      } else if (activeTab === 'vendors') {
        const data = await apiClient.get('/quality/vendor-ratings');
        setVendorRatings(data);
      } else if (activeTab === 'dashboard') {
        const data = await apiClient.get('/quality/dashboard');
        setDashboard(data);
      }
    } catch (error) {
      console.error('Error fetching data:', error);
    }
  };

  const handleCreateInspection = async (e: React.FormEvent) => {
    e.preventDefault();
    
    // Validate UID is selected
    if (!inspectionForm.uid) {
      alert('UID is required for quality inspection. UID enables complete traceability.');
      return;
    }
    
    try {
      // Find selected inspector details
      const selectedInspector = users.find((user: any) => user.id === inspectionForm.inspector_id);
      
      // Get vendor and item details from selectedGRN (populated by handleUIDChange)
      const itemName = selectedGRN?.grn_items?.[0]?.item_name || '';
      const itemCode = selectedGRN?.grn_items?.[0]?.item_code || '';
      const vendorId = selectedGRN?.vendor_id || null;
      const vendorName = selectedGRN?.vendor_name || '';
      
      // Prepare data with all required fields
      const inspectionData = {
        inspection_type: inspectionForm.inspection_type,
        inspection_date: inspectionForm.inspection_date,
        grn_id: inspectionForm.reference_id || null,
        uid: inspectionForm.uid, // UID is now mandatory
        item_id: inspectionForm.item_id,
        item_name: itemName,
        item_code: itemCode,
        vendor_id: vendorId,
        vendor_name: vendorName,
        batch_number: selectedGRN?.batch_number || '',
        lot_number: selectedGRN?.lot_number || '',
        inspected_quantity: inspectionForm.quantity_inspected || 1,
        inspector_name: selectedInspector?.full_name || selectedInspector?.email || '',
        inspection_checklist: inspectionForm.remarks || '',
      };
      
      console.log('Creating inspection with UID:', inspectionForm.uid);
      console.log('Inspection data:', inspectionData);
      await apiClient.post('/quality/inspections', inspectionData);
      setShowInspectionForm(false);
      setInspectionForm({
        inspection_type: 'INCOMING',
        reference_type: 'GRN',
        reference_id: '',
        item_id: '',
        uid: '',
        quantity_inspected: 0,
        inspector_id: '',
        inspection_date: new Date().toISOString().split('T')[0],
        remarks: ''
      });
      setSelectedGRN(null);
      fetchData();
      alert('Inspection created successfully');
    } catch (error) {
      console.error('Error creating inspection:', error);
      alert('Failed to create inspection');
    }
  };

  const handleCompleteInspection = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await apiClient.post(`/quality/inspections/${completeInspectionId}/complete`, completeForm);
      setShowCompleteForm(false);
      setCompleteInspectionId('');
      setCompleteForm({
        inspection_status: 'PASSED',
        quantity_accepted: 0,
        quantity_rejected: 0,
        quantity_on_hold: 0,
        inspector_remarks: '',
        generate_ncr: false,
        ncr_description: ''
      });
      fetchData();
      alert('Inspection completed successfully');
    } catch (error) {
      console.error('Error completing inspection:', error);
      alert('Failed to complete inspection');
    }
  };

  const handleCreateNcr = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await apiClient.post('/quality/ncr', ncrForm);
      setShowNcrForm(false);
      setNcrForm({
        related_to: 'INSPECTION',
        reference_id: '',
        issue_description: '',
        severity: 'MEDIUM',
        root_cause: '',
        containment_action: '',
        corrective_action: '',
        preventive_action: ''
      });
      fetchData();
      alert('NCR created successfully');
    } catch (error) {
      console.error('Error creating NCR:', error);
      alert('Failed to create NCR');
    }
  };

  const handleEditInspection = (inspection: any) => {
    setEditingInspection(inspection);
    setInspectionForm({
      inspection_type: inspection.inspection_type,
      reference_type: 'GRN', // Assuming GRN for now
      reference_id: inspection.grn_id || '',
      item_id: inspection.item_id || '',
      uid: inspection.uid || '',
      quantity_inspected: inspection.quantity_inspected || 0,
      inspector_id: inspection.inspector_id || '',
      inspection_date: inspection.inspection_date ? new Date(inspection.inspection_date).toISOString().split('T')[0] : new Date().toISOString().split('T')[0],
      remarks: inspection.remarks || ''
    });
    setShowInspectionForm(true);
  };

  const handleUpdateInspection = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingInspection) return;

    try {
      // Defensive: Ensure item_id is always UUID
      let itemId = inspectionForm.item_id;
      if (selectedGRN?.grn_items) {
        const found = selectedGRN.grn_items.find((item: any) => item.item_id === itemId);
        if (!found) {
          const fallback = selectedGRN.grn_items.find((item: any) => item.item_name === itemId || item.item_code === itemId);
          if (fallback) {
            itemId = fallback.item_id;
          }
        }
      }

      const selectedItem = selectedGRN?.grn_items?.find((item: any) => item.item_id === itemId);
      const selectedInspector = users.find((user: any) => user.id === inspectionForm.inspector_id);

      const updateData = {
        inspection_type: inspectionForm.inspection_type,
        inspection_date: inspectionForm.inspection_date,
        grn_id: inspectionForm.reference_id,
        uid: inspectionForm.uid || null,
        item_id: itemId,
        item_name: selectedItem?.item_name || '',
        item_code: selectedItem?.item_code || '',
        vendor_id: selectedGRN?.vendor_id || null,
        vendor_name: selectedGRN?.vendor_name || '',
        batch_number: selectedGRN?.batch_number || '',
        lot_number: selectedGRN?.lot_number || '',
        inspected_quantity: inspectionForm.quantity_inspected || 0,
        inspector_id: inspectionForm.inspector_id,
        inspector_name: selectedInspector?.full_name || selectedInspector?.email || '',
        inspection_checklist: inspectionForm.remarks || '',
        remarks: inspectionForm.remarks
      };

      await apiClient.put(`/quality/inspections/${editingInspection.id}`, updateData);
      setShowInspectionForm(false);
      setEditingInspection(null);
      setInspectionForm({
        inspection_type: 'INCOMING',
        reference_type: 'GRN',
        reference_id: '',
        item_id: '',
        uid: '',
        quantity_inspected: 0,
        inspector_id: '',
        inspection_date: new Date().toISOString().split('T')[0],
        remarks: ''
      });
      setSelectedGRN(null);
      fetchData();
      alert('Inspection updated successfully');
    } catch (error) {
      console.error('Error updating inspection:', error);
      alert('Failed to update inspection');
    }
  };

  const handleDeleteInspection = async (inspectionId: string) => {
    try {
      await apiClient.delete(`/quality/inspections/${inspectionId}`);
      setShowDeleteConfirm(null);
      fetchData();
      alert('Inspection deleted successfully');
    } catch (error) {
      console.error('Error deleting inspection:', error);
      alert('Failed to delete inspection');
    }
  };

  const getStatusColor = (status: string) => {
    const colors: { [key: string]: string } = {
      'PENDING': 'bg-yellow-100 text-yellow-800',
      'IN_PROGRESS': 'bg-blue-100 text-blue-800',
      'PASSED': 'bg-green-100 text-green-800',
      'FAILED': 'bg-red-100 text-red-800',
      'ON_HOLD': 'bg-gray-100 text-gray-800',
      'OPEN': 'bg-red-100 text-red-800',
      'UNDER_REVIEW': 'bg-yellow-100 text-yellow-800',
      'ACTION_PLANNED': 'bg-blue-100 text-blue-800',
      'RESOLVED': 'bg-purple-100 text-purple-800',
      'CLOSED': 'bg-green-100 text-green-800'
    };
    return colors[status] || 'bg-gray-100 text-gray-800';
  };

  const getGradeColor = (grade: string) => {
    const colors: { [key: string]: string } = {
      'A+': 'bg-green-600 text-white',
      'A': 'bg-green-500 text-white',
      'B': 'bg-blue-500 text-white',
      'C': 'bg-yellow-500 text-white',
      'D': 'bg-orange-500 text-white',
      'F': 'bg-red-500 text-white'
    };
    return colors[grade] || 'bg-gray-500 text-white';
  };

  return (
    <div className="p-6">
      <div className="mb-6">
        <button
          onClick={() => router.push('/dashboard')}
          className="text-amber-600 hover:text-amber-800 text-sm mb-2"
        >
          ← Back to Dashboard
        </button>
      </div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">Quality & Inspection Management</h1>
        <div className="space-x-2">
          {activeTab === 'inspections' && (
            <button
              onClick={() => setShowInspectionForm(true)}
              className="bg-amber-600 text-white px-4 py-2 rounded hover:bg-amber-700"
            >
              + New Inspection
            </button>
          )}
          {activeTab === 'ncr' && (
            <button
              onClick={() => setShowNcrForm(true)}
              className="bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700"
            >
              + New NCR
            </button>
          )}
        </div>
      </div>

      {/* Tabs */}
      <div className="border-b mb-6">
        <div className="flex space-x-8">
          <button
            onClick={() => setActiveTab('inspections')}
            className={`pb-4 px-2 ${activeTab === 'inspections' ? 'border-b-2 border-amber-600 text-amber-600 font-semibold' : 'text-gray-600'}`}
          >
            Inspections
          </button>
          <button
            onClick={() => setActiveTab('ncr')}
            className={`pb-4 px-2 ${activeTab === 'ncr' ? 'border-b-2 border-amber-600 text-amber-600 font-semibold' : 'text-gray-600'}`}
          >
            NCR
          </button>
          <button
            onClick={() => setActiveTab('vendors')}
            className={`pb-4 px-2 ${activeTab === 'vendors' ? 'border-b-2 border-amber-600 text-amber-600 font-semibold' : 'text-gray-600'}`}
          >
            Vendor Ratings
          </button>
          <button
            onClick={() => setActiveTab('dashboard')}
            className={`pb-4 px-2 ${activeTab === 'dashboard' ? 'border-b-2 border-amber-600 text-amber-600 font-semibold' : 'text-gray-600'}`}
          >
            Dashboard
          </button>
        </div>
      </div>

      {/* Inspections Tab */}
      {activeTab === 'inspections' && (
        <div className="bg-white rounded-lg shadow">
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Inspection #</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Type</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Date</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Item</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Qty Inspected</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Accepted</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Rejected</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Defect Rate</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Inspector</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Actions</th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {inspections.map((inspection) => (
                  <tr key={inspection.id} className="hover:bg-gray-50">
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-amber-600">{inspection.inspection_number}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm">
                      <span className="px-2 py-1 text-xs rounded bg-purple-100 text-purple-800">
                        {inspection.inspection_type}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm">{new Date(inspection.inspection_date).toLocaleDateString()}</td>
                    <td className="px-6 py-4 text-sm">{inspection.item_name}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-right">{inspection.inspected_quantity}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-right text-green-600">{inspection.accepted_quantity || 0}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-right text-red-600">{inspection.rejected_quantity || 0}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-right">
                      {inspection.defect_rate ? `${inspection.defect_rate.toFixed(2)}%` : '-'}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`px-2 py-1 text-xs rounded ${getStatusColor(inspection.status)}`}>
                        {inspection.status}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm">{inspection.inspector_name}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm">
                      <div className="flex space-x-2">
                        <button
                          onClick={() => setViewingInspection(inspection)}
                          className="text-gray-600 hover:text-gray-800"
                        >
                          View
                        </button>
                        {inspection.status === 'PENDING' && (
                          <>
                            <button
                              onClick={() => handleEditInspection(inspection)}
                              className="text-blue-600 hover:text-blue-800"
                            >
                              Edit
                            </button>
                            <button
                              onClick={() => setShowDeleteConfirm(inspection.id)}
                              className="text-red-600 hover:text-red-800"
                            >
                              Delete
                            </button>
                          </>
                        )}
                        {(inspection.status === 'PENDING' || inspection.status === 'IN_PROGRESS') && (
                          <button
                            onClick={() => {
                              setCompleteInspectionId(inspection.id);
                              setCompleteForm({
                                ...completeForm,
                                quantity_accepted: inspection.inspected_quantity
                              });
                              setShowCompleteForm(true);
                            }}
                            className="text-amber-600 hover:text-amber-800"
                          >
                            Complete
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* NCR Tab */}
      {activeTab === 'ncr' && (
        <div className="bg-white rounded-lg shadow">
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">NCR #</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Raised Date</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Item/Part</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Issue Description</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Root Cause</th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Actions</th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {ncrs.map((ncr) => (
                  <tr key={ncr.id} className="hover:bg-gray-50">
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-red-600">{ncr.ncr_number}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm">{new Date(ncr.ncr_date).toLocaleDateString()}</td>
                    <td className="px-6 py-4 text-sm">
                      {ncr.item_name ? (
                        <div>
                          <div className="font-medium">{ncr.item_name}</div>
                          {ncr.quantity_affected && (
                            <div className="text-xs text-gray-500">Qty: {ncr.quantity_affected}</div>
                          )}
                        </div>
                      ) : (
                        <span className="text-gray-400">-</span>
                      )}
                    </td>
                    <td className="px-6 py-4 text-sm max-w-xs truncate">{ncr.description}</td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`px-2 py-1 text-xs rounded ${getStatusColor(ncr.status)}`}>
                        {ncr.status.replace(/_/g, ' ')}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-sm max-w-xs truncate">{ncr.root_cause || <span className="text-gray-400">Pending investigation</span>}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm">
                      <div className="flex space-x-2">
                        <button
                          onClick={() => setViewingNCR(ncr)}
                          className="text-gray-600 hover:text-gray-800"
                        >
                          View
                        </button>
                        {ncr.status !== 'CLOSED' && (
                          <button
                            onClick={() => setEditingNCR(ncr)}
                            className="text-blue-600 hover:text-blue-800"
                          >
                            Update
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Vendor Ratings Tab */}
      {activeTab === 'vendors' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {vendorRatings.map((vendor, index) => (
            <div key={index} className="bg-white rounded-lg shadow p-6">
              <div className="flex justify-between items-start mb-4">
                <h3 className="text-lg font-semibold">{vendor.vendor_name}</h3>
                <span className={`px-3 py-1 rounded-full font-bold ${getGradeColor(vendor.quality_grade)}`}>
                  {vendor.quality_grade}
                </span>
              </div>
              <div className="space-y-3">
                <div className="flex justify-between">
                  <span className="text-sm text-gray-600">Quality Score:</span>
                  <span className="font-semibold">{vendor.quality_score.toFixed(2)}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-sm text-gray-600">Pass Rate:</span>
                  <span className="font-semibold text-green-600">{vendor.pass_rate.toFixed(2)}%</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-sm text-gray-600">Defect Rate (PPM):</span>
                  <span className="font-semibold text-orange-600">{vendor.defect_rate_ppm.toFixed(0)}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-sm text-gray-600">Total Inspections:</span>
                  <span className="font-semibold">{vendor.total_inspections}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-sm text-gray-600">Passed:</span>
                  <span className="font-semibold text-green-600">{vendor.passed_inspections}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-sm text-gray-600">NCR Count:</span>
                  <span className="font-semibold text-red-600">{vendor.ncr_count}</span>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Dashboard Tab */}
      {activeTab === 'dashboard' && dashboard && (
        <div className="space-y-6">
          {/* Summary Cards */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <div className="bg-white rounded-lg shadow p-6">
              <div className="text-sm text-gray-600 mb-2">Total Inspections</div>
              <div className="text-3xl font-bold text-amber-600">{dashboard.total_inspections}</div>
            </div>
            <div className="bg-white rounded-lg shadow p-6">
              <div className="text-sm text-gray-600 mb-2">Pass Rate</div>
              <div className="text-3xl font-bold text-green-600">{dashboard.pass_rate.toFixed(1)}%</div>
            </div>
            <div className="bg-white rounded-lg shadow p-6">
              <div className="text-sm text-gray-600 mb-2">Open NCRs</div>
              <div className="text-3xl font-bold text-red-600">{dashboard.open_ncrs}</div>
            </div>
            <div className="bg-white rounded-lg shadow p-6">
              <div className="text-sm text-gray-600 mb-2">Closed NCRs</div>
              <div className="text-3xl font-bold text-gray-600">{dashboard.closed_ncrs}</div>
            </div>
          </div>

          {/* Inspection Breakdown */}
          <div className="bg-white rounded-lg shadow p-6">
            <h3 className="text-lg font-semibold mb-4">Inspection Results</h3>
            <div className="grid grid-cols-3 gap-4">
              <div className="text-center p-4 bg-green-50 rounded">
                <div className="text-2xl font-bold text-green-600">{dashboard.passed_inspections}</div>
                <div className="text-sm text-gray-600">Passed</div>
              </div>
              <div className="text-center p-4 bg-red-50 rounded">
                <div className="text-2xl font-bold text-red-600">{dashboard.failed_inspections}</div>
                <div className="text-sm text-gray-600">Failed</div>
              </div>
              <div className="text-center p-4 bg-gray-50 rounded">
                <div className="text-2xl font-bold text-gray-600">
                  {dashboard.total_inspections - dashboard.passed_inspections - dashboard.failed_inspections}
                </div>
                <div className="text-sm text-gray-600">Pending</div>
              </div>
            </div>
          </div>

          {/* Top Defects */}
          <div className="bg-white rounded-lg shadow p-6">
            <h3 className="text-lg font-semibold mb-4">Top 5 Defect Types</h3>
            <div className="space-y-3">
              {dashboard.top_defects.map((defect, index) => (
                <div key={index} className="flex items-center justify-between">
                  <div className="flex items-center space-x-3">
                    <div className="w-8 h-8 bg-red-100 text-red-600 rounded-full flex items-center justify-center font-semibold">
                      {index + 1}
                    </div>
                    <span className="font-medium">{defect.defect_type}</span>
                  </div>
                  <span className="px-3 py-1 bg-red-100 text-red-800 rounded-full text-sm font-semibold">
                    {defect.count}
                  </span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Create Inspection Modal */}
      {showInspectionForm && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto">
            <h2 className="text-xl font-bold mb-4">
              {editingInspection ? 'Edit Inspection' : 'Create New Inspection'}
            </h2>
            <form onSubmit={editingInspection ? handleUpdateInspection : handleCreateInspection} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium mb-1">Inspection Type</label>
                  <select
                    value={inspectionForm.inspection_type}
                    onChange={(e) => setInspectionForm({ ...inspectionForm, inspection_type: e.target.value })}
                    className="w-full border rounded px-3 py-2"
                    required
                  >
                    <option value="INCOMING">Incoming (IQC)</option>
                    <option value="IN_PROCESS">In-Process (IPQC)</option>
                    <option value="FINAL">Final (FQC)</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">Inspection Date</label>
                  <input
                    type="date"
                    value={inspectionForm.inspection_date}
                    onChange={(e) => setInspectionForm({ ...inspectionForm, inspection_date: e.target.value })}
                    className="w-full border rounded px-3 py-2"
                    required
                  />
                </div>
              </div>

              {/* UID Selection - PRIMARY FIELD - MANDATORY FOR TRACEABILITY */}
              <div className="bg-amber-50 border-2 border-amber-300 rounded-lg p-4">
                <label className="block text-sm font-semibold mb-2 text-amber-900">
                  🔍 Select UID (Required for Traceability) *
                </label>
                <select
                  value={inspectionForm.uid}
                  onChange={(e) => handleUIDChange(e.target.value)}
                  className="w-full border-2 border-amber-400 rounded px-3 py-2 focus:border-amber-600 focus:ring-2 focus:ring-amber-200"
                  required
                >
                  <option value="">Search and select UID...</option>
                  {uids.map((uid: any) => (
                    <option key={uid.uid} value={uid.uid}>
                      {uid.uid} - {uid.entityType} ({uid.status})
                    </option>
                  ))}
                </select>
                <p className="text-xs text-amber-700 mt-1">
                  ℹ️ UID is mandatory as it enables complete product traceability from receipt through warranty to repairs
                </p>
              </div>

              {/* Auto-populated Vendor Information (read-only) */}
              {selectedGRN && (
                <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                  <h3 className="text-sm font-semibold mb-2 text-blue-900">📦 Auto-populated from UID</h3>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="block text-xs text-blue-700 mb-1">Vendor</label>
                      <input
                        type="text"
                        value={selectedGRN.vendor_name || 'Loading...'}
                        className="w-full border rounded px-3 py-2 bg-gray-50 text-gray-700"
                        readOnly
                      />
                    </div>
                    <div>
                      <label className="block text-xs text-blue-700 mb-1">Item Code</label>
                      <input
                        type="text"
                        value={selectedGRN.grn_items?.[0]?.item_code || 'Loading...'}
                        className="w-full border rounded px-3 py-2 bg-gray-50 text-gray-700"
                        readOnly
                      />
                    </div>
                    <div className="col-span-2">
                      <label className="block text-xs text-blue-700 mb-1">Item Name</label>
                      <input
                        type="text"
                        value={selectedGRN.grn_items?.[0]?.item_name || 'Loading...'}
                        className="w-full border rounded px-3 py-2 bg-gray-50 text-gray-700"
                        readOnly
                      />
                    </div>
                    <div>
                      <label className="block text-xs text-blue-700 mb-1">Batch Number</label>
                      <input
                        type="text"
                        value={selectedGRN.batch_number || '-'}
                        className="w-full border rounded px-3 py-2 bg-gray-50 text-gray-700"
                        readOnly
                      />
                    </div>
                    <div>
                      <label className="block text-xs text-blue-700 mb-1">GRN Number</label>
                      <input
                        type="text"
                        value={selectedGRN.grn_number || '-'}
                        className="w-full border rounded px-3 py-2 bg-gray-50 text-gray-700"
                        readOnly
                      />
                    </div>
                  </div>
                </div>
              )}

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium mb-1">Quantity to Inspect</label>
                  <input
                    type="number"
                    value={inspectionForm.quantity_inspected}
                    onChange={(e) => setInspectionForm({ ...inspectionForm, quantity_inspected: parseFloat(e.target.value) })}
                    className="w-full border rounded px-3 py-2"
                    min="0"
                    step="0.01"
                    required
                  />
                  <p className="text-xs text-gray-500 mt-1">Usually 1 for UID-based inspection</p>
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">Inspector</label>
                  <select
                    value={inspectionForm.inspector_id}
                    onChange={(e) => setInspectionForm({ ...inspectionForm, inspector_id: e.target.value })}
                    className="w-full border rounded px-3 py-2"
                    required
                  >
                    <option value="">Select Inspector...</option>
                    {users.map(user => (
                      <option key={user.id} value={user.id}>
                        {user.full_name || user.email}
                      </option>
                    ))}
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">Remarks</label>
                <textarea
                  value={inspectionForm.remarks}
                  onChange={(e) => setInspectionForm({ ...inspectionForm, remarks: e.target.value })}
                  className="w-full border rounded px-3 py-2"
                  rows={3}
                  placeholder="Visual inspection notes, dimensional checks, functional tests..."
                />
              </div>

              <div className="flex justify-end space-x-3 pt-4">
                <button
                  type="button"
                  onClick={() => {
                    setShowInspectionForm(false);
                    setEditingInspection(null);
                    setInspectionForm({
                      inspection_type: 'INCOMING',
                      reference_type: 'GRN',
                      reference_id: '',
                      item_id: '',
                      uid: '',
                      quantity_inspected: 0,
                      inspector_id: '',
                      inspection_date: new Date().toISOString().split('T')[0],
                      remarks: ''
                    });
                    setSelectedGRN(null);
                  }}
                  className="px-4 py-2 border rounded hover:bg-gray-50"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-amber-600 text-white rounded hover:bg-amber-700"
                  disabled={!inspectionForm.uid}
                >
                  {editingInspection ? 'Update Inspection' : 'Create Inspection'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Complete Inspection Modal */}
      {showCompleteForm && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto">
            <h2 className="text-xl font-bold mb-4">Complete Inspection</h2>
            <form onSubmit={handleCompleteInspection} className="space-y-4">
              <div>
                <label className="block text-sm font-medium mb-1">Inspection Status</label>
                <select
                  value={completeForm.inspection_status}
                  onChange={(e) => setCompleteForm({ ...completeForm, inspection_status: e.target.value })}
                  className="w-full border rounded px-3 py-2"
                  required
                >
                  <option value="PASSED">Passed</option>
                  <option value="FAILED">Failed</option>
                  <option value="ON_HOLD">On Hold</option>
                </select>
              </div>

              <div className="grid grid-cols-3 gap-4">
                <div>
                  <label className="block text-sm font-medium mb-1">Quantity Accepted</label>
                  <input
                    type="number"
                    value={completeForm.quantity_accepted}
                    onChange={(e) => setCompleteForm({ ...completeForm, quantity_accepted: parseFloat(e.target.value) })}
                    className="w-full border rounded px-3 py-2"
                    min="0"
                    step="0.01"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">Quantity Rejected</label>
                  <input
                    type="number"
                    value={completeForm.quantity_rejected}
                    onChange={(e) => setCompleteForm({ ...completeForm, quantity_rejected: parseFloat(e.target.value) })}
                    className="w-full border rounded px-3 py-2"
                    min="0"
                    step="0.01"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">Quantity On Hold</label>
                  <input
                    type="number"
                    value={completeForm.quantity_on_hold}
                    onChange={(e) => setCompleteForm({ ...completeForm, quantity_on_hold: parseFloat(e.target.value) })}
                    className="w-full border rounded px-3 py-2"
                    min="0"
                    step="0.01"
                    required
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">Inspector Remarks</label>
                <textarea
                  value={completeForm.inspector_remarks}
                  onChange={(e) => setCompleteForm({ ...completeForm, inspector_remarks: e.target.value })}
                  className="w-full border rounded px-3 py-2"
                  rows={3}
                />
              </div>

              <div className="flex items-center space-x-2">
                <input
                  type="checkbox"
                  checked={completeForm.generate_ncr}
                  onChange={(e) => setCompleteForm({ ...completeForm, generate_ncr: e.target.checked })}
                  className="rounded"
                />
                <label className="text-sm font-medium">Generate NCR (Non-Conformance Report)</label>
              </div>

              {completeForm.generate_ncr && (
                <div>
                  <label className="block text-sm font-medium mb-1">NCR Description</label>
                  <textarea
                    value={completeForm.ncr_description}
                    onChange={(e) => setCompleteForm({ ...completeForm, ncr_description: e.target.value })}
                    className="w-full border rounded px-3 py-2"
                    rows={3}
                    placeholder="Describe the non-conformance issue..."
                  />
                </div>
              )}

              <div className="flex justify-end space-x-3 pt-4">
                <button
                  type="button"
                  onClick={() => setShowCompleteForm(false)}
                  className="px-4 py-2 border rounded hover:bg-gray-50"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700"
                >
                  Complete Inspection
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Create NCR Modal */}
      {showNcrForm && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto">
            <h2 className="text-xl font-bold mb-4">Create Non-Conformance Report (NCR)</h2>
            <form onSubmit={handleCreateNcr} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium mb-1">Related To</label>
                  <select
                    value={ncrForm.related_to}
                    onChange={(e) => setNcrForm({ ...ncrForm, related_to: e.target.value })}
                    className="w-full border rounded px-3 py-2"
                    required
                  >
                    <option value="INSPECTION">Inspection</option>
                    <option value="VENDOR">Vendor</option>
                    <option value="PRODUCTION">Production</option>
                    <option value="CUSTOMER_COMPLAINT">Customer Complaint</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">Severity</label>
                  <select
                    value={ncrForm.severity}
                    onChange={(e) => setNcrForm({ ...ncrForm, severity: e.target.value })}
                    className="w-full border rounded px-3 py-2"
                    required
                  >
                    <option value="LOW">Low</option>
                    <option value="MEDIUM">Medium</option>
                    <option value="HIGH">High</option>
                    <option value="CRITICAL">Critical</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">Reference ID (UUID)</label>
                <input
                  type="text"
                  value={ncrForm.reference_id}
                  onChange={(e) => setNcrForm({ ...ncrForm, reference_id: e.target.value })}
                  className="w-full border rounded px-3 py-2"
                />
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">Issue Description</label>
                <textarea
                  value={ncrForm.issue_description}
                  onChange={(e) => setNcrForm({ ...ncrForm, issue_description: e.target.value })}
                  className="w-full border rounded px-3 py-2"
                  rows={3}
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">Root Cause Analysis</label>
                <textarea
                  value={ncrForm.root_cause}
                  onChange={(e) => setNcrForm({ ...ncrForm, root_cause: e.target.value })}
                  className="w-full border rounded px-3 py-2"
                  rows={2}
                  placeholder="5 Whys, Fishbone analysis, etc."
                />
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">Containment Action (Immediate)</label>
                <textarea
                  value={ncrForm.containment_action}
                  onChange={(e) => setNcrForm({ ...ncrForm, containment_action: e.target.value })}
                  className="w-full border rounded px-3 py-2"
                  rows={2}
                  placeholder="Immediate actions to contain the issue"
                />
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">Corrective Action (Eliminate Root Cause)</label>
                <textarea
                  value={ncrForm.corrective_action}
                  onChange={(e) => setNcrForm({ ...ncrForm, corrective_action: e.target.value })}
                  className="w-full border rounded px-3 py-2"
                  rows={2}
                  placeholder="Actions to eliminate root cause"
                />
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">Preventive Action (Prevent Recurrence)</label>
                <textarea
                  value={ncrForm.preventive_action}
                  onChange={(e) => setNcrForm({ ...ncrForm, preventive_action: e.target.value })}
                  className="w-full border rounded px-3 py-2"
                  rows={2}
                  placeholder="Actions to prevent recurrence"
                />
              </div>

              <div className="flex justify-end space-x-3 pt-4">
                <button
                  type="button"
                  onClick={() => setShowNcrForm(false)}
                  className="px-4 py-2 border rounded hover:bg-gray-50"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700"
                >
                  Create NCR
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {showDeleteConfirm && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-md">
            <h2 className="text-xl font-bold mb-4">Confirm Delete</h2>
            <p className="text-gray-600 mb-6">
              Are you sure you want to delete this inspection? This action cannot be undone.
            </p>
            <div className="flex justify-end space-x-3">
              <button
                onClick={() => setShowDeleteConfirm(null)}
                className="px-4 py-2 border rounded hover:bg-gray-50"
              >
                Cancel
              </button>
              <button
                onClick={() => handleDeleteInspection(showDeleteConfirm)}
                className="px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700"
              >
                Delete
              </button>
            </div>
          </div>
        </div>
      )}

      {/* View Inspection Details Modal */}
      {viewingInspection && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-3xl max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-start mb-4">
              <h2 className="text-xl font-bold">Inspection Details</h2>
              <button
                onClick={() => setViewingInspection(null)}
                className="text-gray-400 hover:text-gray-600"
              >
                ✕
              </button>
            </div>
            
            <div className="grid grid-cols-2 gap-4 mb-6">
              <div>
                <label className="text-sm font-medium text-gray-600">Inspection Number</label>
                <p className="text-lg font-semibold text-amber-600">{viewingInspection.inspection_number}</p>
              </div>
              <div>
                <label className="text-sm font-medium text-gray-600">Status</label>
                <p>
                  <span className={`px-3 py-1 text-sm rounded ${getStatusColor(viewingInspection.status)}`}>
                    {viewingInspection.status}
                  </span>
                </p>
              </div>
              <div>
                <label className="text-sm font-medium text-gray-600">Type</label>
                <p className="font-medium">{viewingInspection.inspection_type}</p>
              </div>
              <div>
                <label className="text-sm font-medium text-gray-600">Date</label>
                <p className="font-medium">{new Date(viewingInspection.inspection_date).toLocaleDateString()}</p>
              </div>
              <div>
                <label className="text-sm font-medium text-gray-600">Item</label>
                <p className="font-medium">{viewingInspection.item_name}</p>
              </div>
              <div>
                <label className="text-sm font-medium text-gray-600">Inspector</label>
                <p className="font-medium">{viewingInspection.inspector_name}</p>
              </div>
            </div>

            <div className="border-t pt-4 mb-4">
              <h3 className="font-semibold mb-3">Inspection Results</h3>
              <div className="grid grid-cols-4 gap-4">
                <div className="bg-blue-50 p-3 rounded">
                  <div className="text-sm text-gray-600">Inspected</div>
                  <div className="text-xl font-bold text-blue-600">{viewingInspection.inspected_quantity}</div>
                </div>
                <div className="bg-green-50 p-3 rounded">
                  <div className="text-sm text-gray-600">Accepted</div>
                  <div className="text-xl font-bold text-green-600">{viewingInspection.accepted_quantity || 0}</div>
                </div>
                <div className="bg-red-50 p-3 rounded">
                  <div className="text-sm text-gray-600">Rejected</div>
                  <div className="text-xl font-bold text-red-600">{viewingInspection.rejected_quantity || 0}</div>
                </div>
                <div className="bg-yellow-50 p-3 rounded">
                  <div className="text-sm text-gray-600">On Hold</div>
                  <div className="text-xl font-bold text-yellow-600">{viewingInspection.on_hold_quantity || 0}</div>
                </div>
              </div>
            </div>

            {viewingInspection.defect_rate && (
              <div className="border-t pt-4 mb-4">
                <label className="text-sm font-medium text-gray-600">Defect Rate</label>
                <p className="text-2xl font-bold text-red-600">{viewingInspection.defect_rate.toFixed(2)}%</p>
              </div>
            )}

            {viewingInspection.inspector_remarks && (
              <div className="border-t pt-4 mb-4">
                <label className="text-sm font-medium text-gray-600">Inspector Remarks</label>
                <p className="mt-1 text-gray-800">{viewingInspection.inspector_remarks}</p>
              </div>
            )}

            {viewingInspection.uid && (
              <div className="border-t pt-4 mb-4">
                <label className="text-sm font-medium text-gray-600">UID</label>
                <p className="font-mono text-sm bg-gray-100 p-2 rounded">{viewingInspection.uid}</p>
              </div>
            )}

            <div className="flex justify-end pt-4">
              <button
                onClick={() => setViewingInspection(null)}
                className="px-4 py-2 bg-gray-200 text-gray-800 rounded hover:bg-gray-300"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* View NCR Details Modal */}
      {viewingNCR && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-3xl max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-start mb-4">
              <h2 className="text-xl font-bold">NCR Details</h2>
              <button
                onClick={() => setViewingNCR(null)}
                className="text-gray-400 hover:text-gray-600"
              >
                ✕
              </button>
            </div>
            
            <div className="grid grid-cols-2 gap-4 mb-6">
              <div>
                <label className="text-sm font-medium text-gray-600">NCR Number</label>
                <p className="text-lg font-semibold text-red-600">{viewingNCR.ncr_number}</p>
              </div>
              <div>
                <label className="text-sm font-medium text-gray-600">Status</label>
                <p>
                  <span className={`px-3 py-1 text-sm rounded ${getStatusColor(viewingNCR.status)}`}>
                    {viewingNCR.status}
                  </span>
                </p>
              </div>
              <div>
                <label className="text-sm font-medium text-gray-600">Type</label>
                <p className="font-medium">{viewingNCR.nonconformance_type}</p>
              </div>
              <div>
                <label className="text-sm font-medium text-gray-600">Date Raised</label>
                <p className="font-medium">{new Date(viewingNCR.ncr_date).toLocaleDateString()}</p>
              </div>
              {viewingNCR.item_name && (
                <div>
                  <label className="text-sm font-medium text-gray-600">Item</label>
                  <p className="font-medium">{viewingNCR.item_name}</p>
                </div>
              )}
              {viewingNCR.quantity_affected && (
                <div>
                  <label className="text-sm font-medium text-gray-600">Quantity Affected</label>
                  <p className="font-medium">{viewingNCR.quantity_affected}</p>
                </div>
              )}
            </div>

            <div className="space-y-4">
              <div className="border-t pt-4">
                <label className="text-sm font-medium text-gray-600 block mb-2">Issue Description</label>
                <p className="text-gray-800 bg-gray-50 p-3 rounded">{viewingNCR.description}</p>
              </div>

              {/* NCR Workflow Status */}
              <div className="border-t pt-4">
                <label className="text-sm font-medium text-gray-600 block mb-2">NCR Workflow</label>
                <div className="bg-blue-50 border border-blue-200 rounded p-4">
                  <div className="flex items-center space-x-2 mb-2">
                    <span className={`px-3 py-1 text-sm rounded ${getStatusColor(viewingNCR.status)}`}>
                      {viewingNCR.status.replace(/_/g, ' ')}
                    </span>
                    <span className="text-sm text-gray-600">
                      {viewingNCR.status === 'OPEN' && '→ Issue identified, awaiting review'}
                      {viewingNCR.status === 'UNDER_REVIEW' && '→ Being investigated by quality team'}
                      {viewingNCR.status === 'ACTION_PLANNED' && '→ Corrective actions planned, awaiting execution'}
                      {viewingNCR.status === 'IN_PROGRESS' && '→ Corrective actions being implemented'}
                      {viewingNCR.status === 'RESOLVED' && '→ Actions completed, awaiting verification'}
                      {viewingNCR.status === 'CLOSED' && '→ Verified and closed'}
                    </span>
                  </div>
                  <div className="text-xs text-gray-600 mt-2">
                    <p className="font-medium mb-1">Next Steps:</p>
                    {viewingNCR.status === 'OPEN' && (
                      <ul className="list-disc list-inside space-y-1">
                        <li>Conduct root cause analysis</li>
                        <li>Update status to &quot;Under Review&quot;</li>
                      </ul>
                    )}
                    {viewingNCR.status === 'UNDER_REVIEW' && (
                      <ul className="list-disc list-inside space-y-1">
                        <li>Complete root cause investigation</li>
                        <li>Plan corrective and preventive actions</li>
                        <li>Update status to &quot;Action Planned&quot;</li>
                      </ul>
                    )}
                    {viewingNCR.status === 'ACTION_PLANNED' && (
                      <ul className="list-disc list-inside space-y-1">
                        <li>Begin implementing corrective actions</li>
                        <li>Update status to &quot;In Progress&quot;</li>
                      </ul>
                    )}
                    {viewingNCR.status === 'IN_PROGRESS' && (
                      <ul className="list-disc list-inside space-y-1">
                        <li>Complete all corrective actions</li>
                        <li>Verify effectiveness</li>
                        <li>Update status to &quot;Resolved&quot;</li>
                      </ul>
                    )}
                    {viewingNCR.status === 'RESOLVED' && (
                      <ul className="list-disc list-inside space-y-1">
                        <li>Final verification by quality manager</li>
                        <li>Close NCR if satisfactory</li>
                      </ul>
                    )}
                    {viewingNCR.status === 'CLOSED' && (
                      <p className="text-green-700">✓ NCR completed and verified</p>
                    )}
                  </div>
                </div>
              </div>

              {viewingNCR.root_cause && (
                <div className="border-t pt-4">
                  <label className="text-sm font-medium text-gray-600 block mb-2">Root Cause Analysis</label>
                  <p className="text-gray-800 bg-gray-50 p-3 rounded">{viewingNCR.root_cause}</p>
                </div>
              )}

              {viewingNCR.containment_action && (
                <div className="border-t pt-4">
                  <label className="text-sm font-medium text-gray-600 block mb-2">Containment Action (Immediate)</label>
                  <p className="text-gray-800 bg-gray-50 p-3 rounded">{viewingNCR.containment_action}</p>
                </div>
              )}

              {viewingNCR.corrective_action && (
                <div className="border-t pt-4">
                  <label className="text-sm font-medium text-gray-600 block mb-2">Corrective Action (Eliminate Root Cause)</label>
                  <p className="text-gray-800 bg-gray-50 p-3 rounded">{viewingNCR.corrective_action}</p>
                </div>
              )}

              {viewingNCR.preventive_action && (
                <div className="border-t pt-4">
                  <label className="text-sm font-medium text-gray-600 block mb-2">Preventive Action (Prevent Recurrence)</label>
                  <p className="text-gray-800 bg-gray-50 p-3 rounded">{viewingNCR.preventive_action}</p>
                </div>
              )}
            </div>

            <div className="flex justify-end space-x-3 pt-6 border-t mt-6">
              {viewingNCR.status !== 'CLOSED' && (
                <button
                  onClick={() => {
                    setEditingNCR(viewingNCR);
                    setViewingNCR(null);
                  }}
                  className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700"
                >
                  Update NCR
                </button>
              )}
              <button
                onClick={() => setViewingNCR(null)}
                className="px-4 py-2 bg-gray-200 text-gray-800 rounded hover:bg-gray-300"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Edit NCR Modal */}
      {editingNCR && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto">
            <h2 className="text-xl font-bold mb-4">Update NCR - {editingNCR.ncr_number}</h2>
            <form
              onSubmit={async (e) => {
                e.preventDefault();
                try {
                  await apiClient.put(`/quality/ncr/${editingNCR.id}`, {
                    status: editingNCR.status,
                    root_cause: editingNCR.root_cause,
                    containment_action: editingNCR.containment_action,
                    corrective_action: editingNCR.corrective_action,
                    preventive_action: editingNCR.preventive_action,
                  });
                  setEditingNCR(null);
                  fetchData();
                  alert('NCR updated successfully');
                } catch (error) {
                  console.error('Error updating NCR:', error);
                  alert('Failed to update NCR');
                }
              }}
              className="space-y-4"
            >
              <div>
                <label className="block text-sm font-medium mb-1">Status</label>
                <select
                  value={editingNCR.status}
                  onChange={(e) => setEditingNCR({ ...editingNCR, status: e.target.value })}
                  className="w-full border rounded px-3 py-2"
                  required
                >
                  <option value="OPEN">Open</option>
                  <option value="UNDER_REVIEW">Under Review</option>
                  <option value="ACTION_PLANNED">Action Planned</option>
                  <option value="IN_PROGRESS">In Progress</option>
                  <option value="RESOLVED">Resolved</option>
                  <option value="CLOSED">Closed</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">Root Cause Analysis</label>
                <textarea
                  value={editingNCR.root_cause || ''}
                  onChange={(e) => setEditingNCR({ ...editingNCR, root_cause: e.target.value })}
                  className="w-full border rounded px-3 py-2"
                  rows={3}
                />
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">Containment Action</label>
                <textarea
                  value={editingNCR.containment_action || ''}
                  onChange={(e) => setEditingNCR({ ...editingNCR, containment_action: e.target.value })}
                  className="w-full border rounded px-3 py-2"
                  rows={2}
                />
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">Corrective Action</label>
                <textarea
                  value={editingNCR.corrective_action || ''}
                  onChange={(e) => setEditingNCR({ ...editingNCR, corrective_action: e.target.value })}
                  className="w-full border rounded px-3 py-2"
                  rows={2}
                />
              </div>

              <div>
                <label className="block text-sm font-medium mb-1">Preventive Action</label>
                <textarea
                  value={editingNCR.preventive_action || ''}
                  onChange={(e) => setEditingNCR({ ...editingNCR, preventive_action: e.target.value })}
                  className="w-full border rounded px-3 py-2"
                  rows={2}
                />
              </div>

              <div className="flex justify-end space-x-3 pt-4">
                <button
                  type="button"
                  onClick={() => setEditingNCR(null)}
                  className="px-4 py-2 border rounded hover:bg-gray-50"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700"
                >
                  Update NCR
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { apiClient } from '../../../../lib/api-client';
import SearchableSelect from '../../../components/SearchableSelect';
import DuplicateWarning, { useDuplicateDetection } from '../../../components/DuplicateWarning';

type TabType = 'customers' | 'quotations' | 'orders' | 'dispatch' | 'warranties';

interface Customer {
  id: string;
  customer_code: string;
  customer_name: string;
  customer_type: string;
  contact_person?: string;
  email?: string;
  phone?: string;
  mobile?: string;
  gst_number?: string;
  pan_number?: string;
  billing_address?: string;
  shipping_address?: string;
  city?: string;
  state?: string;
  pincode?: string;
  country?: string;
  credit_limit: number;
  credit_days: number;
  is_active: boolean;
}

interface QuotationItem {
  id?: string;
  item_id: string;
  item_description: string;
  quantity: number;
  converted_quantity?: number;
  pending_quantity?: number;
  unit_price: number;
  discount_percentage: number;
  tax_percentage: number;
  line_total?: number;
}

interface Quotation {
  id: string;
  quotation_number: string;
  customer_id: string;
  customer_name?: string;
  quotation_date: string;
  valid_until: string;
  status: string;
  total_amount: number;
  discount_amount: number;
  tax_amount: number;
  net_amount: number;
  payment_terms?: string;
  delivery_terms?: string;
  created_at: string;
  quotation_items?: QuotationItem[];
}

interface SalesOrder {
  id: string;
  so_number: string;
  customer_id: string;
  customer_name?: string;
  order_date: string;
  expected_delivery_date?: string;
  status: string;
  total_amount: number;
  net_amount: number;
  advance_paid: number;
  balance_amount: number;
  project?: string;
  is_direct_order?: boolean;
  source_type?: 'QUOTATION' | 'DIRECT' | 'INTERNAL';
  created_at: string;
}

interface DispatchNote {
  id: string;
  dn_number: string;
  sales_order_id: string;
  so_number?: string;
  customer_id: string;
  customer_name?: string;
  dispatch_date: string;
  transporter_name?: string;
  vehicle_number?: string;
  lr_number?: string;
  created_at: string;
}

interface Warranty {
  id: string;
  warranty_number: string;
  uid: string;
  customer_name?: string;
  item_description?: string;
  warranty_start_date: string;
  warranty_duration_months: number;
  warranty_end_date: string;
  warranty_type: string;
  status: string;
  claim_count: number;
  created_at: string;
}

interface UIDRecord {
  id?: string;
  uid: string;
  entity_id: string;
  status: string;
  location?: string;
  grn_id?: string;
  created_at?: string;
}

export default function SalesPage() {
  const [activeTab, setActiveTab] = useState<TabType>('customers');
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [quotations, setQuotations] = useState<Quotation[]>([]);
  const [orders, setOrders] = useState<SalesOrder[]>([]);
  const [dispatches, setDispatches] = useState<DispatchNote[]>([]);
  const [warranties, setWarranties] = useState<Warranty[]>([]);
  const [items, setItems] = useState<any[]>([]);
  const [availableUIDs, setAvailableUIDs] = useState<{ [key: string]: UIDRecord[] }>({});
  const [loadingUIDs, setLoadingUIDs] = useState<{ [key: number]: boolean }>({});
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [sendingSOEmailId, setSendingSOEmailId] = useState<string | null>(null);

  // Sales Order edit
  const [showOrderEditForm, setShowOrderEditForm] = useState(false);
  const [editingOrderId, setEditingOrderId] = useState<string | null>(null);
  const [orderEditForm, setOrderEditForm] = useState({
    expected_delivery_date: '',
    payment_terms: '',
    delivery_terms: '',
    notes: '',
    status: 'CONFIRMED',
  });

  // Dispatch edit
  const [showDispatchEditForm, setShowDispatchEditForm] = useState(false);
  const [editingDispatchId, setEditingDispatchId] = useState<string | null>(null);
  const [dispatchEditForm, setDispatchEditForm] = useState({
    dispatch_date: '',
    transporter_name: '',
    vehicle_number: '',
    lr_number: '',
    lr_date: '',
    delivery_address: '',
    notes: '',
  });

  // Warranty edit
  const [showWarrantyEditForm, setShowWarrantyEditForm] = useState(false);
  const [editingWarrantyId, setEditingWarrantyId] = useState<string | null>(null);
  const [warrantyEditForm, setWarrantyEditForm] = useState({
    status: 'ACTIVE',
    warranty_type: 'STANDARD',
  });
  
  // Customer form
  const [showCustomerForm, setShowCustomerForm] = useState(false);
  const [editingCustomerId, setEditingCustomerId] = useState<string | null>(null);
  const [customerForm, setCustomerForm] = useState({
    customer_name: '',
    customer_type: 'REGULAR',
    contact_person: '',
    email: '',
    phone: '',
    mobile: '',
    gst_number: '',
    pan_number: '',
    billing_address: '',
    shipping_address: '',
    city: '',
    state: '',
    country: 'India',
    pincode: '',
    credit_limit: 0,
    credit_days: 30,
  });

  const resetCustomerForm = () => {
    setEditingCustomerId(null);
    setCustomerForm({
      customer_name: '',
      customer_type: 'REGULAR',
      contact_person: '',
      email: '',
      phone: '',
      mobile: '',
      gst_number: '',
      pan_number: '',
      billing_address: '',
      shipping_address: '',
      city: '',
      state: '',
      country: 'India',
      pincode: '',
      credit_limit: 0,
      credit_days: 30,
    });
  };

  // Quotation form
  const createDefaultQuotationForm = (): {
    customer_id: string;
    quotation_date: string;
    valid_until: string;
    payment_terms: string;
    delivery_terms: string;
    notes: string;
    items: QuotationItem[];
  } => ({
    customer_id: '',
    quotation_date: new Date().toISOString().split('T')[0],
    valid_until: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    payment_terms: '',
    delivery_terms: '',
    notes: '',
    items: [] as QuotationItem[],
  });
  const [showQuotationForm, setShowQuotationForm] = useState(false);
  const [quotationForm, setQuotationForm] = useState(createDefaultQuotationForm);
  const [editingQuotationId, setEditingQuotationId] = useState<string | null>(null);
  const [viewingQuotation, setViewingQuotation] = useState<any | null>(null);

  // Dispatch form
  const [showDispatchForm, setShowDispatchForm] = useState(false);
  const [selectedOrderForDispatch, setSelectedOrderForDispatch] = useState<SalesOrder | null>(null);
  const [salesOrderItems, setSalesOrderItems] = useState<any[]>([]);
  const [dispatchForm, setDispatchForm] = useState({
    sales_order_id: '',
    dispatch_date: new Date().toISOString().split('T')[0],
    transporter_name: '',
    vehicle_number: '',
    lr_number: '',
    lr_date: new Date().toISOString().split('T')[0],
    delivery_address: '',
    notes: '',
    items: [] as { sales_order_item_id: string; item_id: string; uid: string[]; quantity: number; batch_number?: string }[],
  });

  // Warranty form
  const [showWarrantyForm, setShowWarrantyForm] = useState(false);
  const [warrantyForm, setWarrantyForm] = useState({
    uid: '',
    warranty_duration_months: 12,
    warranty_type: 'STANDARD',
    notes: '',
  });

  // Duplicate detection hooks
  const customerDuplicateDetection = useDuplicateDetection();
  const quotationDuplicateDetection = useDuplicateDetection();
  const salesOrderDuplicateDetection = useDuplicateDetection();

  // Sales Order conversion
  const [showSOConversionForm, setShowSOConversionForm] = useState(false);
  const [selectedQuotationForSO, setSelectedQuotationForSO] = useState<Quotation | null>(null);
  const [soConversionForm, setSOConversionForm] = useState({
    expected_delivery_date: '',
    advance_amount: 0,
    payment_terms: '',
    special_instructions: '',
    project: '',
  });
  const [conversionItems, setConversionItems] = useState<{[key: string]: number}>({});

  // Direct Sales Order form
  const [showDirectSOForm, setShowDirectSOForm] = useState(false);
  const [directSOForm, setDirectSOForm] = useState({
    customer_id: '',
    order_date: new Date().toISOString().split('T')[0],
    expected_delivery_date: '',
    payment_terms: '',
    project: '',
    source_type: 'DIRECT' as 'DIRECT' | 'INTERNAL',
    items: [] as QuotationItem[],
  });

  const handlePrintWarranty = async (warrantyId: string) => {
    try {
      // Try to open a print window immediately (must be synchronous on click to avoid Chrome popup blocking).
      // If popups are blocked, we will fall back to printing via a hidden iframe.
      const printWindow = window.open('', '_blank', 'noopener,noreferrer');
      if (printWindow) {
        printWindow.document.write(
          '<!doctype html><html><head><title>Preparing warranty certificate...</title></head><body style="font-family: Arial, sans-serif; padding: 16px;">Preparing warranty certificate…</body></html>',
        );
        printWindow.document.close();
      }

      const [company, warranty] = await Promise.all([
        apiClient.get<any>('/tenant/current').catch(() => null),
        apiClient.get<any>(`/sales/warranties/${warrantyId}`),
      ]);

      const escapeHtml = (value: unknown) =>
        String(value ?? '')
          .replace(/&/g, '&amp;')
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;')
          .replace(/"/g, '&quot;')
          .replace(/'/g, '&#39;');

      const formatDate = (d: any) => {
        if (!d) return '';
        try {
          return new Date(d).toLocaleDateString('en-IN');
        } catch {
          return String(d);
        }
      };

      const companyName = company?.name || 'Company';
      const companyAddress = company?.address || '';
      const companyPhone = company?.phone || '';
      const companyEmail = company?.email || '';
      const companyLogoUrl = company?.logo_url || '';

      const itemLabel =
        (warranty?.item_code || warranty?.item_name)
          ? `${warranty?.item_code ? `${warranty.item_code} - ` : ''}${warranty?.item_name || ''}`
          : (warranty?.item_description || 'Item');

      const html = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8" />
  <title>Warranty Certificate - ${escapeHtml(warranty?.warranty_number || '')}</title>
  <style>
    @page { margin: 0.5cm; }
    body { font-family: Arial, sans-serif; margin: 0; padding: 20px; color: #000; font-size: 11pt; }
    .letterhead {
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      border-bottom: 2px solid #1e3a8a;
      padding-bottom: 12px;
      margin-bottom: 16px;
    }
    .logo-section { display: flex; align-items: center; gap: 12px; }
    .logo-box {
      width: 52px; height: 52px; background: #1e3a8a; color: white;
      display: flex; align-items: center; justify-content: center;
      font-weight: 700; border-radius: 8px;
    }
    .company-name { font-size: 18px; font-weight: 700; margin: 0; }
    .company-meta { font-size: 10.5pt; margin: 2px 0 0 0; color: #111; }
    .title {
      text-align: center;
      font-size: 18px;
      font-weight: 800;
      margin: 18px 0 10px 0;
      letter-spacing: 0.4px;
    }
    .sub { text-align: center; font-size: 10.5pt; color: #333; margin-top: -6px; }
    .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 16px; }
    .box { border: 1px solid #cbd5e1; border-radius: 8px; padding: 12px; }
    .box h3 { margin: 0 0 8px 0; font-size: 12pt; }
    .row { display: flex; justify-content: space-between; gap: 12px; margin: 6px 0; }
    .label { color: #374151; font-size: 10.5pt; }
    .value { font-weight: 600; font-size: 10.5pt; text-align: right; }
    .terms { margin-top: 16px; border-top: 1px dashed #cbd5e1; padding-top: 12px; font-size: 10.5pt; color: #111; }
    .footer { margin-top: 18px; display: flex; justify-content: space-between; gap: 12px; }
    .sign { width: 48%; border-top: 1px solid #111; padding-top: 6px; font-size: 10.5pt; }
    .muted { color: #4b5563; }
    img.logo { width: 52px; height: 52px; object-fit: contain; border-radius: 8px; }
  </style>
</head>
<body>
  <div class="letterhead">
    <div class="logo-section">
      ${companyLogoUrl ? `<img class="logo" src="${escapeHtml(companyLogoUrl)}" alt="Logo" />` : `<div class="logo-box">${escapeHtml(companyName).slice(0, 2).toUpperCase()}</div>`}
      <div>
        <p class="company-name">${escapeHtml(companyName)}</p>
        ${companyAddress ? `<p class="company-meta">${escapeHtml(companyAddress)}</p>` : ''}
        <p class="company-meta">${[companyPhone ? `Phone: ${escapeHtml(companyPhone)}` : '', companyEmail ? `Email: ${escapeHtml(companyEmail)}` : ''].filter(Boolean).join(' • ')}</p>
      </div>
    </div>
    <div style="text-align:right">
      <div class="muted" style="font-size:10.5pt">Generated on</div>
      <div style="font-weight:700">${escapeHtml(new Date().toLocaleDateString('en-IN'))}</div>
    </div>
  </div>

  <div class="title">WARRANTY CERTIFICATE</div>
  <div class="sub">(1 certificate per dispatched UID)</div>

  <div class="grid">
    <div class="box">
      <h3>Warranty Details</h3>
      <div class="row"><div class="label">Warranty No.</div><div class="value">${escapeHtml(warranty?.warranty_number)}</div></div>
      <div class="row"><div class="label">UID</div><div class="value">${escapeHtml(warranty?.uid)}</div></div>
      <div class="row"><div class="label">Product</div><div class="value">${escapeHtml(itemLabel)}</div></div>
      ${warranty?.serial_number ? `<div class="row"><div class="label">Serial No.</div><div class="value">${escapeHtml(warranty.serial_number)}</div></div>` : ''}
      ${warranty?.batch_number ? `<div class="row"><div class="label">Batch</div><div class="value">${escapeHtml(warranty.batch_number)}</div></div>` : ''}
      <div class="row"><div class="label">Warranty Type</div><div class="value">${escapeHtml(warranty?.warranty_type || 'STANDARD')}</div></div>
      <div class="row"><div class="label">Start Date</div><div class="value">${escapeHtml(formatDate(warranty?.warranty_start_date))}</div></div>
      <div class="row"><div class="label">End Date</div><div class="value">${escapeHtml(formatDate(warranty?.warranty_end_date))}</div></div>
      <div class="row"><div class="label">Duration</div><div class="value">${escapeHtml(String(warranty?.warranty_duration_months || 12))} months</div></div>
    </div>
    <div class="box">
      <h3>Customer / Dispatch</h3>
      <div class="row"><div class="label">Customer</div><div class="value">${escapeHtml(warranty?.customer_name || '')}</div></div>
      ${warranty?.customer_code ? `<div class="row"><div class="label">Customer Code</div><div class="value">${escapeHtml(warranty.customer_code)}</div></div>` : ''}
      ${warranty?.so_number ? `<div class="row"><div class="label">Sales Order</div><div class="value">${escapeHtml(warranty.so_number)}</div></div>` : ''}
      ${warranty?.dn_number ? `<div class="row"><div class="label">Dispatch Note</div><div class="value">${escapeHtml(warranty.dn_number)}</div></div>` : ''}
      ${warranty?.dn_date ? `<div class="row"><div class="label">Dispatch Date</div><div class="value">${escapeHtml(formatDate(warranty.dn_date))}</div></div>` : ''}
      <div class="row"><div class="label">Status</div><div class="value">${escapeHtml(warranty?.status || 'ACTIVE')}</div></div>
    </div>
  </div>

  <div class="terms">
    <div style="font-weight:700; margin-bottom:6px">Standard Warranty Terms</div>
    <div>• This warranty is valid only for the UID/product mentioned above.</div>
    <div>• Warranty is applicable from the start date until the end date stated in this certificate.</div>
    <div>• Please retain this certificate for warranty claims and service support.</div>
  </div>

  <div class="footer">
    <div class="sign">Authorized Signatory</div>
    <div class="sign">Customer Signature</div>
  </div>

  <script>
    window.onload = function(){
      // Keep it immediate; browsers can treat delayed prints as non-user initiated.
      try { window.focus(); } catch(e) {}
      try { window.print(); } catch(e) {}
    };
  </script>
</body>
</html>
      `;

      // Preferred path: if a popup window was successfully opened, render into it.
      if (printWindow) {
        printWindow.document.open();
        printWindow.document.write(html);
        printWindow.document.close();
        return;
      }

      // Fallback: print via hidden iframe (no popup required).
      const frameId = `warranty-print-frame-${warrantyId}`;
      const existing = document.getElementById(frameId);
      if (existing) existing.remove();

      const iframe = document.createElement('iframe');
      iframe.id = frameId;
      iframe.style.position = 'fixed';
      iframe.style.right = '0';
      iframe.style.bottom = '0';
      iframe.style.width = '0';
      iframe.style.height = '0';
      iframe.style.border = '0';
      iframe.style.visibility = 'hidden';
      document.body.appendChild(iframe);

      const doc = iframe.contentWindow?.document;
      if (!doc) {
        iframe.remove();
        throw new Error('Unable to create print frame');
      }

      doc.open();
      doc.write(html);
      doc.close();

      const cleanup = () => {
        try {
          iframe.remove();
        } catch {
          // ignore
        }
      };

      try {
        iframe.contentWindow?.addEventListener('afterprint', cleanup, { once: true });
      } catch {
        // ignore
      }

      setTimeout(cleanup, 30_000);
    } catch (err: any) {
      console.error('Failed to print warranty certificate:', err);
      alert(err?.message || 'Failed to print warranty certificate');
    }
  };

  useEffect(() => {
    fetchItems(); // Fetch items on mount for all forms
    if (activeTab === 'customers') {
      fetchCustomers();
    } else if (activeTab === 'quotations') {
      fetchQuotations();
    } else if (activeTab === 'orders') {
      fetchOrders();
    } else if (activeTab === 'dispatch') {
      fetchDispatches();
    } else if (activeTab === 'warranties') {
      fetchWarranties();
    }
  }, [activeTab]);

  const fetchItems = async () => {
    try {
      const data = await apiClient.get<any[]>('/items');
      console.log('Fetched items:', data);
      setItems(data);
    } catch (err: any) {
      console.error('Failed to fetch items:', err);
    }
  };

  const fetchCustomers = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await apiClient.get<Customer[]>('/sales/customers');
      setCustomers(data);
    } catch (err: any) {
      setError(err.message || 'Failed to fetch customers');
    } finally {
      setLoading(false);
    }
  };

  const fetchQuotations = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await apiClient.get<Quotation[]>('/sales/quotations');
      setQuotations(data);
    } catch (err: any) {
      setError(err.message || 'Failed to fetch quotations');
    } finally {
      setLoading(false);
    }
  };

  const resetQuotationForm = () => {
    setQuotationForm(createDefaultQuotationForm());
    setEditingQuotationId(null);
  };

  const fetchOrders = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await apiClient.get<SalesOrder[]>('/sales/orders');
      setOrders(data);
    } catch (err: any) {
      setError(err.message || 'Failed to fetch sales orders');
    } finally {
      setLoading(false);
    }
  };

  const handleSendSalesOrderEmail = async (orderId: string) => {
    try {
      setSendingSOEmailId(orderId);
      const result = await apiClient.post(`/sales/orders/${orderId}/send-email`, {});
      alert(`Sales order email sent to: ${result?.to || 'customer email'}`);
    } catch (err: any) {
      console.error('Error sending sales order email:', err);
      alert(err?.message || 'Failed to send sales order email');
    } finally {
      setSendingSOEmailId(null);
    }
  };

  const handleEditSalesOrder = async (orderId: string) => {
    try {
      const data: any = await apiClient.get(`/sales/orders/${orderId}`);
      setEditingOrderId(orderId);
      setOrderEditForm({
        expected_delivery_date: data.expected_delivery_date?.split('T')[0] || '',
        payment_terms: data.payment_terms || '',
        delivery_terms: data.delivery_terms || '',
        notes: data.notes || '',
        status: data.status || 'CONFIRMED',
      });
      setShowOrderEditForm(true);
    } catch (err: any) {
      alert(err?.message || 'Failed to load sales order');
    }
  };

  const handleSaveSalesOrder = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingOrderId) return;
    setLoading(true);
    setError(null);
    try {
      await apiClient.put(`/sales/orders/${editingOrderId}`, orderEditForm);
      setShowOrderEditForm(false);
      setEditingOrderId(null);
      await fetchOrders();
    } catch (err: any) {
      setError(err?.message || 'Failed to update sales order');
      alert(err?.message || 'Failed to update sales order');
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteSalesOrder = async (order: SalesOrder) => {
    if (!confirm(`Delete sales order ${order.so_number}?`)) return;
    try {
      await apiClient.delete(`/sales/orders/${order.id}`);
      await fetchOrders();
    } catch (err: any) {
      alert(err?.message || 'Failed to delete sales order');
    }
  };

  const handleEditDispatch = (dispatch: DispatchNote) => {
    setEditingDispatchId(dispatch.id);
    setDispatchEditForm({
      dispatch_date: dispatch.dispatch_date?.split('T')[0] || '',
      transporter_name: dispatch.transporter_name || '',
      vehicle_number: dispatch.vehicle_number || '',
      lr_number: dispatch.lr_number || '',
      lr_date: (dispatch as any).lr_date?.split('T')[0] || '',
      delivery_address: (dispatch as any).delivery_address || '',
      notes: (dispatch as any).notes || '',
    });
    setShowDispatchEditForm(true);
  };

  const handleSaveDispatch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingDispatchId) return;
    setLoading(true);
    setError(null);
    try {
      await apiClient.put(`/sales/dispatch/${editingDispatchId}`, dispatchEditForm);
      setShowDispatchEditForm(false);
      setEditingDispatchId(null);
      await fetchDispatches();
    } catch (err: any) {
      setError(err?.message || 'Failed to update dispatch');
      alert(err?.message || 'Failed to update dispatch');
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteDispatch = async (dispatch: DispatchNote) => {
    if (!confirm(`Delete dispatch note ${dispatch.dn_number}? This will attempt to revert stock and UIDs.`)) return;
    try {
      await apiClient.delete(`/sales/dispatch/${dispatch.id}`);
      await fetchDispatches();
      await fetchOrders();
      await fetchWarranties();
    } catch (err: any) {
      alert(err?.message || 'Failed to delete dispatch');
    }
  };

  const handleEditWarranty = (warranty: Warranty) => {
    setEditingWarrantyId(warranty.id);
    setWarrantyEditForm({
      status: warranty.status || 'ACTIVE',
      warranty_type: warranty.warranty_type || 'STANDARD',
    });
    setShowWarrantyEditForm(true);
  };

  const handleSaveWarranty = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingWarrantyId) return;
    setLoading(true);
    setError(null);
    try {
      await apiClient.put(`/sales/warranties/${editingWarrantyId}`, warrantyEditForm);
      setShowWarrantyEditForm(false);
      setEditingWarrantyId(null);
      await fetchWarranties();
    } catch (err: any) {
      setError(err?.message || 'Failed to update warranty');
      alert(err?.message || 'Failed to update warranty');
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteWarranty = async (warranty: Warranty) => {
    if (!confirm(`Delete warranty ${warranty.warranty_number}?`)) return;
    try {
      await apiClient.delete(`/sales/warranties/${warranty.id}`);
      await fetchWarranties();
    } catch (err: any) {
      alert(err?.message || 'Failed to delete warranty');
    }
  };

  const fetchDispatches = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await apiClient.get<DispatchNote[]>('/sales/dispatch');
      setDispatches(data);
    } catch (err: any) {
      setError(err.message || 'Failed to fetch dispatch notes');
    } finally {
      setLoading(false);
    }
  };

  const fetchWarranties = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await apiClient.get<Warranty[]>('/sales/warranties');
      setWarranties(data);
    } catch (err: any) {
      setError(err.message || 'Failed to fetch warranties');
    } finally {
      setLoading(false);
    }
  };

  const actuallyCreateCustomer = async () => {
    setLoading(true);
    setError(null);
    try {
      if (editingCustomerId) {
        await apiClient.put(`/sales/customers/${editingCustomerId}`, customerForm);
        alert('Customer updated successfully!');
      } else {
        console.log('Creating customer with data:', customerForm);
        const response = await apiClient.post('/sales/customers', customerForm);
        console.log('Customer created successfully:', response);
        alert('Customer created successfully!');
      }
      setShowCustomerForm(false);
      resetCustomerForm();
      fetchCustomers();
    } catch (err: any) {
      console.error('Full error object:', err);
      console.error('Error response:', err.response?.data);
      setError(err.response?.data?.message || err.message || 'Failed to save customer');
    } finally {
      setLoading(false);
    }
  };

  const handleSaveCustomer = async (e: React.FormEvent) => {
    e.preventDefault();
    
    // For updates, skip duplicate check
    if (editingCustomerId) {
      await actuallyCreateCustomer();
      return;
    }

    // Check for duplicates before creating
    await customerDuplicateDetection.checkDuplicates(
      () => apiClient.post('/sales/customers/check-duplicates', customerForm),
      () => actuallyCreateCustomer(),
    );
  };

  const handleEditCustomer = (customer: Customer) => {
    setEditingCustomerId(customer.id);
    const formData = {
      customer_name: customer.customer_name || '',
      customer_type: customer.customer_type || 'REGULAR',
      contact_person: customer.contact_person || '',
      email: customer.email || '',
      phone: customer.phone || '',
      mobile: customer.mobile || '',
      gst_number: customer.gst_number || '',
      pan_number: customer.pan_number || '',
      billing_address: customer.billing_address || '',
      shipping_address: customer.shipping_address || '',
      city: customer.city || '',
      state: customer.state || '',
      country: customer.country || 'India',
      pincode: customer.pincode || '',
      credit_limit: Number(customer.credit_limit) || 0,
      credit_days: Number(customer.credit_days) || 30,
    };
    setCustomerForm(formData);
    setShowCustomerForm(true);
  };

  const handleDeleteCustomer = async (customer: Customer) => {
    if (!confirm(`Delete customer ${customer.customer_name}? This will deactivate the customer.`)) return;
    try {
      await apiClient.delete(`/sales/customers/${customer.id}`);
      await fetchCustomers();
    } catch (err: any) {
      alert(err?.message || 'Failed to delete customer');
    }
  };

  const actuallyCreateQuotation = async () => {
    setLoading(true);
    setError(null);
    try {
      if (editingQuotationId) {
        await apiClient.put(`/sales/quotations/${editingQuotationId}`, quotationForm);
        alert('Quotation updated successfully!');
      } else {
        await apiClient.post('/sales/quotations', quotationForm);
        alert('Quotation created successfully!');
      }
      setShowQuotationForm(false);
      resetQuotationForm();
      fetchQuotations();
    } catch (err: any) {
      setError(err.message || 'Failed to save quotation');
    } finally {
      setLoading(false);
    }
  };

  const handleSaveQuotation = async (e: React.FormEvent) => {
    e.preventDefault();
    
    // For updates, skip duplicate check
    if (editingQuotationId) {
      await actuallyCreateQuotation();
      return;
    }

    // Check for duplicates before creating
    await quotationDuplicateDetection.checkDuplicates(
      () => apiClient.post('/sales/quotations/check-duplicates', quotationForm),
      () => actuallyCreateQuotation(),
    );
  };

  const handleViewQuotation = async (quotationId: string) => {
    try {
      const data = await apiClient.get(`/sales/quotations/${quotationId}`);
      setViewingQuotation(data);
    } catch (err: any) {
      alert(err.message || 'Failed to load quotation');
    }
  };

  const handleEditQuotation = async (quotationId: string) => {
    try {
      const data: any = await apiClient.get(`/sales/quotations/${quotationId}`);
      setEditingQuotationId(quotationId);
      setQuotationForm({
        customer_id: data.customer_id || '',
        quotation_date: data.quotation_date?.split('T')[0] || '',
        valid_until: data.valid_until?.split('T')[0] || '',
        payment_terms: data.payment_terms || '',
        delivery_terms: data.delivery_terms || '',
        notes: data.notes || '',
        items: (data.quotation_items || []).map((item: any) => ({
          item_id: item.item_id || '',
          item_description: item.item_description || '',
          quantity: Number(item.quantity) || 1,
          unit_price: Number(item.unit_price) || 0,
          discount_percentage:
            item.discount_percentage !== undefined ? Number(item.discount_percentage) : 0,
          tax_percentage: item.tax_percentage !== undefined ? Number(item.tax_percentage) : 18,
        })),
      });
      setShowQuotationForm(true);
    } catch (err: any) {
      alert(err.message || 'Failed to load quotation for editing');
    }
  };

  const handleDeleteQuotation = async (quotation: Quotation) => {
    if (quotation.status !== 'DRAFT') return;
    if (!confirm(`Delete quotation ${quotation.quotation_number}?`)) return;
    try {
      await apiClient.delete(`/sales/quotations/${quotation.id}`);
      await fetchQuotations();
    } catch (err: any) {
      alert(err?.message || 'Failed to delete quotation');
    }
  };

  const handleOpenSOConversion = async (quotation: Quotation) => {
    try {
      // Fetch full quotation details with items
      const fullQuotation = await apiClient.get<any>(`/sales/quotations/${quotation.id}`);
      setSelectedQuotationForSO(fullQuotation);
      
      // Initialize conversion items with pending quantities
      const initialConversionItems: {[key: string]: number} = {};
      if (fullQuotation.quotation_items) {
        fullQuotation.quotation_items.forEach((item: QuotationItem) => {
          const pendingQty = item.pending_quantity || (item.quantity - (item.converted_quantity || 0));
          initialConversionItems[item.id!] = pendingQty;
        });
      }
      setConversionItems(initialConversionItems);
      
      setSOConversionForm({
        ...soConversionForm,
        payment_terms: fullQuotation.payment_terms || '',
      });
      setShowSOConversionForm(true);
    } catch (err: any) {
      alert('Failed to load quotation details: ' + err.message);
    }
  };

  const handleCreateDispatch = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      // Prepare dispatch payload with customer_id from selected order
      const dispatchPayload = {
        ...dispatchForm,
        customer_id: selectedOrderForDispatch?.customer_id,
      };

      console.log('Creating dispatch with payload:', dispatchPayload);
      await apiClient.post('/sales/dispatch', dispatchPayload);
      alert('Dispatch note created successfully!');
      setShowDispatchForm(false);
      setSelectedOrderForDispatch(null);
      setSalesOrderItems([]);
      setAvailableUIDs({});
      setDispatchForm({
        sales_order_id: '',
        dispatch_date: new Date().toISOString().split('T')[0],
        transporter_name: '',
        vehicle_number: '',
        lr_number: '',
        lr_date: new Date().toISOString().split('T')[0],
        delivery_address: '',
        notes: '',
        items: [],
      });
      fetchDispatches();
      fetchOrders();
      fetchWarranties();
    } catch (err: any) {
      console.error('Dispatch creation error:', err);
      const errorMessage = err.response?.data?.message || err.message || 'Failed to create dispatch';
      setError(errorMessage);
      alert('❌ Dispatch Creation Failed:\n\n' + errorMessage);
    } finally {
      setLoading(false);
    }
  };

  const addQuotationItem = () => {
    // Validate last row before adding new one
    if (quotationForm.items.length > 0) {
      const lastItem = quotationForm.items[quotationForm.items.length - 1];
      if (!lastItem.item_id || lastItem.quantity <= 0) {
        alert('Please complete the current row before adding a new one');
        return;
      }
    }

    setQuotationForm({
      ...quotationForm,
      items: [
        ...quotationForm.items,
        {
          item_id: '',
          item_description: '',
          quantity: 1,
          unit_price: 0,
          discount_percentage: 0,
          tax_percentage: 18,
        },
      ],
    });
  };

  const updateQuotationItem = (index: number, field: keyof QuotationItem, value: any) => {
    // Check for duplicate items when changing item_id
    if (field === 'item_id' && value) {
      const isDuplicate = quotationForm.items.some((item, i) => 
        i !== index && item.item_id === value
      );
      if (isDuplicate) {
        alert('This item is already added to the quotation. Please select a different item.');
        return;
      }
    }
    
    const newItems = [...quotationForm.items];
    newItems[index] = { ...newItems[index], [field]: value };
    setQuotationForm({ ...quotationForm, items: newItems });
  };

  const removeQuotationItem = (index: number) => {
    setQuotationForm({
      ...quotationForm,
      items: quotationForm.items.filter((_, i) => i !== index),
    });
  };

  const addDispatchItem = () => {
    // Validate last row before adding new one
    if (dispatchForm.items.length > 0) {
      const lastItem = dispatchForm.items[dispatchForm.items.length - 1];
      if (!lastItem.sales_order_item_id || lastItem.quantity <= 0) {
        alert('Please complete the current row before adding a new one');
        return;
      }
    }

    setDispatchForm({
      ...dispatchForm,
      items: [
        ...dispatchForm.items,
        {
          sales_order_item_id: '',
          item_id: '',
          uid: [],
          quantity: 1,
          batch_number: '',
        },
      ],
    });
  };

  const updateDispatchItem = (index: number, field: string, value: any) => {
    const newItems = [...dispatchForm.items];
    if (field === 'sales_order_item_id') {
      // Check for duplicate sales order items
      const isDuplicate = dispatchForm.items.some((item, i) => 
        i !== index && item.sales_order_item_id === value
      );
      if (isDuplicate) {
        alert('This sales order item is already added to the dispatch. Please select a different item.');
        return;
      }
      
      // Auto-fill item_id from selected SO item
      const soItem = salesOrderItems.find(item => item.id === value);
      if (soItem) {
        newItems[index] = { 
          ...newItems[index], 
          sales_order_item_id: value,
          item_id: soItem.item_id,
          // Quantity is based on selected *saleable* UIDs (auto-fills)
          quantity: 0,
          uid: [] // Reset UID when item changes
        };
        // Fetch available UIDs for this item
        fetchAvailableUIDs(soItem.item_id, index);
      } else {
        newItems[index] = { ...newItems[index], [field]: value };
      }
    } else if (field === 'uid') {
      // Handle UID array changes and auto-update quantity
      newItems[index] = { ...newItems[index], uid: value, quantity: value.length };
    } else {
      newItems[index] = { ...newItems[index], [field]: value };
    }
    setDispatchForm({ ...dispatchForm, items: newItems });
  };

  const removeDispatchItem = (index: number) => {
    setDispatchForm({
      ...dispatchForm,
      items: dispatchForm.items.filter((_, i) => i !== index),
    });
  };

  const fetchSalesOrderItems = async (orderId: string) => {
    try {
      console.log('Fetching SO items for order:', orderId);
      const data = await apiClient.get(`/sales/orders/${orderId}`);
      console.log('SO data received:', data);
      const itemsArray = data.sales_order_items || data.items || [];
      console.log('SO items extracted:', itemsArray);
      setSalesOrderItems(itemsArray);
      if (itemsArray.length === 0) {
        alert('⚠️ Warning: This sales order has no items. Please check the sales order.');
      }
    } catch (err: any) {
      console.error('Failed to fetch SO items:', err);
      const errorMsg = err.response?.data?.message || err.message || 'Unknown error';
      alert('❌ Failed to fetch sales order items:\n\n' + errorMsg);
      setSalesOrderItems([]);
    }
  };

  const fetchAvailableUIDs = async (itemId: string, rowIndex: number) => {
    if (!itemId) return;
    
    setLoadingUIDs({ ...loadingUIDs, [rowIndex]: true });
    try {
      // Fetch only saleable UIDs for dispatch: QC PASSED + IN_STOCK status
      const response = await apiClient.get(
        `/uid?item_id=${itemId}&status=IN_STOCK&quality_status=PASSED&limit=5000&sortBy=created_at&sortOrder=asc`
      );
      // Handle paginated response structure: { data: [...], pagination: {...} }
      const uids = response?.data || (Array.isArray(response) ? response : []);
      setAvailableUIDs({ ...availableUIDs, [itemId]: uids });
      
      if (uids.length === 0) {
        console.warn(`No UIDs available for item ${itemId}`);
        alert(`⚠️ No saleable UIDs found for this item. Ensure QC is PASSED and inventory is IN_STOCK.`);
      }
    } catch (err: any) {
      console.error('Failed to fetch UIDs:', err);
      const errorMsg = err.response?.data?.message || err.message || 'Unknown error';
      alert('❌ Failed to fetch available UIDs:\n\n' + errorMsg);
      setAvailableUIDs({ ...availableUIDs, [itemId]: [] });
    } finally {
      setLoadingUIDs({ ...loadingUIDs, [rowIndex]: false });
    }
  };

  const actuallyConvertToSO = async (payload: any) => {
    setLoading(true);
    setError(null);
    try {
      await apiClient.post(`/sales/quotations/${selectedQuotationForSO!.id}/convert-to-so`, payload);
      alert('Quotation converted to Sales Order successfully!');
      setShowSOConversionForm(false);
      setSelectedQuotationForSO(null);
      setSOConversionForm({
        expected_delivery_date: '',
        advance_amount: 0,
        payment_terms: '',
        special_instructions: '',
        project: '',
      });
      setConversionItems({});
      fetchQuotations();
      fetchOrders();
    } catch (err: any) {
      setError(err.message || 'Failed to convert quotation');
      alert('Failed to convert quotation: ' + err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleConvertToSO = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedQuotationForSO) return;
    
    // Build items array with selected quantities
    const items = Object.entries(conversionItems)
      .filter(([_, qty]) => qty > 0)
      .map(([quotation_item_id, quantity]) => ({
        quotation_item_id,
        quantity,
      }));
    
    if (items.length === 0) {
      alert('Please specify quantities to convert for at least one item.');
      return;
    }
    
    const payload = {
      ...soConversionForm,
      items,
      customer_id: selectedQuotationForSO.customer_id,
    };

    // Check for duplicates before converting
    await salesOrderDuplicateDetection.checkDuplicates(
      () => apiClient.post('/sales/orders/check-duplicates', payload),
      () => actuallyConvertToSO(payload),
    );
  };

  const actuallyCreateDirectSO = async () => {
    setLoading(true);
    setError(null);
    try {
      await apiClient.post('/sales/orders', directSOForm);
      alert('Direct Sales Order created successfully!');
      setShowDirectSOForm(false);
      setDirectSOForm({
        customer_id: '',
        order_date: new Date().toISOString().split('T')[0],
        expected_delivery_date: '',
        payment_terms: '',
        project: '',
        source_type: 'DIRECT',
        items: [],
      });
      fetchOrders();
    } catch (err: any) {
      setError(err.message || 'Failed to create direct sales order');
      alert('Failed to create direct sales order: ' + err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleCreateDirectSO = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!directSOForm.customer_id) {
      alert('Please select a customer');
      return;
    }
    if (directSOForm.items.length === 0) {
      alert('Please add at least one item');
      return;
    }
    
    // Check for duplicates before creating
    await salesOrderDuplicateDetection.checkDuplicates(
      () => apiClient.post('/sales/orders/check-duplicates', directSOForm),
      () => actuallyCreateDirectSO(),
    );
  };

  const handleCreateWarranty = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      await apiClient.post('/sales/warranties', warrantyForm);
      alert('Warranty registered successfully!');
      setShowWarrantyForm(false);
      setWarrantyForm({
        uid: '',
        warranty_duration_months: 12,
        warranty_type: 'STANDARD',
        notes: '',
      });
      fetchWarranties();
    } catch (err: any) {
      setError(err.message || 'Failed to register warranty');
      alert('Failed to register warranty: ' + err.message);
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status: string) => {
    const colors: Record<string, string> = {
      DRAFT: 'bg-gray-100 text-gray-800',
      PENDING_APPROVAL: 'bg-yellow-100 text-yellow-800',
      APPROVED: 'bg-green-100 text-green-800',
      REJECTED: 'bg-red-100 text-red-800',
      CONVERTED: 'bg-blue-100 text-blue-800',
      CONFIRMED: 'bg-green-100 text-green-800',
      IN_PRODUCTION: 'bg-purple-100 text-purple-800',
      READY_TO_DISPATCH: 'bg-orange-100 text-orange-800',
      DISPATCHED: 'bg-blue-100 text-blue-800',
      DELIVERED: 'bg-green-100 text-green-800',
      ACTIVE: 'bg-green-100 text-green-800',
      EXPIRED: 'bg-gray-100 text-gray-800',
      CLAIMED: 'bg-yellow-100 text-yellow-800',
      VOID: 'bg-red-100 text-red-800',
    };
    return colors[status] || 'bg-gray-100 text-gray-800';
  };

  const router = useRouter();

  // Smart Job Order (from Sales Order) state
  const [showSmartJOModal, setShowSmartJOModal] = useState(false);
  const [smartJOOrder, setSmartJOOrder] = useState<SalesOrder | null>(null);
  const [smartJOSOItems, setSmartJOSOItems] = useState<any[]>([]);
  const [smartJOSelectedSOItemId, setSmartJOSelectedSOItemId] = useState<string>('');
  const [smartJOLoading, setSmartJOLoading] = useState(false);

  const openSmartJOForSO = async (order: SalesOrder) => {
    setSmartJOLoading(true);
    try {
      const so = await apiClient.get<any>(`/sales/orders/${order.id}`);
      const soItems = (so?.sales_order_items || so?.items || []) as any[];

      const remaining = (Array.isArray(soItems) ? soItems : [])
        .map((soItem) => {
          const remainingQty = Number(soItem.quantity) - Number(soItem.dispatched_quantity || 0);
          return {
            ...soItem,
            remainingQty,
          };
        })
        .filter((soItem) => soItem.item_id && Number(soItem.remainingQty) > 0);

      if (remaining.length === 0) {
        alert('No remaining quantity found in this sales order.');
        return;
      }

      if (remaining.length === 1) {
        const soItem = remaining[0];
        router.push(
          `/dashboard/production/job-orders/smart?salesOrderId=${encodeURIComponent(order.id)}` +
            `&salesOrderItemId=${encodeURIComponent(soItem.id)}` +
            `&itemId=${encodeURIComponent(soItem.item_id)}` +
            `&quantity=${encodeURIComponent(String(soItem.remainingQty))}`,
        );
        return;
      }

      setSmartJOOrder(order);
      setSmartJOSOItems(remaining);
      setSmartJOSelectedSOItemId(String(remaining[0]?.id || ''));
      setShowSmartJOModal(true);
    } catch (err: any) {
      alert(`Failed to load sales order items: ${err?.message || 'Unknown error'}`);
    } finally {
      setSmartJOLoading(false);
    }
  };

  return (
    <div className="p-6">
      <div className="mb-6">
        <button
          onClick={() => router.push('/dashboard')}
          className="text-amber-600 hover:text-amber-800 text-sm mb-2"
        >
          ← Back to Dashboard
        </button>
        <h1 className="text-2xl font-bold text-gray-900">Sales & Dispatch Management</h1>
        <p className="text-sm text-gray-600 mt-1">
          Manage customers, quotations, sales orders, dispatch, and warranties
        </p>
      </div>

      {error && (
        <div className="mb-4 p-4 bg-red-50 border border-red-200 rounded-lg">
          <p className="text-sm text-red-800">{error}</p>
        </div>
      )}

      {/* Tabs */}
      <div className="border-b border-gray-200 mb-6">
        <nav className="-mb-px flex flex-wrap gap-x-8 gap-y-2">
          {[
            { id: 'customers', label: 'Customers' },
            { id: 'quotations', label: 'Quotations' },
            { id: 'orders', label: 'Sales Orders' },
            { id: 'dispatch', label: 'Dispatch' },
            { id: 'warranties', label: 'Warranties' },
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as TabType)}
              className={`py-2 px-1 border-b-2 font-medium text-sm ${
                activeTab === tab.id
                  ? 'border-amber-500 text-amber-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </nav>
      </div>

      {/* Customers Tab */}
      {activeTab === 'customers' && (
        <div>
          <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
            <h2 className="text-lg font-semibold">Customer List</h2>
            <button
              onClick={() => {
                resetCustomerForm();
                setShowCustomerForm(true);
              }}
              className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700"
            >
              + Add Customer
            </button>
          </div>

          {loading ? (
            <p className="text-gray-600">Loading customers...</p>
          ) : (
            <div className="bg-white rounded-lg shadow overflow-x-auto">
              <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Code</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Name</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Type</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Contact</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">City</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Credit Limit</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Actions</th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {customers.map((customer) => (
                    <tr key={customer.id}>
                      <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                        {customer.customer_code}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">{customer.customer_name}</td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">{customer.customer_type}</td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                        {customer.contact_person || '-'}
                        <br />
                        <span className="text-xs">{customer.mobile || customer.phone || '-'}</span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">{customer.city || '-'}</td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                        ₹{customer.credit_limit.toLocaleString()}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span
                          className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                            customer.is_active ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
                          }`}
                        >
                          {customer.is_active ? 'Active' : 'Inactive'}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm">
                        <div className="flex flex-wrap items-center gap-2">
                          <button
                            type="button"
                            onClick={() => handleEditCustomer(customer)}
                            className="text-amber-600 hover:text-amber-800"
                          >
                            Edit
                          </button>
                          <button
                            type="button"
                            onClick={() => handleDeleteCustomer(customer)}
                            className="text-red-600 hover:text-red-800"
                          >
                            Delete
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Customer Form Modal */}
          {showCustomerForm && (
            <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
              <div className="bg-white rounded-lg p-6 max-w-2xl w-full max-h-[90vh] overflow-y-auto">
                <h3 className="text-lg font-semibold mb-4">{editingCustomerId ? 'Edit Customer' : 'Add New Customer'}</h3>
                <form onSubmit={handleSaveCustomer}>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Customer Name *</label>
                      <input
                        type="text"
                        required
                        value={customerForm.customer_name}
                        onChange={(e) => setCustomerForm({ ...customerForm, customer_name: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Customer Type</label>
                      <select
                        value={customerForm.customer_type}
                        onChange={(e) => setCustomerForm({ ...customerForm, customer_type: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      >
                        <option value="REGULAR">Regular</option>
                        <option value="DISTRIBUTOR">Distributor</option>
                        <option value="DEALER">Dealer</option>
                        <option value="CORPORATE">Corporate</option>
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Contact Person</label>
                      <input
                        type="text"
                        value={customerForm.contact_person}
                        onChange={(e) => setCustomerForm({ ...customerForm, contact_person: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
                      <input
                        type="email"
                        value={customerForm.email}
                        onChange={(e) => setCustomerForm({ ...customerForm, email: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Phone</label>
                      <input
                        type="text"
                        value={customerForm.phone}
                        onChange={(e) => setCustomerForm({ ...customerForm, phone: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Mobile</label>
                      <input
                        type="text"
                        value={customerForm.mobile}
                        onChange={(e) => setCustomerForm({ ...customerForm, mobile: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">GST Number</label>
                      <input
                        type="text"
                        value={customerForm.gst_number}
                        onChange={(e) => setCustomerForm({ ...customerForm, gst_number: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">PAN Number</label>
                      <input
                        type="text"
                        value={customerForm.pan_number}
                        onChange={(e) => setCustomerForm({ ...customerForm, pan_number: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div className="col-span-2">
                      <label className="block text-sm font-medium text-gray-700 mb-1">Billing Address</label>
                      <textarea
                        value={customerForm.billing_address}
                        onChange={(e) => setCustomerForm({ ...customerForm, billing_address: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                        rows={2}
                      />
                    </div>
                    <div className="col-span-2">
                      <label className="block text-sm font-medium text-gray-700 mb-1">Shipping Address</label>
                      <textarea
                        value={customerForm.shipping_address}
                        onChange={(e) => setCustomerForm({ ...customerForm, shipping_address: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                        rows={2}
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">City</label>
                      <input
                        type="text"
                        value={customerForm.city}
                        onChange={(e) => setCustomerForm({ ...customerForm, city: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">State</label>
                      <input
                        type="text"
                        value={customerForm.state}
                        onChange={(e) => setCustomerForm({ ...customerForm, state: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Country</label>
                      <input
                        type="text"
                        value={customerForm.country}
                        onChange={(e) => setCustomerForm({ ...customerForm, country: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Pin Code</label>
                      <input
                        type="text"
                        value={customerForm.pincode || ''}
                        onChange={(e) => setCustomerForm({ ...customerForm, pincode: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                        maxLength={6}
                        placeholder="Enter 6-digit pin code"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Credit Limit</label>
                      <input
                        type="number"
                        value={customerForm.credit_limit}
                        onChange={(e) => setCustomerForm({ ...customerForm, credit_limit: parseFloat(e.target.value) })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Credit Days</label>
                      <input
                        type="number"
                        value={customerForm.credit_days}
                        onChange={(e) => setCustomerForm({ ...customerForm, credit_days: parseInt(e.target.value) })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                  </div>
                  <div className="mt-6 flex justify-end space-x-3">
                    <button
                      type="button"
                      onClick={() => {
                        setShowCustomerForm(false);
                        resetCustomerForm();
                      }}
                      className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50"
                    >
                      Cancel
                    </button>
                    <button
                      type="submit"
                      disabled={loading}
                      className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50"
                    >
                      {loading
                        ? editingCustomerId
                          ? 'Saving...'
                          : 'Creating...'
                        : editingCustomerId
                          ? 'Save Changes'
                          : 'Create Customer'}
                    </button>
                  </div>
                </form>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Quotations Tab */}
      {activeTab === 'quotations' && (
        <div>
          <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
            <h2 className="text-lg font-semibold">Quotations</h2>
            <button
              onClick={() => {
                resetQuotationForm();
                setShowQuotationForm(true);
              }}
              className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700"
            >
              + Create Quotation
            </button>
          </div>

          {loading ? (
            <p className="text-gray-600">Loading quotations...</p>
          ) : (
            <div className="bg-white rounded-lg shadow overflow-x-auto">
              <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">QT Number</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Customer</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Date</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Valid Until</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Amount</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Actions</th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {quotations.map((quotation) => (
                    <tr key={quotation.id}>
                      <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                        {quotation.quotation_number}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {quotation.customer_name || '-'}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                        {new Date(quotation.quotation_date).toLocaleDateString()}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                        {new Date(quotation.valid_until).toLocaleDateString()}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        ₹{quotation.net_amount.toLocaleString()}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className={`px-2 py-1 text-xs font-semibold rounded-full ${getStatusColor(quotation.status)}`}>
                          {quotation.status}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm">
                        <div className="flex flex-wrap items-center gap-2">
                          <button
                            onClick={() => handleViewQuotation(quotation.id)}
                            className="text-blue-600 hover:text-blue-900"
                          >
                            View
                          </button>
                          <button
                            type="button"
                            onClick={() => handleEditQuotation(quotation.id)}
                            disabled={quotation.status !== 'DRAFT'}
                            title={quotation.status !== 'DRAFT' ? 'Only DRAFT quotations can be edited' : 'Edit quotation'}
                            className={
                              quotation.status === 'DRAFT'
                                ? 'text-amber-600 hover:text-amber-900'
                                : 'text-gray-400 cursor-not-allowed'
                            }
                          >
                            Edit
                          </button>
                          <button
                            type="button"
                            onClick={() => handleDeleteQuotation(quotation)}
                            disabled={quotation.status !== 'DRAFT'}
                            title={quotation.status !== 'DRAFT' ? 'Only DRAFT quotations can be deleted' : 'Delete quotation'}
                            className={
                              quotation.status === 'DRAFT'
                                ? 'text-red-600 hover:text-red-900'
                                : 'text-gray-400 cursor-not-allowed'
                            }
                          >
                            Delete
                          </button>
                          {quotation.status === 'DRAFT' && (
                            <button
                              onClick={async () => {
                                try {
                                  await apiClient.put(`/sales/quotations/${quotation.id}/approve`);
                                  alert('Quotation approved!');
                                  fetchQuotations();
                                } catch (err: any) {
                                  alert('Failed to approve: ' + err.message);
                                }
                              }}
                              className="text-green-600 hover:text-green-900"
                            >
                              Approve
                            </button>
                          )}
                          {quotation.status === 'APPROVED' && (
                            <button
                              onClick={() => handleOpenSOConversion(quotation)}
                              className="text-amber-600 hover:text-amber-900"
                            >
                              Convert to SO
                            </button>
                          )}
                          {quotation.status === 'PARTIALLY_CONVERTED' && (
                            <button
                              onClick={() => handleOpenSOConversion(quotation)}
                              className="text-blue-600 hover:text-blue-900"
                            >
                              Convert Remaining
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* SO Conversion Form Modal */}
          {showSOConversionForm && selectedQuotationForSO && (
            <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50 overflow-y-auto">
              <div className="bg-white rounded-lg p-6 max-w-4xl w-full my-8 max-h-[90vh] overflow-y-auto">
                <h3 className="text-lg font-semibold mb-4">
                  Convert Quotation {selectedQuotationForSO.quotation_number} to Sales Order
                </h3>
                <form onSubmit={handleConvertToSO}>
                  <div className="space-y-6">
                    {/* Customer Info */}
                    <div className="bg-gray-50 p-4 rounded-lg">
                      <div className="grid grid-cols-2 gap-4">
                        <div>
                          <label className="block text-xs font-medium text-gray-500 mb-1">Customer</label>
                          <p className="text-sm text-gray-900 font-medium">{selectedQuotationForSO.customer_name}</p>
                        </div>
                        <div>
                          <label className="block text-xs font-medium text-gray-500 mb-1">Quotation Total</label>
                          <p className="text-sm text-gray-900 font-medium">₹{selectedQuotationForSO.net_amount.toLocaleString()}</p>
                        </div>
                      </div>
                    </div>

                    {/* Items to Convert */}
                    <div>
                      <h4 className="text-sm font-semibold text-gray-700 mb-3">Select Items & Quantities to Convert</h4>
                      <div className="border rounded-lg overflow-x-auto">
                        <table className="min-w-full divide-y divide-gray-200">
                          <thead className="bg-gray-50">
                            <tr>
                              <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Item</th>
                              <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase">Total Qty</th>
                              <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase">Converted</th>
                              <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase">Pending</th>
                              <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase">Convert Now</th>
                              <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">Unit Price</th>
                            </tr>
                          </thead>
                          <tbody className="bg-white divide-y divide-gray-200">
                            {selectedQuotationForSO.quotation_items?.map((item) => {
                              const convertedQty = item.converted_quantity || 0;
                              const pendingQty = item.pending_quantity || (item.quantity - convertedQty);
                              const currentConvertQty = conversionItems[item.id!] || 0;
                              
                              return (
                                <tr key={item.id} className={pendingQty === 0 ? 'bg-gray-50 opacity-60' : ''}>
                                  <td className="px-4 py-3">
                                    <div className="text-sm font-medium text-gray-900">{item.item_description}</div>
                                    {convertedQty > 0 && (
                                      <div className="mt-1 w-full bg-gray-200 rounded-full h-2">
                                        <div 
                                          className="bg-green-500 h-2 rounded-full" 
                                          style={{ width: `${(convertedQty / item.quantity) * 100}%` }}
                                        ></div>
                                      </div>
                                    )}
                                  </td>
                                  <td className="px-4 py-3 text-center text-sm text-gray-900">{item.quantity}</td>
                                  <td className="px-4 py-3 text-center">
                                    <span className="text-sm text-green-600 font-medium">{convertedQty}</span>
                                  </td>
                                  <td className="px-4 py-3 text-center">
                                    <span className="text-sm text-amber-600 font-medium">{pendingQty}</span>
                                  </td>
                                  <td className="px-4 py-3">
                                    <input
                                      type="number"
                                      min="0"
                                      max={pendingQty}
                                      step="0.01"
                                      value={currentConvertQty}
                                      onChange={(e) => {
                                        const value = parseFloat(e.target.value) || 0;
                                        setConversionItems({
                                          ...conversionItems,
                                          [item.id!]: Math.min(value, pendingQty),
                                        });
                                      }}
                                      disabled={pendingQty === 0}
                                      className="w-24 px-2 py-1 text-center border border-gray-300 rounded text-sm focus:ring-2 focus:ring-amber-500 disabled:bg-gray-100"
                                    />
                                  </td>
                                  <td className="px-4 py-3 text-right text-sm text-gray-900">₹{item.unit_price.toLocaleString()}</td>
                                </tr>
                              );
                            })}
                          </tbody>
                        </table>
                      </div>
                      
                      {/* Quick Actions */}
                      <div className="mt-3 flex space-x-2">
                        <button
                          type="button"
                          onClick={() => {
                            const allItems: {[key: string]: number} = {};
                            selectedQuotationForSO.quotation_items?.forEach((item) => {
                              const pendingQty = item.pending_quantity || (item.quantity - (item.converted_quantity || 0));
                              allItems[item.id!] = pendingQty;
                            });
                            setConversionItems(allItems);
                          }}
                          className="px-3 py-1 text-xs bg-blue-50 text-blue-600 rounded hover:bg-blue-100"
                        >
                          Convert All Remaining
                        </button>
                        <button
                          type="button"
                          onClick={() => {
                            const halfItems: {[key: string]: number} = {};
                            selectedQuotationForSO.quotation_items?.forEach((item) => {
                              const pendingQty = item.pending_quantity || (item.quantity - (item.converted_quantity || 0));
                              halfItems[item.id!] = Math.floor(pendingQty / 2);
                            });
                            setConversionItems(halfItems);
                          }}
                          className="px-3 py-1 text-xs bg-amber-50 text-amber-600 rounded hover:bg-amber-100"
                        >
                          Convert Half
                        </button>
                        <button
                          type="button"
                          onClick={() => setConversionItems({})}
                          className="px-3 py-1 text-xs bg-gray-50 text-gray-600 rounded hover:bg-gray-100"
                        >
                          Clear All
                        </button>
                      </div>
                    </div>

                    {/* Order Details */}
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Expected Delivery Date *</label>
                        <input
                          type="date"
                          required
                          value={soConversionForm.expected_delivery_date}
                          onChange={(e) => setSOConversionForm({ ...soConversionForm, expected_delivery_date: e.target.value })}
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                        />
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Advance Amount (₹)</label>
                        <input
                          type="number"
                          min="0"
                          value={soConversionForm.advance_amount}
                          onChange={(e) => setSOConversionForm({ ...soConversionForm, advance_amount: parseFloat(e.target.value) || 0 })}
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                        />
                      </div>
                    </div>
                    
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Payment Terms</label>
                        <input
                          type="text"
                          value={soConversionForm.payment_terms}
                          onChange={(e) => setSOConversionForm({ ...soConversionForm, payment_terms: e.target.value })}
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                        />
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Project</label>
                        <input
                          type="text"
                          value={soConversionForm.project}
                          onChange={(e) => setSOConversionForm({ ...soConversionForm, project: e.target.value })}
                          placeholder="e.g., Project Alpha, Phase 1"
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                        />
                      </div>
                    </div>
                    
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Special Instructions</label>
                      <textarea
                        rows={2}
                        value={soConversionForm.special_instructions}
                        onChange={(e) => setSOConversionForm({ ...soConversionForm, special_instructions: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                      />
                    </div>
                  </div>

                  <div className="mt-6 flex justify-end space-x-3">
                    <button
                      type="button"
                      onClick={() => {
                        setShowSOConversionForm(false);
                        setSelectedQuotationForSO(null);
                        setConversionItems({});
                      }}
                      className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50"
                    >
                      Cancel
                    </button>
                    <button
                      type="submit"
                      disabled={loading}
                      className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50"
                    >
                      {loading ? 'Converting...' : 'Create Sales Order'}
                    </button>
                  </div>
                </form>
              </div>
            </div>
          )}

          {/* Direct Sales Order Form Modal */}
          {showDirectSOForm && (
            <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
              <div className="bg-white rounded-lg p-6 max-w-5xl w-full max-h-[90vh] overflow-y-auto">
                <div className="flex justify-between items-center mb-4">
                  <h3 className="text-xl font-semibold">Create Direct Sales Order</h3>
                  <button
                    onClick={() => setShowDirectSOForm(false)}
                    className="text-gray-500 hover:text-gray-700"
                  >
                    ✕
                  </button>
                </div>
                <form onSubmit={handleCreateDirectSO} className="space-y-4">
                  {/* Customer and Basic Details */}
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Customer *</label>
                      <SearchableSelect
                        options={customers.map(c => ({ label: `${c.customer_code} - ${c.customer_name}`, value: c.id }))}
                        value={directSOForm.customer_id}
                        onChange={(value) => setDirectSOForm({ ...directSOForm, customer_id: value })}
                        placeholder="Select customer..."
                        required
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Source Type *</label>
                      <select
                        value={directSOForm.source_type}
                        onChange={(e) => setDirectSOForm({ ...directSOForm, source_type: e.target.value as 'DIRECT' | 'INTERNAL' })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                        required
                      >
                        <option value="DIRECT">Direct Customer Order</option>
                        <option value="INTERNAL">Internal Stock</option>
                      </select>
                    </div>
                  </div>

                  <div className="grid grid-cols-3 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Order Date *</label>
                      <input
                        type="date"
                        value={directSOForm.order_date}
                        onChange={(e) => setDirectSOForm({ ...directSOForm, order_date: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                        required
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Expected Delivery Date</label>
                      <input
                        type="date"
                        value={directSOForm.expected_delivery_date}
                        onChange={(e) => setDirectSOForm({ ...directSOForm, expected_delivery_date: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Project</label>
                      <input
                        type="text"
                        value={directSOForm.project}
                        onChange={(e) => setDirectSOForm({ ...directSOForm, project: e.target.value })}
                        placeholder="e.g., Project Alpha, Phase 1"
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Payment Terms</label>
                    <input
                      type="text"
                      value={directSOForm.payment_terms}
                      onChange={(e) => setDirectSOForm({ ...directSOForm, payment_terms: e.target.value })}
                      placeholder="e.g., 30 days, Net 45, etc."
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                    />
                  </div>

                  {/* Items Section */}
                  <div className="border rounded-lg p-4">
                    <div className="flex justify-between items-center mb-3">
                      <h4 className="text-sm font-semibold">Order Items *</h4>
                      <button
                        type="button"
                        onClick={() => {
                          setDirectSOForm({
                            ...directSOForm,
                            items: [...directSOForm.items, {
                              item_id: '',
                              item_description: '',
                              quantity: 1,
                              unit_price: 0,
                              discount_percentage: 0,
                              tax_percentage: 18,
                            }]
                          });
                        }}
                        className="px-3 py-1 bg-blue-600 text-white text-sm rounded hover:bg-blue-700"
                      >
                        + Add Item
                      </button>
                    </div>
                    
                    {directSOForm.items.length === 0 ? (
                      <p className="text-gray-500 text-sm">No items added. Click &ldquo;+ Add Item&rdquo; to start.</p>
                    ) : (
                      <div className="space-y-3">
                        {directSOForm.items.map((item, index) => (
                          <div key={index} className="grid grid-cols-12 gap-2 items-start border-b pb-3">
                            <div className="col-span-4">
                              <label className="block text-xs text-gray-600 mb-1">Item Description *</label>
                              <input
                                type="text"
                                value={item.item_description}
                                onChange={(e) => {
                                  const newItems = [...directSOForm.items];
                                  newItems[index].item_description = e.target.value;
                                  setDirectSOForm({ ...directSOForm, items: newItems });
                                }}
                                className="w-full px-2 py-1 border border-gray-300 rounded text-sm"
                                placeholder="Item description"
                                required
                              />
                            </div>
                            <div className="col-span-2">
                              <label className="block text-xs text-gray-600 mb-1">Quantity *</label>
                              <input
                                type="number"
                                min="1"
                                value={item.quantity}
                                onChange={(e) => {
                                  const newItems = [...directSOForm.items];
                                  newItems[index].quantity = parseFloat(e.target.value) || 1;
                                  setDirectSOForm({ ...directSOForm, items: newItems });
                                }}
                                className="w-full px-2 py-1 border border-gray-300 rounded text-sm"
                                required
                              />
                            </div>
                            <div className="col-span-2">
                              <label className="block text-xs text-gray-600 mb-1">Unit Price (₹) *</label>
                              <input
                                type="number"
                                min="0"
                                step="0.01"
                                value={item.unit_price}
                                onChange={(e) => {
                                  const newItems = [...directSOForm.items];
                                  newItems[index].unit_price = parseFloat(e.target.value) || 0;
                                  setDirectSOForm({ ...directSOForm, items: newItems });
                                }}
                                className="w-full px-2 py-1 border border-gray-300 rounded text-sm"
                                required
                              />
                            </div>
                            <div className="col-span-1">
                              <label className="block text-xs text-gray-600 mb-1">Disc %</label>
                              <input
                                type="number"
                                min="0"
                                max="100"
                                step="0.1"
                                value={item.discount_percentage}
                                onChange={(e) => {
                                  const newItems = [...directSOForm.items];
                                  newItems[index].discount_percentage = parseFloat(e.target.value) || 0;
                                  setDirectSOForm({ ...directSOForm, items: newItems });
                                }}
                                className="w-full px-2 py-1 border border-gray-300 rounded text-sm"
                              />
                            </div>
                            <div className="col-span-1">
                              <label className="block text-xs text-gray-600 mb-1">Tax %</label>
                              <input
                                type="number"
                                min="0"
                                max="100"
                                step="0.1"
                                value={item.tax_percentage}
                                onChange={(e) => {
                                  const newItems = [...directSOForm.items];
                                  newItems[index].tax_percentage = parseFloat(e.target.value) || 0;
                                  setDirectSOForm({ ...directSOForm, items: newItems });
                                }}
                                className="w-full px-2 py-1 border border-gray-300 rounded text-sm"
                              />
                            </div>
                            <div className="col-span-2 flex items-end justify-end">
                              <button
                                type="button"
                                onClick={() => {
                                  const newItems = directSOForm.items.filter((_, i) => i !== index);
                                  setDirectSOForm({ ...directSOForm, items: newItems });
                                }}
                                className="px-2 py-1 bg-red-50 text-red-600 text-xs rounded hover:bg-red-100"
                              >
                                Remove
                              </button>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>

                  <div className="mt-6 flex justify-end space-x-3">
                    <button
                      type="button"
                      onClick={() => {
                        setShowDirectSOForm(false);
                        setDirectSOForm({
                          customer_id: '',
                          order_date: new Date().toISOString().split('T')[0],
                          expected_delivery_date: '',
                          payment_terms: '',
                          project: '',
                          source_type: 'DIRECT',
                          items: [],
                        });
                      }}
                      className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50"
                    >
                      Cancel
                    </button>
                    <button
                      type="submit"
                      disabled={loading}
                      className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50"
                    >
                      {loading ? 'Creating...' : 'Create Sales Order'}
                    </button>
                  </div>
                </form>
              </div>
            </div>
          )}

          {viewingQuotation && (
            <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
              <div className="bg-white rounded-lg p-6 max-w-4xl w-full max-h-[90vh] overflow-y-auto">
                <div className="flex justify-between items-start mb-4">
                  <div>
                    <h3 className="text-lg font-semibold">Quotation {viewingQuotation.quotation_number}</h3>
                    <p className="text-sm text-gray-500">Status: {viewingQuotation.status}</p>
                  </div>
                  <button
                    onClick={() => setViewingQuotation(null)}
                    className="text-gray-500 hover:text-gray-700 text-2xl leading-none"
                    aria-label="Close quotation details"
                  >
                    ×
                  </button>
                </div>

                <div className="grid grid-cols-2 gap-4 border rounded-lg p-4 bg-gray-50 mb-6">
                  <div>
                    <p className="text-xs uppercase text-gray-500">Customer</p>
                    <p className="text-sm text-gray-900">{viewingQuotation.customer_name || '—'}</p>
                  </div>
                  <div>
                    <p className="text-xs uppercase text-gray-500">Quotation Date</p>
                    <p className="text-sm text-gray-900">
                      {new Date(viewingQuotation.quotation_date).toLocaleDateString()}
                    </p>
                  </div>
                  <div>
                    <p className="text-xs uppercase text-gray-500">Valid Until</p>
                    <p className="text-sm text-gray-900">
                      {new Date(viewingQuotation.valid_until).toLocaleDateString()}
                    </p>
                  </div>
                  <div>
                    <p className="text-xs uppercase text-gray-500">Net Amount</p>
                    <p className="text-sm text-gray-900">₹{viewingQuotation.net_amount?.toLocaleString()}</p>
                  </div>
                </div>

                <div>
                  <h4 className="text-sm font-semibold text-gray-700 mb-2">Items</h4>
                  <div className="border rounded-lg overflow-x-auto">
                    <table className="min-w-full divide-y divide-gray-200">
                      <thead className="bg-gray-100">
                        <tr>
                          <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Item</th>
                          <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Qty</th>
                          <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Unit Price</th>
                          <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Discount %</th>
                          <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">Line Total</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-gray-200 bg-white">
                        {(viewingQuotation.quotation_items || []).map((item: any) => (
                          <tr key={item.id}>
                            <td className="px-4 py-2 text-sm text-gray-900">{item.item_description || '—'}</td>
                            <td className="px-4 py-2 text-sm text-gray-600">{item.quantity}</td>
                            <td className="px-4 py-2 text-sm text-gray-600">₹{Number(item.unit_price).toLocaleString()}</td>
                            <td className="px-4 py-2 text-sm text-gray-600">{item.discount_percentage ?? 0}%</td>
                            <td className="px-4 py-2 text-sm text-gray-900">₹{Number(item.line_total).toLocaleString()}</td>
                          </tr>
                        ))}
                        {(viewingQuotation.quotation_items || []).length === 0 && (
                          <tr>
                            <td colSpan={5} className="px-4 py-6 text-center text-sm text-gray-500">
                              No items available for this quotation.
                            </td>
                          </tr>
                        )}
                      </tbody>
                    </table>
                  </div>
                </div>

                <div className="mt-6 text-right">
                  <button
                    onClick={() => setViewingQuotation(null)}
                    className="px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700"
                  >
                    Close
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* Quotation Form Modal */}
          {showQuotationForm && (
            <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
              <div className="bg-white rounded-lg p-6 max-w-4xl w-full max-h-[90vh] overflow-y-auto">
                <h3 className="text-lg font-semibold mb-4">
                  {editingQuotationId ? 'Edit Quotation' : 'Create Quotation'}
                </h3>
                <form onSubmit={handleSaveQuotation}>
                  <div className="grid grid-cols-2 gap-4 mb-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Customer *</label>
                      <select
                        required
                        value={quotationForm.customer_id}
                        onChange={(e) => setQuotationForm({ ...quotationForm, customer_id: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      >
                        <option value="">Select Customer</option>
                        {customers.map((c) => (
                          <option key={c.id} value={c.id}>
                            {c.customer_name} ({c.customer_code})
                          </option>
                        ))}
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Quotation Date *</label>
                      <input
                        type="date"
                        required
                        value={quotationForm.quotation_date}
                        onChange={(e) => setQuotationForm({ ...quotationForm, quotation_date: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Valid Until *</label>
                      <input
                        type="date"
                        required
                        value={quotationForm.valid_until}
                        onChange={(e) => setQuotationForm({ ...quotationForm, valid_until: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Payment Terms</label>
                      <input
                        type="text"
                        value={quotationForm.payment_terms}
                        onChange={(e) => setQuotationForm({ ...quotationForm, payment_terms: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                  </div>

                  <div className="mb-4">
                    <div className="flex justify-between items-center mb-3">
                      <label className="block text-sm font-medium text-gray-700">Quotation Items *</label>
                      <button
                        type="button"
                        onClick={addQuotationItem}
                        className="px-3 py-1.5 text-sm text-white bg-amber-600 hover:bg-amber-700 rounded-md transition-colors"
                      >
                        + Add Item
                      </button>
                    </div>

                    {/* Column Headers */}
                    <div className="grid grid-cols-12 gap-2 mb-2 px-3 py-2 bg-gray-50 rounded-lg border border-gray-200">
                      <div className="col-span-3 text-xs font-semibold text-gray-700 uppercase">Item</div>
                      <div className="col-span-3 text-xs font-semibold text-gray-700 uppercase">Description</div>
                      <div className="col-span-2 text-xs font-semibold text-gray-700 uppercase">Quantity</div>
                      <div className="col-span-2 text-xs font-semibold text-gray-700 uppercase">Unit Price (₹)</div>
                      <div className="col-span-1 text-xs font-semibold text-gray-700 uppercase">Disc %</div>
                      <div className="col-span-1 text-xs font-semibold text-gray-700 uppercase text-center">Action</div>
                    </div>

                    {quotationForm.items.length === 0 ? (
                      <div className="text-center py-8 text-gray-500 border-2 border-dashed border-gray-300 rounded-lg">
                        <p className="text-sm">No items added yet. Click &quot;+ Add Item&quot; to start.</p>
                      </div>
                    ) : (
                      quotationForm.items.map((item, index) => (
                        <div key={index} className="grid grid-cols-12 gap-2 mb-3 p-3 border border-gray-200 rounded-lg hover:border-amber-300 transition-colors bg-white shadow-sm">
                          <div className="col-span-3">
                            <SearchableSelect
                              options={items.map(i => ({
                                value: i.id,
                                label: i.code,
                                subtitle: i.name,
                              }))}
                              value={item.item_id}
                              onChange={(value, option) => {
                                const selectedItem = items.find(i => i.id === value);
                                if (selectedItem) {
                                  const newItems = [...quotationForm.items];
                                  newItems[index] = {
                                    ...newItems[index],
                                    item_id: value,
                                    item_description: selectedItem.name || selectedItem.description || '',
                                    unit_price: selectedItem.selling_price || selectedItem.standard_cost || 0,
                                  };
                                  setQuotationForm({ ...quotationForm, items: newItems });
                                } else {
                                  updateQuotationItem(index, 'item_id', value);
                                }
                              }}
                              placeholder="Search item..."
                              required
                            />
                          </div>
                          <div className="col-span-3">
                            <input
                              type="text"
                              placeholder="Item description"
                              required
                              value={item.item_description}
                              onChange={(e) => updateQuotationItem(index, 'item_description', e.target.value)}
                              className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm focus:ring-2 focus:ring-amber-500 focus:border-amber-500"
                            />
                          </div>
                          <div className="col-span-2">
                            <input
                              type="number"
                              placeholder="0"
                              required
                              min="0.01"
                              step="0.01"
                              value={item.quantity}
                              onChange={(e) => updateQuotationItem(index, 'quantity', parseFloat(e.target.value))}
                              className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm focus:ring-2 focus:ring-amber-500 focus:border-amber-500"
                            />
                          </div>
                          <div className="col-span-2">
                            <input
                              type="number"
                              placeholder="0.00"
                              required
                              min="0"
                              step="0.01"
                              value={item.unit_price}
                              onChange={(e) => updateQuotationItem(index, 'unit_price', parseFloat(e.target.value))}
                              className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm focus:ring-2 focus:ring-amber-500 focus:border-amber-500"
                            />
                          </div>
                          <div className="col-span-1">
                            <input
                              type="number"
                              placeholder="0"
                              min="0"
                              max="100"
                              step="0.1"
                              value={item.discount_percentage}
                              onChange={(e) => updateQuotationItem(index, 'discount_percentage', parseFloat(e.target.value))}
                              className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm focus:ring-2 focus:ring-amber-500 focus:border-amber-500"
                            />
                          </div>
                          <div className="col-span-1 flex items-center justify-center">
                            <button
                              type="button"
                              onClick={() => removeQuotationItem(index)}
                              className="px-2 py-2 text-red-600 hover:text-red-800 hover:bg-red-50 rounded-md transition-colors"
                              title="Remove item"
                            >
                              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                              </svg>
                            </button>
                          </div>
                        </div>
                      ))
                    )}
                  </div>

                  <div className="mt-6 flex justify-end space-x-3">
                    <button
                      type="button"
                      onClick={() => {
                        resetQuotationForm();
                        setShowQuotationForm(false);
                      }}
                      className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50"
                    >
                      Cancel
                    </button>
                    <button
                      type="submit"
                      disabled={loading || quotationForm.items.length === 0}
                      className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50"
                    >
                      {loading
                        ? editingQuotationId
                          ? 'Updating...'
                          : 'Creating...'
                        : editingQuotationId
                          ? 'Update Quotation'
                          : 'Create Quotation'}
                    </button>
                  </div>
                </form>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Sales Orders Tab */}
      {activeTab === 'orders' && (
        <div>
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-lg font-semibold">Sales Orders</h2>
            <button
              onClick={() => setShowDirectSOForm(true)}
              className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
            >
              + Create Direct Order
            </button>
          </div>
          {loading ? (
            <p className="text-gray-600">Loading sales orders...</p>
          ) : (
            <div className="bg-white rounded-lg shadow overflow-x-auto">
              <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">SO Number</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Customer</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Project</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Order Date</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Delivery Date</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Amount</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Balance</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Actions</th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {orders.map((order) => (
                    <tr key={order.id}>
                      <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                        {order.so_number}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {order.customer_name || '-'}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                        {order.project || '-'}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                        {new Date(order.order_date).toLocaleDateString()}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                        {order.expected_delivery_date ? new Date(order.expected_delivery_date).toLocaleDateString() : '-'}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        ₹{order.net_amount.toLocaleString()}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        ₹{order.balance_amount.toLocaleString()}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className={`px-2 py-1 text-xs font-semibold rounded-full ${getStatusColor(order.status)}`}>
                          {order.status}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm">
                        <div className="flex flex-wrap items-center gap-2">
                          <button
                            onClick={() => openSmartJOForSO(order)}
                            className="text-amber-600 hover:text-amber-900 disabled:opacity-50"
                            title="Create a Smart Job Order from this Sales Order"
                            disabled={smartJOLoading}
                          >
                            {smartJOLoading ? 'Loading…' : 'Create Job Order'}
                          </button>
                          <button
                            onClick={() => handleEditSalesOrder(order.id)}
                            className="text-amber-600 hover:text-amber-900"
                          >
                            Edit
                          </button>
                          <button
                            onClick={() => handleDeleteSalesOrder(order)}
                            className="text-red-600 hover:text-red-900"
                          >
                            Delete
                          </button>
                          {(order.status === 'READY_TO_DISPATCH' || order.status === 'CONFIRMED') && (
                            <button
                              onClick={async () => {
                                setSelectedOrderForDispatch(order);
                                setDispatchForm({ ...dispatchForm, sales_order_id: order.id });
                                await fetchSalesOrderItems(order.id);
                                setShowDispatchForm(true);
                              }}
                              className="text-amber-600 hover:text-amber-900"
                            >
                              Create Dispatch
                            </button>
                          )}

                          <button
                            onClick={() => handleSendSalesOrderEmail(order.id)}
                            disabled={sendingSOEmailId === order.id}
                            className="text-amber-600 hover:text-amber-900 disabled:opacity-50"
                          >
                            {sendingSOEmailId === order.id ? 'Sending...' : 'Send SO Email'}
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {showOrderEditForm && editingOrderId && (
            <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
              <div className="bg-white rounded-lg p-6 max-w-xl w-full">
                <h3 className="text-lg font-semibold mb-4">Edit Sales Order</h3>
                <form onSubmit={handleSaveSalesOrder}>
                  <div className="space-y-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Expected Delivery Date</label>
                      <input
                        type="date"
                        value={orderEditForm.expected_delivery_date}
                        onChange={(e) =>
                          setOrderEditForm({ ...orderEditForm, expected_delivery_date: e.target.value })
                        }
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Status</label>
                      <select
                        value={orderEditForm.status}
                        onChange={(e) => setOrderEditForm({ ...orderEditForm, status: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      >
                        <option value="CONFIRMED">CONFIRMED</option>
                        <option value="IN_PRODUCTION">IN_PRODUCTION</option>
                        <option value="READY_TO_DISPATCH">READY_TO_DISPATCH</option>
                        <option value="DISPATCHED">DISPATCHED</option>
                        <option value="DELIVERED">DELIVERED</option>
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Payment Terms</label>
                      <input
                        type="text"
                        value={orderEditForm.payment_terms}
                        onChange={(e) => setOrderEditForm({ ...orderEditForm, payment_terms: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Delivery Terms</label>
                      <input
                        type="text"
                        value={orderEditForm.delivery_terms}
                        onChange={(e) => setOrderEditForm({ ...orderEditForm, delivery_terms: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Notes</label>
                      <textarea
                        value={orderEditForm.notes}
                        onChange={(e) => setOrderEditForm({ ...orderEditForm, notes: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                        rows={3}
                      />
                    </div>
                  </div>

                  <div className="mt-6 flex justify-end space-x-3">
                    <button
                      type="button"
                      onClick={() => {
                        setShowOrderEditForm(false);
                        setEditingOrderId(null);
                      }}
                      className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50"
                    >
                      Cancel
                    </button>
                    <button
                      type="submit"
                      disabled={loading}
                      className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50"
                    >
                      {loading ? 'Saving...' : 'Save Changes'}
                    </button>
                  </div>
                </form>
              </div>
            </div>
          )}

          {/* Dispatch Form Modal */}
          {showDispatchForm && selectedOrderForDispatch && (
            <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
              <div className="bg-white rounded-lg p-6 max-w-4xl w-full max-h-[90vh] overflow-y-auto">
                <h3 className="text-lg font-semibold mb-4">
                  Create Dispatch for {selectedOrderForDispatch.so_number}
                </h3>
                <form onSubmit={handleCreateDispatch}>
                  <div className="grid grid-cols-2 gap-4 mb-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Dispatch Date *</label>
                      <input
                        type="date"
                        required
                        value={dispatchForm.dispatch_date}
                        onChange={(e) => setDispatchForm({ ...dispatchForm, dispatch_date: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Transporter Name</label>
                      <input
                        type="text"
                        value={dispatchForm.transporter_name}
                        onChange={(e) => setDispatchForm({ ...dispatchForm, transporter_name: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Vehicle Number</label>
                      <input
                        type="text"
                        value={dispatchForm.vehicle_number}
                        onChange={(e) => setDispatchForm({ ...dispatchForm, vehicle_number: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">LR Number</label>
                      <input
                        type="text"
                        value={dispatchForm.lr_number}
                        onChange={(e) => setDispatchForm({ ...dispatchForm, lr_number: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                  </div>

                  <div className="mb-4">
                    <div className="flex justify-between items-center mb-2">
                      <label className="block text-sm font-medium text-gray-700">Dispatch Items *</label>
                      <button
                        type="button"
                        onClick={addDispatchItem}
                        className="text-sm text-amber-600 hover:text-amber-700"
                      >
                        + Add Item
                      </button>
                    </div>

                    {salesOrderItems.length === 0 && (
                      <div className="mb-3 p-3 bg-yellow-50 border border-yellow-200 rounded-lg">
                        <p className="text-sm text-yellow-800">
                          ⚠️ No items found in this sales order. The sales order may not have any items yet.
                        </p>
                      </div>
                    )}

                    {dispatchForm.items.map((item, index) => (
                      <div key={index} className="grid grid-cols-4 gap-2 mb-2 p-3 border border-gray-200 rounded-lg bg-gray-50">
                        <div>
                          <label className="block text-xs text-gray-600 mb-1">SO Item *</label>
                          <select
                            required
                            value={item.sales_order_item_id}
                            onChange={(e) => updateDispatchItem(index, 'sales_order_item_id', e.target.value)}
                            className="w-full px-2 py-1 border border-gray-300 rounded text-sm"
                          >
                            <option value="">
                              {salesOrderItems.length === 0 ? 'No items available' : 'Select Item'}
                            </option>
                            {salesOrderItems.map((soItem) => (
                              <option key={soItem.id} value={soItem.id}>
                                {items.find(i => i.id === soItem.item_id)?.code || soItem.item_id} - Qty: {soItem.quantity - (soItem.dispatched_quantity || 0)}
                              </option>
                            ))}
                          </select>
                        </div>
                        <div className="col-span-2">
                          <label className="block text-xs text-gray-600 mb-1">Select UIDs * (Quantity auto-fills)</label>
                          {loadingUIDs[index] ? (
                            <div className="w-full px-2 py-1 border border-gray-300 rounded text-sm bg-gray-50 text-gray-500">
                              Loading UIDs...
                            </div>
                          ) : item.item_id && availableUIDs[item.item_id] ? (
                            <div className="w-full border border-gray-300 rounded-lg p-2 max-h-40 overflow-y-auto bg-white">
                              {availableUIDs[item.item_id].length === 0 ? (
                                <div className="text-sm text-gray-500">No UIDs available</div>
                              ) : (
                                <div className="space-y-1">
                                  {availableUIDs[item.item_id].map((uid) => (
                                    <label key={uid.id} className="flex items-center space-x-2 p-1 hover:bg-amber-50 rounded cursor-pointer">
                                      <input
                                        type="checkbox"
                                        checked={item.uid.includes(uid.uid)}
                                        onChange={(e) => {
                                          const newUids = e.target.checked
                                            ? [...item.uid, uid.uid]
                                            : item.uid.filter(u => u !== uid.uid);
                                          updateDispatchItem(index, 'uid', newUids);
                                        }}
                                        className="w-4 h-4 text-amber-600 rounded focus:ring-amber-500"
                                      />
                                      <span className="text-sm">
                                        {uid.uid} - {uid.status} {uid.location ? `(${uid.location})` : ''}
                                      </span>
                                    </label>
                                  ))}
                                </div>
                              )}
                              {item.uid.length > 0 && (
                                <div className="mt-2 pt-2 border-t border-gray-200 text-xs font-medium text-amber-600">
                                  {item.uid.length} UID{item.uid.length > 1 ? 's' : ''} selected
                                </div>
                              )}
                            </div>
                          ) : (
                            <div className="w-full px-2 py-1 border border-gray-300 rounded text-sm bg-gray-50 text-gray-500">
                              Select item first
                            </div>
                          )}
                        </div>
                        <div>
                          <label className="block text-xs text-gray-600 mb-1">Quantity (Auto)</label>
                          <input
                            type="number"
                            placeholder="Auto"
                            value={item.quantity}
                            readOnly
                            className="w-full px-2 py-1 border border-gray-300 rounded text-sm bg-gray-50 text-gray-700 font-semibold"
                            title="Quantity is automatically set based on selected UIDs"
                          />
                        </div>
                        <div>
                          <label className="block text-xs text-gray-600 mb-1">Batch</label>
                          <input
                            type="text"
                            placeholder="Batch"
                            value={item.batch_number}
                            onChange={(e) => updateDispatchItem(index, 'batch_number', e.target.value)}
                            className="w-full px-2 py-1 border border-gray-300 rounded text-sm"
                          />
                        </div>
                        <div className="flex items-end">
                          <button
                            type="button"
                            onClick={() => removeDispatchItem(index)}
                            className="w-full px-2 py-1 text-red-600 hover:text-red-800 text-sm border border-red-300 rounded hover:bg-red-50"
                          >
                            Remove
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>

                  <div className="mt-6 flex justify-end space-x-3">
                    <button
                      type="button"
                      onClick={() => {
                        setShowDispatchForm(false);
                        setSelectedOrderForDispatch(null);
                        setSalesOrderItems([]);
                      }}
                      className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50"
                    >
                      Cancel
                    </button>
                    <button
                      type="submit"
                      disabled={loading || dispatchForm.items.length === 0}
                      className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50"
                    >
                      {loading ? 'Creating...' : 'Create Dispatch'}
                    </button>
                  </div>
                </form>
              </div>
            </div>
          )}
        </div>
      )}

      {showSmartJOModal && smartJOOrder && (
        <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg p-6 max-w-lg w-full">
            <h3 className="text-lg font-semibold mb-2">Create Job Order</h3>
            <p className="text-sm text-gray-600 mb-4">
              Sales Order: <span className="font-medium text-gray-900">{smartJOOrder.so_number}</span>
            </p>

            <label className="block text-sm font-medium text-gray-700 mb-2">Select Sales Order Item</label>
            <select
              value={smartJOSelectedSOItemId}
              onChange={(e) => setSmartJOSelectedSOItemId(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg"
            >
              {smartJOSOItems.map((soItem) => {
                const item = items.find((i) => i.id === soItem.item_id);
                const label = `${item?.code || soItem.item_id} - Remaining: ${soItem.remainingQty}`;
                return (
                  <option key={soItem.id} value={soItem.id}>
                    {label}
                  </option>
                );
              })}
            </select>

            <div className="mt-6 flex justify-end gap-3">
              <button
                type="button"
                onClick={() => {
                  setShowSmartJOModal(false);
                  setSmartJOOrder(null);
                  setSmartJOSOItems([]);
                  setSmartJOSelectedSOItemId('');
                }}
                className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={() => {
                  const soItem = smartJOSOItems.find((x) => String(x.id) === String(smartJOSelectedSOItemId));
                  if (!soItem?.item_id || Number(soItem.remainingQty) <= 0) {
                    alert('Invalid sales order item selected.');
                    return;
                  }
                  router.push(
                    `/dashboard/production/job-orders/smart?salesOrderId=${encodeURIComponent(smartJOOrder.id)}` +
                      `&salesOrderItemId=${encodeURIComponent(soItem.id)}` +
                      `&itemId=${encodeURIComponent(soItem.item_id)}` +
                      `&quantity=${encodeURIComponent(String(soItem.remainingQty))}`,
                  );
                  setShowSmartJOModal(false);
                }}
                className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700"
              >
                Continue
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Dispatch Tab */}
      {activeTab === 'dispatch' && (
        <div>
          <h2 className="text-lg font-semibold mb-4">Dispatch Notes</h2>
          {loading ? (
            <p className="text-gray-600">Loading dispatch notes...</p>
          ) : (
            <div className="bg-white rounded-lg shadow overflow-x-auto">
              <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">DN Number</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">SO Number</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Customer</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Dispatch Date</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Transporter</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Vehicle No.</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Actions</th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {dispatches.map((dispatch) => (
                    <tr key={dispatch.id}>
                      <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                        {dispatch.dn_number}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {dispatch.so_number || '-'}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {dispatch.customer_name || '-'}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                        {new Date(dispatch.dispatch_date).toLocaleDateString()}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                        {dispatch.transporter_name || '-'}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                        {dispatch.vehicle_number || '-'}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm">
                        <div className="flex flex-wrap items-center gap-2">
                          <button
                            type="button"
                            onClick={() => handleEditDispatch(dispatch)}
                            className="text-amber-600 hover:text-amber-900"
                          >
                            Edit
                          </button>
                          <button
                            type="button"
                            onClick={() => handleDeleteDispatch(dispatch)}
                            className="text-red-600 hover:text-red-900"
                          >
                            Delete
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {showDispatchEditForm && editingDispatchId && (
            <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
              <div className="bg-white rounded-lg p-6 max-w-2xl w-full max-h-[90vh] overflow-y-auto">
                <h3 className="text-lg font-semibold mb-4">Edit Dispatch Note</h3>
                <form onSubmit={handleSaveDispatch}>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Dispatch Date *</label>
                      <input
                        type="date"
                        required
                        value={dispatchEditForm.dispatch_date}
                        onChange={(e) => setDispatchEditForm({ ...dispatchEditForm, dispatch_date: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Transporter Name</label>
                      <input
                        type="text"
                        value={dispatchEditForm.transporter_name}
                        onChange={(e) =>
                          setDispatchEditForm({ ...dispatchEditForm, transporter_name: e.target.value })
                        }
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Vehicle Number</label>
                      <input
                        type="text"
                        value={dispatchEditForm.vehicle_number}
                        onChange={(e) => setDispatchEditForm({ ...dispatchEditForm, vehicle_number: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">LR Number</label>
                      <input
                        type="text"
                        value={dispatchEditForm.lr_number}
                        onChange={(e) => setDispatchEditForm({ ...dispatchEditForm, lr_number: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">LR Date</label>
                      <input
                        type="date"
                        value={dispatchEditForm.lr_date}
                        onChange={(e) => setDispatchEditForm({ ...dispatchEditForm, lr_date: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div className="col-span-2">
                      <label className="block text-sm font-medium text-gray-700 mb-1">Delivery Address</label>
                      <textarea
                        value={dispatchEditForm.delivery_address}
                        onChange={(e) =>
                          setDispatchEditForm({ ...dispatchEditForm, delivery_address: e.target.value })
                        }
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                        rows={2}
                      />
                    </div>
                    <div className="col-span-2">
                      <label className="block text-sm font-medium text-gray-700 mb-1">Notes</label>
                      <textarea
                        value={dispatchEditForm.notes}
                        onChange={(e) => setDispatchEditForm({ ...dispatchEditForm, notes: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                        rows={2}
                      />
                    </div>
                  </div>

                  <div className="mt-6 flex justify-end space-x-3">
                    <button
                      type="button"
                      onClick={() => {
                        setShowDispatchEditForm(false);
                        setEditingDispatchId(null);
                      }}
                      className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50"
                    >
                      Cancel
                    </button>
                    <button
                      type="submit"
                      disabled={loading}
                      className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50"
                    >
                      {loading ? 'Saving...' : 'Save Changes'}
                    </button>
                  </div>
                </form>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Warranties Tab */}
      {activeTab === 'warranties' && (
        <div>
          <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
            <h2 className="text-lg font-semibold">Warranties</h2>
            <button
              onClick={() => setShowWarrantyForm(true)}
              className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700"
            >
              + Register Warranty
            </button>
          </div>
          {loading ? (
            <p className="text-gray-600">Loading warranties...</p>
          ) : (
            <div className="bg-white rounded-lg shadow overflow-x-auto">
              <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Warranty No.</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">UID</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Customer</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Start Date</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Duration</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">End Date</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Claims</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Actions</th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {warranties.map((warranty) => (
                    <tr key={warranty.id}>
                      <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                        {warranty.warranty_number}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm font-mono text-gray-900">
                        {warranty.uid}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {warranty.customer_name || '-'}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                        {new Date(warranty.warranty_start_date).toLocaleDateString()}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                        {warranty.warranty_duration_months} months
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                        {new Date(warranty.warranty_end_date).toLocaleDateString()}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className={`px-2 py-1 text-xs font-semibold rounded-full ${getStatusColor(warranty.status)}`}>
                          {warranty.status}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                        {warranty.claim_count}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm">
                        <div className="flex flex-wrap items-center gap-2">
                          <button
                            type="button"
                            onClick={() => handlePrintWarranty(warranty.id)}
                            className="text-blue-600 hover:text-blue-900"
                          >
                            Print
                          </button>
                          <button
                            type="button"
                            onClick={() => handleEditWarranty(warranty)}
                            className="text-amber-600 hover:text-amber-900"
                          >
                            Edit
                          </button>
                          <button
                            type="button"
                            onClick={() => handleDeleteWarranty(warranty)}
                            className="text-red-600 hover:text-red-900"
                          >
                            Delete
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {showWarrantyEditForm && editingWarrantyId && (
            <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
              <div className="bg-white rounded-lg p-6 max-w-lg w-full">
                <h3 className="text-lg font-semibold mb-4">Edit Warranty</h3>
                <form onSubmit={handleSaveWarranty}>
                  <div className="space-y-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Warranty Type *</label>
                      <select
                        required
                        value={warrantyEditForm.warranty_type}
                        onChange={(e) => setWarrantyEditForm({ ...warrantyEditForm, warranty_type: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      >
                        <option value="STANDARD">Standard Warranty</option>
                        <option value="EXTENDED">Extended Warranty</option>
                        <option value="COMPREHENSIVE">Comprehensive</option>
                        <option value="LIMITED">Limited Warranty</option>
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Status *</label>
                      <select
                        required
                        value={warrantyEditForm.status}
                        onChange={(e) => setWarrantyEditForm({ ...warrantyEditForm, status: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      >
                        <option value="ACTIVE">Active</option>
                        <option value="CLAIMED">Claimed</option>
                        <option value="EXPIRED">Expired</option>
                        <option value="VOID">Void</option>
                      </select>
                    </div>
                  </div>

                  <div className="mt-6 flex justify-end space-x-3">
                    <button
                      type="button"
                      onClick={() => {
                        setShowWarrantyEditForm(false);
                        setEditingWarrantyId(null);
                      }}
                      className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50"
                    >
                      Cancel
                    </button>
                    <button
                      type="submit"
                      disabled={loading}
                      className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50"
                    >
                      {loading ? 'Saving...' : 'Save Changes'}
                    </button>
                  </div>
                </form>
              </div>
            </div>
          )}

          {/* Warranty Form Modal */}
          {showWarrantyForm && (
            <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
              <div className="bg-white rounded-lg p-6 max-w-lg w-full">
                <h3 className="text-lg font-semibold mb-4">Register Warranty</h3>
                <form onSubmit={handleCreateWarranty}>
                  <div className="space-y-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">UID (Unique Identification) *</label>
                      <input
                        type="text"
                        required
                        placeholder="Enter UID from dispatch"
                        value={warrantyForm.uid}
                        onChange={(e) => setWarrantyForm({ ...warrantyForm, uid: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                      <p className="text-xs text-gray-500 mt-1">UID must be from a dispatched item</p>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Warranty Duration (Months) *</label>
                      <input
                        type="number"
                        required
                        min="1"
                        max="120"
                        value={warrantyForm.warranty_duration_months}
                        onChange={(e) => setWarrantyForm({ ...warrantyForm, warranty_duration_months: parseInt(e.target.value) })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Warranty Type *</label>
                      <select
                        required
                        value={warrantyForm.warranty_type}
                        onChange={(e) => setWarrantyForm({ ...warrantyForm, warranty_type: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      >
                        <option value="STANDARD">Standard Warranty</option>
                        <option value="EXTENDED">Extended Warranty</option>
                        <option value="COMPREHENSIVE">Comprehensive</option>
                        <option value="LIMITED">Limited Warranty</option>
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Notes</label>
                      <textarea
                        rows={3}
                        value={warrantyForm.notes}
                        onChange={(e) => setWarrantyForm({ ...warrantyForm, notes: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                        placeholder="Additional warranty terms or conditions..."
                      />
                    </div>
                  </div>

                  <div className="mt-6 flex justify-end space-x-3">
                    <button
                      type="button"
                      onClick={() => setShowWarrantyForm(false)}
                      className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50"
                    >
                      Cancel
                    </button>
                    <button
                      type="submit"
                      disabled={loading}
                      className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50"
                    >
                      {loading ? 'Registering...' : 'Register Warranty'}
                    </button>
                  </div>
                </form>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Duplicate Warning Modals */}
      <DuplicateWarning
        isOpen={customerDuplicateDetection.duplicateState.isOpen}
        exactMatches={customerDuplicateDetection.duplicateState.exactMatches}
        fuzzyMatches={customerDuplicateDetection.duplicateState.fuzzyMatches}
        entityType="Customer"
        onProceed={customerDuplicateDetection.handleProceed}
        onCancel={customerDuplicateDetection.handleCancel}
        formatRecord={(data) => (
          <div className="text-sm">
            <p className="font-semibold">{data.customer_name}</p>
            <p className="text-xs text-gray-600">GST: {data.gst_number || 'N/A'}</p>
            <p className="text-xs text-gray-600">Contact: {data.contact_person}</p>
            <p className="text-xs text-gray-600">Phone: {data.phone || data.mobile}</p>
          </div>
        )}
      />

      <DuplicateWarning
        isOpen={quotationDuplicateDetection.duplicateState.isOpen}
        exactMatches={quotationDuplicateDetection.duplicateState.exactMatches}
        fuzzyMatches={quotationDuplicateDetection.duplicateState.fuzzyMatches}
        entityType="Quotation"
        onProceed={quotationDuplicateDetection.handleProceed}
        onCancel={quotationDuplicateDetection.handleCancel}
        formatRecord={(data) => (
          <div className="text-sm">
            <p className="font-semibold">Quote #{data.quotation_number}</p>
            <p className="text-xs text-gray-600">Customer: {data.customer_name}</p>
            <p className="text-xs text-gray-600">Items: {data.items?.length || data.quotation_items?.length || 0}</p>
            <p className="text-xs text-gray-600">Total: ₹{data.total_amount?.toLocaleString() || data.net_amount?.toLocaleString()}</p>
          </div>
        )}
      />

      <DuplicateWarning
        isOpen={salesOrderDuplicateDetection.duplicateState.isOpen}
        exactMatches={salesOrderDuplicateDetection.duplicateState.exactMatches}
        fuzzyMatches={salesOrderDuplicateDetection.duplicateState.fuzzyMatches}
        entityType="Sales Order"
        onProceed={salesOrderDuplicateDetection.handleProceed}
        onCancel={salesOrderDuplicateDetection.handleCancel}
        formatRecord={(data) => (
          <div className="text-sm">
            <p className="font-semibold">SO #{data.so_number}</p>
            <p className="text-xs text-gray-600">Customer: {data.customer_name}</p>
            <p className="text-xs text-gray-600">Items: {data.items?.length || data.sales_order_items?.length || 0}</p>
            <p className="text-xs text-gray-600">Total: ₹{data.total_amount?.toLocaleString() || data.net_amount?.toLocaleString()}</p>
          </div>
        )}
      />
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { apiClient } from '../../../../lib/api-client';
import SearchableSelect from '../../../components/SearchableSelect';

type TabType = 'tickets' | 'technicians' | 'warranty-check' | 'reports';

interface ServiceTicket {
  id: string;
  ticket_number: string;
  customer: { customer_name: string };
  uid?: string;
  ship_name?: string;
  location?: string;
  service_type: string;
  priority: string;
  status: string;
  complaint_date: string;
  complaint_description: string;
  reported_by?: string;
  contact_number?: string;
  email?: string;
  product_name?: string;
  model_number?: string;
  service_location?: string;
  expected_completion_date?: string;
  is_under_warranty: boolean;
  warranty_valid_until?: string;
  estimated_cost: number;
  actual_cost: number;
  attachments?: string[];
  created_at: string;
}

interface Technician {
  id: string;
  technician_code: string;
  technician_name: string;
  specialization?: string;
  contact_number?: string;
  email?: string;
  is_active: boolean;
  total_assignments: number;
  completed_services: number;
  average_rating: number;
}

interface WarrantyValidation {
  is_valid: boolean;
  warranty: any;
  message: string;
  days_remaining?: number;
}

interface Customer {
  id: string;
  customer_code: string;
  customer_name: string;
  customer_type: string;
  contact_person?: string;
  email?: string;
  phone?: string;
  mobile?: string;
}

interface Item {
  id: string;
  code: string;
  name: string;
  description?: string;
  category?: string;
}

interface UIDRecord {
  uid: string;
  entity_id: string;
  status: string;
  location?: string;
  batch_number?: string;
}

interface DeploymentStatusRecord {
  uid_id: string;
  uid: string;
  client_part_number: string | null;
  job_order_id: string | null;
  item_name: string | null;
  item_code: string | null;
  current_level: string | null;
  current_organization: string | null;
  current_location: string | null;
  current_deployment_date: string | null;
  warranty_expiry_date: string | null;
}

function getAttachmentKind(url: string): 'image' | 'video' | 'other' {
  const normalized = (url || '').split('?')[0].toLowerCase();
  if (normalized.match(/\.(mp4|mov|webm|mkv|avi|m4v)$/)) return 'video';
  if (normalized.match(/\.(png|jpe?g|gif|webp|bmp|svg)$/)) return 'image';
  // Fallback: if backend returns clean /uploads/... without extension
  if (normalized.includes('/uploads/') && normalized.includes('/service/')) return 'image';
  return 'other';
}

export default function ServicePage() {
  const [activeTab, setActiveTab] = useState<TabType>('tickets');
  const [tickets, setTickets] = useState<ServiceTicket[]>([]);
  const [technicians, setTechnicians] = useState<Technician[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  
  // Data for dropdowns
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [items, setItems] = useState<Item[]>([]);
  const [availableUIDs, setAvailableUIDs] = useState<UIDRecord[]>([]);
  const [shipNames, setShipNames] = useState<string[]>([]);
  const [shipNameInput, setShipNameInput] = useState('');
  const [filteredShipNames, setFilteredShipNames] = useState<string[]>([]);
  const [showShipNameDropdown, setShowShipNameDropdown] = useState(false);

  // Product/Part Number/UID lookup (searches deployed units)
  const [productLookupInput, setProductLookupInput] = useState('');
  const [productLookupResults, setProductLookupResults] = useState<DeploymentStatusRecord[]>([]);
  const [showProductLookupDropdown, setShowProductLookupDropdown] = useState(false);
  const [productLookupLoading, setProductLookupLoading] = useState(false);
  const [selectedDeployment, setSelectedDeployment] = useState<DeploymentStatusRecord | null>(null);

  // Forms
  const [showTicketForm, setShowTicketForm] = useState(false);
  const [showTechnicianForm, setShowTechnicianForm] = useState(false);
  const [showTicketDetails, setShowTicketDetails] = useState(false);
  const [selectedTicket, setSelectedTicket] = useState<ServiceTicket | null>(null);
  const [showStatusModal, setShowStatusModal] = useState(false);
  const [showEditTicketModal, setShowEditTicketModal] = useState(false);
  const [editTicketForm, setEditTicketForm] = useState({
    priority: 'MEDIUM',
    expected_completion_date: '',
    ship_name: '',
    location: '',
    service_location: '',
    product_name: '',
    model_number: '',
    reported_by: '',
    contact_number: '',
    email: '',
    complaint_description: '',
  });
  const [showTechnicianDetails, setShowTechnicianDetails] = useState(false);
  const [selectedTechnician, setSelectedTechnician] = useState<any>(null);
  const [showEditTechnicianModal, setShowEditTechnicianModal] = useState(false);
  const [ticketForm, setTicketForm] = useState({
    customer_id: '',
    uid: '',
    ship_name: '',
    location: '',
    complaint_description: '',
    reported_by: '',
    contact_number: '',
    email: '',
    product_id: '',
    product_name: '',
    model_number: '',
    service_location: '',
    priority: 'MEDIUM',
    expected_completion_date: '',
  });

  const [uploadedFiles, setUploadedFiles] = useState<File[]>([]);
  const [uploadPreviews, setUploadPreviews] = useState<string[]>([]);

  const [technicianForm, setTechnicianForm] = useState({
    technician_name: '',
    specialization: '',
    contact_number: '',
    email: '',
    is_active: true,
  });

  // Warranty check
  const [warrantyUID, setWarrantyUID] = useState('');
  const [warrantyResult, setWarrantyResult] = useState<WarrantyValidation | null>(null);

  // Reports
  const [reports, setReports] = useState<any>(null);

  useEffect(() => {
    if (activeTab === 'tickets') {
      fetchTickets();
    } else if (activeTab === 'technicians') {
      fetchTechnicians();
    } else if (activeTab === 'reports') {
      fetchReports();
    }
  }, [activeTab]);

  useEffect(() => {
    // Fetch customers and items when component mounts
    fetchCustomers();
    fetchItems();
    fetchShipNames();
  }, []);

  useEffect(() => {
    if (!showTicketForm) return;

    const query = productLookupInput.trim();
    if (!query) {
      setProductLookupResults([]);
      setShowProductLookupDropdown(false);
      return;
    }

    const handle = setTimeout(async () => {
      try {
        setProductLookupLoading(true);
        const response = await apiClient.get<{
          data: DeploymentStatusRecord[];
          total: number;
          offset: number;
          limit: number;
        }>(
          `/uid/deployment/status?search=${encodeURIComponent(query)}&offset=0&limit=20&sort_by=uid&sort_order=asc`,
        );

        const results = response?.data || [];
        setProductLookupResults(results);
        setShowProductLookupDropdown(results.length > 0);
      } catch (err) {
        console.error('Failed to lookup product/part/uid:', err);
        setProductLookupResults([]);
        setShowProductLookupDropdown(false);
      } finally {
        setProductLookupLoading(false);
      }
    }, 250);

    return () => clearTimeout(handle);
  }, [productLookupInput, showTicketForm]);

  const formatWarrantyDate = (dateStr: string) => {
    const date = new Date(dateStr);
    if (Number.isNaN(date.getTime())) return dateStr;
    // 20-Jan-2026 style
    return date
      .toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })
      .replace(/ /g, '-');
  };

  const getWarrantyStatusText = (warrantyExpiryDate: string | null | undefined) => {
    if (!warrantyExpiryDate) return null;
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const expiry = new Date(warrantyExpiryDate);
    if (Number.isNaN(expiry.getTime())) return null;
    expiry.setHours(0, 0, 0, 0);

    if (expiry >= today) {
      return `In warranty, expiring by ${formatWarrantyDate(warrantyExpiryDate)}`;
    }
    return `Warranty expired on ${formatWarrantyDate(warrantyExpiryDate)}`;
  };

  const selectDeployment = (deployment: DeploymentStatusRecord) => {
    setSelectedDeployment(deployment);
    setProductLookupInput(
      deployment.client_part_number
        ? `${deployment.client_part_number}`
        : deployment.uid,
    );
    setShowProductLookupDropdown(false);

    const matchedItem = deployment.item_code
      ? items.find((item) => item.code === deployment.item_code)
      : undefined;

    setTicketForm((prev) => ({
      ...prev,
      uid: deployment.uid,
      product_id: matchedItem?.id || prev.product_id,
      product_name: deployment.item_name || matchedItem?.name || prev.product_name,
      model_number: deployment.client_part_number || prev.model_number,
    }));
  };

  const fetchCustomers = async () => {
    try {
      const data = await apiClient.get<Customer[]>('/sales/customers');
      setCustomers(data);
    } catch (err) {
      console.error('Failed to fetch customers:', err);
    }
  };

  const fetchItems = async () => {
    try {
      const data = await apiClient.get<Item[]>('/items');
      setItems(data);
    } catch (err) {
      console.error('Failed to fetch items:', err);
    }
  };

  const fetchShipNames = async () => {
    try {
      const data = await apiClient.get<ServiceTicket[]>('/service/tickets');
      const uniqueShipNames = [...new Set(data.map(t => t.ship_name).filter(Boolean))] as string[];
      setShipNames(uniqueShipNames.sort());
    } catch (err) {
      console.error('Failed to fetch ship names:', err);
    }
  };

  const updateShipNameSuggestions = (value: string) => {
    const query = value.trim().toLowerCase();
    const suggestions = query
      ? shipNames.filter((name) => name.toLowerCase().includes(query))
      : shipNames;

    setFilteredShipNames(suggestions);
    setShowShipNameDropdown(suggestions.length > 0);
  };

  const handleShipNameChange = (value: string) => {
    setShipNameInput(value);
    setTicketForm((prev) => ({ ...prev, ship_name: value }));
    updateShipNameSuggestions(value);
  };

  const selectShipName = (name: string) => {
    setShipNameInput(name);
    setTicketForm((prev) => ({ ...prev, ship_name: name }));
    setShowShipNameDropdown(false);
  };

  const fetchAvailableUIDs = async (itemId: string) => {
    if (!itemId) {
      setAvailableUIDs([]);
      return;
    }
    try {
      const data = await apiClient.get<UIDRecord[]>(`/uid?item_id=${itemId}&status=GENERATED`);
      setAvailableUIDs(data);
    } catch (err) {
      console.error('Failed to fetch UIDs:', err);
      setAvailableUIDs([]);
    }
  };

  const fetchTickets = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await apiClient.get<ServiceTicket[]>('/service/tickets');
      setTickets(data);
    } catch (err: any) {
      setError(err.message || 'Failed to fetch service tickets');
    } finally {
      setLoading(false);
    }
  };

  const fetchTechnicians = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await apiClient.get<Technician[]>('/service/technicians');
      setTechnicians(data);
    } catch (err: any) {
      setError(err.message || 'Failed to fetch technicians');
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);
    const validFiles = files.filter(file => {
      const isImage = file.type.startsWith('image/');
      const isVideo = file.type.startsWith('video/');
      const isUnder50MB = file.size <= 50 * 1024 * 1024; // 50MB limit
      return (isImage || isVideo) && isUnder50MB;
    });

    if (validFiles.length < files.length) {
      alert('Some files were rejected. Only images and videos under 50MB are allowed.');
    }

    setUploadedFiles(prev => [...prev, ...validFiles]);

    // Create previews
    validFiles.forEach(file => {
      const reader = new FileReader();
      reader.onloadend = () => {
        setUploadPreviews(prev => [...prev, reader.result as string]);
      };
      reader.readAsDataURL(file);
    });
  };

  const removeFile = (index: number) => {
    setUploadedFiles(prev => prev.filter((_, i) => i !== index));
    setUploadPreviews(prev => prev.filter((_, i) => i !== index));
  };

  const fetchReports = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await apiClient.get<any>('/service/reports');
      setReports(data);
    } catch (err: any) {
      setError(err.message || 'Failed to fetch reports');
    } finally {
      setLoading(false);
    }
  };

  const handleCreateTicket = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      // Remove product_id and clean up empty date fields before sending
      const { product_id, ...ticketData } = ticketForm;
      
      // Convert empty string dates to null for PostgreSQL
      const cleanedData = {
        ...ticketData,
        expected_completion_date: ticketData.expected_completion_date || null,
      };
      
      console.log('Submitting ticket data:', cleanedData);
      
      // If there are files, upload them first
      let attachmentUrls: string[] = [];
      if (uploadedFiles.length > 0) {
        const formData = new FormData();
        uploadedFiles.forEach(file => {
          formData.append('files', file);
        });
        
        try {
          const token =
            typeof window !== 'undefined'
              ? window.localStorage.getItem('accessToken')
              : null;

          const uploadResponse = await fetch('/api/v1/service/uploads', {
            method: 'POST',
            headers: token ? { Authorization: `Bearer ${token}` } : undefined,
            body: formData,
          });
          if (!uploadResponse.ok) {
            const errorText = await uploadResponse.text();
            throw new Error(`Upload failed (${uploadResponse.status}): ${errorText || uploadResponse.statusText}`);
          }
          const uploadResult = await uploadResponse.json();
          attachmentUrls = uploadResult?.urls || [];
        } catch (uploadError) {
          console.error('File upload failed:', uploadError);
          alert('Warning: File upload failed. Ticket will be created without attachments.');
        }
      }
      
      // Create ticket with attachment URLs
      const ticketDataWithAttachments = {
        ...cleanedData,
        attachments: attachmentUrls,
      };
      
      const response = await apiClient.post('/service/tickets', ticketDataWithAttachments);
      console.log('Ticket creation response:', response);
      setShowTicketForm(false);
      setTicketForm({
        customer_id: '',
        uid: '',
        ship_name: '',
        location: '',
        complaint_description: '',
        reported_by: '',
        contact_number: '',
        email: '',
        product_id: '',
        product_name: '',
        model_number: '',
        service_location: '',
        priority: 'MEDIUM',
        expected_completion_date: '',
      });
      setUploadedFiles([]);
      setUploadPreviews([]);
      setShipNameInput('');
      fetchTickets();
      fetchShipNames(); // Refresh ship names list
    } catch (err: any) {
      console.error('Ticket creation error:', err);
      setError(err.message || 'Failed to create service ticket');
    } finally {
      setLoading(false);
    }
  };

  const handleCreateTechnician = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      await apiClient.post('/service/technicians', technicianForm);
      setShowTechnicianForm(false);
      setTechnicianForm({
        technician_name: '',
        specialization: '',
        contact_number: '',
        email: '',
        is_active: true,
      });
      fetchTechnicians();
    } catch (err: any) {
      setError(err.message || 'Failed to create technician');
    } finally {
      setLoading(false);
    }
  };

  const handleWarrantyCheck = async () => {
    if (!warrantyUID.trim()) {
      setError('Please enter a UID');
      return;
    }
    setLoading(true);
    setError(null);
    try {
      const data = await apiClient.get<WarrantyValidation>(`/service/warranty/validate/${warrantyUID}`);
      setWarrantyResult(data);
    } catch (err: any) {
      setError(err.message || 'Failed to validate warranty');
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status: string) => {
    const colors: Record<string, string> = {
      OPEN: 'bg-yellow-100 text-yellow-800',
      ASSIGNED: 'bg-blue-100 text-blue-800',
      IN_PROGRESS: 'bg-purple-100 text-purple-800',
      PARTS_PENDING: 'bg-orange-100 text-orange-800',
      COMPLETED: 'bg-green-100 text-green-800',
      CLOSED: 'bg-gray-100 text-gray-800',
      CANCELLED: 'bg-red-100 text-red-800',
    };
    return colors[status] || 'bg-gray-100 text-gray-800';
  };

  const getPriorityColor = (priority: string) => {
    const colors: Record<string, string> = {
      LOW: 'bg-blue-100 text-blue-800',
      MEDIUM: 'bg-yellow-100 text-yellow-800',
      HIGH: 'bg-orange-100 text-orange-800',
      CRITICAL: 'bg-red-100 text-red-800',
    };
    return colors[priority] || 'bg-gray-100 text-gray-800';
  };

  const router = useRouter();

  return (
    <div className="p-6">
      <div className="mb-6">
        <button
          onClick={() => router.push('/dashboard')}
          className="text-amber-600 hover:text-amber-800 text-sm mb-2"
        >
          ← Back to Dashboard
        </button>
        <h1 className="text-2xl font-bold text-gray-900">Service & Warranty Management</h1>
        <p className="text-sm text-gray-600 mt-1">
          Manage service tickets, technicians, and warranty validations
        </p>
      </div>

      {error && (
        <div className="mb-4 p-4 bg-red-50 border border-red-200 rounded-lg">
          <p className="text-sm text-red-800">{error}</p>
        </div>
      )}

      {/* Tabs */}
      <div className="border-b border-gray-200 mb-6">
        <nav className="-mb-px flex space-x-8">
          {[
            { id: 'tickets', label: 'Service Tickets' },
            { id: 'technicians', label: 'Technicians' },
            { id: 'warranty-check', label: 'Warranty Check' },
            { id: 'reports', label: 'Reports' },
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as TabType)}
              className={`py-2 px-1 border-b-2 font-medium text-sm ${
                activeTab === tab.id
                  ? 'border-amber-500 text-amber-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </nav>
      </div>

      {/* Service Tickets Tab */}
      {activeTab === 'tickets' && (
        <div>
          <div className="mb-4 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-2">
            <h2 className="text-lg font-semibold">Service Tickets</h2>
            <button
              onClick={() => setShowTicketForm(true)}
              className="w-full sm:w-auto px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 text-center"
            >
              + Create Ticket
            </button>
          </div>

          {loading ? (
            <p className="text-gray-600">Loading service tickets...</p>
          ) : (
            <div className="bg-white rounded-lg shadow overflow-hidden">
              {/* Desktop Table */}
              <div className="hidden md:block overflow-x-auto">
              <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Ticket #</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Customer</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Product/UID</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Type</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Priority</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Date</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Warranty</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Actions</th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {tickets.map((ticket) => (
                    <tr key={ticket.id} className="hover:bg-gray-50">
                      <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                        {ticket.ticket_number}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {ticket.customer?.customer_name || '-'}
                      </td>
                      <td className="px-6 py-4 text-sm text-gray-900">
                        <div>{ticket.product_name || '-'}</div>
                        {ticket.uid && <div className="text-xs font-mono text-gray-500">{ticket.uid}</div>}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                        {ticket.service_type}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className={`px-2 py-1 text-xs font-semibold rounded-full ${getPriorityColor(ticket.priority)}`}>
                          {ticket.priority}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className={`px-2 py-1 text-xs font-semibold rounded-full ${getStatusColor(ticket.status)}`}>
                          {ticket.status}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                        {new Date(ticket.complaint_date).toLocaleDateString()}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm">
                        {ticket.is_under_warranty ? (
                          <span className="text-green-600">✓ Valid</span>
                        ) : (
                          <span className="text-gray-400">-</span>
                        )}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm">
                        <div className="flex space-x-2">
                          <button onClick={() => { setSelectedTicket(ticket); setShowTicketDetails(true); }} className="text-blue-600 hover:text-blue-800" title="View Details">
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
                          </button>
                          <button
                            onClick={() => {
                              setSelectedTicket(ticket);
                              setEditTicketForm({
                                priority: ticket.priority || 'MEDIUM',
                                expected_completion_date: (ticket as any).expected_completion_date || '',
                                ship_name: ticket.ship_name || '',
                                location: ticket.location || '',
                                service_location: (ticket as any).service_location || '',
                                product_name: ticket.product_name || '',
                                model_number: (ticket as any).model_number || '',
                                reported_by: ticket.reported_by || '',
                                contact_number: ticket.contact_number || '',
                                email: ticket.email || '',
                                complaint_description: ticket.complaint_description || '',
                              });
                              setShowEditTicketModal(true);
                            }}
                            className="text-amber-600 hover:text-amber-800"
                            title="Edit"
                          >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                          </button>
                          <button onClick={() => { setSelectedTicket(ticket); setShowStatusModal(true); }} className="text-amber-600 hover:text-amber-800" title="Update Status">
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>
                          </button>
                          {ticket.status === 'OPEN' && (
                            <button onClick={async () => { if (confirm('Delete this ticket?')) { try { await apiClient.delete(`/service/tickets/${ticket.id}`); fetchTickets(); } catch (err: any) { setError(err.message); } } }} className="text-red-600 hover:text-red-800" title="Delete">
                              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              </div>
              
              {/* Mobile Card View */}
              <div className="md:hidden space-y-4 p-4">
                {tickets.map((ticket) => (
                  <div key={ticket.id} className="bg-white border border-gray-200 rounded-lg p-4 shadow-sm">
                    <div className="flex justify-between items-start mb-2">
                      <span className="font-semibold text-amber-600">{ticket.ticket_number}</span>
                      <span className={`px-2 py-1 text-xs font-semibold rounded-full ${getStatusColor(ticket.status)}`}>
                        {ticket.status}
                      </span>
                    </div>
                    <div className="text-sm text-gray-900 mb-1">{ticket.customer?.customer_name}</div>
                    <div className="text-xs text-gray-600 space-y-1">
                      {ticket.product_name && <div>📦 {ticket.product_name}</div>}
                      {ticket.uid && <div className="font-mono">🔖 {ticket.uid}</div>}
                      {ticket.ship_name && <div>🚢 {ticket.ship_name}</div>}
                      {ticket.location && <div>📍 {ticket.location}</div>}
                      <div>📅 {new Date(ticket.complaint_date).toLocaleDateString()}</div>
                      <div>
                        <span className={`px-2 py-0.5 rounded-full text-xs ${getPriorityColor(ticket.priority)}`}>
                          {ticket.priority}
                        </span>
                      </div>
                    </div>
                    <div className="mt-3 flex gap-2">
                      <button 
                        onClick={() => { setSelectedTicket(ticket); setShowTicketDetails(true); }}
                        className="flex-1 text-xs px-3 py-2 bg-blue-50 text-blue-700 rounded hover:bg-blue-100"
                      >
                        View
                      </button>
                      <button
                        onClick={() => {
                          setSelectedTicket(ticket);
                          setEditTicketForm({
                            priority: ticket.priority || 'MEDIUM',
                            expected_completion_date: (ticket as any).expected_completion_date || '',
                            ship_name: ticket.ship_name || '',
                            location: ticket.location || '',
                            service_location: (ticket as any).service_location || '',
                            product_name: ticket.product_name || '',
                            model_number: (ticket as any).model_number || '',
                            reported_by: ticket.reported_by || '',
                            contact_number: ticket.contact_number || '',
                            email: ticket.email || '',
                            complaint_description: ticket.complaint_description || '',
                          });
                          setShowEditTicketModal(true);
                        }}
                        className="flex-1 text-xs px-3 py-2 bg-amber-50 text-amber-700 rounded hover:bg-amber-100"
                      >
                        Edit
                      </button>
                      <button 
                        onClick={() => { setSelectedTicket(ticket); setShowStatusModal(true); }}
                        className="flex-1 text-xs px-3 py-2 bg-amber-50 text-amber-700 rounded hover:bg-amber-100"
                      >
                        Update
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Ticket Form Modal */}
          {showTicketForm && (
            <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50 p-4">
              <div className="bg-white rounded-lg p-4 md:p-6 max-w-2xl w-full max-h-[95vh] overflow-y-auto">
                <div className="flex justify-between items-center mb-4">
                  <h3 className="text-lg md:text-xl font-semibold">Create Service Ticket</h3>
                  <button onClick={() => setShowTicketForm(false)} className="text-gray-500 hover:text-gray-700">
                    ✕
                  </button>
                </div>
                <form onSubmit={handleCreateTicket}>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="md:col-span-2">
                      <label className="block text-sm font-medium text-gray-700 mb-1">Customer ID *</label>
                      <SearchableSelect
                        options={customers.map(c => ({ value: c.id, label: `${c.customer_code} - ${c.customer_name}` }))}
                        value={ticketForm.customer_id}
                        onChange={(value) => setTicketForm({ ...ticketForm, customer_id: value })}
                        placeholder="Select Customer"
                        required
                      />
                    </div>

                    {/* NEW FIELDS */}
                    <div className="md:col-span-2 relative">
                      <label className="block text-sm font-medium text-gray-700 mb-1">
                        🚢 Ship Name * 
                        {shipNameInput && !shipNames.includes(shipNameInput) && (
                          <span className="ml-2 text-xs text-amber-600">✨ New ship (will be saved)</span>
                        )}
                      </label>
                      <input
                        type="text"
                        required
                        value={shipNameInput}
                        onChange={(e) => handleShipNameChange(e.target.value)}
                        onFocus={() => {
                          updateShipNameSuggestions(shipNameInput);
                        }}
                        onBlur={() => setTimeout(() => setShowShipNameDropdown(false), 200)}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                        placeholder="Enter or select vessel/ship name"
                      />
                      
                      {/* Autocomplete Dropdown */}
                      {showShipNameDropdown && filteredShipNames.length > 0 && (
                        <div className="absolute z-50 w-full mt-1 bg-white border border-gray-300 rounded-lg shadow-lg max-h-60 overflow-y-auto">
                          {filteredShipNames.map((name, index) => (
                            <div
                              key={index}
                              onClick={() => selectShipName(name)}
                              className="px-4 py-2 hover:bg-amber-50 cursor-pointer text-sm border-b border-gray-100 last:border-b-0"
                            >
                              🚢 {name}
                            </div>
                          ))}
                        </div>
                      )}
                    </div>

                    <div className="md:col-span-2">
                      <label className="block text-sm font-medium text-gray-700 mb-1">📍 Location *</label>
                      <input
                        type="text"
                        required
                        value={ticketForm.location}
                        onChange={(e) => setTicketForm({ ...ticketForm, location: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                        placeholder="Port, coordinates, or specific location"
                      />
                    </div>
                    
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Product Name</label>
                      <SearchableSelect
                        options={items.map(i => ({ value: i.id, label: i.code, subtitle: i.name }))}
                        value={ticketForm.product_id}
                        onChange={(value) => {
                          const selectedItem = items.find(i => i.id === value);
                          setTicketForm({ 
                            ...ticketForm, 
                            product_id: value,
                            product_name: selectedItem?.name || '' 
                          });
                          fetchAvailableUIDs(value);
                        }}
                        placeholder="Select Product"
                      />
                    </div>
                    <div className="col-span-2">
                      <label className="block text-sm font-medium text-gray-700 mb-1">Search by Product / Part No / UID</label>
                      <div className="relative">
                        <input
                          type="text"
                          value={productLookupInput}
                          onChange={(e) => {
                            setProductLookupInput(e.target.value);
                            setShowProductLookupDropdown(true);
                          }}
                          onFocus={() => {
                            if (productLookupResults.length > 0) setShowProductLookupDropdown(true);
                          }}
                          onBlur={() => setTimeout(() => setShowProductLookupDropdown(false), 200)}
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                          placeholder="Type product name, part number, or UID"
                        />

                        {showProductLookupDropdown && (
                          <div className="absolute z-50 w-full mt-1 bg-white border border-gray-300 rounded-lg shadow-lg max-h-60 overflow-y-auto">
                            {productLookupLoading ? (
                              <div className="px-4 py-2 text-sm text-gray-500">Searching...</div>
                            ) : productLookupResults.length === 0 ? (
                              <div className="px-4 py-2 text-sm text-gray-500">No matches found</div>
                            ) : (
                              productLookupResults.map((d) => (
                                <div
                                  key={d.uid_id}
                                  onClick={() => selectDeployment(d)}
                                  className="px-4 py-2 hover:bg-amber-50 cursor-pointer text-sm border-b border-gray-100 last:border-b-0"
                                >
                                  <div className="font-medium">
                                    {d.item_name || 'Unknown Product'}
                                    {d.item_code ? <span className="text-gray-500"> ({d.item_code})</span> : null}
                                  </div>
                                  <div className="text-xs text-gray-600 mt-0.5">
                                    <span className="font-mono">UID: {d.uid}</span>
                                    {d.client_part_number ? <span className="ml-2">Part: {d.client_part_number}</span> : null}
                                  </div>
                                </div>
                              ))
                            )}
                          </div>
                        )}
                      </div>
                      <p className="text-xs text-gray-500 mt-1">Use this when the customer shares a part number</p>
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">UID</label>
                      <input
                        type="text"
                        value={selectedDeployment?.uid || ticketForm.uid}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg bg-gray-50 font-mono"
                        placeholder="Select from search above"
                        disabled
                      />
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Part Number</label>
                      <input
                        type="text"
                        value={selectedDeployment?.client_part_number || ''}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg bg-gray-50"
                        placeholder="Select from search above"
                        disabled
                      />
                      {selectedDeployment?.warranty_expiry_date ? (
                        <p className="text-xs text-gray-600 mt-1">
                          {getWarrantyStatusText(selectedDeployment.warranty_expiry_date)}
                        </p>
                      ) : selectedDeployment ? (
                        <p className="text-xs text-gray-500 mt-1">Warranty status not available</p>
                      ) : null}
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Model Number</label>
                      <input
                        type="text"
                        value={ticketForm.model_number}
                        onChange={(e) => setTicketForm({ ...ticketForm, model_number: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Reported By *</label>
                      <input
                        type="text"
                        required
                        value={ticketForm.reported_by}
                        onChange={(e) => setTicketForm({ ...ticketForm, reported_by: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Contact Number *</label>
                      <input
                        type="text"
                        required
                        value={ticketForm.contact_number}
                        onChange={(e) => setTicketForm({ ...ticketForm, contact_number: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
                      <input
                        type="email"
                        value={ticketForm.email}
                        onChange={(e) => setTicketForm({ ...ticketForm, email: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Priority</label>
                      <select
                        value={ticketForm.priority}
                        onChange={(e) => setTicketForm({ ...ticketForm, priority: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      >
                        <option value="LOW">Low</option>
                        <option value="MEDIUM">Medium</option>
                        <option value="HIGH">High</option>
                        <option value="CRITICAL">Critical</option>
                      </select>
                    </div>
                    <div className="col-span-2">
                      <label className="block text-sm font-medium text-gray-700 mb-1">Service Location</label>
                      <textarea
                        value={ticketForm.service_location}
                        onChange={(e) => setTicketForm({ ...ticketForm, service_location: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                        rows={2}
                      />
                    </div>
                    <div className="col-span-2 md:col-span-2">
                      <label className="block text-sm font-medium text-gray-700 mb-1">Complaint Description *</label>
                      <textarea
                        required
                        value={ticketForm.complaint_description}
                        onChange={(e) => setTicketForm({ ...ticketForm, complaint_description: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                        rows={3}
                        placeholder="Describe the issue in detail"
                      />
                    </div>

                    {/* FILE UPLOAD SECTION */}
                    <div className="col-span-2 md:col-span-2">
                      <label className="block text-sm font-medium text-gray-700 mb-1">📸 Photos & Videos</label>
                      <div className="mt-1 flex justify-center px-6 pt-5 pb-6 border-2 border-gray-300 border-dashed rounded-lg hover:border-amber-400 transition">
                        <div className="space-y-1 text-center">
                          <svg className="mx-auto h-12 w-12 text-gray-400" stroke="currentColor" fill="none" viewBox="0 0 48 48">
                            <path d="M28 8H12a4 4 0 00-4 4v20m32-12v8m0 0v8a4 4 0 01-4 4H12a4 4 0 01-4-4v-4m32-4l-3.172-3.172a4 4 0 00-5.656 0L28 28M8 32l9.172-9.172a4 4 0 015.656 0L28 28m0 0l4 4m4-24h8m-4-4v8m-12 4h.02" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" />
                          </svg>
                          <div className="flex text-sm text-gray-600">
                            <label className="relative cursor-pointer bg-white rounded-md font-medium text-amber-600 hover:text-amber-500 focus-within:outline-none">
                              <span>Upload files</span>
                              <input
                                type="file"
                                multiple
                                accept="image/*,video/*"
                                onChange={handleFileUpload}
                                className="sr-only"
                              />
                            </label>
                            <p className="pl-1">or drag and drop</p>
                          </div>
                          <p className="text-xs text-gray-500">Photos or videos up to 50MB each</p>
                        </div>
                      </div>
                      
                      {/* File Previews */}
                      {uploadedFiles.length > 0 && (
                        <div className="mt-4 grid grid-cols-2 md:grid-cols-4 gap-4">
                          {uploadPreviews.map((preview, index) => (
                            <div key={index} className="relative group">
                              {uploadedFiles[index].type.startsWith('image/') ? (
                                <img src={preview} alt={`Preview ${index + 1}`} className="w-full h-24 object-cover rounded-lg" />
                              ) : (
                                <video src={preview} className="w-full h-24 object-cover rounded-lg" />
                              )}
                              <button
                                type="button"
                                onClick={() => removeFile(index)}
                                className="absolute top-1 right-1 bg-red-500 text-white rounded-full p-1 opacity-0 group-hover:opacity-100 transition"
                              >
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                                </svg>
                              </button>
                              <p className="text-xs text-gray-600 mt-1 truncate">{uploadedFiles[index].name}</p>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  </div>
                  <div className="mt-6 flex justify-end space-x-3">
                    <button
                      type="button"
                      onClick={() => setShowTicketForm(false)}
                      className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50"
                    >
                      Cancel
                    </button>
                    <button
                      type="submit"
                      disabled={loading}
                      className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50"
                    >
                      {loading ? 'Creating...' : 'Create Ticket'}
                    </button>
                  </div>
                </form>
              </div>
            </div>
          )}

          {/* Ticket Details Modal */}
          {showTicketDetails && selectedTicket && (
            <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
              <div className="bg-white rounded-lg p-6 max-w-3xl w-full max-h-[90vh] overflow-y-auto">
                <div className="flex justify-between items-center mb-4">
                  <h3 className="text-lg font-semibold">Ticket Details - {selectedTicket.ticket_number}</h3>
                  <button onClick={() => setShowTicketDetails(false)} className="text-gray-500 hover:text-gray-700">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                  </button>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div><label className="block text-sm font-medium text-gray-600">Customer</label><p className="mt-1 text-sm text-gray-900">{selectedTicket.customer?.customer_name || '-'}</p></div>
                  <div><label className="block text-sm font-medium text-gray-600">Status</label><span className={`mt-1 inline-block px-2 py-1 text-xs font-semibold rounded-full ${getStatusColor(selectedTicket.status)}`}>{selectedTicket.status}</span></div>
                  <div><label className="block text-sm font-medium text-gray-600">Priority</label><span className={`mt-1 inline-block px-2 py-1 text-xs font-semibold rounded-full ${getPriorityColor(selectedTicket.priority)}`}>{selectedTicket.priority}</span></div>
                  <div><label className="block text-sm font-medium text-gray-600">Service Type</label><p className="mt-1 text-sm text-gray-900">{selectedTicket.service_type}</p></div>
                  <div><label className="block text-sm font-medium text-gray-600">Product</label><p className="mt-1 text-sm text-gray-900">{selectedTicket.product_name || '-'}</p></div>
                  <div><label className="block text-sm font-medium text-gray-600">UID</label><p className="mt-1 text-sm font-mono text-gray-900">{selectedTicket.uid || '-'}</p></div>
                  <div><label className="block text-sm font-medium text-gray-600">Reported By</label><p className="mt-1 text-sm text-gray-900">{selectedTicket.reported_by || '-'}</p></div>
                  <div><label className="block text-sm font-medium text-gray-600">Contact</label><p className="mt-1 text-sm text-gray-900">{selectedTicket.contact_number || '-'}</p></div>
                  <div><label className="block text-sm font-medium text-gray-600">Complaint Date</label><p className="mt-1 text-sm text-gray-900">{new Date(selectedTicket.complaint_date).toLocaleDateString()}</p></div>
                  <div><span className="font-medium">Warranty:</span> {selectedTicket.is_under_warranty ? <span className="text-green-600">✓ Valid</span> : <span className="text-gray-600">Not Under Warranty</span>}</div>
                  <div className="col-span-2"><span className="font-medium">Complaint Description:</span> <p className="mt-1 text-sm text-gray-900 bg-gray-50 p-3 rounded">{selectedTicket.complaint_description}</p></div>
                </div>

                {/* Attachments */}
                {Array.isArray(selectedTicket.attachments) && selectedTicket.attachments.length > 0 && (
                  <div className="mt-6">
                    <div className="text-sm font-medium text-gray-700 mb-2">Attachments</div>
                    <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                      {selectedTicket.attachments.map((url, idx) => {
                        const kind = getAttachmentKind(url);
                        return (
                          <a
                            key={`${url}-${idx}`}
                            href={url}
                            target="_blank"
                            rel="noreferrer"
                            className="block border border-gray-200 rounded-lg overflow-hidden hover:border-amber-400 transition"
                            title="Open in new tab"
                          >
                            {kind === 'video' ? (
                              <video src={url} className="w-full h-32 object-cover bg-black" controls />
                            ) : kind === 'image' ? (
                              <img src={url} alt={`Attachment ${idx + 1}`} className="w-full h-32 object-cover" />
                            ) : (
                              <div className="w-full h-32 flex items-center justify-center text-sm text-gray-600 bg-gray-50">
                                Open Attachment
                              </div>
                            )}
                          </a>
                        );
                      })}
                    </div>
                  </div>
                )}

                <div className="mt-6 flex justify-end space-x-3">
                  <button
                    onClick={() => {
                      setEditTicketForm({
                        priority: selectedTicket.priority || 'MEDIUM',
                        expected_completion_date: (selectedTicket as any).expected_completion_date || '',
                        ship_name: selectedTicket.ship_name || '',
                        location: selectedTicket.location || '',
                        service_location: (selectedTicket as any).service_location || '',
                        product_name: selectedTicket.product_name || '',
                        model_number: (selectedTicket as any).model_number || '',
                        reported_by: selectedTicket.reported_by || '',
                        contact_number: selectedTicket.contact_number || '',
                        email: selectedTicket.email || '',
                        complaint_description: selectedTicket.complaint_description || '',
                      });
                      setShowEditTicketModal(true);
                    }}
                    className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700"
                  >
                    Edit
                  </button>
                  <button onClick={() => setShowTicketDetails(false)} className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50">Close</button>
                </div>
              </div>
            </div>
          )}

          {/* Edit Ticket Modal */}
          {showEditTicketModal && selectedTicket && (
            <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
              <div className="bg-white rounded-lg p-6 max-w-2xl w-full mx-4 max-h-[90vh] overflow-y-auto">
                <h3 className="text-lg font-semibold mb-4">Edit Ticket - {selectedTicket.ticket_number}</h3>

                {/* Existing attachments (read-only) */}
                {Array.isArray(selectedTicket.attachments) && selectedTicket.attachments.length > 0 && (
                  <div className="mb-4">
                    <div className="text-sm font-medium text-gray-700 mb-2">Existing Attachments</div>
                    <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                      {selectedTicket.attachments.map((url, idx) => {
                        const kind = getAttachmentKind(url);
                        return (
                          <a
                            key={`${url}-${idx}`}
                            href={url}
                            target="_blank"
                            rel="noreferrer"
                            className="block border border-gray-200 rounded-lg overflow-hidden hover:border-amber-400 transition"
                            title="Open in new tab"
                          >
                            {kind === 'video' ? (
                              <video src={url} className="w-full h-28 object-cover bg-black" controls />
                            ) : kind === 'image' ? (
                              <img src={url} alt={`Attachment ${idx + 1}`} className="w-full h-28 object-cover" />
                            ) : (
                              <div className="w-full h-28 flex items-center justify-center text-sm text-gray-600 bg-gray-50">
                                Open Attachment
                              </div>
                            )}
                          </a>
                        );
                      })}
                    </div>
                  </div>
                )}

                <form
                  onSubmit={async (e) => {
                    e.preventDefault();
                    setLoading(true);
                    setError(null);
                    try {
                      const payload = {
                        ...editTicketForm,
                        expected_completion_date:
                          editTicketForm.expected_completion_date || null,
                      };

                      const updated = await apiClient.put<ServiceTicket>(
                        `/service/tickets/${selectedTicket.id}`,
                        payload,
                      );

                      setSelectedTicket(updated);
                      setShowEditTicketModal(false);
                      fetchTickets();
                    } catch (err: any) {
                      setError(err.message || 'Failed to update ticket');
                    } finally {
                      setLoading(false);
                    }
                  }}
                  className="space-y-4"
                >
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Priority</label>
                      <select
                        value={editTicketForm.priority}
                        onChange={(e) =>
                          setEditTicketForm({
                            ...editTicketForm,
                            priority: e.target.value,
                          })
                        }
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      >
                        <option value="LOW">Low</option>
                        <option value="MEDIUM">Medium</option>
                        <option value="HIGH">High</option>
                        <option value="CRITICAL">Critical</option>
                      </select>
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Expected Completion Date</label>
                      <input
                        type="date"
                        value={editTicketForm.expected_completion_date}
                        onChange={(e) =>
                          setEditTicketForm({
                            ...editTicketForm,
                            expected_completion_date: e.target.value,
                          })
                        }
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Ship Name</label>
                      <input
                        type="text"
                        value={editTicketForm.ship_name}
                        onChange={(e) =>
                          setEditTicketForm({
                            ...editTicketForm,
                            ship_name: e.target.value,
                          })
                        }
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Location</label>
                      <input
                        type="text"
                        value={editTicketForm.location}
                        onChange={(e) =>
                          setEditTicketForm({
                            ...editTicketForm,
                            location: e.target.value,
                          })
                        }
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Service Location</label>
                      <input
                        type="text"
                        value={editTicketForm.service_location}
                        onChange={(e) =>
                          setEditTicketForm({
                            ...editTicketForm,
                            service_location: e.target.value,
                          })
                        }
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Product Name</label>
                      <input
                        type="text"
                        value={editTicketForm.product_name}
                        onChange={(e) =>
                          setEditTicketForm({
                            ...editTicketForm,
                            product_name: e.target.value,
                          })
                        }
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Model Number</label>
                      <input
                        type="text"
                        value={editTicketForm.model_number}
                        onChange={(e) =>
                          setEditTicketForm({
                            ...editTicketForm,
                            model_number: e.target.value,
                          })
                        }
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Reported By</label>
                      <input
                        type="text"
                        value={editTicketForm.reported_by}
                        onChange={(e) =>
                          setEditTicketForm({
                            ...editTicketForm,
                            reported_by: e.target.value,
                          })
                        }
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Contact Number</label>
                      <input
                        type="text"
                        value={editTicketForm.contact_number}
                        onChange={(e) =>
                          setEditTicketForm({
                            ...editTicketForm,
                            contact_number: e.target.value,
                          })
                        }
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>

                    <div className="md:col-span-2">
                      <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
                      <input
                        type="email"
                        value={editTicketForm.email}
                        onChange={(e) =>
                          setEditTicketForm({
                            ...editTicketForm,
                            email: e.target.value,
                          })
                        }
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>

                    <div className="md:col-span-2">
                      <label className="block text-sm font-medium text-gray-700 mb-1">Complaint Description</label>
                      <textarea
                        value={editTicketForm.complaint_description}
                        onChange={(e) =>
                          setEditTicketForm({
                            ...editTicketForm,
                            complaint_description: e.target.value,
                          })
                        }
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                        rows={4}
                      />
                    </div>
                  </div>

                  <div className="flex justify-end space-x-3">
                    <button
                      type="button"
                      onClick={() => setShowEditTicketModal(false)}
                      className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50"
                    >
                      Cancel
                    </button>
                    <button
                      type="submit"
                      disabled={loading}
                      className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50"
                    >
                      {loading ? 'Updating...' : 'Update Ticket'}
                    </button>
                  </div>
                </form>
              </div>
            </div>
          )}

          {/* Update Status Modal */}
          {showStatusModal && selectedTicket && (
            <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
              <div className="bg-white rounded-lg p-6 max-w-md w-full">
                <h3 className="text-lg font-semibold mb-4">Update Ticket Status</h3>
                <div className="mb-4">
                  <label className="block text-sm font-medium text-gray-700 mb-2">Current: <span className={`ml-2 px-2 py-1 text-xs font-semibold rounded-full ${getStatusColor(selectedTicket.status)}`}>{selectedTicket.status}</span></label>
                  <select className="w-full px-3 py-2 border border-gray-300 rounded-lg" defaultValue={selectedTicket.status} onChange={async (e) => { try { await apiClient.put(`/service/tickets/${selectedTicket.id}`, { status: e.target.value }); setShowStatusModal(false); setSelectedTicket(null); fetchTickets(); } catch (err: any) { setError(err.message); } }}>
                    <option value="OPEN">Open</option>
                    <option value="ASSIGNED">Assigned</option>
                    <option value="IN_PROGRESS">In Progress</option>
                    <option value="PARTS_PENDING">Parts Pending</option>
                    <option value="COMPLETED">Completed</option>
                    <option value="CLOSED">Closed</option>
                    <option value="CANCELLED">Cancelled</option>
                  </select>
                </div>
                <div className="flex justify-end">
                  <button onClick={() => { setShowStatusModal(false); setSelectedTicket(null); }} className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50">Cancel</button>
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Technicians Tab */}
      {activeTab === 'technicians' && (
        <div>
          <div className="mb-4 flex justify-between items-center">
            <h2 className="text-lg font-semibold">Technicians</h2>
            <button
              onClick={() => setShowTechnicianForm(true)}
              className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700"
            >
              + Add Technician
            </button>
          </div>

          {loading ? (
            <p className="text-gray-600">Loading technicians...</p>
          ) : (
            <div className="bg-white rounded-lg shadow overflow-hidden">
              <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Code</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Name</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Specialization</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Contact</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Assignments</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Completed</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Rating</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Actions</th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {technicians.map((tech) => (
                    <tr key={tech.id}>
                      <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                        {tech.technician_code}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">{tech.technician_name}</td>
                      <td className="px-6 py-4 text-sm text-gray-600">{tech.specialization || '-'}</td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">
                        {tech.contact_number || '-'}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {tech.total_assignments}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {tech.completed_services}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {tech.average_rating > 0 ? tech.average_rating.toFixed(1) : '-'}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className={`px-2 py-1 text-xs font-semibold rounded-full ${tech.is_active ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'}`}>
                          {tech.is_active ? 'Active' : 'Inactive'}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm">
                        <div className="flex space-x-2">
                          <button onClick={() => { setSelectedTechnician(tech); setShowTechnicianDetails(true); }} className="text-blue-600 hover:text-blue-800" title="View Details">
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
                          </button>
                          <button onClick={() => { setSelectedTechnician(tech); setTechnicianForm({ technician_name: tech.technician_name, specialization: tech.specialization || '', contact_number: tech.contact_number || '', email: tech.email || '', is_active: tech.is_active }); setShowEditTechnicianModal(true); }} className="text-amber-600 hover:text-amber-800" title="Edit">
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                          </button>
                          <button onClick={async () => { if (confirm(`Delete ${tech.technician_name}?`)) { try { await apiClient.delete(`/service/technicians/${tech.id}`); fetchTechnicians(); } catch (err: any) { setError(err.message); } } }} className="text-red-600 hover:text-red-800" title="Delete">
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Technician Form Modal */}
          {showTechnicianForm && (
            <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
              <div className="bg-white rounded-lg p-6 max-w-lg w-full">
                <h3 className="text-lg font-semibold mb-4">Add Technician</h3>
                <form onSubmit={handleCreateTechnician}>
                  <div className="space-y-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Name *</label>
                      <input
                        type="text"
                        required
                        value={technicianForm.technician_name}
                        onChange={(e) => setTechnicianForm({ ...technicianForm, technician_name: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Specialization</label>
                      <input
                        type="text"
                        value={technicianForm.specialization}
                        onChange={(e) => setTechnicianForm({ ...technicianForm, specialization: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Contact Number</label>
                      <input
                        type="text"
                        value={technicianForm.contact_number}
                        onChange={(e) => setTechnicianForm({ ...technicianForm, contact_number: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
                      <input
                        type="email"
                        value={technicianForm.email}
                        onChange={(e) => setTechnicianForm({ ...technicianForm, email: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                      />
                    </div>
                  </div>
                  <div className="mt-6 flex justify-end space-x-3">
                    <button
                      type="button"
                      onClick={() => setShowTechnicianForm(false)}
                      className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50"
                    >
                      Cancel
                    </button>
                    <button
                      type="submit"
                      disabled={loading}
                      className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50"
                    >
                      {loading ? 'Adding...' : 'Add Technician'}
                    </button>
                  </div>
                </form>
              </div>
            </div>
          )}

          {/* Technician Details Modal */}
          {showTechnicianDetails && selectedTechnician && (
            <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
              <div className="bg-white rounded-lg p-6 max-w-2xl w-full mx-4 max-h-[90vh] overflow-y-auto">
                <h3 className="text-lg font-semibold mb-4">Technician Details</h3>
                <div className="space-y-3 text-sm">
                  <div className="grid grid-cols-2 gap-4">
                    <div><span className="font-medium">Code:</span> {selectedTechnician.technician_code}</div>
                    <div><span className="font-medium">Name:</span> {selectedTechnician.technician_name}</div>
                    <div><span className="font-medium">Specialization:</span> {selectedTechnician.specialization || 'N/A'}</div>
                    <div><span className="font-medium">Contact:</span> {selectedTechnician.contact_number || 'N/A'}</div>
                    <div><span className="font-medium">Email:</span> {selectedTechnician.email || 'N/A'}</div>
                    <div><span className="font-medium">Status:</span> <span className={`px-2 py-1 text-xs font-semibold rounded-full ${selectedTechnician.is_active ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'}`}>{selectedTechnician.is_active ? 'Active' : 'Inactive'}</span></div>
                    <div><span className="font-medium">Total Assignments:</span> {selectedTechnician.total_assignments || 0}</div>
                    <div><span className="font-medium">Completed Jobs:</span> {selectedTechnician.completed_jobs || 0}</div>
                    <div><span className="font-medium">Average Rating:</span> {selectedTechnician.average_rating ? `${selectedTechnician.average_rating.toFixed(1)} ⭐` : 'N/A'}</div>
                    <div><span className="font-medium">Join Date:</span> {selectedTechnician.created_at ? new Date(selectedTechnician.created_at).toLocaleDateString() : 'N/A'}</div>
                  </div>
                </div>
                <div className="mt-6 flex justify-end"><button onClick={() => setShowTechnicianDetails(false)} className="px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700">Close</button></div>
              </div>
            </div>
          )}

          {/* Edit Technician Modal */}
          {showEditTechnicianModal && selectedTechnician && (
            <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
              <div className="bg-white rounded-lg p-6 max-w-2xl w-full mx-4">
                <h3 className="text-lg font-semibold mb-4">Edit Technician</h3>
                <form onSubmit={async (e) => { e.preventDefault(); setLoading(true); setError(''); try { await apiClient.put(`/service/technicians/${selectedTechnician.id}`, technicianForm); setShowEditTechnicianModal(false); setTechnicianForm({ technician_name: '', specialization: '', contact_number: '', email: '', is_active: true }); fetchTechnicians(); } catch (err: any) { setError(err.message); } finally { setLoading(false); } }} className="space-y-4">
                  <div><label className="block text-sm font-medium text-gray-700 mb-1">Technician Name *</label><input type="text" value={technicianForm.technician_name} onChange={(e) => setTechnicianForm({ ...technicianForm, technician_name: e.target.value })} className="w-full px-3 py-2 border border-gray-300 rounded-lg" required /></div>
                  <div><label className="block text-sm font-medium text-gray-700 mb-1">Specialization</label><input type="text" value={technicianForm.specialization} onChange={(e) => setTechnicianForm({ ...technicianForm, specialization: e.target.value })} className="w-full px-3 py-2 border border-gray-300 rounded-lg" /></div>
                  <div><label className="block text-sm font-medium text-gray-700 mb-1">Contact Number</label><input type="text" value={technicianForm.contact_number} onChange={(e) => setTechnicianForm({ ...technicianForm, contact_number: e.target.value })} className="w-full px-3 py-2 border border-gray-300 rounded-lg" /></div>
                  <div><label className="block text-sm font-medium text-gray-700 mb-1">Email</label><input type="email" value={technicianForm.email} onChange={(e) => setTechnicianForm({ ...technicianForm, email: e.target.value })} className="w-full px-3 py-2 border border-gray-300 rounded-lg" /></div>
                  <div><label className="flex items-center"><input type="checkbox" checked={technicianForm.is_active} onChange={(e) => setTechnicianForm({ ...technicianForm, is_active: e.target.checked })} className="mr-2" /><span className="text-sm font-medium text-gray-700">Active</span></label></div>
                  <div className="flex justify-end space-x-3"><button type="button" onClick={() => { setShowEditTechnicianModal(false); setTechnicianForm({ technician_name: '', specialization: '', contact_number: '', email: '', is_active: true }); }} className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50">Cancel</button><button type="submit" disabled={loading} className="px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50">{loading ? 'Updating...' : 'Update Technician'}</button></div>
                </form>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Warranty Check Tab */}
      {activeTab === 'warranty-check' && (
        <div>
          <h2 className="text-lg font-semibold mb-4">Warranty Validation</h2>
          <div className="bg-white rounded-lg shadow p-6 max-w-2xl">
            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-2">Enter Product UID</label>
              <div className="flex space-x-3">
                <input
                  type="text"
                  value={warrantyUID}
                  onChange={(e) => setWarrantyUID(e.target.value)}
                  placeholder="Enter UID to check warranty status"
                  className="flex-1 px-4 py-2 border border-gray-300 rounded-lg"
                />
                <button
                  onClick={handleWarrantyCheck}
                  disabled={loading}
                  className="px-6 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50"
                >
                  {loading ? 'Checking...' : 'Check Warranty'}
                </button>
              </div>
            </div>

            {warrantyResult && (
              <div className={`mt-6 p-4 rounded-lg border-2 ${
                warrantyResult.is_valid ? 'bg-green-50 border-green-500' : 'bg-red-50 border-red-500'
              }`}>
                <div className="flex items-center mb-3">
                  <div className={`text-2xl mr-3 ${warrantyResult.is_valid ? 'text-green-600' : 'text-red-600'}`}>
                    {warrantyResult.is_valid ? '✓' : '✗'}
                  </div>
                  <div>
                    <h3 className={`text-lg font-semibold ${
                      warrantyResult.is_valid ? 'text-green-900' : 'text-red-900'
                    }`}>
                      {warrantyResult.is_valid ? 'Warranty Valid' : 'Warranty Invalid/Expired'}
                    </h3>
                    <p className={`text-sm ${warrantyResult.is_valid ? 'text-green-700' : 'text-red-700'}`}>
                      {warrantyResult.message}
                    </p>
                  </div>
                </div>

                {warrantyResult.warranty && (
                  <div className="mt-4 space-y-2 text-sm">
                    <div className="flex justify-between">
                      <span className="text-gray-600">Warranty Number:</span>
                      <span className="font-medium">{warrantyResult.warranty.warranty_number}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-600">Start Date:</span>
                      <span className="font-medium">
                        {new Date(warrantyResult.warranty.warranty_start_date).toLocaleDateString()}
                      </span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-600">End Date:</span>
                      <span className="font-medium">
                        {new Date(warrantyResult.warranty.warranty_end_date).toLocaleDateString()}
                      </span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-600">Duration:</span>
                      <span className="font-medium">{warrantyResult.warranty.warranty_duration_months} months</span>
                    </div>
                    {warrantyResult.is_valid && warrantyResult.days_remaining && (
                      <div className="flex justify-between">
                        <span className="text-gray-600">Days Remaining:</span>
                        <span className="font-medium text-green-600">{warrantyResult.days_remaining} days</span>
                      </div>
                    )}
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      )}

      {/* Reports Tab */}
      {activeTab === 'reports' && (
        <div>
          <h2 className="text-lg font-semibold mb-4">Service Reports</h2>
          {loading ? (
            <p className="text-gray-600">Loading reports...</p>
          ) : reports ? (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="bg-white rounded-lg shadow p-6">
                <h3 className="text-sm font-medium text-gray-600 mb-2">Ticket Status</h3>
                <div className="space-y-2">
                  <div className="flex justify-between">
                    <span className="text-yellow-600">Open Tickets:</span>
                    <span className="font-bold text-yellow-600">{reports.open_tickets}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-green-600">Closed Tickets:</span>
                    <span className="font-bold text-green-600">{reports.closed_tickets}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-600">Total:</span>
                    <span className="font-bold">{reports.total_tickets}</span>
                  </div>
                </div>
              </div>

              <div className="bg-white rounded-lg shadow p-6">
                <h3 className="text-sm font-medium text-gray-600 mb-2">Warranty Claims</h3>
                <div className="space-y-2">
                  <div className="flex justify-between">
                    <span>Claims Count:</span>
                    <span className="font-bold">{reports.warranty_claims_count}</span>
                  </div>
                  <div className="flex justify-between">
                    <span>Total Cost:</span>
                    <span className="font-bold">₹{reports.warranty_claims_cost?.toLocaleString() || 0}</span>
                  </div>
                  <div className="flex justify-between">
                    <span>Parts Cost:</span>
                    <span className="font-bold">₹{reports.warranty_parts_cost?.toLocaleString() || 0}</span>
                  </div>
                </div>
              </div>

              <div className="bg-white rounded-lg shadow p-6">
                <h3 className="text-sm font-medium text-gray-600 mb-2">Top Issues</h3>
                <div className="space-y-2">
                  {reports.product_reliability?.slice(0, 5).map((item: any, index: number) => (
                    <div key={index} className="flex justify-between text-sm">
                      <span className="truncate">{item.product}</span>
                      <span className="font-medium text-red-600">{item.issue_count}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          ) : null}
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Building2, Save } from 'lucide-react';
import { apiClient } from '../../../../../lib/api-client';

interface Company {
  id: string;
  name: string;
  domain: string;
  address?: string;
  phone?: string;
  email?: string;
  tax_id?: string;
  logo_url?: string;
}

export default function CompanySettings() {
  const [company, setCompany] = useState<Company | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState('');

  useEffect(() => {
    fetchCompany();
  }, []);

  const fetchCompany = async () => {
    try {
      setLoading(true);
      const data = await apiClient.get<Company>('/tenant/current');
      setCompany(data);
    } catch (error) {
      console.error('Failed to fetch company:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!company) return;

    setSaving(true);
    setMessage('');

    try {
      await apiClient.put('/tenant/current', company);
      setMessage('Company settings saved successfully!');
      setTimeout(() => setMessage(''), 3000);
    } catch (error: any) {
      setMessage(error.message || 'Failed to save company settings');
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="text-center py-12" style={{ color: '#8B6F47' }}>
        Loading company settings...
      </div>
    );
  }

  if (!company) {
    return (
      <div className="text-center py-12" style={{ color: '#8B6F47' }}>
        Company information not found
      </div>
    );
  }

  return (
    <div className="max-w-3xl">
      <div className="bg-white rounded-lg border-2 p-6" style={{ borderColor: '#E8DCC4' }}>
        <div className="flex items-center gap-3 mb-6">
          <div className="p-3 rounded-lg" style={{ backgroundColor: '#E8DCC4' }}>
            <Building2 className="w-6 h-6" style={{ color: '#8B6F47' }} />
          </div>
          <div>
            <h2 className="text-xl font-semibold" style={{ color: '#6F4E37' }}>
              Company Information
            </h2>
            <p className="text-sm" style={{ color: '#8B6F47' }}>
              Update your company details and settings
            </p>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
                Company Name
              </label>
              <input
                type="text"
                required
                value={company.name}
                onChange={(e) => setCompany({ ...company, name: e.target.value })}
                className="w-full px-4 py-2 rounded-lg border-2 focus:outline-none focus:border-opacity-80"
                style={{ borderColor: '#E8DCC4', color: '#6F4E37' }}
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
                Domain
              </label>
              <input
                type="text"
                required
                value={company.domain}
                onChange={(e) => setCompany({ ...company, domain: e.target.value })}
                className="w-full px-4 py-2 rounded-lg border-2 focus:outline-none focus:border-opacity-80"
                style={{ borderColor: '#E8DCC4', color: '#6F4E37' }}
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
              Address
            </label>
            <textarea
              rows={3}
              value={company.address || ''}
              onChange={(e) => setCompany({ ...company, address: e.target.value })}
              className="w-full px-4 py-2 rounded-lg border-2 focus:outline-none focus:border-opacity-80"
              style={{ borderColor: '#E8DCC4', color: '#6F4E37' }}
              placeholder="Company address..."
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
                Phone
              </label>
              <input
                type="tel"
                value={company.phone || ''}
                onChange={(e) => setCompany({ ...company, phone: e.target.value })}
                className="w-full px-4 py-2 rounded-lg border-2 focus:outline-none focus:border-opacity-80"
                style={{ borderColor: '#E8DCC4', color: '#6F4E37' }}
                placeholder="+1 234 567 8900"
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
                Email
              </label>
              <input
                type="email"
                value={company.email || ''}
                onChange={(e) => setCompany({ ...company, email: e.target.value })}
                className="w-full px-4 py-2 rounded-lg border-2 focus:outline-none focus:border-opacity-80"
                style={{ borderColor: '#E8DCC4', color: '#6F4E37' }}
                placeholder="contact@company.com"
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
              Tax ID / Registration Number
            </label>
            <input
              type="text"
              value={company.tax_id || ''}
              onChange={(e) => setCompany({ ...company, tax_id: e.target.value })}
              className="w-full px-4 py-2 rounded-lg border-2 focus:outline-none focus:border-opacity-80"
              style={{ borderColor: '#E8DCC4', color: '#6F4E37' }}
              placeholder="Tax identification number"
            />
          </div>

          {message && (
            <div
              className={`p-3 rounded-lg text-sm ${
                message.includes('success') ? 'bg-green-50 text-green-600' : 'bg-red-50 text-red-600'
              }`}
            >
              {message}
            </div>
          )}

          <div className="flex justify-end pt-4">
            <button
              type="submit"
              disabled={saving}
              className="flex items-center gap-2 px-6 py-2 rounded-lg text-white font-semibold hover:opacity-90 transition-opacity disabled:opacity-50"
              style={{ backgroundColor: '#8B6F47' }}
            >
              <Save className="w-5 h-5" />
              <span>{saving ? 'Saving...' : 'Save Changes'}</span>
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Mail, Save, RefreshCw } from 'lucide-react';
import { apiClient } from '../../../../../lib/api-client';

interface EmailConfig {
  id?: number;
  email_type: string;
  email_address: string;
  display_name?: string;
  description?: string;
  is_active?: boolean;
}

const emailTypeLabels: Record<string, { name: string; description: string; icon: string }> = {
  admin: {
    name: 'System Administrator',
    description: 'System notifications, critical alerts, and administrative messages',
    icon: '🔧',
  },
  sales: {
    name: 'Sales Department',
    description: 'Quotations, sales orders, and customer communications',
    icon: '💼',
  },
  support: {
    name: 'Customer Support',
    description: 'Customer support requests, service tickets, and inquiries',
    icon: '💬',
  },
  technical: {
    name: 'Technical Team',
    description: 'Technical inquiries, engineering questions, and product specifications',
    icon: '⚙️',
  },
  purchase: {
    name: 'Purchase Department',
    description: 'Purchase orders, vendor communications, and procurement',
    icon: '🛒',
  },
  hr: {
    name: 'Human Resources',
    description: 'Employee matters, payroll, leaves, and HR communications',
    icon: '👥',
  },
  noreply: {
    name: 'No Reply',
    description: 'Automated system notifications (do not reply)',
    icon: '🔔',
  },
};

export default function EmailSettings() {
  const [emailConfigs, setEmailConfigs] = useState<EmailConfig[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState('');

  useEffect(() => {
    fetchEmailConfig();
  }, []);

  const fetchEmailConfig = async () => {
    try {
      setLoading(true);
      const data = await apiClient.get<EmailConfig[]>('/emails/config');
      setEmailConfigs(data);
    } catch (error) {
      console.error('Failed to fetch email config:', error);
      setMessage('Failed to load email configuration');
    } finally {
      setLoading(false);
    }
  };

  const handleEmailChange = (emailType: string, newEmail: string) => {
    setEmailConfigs(
      emailConfigs.map((config) =>
        config.email_type === emailType
          ? { ...config, email_address: newEmail }
          : config
      )
    );
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    setMessage('');

    try {
      const payload = emailConfigs.map((config) => ({
        email_type: config.email_type,
        email_address: config.email_address,
      }));

      await apiClient.put('/emails/config', payload);
      setMessage('Email configuration saved successfully!');
      setTimeout(() => setMessage(''), 3000);
    } catch (error: any) {
      setMessage(error.message || 'Failed to save email configuration');
    } finally {
      setSaving(false);
    }
  };

  const handleApplyToAll = () => {
    if (emailConfigs.length === 0) return;
    const firstEmail = emailConfigs[0].email_address;
    
    if (confirm(`Set all email addresses to: ${firstEmail}?`)) {
      setEmailConfigs(
        emailConfigs.map((config) => ({
          ...config,
          email_address: firstEmail,
        }))
      );
    }
  };

  if (loading) {
    return (
      <div className="text-center py-12" style={{ color: '#8B6F47' }}>
        <RefreshCw className="w-8 h-8 mx-auto mb-4 animate-spin" />
        Loading email configuration...
      </div>
    );
  }

  return (
    <div className="max-w-4xl">
      <div className="bg-white rounded-lg border-2 p-6" style={{ borderColor: '#E8DCC4' }}>
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-3">
            <div className="p-3 rounded-lg" style={{ backgroundColor: '#E8DCC4' }}>
              <Mail className="w-6 h-6" style={{ color: '#8B6F47' }} />
            </div>
            <div>
              <h2 className="text-xl font-semibold" style={{ color: '#6F4E37' }}>
                Email Configuration
              </h2>
              <p className="text-sm" style={{ color: '#8B6F47' }}>
                Manage email addresses for different departments and functions
              </p>
            </div>
          </div>
          
          {emailConfigs.length > 1 && (
            <button
              type="button"
              onClick={handleApplyToAll}
              className="px-4 py-2 rounded-lg text-sm font-medium hover:opacity-80 transition-opacity"
              style={{ backgroundColor: '#E8DCC4', color: '#6F4E37' }}
            >
              Use First Email for All
            </button>
          )}
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          {emailConfigs.map((config) => {
            const label = emailTypeLabels[config.email_type] || {
              name: config.display_name || config.email_type,
              description: config.description || '',
              icon: '📧',
            };

            return (
              <div
                key={config.email_type}
                className="p-4 rounded-lg border-2 hover:border-opacity-80 transition-colors"
                style={{ borderColor: '#E8DCC4' }}
              >
                <div className="flex items-start gap-4">
                  <div className="text-3xl flex-shrink-0">{label.icon}</div>
                  <div className="flex-1">
                    <label
                      className="block text-sm font-semibold mb-1"
                      style={{ color: '#6F4E37' }}
                    >
                      {label.name}
                    </label>
                    <p className="text-xs mb-3" style={{ color: '#8B6F47' }}>
                      {label.description}
                    </p>
                    <input
                      type="email"
                      required
                      value={config.email_address}
                      onChange={(e) => handleEmailChange(config.email_type, e.target.value)}
                      className="w-full px-4 py-2 rounded-lg border-2 focus:outline-none focus:border-opacity-80"
                      style={{ borderColor: '#E8DCC4', color: '#6F4E37' }}
                      placeholder={`${label.name.toLowerCase()}@company.com`}
                    />
                  </div>
                </div>
              </div>
            );
          })}

          {message && (
            <div
              className={`p-3 rounded-lg text-sm ${
                message.includes('success')
                  ? 'bg-green-50 text-green-600'
                  : 'bg-red-50 text-red-600'
              }`}
            >
              {message}
            </div>
          )}

          <div className="flex justify-between items-center pt-4">
            <p className="text-xs" style={{ color: '#8B6F47' }}>
              💡 Tip: You can use the same email for multiple departments or assign unique emails for better organization
            </p>
            <button
              type="submit"
              disabled={saving}
              className="flex items-center gap-2 px-6 py-2 rounded-lg text-white font-semibold hover:opacity-90 transition-opacity disabled:opacity-50"
              style={{ backgroundColor: '#8B6F47' }}
            >
              <Save className="w-5 h-5" />
              <span>{saving ? 'Saving...' : 'Save Changes'}</span>
            </button>
          </div>
        </form>
      </div>

      {/* Info Box */}
      <div
        className="mt-4 p-4 rounded-lg border-2"
        style={{ borderColor: '#E8DCC4', backgroundColor: '#FEF9F0' }}
      >
        <h3 className="font-semibold mb-2" style={{ color: '#6F4E37' }}>
          📖 How It Works
        </h3>
        <ul className="text-sm space-y-1" style={{ color: '#8B6F47' }}>
          <li>• <strong>Sales emails</strong> are used for quotations, sales orders, and customer communications</li>
          <li>• <strong>Purchase emails</strong> are used for POs, vendor communication, and procurement</li>
          <li>• <strong>Support emails</strong> appear in service tickets and customer inquiries</li>
          <li>• <strong>HR emails</strong> are used for employee notifications and payroll</li>
          <li>• <strong>No-Reply</strong> is used for automated notifications users should not reply to</li>
          <li>• Changes take effect immediately across the entire system</li>
        </ul>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Plus, Edit, Trash2, Shield, Check } from 'lucide-react';
import { apiClient } from '../../../../../lib/api-client';

interface Permission {
  module: string;
  view: boolean;
  create: boolean;
  edit: boolean;
  delete: boolean;
  approve: boolean;
}

interface Role {
  id: string;
  name: string;
  description: string;
  permissions: Permission[];
  created_at: string;
}

function normalizePermissions(value: unknown): Permission[] {
  const makeDefault = (module: string): Permission => ({
    module,
    view: false,
    create: false,
    edit: false,
    delete: false,
    approve: false,
  });

  if (Array.isArray(value)) {
    return value as Permission[];
  }

  if (value && typeof value === 'object') {
    const asAny = value as any;

    // Some older data may store a single permission object.
    if (typeof asAny.module === 'string') {
      return [
        {
          module: asAny.module,
          view: !!asAny.view,
          create: !!asAny.create,
          edit: !!asAny.edit,
          delete: !!asAny.delete,
          approve: !!asAny.approve,
        },
      ];
    }

    // Or it may store an object keyed by module name.
    return MODULES.map((module) => {
      const entry = asAny[module];
      if (entry && typeof entry === 'object') {
        return {
          module,
          view: !!entry.view,
          create: !!entry.create,
          edit: !!entry.edit,
          delete: !!entry.delete,
          approve: !!entry.approve,
        };
      }
      return makeDefault(module);
    });
  }

  return MODULES.map(makeDefault);
}

const MODULES = [
  'Purchase Management',
  'Sales Management',
  'Inventory',
  'Production',
  'Quality Control',
  'HR Management',
  'Service Management',
  'BOM & Engineering',
  'Documents',
  'Reports',
  'Settings',
];

export default function RoleManagement() {
  const [roles, setRoles] = useState<Role[]>([]);
  const [loading, setLoading] = useState(true);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [selectedRole, setSelectedRole] = useState<Role | null>(null);

  useEffect(() => {
    fetchRoles();
  }, []);

  const fetchRoles = async () => {
    try {
      setLoading(true);
      const data = await apiClient.get<Role[]>('/roles');
      setRoles(data);
    } catch (error) {
      console.error('Failed to fetch roles:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteRole = async (roleId: string) => {
    if (!confirm('Are you sure you want to delete this role? Users with this role will need to be reassigned.')) {
      return;
    }
    try {
      await apiClient.delete(`/roles/${roleId}`);
      fetchRoles();
    } catch (error) {
      console.error('Failed to delete role:', error);
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-semibold" style={{ color: '#6F4E37' }}>
            Roles & Permissions
          </h2>
          <p className="text-sm mt-1" style={{ color: '#8B6F47' }}>
            Control access to different modules and features
          </p>
        </div>
        <button
          onClick={() => setShowCreateModal(true)}
          className="flex items-center gap-2 px-4 py-2 rounded-lg text-white font-semibold hover:opacity-90 transition-opacity"
          style={{ backgroundColor: '#8B6F47' }}
        >
          <Plus className="w-5 h-5" />
          <span>Create Role</span>
        </button>
      </div>

      {/* Roles Grid */}
      {loading ? (
        <div className="text-center py-12" style={{ color: '#8B6F47' }}>
          Loading roles...
        </div>
      ) : roles.length === 0 ? (
        <div className="text-center py-12" style={{ color: '#8B6F47' }}>
          No roles yet. Create your first role!
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {roles.map((role) => (
            (() => {
              const permissions = normalizePermissions((role as any).permissions);
              const allowedPermissions = permissions.filter(
                (p) => p.view || p.create || p.edit || p.delete || p.approve,
              );
              return (
            <div
              key={role.id}
              className="bg-white rounded-lg border-2 p-6 hover:shadow-lg transition-shadow"
              style={{ borderColor: '#E8DCC4' }}
            >
              <div className="flex items-start justify-between mb-4">
                <div className="flex items-center gap-3">
                  <div className="p-2 rounded-lg" style={{ backgroundColor: '#E8DCC4' }}>
                    <Shield className="w-6 h-6" style={{ color: '#8B6F47' }} />
                  </div>
                  <div>
                    <h3 className="font-semibold text-lg" style={{ color: '#6F4E37' }}>
                      {role.name}
                    </h3>
                    <p className="text-sm" style={{ color: '#8B6F47' }}>
                      {role.description}
                    </p>
                  </div>
                </div>
              </div>

              <div className="space-y-2 mb-4">
                <p className="text-xs font-semibold" style={{ color: '#8B6F47' }}>
                  PERMISSIONS
                </p>
                <div className="flex flex-wrap gap-1">
                  {allowedPermissions.length === 0 ? (
                    <span className="text-xs" style={{ color: '#8B6F47' }}>
                      None
                    </span>
                  ) : (
                    allowedPermissions.slice(0, 3).map((perm) => (
                    <span
                      key={perm.module}
                      className="text-xs px-2 py-1 rounded-full"
                      style={{ backgroundColor: '#E8DCC4', color: '#6F4E37' }}
                    >
                      {perm.module}
                    </span>
                    ))
                  )}
                  {allowedPermissions.length > 3 && (
                    <span
                      className="text-xs px-2 py-1 rounded-full"
                      style={{ backgroundColor: '#E8DCC4', color: '#6F4E37' }}
                    >
                      +{allowedPermissions.length - 3} more
                    </span>
                  )}
                </div>
              </div>

              <div className="flex gap-2 pt-4 border-t" style={{ borderColor: '#E8DCC4' }}>
                <button
                  onClick={() => {
                    setSelectedRole(role);
                    setShowEditModal(true);
                  }}
                  className="flex-1 flex items-center justify-center gap-2 px-3 py-2 rounded-lg border-2 font-medium hover:bg-[#FAF9F6] transition-colors"
                  style={{ borderColor: '#E8DCC4', color: '#6F4E37' }}
                >
                  <Edit className="w-4 h-4" />
                  <span>Edit</span>
                </button>
                <button
                  onClick={() => handleDeleteRole(role.id)}
                  className="px-3 py-2 rounded-lg border-2 border-red-200 text-red-600 hover:bg-red-50 transition-colors"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            </div>
              );
            })()
          ))}
        </div>
      )}

      {/* Create Role Modal */}
      {showCreateModal && (
        <RoleModal onClose={() => setShowCreateModal(false)} onSuccess={fetchRoles} />
      )}

      {/* Edit Role Modal */}
      {showEditModal && selectedRole && (
        <RoleModal role={selectedRole} onClose={() => setShowEditModal(false)} onSuccess={fetchRoles} />
      )}
    </div>
  );
}

// Role Modal Component
function RoleModal({
  role,
  onClose,
  onSuccess,
}: {
  role?: Role;
  onClose: () => void;
  onSuccess: () => void;
}) {
  const [formData, setFormData] = useState({
    name: role?.name || '',
    description: role?.description || '',
    permissions: normalizePermissions((role as any)?.permissions),
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handlePermissionChange = (moduleIndex: number, permission: keyof Omit<Permission, 'module'>, value: boolean) => {
    const newPermissions = [...formData.permissions];
    newPermissions[moduleIndex] = {
      ...newPermissions[moduleIndex],
      [permission]: value,
    };
    setFormData({ ...formData, permissions: newPermissions });
  };

  const handleSelectAll = (moduleIndex: number) => {
    const newPermissions = [...formData.permissions];
    newPermissions[moduleIndex] = {
      ...newPermissions[moduleIndex],
      view: true,
      create: true,
      edit: true,
      delete: true,
      approve: true,
    };
    setFormData({ ...formData, permissions: newPermissions });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      if (role) {
        await apiClient.put(`/roles/${role.id}`, formData);
      } else {
        await apiClient.post('/roles', formData);
      }
      onSuccess();
      onClose();
    } catch (error: any) {
      setError(error.message || `Failed to ${role ? 'update' : 'create'} role`);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-lg p-6 w-full max-w-4xl max-h-[90vh] overflow-y-auto">
        <h2 className="text-2xl font-bold mb-4" style={{ color: '#6F4E37' }}>
          {role ? 'Edit Role' : 'Create New Role'}
        </h2>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
                Role Name
              </label>
              <input
                type="text"
                required
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                placeholder="e.g., Manager, Supervisor, Operator"
                className="w-full px-4 py-2 rounded-lg border-2 focus:outline-none focus:border-opacity-80"
                style={{ borderColor: '#E8DCC4', color: '#6F4E37' }}
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
                Description
              </label>
              <input
                type="text"
                required
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                placeholder="Brief description of this role"
                className="w-full px-4 py-2 rounded-lg border-2 focus:outline-none focus:border-opacity-80"
                style={{ borderColor: '#E8DCC4', color: '#6F4E37' }}
              />
            </div>
          </div>

          <div>
            <h3 className="text-lg font-semibold mb-4" style={{ color: '#6F4E37' }}>
              Module Permissions
            </h3>
            <div className="bg-white rounded-lg border-2 overflow-hidden" style={{ borderColor: '#E8DCC4' }}>
              <table className="w-full">
                <thead style={{ backgroundColor: '#FAF9F6', color: '#6F4E37' }}>
                  <tr>
                    <th className="px-4 py-3 text-left text-sm font-semibold">Module</th>
                    <th className="px-4 py-3 text-center text-sm font-semibold">View</th>
                    <th className="px-4 py-3 text-center text-sm font-semibold">Create</th>
                    <th className="px-4 py-3 text-center text-sm font-semibold">Edit</th>
                    <th className="px-4 py-3 text-center text-sm font-semibold">Delete</th>
                    <th className="px-4 py-3 text-center text-sm font-semibold">Approve</th>
                    <th className="px-4 py-3 text-center text-sm font-semibold">All</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#E8DCC4]">
                  {formData.permissions.map((perm, idx) => (
                    <tr key={idx} className="hover:bg-[#FAF9F6]">
                      <td className="px-4 py-3 font-medium" style={{ color: '#6F4E37' }}>
                        {perm.module}
                      </td>
                      {(['view', 'create', 'edit', 'delete', 'approve'] as const).map((action) => (
                        <td key={action} className="px-4 py-3 text-center">
                          <input
                            type="checkbox"
                            checked={perm[action]}
                            onChange={(e) => handlePermissionChange(idx, action, e.target.checked)}
                            className="w-4 h-4 rounded border-2 cursor-pointer"
                            style={{ accentColor: '#8B6F47' }}
                          />
                        </td>
                      ))}
                      <td className="px-4 py-3 text-center">
                        <button
                          type="button"
                          onClick={() => handleSelectAll(idx)}
                          className="p-1 rounded hover:bg-[#E8DCC4] transition-colors"
                          title="Select All"
                        >
                          <Check className="w-4 h-4" style={{ color: '#8B6F47' }} />
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {error && <div className="p-3 rounded-lg bg-red-50 text-red-600 text-sm">{error}</div>}

          <div className="flex gap-3 pt-4">
            <button
              type="button"
              onClick={onClose}
              className="flex-1 px-4 py-2 rounded-lg border-2 font-semibold hover:bg-[#FAF9F6] transition-colors"
              style={{ borderColor: '#E8DCC4', color: '#6F4E37' }}
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={loading}
              className="flex-1 px-4 py-2 rounded-lg text-white font-semibold hover:opacity-90 transition-opacity disabled:opacity-50"
              style={{ backgroundColor: '#8B6F47' }}
            >
              {loading ? (role ? 'Updating...' : 'Creating...') : role ? 'Update Role' : 'Create Role'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Plus, Edit, Trash2, UserX, UserCheck, Search, Mail } from 'lucide-react';
import { apiClient } from '../../../../../lib/api-client';

interface User {
  id: string;
  email: string;
  first_name: string;
  last_name: string;
  is_active: boolean;
  role?: {
    id: string;
    name: string;
  };
  roles?: Array<{
    role: {
      id: string;
      name: string;
    };
  }>;
  created_at: string;
}

function getUserRoles(user: User): Array<{ id: string; name: string }> {
  const multi = (user.roles || [])
    .map((r) => r?.role)
    .filter(Boolean) as Array<{ id: string; name: string }>;
  if (multi.length > 0) return multi;
  return user.role ? [user.role] : [];
}

export default function UserManagement() {
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [selectedUser, setSelectedUser] = useState<User | null>(null);

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    try {
      setLoading(true);
      const data = await apiClient.get<User[]>('/users');
      setUsers(data);
    } catch (error) {
      console.error('Failed to fetch users:', error);
    } finally {
      setLoading(false);
    }
  };

  const filteredUsers = users.filter(
    (user) =>
      user.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
      `${user.first_name} ${user.last_name}`.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const handleToggleStatus = async (userId: string, currentStatus: boolean) => {
    try {
      await apiClient.put(`/users/${userId}`, { is_active: !currentStatus });
      fetchUsers();
    } catch (error) {
      console.error('Failed to update user status:', error);
    }
  };

  const handleDeleteUser = async (userId: string) => {
    if (!confirm('Are you sure you want to delete this user? This action cannot be undone.')) {
      return;
    }
    try {
      await apiClient.delete(`/users/${userId}`);
      fetchUsers();
    } catch (error) {
      console.error('Failed to delete user:', error);
    }
  };

  return (
    <div className="space-y-6">
      {/* Header Actions */}
      <div className="flex items-center justify-between gap-4">
        {/* Search */}
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5" style={{ color: '#8B6F47' }} />
          <input
            type="text"
            placeholder="Search users by name or email..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2 rounded-lg border-2 focus:outline-none focus:border-opacity-80"
            style={{ borderColor: '#E8DCC4', color: '#6F4E37' }}
          />
        </div>

        {/* Create User Button */}
        <button
          onClick={() => setShowCreateModal(true)}
          className="flex items-center gap-2 px-4 py-2 rounded-lg text-white font-semibold hover:opacity-90 transition-opacity"
          style={{ backgroundColor: '#8B6F47' }}
        >
          <Plus className="w-5 h-5" />
          <span>Create User</span>
        </button>
      </div>

      {/* Users Table */}
      <div className="bg-white rounded-lg border-2 overflow-hidden" style={{ borderColor: '#E8DCC4' }}>
        {loading ? (
          <div className="text-center py-12" style={{ color: '#8B6F47' }}>
            Loading users...
          </div>
        ) : filteredUsers.length === 0 ? (
          <div className="text-center py-12" style={{ color: '#8B6F47' }}>
            {searchQuery ? 'No users found matching your search.' : 'No users yet. Create your first user!'}
          </div>
        ) : (
          <table className="w-full">
            <thead style={{ backgroundColor: '#FAF9F6', color: '#6F4E37' }}>
              <tr>
                <th className="px-6 py-3 text-left text-sm font-semibold">Name</th>
                <th className="px-6 py-3 text-left text-sm font-semibold">Email</th>
                <th className="px-6 py-3 text-left text-sm font-semibold">Role</th>
                <th className="px-6 py-3 text-left text-sm font-semibold">Status</th>
                <th className="px-6 py-3 text-left text-sm font-semibold">Joined</th>
                <th className="px-6 py-3 text-right text-sm font-semibold">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[#E8DCC4]">
              {filteredUsers.map((user) => (
                <tr key={user.id} className="hover:bg-[#FAF9F6] transition-colors">
                  <td className="px-6 py-4">
                    <div className="font-medium" style={{ color: '#6F4E37' }}>
                      {user.first_name} {user.last_name}
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-2" style={{ color: '#8B6F47' }}>
                      <Mail className="w-4 h-4" />
                      <span className="text-sm">{user.email}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex flex-wrap gap-1">
                      {getUserRoles(user).length === 0 ? (
                        <span
                          className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium"
                          style={{ backgroundColor: '#E8DCC4', color: '#6F4E37' }}
                        >
                          No Role
                        </span>
                      ) : (
                        getUserRoles(user).map((role) => (
                          <span
                            key={role.id}
                            className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium"
                            style={{ backgroundColor: '#E8DCC4', color: '#6F4E37' }}
                          >
                            {role.name}
                          </span>
                        ))
                      )}
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    {user.is_active ? (
                      <span className="inline-flex items-center gap-1 text-sm text-green-600">
                        <UserCheck className="w-4 h-4" />
                        Active
                      </span>
                    ) : (
                      <span className="inline-flex items-center gap-1 text-sm text-red-600">
                        <UserX className="w-4 h-4" />
                        Inactive
                      </span>
                    )}
                  </td>
                  <td className="px-6 py-4 text-sm" style={{ color: '#8B6F47' }}>
                    {new Date(user.created_at).toLocaleDateString()}
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center justify-end gap-2">
                      <button
                        onClick={() => {
                          setSelectedUser(user);
                          setShowEditModal(true);
                        }}
                        className="p-2 rounded-lg hover:bg-[#E8DCC4] transition-colors"
                        title="Edit User"
                      >
                        <Edit className="w-4 h-4" style={{ color: '#8B6F47' }} />
                      </button>
                      <button
                        onClick={() => handleToggleStatus(user.id, user.is_active)}
                        className="p-2 rounded-lg hover:bg-[#E8DCC4] transition-colors"
                        title={user.is_active ? 'Deactivate User' : 'Activate User'}
                      >
                        {user.is_active ? (
                          <UserX className="w-4 h-4" style={{ color: '#8B6F47' }} />
                        ) : (
                          <UserCheck className="w-4 h-4" style={{ color: '#8B6F47' }} />
                        )}
                      </button>
                      <button
                        onClick={() => handleDeleteUser(user.id)}
                        className="p-2 rounded-lg hover:bg-red-50 transition-colors"
                        title="Delete User"
                      >
                        <Trash2 className="w-4 h-4 text-red-600" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {/* Create User Modal */}
      {showCreateModal && (
        <CreateUserModal onClose={() => setShowCreateModal(false)} onSuccess={fetchUsers} />
      )}

      {/* Edit User Modal */}
      {showEditModal && selectedUser && (
        <EditUserModal user={selectedUser} onClose={() => setShowEditModal(false)} onSuccess={fetchUsers} />
      )}
    </div>
  );
}

// Create User Modal Component
function CreateUserModal({ onClose, onSuccess }: { onClose: () => void; onSuccess: () => void }) {
  const [formData, setFormData] = useState({
    email: '',
    firstName: '',
    lastName: '',
    roleIds: [] as string[],
    password: '',
  });
  const [roles, setRoles] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchRoles();
  }, []);

  const fetchRoles = async () => {
    try {
      const data = await apiClient.get<any[]>('/roles');
      setRoles(data);
    } catch (error) {
      console.error('Failed to fetch roles:', error);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      await apiClient.post('/users', formData);
      onSuccess();
      onClose();
    } catch (error: any) {
      setError(error.message || 'Failed to create user');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white rounded-lg p-6 w-full max-w-md">
        <h2 className="text-2xl font-bold mb-4" style={{ color: '#6F4E37' }}>
          Create New User
        </h2>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
                First Name
              </label>
              <input
                type="text"
                required
                value={formData.firstName}
                onChange={(e) => setFormData({ ...formData, firstName: e.target.value })}
                className="w-full px-4 py-2 rounded-lg border-2 focus:outline-none focus:border-opacity-80"
                style={{ borderColor: '#E8DCC4', color: '#6F4E37' }}
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
