    'RETURNED'
  ]);
  const [filteredLevels, setFilteredLevels] = useState<string[]>([]);
  const [showLevelDropdown, setShowLevelDropdown] = useState(false);
  
  const [newDeployment, setNewDeployment] = useState({
    deployment_level: 'CUSTOMER',
    organization_name: '',
    location_name: '',
    deployment_date: new Date().toISOString().split('T')[0],
    contact_person: '',
    contact_email: '',
    contact_phone: '',
    deployment_notes: '',
    warranty_expiry_date: '',
    maintenance_schedule: '',
    is_current_location: true,
  });

  useEffect(() => {
    fetchDeployments(1, searchTerm, sortField, sortOrder);
    fetchCustomers();
  }, []);

  useEffect(() => {
    const handle = setTimeout(() => {
      setSearchTerm(searchInput);
      setCurrentPage(1);
      fetchDeployments(1, searchInput, sortField, sortOrder);
    }, 300);

    return () => clearTimeout(handle);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchInput]);
  
  const fetchCustomers = async () => {
    try {
      const data = await apiClient.get<Customer[]>('/sales/customers');
      setCustomers(data);
      setFilteredCustomers(data);
    } catch (error) {
      console.error('Failed to fetch customers:', error);
    }
  };
  
  const fetchCustomerLocations = async (customerName: string) => {
    try {
      // Fetch unique locations for this customer from deployment history
      const response = await apiClient.get<PaginatedResponse<any>>(
        `/uid/deployment/status?organization=${encodeURIComponent(customerName)}&offset=0&limit=200`,
      );
      const allDeployments = response?.data || [];

      const locations = allDeployments
        .filter(d => d.current_organization === customerName)
        .reduce((acc: Map<string, number>, curr) => {
          if (curr.current_location) {
            acc.set(curr.current_location, (acc.get(curr.current_location) || 0) + 1);
          }
          return acc;
        }, new Map<string, number>());
      
      const locationArray: CustomerLocation[] = Array.from(locations.entries()).map(([location_name, count]: [string, number]) => ({
        location_name,
        count
      }));
      
      setCustomerLocations(locationArray);
      setFilteredLocations(locationArray);
    } catch (error) {
      console.error('Failed to fetch locations:', error);
      setCustomerLocations([]);
      setFilteredLocations([]);
    }
  };
  
  const handleOrganizationChange = (value: string) => {
    setNewDeployment({ ...newDeployment, organization_name: value });
    
    const filtered = customers.filter(customer =>
      customer.customer_name.toLowerCase().includes(value.toLowerCase()) ||
      customer.customer_code.toLowerCase().includes(value.toLowerCase())
    );
    setFilteredCustomers(filtered);
    setShowCustomerDropdown(value.length > 0 && filtered.length > 0);
  };
  
  const selectCustomer = (customer: Customer) => {
    setNewDeployment({
      ...newDeployment,
      organization_name: customer.customer_name,
      contact_email: customer.contact_email || newDeployment.contact_email,
      contact_person: customer.contact_person || newDeployment.contact_person,
    });
    setSelectedCustomerId(customer.id);
    setShowCustomerDropdown(false);
    
    // Fetch locations for this customer
    fetchCustomerLocations(customer.customer_name);
  };
  
  const handleLocationChange = (value: string) => {
    setNewDeployment({ ...newDeployment, location_name: value });
    
    const filtered = customerLocations.filter(loc =>
      loc.location_name.toLowerCase().includes(value.toLowerCase())
    );
    setFilteredLocations(filtered);
    setShowLocationDropdown(value.length > 0);
  };
  
  const selectLocation = (location: CustomerLocation) => {
    setNewDeployment({ ...newDeployment, location_name: location.location_name });
    setShowLocationDropdown(false);
  };
  
  const handleDeploymentLevelChange = (value: string) => {
    setNewDeployment({ ...newDeployment, deployment_level: value.toUpperCase() });
    
    const filtered = deploymentLevels.filter(level =>
      level.toLowerCase().includes(value.toLowerCase())
    );
    setFilteredLevels(filtered);
    setShowLevelDropdown(value.length > 0 && filtered.length > 0);
  };
  
  const selectLevel = (level: string) => {
    setNewDeployment({ ...newDeployment, deployment_level: level });
    setShowLevelDropdown(false);
  };

  const fetchDeployments = useCallback(async (
    page = 1,
    search = '',
    sortBy: keyof UIDDeployment = sortField,
    order: 'asc' | 'desc' = sortOrder,
  ) => {
    try {
      setLoading(true);
      const offset = (page - 1) * itemsPerPage;
      const params = new URLSearchParams();
      params.set('offset', String(offset));
      params.set('limit', String(itemsPerPage));
      params.set('sort_by', String(sortBy));
      params.set('sort_order', order);
      if (search.trim()) params.set('search', search.trim());

      const res = await apiClient.get<PaginatedResponse<UIDDeployment>>(`/uid/deployment/status?${params.toString()}`);
      setDeployments(res.data);
      setTotalCount(res.total);
    } catch (error) {
      console.error('Failed to fetch deployments:', error);
    } finally {
      setLoading(false);
    }
  }, [itemsPerPage, sortField, sortOrder]);

  const viewHistory = async (uid: UIDDeployment) => {
    try {
      setSelectedUID(uid);
      const history = await apiClient.get<DeploymentHistory[]>(`/uid/deployment/${uid.uid_id}/history`);
      setDeploymentHistory(history);
      setShowHistoryModal(true);
    } catch (error) {
      console.error('Failed to fetch history:', error);
    }
  };

  const openAddModal = (uid: UIDDeployment) => {
    setSelectedUID(uid);
    setNewDeployment({
      ...newDeployment,
      organization_name: uid.current_organization || '',
      location_name: '',
    });
    setShowAddModal(true);
  };

  const addDeployment = async () => {
    if (!selectedUID) return;
    
    try {
      await apiClient.post('/uid/deployment', {
        uid_id: selectedUID.uid_id,
        ...newDeployment,
      });
      
      alert('Deployment added successfully!');
      setShowAddModal(false);
      fetchDeployments();
      
      // Reset form
      setNewDeployment({
        deployment_level: 'CUSTOMER',
        organization_name: '',
        location_name: '',
        deployment_date: new Date().toISOString().split('T')[0],
        contact_person: '',
        contact_email: '',
        contact_phone: '',
        deployment_notes: '',
        warranty_expiry_date: '',
        maintenance_schedule: '',
        is_current_location: true,
      });
    } catch (error) {
      console.error('Failed to add deployment:', error);
      alert(`Failed to add deployment: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  };

  const getLevelBadgeColor = (level: string | null) => {
    if (!level) return 'bg-gray-200 text-gray-700';
    switch (level.toUpperCase()) {
      case 'CUSTOMER': return 'bg-blue-100 text-blue-800';
      case 'DEPOT': return 'bg-yellow-100 text-yellow-800';
      case 'END_LOCATION': return 'bg-green-100 text-green-800';
      case 'SERVICE_CENTER': return 'bg-orange-100 text-orange-800';
      case 'RETURNED': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-200 text-gray-700';
    }
  };

  const handleSort = (field: keyof UIDDeployment) => {
    let nextSortOrder: 'asc' | 'desc' = 'asc';
    if (sortField === field) {
      nextSortOrder = sortOrder === 'asc' ? 'desc' : 'asc';
      setSortOrder(nextSortOrder);
    } else {
      setSortField(field);
      nextSortOrder = 'asc';
      setSortOrder('asc');
    }

    setCurrentPage(1);
    fetchDeployments(1, searchTerm, field, nextSortOrder);
  };

  const getSortIcon = (field: keyof UIDDeployment) => {
    if (sortField !== field) return '⇅';
    return sortOrder === 'asc' ? '↑' : '↓';
  };

  const totalPages = Math.max(1, Math.ceil(totalCount / itemsPerPage));
  const paginatedDeployments = deployments;

  const goToPage = (page: number) => {
    const nextPage = Math.max(1, Math.min(page, totalPages));
    setCurrentPage(nextPage);
    fetchDeployments(nextPage, searchTerm, sortField, sortOrder);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-50 to-blue-50 p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-4xl font-bold text-gray-900 mb-2">🗺️ Product Deployment Tracking</h1>
          <p className="text-gray-600">Track product locations through distribution channels</p>
        </div>

        {/* Search and Stats */}
        <div className="grid grid-cols-4 gap-6 mb-8">
          <div className="col-span-2">
            <div className="relative">
              <input
                type="text"
                placeholder="🔍 Search by UID, Part No, Item, Organization, Location, Level..."
                value={searchInput}
                onChange={(e) => setSearchInput(e.target.value)}
                className="w-full px-4 py-3 pl-10 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent"
              />
              <svg className="absolute left-3 top-3.5 h-5 w-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
              {searchInput && (
                <button
                  onClick={() => setSearchInput('')}
                  className="absolute right-3 top-3 text-gray-400 hover:text-gray-600"
                >
                  ✕
                </button>
              )}
            </div>
          </div>
          <div className="bg-white rounded-lg shadow-md p-4">
            <div className="text-sm text-gray-600 mb-1">Total Products</div>
            <div className="text-3xl font-bold text-purple-600">{totalCount}</div>
            <div className="text-xs text-gray-500 mt-1">Showing {deployments.length} on this page</div>
          </div>
          <div className="bg-white rounded-lg shadow-md p-4">
            <div className="text-sm text-gray-600 mb-1">With Locations</div>
            <div className="text-3xl font-bold text-green-600">
              {deployments.filter(d => d.current_location).length}
            </div>
            <div className="text-xs text-gray-500 mt-1">(current page)</div>
          </div>
        </div>

        {/* Deployments Table */}
        <div className="bg-white rounded-lg shadow-md overflow-hidden">
          {loading ? (
            <div className="p-8 text-center text-gray-500">Loading deployments...</div>
          ) : totalCount === 0 ? (
            <div className="p-12 text-center">
              <div className="text-6xl mb-4">📦</div>
              <h3 className="text-xl font-semibold text-gray-700 mb-2">No Deployments Found</h3>
              <p className="text-gray-500">Start tracking products by adding deployment information</p>
            </div>
          ) : (
            <>
              <table className="w-full">
                <thead className="bg-purple-50">
                  <tr>
                    <th 
                      className="px-6 py-3 text-left text-xs font-medium text-purple-900 uppercase cursor-pointer hover:bg-purple-100"
                      onClick={() => handleSort('uid')}
                    >
                      UID {getSortIcon('uid')}
                    </th>
                    <th 
                      className="px-6 py-3 text-left text-xs font-medium text-purple-900 uppercase cursor-pointer hover:bg-purple-100"
                      onClick={() => handleSort('client_part_number')}
                    >
                      Part No {getSortIcon('client_part_number')}
                    </th>
                    <th 
                      className="px-6 py-3 text-left text-xs font-medium text-purple-900 uppercase cursor-pointer hover:bg-purple-100"
                      onClick={() => handleSort('item_name')}
                    >
                      Item {getSortIcon('item_name')}
                    </th>
                    <th 
                      className="px-6 py-3 text-left text-xs font-medium text-purple-900 uppercase cursor-pointer hover:bg-purple-100"
                      onClick={() => handleSort('current_level')}
                    >
                      Level {getSortIcon('current_level')}
                    </th>
                    <th 
                      className="px-6 py-3 text-left text-xs font-medium text-purple-900 uppercase cursor-pointer hover:bg-purple-100"
                      onClick={() => handleSort('current_organization')}
                    >
                      Organization {getSortIcon('current_organization')}
                    </th>
                    <th 
                      className="px-6 py-3 text-left text-xs font-medium text-purple-900 uppercase cursor-pointer hover:bg-purple-100"
                      onClick={() => handleSort('current_location')}
                    >
                      Location {getSortIcon('current_location')}
                    </th>
                    <th 
                      className="px-6 py-3 text-left text-xs font-medium text-purple-900 uppercase cursor-pointer hover:bg-purple-100"
                      onClick={() => handleSort('current_deployment_date')}
                    >
                      Date {getSortIcon('current_deployment_date')}
                    </th>
                    <th className="px-6 py-3 text-center text-xs font-medium text-purple-900 uppercase">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200">
                  {paginatedDeployments.map((deployment) => (
                  <tr key={deployment.uid_id} className="hover:bg-gray-50">
                    <td className="px-6 py-4 text-sm font-semibold text-gray-900">{deployment.uid}</td>
                    <td className="px-6 py-4 text-sm text-gray-600">
                      {deployment.client_part_number || <span className="text-gray-400">-</span>}
                    </td>
                    <td className="px-6 py-4">
                      <div className="font-medium text-gray-900">{deployment.item_name}</div>
                      <div className="text-sm text-gray-500">{deployment.item_code}</div>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`px-3 py-1 rounded-full text-xs font-semibold ${getLevelBadgeColor(deployment.current_level)}`}>
                        {deployment.current_level || 'Not Deployed'}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-900">
                      {deployment.current_organization || <span className="text-gray-400">-</span>}
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-900">
                      {deployment.current_location || <span className="text-gray-400">-</span>}
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-600">
                      {deployment.current_deployment_date 
                        ? new Date(deployment.current_deployment_date).toLocaleDateString()
                        : <span className="text-gray-400">-</span>
                      }
                    </td>
                    <td className="px-6 py-4 text-center">
                      <button
                        onClick={() => viewHistory(deployment)}
                        className="text-purple-600 hover:text-purple-800 font-medium mr-3"
                      >
                        History
                      </button>
                      <button
                        onClick={() => openAddModal(deployment)}
                        className="text-green-600 hover:text-green-800 font-medium"
                      >
                        + Add
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>

            <div className="px-6 py-4 bg-gray-50 border-t border-gray-200 flex items-center justify-between">
              <div className="text-sm text-gray-700">
                Showing {totalCount === 0 ? 0 : (currentPage - 1) * itemsPerPage + 1} to {Math.min(currentPage * itemsPerPage, totalCount)} of {totalCount} results
              </div>
              <div className="flex items-center gap-2">
                <button
                  onClick={() => goToPage(1)}
                  disabled={currentPage === 1}
                  className="px-3 py-1 rounded border border-gray-300 text-sm disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-100"
                >
                  ««
                </button>
                <button
                  onClick={() => goToPage(currentPage - 1)}
                  disabled={currentPage === 1}
                  className="px-3 py-1 rounded border border-gray-300 text-sm disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-100"
                >
                  «
                </button>
                
                {(() => {
                  const candidates = [
                    1,
                    totalPages,
                    currentPage - 1,
                    currentPage,
                    currentPage + 1,
                  ].filter((p) => p >= 1 && p <= totalPages);

                  const uniqueSorted = Array.from(new Set(candidates)).sort((a, b) => a - b);

                  const parts: Array<number | 'ellipsis'> = [];
                  for (let i = 0; i < uniqueSorted.length; i++) {
                    const p = uniqueSorted[i];
                    const prev = uniqueSorted[i - 1];
                    if (i > 0 && prev !== undefined && p - prev > 1) {
                      parts.push('ellipsis');
                    }
                    parts.push(p);
                  }

                  return parts.map((part, idx) => {
                    if (part === 'ellipsis') {
                      return (
                        <span key={`ellipsis-${idx}`} className="px-2">
                          ...
                        </span>
                      );
                    }

                    const page = part;
                    return (
                      <button
                        key={page}
                        onClick={() => goToPage(page)}
                        className={`px-3 py-1 rounded text-sm ${
                          currentPage === page
                            ? 'bg-purple-600 text-white font-semibold'
                            : 'border border-gray-300 hover:bg-gray-100'
                        }`}
                      >
                        {page}
                      </button>
                    );
                  });
                })()}
                
                <button
                  onClick={() => goToPage(currentPage + 1)}
                  disabled={currentPage === totalPages}
                  className="px-3 py-1 rounded border border-gray-300 text-sm disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-100"
                >
                  »
                </button>
                <button
                  onClick={() => goToPage(totalPages)}
                  disabled={currentPage === totalPages}
                  className="px-3 py-1 rounded border border-gray-300 text-sm disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-100"
                >
                  »»
                </button>
              </div>
            </div>
            </>
          )}
        </div>
      </div>

      {/* History Modal */}
      {showHistoryModal && selectedUID && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg max-w-4xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b border-gray-200 flex justify-between items-center">
              <div>
                <h2 className="text-2xl font-bold text-gray-900">Deployment History</h2>
                <p className="text-sm text-gray-500">{selectedUID.uid} • {selectedUID.client_part_number || 'No Part No'}</p>
              </div>
              <button
                onClick={() => setShowHistoryModal(false)}
                className="text-gray-500 hover:text-gray-700 text-2xl"
              >
                ×
              </button>
            </div>

            <div className="p-6">
              {deploymentHistory.length === 0 ? (
                <p className="text-gray-500 text-center py-8">No deployment history</p>
              ) : (
                <div className="space-y-4">
                  {deploymentHistory.map((history) => (
                    <div key={history.id} className="relative pl-8 pb-6 border-l-2 border-purple-300 last:border-l-0">
                      <div className={`absolute left-0 top-0 transform -translate-x-1/2 ${
                        history.is_current_location ? 'w-4 h-4 bg-green-500' : 'w-3 h-3 bg-purple-300'
                      } rounded-full`}></div>
                      
                      <div className="bg-gray-50 rounded-lg p-4">
                        <div className="flex items-start justify-between mb-2">
                          <div>
                            <span className={`px-3 py-1 rounded-full text-xs font-semibold ${getLevelBadgeColor(history.deployment_level)}`}>
                              {history.deployment_level}
                            </span>
                            {history.is_current_location && (
                              <span className="ml-2 px-3 py-1 bg-green-100 text-green-800 rounded-full text-xs font-semibold">
                                CURRENT
                              </span>
                            )}
                          </div>
                          <span className="text-sm text-gray-500">
                            {new Date(history.deployment_date).toLocaleDateString()}
                          </span>
                        </div>
                        
                        <div className="text-lg font-bold text-gray-900 mb-1">
                          {history.organization_name}
                        </div>
                        <div className="text-md text-gray-700 mb-2">
                          📍 {history.location_name}
                        </div>
                        
                        {history.contact_person && (
                          <div className="text-sm text-gray-600">
                            👤 {history.contact_person}
                            {history.contact_email && ` • ${history.contact_email}`}
                          </div>
                        )}
                        
                        {history.deployment_notes && (
                          <div className="mt-2 text-sm text-gray-600 italic">
                            &quot;{history.deployment_notes}&quot;
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Add Deployment Modal */}
      {showAddModal && selectedUID && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg max-w-2xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b border-gray-200 flex justify-between items-center">
              <div>
                <h2 className="text-2xl font-bold text-gray-900">Add New Deployment</h2>
                <p className="text-sm text-gray-500">{selectedUID.uid} • {selectedUID.client_part_number || 'No Part No'}</p>
              </div>
              <button
                onClick={() => setShowAddModal(false)}
                className="text-gray-500 hover:text-gray-700 text-2xl"
              >
                ×
              </button>
            </div>

            <div className="p-6 space-y-4">
              {/* Organization Name - First with Autocomplete */}
              <div className="relative">
                <label className="block text-sm font-medium text-gray-700 mb-1">Organization Name *</label>
                <input
                  type="text"
                  value={newDeployment.organization_name}
                  onChange={(e) => handleOrganizationChange(e.target.value)}
                  onFocus={() => setShowCustomerDropdown(newDeployment.organization_name.length > 0 && filteredCustomers.length > 0)}
                  onBlur={() => setTimeout(() => setShowCustomerDropdown(false), 200)}
                  placeholder="Start typing customer name..."
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500"
                />
                
                {/* Customer Autocomplete Dropdown */}
                {showCustomerDropdown && (
                  <div className="absolute z-10 w-full mt-1 bg-white border border-gray-300 rounded-lg shadow-lg max-h-60 overflow-y-auto">
                    {filteredCustomers.map((customer) => (
                      <div
                        key={customer.id}
                        onClick={() => selectCustomer(customer)}
                        className="px-4 py-3 cursor-pointer hover:bg-purple-50 border-b border-gray-100 last:border-b-0"
                      >
                        <div className="font-medium text-gray-900">{customer.customer_name}</div>
                        <div className="text-sm text-gray-500">
                          Code: {customer.customer_code} {customer.contact_email && `• ${customer.contact_email}`}
                        </div>
                      </div>
                    ))}
                    {filteredCustomers.length === 0 && newDeployment.organization_name && (
                      <div className="px-4 py-3 text-sm text-gray-500 italic">
                        New customer will be created: &quot;{newDeployment.organization_name}&quot;
                      </div>
                    )}
                  </div>
                )}
              </div>

              {/* Location Name - Second with Autocomplete */}
              <div className="relative">
                <label className="block text-sm font-medium text-gray-700 mb-1">Location Name *</label>
                <input
                  type="text"
                  value={newDeployment.location_name}
                  onChange={(e) => handleLocationChange(e.target.value)}
                  onFocus={() => setShowLocationDropdown(newDeployment.location_name.length > 0)}
                  onBlur={() => setTimeout(() => setShowLocationDropdown(false), 200)}
                  placeholder={newDeployment.organization_name ? "Start typing location..." : "Select customer first"}
                  disabled={!newDeployment.organization_name}
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 disabled:bg-gray-100"
                />
                
                {/* Location Autocomplete Dropdown */}
                {showLocationDropdown && customerLocations.length > 0 && (
                  <div className="absolute z-10 w-full mt-1 bg-white border border-gray-300 rounded-lg shadow-lg max-h-60 overflow-y-auto">
                    {filteredLocations.map((location, idx) => (
                      <div
                        key={idx}
                        onClick={() => selectLocation(location)}
                        className="px-4 py-3 cursor-pointer hover:bg-purple-50 border-b border-gray-100 last:border-b-0"
                      >
                        <div className="font-medium text-gray-900">{location.location_name}</div>
                        <div className="text-sm text-gray-500">Used {location.count} time(s)</div>
                      </div>
                    ))}
                  </div>
                )}
                {showLocationDropdown && customerLocations.length === 0 && newDeployment.location_name && (
                  <div className="absolute z-10 w-full mt-1 bg-white border border-gray-300 rounded-lg shadow-lg">
                    <div className="px-4 py-3 text-sm text-gray-500 italic">
                      New location will be created: &quot;{newDeployment.location_name}&quot;
                    </div>
                  </div>
                )}
              </div>

              {/* Deployment Level */}
              <div className="relative">
                <label className="block text-sm font-medium text-gray-700 mb-1">Deployment Level *</label>
                <input
                  type="text"
                  value={newDeployment.deployment_level}
                  onChange={(e) => handleDeploymentLevelChange(e.target.value)}
                  onFocus={() => {
                    const filtered = deploymentLevels.filter(level =>
                      level.toLowerCase().includes(newDeployment.deployment_level.toLowerCase())
                    );
                    setFilteredLevels(filtered);
                    setShowLevelDropdown(filtered.length > 0);
                  }}
                  onBlur={() => setTimeout(() => setShowLevelDropdown(false), 200)}
                  placeholder="Type or select level..."
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500"
                />
                
                {/* Level Autocomplete Dropdown */}
                {showLevelDropdown && (
                  <div className="absolute z-10 w-full mt-1 bg-white border border-gray-300 rounded-lg shadow-lg max-h-60 overflow-y-auto">
                    {filteredLevels.map((level, idx) => (
                      <div
                        key={idx}
                        onClick={() => selectLevel(level)}
                        className="px-4 py-3 cursor-pointer hover:bg-purple-50 border-b border-gray-100 last:border-b-0"
                      >
                        <div className="font-medium text-gray-900">{level}</div>
                      </div>
                    ))}
                  </div>
                )}
                {!showLevelDropdown && newDeployment.deployment_level && !deploymentLevels.includes(newDeployment.deployment_level) && (
                  <div className="mt-1 text-sm text-purple-600 italic">
                    ✨ New custom level: &quot;{newDeployment.deployment_level}&quot;
                  </div>
                )}
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Contact Person</label>
                  <input
                    type="text"
                    value={newDeployment.contact_person}
                    onChange={(e) => setNewDeployment({ ...newDeployment, contact_person: e.target.value })}
                    placeholder="Name"
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Contact Email</label>
                  <input
                    type="email"
                    value={newDeployment.contact_email}
                    onChange={(e) => setNewDeployment({ ...newDeployment, contact_email: e.target.value })}
                    placeholder="email@example.com"
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500"
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Contact Phone</label>
                <input
                  type="text"
                  value={newDeployment.contact_phone}
                  onChange={(e) => setNewDeployment({ ...newDeployment, contact_phone: e.target.value })}
                  placeholder="+91 XXXXXXXXXX"
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Deployment Notes</label>
                <textarea
                  value={newDeployment.deployment_notes}
                  onChange={(e) => setNewDeployment({ ...newDeployment, deployment_notes: e.target.value })}
                  placeholder="Additional notes..."
                  rows={3}
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Deployment Date</label>
                  <input
                    type="date"
                    value={newDeployment.deployment_date}
                    onChange={(e) => setNewDeployment({ ...newDeployment, deployment_date: e.target.value })}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Warranty Expiry</label>
                  <input
                    type="date"
                    value={newDeployment.warranty_expiry_date}
                    onChange={(e) => setNewDeployment({ ...newDeployment, warranty_expiry_date: e.target.value })}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500"
                  />
                </div>
              </div>

              <div>
                <label className="flex items-center">
                  <input
                    type="checkbox"
                    checked={newDeployment.is_current_location}
                    onChange={(e) => setNewDeployment({ ...newDeployment, is_current_location: e.target.checked })}
                    className="mr-2"
                  />
                  <span className="text-sm font-medium text-gray-700">Set as current location</span>
                </label>
              </div>

              <div className="flex justify-end gap-3 pt-4">
                <button
                  onClick={() => setShowAddModal(false)}
                  className="px-6 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50"
                >
                  Cancel
                </button>
                <button
                  onClick={addDeployment}
                  className="px-6 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700"
                >
                  Add Deployment
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import { apiClient } from '../../../../lib/api-client';

interface UIDRecord {
  id: string;
  uid: string;
  entity_type: string;
  entity_id: string;
  parent_uids: string[];
  child_uids: string[];
  assembly_level: number;
  status: string;
  location: string;
  supplier_id: string;
  supplier?: {
    name: string;
    vendor_code: string;
  };
  vendorName?: string;
  vendorCode?: string;
  purchase_order_id: string;
  purchase_order?: {
    po_number: string;
  };
  grn_id: string;
  grn?: {
    grn_number: string;
  };
  grnNumber?: string;
  batch_number: string;
  items?: {
    id: string;
    code: string;
    name: string;
  };
  itemName?: string;
  itemCode?: string;
  quality_status: string;
  client_part_number?: string;
  lifecycle: Array<{
    stage: string;
    timestamp: string;
    location: string;
    reference: string;
    user: string;
  }>;
  created_at: string;
}

const statusColors: Record<string, string> = {
  ACTIVE: 'bg-green-100 text-green-800',
  IN_PRODUCTION: 'bg-amber-100 text-amber-800',
  IN_TRANSIT: 'bg-yellow-100 text-yellow-800',
  SOLD: 'bg-purple-100 text-purple-800',
  IN_SERVICE: 'bg-orange-100 text-orange-800',
  SCRAPPED: 'bg-red-100 text-red-800',
  RETURNED: 'bg-gray-100 text-gray-800',
};

export default function UIDTrackingPage() {
  const router = useRouter();
  const [uids, setUids] = useState<UIDRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchUID, setSearchUID] = useState('');
  const [searchResults, setSearchResults] = useState<UIDRecord[]>([]);
  const [showSearchDropdown, setShowSearchDropdown] = useState(false);
  const [selectedUID, setSelectedUID] = useState<UIDRecord | null>(null);
  const [showModal, setShowModal] = useState(false);
  const [showTraceModal, setShowTraceModal] = useState(false);
  const [showPartNumberModal, setShowPartNumberModal] = useState(false);
  const [editingUID, setEditingUID] = useState<UIDRecord | null>(null);
  const [partNumberInput, setPartNumberInput] = useState('');
  const [searchLoading, setSearchLoading] = useState(false);
  
  // Pagination and sorting
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage] = useState(10);
  const [totalCount, setTotalCount] = useState(0);
  const [sortField, setSortField] = useState<keyof UIDRecord>('created_at');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');

  // Filters
  const [filters, setFilters] = useState({
    status: '',
    entity_type: '',
    location: '',
    quality_status: '',
  });

  const fetchUIDs = useCallback(async () => {
    setLoading(true);
    try {
      const queryParams = new URLSearchParams();
      
      if (filters.status) queryParams.append('status', filters.status);
      if (filters.entity_type) queryParams.append('entity_type', filters.entity_type);
      if (filters.location) queryParams.append('location', filters.location);
      if (filters.quality_status) queryParams.append('quality_status', filters.quality_status);
      
      // Server-side pagination
      const offset = (currentPage - 1) * itemsPerPage;
      queryParams.append('limit', itemsPerPage.toString());
      queryParams.append('offset', offset.toString());
      
      // Sorting
      queryParams.append('sortBy', sortField);
      queryParams.append('sortOrder', sortOrder);

      const response = await apiClient.get<any>(`/uid?${queryParams}`);
      // Handle both old array format and new paginated format
      const data = Array.isArray(response) ? response : response.data || [];
      setUids(data);
      
      // If API returns total count, use it for pagination
      if (response.total) {
        setTotalCount(response.total);
      }
    } catch (error) {
      console.error('Error fetching UIDs:', error);
    } finally {
      setLoading(false);
    }
  }, [filters, currentPage, itemsPerPage, sortField, sortOrder]);

  useEffect(() => {
    fetchUIDs();
  }, [fetchUIDs]);

  // Debounced search - only call API after user stops typing
  useEffect(() => {
    if (searchUID.trim().length > 0) {
      const timeoutId = setTimeout(() => {
        performSearch();
      }, 300); // Wait 300ms after user stops typing
      return () => clearTimeout(timeoutId);
    } else {
      setSearchResults([]);
      setShowSearchDropdown(false);
    }
  }, [searchUID]);

  const performSearch = async () => {
    if (!searchUID.trim()) return;
    
    setSearchLoading(true);
    try {
      const queryParams = new URLSearchParams();
      queryParams.append('search', searchUID.trim());
      queryParams.append('limit', '10'); // Only fetch top 10 results
      
      const response = await apiClient.get<any>(`/uid?${queryParams}`);
      const data = Array.isArray(response) ? response : response.data || [];
      setSearchResults(data);
      setShowSearchDropdown(data.length > 0);
    } catch (error) {
      console.error('Error searching UIDs:', error);
    } finally {
      setSearchLoading(false);
    }
  };

  const searchForUID = async (uid: string) => {
    try {
      const data = await apiClient.get<UIDRecord>(`/uid/search/${encodeURIComponent(uid)}`);
      // Parse JSON strings to objects and add vendor/GRN names
      const parsedData: any = {
        ...data,
        lifecycle: typeof data.lifecycle === 'string' ? JSON.parse(data.lifecycle) : data.lifecycle,
        parent_uids: typeof data.parent_uids === 'string' ? JSON.parse(data.parent_uids) : data.parent_uids,
        child_uids: typeof data.child_uids === 'string' ? JSON.parse(data.child_uids) : data.child_uids,
        vendorName: data.supplier?.name || '',
        vendorCode: data.supplier?.vendor_code || '',
        grnNumber: data.grn?.grn_number || '',
      };
      setSelectedUID(parsedData);
      setShowTraceModal(true);
      setShowSearchDropdown(false);
    } catch (error) {
      console.error('Error searching UID:', error);
      alert('Error searching for UID');
    }
  };

  const selectSearchResult = (uid: UIDRecord) => {
    setSearchUID(uid.uid);
    searchForUID(uid.uid);
  };

  const openPartNumberModal = (uid: UIDRecord) => {
    setEditingUID(uid);
    setPartNumberInput(uid.client_part_number || '');
    setShowPartNumberModal(true);
  };

  const updatePartNumber = async () => {
    if (!editingUID) return;

    try {
      await apiClient.put(`/uid/${editingUID.uid}/part-number`, {
        client_part_number: partNumberInput.trim() || null,
      });
      
      // Refresh UIDs list
      await fetchUIDs();
      
      setShowPartNumberModal(false);
      setEditingUID(null);
      setPartNumberInput('');
      
      alert('Part number updated successfully!');
    } catch (error) {
      console.error('Error updating part number:', error);
      alert('Failed to update part number');
    }
  };

  const generateQRCode = (uid: string) => {
    // Generate QR code URL using a QR code API
    return `https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(uid)}`;
  };

  const handleSort = (field: keyof UIDRecord) => {
    if (sortField === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortOrder('asc');
    }
    setCurrentPage(1); // Reset to first page when sorting
  };

  const getSortIcon = (field: keyof UIDRecord) => {
    if (sortField !== field) return '⇅';
    return sortOrder === 'asc' ? '↑' : '↓';
  };

  // Calculate total pages based on total count or current data
  const totalPages = totalCount > 0 
    ? Math.ceil(totalCount / itemsPerPage)
    : Math.ceil(uids.length / itemsPerPage);
  
  // No need to sort or paginate client-side - server does it
  const paginatedUIDs = uids;

  const goToPage = (page: number) => {
    setCurrentPage(Math.max(1, Math.min(page, totalPages)));
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-IN', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-lg">Loading UID registry...</div>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-7xl mx-auto">
      {/* Back Button */}
      <button
        onClick={() => router.push('/dashboard')}
        className="mb-4 flex items-center gap-2 text-amber-600 hover:text-amber-800 font-medium"
      >
        ← Back to Dashboard
      </button>

      {/* Header */}
      <div className="mb-6 flex justify-between items-start">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 mb-2">
            🔍 UID Tracking System
          </h1>
          <p className="text-gray-600">
            Complete traceability from procurement to service - Every part has a story
          </p>
        </div>
        <button
          onClick={() => router.push('/dashboard/uid/trace')}
          className="bg-gradient-to-r from-orange-500 to-amber-500 text-white px-6 py-3 rounded-lg hover:from-orange-600 hover:to-amber-600 transition-colors font-semibold shadow-lg flex items-center gap-2"
        >
          🔍 Trace Product
        </button>
      </div>

      {/* Search Bar */}
      <div className="mb-6 bg-gradient-to-r from-amber-50 to-orange-50 p-6 rounded-xl shadow">
        <h2 className="text-lg font-semibold mb-3 text-gray-800">🔎 Track Any UID</h2>
        <div className="relative">
          <input
            type="text"
            placeholder="Start typing UID, Part No, Item, Location..."
            value={searchUID}
            onChange={(e) => setSearchUID(e.target.value)}
            onFocus={() => searchUID && setShowSearchDropdown(true)}
            onBlur={() => setTimeout(() => setShowSearchDropdown(false), 200)}
            className="w-full px-4 py-3 pr-10 border-2 border-amber-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent text-lg"
          />
          {searchLoading ? (
            <div className="absolute right-3 top-3.5 h-6 w-6">
              <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-amber-600"></div>
            </div>
          ) : (
            <svg className="absolute right-3 top-3.5 h-6 w-6 text-amber-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
          )}
          
          {/* Autocomplete Dropdown */}
          {showSearchDropdown && searchResults.length > 0 && (
            <div className="absolute z-50 w-full mt-2 bg-white border-2 border-amber-300 rounded-lg shadow-xl max-h-96 overflow-y-auto">
              {searchResults.map((uid) => (
                <div
                  key={uid.id}
                  onClick={() => selectSearchResult(uid)}
                  className="px-4 py-3 cursor-pointer hover:bg-amber-50 border-b border-gray-100 last:border-b-0 transition-colors"
                >
                  <div className="flex items-center justify-between">
                    <div className="flex-1">
                      <div className="font-semibold text-gray-900">{uid.uid}</div>
                      <div className="text-sm text-gray-600 mt-1 flex items-center gap-2">
                        {uid.itemName && <span>📦 {uid.itemName}</span>}
                        {uid.itemCode && <span className="text-amber-600">({uid.itemCode})</span>}
                      </div>
                      <div className="text-xs text-gray-500 mt-1 flex items-center gap-3">
                        {uid.client_part_number && <span>🔖 {uid.client_part_number}</span>}
                        {uid.location && <span>📍 {uid.location}</span>}
                        {uid.batch_number && <span>🏷️ Batch: {uid.batch_number}</span>}
                      </div>
                    </div>
                    <span className={`px-3 py-1 rounded-full text-xs font-semibold ${statusColors[uid.status] || 'bg-gray-100 text-gray-800'}`}>
                      {uid.status}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          )}
          
          {searchUID && searchResults.length === 0 && !showSearchDropdown && !searchLoading && (
            <div className="absolute z-50 w-full mt-2 bg-white border-2 border-amber-300 rounded-lg shadow-xl p-4 text-center text-gray-500">
              No UIDs found matching &quot;{searchUID}&quot;
            </div>
          )}
        </div>
        <p className="text-sm text-gray-600 mt-2">
          💡 Scan QR code or enter UID to view complete history and traceability
        </p>
        <p className="text-xs text-amber-600 mt-1">
          ℹ️ Showing 10 UIDs per page. Use search above to find specific UIDs, or navigate pages below to browse all records.
        </p>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
        {[
          { label: 'Total UIDs', value: totalCount || uids.length, color: 'amber', icon: '🏷️' },
          { label: 'Showing', value: uids.length, color: 'blue', icon: '📄' },
          { label: 'Current Page', value: currentPage, color: 'green', icon: '📖' },
          { label: 'Total Pages', value: totalPages, color: 'orange', icon: '📚' },
        ].map((stat, idx) => (
          <div key={idx} className="bg-white p-5 rounded-lg shadow border-l-4 border-amber-500">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">{stat.label}</p>
                <p className="text-3xl font-bold text-gray-900 mt-1">{stat.value}</p>
              </div>
              <span className="text-4xl">{stat.icon}</span>
            </div>
          </div>
        ))}
      </div>

      {/* Filters */}
      <div className="mb-6 bg-white p-4 rounded-lg shadow">
        <div className="flex gap-4 items-center justify-between">
          <div className="flex gap-4 items-center flex-1">
            <select
              value={filters.status}
              onChange={(e) => setFilters({ ...filters, status: e.target.value })}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500"
            >
              <option value="">All Status</option>
              <option value="ACTIVE">Active</option>
              <option value="IN_PRODUCTION">In Production</option>
              <option value="IN_TRANSIT">In Transit</option>
              <option value="SOLD">Sold</option>
              <option value="IN_SERVICE">In Service</option>
              <option value="SCRAPPED">Scrapped</option>
            </select>

            <select
              value={filters.entity_type}
              onChange={(e) => setFilters({ ...filters, entity_type: e.target.value })}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500"
            >
              <option value="">All Types</option>
              <option value="RAW_MATERIAL">Raw Material</option>
              <option value="COMPONENT">Component</option>
              <option value="ASSEMBLY">Assembly</option>
              <option value="FINISHED_GOOD">Finished Good</option>
            </select>

            <select
              value={filters.quality_status}
              onChange={(e) => setFilters({ ...filters, quality_status: e.target.value })}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500"
            >
              <option value="">All QC</option>
              <option value="PASSED">QC PASSED</option>
              <option value="ON_HOLD">QC ON HOLD</option>
              <option value="FAILED">QC FAILED</option>
            </select>

            <input
              type="text"
              placeholder="Filter by location..."
              value={filters.location}
              onChange={(e) => setFilters({ ...filters, location: e.target.value })}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500"
            />
          </div>
          
          {(filters.status || filters.entity_type || filters.location || filters.quality_status) && (
            <button
              onClick={() => setFilters({ status: '', entity_type: '', location: '', quality_status: '' })}
              className="px-4 py-2 bg-red-100 text-red-700 rounded-lg hover:bg-red-200 font-medium flex items-center gap-2"
            >
              ✕ Clear Filters
            </button>
          )}
        </div>
      </div>

      {/* UID Table */}
      <div className="bg-white rounded-lg shadow overflow-hidden">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-amber-50">
            <tr>
              <th 
                onClick={() => handleSort('uid')}
                className="px-6 py-3 text-left text-xs font-medium text-amber-900 uppercase cursor-pointer hover:bg-amber-100"
              >
                UID {getSortIcon('uid')}
              </th>
              <th 
                onClick={() => handleSort('client_part_number')}
                className="px-6 py-3 text-left text-xs font-medium text-amber-900 uppercase cursor-pointer hover:bg-amber-100"
              >
                Part No {getSortIcon('client_part_number')}
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-amber-900 uppercase">Item</th>
              <th 
                onClick={() => handleSort('entity_type')}
                className="px-6 py-3 text-left text-xs font-medium text-amber-900 uppercase cursor-pointer hover:bg-amber-100"
              >
                Type {getSortIcon('entity_type')}
              </th>
              <th 
                onClick={() => handleSort('status')}
                className="px-6 py-3 text-left text-xs font-medium text-amber-900 uppercase cursor-pointer hover:bg-amber-100"
              >
                Status {getSortIcon('status')}
              </th>
              <th 
                onClick={() => handleSort('location')}
                className="px-6 py-3 text-left text-xs font-medium text-amber-900 uppercase cursor-pointer hover:bg-amber-100"
              >
                Location {getSortIcon('location')}
              </th>
              <th 
                onClick={() => handleSort('assembly_level')}
                className="px-6 py-3 text-left text-xs font-medium text-amber-900 uppercase cursor-pointer hover:bg-amber-100"
              >
                Level {getSortIcon('assembly_level')}
              </th>
              <th 
                onClick={() => handleSort('created_at')}
                className="px-6 py-3 text-left text-xs font-medium text-amber-900 uppercase cursor-pointer hover:bg-amber-100"
              >
                Created {getSortIcon('created_at')}
              </th>
              <th className="px-6 py-3 text-center text-xs font-medium text-amber-900 uppercase">Actions</th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {paginatedUIDs.map((uid) => (
              <tr key={uid.id} className="hover:bg-gray-50">
                <td className="px-6 py-4">
                  <div className="font-mono text-sm font-medium text-amber-600">{uid.uid}</div>
                  {uid.batch_number && (
                    <div className="text-xs text-gray-500">Batch: {uid.batch_number}</div>
                  )}
                </td>
                <td className="px-6 py-4">
                  <div className="flex items-center gap-2">
                    {uid.client_part_number ? (
                      <span className="px-2 py-1 bg-blue-100 text-blue-800 rounded text-xs font-semibold">
                        {uid.client_part_number}
                      </span>
                    ) : (
                      <span className="text-gray-400 text-xs">Not assigned</span>
                    )}
                    <button
                      onClick={() => openPartNumberModal(uid)}
                      className="text-blue-600 hover:text-blue-800 text-xs"
                      title="Edit Part Number"
                    >
                      ✏️
                    </button>
                  </div>
                </td>
                <td className="px-6 py-4">
                  {uid.items ? (
                    <div>
                      <div className="text-sm font-medium text-gray-900">{uid.items.code}</div>
                      <div className="text-xs text-gray-500">{uid.items.name}</div>
                    </div>
                  ) : (
                    <div className="text-sm text-gray-400">-</div>
                  )}
                </td>
                <td className="px-6 py-4 text-sm text-gray-900">{uid.entity_type}</td>
                <td className="px-6 py-4">
                  <span className={`px-2 py-1 rounded text-xs font-medium ${statusColors[uid.status] || 'bg-gray-100 text-gray-800'}`}>
                    {uid.status}
                  </span>
                </td>
                <td className="px-6 py-4 text-sm text-gray-900">{uid.location || 'N/A'}</td>
                <td className="px-6 py-4 text-sm text-gray-900">
                  <span className="flex items-center gap-1">
                    <span>L{uid.assembly_level}</span>
                    {uid.parent_uids && uid.parent_uids.length > 0 && (
                      <span className="text-xs text-amber-600">⬆{uid.parent_uids.length}</span>
                    )}
                    {uid.child_uids && uid.child_uids.length > 0 && (
                      <span className="text-xs text-green-600">⬇{uid.child_uids.length}</span>
                    )}
                  </span>
                </td>
                <td className="px-6 py-4 text-sm text-gray-500">
                  {new Date(uid.created_at).toLocaleDateString()}
                </td>
                <td className="px-6 py-4 text-sm space-x-2">
                  <button
                    onClick={async () => {
                      try {
                        const data = await apiClient.get<UIDRecord>(`/uid/search/${encodeURIComponent(uid.uid)}`);
                        const parsedUID: any = {
                          ...data,
                          lifecycle: typeof data.lifecycle === 'string' ? JSON.parse(data.lifecycle) : data.lifecycle,
                          parent_uids: typeof data.parent_uids === 'string' ? JSON.parse(data.parent_uids) : data.parent_uids,
                          child_uids: typeof data.child_uids === 'string' ? JSON.parse(data.child_uids) : data.child_uids,
                          vendorName: data.supplier?.name || '',
                          vendorCode: data.supplier?.vendor_code || '',
                          grnNumber: data.grn?.grn_number || '',
                        };
                        setSelectedUID(parsedUID);
                        setShowTraceModal(true);
                      } catch (error) {
                        console.error('Error loading trace data:', error);
                        alert('Error loading trace information');
                      }
                    }}
                    className="text-amber-600 hover:text-amber-900 font-medium"
                  >
                    Trace
                  </button>
                  <button
                    onClick={() => {
                      const parsedUID: any = {
                        ...uid,
                        lifecycle: typeof uid.lifecycle === 'string' ? JSON.parse(uid.lifecycle) : uid.lifecycle,
                        parent_uids: typeof uid.parent_uids === 'string' ? JSON.parse(uid.parent_uids) : uid.parent_uids,
                        child_uids: typeof uid.child_uids === 'string' ? JSON.parse(uid.child_uids) : uid.child_uids,
                      };
                      setSelectedUID(parsedUID);
                      setShowModal(true);
                    }}
                    className="text-purple-600 hover:text-purple-900 font-medium"
                  >
                    QR Code
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* Pagination */}
        <div className="px-6 py-4 bg-gray-50 border-t border-gray-200 flex items-center justify-between">
          <div className="text-sm text-gray-700">
            {totalCount > 0 ? (
              <>Showing {(currentPage - 1) * itemsPerPage + 1} to {Math.min(currentPage * itemsPerPage, totalCount)} of {totalCount} results</>
            ) : (
              <>Showing {uids.length} results</>
            )}
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => goToPage(1)}
              disabled={currentPage === 1}
              className="px-3 py-1 rounded border border-gray-300 text-sm disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-100"
            >
              ««
            </button>
            <button
              onClick={() => goToPage(currentPage - 1)}
              disabled={currentPage === 1}
              className="px-3 py-1 rounded border border-gray-300 text-sm disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-100"
            >
              «
            </button>
            
            {[...Array(totalPages)].map((_, i) => {
              const page = i + 1;
              if (
                page === 1 ||
                page === totalPages ||
                (page >= currentPage - 1 && page <= currentPage + 1)
              ) {
                return (
                  <button
                    key={page}
                    onClick={() => goToPage(page)}
                    className={`px-3 py-1 rounded text-sm ${
                      currentPage === page
                        ? 'bg-amber-600 text-white font-semibold'
                        : 'border border-gray-300 hover:bg-gray-100'
                    }`}
                  >
                    {page}
                  </button>
                );
              } else if (page === currentPage - 2 || page === currentPage + 2) {
                return <span key={page} className="px-2">...</span>;
              }
              return null;
            })}
            
            <button
              onClick={() => goToPage(currentPage + 1)}
              disabled={currentPage === totalPages}
              className="px-3 py-1 rounded border border-gray-300 text-sm disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-100"
            >
              »
            </button>
            <button
              onClick={() => goToPage(totalPages)}
              disabled={currentPage === totalPages}
              className="px-3 py-1 rounded border border-gray-300 text-sm disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-100"
            >
              »»
            </button>
          </div>
        </div>
      </div>

      {uids.length === 0 && !loading && (
        <div className="text-center py-12 bg-white rounded-lg shadow mt-6">
          <p className="text-gray-500">No UIDs found. UIDs are auto-generated at Goods Receipt.</p>
        </div>
      )}

      {/* QR Code Modal */}
      {showModal && selectedUID && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-lg max-w-md w-full p-6">
            <h2 className="text-2xl font-bold mb-4">QR Code</h2>
            <div className="text-center">
              <div className="bg-gray-50 p-4 rounded-lg mb-4">
                <img
                  src={generateQRCode(selectedUID.uid)}
                  alt="QR Code"
                  className="mx-auto"
                />
              </div>
              <p className="font-mono text-sm text-gray-700 mb-2">{selectedUID.uid}</p>
              <p className="text-sm text-gray-500 mb-4">
                Scan to view complete traceability
              </p>
              <button
                onClick={() => window.print()}
                className="bg-amber-600 text-white px-4 py-2 rounded-lg hover:bg-amber-700 mr-2"
              >
                Print Label
              </button>
              <button
                onClick={() => setShowModal(false)}
                className="bg-gray-200 text-gray-800 px-4 py-2 rounded-lg hover:bg-gray-300"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Trace Modal */}
      {showTraceModal && selectedUID && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50 overflow-y-auto">
          <div className="bg-white rounded-lg max-w-4xl w-full p-6 my-8">
            <div className="flex justify-between items-start mb-6">
              <div>
                <h2 className="text-2xl font-bold">UID Traceability Report</h2>
                <p className="font-mono text-lg text-amber-600 mt-1">{selectedUID.uid}</p>
              </div>
              <button
                onClick={() => setShowTraceModal(false)}
                className="text-gray-500 hover:text-gray-700 text-2xl"
              >
                ×
              </button>
            </div>

            {/* Basic Info */}
            <div className="grid grid-cols-2 gap-4 mb-6">
              <div className="bg-gray-50 p-4 rounded-lg">
                <p className="text-sm text-gray-600">Entity Type</p>
                <p className="font-medium">{selectedUID.entity_type}</p>
              </div>
              <div className="bg-gray-50 p-4 rounded-lg">
                <p className="text-sm text-gray-600">Status</p>
                <span className={`px-2 py-1 rounded text-xs font-medium ${statusColors[selectedUID.status]}`}>
                  {selectedUID.status}
                </span>
              </div>
              <div className="bg-gray-50 p-4 rounded-lg">
                <p className="text-sm text-gray-600">Current Location</p>
                <p className="font-medium">{selectedUID.location || 'N/A'}</p>
              </div>
              <div className="bg-gray-50 p-4 rounded-lg">
                <p className="text-sm text-gray-600">Assembly Level</p>
                <p className="font-medium">Level {selectedUID.assembly_level}</p>
              </div>
            </div>

            {/* Hierarchy */}
            {(selectedUID.parent_uids?.length > 0 || selectedUID.child_uids?.length > 0) && (
              <div className="mb-6">
                <h3 className="font-semibold text-lg mb-3">📊 Assembly Hierarchy</h3>
                {selectedUID.parent_uids && selectedUID.parent_uids.length > 0 && (
                  <div className="mb-3">
                    <p className="text-sm text-gray-600 mb-2">⬆ Parent Components ({selectedUID.parent_uids.length})</p>
                    <div className="flex flex-wrap gap-2">
                      {selectedUID.parent_uids.map((parentUID, idx) => (
                        <span key={idx} className="px-3 py-1 bg-amber-50 text-amber-700 rounded text-sm font-mono">
                          {parentUID}
                        </span>
                      ))}
                    </div>
                  </div>
                )}
                {selectedUID.child_uids && selectedUID.child_uids.length > 0 && (
                  <div>
                    <p className="text-sm text-gray-600 mb-2">⬇ Child Components ({selectedUID.child_uids.length})</p>
                    <div className="flex flex-wrap gap-2">
                      {selectedUID.child_uids.map((childUID, idx) => (
                        <span key={idx} className="px-3 py-1 bg-green-50 text-green-700 rounded text-sm font-mono">
                          {childUID}
                        </span>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* Source Traceability */}
            {selectedUID.supplier_id && (
              <div className="bg-yellow-50 p-4 rounded-lg mb-4">
                <h3 className="font-semibold mb-2">📦 Source Traceability</h3>
                <p className="text-sm">
                  Supplier: {selectedUID.vendorName || 'Unknown'}
                  {selectedUID.vendorCode && <span className="text-gray-500 ml-2">({selectedUID.vendorCode})</span>}
                </p>
                {selectedUID.purchase_order_id && (
                  <p className="text-sm">
                    PO: {selectedUID.purchase_order?.po_number || selectedUID.purchase_order_id}
                  </p>
                )}
                {selectedUID.grn_id && (
                  <p className="text-sm">
                    GRN: {selectedUID.grnNumber || selectedUID.grn_id}
                  </p>
                )}
                {selectedUID.batch_number && (
                  <p className="text-sm">Batch: {selectedUID.batch_number}</p>
                )}
              </div>
            )}

            {/* Quality Status */}
            {selectedUID.quality_status && (
              <div className="bg-green-50 p-4 rounded-lg mb-4">
                <h3 className="font-semibold mb-2">✅ Quality Status</h3>
                <p className="text-sm">{selectedUID.quality_status}</p>
              </div>
            )}

            {/* Lifecycle Timeline */}
            {selectedUID.lifecycle && selectedUID.lifecycle.length > 0 && (
              <div className="bg-blue-50 p-4 rounded-lg mb-4">
                <h3 className="font-semibold mb-3">📅 Lifecycle Timeline</h3>
                <div className="space-y-3">
                  {selectedUID.lifecycle.map((event: any, idx: number) => (
                    <div key={idx} className="flex items-start">
                      <div className="flex-shrink-0 w-24 text-xs text-gray-500">
                        {new Date(event.timestamp).toLocaleDateString()}
                      </div>
                      <div className="flex-1">
                        <p className="text-sm font-medium text-gray-900">{event.stage}</p>
                        <p className="text-xs text-gray-600">
                          Location: {event.location}
                          {event.reference && ` | Ref: ${event.reference}`}
                        </p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="mt-6 flex gap-2">
              <button
                onClick={() => window.print()}
                className="flex-1 bg-amber-600 text-white px-4 py-2 rounded-lg hover:bg-amber-700"
              >
                Print Report
              </button>
              <button
                onClick={() => setShowTraceModal(false)}
                className="flex-1 bg-gray-200 text-gray-800 px-4 py-2 rounded-lg hover:bg-gray-300"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Part Number Edit Modal */}
      {showPartNumberModal && editingUID && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-lg max-w-md w-full p-6">
            <h2 className="text-xl font-bold mb-4">Edit Part Number</h2>
            
            <div className="mb-4">
              <p className="text-sm text-gray-600 mb-2">UID: <span className="font-mono font-semibold">{editingUID.uid}</span></p>
            </div>

            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Client Part Number
              </label>
              <input
                type="text"
                value={partNumberInput}
                onChange={(e) => setPartNumberInput(e.target.value)}
                placeholder="Enter part number (e.g., 53022)"
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                autoFocus
              />
              <p className="text-xs text-gray-500 mt-1">Leave empty to remove part number</p>
            </div>

            <div className="flex gap-3">
              <button
                onClick={updatePartNumber}
                className="flex-1 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 font-medium"
              >
                Save
              </button>
              <button
                onClick={() => {
                  setShowPartNumberModal(false);
                  setEditingUID(null);
                  setPartNumberInput('');
                }}
                className="flex-1 bg-gray-200 text-gray-800 px-4 py-2 rounded-lg hover:bg-gray-300"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, Suspense } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';

interface LifecycleEvent {
  stage: string;
  timestamp: string;
  location: string;
  reference: string;
  user: string;
}

interface Component {
  uid: string;
  item_code: string;
  item_name: string;
  batch_number: string;
  vendor_name?: string;
  received_date: string;
  qc_status: string;
}

interface UIDTrace {
  uid: string;
  entity_type: string;
  item: {
    code: string;
    name: string;
    category: string;
  };
  status: string;
  location: string;
  batch_number?: string;
  lifecycle: LifecycleEvent[];
  components: Component[];
  parent_products: Array<{
    uid: string;
    item_code: string;
    item_name: string;
  }>;
  vendor: {
    name: string;
    code: string;
    contact: string;
  } | null;
  purchase_order?: {
    po_number: string;
    order_date: string;
    total_amount: number;
  } | null;
  grn?: {
    grn_number: string;
    grn_date: string;
  } | null;
  quality_checkpoints: Array<{
    stage: string;
    status: string;
    date: string;
    inspector: string;
    notes: string;
  }>;
  customer: {
    name: string;
    location: string;
    delivery_date: string;
    invoice_number: string;
  } | null;
}

function TraceProductContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [searchUID, setSearchUID] = useState(searchParams?.get('uid') || '');
  const [traceData, setTraceData] = useState<UIDTrace | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const searchTrace = async () => {
    if (!searchUID.trim()) {
      setError('Please enter a UID');
      return;
    }

    setLoading(true);
    setError('');

    try {
      const token = localStorage.getItem('accessToken');
      const response = await fetch(`/api/v1/uid/trace/${encodeURIComponent(searchUID)}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!response.ok) throw new Error('UID not found');

      const data = await response.json();
      console.log('[Frontend] Received trace data:', data);
      console.log('[Frontend] Vendor data:', data.vendor);
      console.log('[Frontend] Purchase order data:', data.purchase_order);
      setTraceData(data);
    } catch (err: any) {
      setError(err.message || 'Failed to fetch trace data');
      setTraceData(null);
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleString('en-IN', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const getStageIcon = (stage: string) => {
    if (stage.includes('RECEIVED') || stage.includes('RECEIPT')) return '📦';
    if (stage.includes('QC') || stage.includes('QUALITY')) return '🔍';
    if (stage.includes('PRODUCTION') || stage.includes('ASSEMBLY')) return '🏭';
    if (stage.includes('SHIPPED') || stage.includes('DELIVERY')) return '🚚';
    if (stage.includes('DEFECT')) return '⚠️';
    if (stage.includes('REPAIR')) return '🔧';
    return '📍';
  };

  const getStatusColor = (status: string) => {
    const colors: Record<string, string> = {
      PASSED: 'bg-green-100 text-green-800',
      FAILED: 'bg-red-100 text-red-800',
      PENDING: 'bg-yellow-100 text-yellow-800',
      AVAILABLE: 'bg-blue-100 text-blue-800',
      CONSUMED: 'bg-purple-100 text-purple-800',
      DEFECTIVE: 'bg-red-100 text-red-800',
      IN_REPAIR: 'bg-orange-100 text-orange-800',
    };
    return colors[status] || 'bg-gray-100 text-gray-800';
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-orange-50 via-white to-amber-50 p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="bg-white rounded-lg shadow-lg p-6 mb-6">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h1 className="text-3xl font-bold text-gray-800">🔍 Product Traceability</h1>
              <p className="text-gray-600 mt-1">Complete lifecycle tracking from supplier to customer</p>
            </div>
            <button
              onClick={() => router.push('/dashboard/uid')}
              className="px-4 py-2 text-gray-600 hover:text-gray-800"
            >
              ← Back to UID Management
            </button>
          </div>

          {/* Search Bar */}
          <div className="flex gap-3">
            <input
              type="text"
              value={searchUID}
              onChange={(e) => setSearchUID(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && searchTrace()}
              placeholder="Enter UID (e.g., UID-SAIF-KOL-FG-000123-A1)"
              className="flex-1 px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent"
            />
            <button
              onClick={searchTrace}
              disabled={loading}
              className="px-8 py-3 bg-gradient-to-r from-orange-500 to-amber-500 text-white rounded-lg font-semibold hover:from-orange-600 hover:to-amber-600 disabled:opacity-50 disabled:cursor-not-allowed shadow-lg"
            >
              {loading ? 'Searching...' : 'Trace Product'}
            </button>
          </div>

          {error && (
            <div className="mt-4 p-4 bg-red-50 border border-red-200 rounded-lg text-red-700">
              {error}
            </div>
          )}
        </div>

        {traceData && (
          <>
            {/* Product Summary Card */}
            <div className="bg-white rounded-lg shadow-lg p-6 mb-6">
              <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                <div>
                  <h3 className="text-sm font-semibold text-gray-500 mb-2">Product UID</h3>
                  <p className="text-lg font-mono font-bold text-orange-600">{traceData.uid}</p>
                </div>
                <div>
                  <h3 className="text-sm font-semibold text-gray-500 mb-2">Product</h3>
                  <p className="font-bold text-gray-800">{traceData.item.code}</p>
                  <p className="text-sm text-gray-600">{traceData.item.name}</p>
                </div>
                <div>
                  <h3 className="text-sm font-semibold text-gray-500 mb-2">Current Status</h3>
                  <span className={`inline-block px-3 py-1 rounded-full text-sm font-semibold ${getStatusColor(traceData.status)}`}>
                    {traceData.status}
                  </span>
                </div>
                <div>
                  <h3 className="text-sm font-semibold text-gray-500 mb-2">Current Location</h3>
                  <p className="font-bold text-gray-800">📍 {traceData.location}</p>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
              {/* Visual Timeline */}
              <div className="lg:col-span-2">
                <div className="bg-white rounded-lg shadow-lg p-6">
                  <h2 className="text-xl font-bold text-gray-800 mb-4">📅 Complete Timeline</h2>
                  
                  <div className="relative">
                    {/* Timeline Line */}
                    <div className="absolute left-6 top-0 bottom-0 w-0.5 bg-gradient-to-b from-orange-500 via-amber-400 to-orange-500"></div>
                    
                    {/* Timeline Events */}
                    <div className="space-y-6">
                      {traceData.lifecycle.map((event, index) => (
                        <div key={index} className="relative pl-16">
                          {/* Timeline Dot */}
                          <div className="absolute left-3 w-6 h-6 bg-orange-500 rounded-full border-4 border-white shadow-lg flex items-center justify-center text-white text-xs">
                            {getStageIcon(event.stage)}
                          </div>
                          
                          {/* Event Card */}
                          <div className="bg-gradient-to-r from-orange-50 to-amber-50 rounded-lg p-4 hover:shadow-md transition-shadow">
                            <div className="flex justify-between items-start mb-2">
                              <div>
                                <h3 className="font-bold text-gray-800">{event.stage.replace(/_/g, ' ')}</h3>
                                <p className="text-sm text-gray-600">{event.location}</p>
                              </div>
                              <span className="text-xs text-gray-500">
                                {formatDate(event.timestamp)}
                              </span>
                            </div>
                            
                            <div className="text-sm text-gray-700 mt-2">
                              <p><strong>Reference:</strong> {event.reference}</p>
                              <p><strong>By:</strong> {event.user}</p>
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </div>

              {/* Right Column - Additional Info */}
              <div className="space-y-6">
                {/* Vendor Details */}
                {traceData.vendor && (
                  <div className="bg-white rounded-lg shadow-lg p-6">
                    <h2 className="text-xl font-bold text-gray-800 mb-4">🏢 Vendor Details</h2>
                    <div className="space-y-3">
                      <div>
                        <p className="text-sm text-gray-500">Vendor Code</p>
                        <p className="font-bold text-gray-800">{traceData.vendor.code}</p>
                      </div>
                      <div>
                        <p className="text-sm text-gray-500">Vendor Name</p>
                        <p className="font-bold text-gray-800">{traceData.vendor.name}</p>
                      </div>
                      <div>
                        <p className="text-sm text-gray-500">Contact</p>
                        <p className="text-gray-700">{traceData.vendor.contact}</p>
                      </div>
                    </div>
                  </div>
                )}

                {/* Purchase Order Details */}
                {traceData.purchase_order && (
                  <div className="bg-white rounded-lg shadow-lg p-6">
                    <h2 className="text-xl font-bold text-gray-800 mb-4">📋 Purchase Order</h2>
                    <div className="space-y-3">
                      <div>
                        <p className="text-sm text-gray-500">PO Number</p>
                        <p className="font-bold text-gray-800">{traceData.purchase_order.po_number}</p>
                      </div>
                      <div>
                        <p className="text-sm text-gray-500">Order Date</p>
                        <p className="text-gray-700">{new Date(traceData.purchase_order.order_date).toLocaleDateString('en-IN')}</p>
                      </div>
                      <div>
                        <p className="text-sm text-gray-500">Total Amount</p>
                        <p className="text-gray-700">₹{traceData.purchase_order.total_amount.toLocaleString('en-IN')}</p>
                      </div>
                    </div>
                  </div>
                )}

                {/* GRN Details */}
                {traceData.grn && (
                  <div className="bg-white rounded-lg shadow-lg p-6">
                    <h2 className="text-xl font-bold text-gray-800 mb-4">📦 Goods Receipt</h2>
                    <div className="space-y-3">
                      <div>
                        <p className="text-sm text-gray-500">GRN Number</p>
                        <p className="font-bold text-gray-800">{traceData.grn.grn_number}</p>
                      </div>
                      <div>
                        <p className="text-sm text-gray-500">Receipt Date</p>
                        <p className="text-gray-700">{new Date(traceData.grn.grn_date).toLocaleDateString('en-IN')}</p>
                      </div>
                      {traceData.batch_number && (
                        <div>
                          <p className="text-sm text-gray-500">Batch Number</p>
                          <p className="text-gray-700">{traceData.batch_number}</p>
                        </div>
                      )}
                    </div>
                  </div>
                )}

                {/* Quality Checkpoints */}
                <div className="bg-white rounded-lg shadow-lg p-6">
                  <h2 className="text-xl font-bold text-gray-800 mb-4">✅ Quality Checkpoints</h2>
                  {traceData.quality_checkpoints.length > 0 ? (
                    <div className="space-y-3">
                      {traceData.quality_checkpoints.map((qc, index) => (
                        <div key={index} className="border-l-4 border-orange-500 pl-3 py-2">
                          <div className="flex justify-between items-start mb-1">
                            <p className="font-semibold text-gray-800">{qc.stage}</p>
                            <span className={`px-2 py-1 rounded text-xs font-bold ${getStatusColor(qc.status)}`}>
                              {qc.status}
                            </span>
                          </div>
                          <p className="text-xs text-gray-500">{formatDate(qc.date)}</p>
                          <p className="text-sm text-gray-600 mt-1">{qc.inspector}</p>
                          {qc.notes && (
                            <p className="text-sm text-gray-700 mt-1 italic">{qc.notes}</p>
                          )}
                        </div>
                      ))}
                    </div>
                  ) : (
                    <p className="text-gray-500 text-sm">No quality checkpoints recorded</p>
                  )}
                </div>

                {/* Customer Location */}
                {traceData.customer && (
                  <div className="bg-white rounded-lg shadow-lg p-6">
                    <h2 className="text-xl font-bold text-gray-800 mb-4">👤 Customer Details</h2>
                    <div className="space-y-3">
                      <div>
                        <p className="text-sm text-gray-500">Customer Name</p>
                        <p className="font-bold text-gray-800">{traceData.customer.name}</p>
                      </div>
                      <div>
                        <p className="text-sm text-gray-500">Location</p>
                        <p className="text-gray-700">📍 {traceData.customer.location}</p>
                      </div>
                      <div>
                        <p className="text-sm text-gray-500">Delivery Date</p>
                        <p className="text-gray-700">{formatDate(traceData.customer.delivery_date)}</p>
                      </div>
                      <div>
                        <p className="text-sm text-gray-500">Invoice Number</p>
                        <p className="font-mono text-gray-800">{traceData.customer.invoice_number}</p>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            </div>

            {/* Component Tree Diagram - Enhanced Hierarchical View */}
            {traceData.components.length > 0 && (
              <div className="bg-white rounded-lg shadow-lg p-6 mt-6">
                <h2 className="text-xl font-bold mb-4" style={{ color: '#6F4E37' }}>🌳 Component Tree - Hierarchical Structure</h2>
                <p className="text-sm text-gray-600 mb-6">
                  This product was assembled from {traceData.components.length} component(s). Each branch shows the complete traceability.
                </p>
                
                {/* Hierarchical Tree Visualization */}
                <div className="relative">
                  {/* Root Product */}
                  <div className="flex items-center justify-center mb-8">
                    <div className="relative p-4 rounded-lg border-2 shadow-lg text-center min-w-[300px]" 
                         style={{ borderColor: '#8B6F47', backgroundColor: '#FAF8F3' }}>
                      <div className="text-xs font-semibold mb-1" style={{ color: '#6F4E37' }}>FINAL PRODUCT</div>
                      <div className="font-mono text-sm font-bold mb-1" style={{ color: '#8B6F47' }}>{traceData.uid}</div>
                      <div className="text-sm font-semibold">{traceData.item.code}</div>
                      <div className="text-xs text-gray-600">{traceData.item.name}</div>
                      <div className={`inline-block px-2 py-1 rounded text-xs font-bold mt-2 ${getStatusColor(traceData.status)}`}>
                        {traceData.status}
                      </div>
                    </div>
                  </div>
                  
                  {/* Connecting Lines */}
                  {traceData.components.length > 0 && (
                    <div className="flex justify-center mb-4">
                      <div className="w-0.5 h-8" style={{ backgroundColor: '#8B6F47' }}></div>
                    </div>
                  )}
                  
                  {/* Component Branches */}
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 relative">
                    {traceData.components.map((component, index) => (
                      <div key={index} className="relative">
                        {/* Branch Line */}
                        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-0.5 h-4 -mt-4" 
                             style={{ backgroundColor: '#8B6F47' }}></div>
                        
                        {/* Component Card */}
                        <div className="relative p-4 rounded-lg border-2 hover:shadow-xl transition-all cursor-pointer group"
                             style={{ borderColor: '#E8DCC4', backgroundColor: '#FFFFFF' }}
                             onClick={() => {
                               setSearchUID(component.uid);
                               searchTrace();
                             }}>
                          
                          {/* Branch Number Badge */}
                          <div className="absolute -top-3 -left-3 w-8 h-8 rounded-full flex items-center justify-center font-bold text-white text-sm"
                               style={{ backgroundColor: '#8B6F47' }}>
                            {index + 1}
                          </div>
                          
                          {/* UID and Status */}
                          <div className="mb-3 pb-3 border-b" style={{ borderColor: '#E8DCC4' }}>
                            <div className="flex items-center justify-between mb-2">
                              <span className="font-mono text-xs font-bold" style={{ color: '#8B6F47' }}>
                                {component.uid}
                              </span>
                              <span className={`px-2 py-0.5 rounded text-xs font-bold ${getStatusColor(component.qc_status)}`}>
                                {component.qc_status}
                              </span>
                            </div>
                          </div>
                          
                          {/* Component Details */}
                          <div className="space-y-2 text-sm">
                            <div>
                              <p className="text-xs text-gray-500 uppercase">Item</p>
                              <p className="font-semibold text-gray-800">{component.item_code}</p>
                              <p className="text-xs text-gray-600">{component.item_name}</p>
                            </div>
                            
                            <div className="grid grid-cols-2 gap-2 pt-2">
                              <div>
                                <p className="text-xs text-gray-500">Batch</p>
                                <p className="font-mono text-xs font-semibold">{component.batch_number}</p>
                              </div>
                              
                              <div>
                                <p className="text-xs text-gray-500">Received</p>
                                <p className="text-xs">{new Date(component.received_date).toLocaleDateString()}</p>
                              </div>
                            </div>
                            
                            {component.vendor_name && (
                              <div className="pt-2 border-t" style={{ borderColor: '#E8DCC4' }}>
                                <p className="text-xs text-gray-500">Vendor</p>
                                <p className="text-xs font-semibold">{component.vendor_name}</p>
                              </div>
                            )}
                          </div>
                          
                          {/* Hover Action */}
                          <div className="mt-3 pt-3 border-t flex items-center justify-center text-xs font-semibold transition-colors"
                               style={{ borderColor: '#E8DCC4', color: '#6F4E37' }}>
                            <span className="group-hover:underline">→ Click to trace this component</span>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                  
                  {/* Tree Legend */}
                  <div className="mt-6 p-4 rounded-lg" style={{ backgroundColor: '#FAF8F3' }}>
                    <div className="flex items-center gap-6 text-xs text-gray-600">
                      <div className="flex items-center gap-2">
                        <div className="w-4 h-4 rounded-full" style={{ backgroundColor: '#8B6F47' }}></div>
                        <span>Component Level</span>
                      </div>
                      <div className="flex items-center gap-2">
                        <div className="w-4 h-0.5" style={{ backgroundColor: '#8B6F47' }}></div>
                        <span>Assembly Relationship</span>
                      </div>
                      <div className="flex items-center gap-2">
                        <span className="font-mono font-bold" style={{ color: '#8B6F47' }}>UID</span>
                        <span>Click to drill down</span>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Parent Products (if this component is used in other products) */}
            {traceData.parent_products.length > 0 && (
              <div className="bg-white rounded-lg shadow-lg p-6 mt-6">
                <h2 className="text-xl font-bold text-gray-800 mb-4">⬆️ Used In Products</h2>
                <p className="text-sm text-gray-600 mb-4">
                  This component/material was used in the following products:
                </p>
                
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {traceData.parent_products.map((parent, index) => (
                    <div key={index} className="p-4 border-2 border-orange-200 rounded-lg hover:border-orange-400 transition-colors">
                      <p className="font-mono text-sm font-bold text-orange-600 mb-2">{parent.uid}</p>
                      <p className="font-semibold text-gray-800">{parent.item_code}</p>
                      <p className="text-sm text-gray-600">{parent.item_name}</p>
                      <button
                        onClick={() => {
                          setSearchUID(parent.uid);
                          searchTrace();
                        }}
                        className="mt-2 text-xs text-orange-600 hover:text-orange-800 font-semibold"
                      >
                        → Trace this product
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </>
        )}

        {!traceData && !loading && !error && (
          <div className="bg-white rounded-lg shadow-lg p-12 text-center">
            <div className="text-6xl mb-4">🔍</div>
            <h2 className="text-2xl font-bold text-gray-800 mb-2">Search for a Product UID</h2>
            <p className="text-gray-600">
              Enter a UID above to view complete traceability from supplier to customer
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

export default function TraceProductPage() {
  return (
    <Suspense fallback={
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-lg">Loading...</div>
      </div>
    }>
      <TraceProductContent />
    </Suspense>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { apiClient } from '../../../../lib/api-client';

interface WorkStation {
  id: string;
  station_name: string;
  station_code: string;
  station_type: string;
  capacity: number;
  is_active: boolean;
  description: string | null;
  created_at: string;
}

export default function WorkStationsPage() {
  const [workStations, setWorkStations] = useState<WorkStation[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // Form state
  const [formData, setFormData] = useState({
    stationName: '',
    stationCode: '',
    stationType: 'MACHINING',
    capacity: 1,
    isActive: true,
    description: '',
  });

  const stationTypes = [
    'MACHINING',
    'ASSEMBLY',
    'WELDING',
    'PAINTING',
    'TESTING',
    'PACKAGING',
    'OTHER',
  ];

  useEffect(() => {
    fetchWorkStations();
  }, []);

  const fetchWorkStations = async () => {
    setLoading(true);
    try {
      console.log('Fetching work stations');
      const data = await apiClient.get('/production/work-stations');
      console.log('Received data:', data);
      // Ensure data is always an array
      const stationsArray = Array.isArray(data) ? data : (data?.data ? data.data : []);
      setWorkStations(stationsArray);
    } catch (error) {
      console.error('Failed to fetch work stations:', error);
      setWorkStations([]);
      alert('Failed to load work stations: ' + (error instanceof Error ? error.message : 'Unknown error'));
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      if (editingId) {
        await apiClient.put(`/production/work-stations/${editingId}`, formData);
      } else {
        await apiClient.post('/production/work-stations', formData);
      }

      alert(editingId ? 'Work station updated successfully' : 'Work station created successfully');
      resetForm();
      fetchWorkStations();
    } catch (error: any) {
      console.error('Save error:', error);
      alert('Failed to save work station: ' + (error.message || 'Unknown error'));
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (station: WorkStation) => {
    setFormData({
      stationName: station.station_name,
      stationCode: station.station_code,
      stationType: station.station_type,
      capacity: station.capacity,
      isActive: station.is_active,
      description: station.description || '',
    });
    setEditingId(station.id);
    setShowForm(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this work station?')) return;

    setLoading(true);
    try {
      await apiClient.delete(`/production/work-stations/${id}`);
      alert('Work station deleted successfully');
      fetchWorkStations();
    } catch (error: any) {
      alert(error.response?.data?.message || 'Failed to delete work station');
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setFormData({
      stationName: '',
      stationCode: '',
      stationType: 'MACHINING',
      capacity: 1,
      isActive: true,
      description: '',
    });
    setEditingId(null);
    setShowForm(false);
  };

  return (
    <div className="container mx-auto py-6 px-4">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Work Stations</h1>
          <p className="text-gray-600 mt-1">Manage production work centers and workstations</p>
        </div>
        <button
          onClick={() => setShowForm(!showForm)}
          className="bg-blue-600 text-white px-6 py-2 rounded-lg hover:bg-blue-700 font-medium"
        >
          {showForm ? 'Cancel' : '+ New Work Station'}
        </button>
      </div>

      {/* Form */}
      {showForm && (
        <div className="bg-white rounded-lg shadow p-6 mb-6">
          <h2 className="text-xl font-bold text-gray-900 mb-4">
            {editingId ? 'Edit Work Station' : 'Create Work Station'}
          </h2>

          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Name <span className="text-red-600">*</span>
                </label>
                <input
                  type="text"
                  required
                  value={formData.stationName}
                  onChange={(e) => setFormData({ ...formData, stationName: e.target.value })}
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  placeholder="e.g., CNC Machine 1"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Code <span className="text-red-600">*</span>
                </label>
                <input
                  type="text"
                  required
                  value={formData.stationCode}
                  onChange={(e) => setFormData({ ...formData, stationCode: e.target.value })}
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  placeholder="e.g., WS-CNC-01"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Station Type <span className="text-red-600">*</span>
                </label>
                <select
                  required
                  value={formData.stationType}
                  onChange={(e) => setFormData({ ...formData, stationType: e.target.value })}
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                >
                  {stationTypes.map((type) => (
                    <option key={type} value={type}>
                      {type}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Capacity (operators) <span className="text-red-600">*</span>
                </label>
                <input
                  type="number"
                  required
                  min="1"
                  value={formData.capacity}
                  onChange={(e) => setFormData({ ...formData, capacity: parseInt(e.target.value) })}
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Description (Optional)
              </label>
              <textarea
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                rows={3}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                placeholder="Additional details about this work station..."
              />
            </div>

            <div className="flex items-center">
              <input
                type="checkbox"
                id="is_active"
                checked={formData.isActive}
                onChange={(e) => setFormData({ ...formData, isActive: e.target.checked })}
                className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
              />
              <label htmlFor="is_active" className="ml-2 text-sm text-gray-700">
                Active
              </label>
            </div>

            <div className="flex justify-end space-x-4">
              <button
                type="button"
                onClick={resetForm}
                className="px-6 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 font-medium"
              >
                Cancel
              </button>
              <button
                type="submit"
                disabled={loading}
                className="bg-blue-600 text-white px-6 py-2 rounded-lg hover:bg-blue-700 disabled:bg-gray-300 disabled:cursor-not-allowed font-medium"
              >
                {loading ? 'Saving...' : editingId ? 'Update' : 'Create'}
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Table */}
      <div className="bg-white rounded-lg shadow">
        {loading && !showForm ? (
          <div className="px-6 py-12 text-center text-gray-500">Loading...</div>
        ) : workStations.length === 0 ? (
          <div className="px-6 py-12 text-center text-gray-500">
            No work stations found. Create one to get started.
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Code
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Name
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Type
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Capacity
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Status
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Actions
                  </th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {workStations.map((station) => (
                  <tr key={station.id} className="hover:bg-gray-50">
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                      {station.station_code}
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-900">
                      {station.station_name}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      {station.station_type}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      {station.capacity} operator{station.capacity !== 1 ? 's' : ''}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span
                        className={`px-2 py-1 rounded-full text-xs font-medium ${
                          station.is_active
                            ? 'bg-green-100 text-green-800'
                            : 'bg-gray-100 text-gray-800'
                        }`}
                      >
                        {station.is_active ? 'Active' : 'Inactive'}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm space-x-2">
                      <button
                        onClick={() => handleEdit(station)}
                        className="text-blue-600 hover:text-blue-900 font-medium"
                      >
                        Edit
                      </button>
                      <button
                        onClick={() => handleDelete(station.id)}
                        className="text-red-600 hover:text-red-900 font-medium"
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';

interface Customer {
  id: string;
  customer_name: string;
  customer_code: string;
  contact_email: string;
  contact_person: string;
}

interface ProductInfo {
  uid: string;
  client_part_number: string;
  job_order_id: string;
  current_level: string;
  current_organization: string;
  current_location: string;
  current_deployment_date: string;
  original_customer: string;
  warranty_expiry_date: string;
  contact_person: string;
  contact_email: string;
  contact_phone: string;
}

interface DeploymentHistory {
  deployment_level: string;
  organization_name: string;
  location_name: string;
  deployment_date: string;
  deployment_notes: string;
}

export default function WarrantyPortalPage() {
  const router = useRouter();
  const [activeTab, setActiveTab] = useState<'search' | 'register'>('search');
  const [searchType, setSearchType] = useState<'part_number' | 'access_token'>('part_number');
  const [searchValue, setSearchValue] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [productInfo, setProductInfo] = useState<ProductInfo | null>(null);
  const [deploymentHistory, setDeploymentHistory] = useState<DeploymentHistory[]>([]);
  const [showUpdateForm, setShowUpdateForm] = useState(false);
  
  // Customer list for autocomplete
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [filteredCustomers, setFilteredCustomers] = useState<Customer[]>([]);
  const [showCustomerDropdown, setShowCustomerDropdown] = useState(false);
  
  // Update form state
  const [updateForm, setUpdateForm] = useState({
    deployment_level: 'END_LOCATION',
    organization_name: '',
    location_name: '',
    deployment_notes: '',
  });
  
  // Registration form state
  const [registrationForm, setRegistrationForm] = useState({
    uid: '',
    part_number: '',
    customer_name: '',
    customer_email: '',
    customer_phone: '',
    customer_address: '',
    purchase_date: '',
    dealer_name: '',
    invoice_number: '',
    warranty_years: '1',
    vessel: '',
    location: '',
  });

  const [customerNameLocked, setCustomerNameLocked] = useState(false);
  
  // Fetch customers on mount
  useEffect(() => {
    fetchCustomers();
  }, []);
  
  const fetchCustomers = async () => {
    try {
      const response = await fetch('/api/v1/sales/customers', {
        credentials: 'include',
      });
      if (response.ok) {
        const data = await response.json();
        setCustomers(data);
        setFilteredCustomers(data);
      }
    } catch (err) {
      console.error('Failed to fetch customers:', err);
    }
  };

  // Auto-fill customer details from system when UID is entered
  useEffect(() => {
    const uid = registrationForm.uid.trim().toUpperCase();
    if (!uid || uid.length < 4) {
      setCustomerNameLocked(false);
      return;
    }

    const controller = new AbortController();
    const timeout = setTimeout(() => {
      void (async () => {
        try {
          const apiUrl =
            process.env.NEXT_PUBLIC_API_URL ||
            (typeof window !== 'undefined'
              ? `http://${window.location.hostname}:4000/api/v1`
              : 'http://localhost:4000/api/v1');

          const response = await fetch(
            `${apiUrl}/uid/deployment/status?uid=${encodeURIComponent(uid)}`,
            { signal: controller.signal },
          );
          if (!response.ok) return;
          const data = await response.json();
          const info = Array.isArray(data) ? data[0] : null;
          if (!info) return;

          const nextCustomerName = String(info.original_customer || info.current_organization || '').trim();
          const nextCustomerEmail = String(info.contact_email || '').trim();
          const nextCustomerPhone = String(info.contact_phone || '').trim();

          setCustomerNameLocked(Boolean(nextCustomerName));

          setRegistrationForm((prev) => ({
            ...prev,
            uid,
            customer_name: nextCustomerName || prev.customer_name,
            customer_email: nextCustomerEmail || prev.customer_email,
            customer_phone: nextCustomerPhone || prev.customer_phone,
          }));
        } catch (err: any) {
          if (err?.name === 'AbortError') return;
          console.error('Failed to lookup UID customer details:', err);
          setCustomerNameLocked(false);
        }
      })();
    }, 450);

    return () => {
      controller.abort();
      clearTimeout(timeout);
    };
  }, [registrationForm.uid]);
  
  const handleCustomerNameChange = (value: string) => {
    setRegistrationForm({ ...registrationForm, customer_name: value });
    
    // Filter customers based on input
    const filtered = customers.filter(customer =>
      customer.customer_name.toLowerCase().includes(value.toLowerCase()) ||
      customer.customer_code.toLowerCase().includes(value.toLowerCase())
    );
    setFilteredCustomers(filtered);
    setShowCustomerDropdown(value.length > 0 && filtered.length > 0);
  };
  
  const selectCustomer = (customer: Customer) => {
    setRegistrationForm({
      ...registrationForm,
      customer_name: customer.customer_name,
      customer_email: customer.contact_email || registrationForm.customer_email,
    });
    setShowCustomerDropdown(false);
  };
  const [registrationSuccess, setRegistrationSuccess] = useState(false);
  const [registrationLoading, setRegistrationLoading] = useState(false);

  const handleSearch = async () => {
    if (!searchValue.trim()) {
      setError('Please enter a value to search');
      return;
    }

    setLoading(true);
    setError(null);
    setProductInfo(null);
    setDeploymentHistory([]);

    try {
      const apiUrl =
        process.env.NEXT_PUBLIC_API_URL ||
        (typeof window !== 'undefined'
          ? `http://${window.location.hostname}:4000/api/v1`
          : 'http://localhost:4000/api/v1');
      
      // Search by part number or access token
      const endpoint = searchType === 'part_number' 
        ? `/uid/search/part-number?part_number=${encodeURIComponent(searchValue)}`
        : `/uid/deployment/public/${searchValue}`;
      
      const response = await fetch(`${apiUrl}${endpoint}`);
      
      if (!response.ok) {
        throw new Error('Product not found');
      }
      
      const data = await response.json();
      
      if (searchType === 'part_number') {
        // Get deployment status for the UID
        const statusResponse = await fetch(`${apiUrl}/uid/deployment/status?uid=${data.uid}`);
        if (statusResponse.ok) {
          const statusData = await statusResponse.json();
          setProductInfo(statusData[0] || null);
          
          // Get deployment history
          const historyResponse = await fetch(`${apiUrl}/uid/deployment/history/${statusData[0]?.uid_id}`);
          if (historyResponse.ok) {
            const historyData = await historyResponse.json();
            setDeploymentHistory(historyData);
          }
        }
      } else {
        // Access token search returns deployment info directly
        setProductInfo(data.product);
        setDeploymentHistory(data.history || []);
      }
    } catch (err: any) {
      setError(err.message || 'Failed to fetch product information');
    } finally {
      setLoading(false);
    }
  };

  const handleUpdateDeployment = async () => {
    if (!productInfo) return;
    
    if (!updateForm.organization_name || !updateForm.location_name) {
      alert('Please fill in organization and location');
      return;
    }

    try {
      const apiUrl =
        process.env.NEXT_PUBLIC_API_URL ||
        (typeof window !== 'undefined'
          ? `http://${window.location.hostname}:4000/api/v1`
          : 'http://localhost:4000/api/v1');
      const response = await fetch(`${apiUrl}/uid/deployment`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          uid: productInfo.uid,
          ...updateForm,
        }),
      });

      if (!response.ok) throw new Error('Failed to update deployment');

      alert('Deployment location updated successfully!');
      setShowUpdateForm(false);
      // Refresh data
      handleSearch();
    } catch (err: any) {
      alert(err.message || 'Failed to update deployment');
    }
  };

  const getLevelBadgeColor = (level: string) => {
    switch (level) {
      case 'CUSTOMER': return 'bg-amber-100 text-amber-800';
      case 'DEPOT': return 'bg-yellow-100 text-yellow-800';
      case 'END_LOCATION': return 'bg-green-100 text-green-800';
      case 'SERVICE_CENTER': return 'bg-orange-100 text-orange-800';
      case 'RETURNED': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };
  
  const handleWarrantyRegistration = async () => {
    if (!registrationForm.uid || !registrationForm.customer_name || !registrationForm.customer_email || !registrationForm.purchase_date) {
      alert('Please fill in all required fields (UID, Name, Email, Purchase Date)');
      return;
    }
    
    setRegistrationLoading(true);
    
    try {
      const apiUrl =
        process.env.NEXT_PUBLIC_API_URL ||
        (typeof window !== 'undefined'
          ? `http://${window.location.hostname}:4000/api/v1`
          : 'http://localhost:4000/api/v1');
      
      // Calculate warranty expiry
      const purchaseDate = new Date(registrationForm.purchase_date);
      const warrantyExpiry = new Date(purchaseDate);
      warrantyExpiry.setFullYear(warrantyExpiry.getFullYear() + parseInt(registrationForm.warranty_years));

      const deploymentLocation = (() => {
        const vessel = registrationForm.vessel.trim();
        const location = registrationForm.location.trim();
        if (vessel && location) return `${vessel} / ${location}`;
        if (vessel) return vessel;
        if (location) return location;
        return registrationForm.customer_address || 'Customer Location';
      })();
      
      // Create initial deployment record
      const response = await fetch(`${apiUrl}/uid/deployment`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          uid: registrationForm.uid,
          deployment_level: 'CUSTOMER',
          organization_name: registrationForm.customer_name,
          location_name: deploymentLocation,
          deployment_date: registrationForm.purchase_date,
          contact_person: registrationForm.customer_name,
          contact_email: registrationForm.customer_email,
          contact_phone: registrationForm.customer_phone,
          deployment_notes: `Warranty Registration - Invoice: ${registrationForm.invoice_number || 'N/A'}, Dealer: ${registrationForm.dealer_name || 'N/A'}`,
          warranty_expiry_date: warrantyExpiry.toISOString().split('T')[0],
          is_current_location: true,
        }),
      });
      
      if (!response.ok) throw new Error('Failed to register warranty');
      
      setRegistrationSuccess(true);
      alert('Warranty registered successfully! You will receive a confirmation email shortly.');
      
      // Reset form
      setRegistrationForm({
        uid: '',
        part_number: '',
        customer_name: '',
        customer_email: '',
        customer_phone: '',
        customer_address: '',
        purchase_date: '',
        dealer_name: '',
        invoice_number: '',
        warranty_years: '1',
        vessel: '',
        location: '',
      });
    } catch (err: any) {
      alert(err.message || 'Failed to register warranty');
    } finally {
      setRegistrationLoading(false);
    }
  };

  return (
    <div className="min-h-screen" style={{ background: 'linear-gradient(to bottom right, #FAF8F3, #E8DCC4)' }}>
      {/* Header */}
      <div className="bg-white shadow-sm border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-3xl font-bold text-gray-900">🛡️ Warranty Portal</h1>
              <p className="mt-1 text-sm text-gray-600">Track your product warranty and deployment information</p>
            </div>
            <button
              onClick={() => router.push('/dashboard')}
              className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50"
            >
              ← Back to Dashboard
            </button>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Tab Navigation */}
        <div className="flex gap-4 mb-6">
          <button
            onClick={() => setActiveTab('search')}
            className={`px-6 py-3 rounded-lg font-medium transition-all ${
              activeTab === 'search'
                ? 'text-white shadow-lg'
                : 'bg-white text-gray-700 hover:bg-gray-50'
            }`}
            style={activeTab === 'search' ? { backgroundColor: '#6F4E37' } : {}}
          >
            🔍 Search Warranty
          </button>
          <button
            onClick={() => setActiveTab('register')}
            className={`px-6 py-3 rounded-lg font-medium transition-all ${
              activeTab === 'register'
                ? 'text-white shadow-lg'
                : 'bg-white text-gray-700 hover:bg-gray-50'
            }`}
            style={activeTab === 'register' ? { backgroundColor: '#6F4E37' } : {}}
          >
            📝 Register Product
          </button>
        </div>
        
        {/* Search Tab Content */}
        {activeTab === 'search' && (
          <>
        {/* Search Card */}
        <div className="bg-white rounded-xl shadow-lg p-6 mb-6">
          <h2 className="text-xl font-semibold text-gray-900 mb-4">Find Your Product</h2>
          
          {/* Search Type Toggle */}
          <div className="flex gap-4 mb-4">
            <button
              onClick={() => setSearchType('part_number')}
              className={`px-4 py-2 rounded-lg font-medium ${
                searchType === 'part_number'
                  ? 'text-white'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
              style={searchType === 'part_number' ? { backgroundColor: '#6F4E37' } : {}}
            >
              Search by Part Number
            </button>
            <button
              onClick={() => setSearchType('access_token')}
              className={`px-4 py-2 rounded-lg font-medium ${
                searchType === 'access_token'
                  ? 'text-white'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
              style={searchType === 'access_token' ? { backgroundColor: '#6F4E37' } : {}}
            >
              Search by Warranty Token
            </button>
          </div>

          {/* Search Input */}
          <div className="flex gap-3">
            <input
              type="text"
              value={searchValue}
              onChange={(e) => setSearchValue(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleSearch()}
              placeholder={
                searchType === 'part_number'
                  ? 'Enter part number (e.g., 53022)'
                  : 'Enter warranty token (e.g., WRT-XXXXX)'
              }
              className="flex-1 px-4 py-3 border-2 rounded-lg focus:ring-2 focus:outline-none"
              style={{ borderColor: '#E8DCC4' }}
              onFocus={(e) => { e.target.style.borderColor = '#8B6F47'; e.target.style.boxShadow = '0 0 0 3px rgba(139, 111, 71, 0.1)'; }}
              onBlur={(e) => { e.target.style.borderColor = '#E8DCC4'; e.target.style.boxShadow = 'none'; }}
            />
            <button
              onClick={handleSearch}
              disabled={loading}
              className="px-6 py-3 text-white rounded-lg disabled:bg-gray-400 font-medium transition-opacity hover:opacity-90"
              style={{ backgroundColor: loading ? '#9CA3AF' : '#6F4E37' }}
            >
              {loading ? 'Searching...' : 'Search'}
            </button>
          </div>

          {error && (
            <div className="mt-4 p-3 bg-red-50 border border-red-200 rounded-lg text-red-700 text-sm">
              {error}
            </div>
          )}
        </div>

        {/* Product Information */}
        {productInfo && (
          <>
            {/* Current Status Card */}
            <div className="bg-white rounded-xl shadow-lg p-6 mb-6">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-xl font-semibold text-gray-900">Current Status</h2>
                <button
                  onClick={() => setShowUpdateForm(!showUpdateForm)}
                  className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 text-sm font-medium"
                >
                  {showUpdateForm ? 'Cancel Update' : 'Update Location'}
                </button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <h3 className="text-sm font-medium text-gray-500 mb-2">Product Details</h3>
                  <div className="space-y-2">
                    <div>
                      <span className="text-xs text-gray-500">UID:</span>
                      <p className="font-semibold text-gray-900">{productInfo.uid}</p>
                    </div>
                    <div>
                      <span className="text-xs text-gray-500">Part Number:</span>
                      <p className="font-semibold text-gray-900">{productInfo.client_part_number}</p>
                    </div>
                    <div>
                      <span className="text-xs text-gray-500">Job Order:</span>
                      <p className="font-semibold text-gray-900">{productInfo.job_order_id || 'N/A'}</p>
                    </div>
                  </div>
                </div>

                <div>
                  <h3 className="text-sm font-medium text-gray-500 mb-2">Current Location</h3>
                  <div className="space-y-2">
                    <div>
                      <span className={`px-2 py-1 rounded text-xs font-semibold ${getLevelBadgeColor(productInfo.current_level)}`}>
                        {productInfo.current_level?.replace('_', ' ')}
                      </span>
                    </div>
                    <div>
                      <span className="text-xs text-gray-500">Organization:</span>
                      <p className="font-semibold text-gray-900">{productInfo.current_organization}</p>
                    </div>
                    <div>
                      <span className="text-xs text-gray-500">Location:</span>
                      <p className="font-semibold text-gray-900">{productInfo.current_location}</p>
                    </div>
                    <div>
                      <span className="text-xs text-gray-500">Since:</span>
                      <p className="font-semibold text-gray-900">
                        {productInfo.current_deployment_date ? new Date(productInfo.current_deployment_date).toLocaleDateString() : 'N/A'}
                      </p>
                    </div>
                  </div>
                </div>
              </div>

              {/* Warranty Info */}
              <div className="mt-6 pt-6 border-t border-gray-200">
                <h3 className="text-sm font-medium text-gray-500 mb-3">Warranty & Contact</h3>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <div>
                    <span className="text-xs text-gray-500">Warranty Expiry:</span>
                    <p className="font-semibold text-gray-900">
                      {productInfo.warranty_expiry_date 
                        ? new Date(productInfo.warranty_expiry_date).toLocaleDateString()
                        : 'N/A'}
                    </p>
                  </div>
                  <div>
                    <span className="text-xs text-gray-500">Contact Person:</span>
                    <p className="font-semibold text-gray-900">{productInfo.contact_person || 'N/A'}</p>
                  </div>
                  <div>
                    <span className="text-xs text-gray-500">Contact Details:</span>
                    <p className="text-sm text-gray-900">{productInfo.contact_email || productInfo.contact_phone || 'N/A'}</p>
                  </div>
                </div>
              </div>
            </div>

            {/* Update Form */}
            {showUpdateForm && (
              <div className="bg-white rounded-xl shadow-lg p-6 mb-6">
                <h2 className="text-xl font-semibold text-gray-900 mb-4">Update Deployment Location</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">Deployment Level</label>
                    <select
                      value={updateForm.deployment_level}
                      onChange={(e) => setUpdateForm({ ...updateForm, deployment_level: e.target.value })}
                      className="w-full px-3 py-2 border-2 rounded-lg focus:outline-none"
                      style={{ borderColor: '#E8DCC4' }}
                      onFocus={(e) => { e.currentTarget.style.borderColor = '#8B6F47'; }}
                      onBlur={(e) => { e.currentTarget.style.borderColor = '#E8DCC4'; }}
                    >
                      <option value="CUSTOMER">Customer</option>
                      <option value="DEPOT">Depot</option>
                      <option value="END_LOCATION">End Location</option>
                      <option value="SERVICE_CENTER">Service Center</option>
                      <option value="RETURNED">Returned</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">Organization Name *</label>
                    <input
                      type="text"
                      value={updateForm.organization_name}
                      onChange={(e) => setUpdateForm({ ...updateForm, organization_name: e.target.value })}
                      placeholder="e.g., Indian Navy"
                      className="w-full px-3 py-2 border-2 rounded-lg focus:outline-none"
                      style={{ borderColor: '#E8DCC4' }}
                      onFocus={(e) => { e.currentTarget.style.borderColor = '#8B6F47'; }}
                      onBlur={(e) => { e.currentTarget.style.borderColor = '#E8DCC4'; }}
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">Location Name *</label>
                    <input
                      type="text"
                      value={updateForm.location_name}
                      onChange={(e) => setUpdateForm({ ...updateForm, location_name: e.target.value })}
                      placeholder="e.g., INS Vikrant"
                      className="w-full px-3 py-2 border-2 rounded-lg focus:outline-none"
                      style={{ borderColor: '#E8DCC4' }}
                      onFocus={(e) => { e.currentTarget.style.borderColor = '#8B6F47'; }}
                      onBlur={(e) => { e.currentTarget.style.borderColor = '#E8DCC4'; }}
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">Notes (Optional)</label>
                    <input
                      type="text"
                      value={updateForm.deployment_notes}
                      onChange={(e) => setUpdateForm({ ...updateForm, deployment_notes: e.target.value })}
                      placeholder="Additional notes"
                      className="w-full px-3 py-2 border-2 rounded-lg focus:outline-none"
                      style={{ borderColor: '#E8DCC4' }}
                      onFocus={(e) => { e.currentTarget.style.borderColor = '#8B6F47'; }}
                      onBlur={(e) => { e.currentTarget.style.borderColor = '#E8DCC4'; }}
                    />
                  </div>
                </div>
                <div className="mt-4">
                  <button
                    onClick={handleUpdateDeployment}
                    className="px-6 py-2 text-white rounded-lg font-medium transition-opacity hover:opacity-90"
                    style={{ backgroundColor: '#6F4E37' }}
                  >
                    Submit Update
                  </button>
                </div>
              </div>
            )}

            {/* Deployment History */}
            {deploymentHistory.length > 0 && (
              <div className="bg-white rounded-xl shadow-lg p-6">
                <h2 className="text-xl font-semibold text-gray-900 mb-4">Deployment History</h2>
                <div className="space-y-4">
                  {deploymentHistory.map((deployment, index) => (
                    <div key={index} className="border-l-4 pl-4 py-2" style={{ borderColor: '#8B6F47' }}>
                      <div className="flex items-center gap-3 mb-1">
                        <span className={`px-2 py-1 rounded text-xs font-semibold ${getLevelBadgeColor(deployment.deployment_level)}`}>
                          {deployment.deployment_level.replace('_', ' ')}
                        </span>
                        <span className="text-sm text-gray-500">
                          {new Date(deployment.deployment_date).toLocaleDateString()}
                        </span>
                      </div>
                      <p className="font-semibold text-gray-900">{deployment.organization_name}</p>
                      <p className="text-sm text-gray-600">{deployment.location_name}</p>
                      {deployment.deployment_notes && (
                        <p className="text-sm text-gray-500 mt-1">{deployment.deployment_notes}</p>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            )}
          </>
        )}

        {/* Info Card */}
        {!productInfo && (
          <div className="rounded-xl p-6 border-2" style={{ backgroundColor: '#FAF8F3', borderColor: '#E8DCC4' }}>
            <h3 className="font-semibold mb-2" style={{ color: '#6F4E37' }}>How to use this portal:</h3>
            <ul className="space-y-2 text-sm" style={{ color: '#8B6F47' }}>
              <li>• <strong>Part Number Search:</strong> Enter the part number found on your product label</li>
              <li>• <strong>Warranty Token:</strong> Use the WRT-XXXXX code provided during purchase or deployment</li>
              <li>• <strong>Update Location:</strong> Click &quot;Update Location&quot; to report where your product is currently deployed</li>
              <li>• <strong>View History:</strong> See the complete deployment chain of your product</li>
            </ul>
          </div>
        )}
      </>
      )}

      {/* Registration Tab */}
      {activeTab === 'register' && (
        <>
          {/* Success Message */}
          {registrationSuccess && (
            <div className="rounded-xl p-6 border-2 mb-6" style={{ backgroundColor: '#E8F5E9', borderColor: '#4CAF50' }}>
              <div className="flex items-start gap-3">
                <svg className="w-6 h-6 flex-shrink-0 mt-0.5" style={{ color: '#4CAF50' }} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
                <div>
                  <h3 className="font-semibold text-lg mb-1" style={{ color: '#2E7D32' }}>Warranty Registration Successful!</h3>
                  <p className="text-sm" style={{ color: '#558B2F' }}>
                    Your product has been registered for warranty. You will receive a confirmation email shortly.
                  </p>
                </div>
              </div>
            </div>
          )}

          {/* Registration Form */}
          <div className="rounded-xl border-2 overflow-hidden" style={{ borderColor: '#E8DCC4' }}>
            <div className="px-6 py-4" style={{ backgroundColor: '#6F4E37' }}>
              <h2 className="text-xl font-bold text-white">Register Product for Warranty</h2>
              <p className="text-sm mt-1 text-white/90">Fill in the details below to activate your product warranty</p>
            </div>
            
            <div className="p-6" style={{ backgroundColor: '#FAF8F3' }}>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Product Details */}
                <div className="space-y-4">
                  <h3 className="font-semibold text-lg mb-4" style={{ color: '#6F4E37' }}>Product Details</h3>
                  
                  <div>
                    <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
                      Product UID / Serial Number *
                    </label>
                    <input
                      type="text"
                      value={registrationForm.uid}
                      onChange={(e) => setRegistrationForm({ ...registrationForm, uid: e.target.value.toUpperCase() })}
                      placeholder="e.g., DIO-SMD-PNJM7"
                      className="w-full px-4 py-2 border-2 rounded-lg focus:outline-none transition-colors"
                      style={{ borderColor: '#E8DCC4', backgroundColor: '#FFFFFF' }}
                      onFocus={(e) => { e.currentTarget.style.borderColor = '#8B6F47'; }}
                      onBlur={(e) => { e.currentTarget.style.borderColor = '#E8DCC4'; }}
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
                      Part Number (Optional)
                    </label>
                    <input
                      type="text"
                      value={registrationForm.part_number}
                      onChange={(e) => setRegistrationForm({ ...registrationForm, part_number: e.target.value })}
                      placeholder="e.g., DIO-SMD-001"
                      className="w-full px-4 py-2 border-2 rounded-lg focus:outline-none transition-colors"
                      style={{ borderColor: '#E8DCC4', backgroundColor: '#FFFFFF' }}
                      onFocus={(e) => { e.currentTarget.style.borderColor = '#8B6F47'; }}
                      onBlur={(e) => { e.currentTarget.style.borderColor = '#E8DCC4'; }}
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
                      Purchase Date *
                    </label>
                    <input
                      type="date"
                      value={registrationForm.purchase_date}
                      onChange={(e) => setRegistrationForm({ ...registrationForm, purchase_date: e.target.value })}
                      className="w-full px-4 py-2 border-2 rounded-lg focus:outline-none transition-colors"
                      style={{ borderColor: '#E8DCC4', backgroundColor: '#FFFFFF' }}
                      onFocus={(e) => { e.currentTarget.style.borderColor = '#8B6F47'; }}
                      onBlur={(e) => { e.currentTarget.style.borderColor = '#E8DCC4'; }}
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
                      Warranty Period (Years)
                    </label>
                    <select
                      value={registrationForm.warranty_years}
                      onChange={(e) => setRegistrationForm({ ...registrationForm, warranty_years: e.target.value })}
                      className="w-full px-4 py-2 border-2 rounded-lg focus:outline-none transition-colors"
                      style={{ borderColor: '#E8DCC4', backgroundColor: '#FFFFFF' }}
                      onFocus={(e) => { e.currentTarget.style.borderColor = '#8B6F47'; }}
                      onBlur={(e) => { e.currentTarget.style.borderColor = '#E8DCC4'; }}
                    >
                      <option value="1">1 Year</option>
                      <option value="2">2 Years</option>
                      <option value="3">3 Years</option>
                      <option value="5">5 Years</option>
                      <option value="10">10 Years</option>
                    </select>
                  </div>
                </div>

                {/* Customer Details */}
                <div className="space-y-4">
                  <h3 className="font-semibold text-lg mb-4" style={{ color: '#6F4E37' }}>Customer Details</h3>
                  
                  <div className="relative">
                    <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
                      Customer / Organization Name *
                    </label>
                    <input
                      type="text"
                      value={registrationForm.customer_name}
                      readOnly={customerNameLocked}
                      onChange={(e) => {
                        if (customerNameLocked) return;
                        handleCustomerNameChange(e.target.value);
                      }}
                      onFocus={() => {
                        if (customerNameLocked) return;
                        setShowCustomerDropdown(
                          registrationForm.customer_name.length > 0 && filteredCustomers.length > 0,
                        );
                      }}
                      onBlur={() => {
                        if (customerNameLocked) return;
                        setTimeout(() => setShowCustomerDropdown(false), 200);
                      }}
                      placeholder="Start typing customer name..."
                      className="w-full px-4 py-2 border-2 rounded-lg focus:outline-none transition-colors"
                      style={{ borderColor: '#E8DCC4', backgroundColor: '#FFFFFF' }}
                      onFocusCapture={(e) => { e.currentTarget.style.borderColor = '#8B6F47'; }}
                      onBlurCapture={(e) => { e.currentTarget.style.borderColor = '#E8DCC4'; }}
                    />
                    
                    {/* Autocomplete Dropdown */}
                    {showCustomerDropdown && (
                      <div 
                        className="absolute z-10 w-full mt-1 bg-white border-2 rounded-lg shadow-lg max-h-60 overflow-y-auto"
                        style={{ borderColor: '#E8DCC4' }}
                      >
                        {filteredCustomers.map((customer) => (
                          <div
                            key={customer.id}
                            onClick={() => selectCustomer(customer)}
                            className="px-4 py-3 cursor-pointer border-b transition-colors"
                            style={{ borderColor: '#F5F5F5' }}
                            onMouseEnter={(e) => { e.currentTarget.style.backgroundColor = '#FAF8F3'; }}
                            onMouseLeave={(e) => { e.currentTarget.style.backgroundColor = '#FFFFFF'; }}
                          >
                            <div className="font-medium" style={{ color: '#6F4E37' }}>
                              {customer.customer_name}
                            </div>
                            <div className="text-sm" style={{ color: '#8B6F47' }}>
                              Code: {customer.customer_code} {customer.contact_email && `• ${customer.contact_email}`}
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>

                  <div>
                    <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
                      Vessel (Optional)
                    </label>
                    <input
                      type="text"
                      value={registrationForm.vessel}
                      onChange={(e) => setRegistrationForm({ ...registrationForm, vessel: e.target.value })}
                      placeholder="Vessel name"
                      className="w-full px-4 py-2 border-2 rounded-lg focus:outline-none transition-colors"
                      style={{ borderColor: '#E8DCC4', backgroundColor: '#FFFFFF' }}
                      onFocus={(e) => { e.currentTarget.style.borderColor = '#8B6F47'; }}
                      onBlur={(e) => { e.currentTarget.style.borderColor = '#E8DCC4'; }}
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
                      Location (Optional)
                    </label>
                    <input
                      type="text"
                      value={registrationForm.location}
                      onChange={(e) => setRegistrationForm({ ...registrationForm, location: e.target.value })}
                      placeholder="Location"
                      className="w-full px-4 py-2 border-2 rounded-lg focus:outline-none transition-colors"
                      style={{ borderColor: '#E8DCC4', backgroundColor: '#FFFFFF' }}
                      onFocus={(e) => { e.currentTarget.style.borderColor = '#8B6F47'; }}
                      onBlur={(e) => { e.currentTarget.style.borderColor = '#E8DCC4'; }}
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
                      Email Address *
                    </label>
                    <input
                      type="email"
                      value={registrationForm.customer_email}
                      onChange={(e) => setRegistrationForm({ ...registrationForm, customer_email: e.target.value })}
                      placeholder="customer@example.com"
                      className="w-full px-4 py-2 border-2 rounded-lg focus:outline-none transition-colors"
                      style={{ borderColor: '#E8DCC4', backgroundColor: '#FFFFFF' }}
                      onFocus={(e) => { e.currentTarget.style.borderColor = '#8B6F47'; }}
                      onBlur={(e) => { e.currentTarget.style.borderColor = '#E8DCC4'; }}
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
                      Phone Number (Optional)
                    </label>
                    <input
                      type="tel"
                      value={registrationForm.customer_phone}
                      onChange={(e) => setRegistrationForm({ ...registrationForm, customer_phone: e.target.value })}
                      placeholder="+91 XXXXX XXXXX"
                      className="w-full px-4 py-2 border-2 rounded-lg focus:outline-none transition-colors"
                      style={{ borderColor: '#E8DCC4', backgroundColor: '#FFFFFF' }}
                      onFocus={(e) => { e.currentTarget.style.borderColor = '#8B6F47'; }}
                      onBlur={(e) => { e.currentTarget.style.borderColor = '#E8DCC4'; }}
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
                      Address (Optional)
                    </label>
                    <textarea
                      value={registrationForm.customer_address}
                      onChange={(e) => setRegistrationForm({ ...registrationForm, customer_address: e.target.value })}
                      placeholder="Full Address"
                      rows={3}
                      className="w-full px-4 py-2 border-2 rounded-lg focus:outline-none transition-colors"
                      style={{ borderColor: '#E8DCC4', backgroundColor: '#FFFFFF' }}
                      onFocus={(e) => { e.currentTarget.style.borderColor = '#8B6F47'; }}
                      onBlur={(e) => { e.currentTarget.style.borderColor = '#E8DCC4'; }}
                    />
                  </div>
                </div>

                {/* Purchase Details */}
                <div className="space-y-4 md:col-span-2">
                  <h3 className="font-semibold text-lg mb-4" style={{ color: '#6F4E37' }}>Purchase Details (Optional)</h3>
                  
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
                        Dealer / Seller Name
                      </label>
                      <input
                        type="text"
                        value={registrationForm.dealer_name}
                        onChange={(e) => setRegistrationForm({ ...registrationForm, dealer_name: e.target.value })}
                        placeholder="Dealer Name"
                        className="w-full px-4 py-2 border-2 rounded-lg focus:outline-none transition-colors"
                        style={{ borderColor: '#E8DCC4', backgroundColor: '#FFFFFF' }}
                        onFocus={(e) => { e.currentTarget.style.borderColor = '#8B6F47'; }}
                        onBlur={(e) => { e.currentTarget.style.borderColor = '#E8DCC4'; }}
                      />
                    </div>

                    <div>
                      <label className="block text-sm font-medium mb-2" style={{ color: '#6F4E37' }}>
                        Invoice / Order Number
                      </label>
                      <input
                        type="text"
                        value={registrationForm.invoice_number}
                        onChange={(e) => setRegistrationForm({ ...registrationForm, invoice_number: e.target.value })}
                        placeholder="INV-XXXXX"
                        className="w-full px-4 py-2 border-2 rounded-lg focus:outline-none transition-colors"
                        style={{ borderColor: '#E8DCC4', backgroundColor: '#FFFFFF' }}
                        onFocus={(e) => { e.currentTarget.style.borderColor = '#8B6F47'; }}
                        onBlur={(e) => { e.currentTarget.style.borderColor = '#E8DCC4'; }}
                      />
                    </div>
                  </div>
                </div>
              </div>

              {/* Submit Button */}
              <div className="mt-8 flex justify-end gap-4">
                <button
                  onClick={() => {
                    setRegistrationForm({
                      uid: '', part_number: '', customer_name: '', customer_email: '',
                      customer_phone: '', customer_address: '', purchase_date: '',
                      dealer_name: '', invoice_number: '', warranty_years: '1',
                      vessel: '', location: ''
                    });
                    setRegistrationSuccess(false);
                  }}
                  className="px-6 py-2 border-2 rounded-lg font-medium transition-colors"
                  style={{ borderColor: '#E8DCC4', color: '#6F4E37' }}
                >
                  Clear Form
                </button>
                <button
                  onClick={handleWarrantyRegistration}
                  disabled={registrationLoading}
                  className="px-8 py-2 rounded-lg font-medium text-white transition-colors disabled:opacity-50"
                  style={{ backgroundColor: '#6F4E37' }}
                  onMouseEnter={(e) => { if (!registrationLoading) e.currentTarget.style.backgroundColor = '#8B6F47'; }}
                  onMouseLeave={(e) => { e.currentTarget.style.backgroundColor = '#6F4E37'; }}
                >
                  {registrationLoading ? 'Registering...' : 'Register Warranty'}
                </button>
              </div>

              {/* Info Note */}
              <div className="mt-6 p-4 rounded-lg border-2" style={{ backgroundColor: '#FFF9E6', borderColor: '#FFE082' }}>
                <p className="text-sm" style={{ color: '#6F4E37' }}>
                  <strong>Note:</strong> Fields marked with * are required. After registration, you will receive a confirmation email with your warranty details and token.
                </p>
              </div>
            </div>
          </div>
        </>
      )}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';

interface Drawing {
  id: string;
  file_name: string;
  file_url: string;
  file_type: string;
  file_size: number;
  version: number;
  revision_notes: string;
  is_active: boolean;
  uploaded_by: string;
  created_at: string;
  document_id?: string | null;
}

interface DocumentOption {
  id: string;
  title?: string | null;
  file_name?: string | null;
  file_url?: string | null;
  file_type?: string | null;
  file_size?: number | null;
  created_at?: string | null;
  document_type?: string | null;
}

interface DrawingManagerProps {
  itemId: string;
  itemCode: string;
  itemName: string;
  onClose: () => void;
  mandatory?: boolean;
}

export default function DrawingManager({ itemId, itemCode, itemName, onClose, mandatory = false }: DrawingManagerProps) {
  const [drawings, setDrawings] = useState<Drawing[]>([]);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [linking, setLinking] = useState(false);
  const [updatingActiveId, setUpdatingActiveId] = useState<string | null>(null);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [revisionNotes, setRevisionNotes] = useState('');
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);

  const [documents, setDocuments] = useState<DocumentOption[]>([]);
  const [documentsLoading, setDocumentsLoading] = useState(false);
  const [selectedDocumentId, setSelectedDocumentId] = useState<string>('');

  const dataUrlToBlob = (dataUrl: string) => {
    const match = dataUrl.match(/^data:(.+?);base64,(.+)$/);
    if (!match) return null;

    const mimeType = match[1];
    const base64Data = match[2];
    const byteString = atob(base64Data);
    const byteArray = new Uint8Array(byteString.length);
    for (let i = 0; i < byteString.length; i++) {
      byteArray[i] = byteString.charCodeAt(i);
    }

    return new Blob([byteArray], { type: mimeType });
  };

  const openDrawingInNewTab = async (drawing: Drawing) => {
    try {
      if (!drawing?.file_url) return;

      // Prefer Blob URLs for reliability (data: URLs can be too long / blocked in some browsers)
      if (drawing.file_url.startsWith('data:')) {
        const blob = dataUrlToBlob(drawing.file_url);
        if (!blob) {
          window.open(drawing.file_url, '_blank', 'noopener,noreferrer');
          return;
        }
        const blobUrl = URL.createObjectURL(blob);
        window.open(blobUrl, '_blank', 'noopener,noreferrer');
        setTimeout(() => URL.revokeObjectURL(blobUrl), 60_000);
        return;
      }

      window.open(drawing.file_url, '_blank', 'noopener,noreferrer');
    } catch (error) {
      console.error('Error opening drawing:', error);
      alert('Failed to open drawing');
    }
  };

  const downloadDrawing = async (drawing: Drawing) => {
    try {
      if (!drawing?.file_url) return;

      if (drawing.file_url.startsWith('data:')) {
        const blob = dataUrlToBlob(drawing.file_url);
        if (!blob) {
          const link = document.createElement('a');
          link.href = drawing.file_url;
          link.download = drawing.file_name || 'drawing';
          document.body.appendChild(link);
          link.click();
          link.remove();
          return;
        }

        const blobUrl = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = blobUrl;
        link.download = drawing.file_name || 'drawing';
        document.body.appendChild(link);
        link.click();
        link.remove();
        setTimeout(() => URL.revokeObjectURL(blobUrl), 60_000);
        return;
      }

      const link = document.createElement('a');
      link.href = drawing.file_url;
      link.download = drawing.file_name || 'drawing';
      document.body.appendChild(link);
      link.click();
      link.remove();
    } catch (error) {
      console.error('Error downloading drawing:', error);
      alert('Failed to download drawing');
    }
  };

  useEffect(() => {
    fetchDrawings();
    fetchDocuments();
  }, [itemId]);

  const fetchDrawings = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('accessToken');
      const response = await fetch(`/api/v1/inventory/items/${itemId}/drawings`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (response.ok) {
        const data = await response.json();
        setDrawings(data);
      }
    } catch (error) {
      console.error('Error fetching drawings:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchDocuments = async () => {
    try {
      setDocumentsLoading(true);
      const token = localStorage.getItem('accessToken');

      // We store drawings as Documents of type DRAWING (and sometimes TECHNICAL_DRAWING)
      const [drawingsRes, technicalRes] = await Promise.all([
        fetch('/api/v1/documents?document_type=DRAWING', {
          headers: { Authorization: `Bearer ${token}` },
        }),
        fetch('/api/v1/documents?document_type=TECHNICAL_DRAWING', {
          headers: { Authorization: `Bearer ${token}` },
        }),
      ]);

      const results: DocumentOption[] = [];
      if (drawingsRes.ok) {
        const data = await drawingsRes.json();
        if (Array.isArray(data)) results.push(...data);
      }
      if (technicalRes.ok) {
        const data = await technicalRes.json();
        if (Array.isArray(data)) results.push(...data);
      }

      // Deduplicate by id, and keep newest first
      const byId = new Map<string, DocumentOption>();
      for (const doc of results) {
        if (doc?.id && !byId.has(doc.id)) byId.set(doc.id, doc);
      }

      const merged = Array.from(byId.values()).sort((a, b) => {
        const at = a.created_at ? new Date(a.created_at).getTime() : 0;
        const bt = b.created_at ? new Date(b.created_at).getTime() : 0;
        return bt - at;
      });

      setDocuments(merged);
    } catch (error) {
      console.error('Error fetching documents:', error);
      setDocuments([]);
    } finally {
      setDocumentsLoading(false);
    }
  };

  const handleLinkExistingDocument = async () => {
    if (!selectedDocumentId) {
      alert('Please select a drawing document');
      return;
    }

    if (!revisionNotes.trim() && drawings.length > 0) {
      alert('Please add revision notes for new versions');
      return;
    }

    setLinking(true);
    try {
      const token = localStorage.getItem('accessToken');

      const response = await fetch(`/api/v1/inventory/items/${itemId}/drawings`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          documentId: selectedDocumentId,
          revisionNotes: revisionNotes.trim() || (drawings.length > 0 ? 'Linked from Documents' : 'Initial version'),
        }),
      });

      if (response.ok) {
        alert('Drawing linked successfully!');
        setSelectedDocumentId('');
        setRevisionNotes('');
        await fetchDrawings();
      } else {
        const error = await response.json().catch(() => ({}));
        alert(`Failed to link: ${error.message || 'Unknown error'}`);
      }
    } catch (error) {
      console.error('Error linking document:', error);
      alert('Failed to link drawing');
    } finally {
      setLinking(false);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      // Validate file type
      const validTypes = ['image/png', 'image/jpeg', 'image/jpg', 'application/pdf'];
      if (!validTypes.includes(file.type)) {
        alert('Please upload PNG, JPG, or PDF files only');
        return;
      }

      // Validate file size (max 10MB)
      if (file.size > 10 * 1024 * 1024) {
        alert('File size must be less than 10MB');
        return;
      }

      setSelectedFile(file);

      // Create preview for images
      if (file.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onloadend = () => {
          setPreviewUrl(reader.result as string);
        };
        reader.readAsDataURL(file);
      } else {
        setPreviewUrl(null);
      }
    }
  };

  const handleUpload = async () => {
    if (!selectedFile) {
      alert('Please select a file');
      return;
    }

    if (!revisionNotes.trim() && drawings.length > 0) {
      alert('Please add revision notes for new versions');
      return;
    }

    setUploading(true);
    try {
      // Convert file to base64
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        
        const token = localStorage.getItem('accessToken');
        const response = await fetch(`/api/v1/inventory/items/${itemId}/drawings`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            fileName: selectedFile.name,
            fileUrl: base64,
            fileType: selectedFile.type,
            fileSize: selectedFile.size,
            revisionNotes: revisionNotes.trim() || 'Initial version',
          }),
        });

        if (response.ok) {
          alert('Drawing uploaded successfully!');
          setSelectedFile(null);
          setRevisionNotes('');
          setPreviewUrl(null);
          fetchDrawings();
        } else {
          const error = await response.json();
          alert(`Failed to upload: ${error.message || 'Unknown error'}`);
        }
      };
      reader.readAsDataURL(selectedFile);
    } catch (error) {
      console.error('Error uploading drawing:', error);
      alert('Failed to upload drawing');
    } finally {
      setUploading(false);
    }
  };

  const handleSetActive = async (drawing: Drawing) => {
    if (drawing.is_active) return;

    try {
      setUpdatingActiveId(drawing.id);
      const token = localStorage.getItem('accessToken');

      const response = await fetch(`/api/v1/inventory/items/${itemId}/drawings/${drawing.id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          revisionNotes: drawing.revision_notes,
          isActive: true,
        }),
      });

      if (response.ok) {
        await fetchDrawings();
      } else {
        const error = await response.json().catch(() => ({}));
        alert(`Failed to set active drawing: ${error.message || 'Unknown error'}`);
      }
    } catch (error) {
      console.error('Error setting active drawing:', error);
      alert('Failed to set active drawing');
    } finally {
      setUpdatingActiveId(null);
    }
  };

  const formatFileSize = (bytes: number) => {
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(2) + ' KB';
    return (bytes / (1024 * 1024)).toFixed(2) + ' MB';
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-IN', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const canClose = !mandatory || drawings.length > 0;

  const activeDrawing = drawings.find(d => d.is_active) || null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-lg max-w-4xl w-full max-h-[90vh] overflow-y-auto">
        {/* Header */}
        <div className="p-6 border-b border-gray-200 sticky top-0 bg-white">
          <div className="flex justify-between items-start">
            <div>
              <h2 className="text-2xl font-bold text-gray-900">Drawing Management</h2>
              <p className="text-gray-600 mt-1">
                {itemCode} - {itemName}
              </p>
              {mandatory && drawings.length === 0 && (
                <div className="mt-2 bg-red-50 border border-red-200 rounded px-3 py-2 text-sm text-red-800">
                  ⚠️ Drawing upload is mandatory for this item before proceeding
                </div>
              )}
            </div>
            {canClose && (
              <button
                onClick={onClose}
                className="text-gray-500 hover:text-gray-700 text-2xl"
              >
                ×
              </button>
            )}
          </div>
        </div>

        <div className="p-6 space-y-6">
          {/* Upload Section */}
          <div className="bg-amber-50 border border-amber-200 rounded-lg p-4">
            <h3 className="font-semibold text-amber-900 mb-3">
              {drawings.length > 0 ? `Upload New Version (v${drawings[0].version + 1})` : 'Upload First Drawing (v1)'}
            </h3>

            <div className="space-y-4">
              {/* Link existing Document */}
              <div className="bg-white border border-amber-200 rounded-lg p-3">
                <div className="text-sm font-medium text-amber-900 mb-2">Use Existing Drawing from Documents</div>
                <div className="flex gap-2 items-center">
                  <select
                    value={selectedDocumentId}
                    onChange={(e) => setSelectedDocumentId(e.target.value)}
                    className="flex-1 border border-gray-300 rounded-lg px-3 py-2 text-sm"
                    disabled={documentsLoading || linking}
                  >
                    <option value="">{documentsLoading ? 'Loading drawings…' : 'Select a drawing document'}</option>
                    {documents.map((doc) => {
                      const label = (doc.title || doc.file_name || doc.id || '').toString();
                      return (
                        <option key={doc.id} value={doc.id}>
                          {label}
                        </option>
                      );
                    })}
                  </select>

                  <button
                    type="button"
                    onClick={handleLinkExistingDocument}
                    disabled={!selectedDocumentId || linking}
                    className="bg-amber-600 text-white px-4 py-2 rounded-lg hover:bg-amber-700 disabled:bg-gray-400 text-sm"
                  >
                    {linking ? 'Linking…' : 'Link'}
                  </button>
                </div>
                <div className="text-xs text-gray-600 mt-2">
                  This will create a new drawing version for this item using the selected Document.
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Select File (PNG, JPG, PDF - Max 10MB) *
                </label>
                <input
                  type="file"
                  accept="image/png,image/jpeg,image/jpg,application/pdf"
                  onChange={handleFileSelect}
                  className="w-full border border-gray-300 rounded-lg px-4 py-2"
                />
              </div>

              {previewUrl && (
                <div className="border border-gray-300 rounded-lg p-2">
                  <img src={previewUrl} alt="Preview" className="max-h-48 mx-auto" />
                </div>
              )}

              {selectedFile && (
                <div className="text-sm text-gray-600">
                  Selected: {selectedFile.name} ({formatFileSize(selectedFile.size)})
                </div>
              )}

              {drawings.length > 0 && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Revision Notes *
                  </label>
                  <textarea
                    value={revisionNotes}
                    onChange={(e) => setRevisionNotes(e.target.value)}
                    rows={3}
                    className="w-full border border-gray-300 rounded-lg px-4 py-2"
                    placeholder="What changed in this version..."
                  />
                </div>
              )}

              <button
                onClick={handleUpload}
                disabled={uploading || !selectedFile}
                className="w-full bg-amber-600 text-white px-6 py-3 rounded-lg hover:bg-amber-700 disabled:opacity-50 disabled:cursor-not-allowed font-semibold"
              >
                {uploading ? 'Uploading...' : 'Upload Drawing'}
              </button>
            </div>
          </div>

          {/* Existing Drawings */}
          <div>
            <h3 className="font-semibold text-gray-900 mb-3">
              Drawing History ({drawings.length} versions)
            </h3>

            {activeDrawing && (
              <div className="mb-3 text-sm bg-green-50 border border-green-200 rounded px-3 py-2 text-green-900">
                Active drawing: <span className="font-semibold">v{activeDrawing.version}</span> ({activeDrawing.file_name})
              </div>
            )}

            {loading ? (
              <div className="text-center py-8 text-gray-500">Loading drawings...</div>
            ) : drawings.length === 0 ? (
              <div className="text-center py-8 border-2 border-dashed border-gray-300 rounded-lg">
                <div className="text-4xl mb-2">📄</div>
                <p className="text-gray-600">No drawings uploaded yet</p>
                <p className="text-sm text-gray-500 mt-1">Upload the first version above</p>
              </div>
            ) : (
              <div className="space-y-3">
                {drawings.map((drawing) => (
                  <div
                    key={drawing.id}
                    className="border border-gray-300 rounded-lg p-4 hover:shadow-md transition-shadow"
                  >
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <div className="flex items-center gap-3">
                          <span className="bg-blue-100 text-blue-800 px-2 py-1 rounded text-sm font-semibold">
                            v{drawing.version}
                          </span>
                          <span className="font-medium text-gray-900">{drawing.file_name}</span>
                          {drawing.version === drawings[0].version && (
                            <span className="bg-green-100 text-green-800 px-2 py-1 rounded text-xs font-semibold">
                              LATEST
                            </span>
                          )}
                          {drawing.is_active && (
                            <span className="bg-amber-100 text-amber-900 px-2 py-1 rounded text-xs font-semibold">
                              ACTIVE
                            </span>
                          )}
                        </div>

                        <div className="mt-2 text-sm text-gray-600 grid grid-cols-2 gap-x-4">
                          <div>Type: {drawing.file_type}</div>
                          <div>Size: {formatFileSize(drawing.file_size)}</div>
                          <div className="col-span-2 mt-1">Uploaded: {formatDate(drawing.created_at)}</div>
                        </div>

                        {drawing.revision_notes && (
                          <div className="mt-2 text-sm bg-gray-50 rounded px-3 py-2">
                            <span className="font-medium">Notes:</span> {drawing.revision_notes}
                          </div>
                        )}
                      </div>

                      <div className="flex gap-2">
                        <button
                          type="button"
                          onClick={() => openDrawingInNewTab(drawing)}
                          className="bg-blue-100 text-blue-700 px-4 py-2 rounded hover:bg-blue-200 text-sm font-medium"
                        >
                          View
                        </button>
                        <button
                          type="button"
                          onClick={() => downloadDrawing(drawing)}
                          className="bg-green-100 text-green-700 px-4 py-2 rounded hover:bg-green-200 text-sm font-medium"
                        >
                          Download
                        </button>
                        {!drawing.is_active && (
                          <button
                            type="button"
                            onClick={() => handleSetActive(drawing)}
                            disabled={updatingActiveId === drawing.id}
                            className="bg-amber-100 text-amber-900 px-4 py-2 rounded hover:bg-amber-200 text-sm font-medium disabled:opacity-50 disabled:cursor-not-allowed"
                          >
                            {updatingActiveId === drawing.id ? 'Applying...' : 'Set Active'}
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Footer */}
        <div className="p-6 border-t border-gray-200 flex justify-end gap-4">
          {!canClose && (
            <p className="text-red-600 text-sm flex-1">
              Please upload at least one drawing before closing
            </p>
          )}
          {canClose && (
            <button
              onClick={onClose}
              className="px-6 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700"
            >
              Close
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';

export interface DuplicateMatch {
  id: string;
  matchScore: number;
  matchedFields: string[];
  data: any;
}

export interface DuplicateWarningProps {
  isOpen: boolean;
  exactMatches: DuplicateMatch[];
  fuzzyMatches: DuplicateMatch[];
  entityType: string;
  onProceed: () => void;
  onCancel: () => void;
  formatRecord?: (data: any) => React.ReactNode;
}

export default function DuplicateWarning({
  isOpen,
  exactMatches,
  fuzzyMatches,
  entityType,
  onProceed,
  onCancel,
  formatRecord,
}: DuplicateWarningProps) {
  const [acknowledged, setAcknowledged] = useState(false);

  if (!isOpen) return null;

  const hasExactMatches = exactMatches.length > 0;
  const hasFuzzyMatches = fuzzyMatches.length > 0;

  return (
    <div className="fixed inset-0 bg-gray-600 bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white rounded-lg p-6 max-w-3xl w-full max-h-[80vh] overflow-y-auto">
        <div className="flex items-start mb-4">
          <div className="flex-shrink-0">
            <svg
              className="h-8 w-8 text-amber-500"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"
              />
            </svg>
          </div>
          <div className="ml-4 flex-1">
            <h3 className="text-lg font-semibold text-gray-900">
              {hasExactMatches ? 'Duplicate Detected!' : 'Similar Record Found'}
            </h3>
            <p className="text-sm text-gray-600 mt-1">
              {hasExactMatches
                ? `An exact duplicate ${entityType} already exists in the system.`
                : `A similar ${entityType} already exists in the system.`}
            </p>
          </div>
          <button
            onClick={onCancel}
            className="text-gray-400 hover:text-gray-600"
          >
            ✕
          </button>
        </div>

        {/* Exact Matches */}
        {hasExactMatches && (
          <div className="mb-4">
            <h4 className="text-sm font-semibold text-red-700 mb-2">
              Exact Matches ({exactMatches.length})
            </h4>
            {exactMatches.map((match, index) => (
              <div
                key={match.id}
                className="bg-red-50 border border-red-200 rounded-lg p-3 mb-2"
              >
                <div className="flex justify-between items-start mb-2">
                  <div className="text-xs text-red-600 font-medium">
                    Matched Fields: {match.matchedFields.join(', ')}
                  </div>
                  <div className="text-xs bg-red-600 text-white px-2 py-1 rounded">
                    {match.matchScore}% Match
                  </div>
                </div>
                {formatRecord ? (
                  formatRecord(match.data)
                ) : (
                  <pre className="text-xs text-gray-700 overflow-auto">
                    {JSON.stringify(match.data, null, 2)}
                  </pre>
                )}
              </div>
            ))}
          </div>
        )}

        {/* Fuzzy Matches */}
        {hasFuzzyMatches && !hasExactMatches && (
          <div className="mb-4">
            <h4 className="text-sm font-semibold text-amber-700 mb-2">
              Similar Records ({fuzzyMatches.length})
            </h4>
            {fuzzyMatches.map((match, index) => (
              <div
                key={match.id}
                className="bg-amber-50 border border-amber-200 rounded-lg p-3 mb-2"
              >
                <div className="flex justify-between items-start mb-2">
                  <div className="text-xs text-amber-600 font-medium">
                    Similar Fields: {match.matchedFields.join(', ')}
                  </div>
                  <div className="text-xs bg-amber-600 text-white px-2 py-1 rounded">
                    {match.matchScore}% Match
                  </div>
                </div>
                {formatRecord ? (
                  formatRecord(match.data)
                ) : (
                  <pre className="text-xs text-gray-700 overflow-auto">
                    {JSON.stringify(match.data, null, 2)}
                  </pre>
                )}
              </div>
            ))}
          </div>
        )}

        {/* Warning Message */}
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4 mb-4">
          <p className="text-sm text-yellow-800">
            <strong>⚠️ Warning:</strong> Creating a duplicate {entityType} may lead to:
          </p>
          <ul className="list-disc list-inside text-xs text-yellow-700 mt-2 space-y-1">
            <li>Data inconsistency and reporting errors</li>
            <li>Confusion in operations and order processing</li>
            <li>Duplicate payments or invoices</li>
            <li>Inventory tracking issues</li>
          </ul>
        </div>

        {/* Acknowledgment Checkbox */}
        <div className="mb-4">
          <label className="flex items-start gap-2 cursor-pointer">
            <input
              type="checkbox"
              checked={acknowledged}
              onChange={(e) => setAcknowledged(e.target.checked)}
              className="mt-1 w-4 h-4"
            />
            <span className="text-sm text-gray-700">
              I acknowledge that this is a duplicate/similar entry and I want to proceed
              with creating it anyway. I understand the potential risks.
            </span>
          </label>
        </div>

        {/* Action Buttons */}
        <div className="flex justify-end gap-3">
          <button
            onClick={onCancel}
            className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50"
          >
            Cancel
          </button>
          <button
            onClick={onProceed}
            disabled={!acknowledged}
            className={`px-4 py-2 rounded-lg ${
              acknowledged
                ? 'bg-amber-600 text-white hover:bg-amber-700'
                : 'bg-gray-300 text-gray-500 cursor-not-allowed'
            }`}
          >
            Proceed Anyway
          </button>
        </div>
      </div>
    </div>
  );
}

// Hook for duplicate detection
export function useDuplicateDetection() {
  const [duplicateState, setDuplicateState] = useState<{
    isOpen: boolean;
    exactMatches: DuplicateMatch[];
    fuzzyMatches: DuplicateMatch[];
    onProceedCallback?: () => void;
  }>({
    isOpen: false,
    exactMatches: [],
    fuzzyMatches: [],
  });

  const checkDuplicates = async (
    apiCall: () => Promise<{ hasDuplicates: boolean; exactMatches: DuplicateMatch[]; fuzzyMatches: DuplicateMatch[] }>,
    onProceed: () => void,
  ) => {
    const result = await apiCall();

    if (result.hasDuplicates) {
      setDuplicateState({
        isOpen: true,
        exactMatches: result.exactMatches,
        fuzzyMatches: result.fuzzyMatches,
        onProceedCallback: onProceed,
      });
      return false; // Don't proceed yet
    } else {
      onProceed(); // No duplicates, proceed
      return true;
    }
  };

  const handleProceed = () => {
    setDuplicateState({
      isOpen: false,
      exactMatches: [],
      fuzzyMatches: [],
    });
    duplicateState.onProceedCallback?.();
  };

  const handleCancel = () => {
    setDuplicateState({
      isOpen: false,
      exactMatches: [],
      fuzzyMatches: [],
    });
  };

  return {
    duplicateState,
    checkDuplicates,
    handleProceed,
    handleCancel,
  };
}

'use client';

import { useState } from 'react';
import * as XLSX from 'xlsx';

interface ExcelUploadProps {
  onDataParsed: (data: any[]) => void;
  onClose: () => void;
  templateColumns: string[];
}

export default function ExcelUpload({ onDataParsed, onClose, templateColumns }: ExcelUploadProps) {
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState<any[]>([]);
  const [error, setError] = useState<string>('');

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (!selectedFile) return;

    // Check file type
    const validTypes = [
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      'application/vnd.ms-excel',
      'text/csv'
    ];
    
    if (!validTypes.includes(selectedFile.type) && !selectedFile.name.match(/\.(xlsx|xls|csv)$/)) {
      setError('Please upload a valid Excel or CSV file');
      return;
    }

    setFile(selectedFile);
    setError('');
    parseFile(selectedFile);
  };

  const parseFile = (file: File) => {
    const reader = new FileReader();
    
    reader.onload = (e) => {
      try {
        const data = e.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const jsonData = XLSX.utils.sheet_to_json(worksheet);
        
        if (jsonData.length === 0) {
          setError('The file is empty or has no valid data');
          return;
        }

        setPreview(jsonData.slice(0, 5)); // Show first 5 rows
        setError('');
      } catch (err) {
        setError('Failed to parse file. Please check the format.');
        console.error('Parse error:', err);
      }
    };

    reader.readAsBinaryString(file);
  };

  const handleUpload = () => {
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = e.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const jsonData = XLSX.utils.sheet_to_json(worksheet);
        
        onDataParsed(jsonData);
      } catch (err) {
        setError('Failed to process file');
        console.error('Upload error:', err);
      }
    };

    reader.readAsBinaryString(file);
  };

  const downloadTemplate = () => {
    // Create sample data with column headers
    const template = [templateColumns.reduce((acc, col) => {
      acc[col] = '';
      return acc;
    }, {} as any)];

    const worksheet = XLSX.utils.json_to_sheet(template);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Items Template');
    XLSX.writeFile(workbook, 'items_template.xlsx');
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-lg max-w-4xl w-full max-h-[90vh] overflow-y-auto">
        <div className="p-6 border-b border-gray-200">
          <h2 className="text-2xl font-bold text-gray-900">📊 Upload Items from Excel</h2>
          <p className="text-sm text-gray-600 mt-1">Upload an Excel file with multiple items</p>
        </div>

        <div className="p-6 space-y-6">
          {/* Download Template Button */}
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
            <div className="flex items-start gap-3">
              <span className="text-2xl">💡</span>
              <div className="flex-1">
                <h3 className="font-semibold text-blue-900 mb-1">Need a template?</h3>
                <p className="text-sm text-blue-700 mb-3">
                  Download the Excel template with the correct column format
                </p>
                <button
                  onClick={downloadTemplate}
                  className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded text-sm font-medium"
                >
                  📥 Download Template
                </button>
              </div>
            </div>
          </div>

          {/* File Upload */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Select Excel File
            </label>
            <input
              type="file"
              accept=".xlsx,.xls,.csv"
              onChange={handleFileChange}
              className="block w-full text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded file:border-0 file:text-sm file:font-semibold file:bg-amber-50 file:text-amber-700 hover:file:bg-amber-100"
            />
            {error && (
              <p className="text-red-600 text-sm mt-2">{error}</p>
            )}
          </div>

          {/* Preview */}
          {preview.length > 0 && (
            <div>
              <h3 className="font-semibold text-gray-900 mb-3">
                Preview (First {preview.length} rows)
              </h3>
              <div className="overflow-x-auto border rounded-lg">
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-gray-50">
                    <tr>
                      {Object.keys(preview[0]).map((key) => (
                        <th
                          key={key}
                          className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider"
                        >
                          {key}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {preview.map((row, idx) => (
                      <tr key={idx}>
                        {Object.values(row).map((val: any, cellIdx) => (
                          <td key={cellIdx} className="px-4 py-2 text-sm text-gray-900 whitespace-nowrap">
                            {String(val)}
                          </td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              <p className="text-sm text-gray-600 mt-2">
                Total rows in file: {preview.length > 0 ? 'Loading...' : '0'}
              </p>
            </div>
          )}

          {/* Expected Format */}
          <div className="bg-gray-50 border border-gray-200 rounded-lg p-4">
            <h3 className="font-semibold text-gray-900 mb-2">Expected Columns:</h3>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-2 text-sm">
              {templateColumns.map((col) => (
                <div key={col} className="flex items-center gap-2">
                  <span className="text-green-600">✓</span>
                  <code className="text-gray-700">{col}</code>
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="p-6 border-t border-gray-200 flex justify-end gap-4">
          <button
            onClick={onClose}
            className="px-6 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
          >
            Cancel
          </button>
          <button
            onClick={handleUpload}
            disabled={!file || preview.length === 0}
            className="px-6 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:bg-gray-300 disabled:cursor-not-allowed"
          >
            Upload & Import Items
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';

interface FileUploadProps {
  onUploadComplete: (fileUrl: string, fileName: string, fileSize: number) => void;
  acceptedTypes?: string;
  maxSize?: number;
  folder?: string;
}

export default function FileUpload({
  onUploadComplete,
  acceptedTypes = '.pdf,.doc,.docx,.dwg,.dxf,.png,.jpg,.jpeg',
  maxSize = 50,
}: FileUploadProps) {
  const [uploading, setUploading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const fileSizeMB = file.size / (1024 * 1024);
    if (fileSizeMB > maxSize) {
      setError(`File size exceeds ${maxSize}MB limit`);
      return;
    }

    setError(null);
    setUploading(true);
    setProgress(0);

    try {
      const progressInterval = setInterval(() => {
        setProgress((prev) => (prev >= 90 ? 90 : prev + 10));
      }, 200);

      const reader = new FileReader();
      reader.onload = (event) => {
        clearInterval(progressInterval);
        setProgress(100);
        onUploadComplete(event.target?.result as string, file.name, file.size);
        setTimeout(() => {
          setUploading(false);
          setProgress(0);
        }, 1000);
      };
      reader.readAsDataURL(file);
    } catch (err: any) {
      setError(err.message || 'Upload failed');
      setUploading(false);
      setProgress(0);
    }
  };

  return (
    <div className="space-y-3">
      <label
        htmlFor="file-upload"
        className={`flex-1 px-4 py-3 border-2 border-dashed rounded-lg cursor-pointer transition-colors text-center block ${
          uploading ? 'bg-gray-50 cursor-not-allowed' : 'hover:bg-blue-50 hover:border-blue-400'
        } ${error ? 'border-red-300 bg-red-50' : 'border-gray-300'}`}
      >
        <input
          id="file-upload"
          type="file"
          accept={acceptedTypes}
          onChange={handleFileChange}
          disabled={uploading}
          className="hidden"
        />
        <div className="flex items-center justify-center gap-2">
          {uploading ? (
            <>
              <svg className="animate-spin h-5 w-5 text-blue-600" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
              </svg>
              <span className="text-sm text-gray-600">Uploading... {progress}%</span>
            </>
          ) : (
            <>
              <svg className="w-5 h-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
              </svg>
              <span className="text-sm text-gray-600">Click to upload file</span>
            </>
          )}
        </div>
        <p className="text-xs text-gray-500 mt-1">Max {maxSize}MB</p>
      </label>

      {error && (
        <div className="p-3 bg-red-50 border border-red-200 rounded-lg">
          <p className="text-sm text-red-600">{error}</p>
        </div>
      )}

      {uploading && progress > 0 && (
        <div className="w-full bg-gray-200 rounded-full h-2">
          <div className="bg-blue-600 h-2 rounded-full transition-all" style={{ width: `${progress}%` }} />
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect, useRef } from 'react';

interface Item {
  id: string;
  code: string;
  name: string;
  description?: string;
  uom?: string;
  category?: string;
}

interface ItemSearchProps {
  value: string;
  onSelect: (item: Item) => void;
  initialItem?: Pick<Item, 'id' | 'code' | 'name'> | null;
  placeholder?: string;
  className?: string;
  disabled?: boolean;
}

export default function ItemSearch({ value, onSelect, initialItem, placeholder, className, disabled }: ItemSearchProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [items, setItems] = useState<Item[]>([]);
  const [showDropdown, setShowDropdown] = useState(false);
  const [loading, setLoading] = useState(false);
  const [selectedItem, setSelectedItem] = useState<Item | null>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);

  // Fetch initial item if value prop is provided
  useEffect(() => {
    const fetchInitialItem = async () => {
      if (!value || searchQuery) return; // Skip if no value or already has searchQuery

      if (initialItem && initialItem.id === value && initialItem.code && initialItem.name) {
        setSearchQuery(`${initialItem.code} - ${initialItem.name}`);
        setSelectedItem(initialItem as Item);
        return;
      }
      
      try {
        const token = localStorage.getItem('accessToken');
        if (!token) return;

        const response = await fetch(`/api/v1/inventory/items/${value}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        
        if (response.ok) {
          const item = await response.json();
          setSearchQuery(`${item.code} - ${item.name}`);
          setSelectedItem(item);
        }
      } catch (error) {
        console.error('Error fetching initial item:', error);
      }
    };
    
    fetchInitialItem();
  }, [value, searchQuery, initialItem]);

  // Close dropdown when clicking outside
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setShowDropdown(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Search items as user types
  useEffect(() => {
    const searchItems = async () => {
      if (searchQuery.trim().length < 2) {
        setItems([]);
        return;
      }

      setLoading(true);
      try {
        const token = localStorage.getItem('accessToken');
        if (!token) {
          setItems([]);
          return;
        }
        const response = await fetch(`/api/v1/inventory/items/search?q=${encodeURIComponent(searchQuery)}`, {
          headers: { Authorization: `Bearer ${token}` },
        });

        if (response.ok) {
          const data = await response.json();
          setItems(data);
          setShowDropdown(true);
        }
      } catch (error) {
        console.error('Error searching items:', error);
      } finally {
        setLoading(false);
      }
    };

    const debounce = setTimeout(searchItems, 300);
    return () => clearTimeout(debounce);
  }, [searchQuery]);

  const handleSelect = (item: Item) => {
    setSelectedItem(item);
    setSearchQuery(`${item.code} - ${item.name}`);
    setShowDropdown(false);
    onSelect(item);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchQuery(e.target.value);
    setSelectedItem(null);
    if (e.target.value.trim().length >= 2) {
      setShowDropdown(true);
    }
  };

  return (
    <div ref={wrapperRef} className="relative">
      <input
        type="text"
        value={searchQuery}
        onChange={handleInputChange}
        onFocus={() => searchQuery.trim().length >= 2 && setShowDropdown(true)}
        className={className || "w-full border border-gray-300 rounded-lg px-4 py-2 focus:ring-2 focus:ring-amber-500 focus:border-amber-500"}
        placeholder={placeholder || "Type to search items..."}
        disabled={disabled}
      />

      {showDropdown && (
        <div className="absolute z-50 w-full mt-1 bg-white border border-gray-300 rounded-lg shadow-lg max-h-64 overflow-y-auto">
          {loading ? (
            <div className="p-3 text-center text-gray-500">Searching...</div>
          ) : items.length === 0 ? (
            <div className="p-3 text-center text-gray-500">
              {searchQuery.length < 2 ? 'Type at least 2 characters' : 'No items found'}
            </div>
          ) : (
            items.map((item) => (
              <div
                key={item.id}
                onClick={() => handleSelect(item)}
                className="p-3 hover:bg-amber-50 cursor-pointer border-b last:border-b-0"
              >
                <div className="font-medium text-gray-900">{item.code} - {item.name}</div>
                {item.description && (
                  <div className="text-sm text-gray-600">{item.description}</div>
                )}
                <div className="text-xs text-gray-500 mt-1">
                  {item.category && <span className="mr-3">Category: {item.category}</span>}
                  {item.uom && <span>UOM: {item.uom}</span>}
                </div>
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
}

